(function () {
  "use strict";
  var DATA = {"version":"2.1.0","builtAt":"2026-09-03T06:24:44.578Z","curriculum":{"$schema":"AI Knowledge OS · Curriculum v2.0 (Category → Chapter → Lesson → Concept)","note":"四层结构：Category 分类 → Chapter 章 → Lesson 课（真正学习单元）→ Concept（知识图谱最小节点）。134 个 Concept 被组织进约 52 个 Lesson；一个 Lesson 可由多个 Concept 组合而成。此时 Lesson 是学习单位，Concept 是图谱节点。","lessonCount":52,"flagShip":["l00-ai-world","l-attention","l-embedding","l-transformer","l-rag","l-agent"],"categories":[{"category":"c01-ai-world","title":"AI 世界地图","overview":{"headline":"让机器从数据里找到规律","questions":["AI、机器学习、深度学习到底是什么关系？","AI 现在能干什么、不能干什么？","为什么最近几年 AI 突然爆发？","我从哪里开始学起？"],"mentalModel":["数据 Data","模型 Model","预测 Prediction","误差 Loss","梯度 Gradient","参数更新 Update"]},"chapters":[{"title":"第一章 · AI 全景","lessons":[{"id":"l00-ai-world","ready":true,"title":"一张图看懂整个 AI 世界"},{"id":"l01-ai-vs-ml-dl","ready":false,"title":"AI / Machine Learning / Deep Learning 到底什么关系"}]}]},{"category":"c02-essentials","title":"AI 必备基础","overview":{"headline":"看懂 AI 需要的最小数学与概念地基","questions":["文字、图片怎么变成电脑能算的数字？","向量是什么？为什么意思相近的词距离更近？","什么叫梯度，为什么模型靠它学习？","概率和不确定性在 AI 里有什么用？"],"mentalModel":["实体","→ 向量 Vector","→ 向量空间","→ 相似度","→ 学习"]},"chapters":[{"title":"第一章 · 向量与语义","lessons":[{"id":"l-embedding","ready":true,"title":"Embedding｜怎么把词变成电脑能懂的数字"},{"id":"l02-vector-space","ready":false,"title":"向量空间与相似度"}]},{"title":"第二章 · 数学地基","lessons":[{"id":"l03-matrix-gradient","ready":false,"title":"矩阵、函数与梯度入门"},{"id":"l04-probability","ready":false,"title":"概率：AI 在预测什么"}]}]},{"category":"c03-ml","title":"机器学习","overview":{"headline":"让机器从数据里找到规律","questions":["机器到底怎么『学习』？","模型为什么能预测没见过的东西？","模型怎么知道自己错了？","为什么训练效果好，现实里却可能很差？"],"mentalModel":["数据","→ 模型","→ 预测","→ 误差 Loss","→ 梯度 Gradient","→ 参数更新","↺"]},"chapters":[{"title":"第一章 · 学会学习","lessons":[{"id":"l05-gradient-descent","ready":false,"title":"Gradient Descent｜模型怎么『往下走』学会预测"}]},{"title":"第二章 · 预测与评估","lessons":[{"id":"l06-overfitting","ready":false,"title":"为什么训练好、现实差：过拟合"},{"id":"l07-eval","ready":false,"title":"怎么判断模型到底好不好"}]}]},{"category":"c04-dl","title":"深度学习","overview":{"headline":"多层神经网络如何工作","questions":["神经元、层、网络是什么？","反向传播在传什么？","深度为什么有用？"],"mentalModel":["输入","→ 神经元","→ 层","→ 激活","→ 输出","← 反向传播 ← 误差"]},"chapters":[{"title":"第一章 · 神经网络","lessons":[{"id":"l08-neural-network","ready":false,"title":"Neural Network｜神经元如何组成可学习的网络"}]},{"title":"第二章 · 学习机制","lessons":[{"id":"l09-backprop","ready":false,"title":"反向传播：误差如何传回去改参数"},{"id":"l10-cnn-rnn","ready":false,"title":"CNN 与 RNN：两种经典网络在解决什么"}]}]},{"category":"c05-llm","title":"大语言模型","overview":{"headline":"ChatGPT 这类大模型到底在干嘛","questions":["大模型是怎么『学会』说话的？","Transformer 和 Attention 是什么？为什么它颠覆了一切？","上下文窗口、Token、温度是什么意思？","为什么模型会一本正经地胡说八道？"],"mentalModel":["Token","→ Embedding","→ Transformer","→ 生成下一个词","→ 上下文","→ 输出"]},"chapters":[{"title":"第一章 · 语言如何进入模型","lessons":[{"id":"l11-tokenization","ready":false,"title":"Tokenization｜LLM 是怎么『读』文字的"},{"id":"l12-context-window","ready":false,"title":"上下文窗口：模型一次能『看见』多少"}]},{"title":"第二章 · Transformer","lessons":[{"id":"l-transformer","ready":true,"title":"Transformer｜大模型的地基架构"},{"id":"l-attention","ready":true,"title":"Attention｜模型为什么知道该关注哪个词"}]},{"title":"第三章 · 训练与推理","lessons":[{"id":"l13-llm-training","ready":false,"title":"预训练 / 微调 / RLHF"},{"id":"l14-inference","ready":false,"title":"推理：模型如何生成一个词一个词地说话"},{"id":"l15-prompt","ready":false,"title":"Prompt 工程：怎么和模型说清楚"}]}]},{"category":"c06-llm-app","title":"LLM 应用","overview":{"headline":"把大模型接进真实产品","questions":["怎么调用一个模型做出产品？","函数调用、结构化输出、流式是什么？","怎么评估一个 AI 功能做得好不好？"],"mentalModel":["用户输入","→ API","→ 模型","→ 输出","→ 评估"]},"chapters":[{"title":"第一章 · 接入模型","lessons":[{"id":"l16-llm-api","ready":false,"title":"用 API 把模型接进你的产品"},{"id":"l17-function-calling","ready":false,"title":"Function Calling｜让模型能『动手』"}]}]},{"category":"c07-rag","title":"RAG 检索增强","overview":{"headline":"让模型基于你的资料回答","questions":["模型记不住我的私有资料，怎么办？","RAG 是怎么『找到』相关内容的？","RAG 和微调有什么不同？"],"mentalModel":["文档","→ 切块 Chunk","→ 向量化","→ 检索","→ 上下文","→ 生成"]},"chapters":[{"title":"第一章 · RAG 全流程","lessons":[{"id":"l-rag","ready":true,"title":"RAG｜让模型『查资料』再回答"}]}]},{"category":"c08-agent","title":"Agent 智能体","overview":{"headline":"让 AI 从『回答』到『做事』","questions":["为什么 ChatGPT 不能帮我们操作电脑，Codex 却可以？","Agent 和普通聊天机器人差在哪？","Agent 怎么用工具、怎么规划、怎么循环？"],"mentalModel":["目标","→ 推理","→ 调用工具","→ 观察结果","→ 下一步","↺"]},"chapters":[{"title":"第一章 · 从会说到会做","lessons":[{"id":"l-agent","ready":true,"title":"Agent｜让 AI 自己动手做事"}]}]},{"category":"c09-multimodal","title":"多模态","overview":{"headline":"让 AI 看得见、听得见、能生成","questions":["AI 怎么『看懂』图片和视频？","声音、图像、文字怎么在一个模型里对齐？","扩散模型怎么生成图片？"],"mentalModel":["图像","→ 编码","→ 对齐","→ 生成"]},"chapters":[{"title":"第一章 · 多模态基础","lessons":[{"id":"l18-multimodal","ready":false,"title":"多模态｜AI 如何同时理解文字、图片、声音"},{"id":"l19-diffusion","ready":false,"title":"Diffusion｜图片是怎么被『画』出来的"}]}]},{"category":"c10-ai-eng","title":"AI 工程","overview":{"headline":"把 AI 系统做进生产环境","questions":["一个 AI 应用上线要做什么？","成本、延迟、评估怎么管理？","向量数据库、评估、框架怎么选？"],"mentalModel":["需求","→ 选型","→ 构建","→ 评估","→ 上线","→ 监控"]},"chapters":[{"title":"第一章 · 工程化","lessons":[{"id":"l20-ai-eng","ready":false,"title":"AI 工程：从原型到生产"},{"id":"l21-eval-cost","ready":false,"title":"评估与成本：怎么判断值不值"}]}]},{"category":"c11-ai-coding","title":"AI 编程","overview":{"headline":"用 AI 大幅提升编码效率","questions":["AI 结对编程怎么用？","Agentic Coding 和补全有什么不同？","上下文工程怎么让 AI 更懂你的代码库？"],"mentalModel":["需求","→ 上下文","→ AI 生成","→ 审查","→ 迭代"]},"chapters":[{"title":"第一章 · AI Coding","lessons":[{"id":"l22-ai-coding","ready":false,"title":"AI Coding｜把 AI 变成你的结对程序员"}]}]},{"category":"c12-ai-product","title":"AI 产品与商业","overview":{"headline":"判断一个 AI 产品值不值得做","questions":["一个 AI 产品『技术上能不能做』怎么判断？","AI 产品怎么创造真实价值？","合规、伦理、成本怎么权衡？"],"mentalModel":["用户问题","→ AI 能力","→ 产品形态","→ 价值","→ 商业模式"]},"chapters":[{"title":"第一章 · 产品思维","lessons":[{"id":"l23-ai-product","ready":false,"title":"AI 产品：从想法到落地"}]}]}]},"lessonCount":26,"flagship":["l00-ai-world","l-attention","l-embedding","l-transformer","l-rag","l-agent"],"lessons":{"l-agent":{"id":"l-agent","title":"Agent｜让 AI 自己动手做事","subtitle":"为什么 ChatGPT 只能在对话框里打字，而 Codex 能改你的代码、跑你的测试、提交 PR？Agent 就是把『会说话』的模型，变成『会做事』的执行者。","category":"c08-agent","chapterTitle":"第一章 · 从会说到会做","level":"base","estTime":"25-30 分钟","difficulty":2,"concepts":["agent-intro","agent-loop","tool-use","agent-planning","agent-memory","agent-reflection"],"prereqLessons":["l-rag","l-transformer"],"nextLesson":"l22-ai-coding","sections":[{"type":"opening","question":"你已经能让 ChatGPT 把某个概念讲得头头是道，也能用 RAG 让它查你的资料。但如果你说『去我 GitHub 仓库里把那个测试失败修掉』——为什么 ChatGPT 只能在对话框里给建议，而 Codex 却能真的打开文件、改代码、跑测试、把活干完？","guess":"有人会说「Codex 的模型更聪明」。","next":"这节课揭穿这个误会：Agent 的厉害不在模型智商，而在于给模型装上一个『决策循环 + 一双能动手的工具』。学完你就掌握 Agent = 模型 + 工具 + 循环这条主线。"},{"type":"why","before":"到这一课，我们有了很聪明的模型、也有了让它查资料的 RAG。但你还是有个困扰：让 ChatGPT 整理个表格它倒是能，让它『去我仓库里改掉那个 bug』，它做不到。","problem":"因为聊天模型只有一张嘴：它只能输出文字，看不见你的文件、读不了你的代码、跑不了测试命令。你让它操作仓库，它连仓库在哪都不知道。","need":"Model（思考）+ Tools（手和眼）+ Loop（循环驱动）= Agent。它想一下 → 动一下 → 看一眼结果 → 再想 → 再动。这就是 ChatGPT 和 Codex 的分水岭。","visualNote":"下面这个循环图就是 Agent 的灵魂——你可以亲手点不同工具，看它每一步怎么决策、怎么应对失败。"},{"type":"oneline","text":"Agent（智能体）不是换个更厉害的模型，而是给模型装上一个『决策循环』：它会自己拆目标、自己调用工具（读写文件、执行代码、搜网页）、观察结果、再决定下一步，如此循环直到把事情做完。同样一个模型，套上这个循环，就从『只会回答』变成了『会做事』。"},{"type":"visual","kind":"agent-loop","title":"Agent 循环模拟器：想 → 做 → 看 → 再想（可交互）","hint":"这是一个升级版交互模拟器：你扮演一个修复 bug 的 Codex Agent，在每个步骤从几个工具里选一个。选对了推进，选错了会得到失败反馈，教你『Agent 正是靠不断试错修正才把活干完』。"},{"type":"intuition","blocks":[{"k":"计算器只会算，助理会办事","t":"普通聊天模型像一台高级计算器：你问它答。Agent 像你的助理：你交代一件事，它自己拆步骤、打电话（调工具）、核对结果，办完给你汇报。"},{"k":"不是变聪明，是变『能动』","t":"它没有比 ChatGPT 更聪明——它只是多了一圈『能动手、能看反馈、能再试』的回路。代码还是那个代码，差别在于它学会了执行-反馈-调整。"},{"k":"有钥匙的实习生 vs 没钥匙的实习生","t":"ChatGPT 是没钥匙的实习生：看到门（需要改文件）只会描述『你应该去改那个文件』。Agent 是有钥匙的实习生：自己开门、改文件、跑测试、看结果、再改。"}]},{"type":"how","intro":"一个 Agent 改 bug 的完整工作过程。核心就一句话：目标 → 循环（想 + 做 + 看）→ 交付。这也是本课的骨架。","steps":[{"in":"理解目标","process":"用户下达：『修好注册页面的 bug』。模型先把模糊目标翻译成具体子任务列表。","out":"一个可执行的任务清单"},{"in":"规划 Planning","process":"它推理出步骤：先找到注册页代码 → 读源码定位问题 → 想怎么改 → 改 → 跑测试验证。","out":"Agenda：找代码 → 读 → 改 → 测"},{"in":"调用工具 Tool Use（做）","process":"它请求调用工具：read_file 读代码、edit_file 修改、run_command 跑测试。工具返回结果。","out":"一次具体的『动手』"},{"in":"观察结果 Observe（看）","process":"看到工具返回值：测试报错，或编译失败。它读到反馈，判断是否达到目标。","out":"对『刚才做对没有』的感知"},{"in":"循环 Loop：再想再做","process":"若未达成，回到『想』：根据报错调整方案，再调用工具。如此循环直到测试通过或放弃。","out":"反复的 agent loop（这正是与 ChatGPT 的本质区别）"},{"in":"交付与汇报","process":"任务完成：向用户总结改了什么、测试结果，甚至主动提交 PR、申请权限。","out":"一件完成的事，而不是一段话"}]},{"type":"realworld","items":[{"name":"Codex / Claude Code","note":"Agentic Coding 的典型：能读你的仓库、找 bug、改代码、跑测试、提交 PR。这就是『ChatGPT 做不到、它做得到』的原因——它装了代码工具 + agent loop。"},{"name":"Cursor / Windsurf","note":"IDE 里的 Agent：理解整个项目上下文，跨多个文件完成重构，而不只是一行行补全。"},{"name":"浏览器 Agent（Browser Use / Operator）","note":"自己打开网页、读取、点击、填表，把逛网页办事自动化。"},{"name":"n8n / 工作流编排","note":"让 Agent 串联多个工具/API 完成端到端业务流程（取数 → 处理 → 发通知）。"}]},{"type":"compare","pairs":[{"a":"Chatbot（聊天机器人）","b":"Agent（智能体）","diff":"Chatbot 只输出文字、终结于回答；Agent 拆目标、调工具、看结果、循环迭代，终结于做成事。"},{"a":"单次工具调用","b":"多步 Agent Loop","diff":"会调一个工具的助手只是初级；真正的 Agent 会根据结果决定下一调用，持续多轮直到完成。"},{"a":"RPA（脚本化机器人）","b":"LLM Agent","diff":"RPA 按写死的剧本执行、一变就崩；Agent 动态推理、能处理没见过的异常情况。"},{"a":"Agent","b":"RAG","diff":"Agent 是『多步决策、自己调用工具的循环』；RAG 是『查资料再回答的单步机制』。Agent 需要信息时常用 RAG 当其中一个工具。"}]},{"type":"mistakes","items":["以为 Agent 只是换了个更聪明的模型。本质差别在『循环 + 工具』，不是模型本身。","以为 Agent 能无限可靠地自主执行。它也会反复失败、会犯错，所以需要权限门槛（approval gate）、观测和护栏。","忽视权限与安全。放任 Agent 删文件/发数据/花钱是最危险的坑，生产环境必须加授权与审计。","把会调用工具当成有规划和反思。会调一个函数 ≠ 会拆解复杂目标并自我修正，后者才是 Agent 的进阶。","以为多 Agent 一定更好。多数场景单 Agent 更简单可控，盲目堆 Agent 只会带来编排复杂度和成本。"]},{"type":"deep","title":"深入一点：Agent 的工程骨架","beginner":["Agent Loop 不是魔法：本质就是模型的 for/while 循环——决定下一步 → 调用工具 → 看结果 → 决定再下一步。","工具（Tool）就是一个函数：read_file、write_file、run_command、web_search。模型学会了在合适时机调用它们。","最朴素的 Agent = LLM + 工具集 + 一个决定何时停止的循环。它也可以有记忆和规划，但核心就是这个循环。"],"advanced":["Tool Use / Function Calling：模型输出结构化的『要调用哪个函数、传什么参数』，由系统执行并把结果喂回去，形成闭环。","记忆分两层：短期（当前任务的对话/工具历史）与长期（跨对话的项目知识、偏好，常存向量库）。","Planning 范式：ReAct（Reason + Act 交替）、Plan-and-Execute（先定计划再逐步执行，plan 可被动态修订）、Tree-of-Thought 等。","权限与安全 Permission：Agent 不会无限乱来——危险操作（删文件、花钱、外发数据）要求用户授权（approval gate）。","MCP（Model Context Protocol）：统一工具/数据源接入协议，让一个 Agent 能标准化接入文件系统、数据库、浏览器等多种工具，避免每家写一套私有接口。","Reflection 反思：让 Agent 回顾刚才失败的原因再调整，显著提升长任务可靠性。多 Agent 协作则是多个专业 Agent 分工。",{"code":"# 概念示意：Agent 循环的骨架，就长这样\nwhile not goal_reached:\n    thought = model.think(state, memory)      # 想：我要做哪一步？\n    if thought.should_stop: break              # 判断是否完成\n    tool_result = call_tool(thought.tool_call) # 做：调用工具\n    state.append(tool_result)                  # 看：把结果存进上下文\n    memory.update(state)                       # 记住教训\n# 交付\nreport(model.summarize(state))","lang":"python"}]},{"type":"exercise","prompt":"你（作为 Codex Agent）被要求『修好登录页的 bug』。你读完代码，发现登录按钮点击后有报错。现在到了『做』这一步——猜一猜，Agent 下一步最合理的选择是哪个？","opts":["直接凭记忆改掉一行代码","先运行测试/查看报错日志，定位错误来源，再决定改哪里","马上发邮件问用户想怎么改","直接重新写整个登录页"],"a":1,"explain":"正确动作是先『看』——运行测试或读日志拿到报错信息，有了反馈才知道要改哪。这正是 Agent loop 里『做』与『看』的配合：不观察就动手，等于闭眼改代码。","jump":"sec5-step3","jumpLabel":"观察结果 Observe 这一步"},{"type":"check","title":"结课检测：你真的理解 Agent 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 ChatGPT 不能操作你的仓库，而 Codex 可以？","opts":["因为 Codex 的模型更聪明","因为 Codex 被接上了工具（读写文件/跑命令）+ Agent 循环，ChatGPT 只有对话输出","因为 ChatGPT 没联网","因为模型大小不同"],"a":1,"explain":"决定性差异不是模型智能，而是 Agent 结构：工具让它能动手，循环让它能做→看→修正直到完成。","jump":"sec2","jumpLabel":"一句话理解 Agent 那条"},{"q":"Agent Loop 的核心循环顺序是？","opts":["看 → 做 → 想","想 → 做 → 看 → 再想","只做不看不回头","想 → 想 → 想"],"a":1,"explain":"标准 agent loop：决定下一步（想）→ 调用工具（做）→ 观察结果（看）→ 根据结果再决定下一步（再想），循环到目标达成。","jump":"sec5-step4","jumpLabel":"循环 Loop 这一步"},{"q":"MCP（Model Context Protocol）主要解决什么问题？","opts":["让模型跑得更快","统一 Agent 接入工具/数据源的接口标准，避免各家用私有协议","代替向量数据库","让模型更聪明"],"a":1,"explain":"MCP 是 Agent 与文件、数据库、浏览器等外部工具的标准化接入协议，一次接入、到处复用。","jump":"sec9","jumpLabel":"深入节里 MCP 那条"},{"q":"下面哪个最能代表『Agent 与 Chatbot 的本质区别』？","opts":["Agent 文字更长","Agent 会拆目标、调工具、看反馈并循环，终结于做成事；Chatbot 只回复文字","Agent 不需要模型","Chatbot 也能调用工具"],"a":1,"explain":"Chatbot 止于回答；Agent 以『做成事』为目标，通过循环驱动工具完成多步任务。","jump":"sec7","jumpLabel":"对比区 Chatbot vs Agent"},{"q":"为什么生产环境里 Agent 的危险操作要加『授权门槛（approval gate）』？","opts":["为了拖慢速度","Agent 也会犯错，删文件/花钱/外发数据必须先经用户确认，防止不可逆损失","模型必须要人帮它思考","为了多收费"],"a":1,"explain":"Agent 并非无限可靠，危险动作必须先授权再执行，是落地安全的关键护栏。","jump":"sec8","jumpLabel":"『忽视权限与安全』那条误区"}],"done":"你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。最后一章会带你顺着这条主线进入真正的 AI 编程实践。","nextLesson":"l22-ai-coding"},{"type":"connection","known":["Transformer：模型怎么生成内容","RAG：怎么让模型查资料","工具调用 Function Calling"],"learned":["Agent = 模型 + 工具 + 循环（想→做→看→再想）","它能拆目标、规划、调用工具、观察反馈、反复修正","关键工程点：Tool Use / Memory / Planning / Permission / MCP / Reflection","Chatbot 回答问题，Agent 做成事"],"next":"到这里，你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。想继续深入，建议顺着目标分支走：做产品学 LLM 应用与 RAG，写代码就进入 AI 编程（Agentic Coding / Claude Code）那一章——用 Agent 亲自改代码、跑测试、提交 PR。"}]},"l-attention":{"id":"l-attention","title":"Attention｜模型为什么知道该关注哪个词","subtitle":"当模型读到『它』，怎么知道是猫还是狗？为什么句子再长，模型也能把前后的词对上号？","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["attention","qkv","multihead","attention-long"],"prereqLessons":["l-embedding"],"nextLesson":"l-transformer","sections":[{"type":"opening","question":"请读这句话：「小狗跑向小猫，因为它害怕小狗。」这个『它』指的到底是小猫还是小狗？只盯着『它』一个词，谁也说不清——那 ChatGPT 是怎么判断出来的呢？","guess":"有人会说「代词当然指前面离得最近的动物」。但中文里『它』常跨好几个词、甚至跨好几句指代，光看位置根本猜不准。","next":"这节课要讲的就是模型的『读心术』——Attention 注意力机制。它让模型在处理『它』时，回头看一眼整句话，自己判断该靠哪些词来理解『它』。"},{"type":"why","before":"上节课我们把每个词变成了向量。但词是孤立的：『猫』『追』『狗』『它』，每一个都只是单独的一串数字。","problem":"真正的语言是互相指代的。『猫追狗，它跑得飞快』——这个『它』是谁？只看『它』这个词本身，根本答不上来。更糟的是：在 Attention 出现以前，老式模型（RNN）看长句时，越靠前的词就越『记不清』。","need":"我们需要一个机制：在处理任何一个词时，能直接『回看』整句话里的所有词，按相关程度加权吸收它们的信息。这就是 Attention——『注意力』，它解决了『远距离指代』和『长句遗忘』两大难题。","visualNote":"下面你可以亲手造一句中文，点任何一个词，看它把注意力分给了谁。"},{"type":"oneline","text":"Attention 是这样一种机制：模型在理解某个词时，会『回头看一眼』句子里的每一个词，给它们分别打一个权重分——分数越高的词，模型花越多注意力在它身上。于是『它』到底指猫还是狗，模型有了办法分清。"},{"type":"visual","kind":"attention-heatmap","title":"Attention 热力图：点一个词，看它关注谁","hint":"输入一句话，点任意一个词（比如那棵/那株），热力图会显示这个词对其它词的『关注权重』——颜色越深，越关注。试试改动量词，体验权重如何跟着语义线索移动。"},{"type":"intuition","blocks":[{"k":"老师点名：每读一个词都在点名","t":"读到『它』这个词时，模型其实在问：『谁能告诉我『它』指谁？』——它把问题抛向所有词，然后重点听『猫』『跑』这些最相关的答案。"},{"k":"查字典：不是顺序读，而是跳着看","t":"Attention 最反直觉的一点：它不老老实实从左往右读。读到『它』，它像翻开一本字典快速扫过所有词条，直接锁定『猫』『跑』，记下『我主要靠这几个词来理解自己』。"},{"k":"聚光灯：每个词都举着无数盏灯","t":"句子里每个词都举着一盏聚光灯照向其它词。灯越亮，代表『我理解你时越依赖你』。Attention 就是计算这盏灯亮度的过程。远近都一样亮——这是它比老方法强的地方。"}]},{"type":"how","intro":"Attention 到底怎么『算』注意力？核心就一句话：每个词同时扮演三个角色——Query（我找谁）、Key（我是谁）、Value（我的内容），然后『找相似、按相似加权吸收』。","steps":[{"in":"乘上三个矩阵，得到 Q / K / V","process":"每个词的向量分别乘以三个不同的矩阵，变成三个新向量：Query『我要去匹配谁』、Key『我是谁，请拿我来匹配』、Value『我的有效内容』。","out":"单词 → (Query, Key, Value) 三件套"},{"in":"用 Query 和所有 Key 算相似度","process":"以『它』的 Query 为例，和句子里每个词的 Key 做点积（就是 Embedding 课学过的『方向越像越接近』）。","out":"得到分数列表：它 vs 猫 = 高分，它 vs 跑 = 中等……"},{"in":"Softmax 归一化成权重","process":"把所有分数经过 softmax，变成『加起来等于 100%』的权重。这一步保证分数变成可比较、可加权的概率。","out":"注意力权重：猫 0.6、跑 0.25、飞快 0.15……"},{"in":"用权重 × Value 加权求和","process":"把每个词的 Value 乘上对应权重再全部相加。权重大的词，内容在结果里占的份量就大。","out":"『它』的新向量 = 主要吸收了『猫』的信息 → 模型知道『它≈猫』"},{"in":"每个词同时做，得到上下文向量","process":"句子里每个词都执行同一套操作，得到一批『结合了全局上下文的新向量』。","out":"整句话从一串孤立向量 → 一串互相理解的向量"},{"in":"多个头并行（多头注意力）","process":"为了不只从一种角度看，模型并行做多组 Q/K/V（不同随机初始化的矩阵），相当于多个不同视角同时观察。","out":"一个头看指代关系、另一个头看语法结构、再一个看长度……组合出更丰富的理解"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude 生成每个词","note":"每生成一个 token，模型都要对上下文做一次 Attention：决定下一个词更依赖前面的哪部分。这是生成的核心动作。"},{"name":"翻译模型的对齐","note":"把『I love you』翻成中文时，Attention 让『love』和『爱』自动对上号，哪怕位置完全错开（这就是 Cross-Attention 用武之地）。"},{"name":"代码补全","note":"补全函数体时，Attention 帮模型盯住几千行前的函数签名和参数定义，而不是只看到最近几行。"},{"name":"长文档问答","note":"在长文章里问『第三部分的结论是？』，Attention 让模型跳过大段无关内容，直接聚焦第三部分的句子。"}]},{"type":"compare","pairs":[{"a":"RNN 顺序处理","b":"Attention 全局直连","diff":"RNN 必须一个字一个字按顺序传，远处信息会衰减；Attention 让任意两个位置直接相连，没有距离衰减。"},{"a":"Self-Attention","b":"Cross-Attention","diff":"Self 是同句话内部互相理解；Cross 是让一方去『读』另一方（翻译、RAG 上下文注入都用它）。"},{"a":"单头注意力","b":"多头注意力","diff":"单头只有一种看法；多头并行多组 Q/K/V，相当于同时用多个角度理解，效果明显更好。"},{"a":"注意力（Attention）","b":"记忆（Memory）","diff":"注意力是每次计算时动态算出的关注权重，不存下来；记忆是存下来的长期信息。很多人把注意力误当成记忆。"}]},{"type":"mistakes","items":["以为 Attention 是『看一遍就记住』的长期记忆。它不是记忆，而是每次计算时动态分配的关注权重——每次都要重新算，不会存下来。","以为注意力可视化等于模型的可解释性。权重高代表统计上相关，不代表模型逻辑上『是因为这个』。","把『注意力』和『上下文窗口』混为一谈。窗口决定能看多远，Attention 决定窗口内怎么分配关注。","以为只看『最近几个词』。Attention 恰恰是全局的——它牺牲计算量，换来的是真正看全上下文。","以为 Attention 零成本。它的核心开销是 O(n²)：n 个词两两算一遍。这正是上下文窗口成为瓶颈的原因。"]},{"type":"deep","title":"深入一点：从直觉到公式","beginner":["注意力权重加起来等于 1（100%）。Softmax 就是把一坨分数变成『加起来为 1、且大的更大』的数。","不必纠结矩阵怎么算，你只需记住一句口诀：『Query 找人，Key 被找，Value 是内容，三者相乘加权求和』。","它最厉害的地方：任意两个词无论隔多远都能直接相关——远处那个词和眼前这个词，算注意力的成本完全一样，这是它战胜 RNN 的根本原因。"],"advanced":["核心公式：Attention(Q, K, V) = softmax( (Q·Kᵀ) / √d ) · V。除以 √d（d 是向量维度）是为了防止点积过大把 softmax 压死、导致梯度消失。","Self-Attention 的 Q/K/V 都来自同一句话，让句子内部互相理解；Cross-Attention 的 Q 来自一方、K/V 来自另一方（如翻译、RAG 上下文注入）。","复杂度 O(n²)：n 个词两两都算一遍。这正是上下文窗口成为瓶颈的原因，也是稀疏注意力、局部注意力、线性注意力研究的动机。","不要神化注意力可视化：权重高 ≠ 模型真『懂』了，它更多是统计相关而非可解释的因果。",{"code":"# 概念示意：手工算一次注意力（极简 2 词版）\nimport math\n\ndef softmax(xs):\n    ex = [math.exp(x) for x in xs]\n    s = sum(ex)\n    return [e / s for e in ex]\n\nq = [1.0, 0.0]  # 我是『它』的 Query\nks = {\"猫\": [0.9, 0.1], \"狗\": [0.2, 0.8]}  # 两个词的 Key\n\nscores = {w: round(q[0]*k[0] + q[1]*k[1], 3) for w, k in ks.items()}\nprint(\"点积分数:\", scores)\nweights = dict(zip(scores, softmax(list(scores.values()))))\nprint(\"softmax 权重:\", {w: round(v,3) for w,v in weights.items()})\n# 猫的权重明显更高 → 模型认为『它』更像猫","lang":"python"}]},{"type":"exercise","prompt":"「它拿起了那支笔，因为【　】太亮了。」这个【　】里的词，会让『太亮了』把更多注意力分给『笔』而不是『它』，你能猜出最合理的一个词吗？","opts":["灯","笔帽","手","桌"],"a":0,"explain":"『灯太亮了』语义合理，Attention 会让『亮』和『灯』形成高权重连接；而『笔帽太亮了』虽然通顺，但更重要是体会：有了『亮』这个线索，Attention 会去找『最配得上的名词』。模型正是靠大量这样的共现线索来分配注意力。","jump":"sec5-step1","jumpLabel":"用 Query 和 Key 算相似度这一步"},{"type":"check","title":"结课检测：你真的理解 Attention 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"Attention 中 Query、Key、Value 各自的作用，最准确的说法是？","opts":["Q 是内容，K 是找人，V 是被找","Q 在找人，K 是被找的标签，V 是被吸收的内容","三者完全相同","Q 是权重，K 是分数，V 是标签"],"a":1,"explain":"Q（Query）发起匹配去『找谁』；K（Key）告诉别人『我是谁』供匹配；V（Value）是被加权吸收进的真正内容。","jump":"sec5-step0","jumpLabel":"乘上三个矩阵得到 Q/K/V 这一步"},{"q":"为什么说 Attention 解决了 RNN『记不住长句』的问题？","opts":["因为它是顺序处理的","因为任意两个词都可以直接相关，不随距离衰减","因为它把句子变短了","因为它只关心最近的词"],"a":1,"explain":"RNN 依赖顺序传递、距离远信息衰减；Attention 让任意两个位置直接相连、远近一视同仁。","jump":"sec8","jumpLabel":"『以为只看最近几个词』那条误区"},{"q":"把注意力分数做 softmax 是为了什么？","opts":["让负数变成正数","让分数变成加和为 1 的权重，且强调大的","让计算更快","让向量变短"],"a":1,"explain":"Softmax 把一坨任意分数变成『加起来为 1』、且大者更大的概率分布，这样加权求和才合理、可解释。","jump":"sec5-step2","jumpLabel":"Softmax 归一化成权重这一步"},{"q":"Self-Attention 与 Cross-Attention 的区别是？","opts":["没有区别","Self 是同句话内部互相理解；Cross 是让一方去读另一方","Self 只用于图片，Cross 只用于文字","Self 更快，Cross 更慢"],"a":1,"explain":"Self-Attention 的 Q/K/V 来自同一句话；Cross-Attention 的 Q 来自一方、K/V 来自另一方（翻译、RAG 都用）。","jump":"sec7","jumpLabel":"对比区里的 Self vs Cross 那一条"},{"q":"多头注意力（Multi-Head）的本质好处是？","opts":["让模型更快","让模型从多个不同视角同时理解，组合出更丰富的语义","让上下文窗口变长一倍","省掉 Softmax"],"a":1,"explain":"把模型注意力想象成多个不同的专家，各看一面（指代、语法、距离），最后合并，理解更全面。","jump":"sec5-step5","jumpLabel":"多个头并行这一步"}],"done":"你已经理解 Attention 是 Transformer 的心脏。这个『找相似、加权吸收』的机制，也是后面 RAG 把检索结果喂进模型时的同一套逻辑。","nextLesson":"l-transformer"},{"type":"connection","known":["词 → 向量（Embedding）","向量方向越像、语义越近（余弦相似度）"],"learned":["每个词同时扮演 Query / Key / Value 三角色","注意力 = 相似度分数 → softmax 权重 → 加权求和","Self-Attention 让句子内部互相理解，多头提供多视角","Attention 任意位置直连、无距离衰减，解决了长句遗忘"],"next":"Attention 是 Transformer 的心脏。下一课我们把这套注意力装进一个完整的架构：位置编码、多头、归一化……看看它怎么组成一个能真正训练、能翻译能写诗的大模型——Transformer。"}]},"l-embedding":{"id":"l-embedding","title":"Embedding｜怎么把词变成电脑能懂的数字","subtitle":"为什么文字不能直接进神经网络？为什么不是给每个词编个号？为什么意思相近的词离得更近？","category":"c02-essentials","chapterTitle":"第一章 · 向量与语义","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["embedding","vector","cosine-similarity","emb-vector-store"],"prereqLessons":["l00-ai-world"],"nextLesson":"l-attention","sections":[{"type":"opening","question":"你让 ChatGPT 翻译『苹果很好吃』，它内部第一件事不是『读懂』这句话，而是把『苹果』变成了一串数字。猜一猜：为什么电脑不能用『苹果』这两个汉字直接思考，非得多此一举先转成数字？","guess":"有人会想：给猫=1、狗=2、苹果=3 编个号不就行了？","next":"这节课就回答『为什么不能简单编号』，以及真正的 Embedding 是怎么做到『意思相近的词，数字也相近』的。"},{"type":"why","before":"神经网络只会做数学运算：加法、乘法、比较大小、算距离。它天生看不懂『猫』『狗』『苹果』这些文字。","problem":"如果文字根本送不进神经网络，那后面的一切——翻译、对话、理解、检索——全都是空中楼阁。这是所有语言模型的『第一道门』，绕不过去。","need":"所以我们必须在『文字』和『数字』之间搭一座桥，让电脑既能「算」文字，又能保留文字的含义。这座桥就是 Embedding。","visualNote":"下面这张 2D 语义空间图，就是你要带走的直觉：位置 = 语义。"},{"type":"oneline","text":"Embedding 就是把『一个词』变成『一串数字（向量）』，并且让意思相近的词，数字串长得也相近——于是电脑就能『算』语义了。"},{"type":"visual","kind":"embedding-space","title":"Embedding 2D 语义空间（可交互）","hint":"这是把词『压扁』到二维的示意：意思相近的词会聚在一起。观察猫/狗/狮子聚在『动物角』，苹果/香蕉聚在『食物角』。试试输入几个词，看它落在哪一群。"},{"type":"intuition","blocks":[{"k":"为什么不能直接给词编号？","t":"你可能会想：猫=1、狗=2、苹果=3 不就行了？但问题是：2 和 3 只差 1，可『狗』和『苹果』的语义差得十万八千里。编号把『数字距离』和『语义距离』完全搞乱了——电脑会误以为狗和苹果几乎一样。"},{"k":"用一张坐标纸来想","t":"想象一张地图，横轴是『是不是动物』，纵轴是『是不是食物』。『猫』放左边靠上，『狗』紧挨它，『苹果』放右上角。位置越近，意思越像。Embedding 本质就是在几百上千维的『坐标纸』上，给每个词找个位置。"},{"k":"一个生活类比","t":"就像地理坐标：北京和天津坐标很近，所以在空间里相邻；语义相近的词，在 Embedding 空间里坐标也相邻。"}]},{"type":"how","intro":"Embedding 是怎么『学』出来的？核心思想只有一句话：一个词的含义 = 它经常和哪些词一起出现。","steps":[{"in":"收集海量文本","process":"从整个互联网语料里，观察『猫』总是和『狗、宠物、喵、毛』一起出现，而『苹果』总跟『水果、吃、红色』一起出现。","out":"得到每个词在语料里的『共现模式』"},{"in":"用共现模式训练向量","process":"训练一开始给每个词一组随机数字，然后不断调整，让『经常一起出现』的词向量越走越近，『从不一起出现』的词向量越走越远。","out":"每个词最终固定成一个固定长度的向量（如 300 或 768 维）"},{"in":"用向量距离比较语义","process":"两个词的向量越接近（夹角越小、余弦相似度越高），语义越相近。电脑从此『算得出』猫≈狗、苹果≠猫。","out":"文字第一次可以被数值比较"},{"in":"送入下游模型","process":"这个数字向量就是神经网络的输入。LLM 只认数字，现在它『看得懂』词了，可以开始做翻译、对话、生成。","out":"模型能对词做运算、比较、生成"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude","note":"内部第一件事就是把你的每个 Token 转成 Embedding 向量，再送进 Transformer 网络。"},{"name":"搜索引擎语义检索","note":"把『怎么养猫』和『养宠物指南』都向量化，语义相近就能互相匹配，不必字面相同也能搜到。"},{"name":"NotebookLM / RAG","note":"把你的资料切成块并向量化，用户提问时在向量空间里『找最像的那几块』再交给模型回答——这就是 RAG 的地基。"}]},{"type":"compare","pairs":[{"a":"Token","b":"Embedding","diff":"Token 是文字切出的『小块』（词/子词）；Embedding 是把每个小块变成的『数字向量』。先切 Token，再做 Embedding。"},{"a":"Embedding 模型","b":"LLM","diff":"Embedding 模型把文本压成『定位向量』（不生成文字）；LLM 生成文字。一个是『编码员』，一个是『作家』。"},{"a":"One-hot 编号","b":"Embedding","diff":"One-hot 让所有词互相『等距』、无法表达语义；Embedding 让相近的词更近，真正抓住含义。"}]},{"type":"mistakes","items":["以为 Embedding 只是『给每个词一个数字』。其实是一整串数字（向量），且数字之间存在『相似关系』——这才是关键。","以为 Embedding 模型和 LLM 是同一个东西。它们是分工不同的两个模型：一个负责编码相似度，一个负责生成文字。","以为向量维度越高一定越好。维度越高表达力越强，但更贵、更易过拟合，常见几百维就够用。","以为 Embedding 能『理解逻辑』。它只捕捉统计上的相似，不保证逻辑正确——所以光靠 Embedding 做问答会答非所问。"]},{"type":"deep","title":"深入一点：从二维直觉到真实向量空间","beginner":["Embedding 在工程上就是『查表』：模型里有一张巨大的表，每个词一行，那一行数字就是它的向量。训练好了之后，直接用查到的数字即可。","维度越高，能表达的语义越细腻，但计算越贵。常见几百维就够处理大多数任务。","真正常用的是一种叫『子词』的粒度：一个字被拆成更小的片段（如 'unbreakable' → 'un' + 'break' + 'able'），这样遇到没见过的词也能拼出向量。"],"advanced":["向量不只给每个词一个『标签』，它把语义结构编进了几何里：经典例子 king − man + woman ≈ queen，说明向量『方向』也承载意义。","Embedding 模型（如 text-embedding 系列）与 LLM 是不同模型：前者把文本压缩成『定位码』，后者生成文字。它们可以分开训练、分开使用。","计算两个向量有多像，最常用的指标是**余弦相似度** cos(θ)：只看方向、不看长度，数值越接近 1 越像。",{"code":"# 余弦相似度：越大越像\nimport numpy as np\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\ncat   = np.array([0.9, 0.1])   # 靠近动物方向\napple = np.array([0.1, 0.9])   # 靠近食物方向\ndog   = np.array([0.85, 0.15]) # 很接近猫\n\nprint(round(cosine(cat, apple), 2))  # 0.22  → 语义远\nprint(round(cosine(cat, dog), 2))    # 1.0   → 语义很近","lang":"python"},"维度本质：真实 Embedding（如 OpenAI text-embedding-3）常达上千维，一个词就是一个上千维空间里的点。降维可视化（t-SNE / PCA）只是把上千维『压扁』到 2D 方便人看。"]},{"type":"exercise","prompt":"在一个语义空间里，『国王』向量减去『男人』向量，再加上『女人』向量，猜一猜结果最可能靠近下面哪个词？","opts":["王子","女王（皇后）","父亲","阿姨"],"a":1,"explain":"这正是著名的 king − man + woman ≈ queen 现象：向量的方向承载意义，『王 - 男 + 女』就指向『女王』的方向。它说明 Embedding 抓到的不是孤立的词，而是语义结构。","jump":"sec5-step3","jumpLabel":"用向量距离比较语义这一步"},{"type":"check","title":"结课检测：你真正理解 Embedding 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么不能直接给每个词编个号（猫=1，狗=2，苹果=3）？","opts":["因为编号会让相近的词距离更近","因为编号会破坏语义距离：狗和苹果只差 1，但语义差很远","因为编号需要太多内存","因为编号不能用于神经网络"],"a":1,"explain":"编号把数字距离和语义距离搞混了：狗(2)和苹果(3)只差1会被当成很相似，但它们的含义毫无关系。","jump":"sec4","jumpLabel":"『为什么不能直接给词编号』这一段"},{"q":"两个 Embedding 向量夹角越小（余弦相似度越高），说明什么？","opts":["两个词的语义越相近","两个词的字符串越长越像","两个词出现频率越接近","两个词的长度越接近"],"a":0,"explain":"夹角越小，向量在空间里越靠近，代表语义越相近。这就是『用距离算语义』。","jump":"sec5-step2","jumpLabel":"『用向量距离比较语义』这一步"},{"q":"关于 Embedding 模型与 LLM 的关系，正确的是？","opts":["它们是同一个模型","Embedding 模型把文本变向量、LLM 生成文字，二者分工不同","LLM 内部根本不做 Embedding","Embedding 模型能直接写文章"],"a":1,"explain":"Embedding 模型负责『编码相似度』，LLM 负责『生成内容』，是两个可分开训练的模型。","jump":"sec7","jumpLabel":"『Embedding 模型 vs LLM』那一条对比"},{"q":"Embedding 的『含义』主要来自哪里？","opts":["每个字在字典里的官方解释","这个模型『预测下一个词』时学到的共现模式","开发者手写的规则","词的笔画数"],"a":1,"explain":"一个词的含义 = 它常和哪些词一起出现。模型在大量文本上学到的正是这种共现模式。","jump":"sec5-step0","jumpLabel":"『收集海量文本』这一步"},{"q":"下面哪句关于向量维度的说法正确？","opts":["维度越高一定越好，越细越好","维度越低越好，因为一定更便宜","维度是表达力与成本的权衡，常见几百维就够用，过高更贵且易过拟合","维度只影响颜色不影响语义"],"a":2,"explain":"维度是权衡的结果：高维表达强但贵且易过拟合，低维省但表达粗糙。实际常用几百维。","jump":"sec9","jumpLabel":"深入一节关于维度的说明"}],"done":"你已经理解了『文字 → 数字向量 → 算距离』这条链路，这是 RAG、搜索、推荐共同的地基。","nextLesson":"l-attention"},{"type":"connection","known":["AI 世界全景：模型只能处理数字","Embedding 是文字进入模型的第一道门"],"learned":["文字 → 向量，让电脑能算语义","相近的词向量距离更近，用余弦相似度衡量","Embedding 模型与 LLM 分工不同","向量方向也能承载意义（king − man + woman ≈ queen）"],"next":"有了『每个词是一个数字向量』，下一步就是大招：Attention——模型怎么在一句话里决定『该重点关注哪个词』。这决定了模型能不能读懂『这只狗没咬那只猫，是因为它怕它』里『它』到底指谁。"}]},"l-rag":{"id":"l-rag","title":"RAG｜让模型『查资料』再回答","subtitle":"为什么 ChatGPT 不知道你的私有文档？怎么让模型『翻开你的资料』再回答？从切块到生成，一条流水线看懂 RAG。","category":"c07-rag","chapterTitle":"第一章 · RAG 全流程","level":"base","estTime":"30-35 分钟","difficulty":2,"concepts":["rag-pain","rag-pipeline","chunking","emb-vector-store","vector-search","rerank"],"prereqLessons":["l-transformer","l-embedding"],"nextLesson":"pl-function-calling","sections":[{"type":"opening","question":"你的同事把公司 80 页的员工手册发给你，让你问 ChatGPT『年假到底有几天』。但 ChatGPT 根本没见过这本手册——你猜它是会照着手册答，还是自己编一个答案？如果它答错了，该怎么办？","guess":"很多人觉得「那就把整本手册贴上问它」。但手册几十万字，靠粘贴根本塞不进一次对话，而且重点会淹没在噪声里。","next":"这节课要讲的就是正解：RAG 检索增强生成。它让模型在回答前，先去你的资料库里『只挑最相关的几段』，再照着这几段回答——既答得准，又附出处。"},{"type":"why","before":"经过前面几课，我们已经有了一个很聪明的模型（Decoder-only Transformer）。但它有一个致命限制：它只知道训练时见过的东西，而且经常一本正经地编造（幻觉）。","problem":"1) 你的合同、内部 SOP、论文——模型训练时根本没看过；2) 即使看过，版本也早就过期了；3) 让它硬答私有问题，它大概率会编。而重新训练整个模型，又贵又慢又不可能频繁做。","need":"与其改模型的『脑子』，不如每次回答时给它配一本『说明书』：先把相关的资料找出来喂给它，让它照着说。这个思路就是 RAG——简单、便宜、资料随时能更新。","visualNote":"下面这条流水线是 RAG 的完整精神：切块 → 向量化 → 检索 → 重排 → 组装 → 生成。你可以点『运行』亲手体验。"},{"type":"oneline","text":"RAG（检索增强生成）就是：让模型在回答之前，先去你的资料库里检索相关内容，把查到的片段拼进上下文，再让模型照着一小份『精选资料』作答。于是它能回答自己没学过的私有知识，还能顺便指出出处。"},{"type":"visual","kind":"rag-pipeline","title":"RAG 完整流水线：从文档到回答（可交互）","hint":"这就是升级版可交互 RAG 实验：左边填一份『你要提问的文档』，下面输问题，点【▶ 运行 RAG】。观察系统如何切块 → 向量化 → 检索 → 重排 → 组装上下文 → 生成带引用的回答。"},{"type":"intuition","blocks":[{"k":"开卷考试 vs 闭卷考试","t":"普通 LLM 是闭卷考试：只凭脑子里的记忆答题，记不住就编。RAG 是开卷考试：允许你翻资料，翻到相关的那页再答。显然开卷更可靠、更可核对。"},{"k":"图书馆查书再回答","t":"你问『公司年假制度是什么』。RAG 不会直接在记忆里编，而是先去公司知识库检索年假相关文档，找到后引用着回答。"},{"k":"不是变聪明，是带了参考书","t":"RAG 不提升模型智商，而是每次回答都带着最新、属于你的资料。资料一更新，回答立刻跟着更新，完全不用重新训练模型。"}]},{"type":"how","intro":"RAG 分两个阶段：『入库』（离线，把文档变成可检索的向量库）和『查询』（在线，用户提问时检索 + 生成）。下面是完整流程，也是本课的主干。","steps":[{"in":"先想清楚：为什么要用 RAG","process":"场景判断：需要回答私有/最新/超长知识，或答案需要可溯源时用 RAG。如果模型自带答案且内容不敏感，也许不需要 RAG。","out":"RAG 解决『知识更新与私有化』，不是『让模型变聪明』"},{"in":"解析 Parsing","process":"把原始文档（PDF、Word、网页）用解析器抽取出结构化文本，去掉页眉页脚、图表残渣，必要时做 OCR。","out":"干净、可用的纯文本"},{"in":"切块 Chunking","process":"把长的文本切成几百到上千字的小块。切多大、是否重叠、按什么切（标题/段落）直接影响检索质量。","out":"文档 → 若干 chunk（带来源、页码等元数据）"},{"in":"向量化 Embedding","process":"用 Embedding 模型把每个 chunk 变成一个向量（语义相近的向量相近）。","out":"每个 chunk → 一个向量"},{"in":"存入向量库 VectorDB","process":"把『向量 + 原文 + 元数据』存进向量数据库（FAISS、Milvus、pgvector、Qdrant），并建好索引以便毫秒级检索。","out":"可快速相似检索的向量库"},{"in":"检索 Retrieval（含 Top-K）","process":"用户提问时，把问题也向量化，在向量库里找最像的『Top-K 块』（通常 K=5~20，按余弦相似度排名）。","out":"问题 → 排好序的 N 个候选 chunk"},{"in":"重排序 Rerank","process":"初筛的 Top-K 往往有噪音。用一个更精细的模型把 K 个候选再精排，把真正相关的提到最前、滤掉无关项。","out":"更精准的少量片段（通常取前 3~5 块）"},{"in":"组装上下文 + 生成","process":"把精选 chunks 拼进 Prompt，附上问题，提示模型『只依据下面资料回答并引用出处』。LLM 据此生成带引用的回答。","out":"有出处、可更新、针对私有知识的回答"}]},{"type":"realworld","items":[{"name":"NotebookLM","note":"你上传 PDF/视频，它检索你的资料再回答，还能生成带引用的播客、摘要。教科书级 RAG 产品。"},{"name":"企业内部知识库客服","note":"把 SOP、产品手册向量化，客服 AI 查文档再回答，而不是对着空气编。"},{"name":"Claude Projects / 附件上传","note":"给对话挂上资料，模型按需检索引用，本质是一套轻量 RAG。"},{"name":"搜索增强的 ChatGPT / Perplexity","note":"它先联网检索实时网页，再基于检索结果回答——用互联网当『向量库』的 RAG。"}]},{"type":"compare","pairs":[{"a":"RAG","b":"微调 Fine-tuning","diff":"RAG 每次查最新资料、可溯源、便宜、可随时更新；微调是改模型脑子、更适合学风格学格式。知识类更新首选 RAG。"},{"a":"向量检索（语义）","b":"关键词检索（BM25）","diff":"向量找语义相近（换个说法也能找到）；关键词精准匹配字面（找人名/编号更稳）。生产常用『混合检索』互补。"},{"a":"RAG","b":"超长上下文","diff":"RAG 主动挑最相关片段、便宜快速；超长上下文把整本书塞进去、贵且重点容易淹没。大资料库优先 RAG。"},{"a":"RAG","b":"Agent","diff":"RAG 是『查资料再回答的单步机制』；Agent 是『多步决策、自己调用工具的循环』。两者常配合：Agent 需要信息时用 RAG。"}]},{"type":"mistakes","items":["以为 RAG = 把文档一股脑塞进提示词。真正的 RAG 要先切块、向量化、检索、重排，只喂最相关的几块。","忽略 chunking 质量。切坏了，再好的模型也答不准——检索进来自的都是垃圾，这叫『垃圾进、垃圾出』。","以为检索到就完了、不必做 rerank。初检的 Top-K 常有噪音，重排能明显提高准确率。","忘记引用溯源。落地到医疗/法务/企业等严肃场景，没有出处等于不可信。","把 RAG 当成解决幻觉的万灵药。资料里没有、或检索失败时，模型照样可能编——还要做『越权拒答』『检索兜底』。","只在单文档上跑 RAG 就上生产。跨多文档局部推理（关系、总分结构）需要更进阶的方案（如 GraphRAG、切分策略优化）。"]},{"type":"deep","title":"深入一点：把 RAG 的每一个零件都拆开","beginner":["chunk 太小 → 语义不完整；chunk 太大 → 噪音多、可能被截断。常见几百~一千字，配合 20%~50% 重叠（overlap）避免把完整语义在边界切断。","向量相似 ≠ 字面相似：换个说法（『年假』vs『带薪假期』）有时也能检索到，这是向量检索比关键词强的地方。","RAG 不会凭空创造知识，它只会引用你给的东西——资料库质量 ≈ 回答质量。","Top-K 的含义：K 是取前几个相似块。K 太小漏信息，K 太大引入噪音挤占上下文，通常 5~20 之间调。"],"advanced":["混合检索（Hybrid）：向量检索（语义）+ 关键词检索（BM25，精确匹配人名/编号）并行，再用加权或 RRF 融合，互补漏检。","Rerank 为什么必要：初检向量健壮但不精，专门的 rerank 模型（cross-encoder）能逐对精判相关性，显著提升准确率和最终回答质量。","引用溯源（Citation / Grounding）：让模型输出带片段编号，用户可核对来源；对合规落地几乎是刚需。","切分进阶：按章节/标题等『结构感知』切块（structure-aware chunking）、父子块（parent-child）、滚动窗口，都比盲目按字数切更好。","评估：用『召回率（该找到的找到没）+ 准确率（找到的是不是都相关）』评价检索，用『忠实度/有据率』评价最终回答，还要做『检索失败与拒答』的兜底。","Agentic RAG：把检索从单次升级成『多轮自主规划』——Agent 先判断需要什么信息、决定检索哪几个库、必要时多轮追问或修正查询词，而不是一次检索定死。",{"code":"# 概念示意：RAG 里最核心的一步——向量检索（伪代码思路）\nimport numpy as np\n\nchunks = [\"年假制度：入职满一年享 5 天…\", \"报销流程：金额低于 1000 走 OA…\"]\nchunk_vecs = [np.array([0.9, 0.1]), np.array([0.1, 0.9])]  # 示意向量\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\nquery_vec = np.array([0.85, 0.15])  # 用户问题『年假有几天』向量化\ntop_k = 1\nranked = sorted(((cosine(query_vec, v), i) for i, v in enumerate(chunk_vecs)),\n                reverse=True)[:top_k]\nprint('最相关的资料块:', chunks[ranked[0][1]])\n# → 年假制度那一段","lang":"python"}]},{"type":"exercise","prompt":"继上一课：公司手册 80 页，你的知识库已经把它切成几百块并存好向量。现在问『年假有几天』，系统检索返回了 8 个候选块，其中第 3 块是『员工福利总览』、第 7 块是『请假制度细则』。下一步系统应该做什么？","opts":["直接把 8 块全部塞进提示词","对 8 块做 Rerank 精排，只取最相关的 3~5 块再喂给模型","不用检索了，直接让模型猜","把 8 块向量相加存回库里"],"a":1,"explain":"初检的 Top-K 常有噪音。正确做法是先 Rerank 精排，把真正相关的『请假制度』提到最前、滤掉无关的『福利总览』，再只喂少量精选块给模型——既省上下文又更准。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"type":"check","title":"结课检测：你真的理解 RAG 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"RAG 解决的核心问题是？","opts":["让模型数学更好","让模型能回答私有/最新知识并可溯源，而不用重新训练","让模型更快生成","让模型学会编程"],"a":1,"explain":"RAG 的核心价值：用检索到的外部资料补充模型没学过的知识，便宜、可更新、可引用。","jump":"sec5-step0","jumpLabel":"先想清楚为什么要用 RAG 这一步"},{"q":"RAG 的『入库』阶段，正确的顺序是？","opts":["向量化 → 切块 → 存库","切块 → 向量化 → 存库","存库 → 向量化 → 切块","检索 → 切块 → 向量化"],"a":1,"explain":"先把长文档切成 chunk，再逐块向量化，最后连向量带原文存进向量库。检索是查询阶段的事。","jump":"sec5-step2","jumpLabel":"切块 Chunking 这一步"},{"q":"『切块太大（比如把整章当一个块）』最可能带来什么问题？","opts":["向量库存不下","块内噪声多、关键信息被淹没，检索和回答变差","一定比小块更准","会让模型忘掉上下文"],"a":1,"explain":"块太大噪声多、语义杂，检索命中后无关内容挤占上下文，回答质量下降。所以要用合适的块大小 + 重叠。","jump":"sec9","jumpLabel":"深入节里关于 chunk 大小/重叠的说明"},{"q":"为什么生产系统里还要做 Rerank 重排？","opts":["为了多花一点算力","初检的 Top-K 常有噪音，用更精细的模型重排能显著提升相关性与准确率","为了把回答变长","为了跳过 Embedding"],"a":1,"explain":"向量初检健壮但不精，专门的 rerank 模型能逐对精判，把真正相关的片段提到最前。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"q":"资料库里根本没有答案时，一个设计良好的 RAG 系统应该？","opts":["强行编一个最像的答案","在引用不到出处时明确『资料中未找到』或拒答，做检索兜底","把用户问题原样丢回","删掉这个问题"],"a":1,"explain":"RAG 不是幻觉万灵药。检索不到可靠出处时应『越权拒答/检索兜底』，而不是硬编。","jump":"sec8","jumpLabel":"『把 RAG 当万灵药』那条误区"}],"done":"你已经掌握 RAG 的完整流水线和调优要点。现在模型会查资料了，但它还是『你问一句、它答一句』。最后一课，我们让它自己动起手来。","nextLesson":"l-agent"},{"type":"connection","known":["Embedding：文字 → 向量，语义相近的向量相近","Transformer：模型的脑子","上下文窗口：模型一次能看多少"],"learned":["RAG 让模型先检索资料再回答，解决私有/最新/可溯源","完整流程：解析 → 切块 → 向量化 → 向量库 → 检索 Top-K → 重排 → 组装 → 生成 + 引用","chunk 大小/重叠、混合检索、Top-K、rerank、评估、Agentic RAG 等调优点","RAG vs 微调 vs 长上下文 vs Agent 的取舍"],"next":"RAG 让模型会查资料，但模型仍停在你说一句、它应一句。下一课是这个旅程的终点也是新起点：Agent——让模型自己拆目标、自己调用工具、根据反馈循环，把一整件事独立做完。"}]},"l-transformer":{"id":"l-transformer","title":"Transformer｜大模型的地基架构","subtitle":"为什么 2017 年诞生的它，能横扫翻译、写作、代码、对话？一个 20 分钟看懂『大模型的心脏是怎么拼出来的』。","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"25-30 分钟","difficulty":3,"concepts":["transformer","position-enc","multihead","attention"],"prereqLessons":["l-attention"],"nextLesson":"l12-context-window","sections":[{"type":"opening","question":"上一课我们有了 Attention，它能让任何两个词互相关注。但只用 Attention 还是没法当一个能工作的模型——它不知道『第 5 个词和第 2 个词』谁先谁后，也堆不了很深。猜一猜：研究人员 2017 年到底在 Attention 外面『加了哪些零件』，才把它拼成了横扫一切的 Transformer？","guess":"很多人以为 Transformer = Attention，觉得『注意力』就是全部。","next":"这节课我们把注意力装进完整的大脑：位置编码、多头、残差、归一化、前馈网络、N 层堆叠。学完你就明白，为什么它能取代 RNN、成为所有大模型的共同地基。"},{"type":"why","before":"上一课我们有了 Attention：任何两个词都能直接互相关注。但这只是一块『积木』，离一个能真正工作的模型还差很远。","problem":"只靠 Attention 不够：1) 它不知道词的位置——『猫追狗』和『狗追猫』词全一样；2) 一层注意力学到的东西有限；3) 想堆深又容易训练不动（梯度消失）。","need":"Transformer 就是给 Attention 配上『位置感、深度、稳定训练』三件装备，把一块积木组装成一台可以训练、可以并行、可以堆得极深的机器。它是 ChatGPT、Claude、Gemini 的共同地基。","visualNote":"下面这张图是 Transformer 的主干流水线，你可以一步一步点开看每一层在干什么。"},{"type":"oneline","text":"Transformer 是 2017 年提出的一个『把注意力机制组装成完整大脑』的架构：它用『多头注意力 + 前馈网络 + 残差连接 + 位置编码』堆成一层又一层的模块，能并行、能训练得非常深，从此成为所有现代大语言模型的共同地基。"},{"type":"visual","kind":"transformer-flow","title":"Transformer 主干流水线：一步一步看","hint":"点击【下一步】，观察一个词从数字向量走到预测下一个词的完整过程：输入 → 位置编码 → 多头注意力 → 残差+归一化 → 前馈网络 → 重复堆叠 → 输出。"},{"type":"intuition","blocks":[{"k":"一个加工厂流水线","t":"把 Transformer 想成一家加工厂：原料是一串向量。每个工位（层）做两件事——同事协作（注意力，大家互通信息）+ 个人精加工（前馈网络，每个词独自想更深）。一层做完送下一层，共 N 层。"},{"k":"用乐高积木来想","t":"Attention 只是其中一块积木。Transformer 是说明书：告诉你这一层要怎么拼——注意力 + 残差 + 归一化 + 前馈，然后复制粘贴 N 次。"},{"k":"办公室里的并行会议","t":"RNN 像只有一个话筒的圆桌，每人必须轮流说（慢）；Transformer 像微信群——所有人同时发言、同时收听（并行快），谁跟谁相关自己匹配（注意力）。这就是它又快又强的秘密。"}]},{"type":"how","intro":"一个词在 Transformer 里的完整旅程。每一步都围绕同一批向量做变换，最后模型学会『预测下一个词』。","steps":[{"in":"输入：词向量 + 位置编码","process":"每个词先查表得到 Embedding 向量。但向量本身不含位置，所以再加一个位置信息（位置编码），让模型知道『这是第 5 个词』。","out":"每个词都带上位置的向量"},{"in":"多头注意力层（同事协作）","process":"这一层让每个词结合全局上下文：用上节课的 Q/K/V 机制，多组并行，输出再拼接。词的『含义』从此包含了周围所有词。","out":"每个词变成理解上下文后的新向量"},{"in":"残差连接 + 归一化（稳定训练）","process":"把『进来的向量 + 注意力算完的向量』加在一起（残差），再做归一化。这就像修了一条高速公路：信息不衰减地直接流过深层。","out":"浅层信息能无损抄近道到达深层，网络可以堆得深"},{"in":"前馈网络 FFN（个人精加工）","process":"一个两层全连接网络，对每个词独立做非线性变换，让模型有能力表达更复杂的关系。","out":"每个词被再想一想，表达能力增强"},{"in":"重复堆叠 N 层","process":"把『注意力 + 残差 + 归一化 + 前馈』复制 N 次叠起来（GPT 有十到上百层）。每层都让词的表示更抽象、更接近任务。","out":"深层的向量已经浓缩了整句话的语义"},{"in":"输出：预测下一个词","process":"最后一层接线性层 + softmax，把向量变成词典里每个词的概率，取概率最高的作为下一个词。","out":"生成一个词 → 拼回输入 → 继续预测下一个词"}]},{"type":"realworld","items":[{"name":"ChatGPT / GPT 系列","note":"Decoder-only Transformer：单纯地一层层预测下一个词，就长出了对话和推理能力。"},{"name":"Claude / Gemini","note":"同一架构的不同工程实现：同样的多头注意力 + 深层堆叠，在尺度与训练技巧上各有差异。"},{"name":"翻译与摘要模型（T5/BART）","note":"Encoder-Decoder 结构：编码器读懂全文，解码器再一句句生成译文或摘要。"},{"name":"代码补全（Codex 前身/Copilot）","note":"把代码当另一种语言喂给 Decoder-only Transformer，学会了补全、续写、改 bug。"}]},{"type":"compare","pairs":[{"a":"RNN","b":"Transformer","diff":"RNN 顺序串行、远处信息衰减、难并行；Transformer 全局直连、天然并行、能堆深。2017 后几乎完全取代 RNN。"},{"a":"Encoder-only（BERT）","b":"Decoder-only（GPT）","diff":"前者双向读全文、擅长理解（分类/检索）；后者只能从左往右、擅长生成（对话/写作/代码）。"},{"a":"单层注意力","b":"N 层堆叠的 Transformer","diff":"单层只做一次互相看；Transformer 把多次『互相看 + 精加工』叠起来，让表示一层比一层抽象。"},{"a":"Transformer","b":"Attention","diff":"Attention 是其中的一个子模块；Transformer 是包含注意力在内的一整套完整架构。很多人把两者画等号，其实 Attention ⊆ Transformer。"}]},{"type":"mistakes","items":["以为『Transformer = Attention』。Attention 只是其中一个子模块，完整架构还包括残差、归一化、前馈、位置编码。","以为 BERT 和 GPT 一样。BERT 双向理解、GPT 单向生成，职权完全不同。","以为层数越多一定越好。层越深效果提升有边际，还带来更大算力和训练难度。","把『位置编码』当可选项。没有它，『猫追狗』和『狗追猫』对模型来说完全一样——这可是天壤之别。","以为 ChatGPT 用的是完整 Encoder-Decoder。GPT 只用 Decoder-only，这是它和 T5 这类翻译模型的关键区别。"]},{"type":"deep","title":"深入一点：从直觉到架构细节","beginner":["位置编码就是给每个词加一个『第几个』的记号，否则『猫追狗』和『狗追猫』对模型来说字全一样。","残差连接简单说就是『进来和出去加一起』，像搭桥——让深层的梯度不会消失，模型才能堆数十上百层。","前馈网络 FFN 是给每个词单独换个角度想一遍，和注意力（词与词协作）分工不同、缺一不可。","GPT 其实只用了 Transformer 的一半：只有解码器那套（Decoder-only），用来不停地预测下一个词。"],"advanced":["核心是 Decoder：每个 token 只看自己和前面（因果掩码 causal mask），保证预测时不偷看未来。这是它和编码器的最大区别。","缩放点积注意力：Attention = softmax( (Q·Kᵀ) / √d )·V。除以 √d 防点积过大导致梯度消失 / softmax 饱和。","三种架构：Encoder-only（BERT：理解）、Decoder-only（GPT：生成）、Encoder-Decoder（T5：翻译/转换）。ChatGPT 系清一色 Decoder-only。","残差连接 + LayerNorm（常采用 Pre-LN 顺序：先归一化再进子层）是训练稳定性的关键工程细节，是它能堆到千亿参数的原因之一。","复杂度 O(n²)：上下文窗口越大成本越高——这直接决定了长上下文为什么贵、为什么要引入 RAG。",{"code":"# 概念示意：位置编码的经典公式（体会它想表达什么即可）\nimport math\n\ndef pos_encoding(pos, d_model=8):\n    vec = []\n    for i in range(d_model):\n        angle = pos / (10000 ** (2 * (i // 2) / d_model))\n        vec.append(round(math.sin(angle), 3) if i % 2 == 0 else round(math.cos(angle), 3))\n    return vec\n\nfor p in [0, 1, 2, 3]:\n    print(f\"第{p}个词的位置: {pos_encoding(p)}\")\n# 每个位置生成一组各不相同的位置向量 → 模型据此知道先后顺序","lang":"python"}]},{"type":"exercise","prompt":"如果完全不给模型位置编码，只给它 Attention，那么『猫追狗』和『狗追猫』这两句话，模型会怎么看待？","opts":["认为它们语义完全不同（追的方向相反）","认为它们几乎一样（词完全相同，注意力无差别混合）","认为它们字数不同","完全无法处理两个词以上的句子"],"a":1,"explain":"注意力是把所有词互相加权求和，本质记不得先后顺序。没有位置编码，模型会认为两句话『字都一样所以差不多』，分不清谁追谁。这正是位置编码存在的意义。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"type":"check","title":"结课检测：你真的理解 Transformer 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 Transformer 需要位置编码？","opts":["为了让向量维度变大","因为注意力本身不含位置信息，没有它『狗追猫』和『猫追狗』无法区分","为了加快计算","为了让训练更快收敛"],"a":1,"explain":"注意力把所有词互相加权、天然不记顺序；位置编码把『第几个』注入向量，模型才知道先后。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"q":"残差连接（Residual）的主要作用是？","opts":["增加参数数量","让信息能无损跨层传递，网络可以堆得很深且训练稳定","让模型更快生成","代替位置编码"],"a":1,"explain":"把输入与输出相加，像搭桥一样让信息直达深层，缓解梯度消失，是能堆几十上百层的关键。","jump":"sec5-step2","jumpLabel":"残差连接 + 归一化这一步"},{"q":"GPT 属于哪种结构？","opts":["Encoder-only","Decoder-only","Encoder-Decoder","既不是编码器也不是解码器"],"a":1,"explain":"GPT 只用解码器（带因果掩码、从左往右生成），反复预测下一个词。","jump":"sec9","jumpLabel":"深入节里 GPT=Decoder-only 那条"},{"q":"Attention 和 Transformer 的正确关系是？","opts":["它们是同一个东西","Transformer 是 Attention 的一个零件","Attention 是 Transformer 的一个子系统，Transformer 是完整架构","完全没有关系"],"a":2,"explain":"Attention ⊆ Transformer：Transformer 在 Attention 之外还包含残差、归一化、前馈、位置编码等。","jump":"sec8","jumpLabel":"『以为 Transformer=Attention』那条误区"},{"q":"为什么说 Transformer 比 RNN 快（并行）？","opts":["因为它跳过了很多词","因为它让所有词同时参与计算，不用一个字一个字排队","因为它更短","因为它的层更少"],"a":1,"explain":"RNN 必须按顺序串行处理每个词；Transformer 所有位置并行计算，谁跟谁相关靠注意力自己匹配。","jump":"sec7","jumpLabel":"对比区 RNN vs Transformer"}],"done":"你已经明白大模型的地基长什么样了。但这个『什么都会的模型』只记得训练时的知识——它不知道你公司的最新政策。下一课解决这个问题。","nextLesson":"l-rag"},{"type":"connection","known":["Attention：Q/K/V 加权求和，让词与词互相关注","词是向量，语义可算相似度"],"learned":["Transformer = 多头注意力 + 残差 + 归一化 + 前馈网络的 N 层堆叠","位置编码让模型感知顺序，否则猫追狗 = 狗追猫","GPT 是 Decoder-only，靠预测下一个词长出能力","O(n²) 复杂度是长上下文贵的根源，引出 RAG"],"next":"Transformer 有了，模型『什么都懂但只记得训练时的知识』。下一课我们解决这个关键问题：RAG——怎么让模型在回答前先到你的资料库查资料，从而答出它没学过的私有内容。"}]},"l00-ai-world":{"id":"l00-ai-world","title":"一张图看懂整个 AI 世界","subtitle":"在学任何一个概念之前，先拿到整张地图：你现在站在哪里，接下来要走到哪里。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"15-20 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl","ai-apps","ai-limits"],"prereqLessons":[],"nextLesson":"l01-ai-vs-ml-dl","sections":[{"type":"opening","question":"你每天听到的 ChatGPT、大语言模型（LLM）、Transformer、Agent、RAG……它们到底谁包含谁、谁建在谁之上？如果你现在只能用一句话回答「它们是什么关系」，你会怎么说？","guess":"很多人会脱口而出「都是一回事，就是 AI」。","next":"这节课不教任何公式，只画一张总地图。学完你不仅能说清这些词的关系，还能知道接下来 5 节旗舰课各自站在这张地图的哪个格子里。"},{"type":"why","before":"你在标题、文章、面试里反复遇到 Token、Attention、Transformer、RAG、Agent、Fine-tune……每个词单独看都懂一点，但凑在一起就乱。","problem":"初学者最大的障碍不是「不够努力」，而是没有地图：他不知道现在学的东西将来会连到哪里，于是学一个忘一个，越学越焦虑。","need":"所以第一节课我们不讲任何实现细节，只建立骨架：AI 世界分哪几层、每一层由什么构成、你将来要学的每一块长在哪个位置。地图在手里，后面的路才走得稳。"},{"type":"oneline","text":"AI（人工智能）是整片森林；机器学习是其中『会自己从数据里找规律』的那片林子；深度学习是最能长的那几棵大树；大语言模型（LLM）是最近最抢眼、能和你聊天的那一棵；而 RAG、Agent 这些，是围绕这棵树搭起来的『脚手架』——让树上的果子更好摘。"},{"type":"visual","kind":"ai-world-map","title":"AI 世界全景图","hint":"从最外层的 AI 一路收缩到 LLM，再向外展开 Vision / Speech / Agent / RAG 等应用方向。点击让你看明白的节点，就能往下一层走。"},{"type":"intuition","blocks":[{"k":"用俄罗斯套娃来想","t":"AI 是最大的套娃，机器学习是里面一层，深度学习再里面一层，LLM 是最小最精致的那层。每往里一层，都建立在外层之上——这叫『包含』，不是『并列』。"},{"k":"用搭积木来想","t":"只给你一个 LLM 你只能『聊天』。但当你往它外面搭『检索』（RAG）、『工具调用』（Agent）、『工作流编排』（Workflow）这些积木，你就从『会聊天』升级成『会办事』。产品形态 = 模型 + 一层层积木。"},{"k":"一句话记住主干","t":"AI ⊃ ML ⊃ DeepLearning ⊃ Foundation Model ⊃ LLM。这一个箭头链，就是整张地图的主干，也串起了你即将学的六节课。"}]},{"type":"how","intro":"把 AI 世界拆成「五层结构」与「五大应用方向」，你学完至少知道每块知识的归属，再也不会把它们混为一谈。","steps":[{"in":"第 0 层 · AI（人工智能）","process":"最上层总称：让机器表现出智能的一切技术，包括早期靠人写规则、搜索、专家系统。","out":"范围最大，是『目标』而不是某一门具体技术"},{"in":"第 1 层 · Machine Learning 机器学习","process":"不再靠人写死规则，而是让机器从数据里『自己找规律』，再拿规律去做预测。","out":"监督学习 / 无监督学习 / 强化学习 三大流派"},{"in":"第 2 层 · Deep Learning 深度学习","process":"用『多层神经网络』来自动提取特征，是机器学习的子集，能力更强：不用人手设计特征。","out":"CNN（图像）、RNN/Transformer（序列）、扩散模型（生成）等结构"},{"in":"第 3 层 · Foundation Model 基础模型","process":"在大规模数据上预训练好的『通用大脑』，可以微调或直接复用到很多不同任务。","out":"LLM（语言）、视觉基础模型、多模态基础模型"},{"in":"第 4 层 · LLM 大语言模型","process":"把『预测下一个词』当唯一训练目标，靠海量文本硬学出来的语言模型，意外获得了语言与世界的知识。","out":"ChatGPT、Claude、Gemini 背后的模型本体"},{"in":"围绕 LLM 的『脚手架』与应用架构","process":"光会聊天不够，为了让模型能办成事，在外面叠加外围技术。","out":"Prompt 提示 · RAG 检索增强 · Workflow 工作流 · Agent 智能体 · 多模态"}]},{"type":"realworld","items":[{"name":"ChatGPT","note":"「纯 LLM 对话产品」：你打字，它预测下一段话。它本身不做检索也不调工具，是最纯粹的一层。"},{"name":"Claude / Gemini","note":"同样是 LLM 驱动的对话产品，但在模型能力与对齐上做得不同，代表『同一个塔、不同的果』。"},{"name":"NotebookLM / 企业知识库问答","note":"「LLM + RAG」：你上传私有资料，系统先检索相关片段，再让模型基于这些片段回答，杜绝凭空编造。"},{"name":"Workflow 编排（如 Zapier AI / Coze 工作流）","note":"「LLM + 规则流程」：把『先做A、判断结果再做B』写成固定流水线，模型只负责其中某一环。"},{"name":"Codex / Claude Code","note":"「LLM + Agent 智能体」：不只是回答，还能自主决定『读文件→改代码→跑测试→看报错→再改』，直到把活干完。"},{"name":"Midjourney / Sora","note":"「不是 LLM 的另一棵树」：用扩散模型做图像/视频生成。提醒你 AI 世界不只有语言这一棵大树。"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是「目标——机器有智能」；机器学习是实现它的一种主流手段（用数据学出来）。早期用规则实现的人工智能，不属于机器学习，但仍然属于 AI。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是「从数据学习」；机器学习范围更大（含决策树、SVM 等传统算法），深度学习专指用多层神经网络，能自动提取特征，是机器学习的一个子集。"},{"a":"LLM","b":"Foundation Model","diff":"LLM 是专做语言的基础模型；Foundation Model 是更大的类，还包括视觉、多模态基础模型。LLM ⊂ 基础模型。"},{"a":"RAG","b":"Agent","diff":"RAG 是『给模型外接资料库』的检索增强；Agent 是『让模型自主决策与调用工具』的智能体。两者常配合：Agent 需要信息时用 RAG 检索。它们都不是模型本身，而是脚手架。"},{"a":"模型（Model）","b":"产品（Product）","diff":"模型是被训练出来的『大脑』；产品是把这个大脑装进界面、加上检索/记忆/工具后的完整应用。你用的是产品，不直接是模型。"}]},{"type":"mistakes","items":["把「AI、机器学习、深度学习、LLM」当同义词——它们是一层层包含关系，不是并列。","以为 ChatGPT = 整个 AI。ChatGPT 只是 LLM 的一颗果实；AI 世界还有视觉、语音、生成、机器人、Agent 等一大片。","以为 RAG 和 Agent 是「模型」。它们是在模型外面搭的脚手架/架构，本身没有『大脑』。","以为只有学完高等数学才能开始。第一门旗舰课（Embedding）就能带你把概念走通，数学按「够用」给，不是研究生讲义。","以为 Fine-tuning（微调）和 RAG 是一回事。前者改模型自身权重，后者不改模型、只改给它看的外部资料——它们解决不同问题。"]},{"type":"deep","title":"深入一点：把「领域 / 模型 / 技术 / 应用架构 / 产品形态」五顶帽子分清楚","beginner":["用「帽子」来记：同一个东西，问问题的角度不同，答案就不同。","「这属于哪个**领域**？」—— 问的是地图范围（AI、ML、DL 是领域/学科级）。","「这是个什么**模型**？」—— 问的是被训练出来的产物（LLM、扩散模型、视觉模型是模型级）。","「用了什么**技术/算法**？」—— 问的是怎么做（Attention、Transformer、RAG 检索是技术级）。","「这是什么**应用架构**？」—— 问的是怎么组合（RAG 架构、Agent 循环、Workflow 流水线是架构级）。","「最终做成什么**产品**？」—— 问的是用户能用的东西（ChatGPT、Codex、NotebookLM 是产品级）。"],"advanced":["用一条「从模型到产品」的抽象层次链来定位任何 AI 名词：","「AI 世界 = 领域层（AI⊃ML⊃DL）→ 模型层（Foundation Model→LLM/Diffusion/多模态）→ 技术层（Attention、位置编码、损失函数）→ 架构层（RAG、Agent、Workflow、多智能体协作）→ 产品层（ChatGPT、Claude Code）」。","判断法则：问「它能不能被『训练』出来」？能 → 模型层或更深；问「它是不是一个『零件/接法』」？能 → 技术层或架构层。训练产物是模型，接法是架构。","示例定位：Transformer 是技术层（一种网络结构）；GPT 系列是基于 Transformer 训练出来的模型（模型层）；把 GPT 接上检索= RAG 架构（架构层）；打包成网站= ChatGPT 产品（产品层）。","顺带一个工程事实：你平时说的「大模型」绝大多数指 LLM 或基础模型；而「智能体」「Agent」在业界常被定义为『模型 + 记忆 + 规划 + 工具调用』，是一个架构概念而非单个模型。"]},{"type":"exercise","prompt":"你现在打开了一款「企业知识库问答」App，上传公司政策文件后提了个问题，系统给出的回答里标注了「依据文件第 3 页」。你觉得它最可能是下面哪种组合？","opts":["只有 LLM，全靠模型自己编","LLM + RAG（先检索你的文件，再基于片段回答）","LLM + Agent（让模型自己去改代码）","纯扩散模型"],"a":1,"explain":"回答『依据你上传的文件』并带引用，正是 RAG 的典型特征：先检索相关片段，再让模型基于片段生成答案。","jump":"sec5-step5","jumpLabel":"围绕 LLM 的脚手架（RAG 检索）这一段"},{"type":"check","title":"结课检测：你真的懂这幅地图了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"下面哪条包含关系是正确的？","opts":["AI ⊃ LLM ⊃ Deep Learning ⊃ ML","AI ⊃ ML ⊃ Deep Learning ⊃ LLM","LLM ⊃ AI ⊃ ML ⊃ Deep","Deep Learning ⊃ ML ⊃ AI ⊃ LLM"],"a":1,"explain":"AI 包含机器学习，机器学习包含深度学习，LLM 是深度学习上长出的具体模型。","jump":"sec5-step0","jumpLabel":"五层结构第一步"},{"q":"ChatGPT 最准确地说是下面哪一个？","opts":["一个 Agent 智能体","一个纯 LLM 对话产品","一个 RAG 系统","一个视觉模型"],"a":1,"explain":"ChatGPT 的核心就是大语言模型：输入→预测下一段。RAG/Agent 是对它的增强，而不是它的本质。","jump":"sec5-step4","jumpLabel":"第 4 层 LLM 这一段"},{"q":"「NotebookLM 先查你上传的资料再回答」主要用到了哪项技术？","opts":["RAG 检索增强生成","纯预训练","扩散模型","只靠提示词"],"a":0,"explain":"针对私有资料，RAG 让模型先检索相关片段再回答，这正是 NotebookLM 类产品的核心。","jump":"sec5-step5","jumpLabel":"脚手架之 RAG 这一段"},{"q":"Codex「自己读代码、改代码、跑测试、看报错再重试」的能力，对应哪种架构？","opts":["RAG 检索增强","Agent 智能体循环","纯一次性生成","工作流固定流水线"],"a":1,"explain":"自主决策 + 调用工具 + 根据反馈循环，这正是 Agent 的核心：想→做→看→再想。","jump":"sec5-step5","jumpLabel":"脚手架之 Agent 这一段"},{"q":"「Midjourney 能生成图片」用到的模型，和 ChatGPT 的 LLM 是什么关系？","opts":["同一个模型","都是 LLM","Midjourney 用的是扩散模型，是 AI 世界里另一棵大树","Midjourney 不用 AI"],"a":2,"explain":"图像生成多靠扩散模型（Diffusion），与语言类的 LLM 是并列的不同模型，提醒你 AI 世界不止语言一棵树。","jump":"sec6","jumpLabel":"现实应用里的 Midjourney / Sora"}],"done":"现在你手里有整张地图了。接下来我们要下到模型的正下方——先搞清楚：电脑到底怎么把一句话变成它算得动的『数字』。","nextLesson":"l-embedding"},{"type":"connection","known":["（这是第一节课，还没有前置知识）"],"learned":["AI → ML → DL → Foundation Model → LLM 的主干链条（包含关系）","领域 / 模型 / 技术 / 应用架构 / 产品形态 五顶帽子怎么分","RAG、Agent、Workflow 是围绕 LLM 的脚手架，不是模型","ChatGPT、Claude（LLM产品）、NotebookLM（RAG）、Coze（工作流）、Codex（Agent）、Midjourney（扩散）各代表一类"],"next":"下一课我们钻到模型正下方：Embedding——电脑怎么把『一句话』变成『一串数字』。这是理解 LLM 的第一块砖，也是 RAG、搜索、推荐的地基。"}]},"l01-ai-vs-ml-dl":{"id":"l01-ai-vs-ml-dl","title":"AI / Machine Learning / Deep Learning 到底什么关系","subtitle":"三个天天混着用的词，其实是三层包含关系。把它们理清，你才不会再被『这不是深度学习吗』『这算 AI 吗』这类问题卡住。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl"],"prereqLessons":["l00-ai-world"],"nextLesson":"pl-train-infer","sections":[{"type":"opening","question":"面试、文章、和同行聊天里，你几乎天天听到『AI』『机器学习』『深度学习』这三个词。它们到底是同义词，还是完全不同的东西？下面的说法，哪句最接近事实？","guess":"很多人觉得它们是同一件事的不同叫法，可以随便混用。","next":"上一课你拿到了整张 AI 世界地图。这一课我们只解决一个词根问题：AI、机器学习（ML）、深度学习（DL）谁包含谁。理清这层包含关系后，后面讲到神经网络、大模型时，你就知道它们各自站在哪一层。"},{"type":"why","before":"你读了文章，看到『用机器学习做了个推荐』，又看到『深度学习模型碾压传统算法』，还有『人工智能正在改变世界』。三个词来回出现，你分不清它们是不是一回事。","problem":"如果不理清，你会把它们当成可互换的词。结果就是：该用『AI 这个概念』时却拿『深度学习』去套，理解错位，越学越混乱。更关键的是，它影响了你的地图感——你不知道每一个具体技术在大结构里的归属。","need":"所以我们要把『包含关系』这条线彻底拉直：AI 是最外层的大概念，机器学习是实现 AI 的主流手段，深度学习又是机器学习里最强的一个分支。记住这一个箭头链，比背一百个术语都有用。"},{"type":"oneline","text":"AI（人工智能）是整片森林；机器学习（ML）是森林里『让程序从数据中自己找规律』这一派；深度学习（DL）是这一派里靠『多层神经网络』自动提取特征、效果最强的一支；而大语言模型（LLM）是深度学习在语言上结出的果子。"},{"type":"intuition","blocks":[{"k":"用俄罗斯套娃想","t":"AI 是最外面的大套娃，机器学习是里面一层，深度学习再里面一层。每一个内层都建立在外层之上。『它是 AI 吗？』——所有机器学习、深度学习都属于 AI；但『它是机器学习吗？』——只有 AI 的一部分才是。"},{"k":"用交通工具想","t":"AI＝『交通工具』这个大分类；机器学习＝其中『能自己开的车』；深度学习＝车里面『最豪华、自动驾驶能力最强的那批』。你要去的地方（目标）叫 AI，但真正驱动现在的靠的是深度学习这辆快车。"},{"k":"一句话记住","t":"AI ⊃ ML ⊃ DL。哪个词越大，哪一个就越『含』后面的。说『大模型是深度学习』正确，说『深度学习就是 AI』则太窄。"}]},{"type":"how","intro":"把三层关系拆开看：每一层『是什么、靠什么实现、典型代表是谁』。","steps":[{"in":"第 0 层 · AI 人工智能（最外圈）","process":"让机器表现出智能的一切技术。范围最广，既包括学出来的，也包括早期靠人写规则、专家系统、搜索的『传统 AI』。","out":"AI 是一个『目标 / 领域』，不是某一门固定技术"},{"in":"第 1 层 · 机器学习 ML","process":"AI 的一条主流路径：不再由人写死规则，而是给程序大量数据，让它自己找出规律，再拿规律预测没见过的新数据。","out":"监督学习 / 无监督学习 / 强化学习 三大流派"},{"in":"第 2 层 · 深度学习 DL","process":"机器学习里靠『多层神经网络』的那一支。区别在于：它无需人手设计特征，网络自己逐层提取。数据、算力上去后，效果远超传统 ML。","out":"CNN（图像）、RNN、Transformer、扩散模型等现代结构"},{"in":"果实 · 大语言模型 LLM","process":"把深度学习用在语言上，用『预测下一个词』的目标在海量文字上训练出来的模型。它是当下 AI 浪潮最亮眼的具体成果。","out":"ChatGPT、Claude、Gemini 背后的模型本体"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是目标——机器有智能；ML 是达成目标的主流手段——从数据里学规律。早期用规则实现的人工智能属于 AI、但不属于 ML。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是『从数据学习』；ML 范围更大（含决策树、SVM 等传统算法），DL 专指用多层神经网络，能自动提取特征，是 ML 的子集，也是当下主力。"},{"a":"DL","b":"LLM","diff":"DL 是方法（多层神经网络）；LLM 是用 DL 专门处理语言、以预测下一个词为目标的产物。LLM 是 DL 在语言上的具体应用果实。"},{"a":"传统规则 AI","b":"机器学习","diff":"传统规则 AI 是人手动写 if-else 规则，机器不会自己学；ML 让机器从数据里学规则。前者『别人给孩子吃』，后者『教孩子自己找吃的』。"}]},{"type":"mistakes","items":["把三个词当同义词——它们是包含关系：AI ⊃ ML ⊃ DL。","以为『只要用了 AI 就是深度学习』——很多产品底层还是传统机器学习（决策树、统计方法）。","以为『深度学习之外的东西都不是 AI』——AI 的范围比 DL 大得多。","把『大语言模型』直接等同于『全面工智能』——LLM 只是 AI 世界一小棵树上结的果。","纠结『这到底算不算 AI』这种分类洁癖——关键是理解它在哪一层、解决什么问题，而不是给它贴哪个标签。"]},{"type":"deep","title":"深入一点：为什么近十年忽然『深度学习』最火","beginner":["不是说传统机器学习不好，而是深度学习在『大规模数据 + 强大 GPU』的条件下，能力曲线突然反超。","三点原因：①数据足够多，神经网络学得动；②GPU 让多层网络算得动（训练从几周缩到几小时）；③多层网络能自动学特征，不用人手工设计。","一句话：深度学习强的不是『智能』，是『在足够数据下自动找到规律的能力』。"],"advanced":["技术脉络：2006 年深度信念网络证明深层训练可行 → 2012 年 AlexNet 用 CNN 赢下 ImageNet，深度学习在视觉上引爆 → 2017 年 Transformer 论文出现，注意力机制取代循环结构，为语言大模型铺路 → 2022 年 ChatGPT 把『预测下一个词』放大到规模对话，大众才真正感知到。","一个判断技巧：当文章说『神经网络』『层数』『激活函数』『反向传播』时，多半在讲 DL；说『特征工程』『决策树』『SVM』时，多半是传统 ML。","从 DL 到 LLM 的桥梁就是『词元 + 注意力』：把语言切碎成 token，再用自注意力建模词与词的关系。这将在后文《Tokenization》《Attention》《Transformer》三课展开。"]},{"type":"exercise","prompt":"一位朋友说：『我帮公司做了个深度学习项目，所以我在做人工智能。』这句话的问题在哪？","opts":["完全正确，深度学习就是 AI 的全部","只对一部分：深度学习确实是 AI，但不能反过来说『AI = 深度学习』，AI 的范围大得多","完全错误，深度学习不算 AI","深度学习是机器学习之外的技术，和 AI 无关"],"a":1,"explain":"深度学习是 AI 的子集（AI ⊃ ML ⊃ DL），所以『做深度学习就是在做 AI』正确；但把它当成 AI 的全部就错了，因为 AI 还包括传统 ML、规则系统等许多内容。","jump":"sec5-step0","jumpLabel":"第 0 层 AI 这一段"},{"type":"check","title":"结课检测：三层包含关系你拉直了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"下面哪条包含关系是正确的？","opts":["AI ⊃ ML ⊃ DL","ML ⊃ AI ⊃ DL","DL ⊃ ML ⊃ AI","AI ⊃ DL ⊃ ML"],"a":0,"explain":"AI 是最外层目标，机器学习是其内一层主流手段，深度学习又是机器学习里最强的一个分支。","jump":"sec5-step0","jumpLabel":"三层关系这一段"},{"q":"『决策树 / SVM』这类经典算法，通常归属于哪一层？","opts":["深度学习 DL","传统机器学习 ML（但不一定是 DL）","纯规则 AI（非学习）","大语言模型 LLM"],"a":1,"explain":"决策树、SVM 属于机器学习，但它们不靠多层神经网络，所以不算深度学习，也称不上 DL。","jump":"sec5-step1","jumpLabel":"机器学习这一层"},{"q":"『多层神经网络 + 自动提取特征』，最准确对应的概念是？","opts":["传统规则 AI","深度学习 DL","数据库","网络通信"],"a":1,"explain":"利用多层神经网络、无需人工设计特征自动学习，正是深度学习区别于传统 ML 的核心。","jump":"sec5-step2","jumpLabel":"深度学习这一层"},{"q":"大语言模型（LLM）与深度学习的关系是？","opts":["它们是同一件事的两个名字","LLM 是深度学习在语言上结出的具体果实","LLM 与深度学习毫无关系","LLM 属于传统机器学习"],"a":1,"explain":"LLM 用深度学习的方法专门处理语言，以『预测下一个词』为目标训练出来，是 DL 在语言上的具体应用。","jump":"sec5-step3","jumpLabel":"LLM 这一层"}],"done":"现在 AI、ML、DL、LLM 四者的包含关系你彻底拉直了。可这些高大上的模型到底怎么『学』出来的？下一课我们就回答最根本的一问：训练（Training）和使用（Inference）到底有什么区别。","nextLesson":"pl-train-infer"},{"type":"connection","known":["AI 是包含 ML、DL 的最外层大概念（来自上一课《一张图看懂整个 AI 世界》的地图骨架）"],"learned":["AI ⊃ ML ⊃ DL ⊃ LLM 的清晰包含链","三者的定义、实现手段与典型代表","为什么深度学习在数据与算力充足时成为主力","LLM 是深度学习在语言上的果实"],"next":"下一步我们回答『学习』这件事本身：模型『训练』时和『使用』时，到底发生了什么、有什么本质区别。这是理解一切 AI 应用的前提。","links":[{"href":"#/lesson/l00-ai-world","text":"回看《一张图看懂整个 AI 世界》"},{"href":"#/lesson/l08-neural-network","text":"提前了解《神经网络》一课"}]}]},"l05-gradient-descent":{"id":"l05-gradient-descent","title":"损失函数与梯度下降：模型怎么自己变聪明","subtitle":"训练的核心不是『照抄答案』，而是给错误『打分』，然后沿着『下山最快』的方向一步步调整参数。看懂这一步，你就真懂了 AI 的『学习』。","category":"c03-ml","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["loss","gradient","gradient-descent"],"prereqLessons":["pl-data"],"nextLesson":"l08-neural-network","sections":[{"type":"opening","question":"上一课我们说训练就是『反复调整参数』。可模型该往哪个方向调、调多少？它怎么知道自己『猜错了』？这里有一个非常优雅的核心机制——损失函数 + 梯度下降。","guess":"有人以为训练就是不断『枚举试错』，或模型直接记住正确答案。","next":"这一课我们讲训练最核心的两个概念：损失函数（给错误打分）和梯度下降（沿下山最快的路调整参数）。这是所有深度学习『自带学习』的根本。"},{"type":"why","before":"你想真正理解 AI 怎么『学会』的（而不是只会背结论），于是查『训练』『反向传播』，却看到一堆数学公式，被梯度、导数吓退。","problem":"不理解损失与梯度下降，你就只能把训练当『黑盒』——不知道模型为什么学会、为什么有时候学不会、为什么训练会发散或过拟合。后续看一切『调参』话题都会费劲。","need":"我们把核心讲得足够直观：损失＝错得有多离谱的比分；梯度＝每个旋钮往哪个方向拧能让误差下降最快。有了这两把钥匙，训练不再是黑盒。"},{"type":"oneline","text":"损失函数（Loss）= 给模型当前『错得多离谱』打的一个分数，越小越好；梯度下降（Gradient Descent）= 算出每个参数要让误差下降，应该往哪个方向拧、拧多少，然后沿『下山最快』的方向反复更新，直到误差降不下去。"},{"type":"intuition","blocks":[{"k":"用下山来想","t":"想象你被蒙着眼站在一座山上，目标是最低点（误差最小）。你每走一步就摸摸脚下的坡度（梯度：哪里更陡地往下）。你就朝最陡的下坡方向迈一小步，反复走，就一步步接近山谷最低点。这就是梯度下降。"},{"k":"用射箭来想","t":"损失函数＝你射偏的距离（离靶心多远）。梯度＝『往东偏了，该往西调一点』的修正提示。每一轮你根据偏差方向和大小校正弓，越射越准。"},{"k":"一句话记住","t":"损失＝错得有多远；梯度＝该往哪调、调多少。训练＝沿着『误差下降最快』的方向一次次微调参数，走出一座‘误差之山’。"}]},{"type":"how","intro":"把一次训练迭代（一步学习）拆成四步。","steps":[{"in":"① 前向预测：模型猜一次","process":"喂一批数据，模型按当前参数算出一批预测结果（如：这张图是猫的概率、下一个词是哪个）。","out":"得到模型的『猜测』输出"},{"in":"② 计算损失：给错误打分","process":"拿猜测和真实答案对比，用一个损失函数算出数值：差得多分数高，差得少分数低。这就是 Loss。","out":"一个代表错得多离谱的数值（Loss）"},{"in":"③ 反向计算梯度：找下降方向","process":"用微分/反向传播算出：每个参数向哪个方向微调会让 Loss 变小、大概变小多少。这就是梯度（下山方向）。","out":"每个参数对应的『修正方向 + 幅度』"},{"in":"④ 更新参数：沿梯度走一小步","process":"按学习率（步长）把每个参数往梯度方向调一点。重复 ①②③④ 成千上万次，Loss 逐渐下降。","out":"一轮一轮的微调后，误差越来越小，模型变聪明"}]},{"type":"realworld","items":[{"name":"学习率（Learning Rate）","note":"决定每步走多大。太大容易在山谷两边来回震荡甚至发散；太小走到山谷要很久。调学习率是训练头号工程问题。"},{"name":"为什么训练会『过拟合』","note":"下山下过头，模型把训练数据的噪声也背下来，对没见过的数据反而变差。这需要正则、早停、更多数据来约束。"},{"name":"批量大小（Batch）","note":"一次用多少样本算梯度。太小震荡大、太大太慢。是训练的重要超参数。"},{"name":"为什么有的模型『训练发散』（Loss 变 NaN）","note":"梯度爆炸或学习率过大，参数一步跳得太远，误差爆炸。工程上要加梯度裁剪、合理初始化。"}]},{"type":"compare","pairs":[{"a":"损失函数 Loss","b":"梯度 Gradient","diff":"Loss 是『错得多远』的分数（一个数）；梯度是『该往哪调、调多少』的方向信息。先有 Loss，才有 Gradient。"},{"a":"梯度下降","b":"随机梯度下降 SGD","diff":"梯度下降每步用全部数据算梯度（准但慢）；SGD 每次只用一小批数据算梯度（快但有噪声，实践中更常用）。"},{"a":"学习率大","b":"学习率小","diff":"大步长收敛快但易震荡/发散；小步长稳但慢。要平衡。"},{"a":"训练 Loss","b":"验证 Loss","diff":"训练 Loss 是模型背题目的程度；验证 Loss 是它在没见过的题上的表现。后者才是真正关心的泛化能力。"}]},{"type":"mistakes","items":["以为训练是『背答案』——不，是学规律后用梯度一点点靠近最优参数。","以为『Loss 越低越好到越低就越强』——训练 Loss 降得太低常意味着过拟合，真正看验证 Loss。","以为梯度下降只有一条最优路径——它是启发式最优化，可能卡在局部极小值，且对超参数敏感。","把『梯度』和『参数值』混为一谈——梯度是方向信息，参数才是被更新的值。","以为学习率越大越快——过大会发散，这不是勇气，是翻车。"]},{"type":"deep","title":"深入一点：数学直觉（给愿意往下钻的你）","beginner":["梯度就是『误差对每个参数的偏导数』：把参数稍微动一点点，看 Loss 变多少。","梯度方向是 Loss 上升最快的方向，所以沿它的反方向走，就是下降最快的方向。","更新公式一眼看懂：新参数 = 旧参数 − 学习率 × 梯度。"],"advanced":["优化目标是最小化 L(θ)。更新：θ ← θ − η∇L(θ)。η 是学习率，∇L 是梯度。","深度学习用的多是 Adam 等自适应优化器：为每个参数自动调整学习率，能加速收敛、更稳。","对 LLM，预训练用海量数据做较长时间的大规模梯度下降；微调用小数据小学习率。现代还加入 LoRA 等参数高效方式只更新低秩子空间。","需要警惕的工程陷阱：梯度爆炸/消失（影响深层网络）、学习率 warmup、loss 尺度不一等。"]},{"type":"exercise","prompt":"训练中你看到 Loss 一会儿 4.8、一会儿 4.2、一会儿又 5.1，总体没怎么降。最可能是哪类问题？","opts":["模型已经过拟合了","学习率过大或数据太吵，导致震荡、收敛困难","数据量太多","显卡坏了"],"a":1,"explain":"Loss 来回震荡不下滑，常是学习率过大、批量太小导致的噪声，或需要调整超参数让训练稳定下来。","jump":"sec5-step3","jumpLabel":"更新参数这一步"},{"type":"check","title":"结课检测：损失与梯度下降你懂了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"损失函数（Loss）的作用是？","opts":["给模型的错误打一个分，越小越好","让显卡更热","控制网页颜色","增加参数量"],"a":0,"explain":"Loss 衡量模型预测与真实答案的差距，是训练的‘成绩单’，目标是把它降到尽可能低。","jump":"sec5-step1","jumpLabel":"计算损失这一步"},{"q":"梯度（Gradient）告诉模型什么？","opts":["正确答案本身","每个参数该往哪个方向调能让误差下降","模型的名字","数据的来源"],"a":1,"explain":"梯度是误差对参数的偏导方向信息，模型沿其反方向（下降最快）调整参数。","jump":"sec5-step2","jumpLabel":"反向计算梯度这一步"},{"q":"下面的参数更新思路，哪项正确？","opts":["新参数 = 旧参数 + 学习率 × 梯度（反了）","新参数 = 旧参数 − 学习率 × 梯度","新参数和旧参数无关","只在推理时改参数"],"a":1,"explain":"沿梯度反方向（下降方向）走，所以是减去学习率乘梯度。训练改参数、推理只读。","jump":"sec5-step3","jumpLabel":"更新参数这一步"},{"q":"学习率设得过大，最常见的后果是？","opts":["训练更快且更好","参数一步跳太远，Loss 震荡甚至发散","模型变成大模型","不需要数据了"],"a":1,"explain":"步长过大容易在最优附近来回跳过，甚至梯度爆炸导致 Loss 发散。","jump":"sec6","jumpLabel":"学习率这个现实话题"}],"done":"你知道了训练是怎么『一步步下山』的：给错误打分，沿梯度往误差下降的方向拧参数。下一课我们把镜头拉回模型本身——神经网络到底长什么样、神经元是怎么组成可学习网络的。","nextLesson":"l08-neural-network"},{"type":"connection","known":["数据、模型、参数三件套（上一课）","训练＝反复调整参数"],"learned":["损失函数＝给错误打分，目标是降低","梯度＝哪个方向能最快降低误差","梯度下降＝沿下山最快方向反复微调参数","学习率、过拟合、训练/验证 Loss 这些关键概念"],"next":"梯度下降要在『模型』上发挥作用，可这个模型到底长什么样？下一课《神经网络》：神经元、层、激活函数，理解模型的躯体。","links":[{"href":"#/lesson/pl-data","text":"复习《数据、模型与参数》"},{"href":"#/lesson/l08-neural-network","text":"进入《神经网络》"}]}]},"l08-neural-network":{"id":"l08-neural-network","title":"神经网络：神经元如何组成可学习的网络","subtitle":"深度学习的大脑＝一层层神经元。看懂『神经元怎么算、层怎么堆、信息怎么流动』，你就拥有了理解几乎所有现代模型的基础底盘。","category":"c04-dl","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["neural-network","neuron","layer","activation"],"prereqLessons":["l05-gradient-descent"],"nextLesson":"l09-backprop","sections":[{"type":"opening","question":"『神经网络』你听了无数遍，可它到底长什么样？是不是真和大脑一样？为什么『一堆神经元连起来』就能写诗、识图、跟你聊天？","guess":"有人以为神经网络真的模仿大脑生物结构，或以为它是魔法般‘突然会了’。","next":"这一课我们拆开神经网络的正脸：一个神经元在算什么、一层层怎么叠加、信息怎么从输入流到输出。你会惊讶它其实是由‘乘加 + 激活’这种超级简单的运算堆出来的。"},{"type":"why","before":"你想真正理解深度学习，而不是只会说‘神经网络很厉害’。可一打开网上资料就全是神经元、权重、激活函数、层，不知道它们是怎么组成一个能干活的整体。","problem":"不搞懂神经网络的基本结构，后续看 Attention、Transformer 时会完全跟不上——因为那些都是在这个底盘上加的新花样。","need":"我们先用最直观的方式把神经网络‘长什么样’讲清楚：神经元怎么算、为什么需要非线性（激活）、层越多能学到越抽象的东西。地基打牢，后面全是加分项。"},{"type":"oneline","text":"神经网络＝把大量『简单神经元』分层堆叠：每个神经元把上一层传来的数字加权求和，再过一道非线性激活函数输出；一层接一层，把原始输入逐渐加工成可用的结果。学习就是在训练中不断调这些权重（配合上一课的梯度下降）。"},{"type":"intuition","blocks":[{"k":"用力工流水线来想","t":"神经网络像一条多工序的工厂流水线：原料（像素/文字）进第一道工序，每道工序负责提取一个层面的特征，成品在最后一道工序出来。层数越多，能提取的特征越高维越抽象——从‘一小片边’到‘一只眼睛’到‘一张脸’。"},{"k":"用算盘/计算器来想","t":"每个神经元本质就是一个‘小计算器’：把几个输入各自乘一个权重再加起来，然后决定要不要‘被激活’。网络就是成千上万个小计算器排队协作。"},{"k":"一句话记住","t":"神经元＝乘加 + 激活；层＝一批神经元；深度＝有多少层。层数越多，学到的东西越抽象；而训练负责把这些‘乘加里的权重’调好。"}]},{"type":"how","intro":"从单个神经元讲到整张网络，四步走。","steps":[{"in":"① 单个神经元：一次性小计算","process":"一个神经元接收上一层传来的多个数字，每个数字乘一个权重，求和，再加一个偏置，得到一个‘原始得分’。","out":"一个加权求和后的数字（还没加工完）"},{"in":"② 激活函数：引入非线性","process":"把原始得分过一道激活函数（如 ReLU：负数归零、正数保留）。没有这步，再多层也等价于一层，学不了复杂东西。非线性是关键。","out":"一个‘激活后’的输出值，传给下一层"},{"in":"③ 分层堆叠：从底层特征到高层语义","process":"把很多神经元放一层，再叠很多层。第一层学边缘/局部，中间层学部件/模式，高层学整体语义（对着图那就是‘脸’‘猫’）。","out":"一个能逐层提取特征、层层抽象的网络"},{"in":"④ 输出层 → 预测","process":"最后一层把中间表示转换成最终答案：分类（各类概率）、回归（一个数）、或语言模型的‘下一个词的概率分布’。","out":"可解释成‘预测/概率’的输出"}]},{"type":"realworld","items":[{"name":"全连接层（MLP）","note":"每一层的每个神经元都和上一层所有神经元相连，是最基础的结构。Transformer 里的前馈网络就是一种 MLP。"},{"name":"CNN（卷积网络）","note":"用小的卷积核在图像上滑动提取局部特征，擅长图像。AlexNet 靠它在 2012 年引爆深度学习。"},{"name":"RNN / LSTM（循环网络）","note":"为序列而生，靠循环传递上个时间步的状态。后来在处理长文本上被 Transformer 取代。"},{"name":"Transformer","note":"不用循环，全靠注意力机制并行处理序列，是现在所有大语言模型的地基。后面专门一课讲。"}]},{"type":"compare","pairs":[{"a":"浅层网络","b":"深层网络","diff":"浅层只能学到简单特征与关系；深层能逐步抽象，能力更强，但更难训练、更容易梯度消失，需要残差连接等设计。"},{"a":"线性（无激活）","b":"非线性（有激活）","diff":"没有非线性，再多层叠加仍是线性变换，学不了复杂函数。激活函数带来非线性表达能力。"},{"a":"卷积 CNN","b":"全连接 FC","diff":"CNN 用局部连接+卷积核，参数少、适合图像；FC 全连接，参数多，通用。"},{"a":"RNN","b":"Transformer","diff":"RNN 串行逐步处理，难并行、长距离记忆弱；Transformer 一次看全部、可并行、长距离强，是现代主流。"}]},{"type":"mistakes","items":["以为神经网络真和大脑生物神经元一样——它只是受启发，用的是数学上的‘人工神经元’，比大脑简单得多。","以为层越多一定越好——过深反而不易训练、易过拟合，需要配套技巧（归一化、残差、正则）。","以为激活函数可有可无——少了非线性，层数再多也等价于一层线性，模型能力骤降。","把神经网络的‘参数’和‘权重’搞混——权重就是参数的一种，它们才是训练要调的。","以为网络是‘背下所有答案’——它学的是从输入映射到输出的规律（通过调权重）。"]},{"type":"deep","title":"深入一点：深度为什么有用、又为什么难训练","beginner":["深度带来‘分层表示’：浅层学局部细节，深层学整体概念。这种层级抽象是深度网络能力强的关键。","但也带来训练难点：层太深，梯度在回传时容易‘消失’（乘很多小值趋近 0），最底层学不到东西。","于是有了残差连接（把上一层的值直接跳到后面）等设计来缓解。"],"advanced":["神经网络的万能近似：只要神经元够多、激活非线性，理论上能逼近任意连续函数。","深度网络优于浅层网络在于‘表示效率’：同样的表达能力，深层所需参数往往更少、泛化更好。","现代大模型（Transformer）本质也是神经网络：多头注意力 + 前馈层，只是给它堆了海量参数与数据。","反向传播（下一课）就是在这样的网络上高效算出每一个权重的梯度，让梯度下降在大规模场景下可行。"]},{"type":"exercise","prompt":"一个由多层线性变换（无激活函数）堆叠成的‘网络’，实际效果等价于？","opts":["一个强大的深层网络","一个单层线性模型（因为没有非线性，层数等于白叠）","一定会比深层网络强","无法训练"],"a":1,"explain":"没有非线性激活，多层线性变换可以合并成一个线性变换，等于只有一个线性层，能力有限。非线性是关键。","jump":"sec5-step1","jumpLabel":"激活函数这一步"},{"type":"check","title":"结课检测：神经网络的地基你打牢了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"单个神经元最基本的运算组合是？","opts":["加权求和 + 激活函数","排序 + 去重","加密 + 解密","复制 + 粘贴"],"a":0,"explain":"神经元把输入加权求和得到原始得分，再经激活函数引入非线性。这是最基本的组成单位。","jump":"sec5-step0","jumpLabel":"单个神经元这一步"},{"q":"为什么神经网络需要非线性的激活函数？","opts":["为了更美观","没有非线性，多层也等价于一层线性变换，学不了复杂规律","为了增加参数数量","因为 CPU 喜欢"],"a":1,"explain":"非线性让网络能逼近复杂函数；没有它，多层网络被压缩成一层，表达能力大跌。","jump":"sec5-step1","jumpLabel":"激活函数这一步"},{"q":"『深度网络善于提取越来越抽象的特征』，这个抽象层次受益于？","opts":["只有一层","层层堆叠、逐层抽象","加越多噪声越好","不训练"],"a":1,"explain":"多层结构让浅层学细节、深层学整体语义，形成层级抽象，是深度的价值。","jump":"sec5-step2","jumpLabel":"分层堆叠这一步"},{"q":"神经网络训练时要调的主要是？","opts":["每层的神经元数量结构","连接上的权重（参数）","用户的界面","网络的波长"],"a":1,"explain":"结构（层数、神经元数）通常在训练前定好；训练反复调整的是连接权重这些参数（配合梯度下降）。","jump":"sec6","jumpLabel":"全连接层这个话题"}],"done":"你认识了神经网络的躯体：神经元加权求和 + 激活，分层堆叠提取特征。那训练时，误差到底是怎么‘传回去’改每一层权重的？下一课《反向传播》揭晓。","nextLesson":"l09-backprop"},{"type":"connection","known":["梯度下降＝沿误差下降方向调整参数（上一课）"],"learned":["神经元＝加权求和 + 激活函数","层、深度、非线性为什么关键","CNN / RNN / Transformer 各自擅长的场景","网络通过对大量权重调参来学习"],"next":"误差要传回每一层去改权重的那个高效方法，就是下一课的核心。准备好了吗？《反向传播：误差如何传回去改参数》。","links":[{"href":"#/lesson/l05-gradient-descent","text":"复习《损失函数与梯度下降》"},{"href":"#/lesson/l09-backprop","text":"进入《反向传播》"}]}]},"l09-backprop":{"id":"l09-backprop","title":"反向传播：误差如何传回去改参数","subtitle":"深度网络有几亿参数，梯度下降却要算出每一个该往哪调。反向传播就是那个能在一次计算里，高效把所有梯度算出来的巧妙方法。","category":"c04-dl","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["backpropagation","gradient","chain-rule"],"prereqLessons":["l08-neural-network","l05-gradient-descent"],"nextLesson":"l11-tokenization","sections":[{"type":"opening","question":"一个 70B 参数的大模型，训练时要为每个参数算出‘该往哪调、调多少’。如果一个个算，几辈子都算不完。可训练只花几个星期就完成了——靠的是反向传播这个精巧机制。它是怎么做到的？","guess":"有人以为训练是‘挨个试’每个参数，或以为靠的是超级电脑大力出奇迹。","next":"这一课讲反向传播：误差如何从输出端‘倒着传回去’，用一条链式法则，一次性算出所有参数该调整的方向与幅度。看懂它，训练不再神秘。"},{"type":"why","before":"你接受了‘训练要调几亿个参数’这个设定，但马上困惑：神经网络的每层都互相影响，怎么知道到底是哪一层、哪个权重该为错误负责？","problem":"如果不理解反向传播，你会觉得大规模训练是魔法；也无法理解为什么深度学习速度这么快、为什么需要特殊硬件（GPU）、为什么梯度会‘消失’。","need":"反向传播把‘如何高效地给每个参数下发修正指令’这件事讲透了：从输出端倒推，每层把自己应负的责任传给上一层。这是理解训练提速、梯度消失、以及对 Transformer 训练的一切认知的钥匙。"},{"type":"oneline","text":"反向传播 = 先从输出端算出‘错得有多远’，再沿着计算的反方向，用链式法则把这份‘责任’逐层传回每一层的每个权重，一次算出所有梯度，让梯度下降可以批量更新整个网络。"},{"type":"intuition","blocks":[{"k":"用传话游戏来想","t":"信息正向往前传（输入→输出），误差反向往回传（输出→输入）。就像把你每一句话造成的最终偏差，逆着报给每一位讲话的人，告诉他该改多少。"},{"k":"用差评溯源来想","t":"一道菜难吃（大 Loss），要找到是哪个厨师、哪道工序的问题。你从成品倒着往回查：出锅太咸可能是调味这步，而调味又是前面采购/配比叠加的结果。反向传播就是这样从输出端把责任一路分派回每一层。"},{"k":"一句话记住","t":"正向传信息，反向传误差。反向传播用链式法则在一次回传里同时算出上亿个梯度，让深度学习训练成为可能。"}]},{"type":"how","intro":"把反向传播拆成一次‘四步回传’。","steps":[{"in":"① 正向算出误差","process":"网络前向算一遍，得到输出，与真实答案比较，得到 Loss（上一课已讲）。","out":"一个总误差数值"},{"in":"② 从最后一层往回，算‘谁的责任’","process":"从输出层开始，问：每个神经元的输出变化一点，Loss 变化多少？这就是梯度。","out":"最外层每个参数的梯度"},{"in":"③ 用链式法则逐层回传","process":"靠链式法则，把上一层的梯度乘上本层的局部导数，就得到更前一层的梯度。一路从输出传到输入，每一层都拿到自己的‘修正指令’。","out":"每一层每个权重都得到一个梯度"},{"in":"④ 汇总更新，再来一轮","process":"把所有层的梯度汇总，沿梯度反方向更新全部参数（梯度下降）。然后对下一批数据再来一轮。","out":"一次更新完成，误差整体下降一点"}]},{"type":"realworld","items":[{"name":"为什么需要 GPU","note":"反向传播涉及大量矩阵乘法和链式求导，GPU 能上千核并行，把训练从‘不可行’变成‘几周完成’。这是深度学习兴起的关键硬件。"},{"name":"梯度消失 / 梯度爆炸","note":"层太深时，梯度一层层相乘可能越来越小（消失）或爆炸。反向传播因此难以训练极深网络，催生了残差连接、归一化等设计。"},{"name":"自动微分框架（PyTorch / TensorFlow）","note":"你把网络搭好、写个 Loss，框架会自动帮你做反向传播求梯度。平时训练根本不手写链式法则。"},{"name":"大模型训练同理","note":"Transformer、GPT 的训练底层仍然是反向传播 + 梯度下降，规模放大而已。理解它，你就懂整个深度学习训练的统一范式。"}]},{"type":"compare","pairs":[{"a":"前向传播","b":"反向传播","diff":"前向：输入 → 输出，用于给出预测；反向：输出误差 → 层层回传梯度，用于更新参数。推理只用前向，训练两者都用。"},{"a":"数值求导（逐个试）","b":"反向传播（链式一次算完）","diff":"数值求导每个参数试一下、极慢；反向传播靠链式法则一次回传算完全部梯度，快几个量级。"},{"a":"局部梯度","b":"全局梯度","diff":"局部是单步的输出对输入的变化率；全局经链式法则把路径上所有局部梯度连起来，才得到最终要用的梯度。"},{"a":"训练 Loss","b":"测试表现","diff":"反向传播降的是训练 Loss；真正目标是让验证/测试也变好（泛化），二者并不总一致。"}]},{"type":"mistakes","items":["以为反向传播是一种‘独立的训练算法’——它只是高效算梯度的办法，配合梯度下降做更新。","以为反向传播会‘改变数据’——它改的是参数，数据只是被读取。","以为每次更新‘重算一遍整个网络’——它就是一次前向加一次反向后向，是训练一轮的标准动作。","把链式法则当作负担——它恰恰是把‘上亿次求导’压缩成一次回传的功臣。","以为推理阶段也在反向传播——推理只做前向，反向传播只在训练阶段发生。"]},{"type":"deep","title":"深入一点：链式法则为什么能一次算完所有梯度","beginner":["想象很多齿轮咬合在一起，转动第一个会带动一系列变化。链式法则就是：要知道第一个变化对最后结果影响多大，把每一段齿轮的传动比连乘起来。","反向传播正因为是‘倒着’算，每一层的中间结果能复用给前一层，所以只回传一次就拿到所有梯度。","这就是为什么训练深度网络是可行的：代价只是一次前向 + 一次反向后向的两次‘完整扫过’。"],"advanced":["数学上：∂L/∂θ 通过链式法则逐层展开，如 ∂L/∂W² = ∂L/∂ŷ · ∂ŷ/∂h² · ∂h²/∂W²，其中 ∂L/∂h 从上一层传下来被复用。","反向传播的本质是‘反向模式的自动微分’，与机器学习框架的自动微分是同一套东西。","内存成本：正向要保存每层的中间激活供反向使用，所以训练显存常是推理的好几倍——这也是为什么训练和部署对显存要求差别巨大。","工程技巧：混合精度、梯度累加、梯度裁剪、残差与归一化，都是为了在反向传播时保持数值稳定、让梯度健康流动。"]},{"type":"exercise","prompt":"为什么说反向传播能在‘一次回传’里算出所有参数的梯度，而不是一个个试？","opts":["因为它用了链式法则，把中间结果逐层复用给前一层","因为它只更新一个参数","因为它不计算梯度，靠猜","因为反向传播其实是推理阶段做的事"],"a":0,"explain":"反向传播从输出端倒推，每一层的中间结果可被前一层复用，所以沿链式法则一次回传就获得全部梯度。","jump":"sec5-step2","jumpLabel":"链式法则逐层回传这一步"},{"type":"check","title":"结课检测：反向传播你弄懂了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"反向传播是在哪个阶段发生的？","opts":["只有在推理时","只在训练阶段，用来算梯度","随时都在发生","只在上线后"],"a":1,"explain":"反向传播只在训练时用（算梯度供梯度下降），推理阶段只做前向传播。","jump":"sec5-step0","jumpLabel":"正向算误差这一步"},{"q":"反向传播高效的关键在于？","opts":["暴力逐个试参数","链式法则把中间结果复用、一次回传算全部梯度","不计算梯度","只算一个神经元"],"a":1,"explain":"链式法则＋逐层复用让一次反向回传就能得到所有参数的梯度，从而高效。","jump":"sec5-step2","jumpLabel":"链式法则逐层回传这一步"},{"q":"『梯度消失』问题主要出现在？","opts":["只有一层的网络","层太深、梯度逐层相乘越来越小","训练数据太少","没有激活函数"],"a":1,"explain":"层数过多时梯度经链式反向往回传越乘越小，导致深层最底层几乎学不到东西——这就是梯度消失。","jump":"sec6","jumpLabel":"梯度消失这个现实话题"},{"q":"训练时为什么显存占用往往远高于推理？","opts":["因为屏幕更亮","正向要保存各层中间激活供反向使用","因为数据更大","因为反向传播用不了串行"],"a":1,"explain":"反向传播需要正向阶段的中间激活，这些要存起来，所以训练显存需求远高于只做前向的推理。","jump":"sec7","jumpLabel":"内存成本这一段"}],"done":"你知道了误差是怎么‘倒着传回去’高效改每一层参数的。至此我们讲完了模型的学习机制。下一大步：这些原理在语言模型上怎么落地？先从最底层的『切词』开始——Tokenization。","nextLesson":"l11-tokenization"},{"type":"connection","known":["神经网络的结构（一层层神经元）","梯度下降＝沿误差下降方向调参数"],"learned":["反向传播＝误差从输出端倒着传回每一层","链式法则让一次回传算完所有梯度","为什么大规模训练可行、为什么需要 GPU","梯度消失/爆炸、训练显存为何更大"],"next":"模型的‘通用学习引擎’讲完了。现在进入语言的世界：文字是怎么被喂进模型、变成数字的？下一课《Tokenization》。","links":[{"href":"#/lesson/l08-neural-network","text":"复习《神经网络》"},{"href":"#/lesson/l11-tokenization","text":"进入《Tokenization》"}]}]},"l11-tokenization":{"id":"l11-tokenization","title":"Tokenization：大模型是怎么『读』文字的","subtitle":"模型不直接‘看字’，而是先把文字切成一小块一小块的 Token，再变成数字。理解了 Token，你就理解了计费、长度限制、以及为什么某些词会被‘拆开’。","category":"c05-llm","chapterTitle":"第三章 · 语言进入模型","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["tokenization","token","bpe"],"prereqLessons":["l09-backprop"],"nextLesson":"l-embedding","sections":[{"type":"opening","question":"你经常看到『这个模型上下文 128K』『这次对话用了 3 万个 token』。Token 到底是什么？为什么不是按‘字’或‘词’计？模型到底是怎么把整段中文读进去的？","guess":"有人以为 token 就是字，或者以为模型直接读整个单词。","next":"这一课讲 Tokenization——把文字切成基本面片（Token），并把它变成模型能算的数字的前半段（后半段是下一课的 Embedding）。这一课你看懂『切词』。"},{"type":"why","before":"你想弄懂大模型到底在‘读’什么，但看到‘token’‘BPE’‘词表’这些词就头大，甚至搞不清 token 和字、词的区别。","problem":"不理解 Tokenization，你就看不懂计费为什么按 token、为什么输入太长会被截断、为什么个别词会被拆得‘很怪’，以及为什么不同分词器能力差别这么大。","need":"我们把‘切词’这件事讲透：先切成 Token，再查词表变数字。基础知识一到手，计费、上下文、词表这些概念全部能对号入座。"},{"type":"oneline","text":"Tokenization = 把一段文字按词表切成一连串 Token（大部分 Token 是常见词或词的一小段），再为每个 Token 分配一个编号；模型读的是这一串编号。Token 通常不等于“字”，一个英文单词多被切成 1~2 个 token。"},{"type":"intuition","blocks":[{"k":"用超市小票来想","t":"词表＝超市商品的条码目录；每件商品（常见词/词组）有固定条码。文字就是选购清单，Tokenizer 把清单拆成一件件能扫的商品（Token），每个扫出一个条码号。模型只见条码，不见商品。"},{"k":"用给单词编学号来想","t":"你给全班每个同学发学号，老师点名说学号而不是名字。Token 就是‘语言的学号’：把海量语言变成有限的一本学号册（词表），每个词/词片对应一个编号。"},{"k":"一句话记住","t":"Token 是模型能读的最小语言单位（常见词或词的一小段），每个 token 有编号。Token 数量≈你对模型说的话的‘字数账单’。"}]},{"type":"how","intro":"把一段文字从‘人看的’变成‘模型算的’，四步。","steps":[{"in":"① 准备词表（Vocabulary）","process":"训练前统计海量语料，用算法（如 BPE）找出最常用的一批‘词/词片’，编成词表（如 5 万~20 万个 token）。","out":"一本固定的‘条码目录’（词表）"},{"in":"② 切分（Tokenize）","process":"把输入文字按词表切成一连串 token。常见词整词成一个 token；生僻、低频的长词会被切成一两段。","out":"一串 token 编号"},{"in":"③ 变数字（映射到索引）","process":"每个 token 查它在词表里的位置，输出一个整数编号。这串整数就是模型真正‘看到’的输入。","out":"一串数字索引（模型输入）"},{"in":"④ 进入 Embedding（下一课）","process":"每个编号再被映射成一个稠密向量（Embedding），进入神经网络。注意：token 是‘编号’，向量是那棵树的下一层。","out":"可被神经网络计算的高维向量序列"}]},{"type":"realworld","items":[{"name":"为什么按 Token 计费","note":"模型的计算量正比于 token 数量——输入、输出都要为每个 token 过一次计算，所以 API 按 token 计费。"},{"name":"为什么中文更‘烧’ token","note":"中文字符一般每个字约占 1~1.5 个 token，英文常见的 1 个词常只占 1 个 token 左右。同样‘一段话’，中英 token 数差别明显。"},{"name":"为什么输入太长会被截断","note":"模型有上下文长度上限（如 128K token）。超出部分会被丢掉或报错，所以长文档要先剪裁。"},{"name":"为什么有的词被拆得奇怪","note":"词表有限，低频长词只能被切成几段。你看到 tokenizer 演示里把长词拆开，是正常操作。"}]},{"type":"compare","pairs":[{"a":"字（Character）","b":"Token","diff":"字是按书写单元；Token 是模型的分词单元，一个 token 常等于一个词或词的一部分，跟字不一一对应。"},{"a":"词（Word）","b":"Token","diff":"常见词一个词≈一个 token；但生僻词可能切成一两个 token 片段，tokenizer 不保证按词切。"},{"a":"Token 编号","b":"Embedding 向量","diff":"编号是‘这是谁’；Embedding 是把这个 token 变成一个携带语义的向量（下一课讲）。编号在前面，向量在后面。"},{"a":"不同模型词表","b":"同一模型词表","diff":"不同分词器/模型的词表不同，同一个词在不同模型的 token 数可能不同；这也是跨模型比较长度时要小心的点。"}]},{"type":"mistakes","items":["以为 token = 字数或单个字——一个 token 常是一词或词的一部分，中文约一字多 token。","以为 token 就是向量——token 是先编号，向量是下一层（Embedding）。","以为所有模型分词方式一样——不同模型词表和切分差异很大。","以为加长输入不花钱——输入要按 token 计费，上下文越长越贵。","给模型喂’整本小说‘——超出上下文窗口会被截断，要靠检索/摘要后再喂。"]},{"type":"deep","title":"深入一点：BPE 到底怎么切词（直观版）","beginner":["BPE（Byte Pair Encoding）思路：先把文字拆成最细单位，再反复把‘出现次数最多的相邻对’合并成一个新 token，直到词汇表够大。","结果：高频常见词是整词 token，低频长词被切成若干常用片段组合。","好处：既覆盖常见词，又能拼出任意新词（不生僻词就拼接），内存与效率平衡。"],"advanced":["更现代的有 SentencePiece / tiktoken 等，支持不依赖空格的中文、日文切分，并常对字节级做回退保证任何输入都可表达。","词表规模是权衡：太大则嵌入矩阵大、训练/部署内存高；太小则文本被切得更碎、每句 token 数变多。","指令/特殊 token（如 \u003c|start|>、\u003ceos>）也在词表里，模型输出时也会生成这些控制 token。","工程：API 的 max_tokens、上下文窗口、计费都与 tokenizer 强绑定，读文档时先看它用哪种 tokenizer。"]},{"type":"exercise","prompt":"你调用一个 LLM API，回答收到一本 200 页的小说说‘超长’。为什么？","opts":["小说太‘重’，服务器磁盘满了","文本 token 数超过了模型的上下文窗口上限，被截断或报错","小说是中文所以坏了","token 与长度无关"],"a":1,"explain":"模型能读的 token 总量有上限（上下文窗口）。200 页小说 token 数超限，所以被拒绝/截断。","jump":"sec5-step2","jumpLabel":"切分这一步"},{"type":"check","title":"结课检测：Token 你切明白了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"Token 最准确的理解是？","opts":["一个汉字或英文字母","模型能读的最小语言单位（常见词或词的一部分）","一个句子","一张图片"],"a":1,"explain":"Token 是分词后的单元，通常是常见词或词的一部分；不是字也不是句子。","jump":"sec5-step1","jumpLabel":"准备词表这一步"},{"q":"一段英文通常比同样内容的中文 token 数？","opts":["中文每字约占 1~1.5 token，英文常见 1 个词约 1 token，因此同样内容中英 token 数不同","完全一样","英文一定少","中文一定少"],"a":0,"explain":"不同语言的 token 化效率不同，同样语义中英所需 token 数有差别，这也影响计费与上下文占用。","jump":"sec6","jumpLabel":"中文更烧 token 这个点"},{"q":"模型计费为什么按 token？","opts":["因为 token 比较好看","模型计算量正比于 token 数，输入输出都按 token 消耗算力与成本","与算力无关，只是习惯","只有输出按 token"],"a":1,"explain":"每个 token 都要经过模型计算，所以输入输出都按 token 计费。上下文越长成本越高。","jump":"sec5-step3","jumpLabel":"进入 Embedding 这一步"},{"q":"Token 编号和 Embedding 向量的关系是？","opts":["二者是同一个东西","token 先编号，再映射成向量（Embedding），是两步","embedding 在 token 前面","没有关系"],"a":1,"explain":"先切词得到 token 编号，再把编号映射成稠密向量（Embedding）进入网络。编号是第一步，向量是第二层。","jump":"sec5-step3","jumpLabel":"进入 Embedding 这一步"}],"done":"文字被切成了 token 编号。可编号只是‘学号’，怎么变成‘有语义的数字’？下一课《Embedding》——把词变成电脑能懂、能算相似度的向量。","nextLesson":"l-embedding"},{"type":"connection","known":["神经网络只能处理数字（前面几课）"],"learned":["Token = 模型能读的最小语言单位","词表 + 切分 → token 编号","计费、上下文窗口、中文 token 化差异","BPE / SentencePiece 的思路"],"next":"拿到了 token 编号，下一课让它们‘变得有意义’：《Embedding》教你如何把每个 token 变成携带语义、能算相似度的向量。","links":[{"href":"#/lesson/l-embedding","text":"进入《Embedding》"},{"href":"#/lesson/l12-context-window","text":"相关：《上下文窗口与推理》"}]}]},"l12-context-window":{"id":"l12-context-window","title":"上下文窗口与推理：模型一次能『看见』多少","subtitle":"模型不是全知全能的——它一次只能‘看见’上下文窗口里的那点内容。搞懂窗口、记忆与推理，你就明白了为什么模型‘记不住上句’、以及长对话为什么会『健忘』。","category":"c05-llm","chapterTitle":"第三章 · 语言进入模型","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["context-window","inference","token"],"prereqLessons":["l11-tokenization"],"nextLesson":"pl-prompt","sections":[{"type":"opening","question":"你问模型‘还记得我们刚才说的那件事吗’，它却像失忆。可它明明能把长文档读得很好。这种‘时而记得、时而忘记’是怎么回事？关键就在‘上下文窗口’。","guess":"有人以为模型像人一样有持久记忆，或者把所有历史都一直记着。","next":"这一课讲上下文窗口（一次能读多少 token）、以及推理时模型怎么用它。你会明白：模型的‘记忆’不是永久的，而是每次只装进窗口里的内容。"},{"type":"why","before":"你想让模型处理长文档、维持长对话，可它总是‘忘’前文，或说‘超出长度’。你需要知道模型的看得见范围到底由什么决定。","problem":"不理解上下文窗口，你会误以为模型‘记性差是 bug’，或把太长内容硬塞进去导致被截断、变慢、变贵。","need":"我们把窗口和记忆讲清楚：模型每一轮都只看窗口内 token，历史要么‘还装得下’、要么被截断或靠摘要/检索补充。这是产品设计里管理长上下文的必修课。"},{"type":"oneline","text":"上下文窗口 = 模型处理一次输入时能同时‘看见’的 token 总量上限（如 8K / 128K）。模型没有永久记忆：每次回答都只基于【当前提问 + 窗口里装得下的前文】来推理；超出的部分会被忽略或截断。"},{"type":"intuition","blocks":[{"k":"用餐桌来想","t":"上下文窗口＝一张固定的餐桌，一次只能摆下这么多菜（token）。你点的菜超过桌面，就只能摆一部分，多余的放不下（被截断/挤掉）。想让模型‘看见’更多前文，就得在桌面腾位置。"},{"k":"用近视眼来想","t":"模型像只能看清眼前一页的近视读者：它‘当下’能读到的就是窗口内这一页（token）。你翻页太快、或书太长，它就只能看到最近一页，前面就模糊/记不住了。"},{"k":"一句话记住","t":"窗口决定‘这一次能看多少’；推理时模型只用窗口内信息作答。管理好窗口＝控制成本、长度与质量。"}]},{"type":"how","intro":"把‘一次推理’如何用上下文窗口拆开。","steps":[{"in":"① 组装输入：系统提示 + 历史对话 + 当前问题","process":"把要模型‘看到’的内容（系统指令、历史轮次、当前提问）全部转成 token，拼在一起。","out":"一串待处理的 token"},{"in":"② 检查是否超窗：超出则截断/丢弃","process":"如果这串 token 超过上下文窗口，就要截断——通常去掉最早的部分（把最旧历史丢掉）或报错。","out":"窗口内的 token 序列（旧的被挤掉）"},{"in":"③ 模型基于窗口推理：只看眼前这些","process":"模型对窗口内 token 做前向计算，生成输出。它看到的‘世界’仅限于窗口内的内容。","out":"一个基于窗口内容的回答"},{"in":"④ 输出也占窗口：新一轮把回答加进历史","process":"新生成的回答也消耗 token，下一轮会把它并进历史一起送入窗口。窗口放不下时，最老的内容再次被挤掉。","out":"对话一轮轮推进，历史越久越可能被挤走"}]},{"type":"realworld","items":[{"name":"系统提示（System Prompt）","note":"放在窗口最前面的‘设定’，指导模型身份与行为。它一直占用窗口空间，越长越‘挤占’可用的对话空间。"},{"name":"长对话为什么会‘忘’","note":"窗口有限，塞满了就从最早的开始丢。所以你说‘刚才那事’时，如果它早已被挤出窗口，模型就‘失忆’了。"},{"name":"RAG / 摘要来救场","note":"为了解决窗口有限，常用检索增强（把相关资料塞进窗口）或把历史先摘要再放进去，让模型‘看到’最关键的内容。"},{"name":"为什么窗口越大越贵","note":"窗口越大，每次处理 token 越多，计算和成本越高，延迟也越高。所以要在‘装得下’和‘别太贵’之间权衡。"}]},{"type":"compare","pairs":[{"a":"上下文窗口","b":"长期记忆","diff":"窗口是一次处理能看到的上限，用完即丢；长期记忆（如数据库/向量库）是把历史存在外部，需要时再取回塞进窗口。"},{"a":"窗口大","b":"窗口小","diff":"大窗口能装更多历史、处理长文档，但更贵更慢；小窗口便宜快，但容易丢失远历史。"},{"a":"截断最老","b":"截断最新","diff":"为保住当前问题和关键指令，通常优先丢最早的旧历史；但设计截断策略是产品细节。"},{"a":"窗口内的 token","b":"窗口外的内容","diff":"窗口内模型能‘看到’，窗口外对本次推理透明。管理好‘哪些进窗口’是做好 AI 应用的核心。"}]},{"type":"mistakes","items":["以为模型有永久记忆——它每轮只看窗口内内容，不主动记到外部。","把超长内容硬塞——会截断或报错、变贵变慢，应该先摘要/检索。","以为窗口越大越好——越大越贵越慢，够用就好。","忽略系统提示占用——过长的 system prompt 会挤占对话空间。","以为‘上轮内容必定还在窗口’——长对话久了旧内容会被挤出。"]},{"type":"deep","title":"深入一点：怎么把‘再多的历史’塞进有限窗口","beginner":["三个常用办法：①截断（只留最近）；②摘要（把旧历史浓缩成几句再放进去）；③检索（RAG，只把相关的片段取回）。","这样有限窗口能处理远超其长度的内容——不是全看，而是挑重点看。","本质：把‘无限的过去’压缩成‘有限但有信息量’的内容。"],"advanced":["KV 缓存：推理时为每个历史 token 缓存注意力 Key/Value，新轮次只需对新 token 计算，从而复用历史、提速。缓存也占用显存，受窗口与批大小影响。","窗口的‘有效长度’与注意力机制相关：超长上下文下模型对窗口中部的内容注意力会衰减，所以不是窗口越大‘有效信息’就越多。","工程：滑动窗口、压缩记忆、多轮摘要、RAG 是处理长上下文的四大主流手段；商用 API 要对 max_tokens、上下文上限、成本三者一起规划。"]},{"type":"exercise","prompt":"你的 AI 助手很奇怪：昨天聊了 500 条，今天一问‘咱昨天说的方案是啥’，它答不上来。为什么？","opts":["它丢了硬盘","500 条历史远超上下文窗口，最早的早已被挤出，今天只剩窗口内的内容","它故意装傻","因为模型只能记住今天的话"],"a":1,"explain":"模型无永久记忆，每轮只看窗口内 token。昨天 500 条早已超出窗口被挤掉，所以它‘忘’了——除非你用摘要或检索把关键内容放回窗口。","jump":"sec5-step3","jumpLabel":"模型基于窗口推理这一步"},{"type":"check","title":"结课检测：上下文窗口你懂了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"上下文窗口指的是？","opts":["模型一次能同时看到的 token 量上限","浏览器窗口大小","训练数据的来源","硬盘剩余空间"],"a":0,"explain":"上下文窗口是模型一次处理时能‘看见’的 token 总量上限，决定它能读到多少前文。","jump":"sec5-step0","jumpLabel":"组装输入这一步"},{"q":"输入超过上下文窗口时，最常发生的是？","opts":["模型偷偷多学一点","截断（通常丢最早的历史）或报错","自动扩容到无限","毫无影响"],"a":1,"explain":"超窗后通常从最早部分开始截断，或直接报错；不会无限扩容。","jump":"sec5-step1","jumpLabel":"检查是否超窗这一步"},{"q":"模型为什么‘记不住’很久以前的对话？","opts":["没有永久记忆，长对话旧内容会被挤出窗口","因为对话太长会伤显卡","模型只记一天","因为没人提醒它"],"a":0,"explain":"模型每轮只基于窗口内 token 作答，旧历史放不下就被挤掉，所以会‘健忘’。","jump":"sec5-step3","jumpLabel":"模型基于窗口推理这一步"},{"q":"处理远超窗口的长文档，常用哪种做法？","opts":["整本硬塞，靠运气","先切块/检索（RAG）把最相关的部分放进窗口","让模型用放大镜","把窗口变小"],"a":1,"explain":"用切块检索（RAG）或摘要，把关键内容装进有限窗口，是处理超长内容的主流手段。","jump":"sec8","jumpLabel":"长对话救场这一段"}],"done":"你明白了窗口的边界与记忆的关系。那怎么把‘想表达的东西’在有限窗口里说得最清楚？下一课《Prompt 与上下文》——怎么和模型说清楚。","nextLesson":"pl-prompt"},{"type":"connection","known":["Token 是计费与长度的基本单位（上一课）"],"learned":["上下文窗口 = 一次能看到的 token 上限","模型无永久记忆，只看窗口内","长对话为何会‘忘’、如何用摘要/检索救场","窗口越大越贵、KV 缓存等工程细节"],"next":"窗口里装什么是你说了算的。下一课《Prompt 与上下文》：如何把提示词组织好，让模型在窗口里看到最有用的信息。","links":[{"href":"#/lesson/l11-tokenization","text":"复习《Tokenization》"},{"href":"#/lesson/pl-prompt","text":"进入《Prompt 与上下文》"}]}]},"l18-vibe-coding":{"id":"l18-vibe-coding","title":"Vibe Coding 入门：用 AI 直接做出产品","subtitle":"十八节课的终点，也是‘你真的能做出东西’的起点。Vibe Coding 就是：把 AI 当结对程序员，用‘先跑起来、边做边改’的节奏，从零做出一个能上线的产品。","category":"c11-ai-coding","chapterTitle":"第五章 · 让 AI 干活","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["vibe-coding","ai-coding","product-building"],"prereqLessons":["l22-ai-coding"],"nextLesson":"v01-web","sections":[{"type":"opening","question":"你把 AI 的原理、模型、Agent、AI 编程都学了一遍。现在只剩下最后一个问题：我到底怎么靠 AI，做出一个真正能给别人用的产品？","guess":"有人以为要做产品必须先写几年代码，或以为‘让 AI 全自动’就能直接上线。","next":"这一课收官：Vibe Coding 方法学——从想法到上线的五步节奏，以及它与前 17 课的知识怎么连成一条线。学完这课，你就可以直接进入 Vibe 路径，一步步动手了。"},{"type":"why","before":"你懂了很多概念，却感到‘知识到产品’之间有道坎：真上手做，不知道从哪里开始、怎么保证不翻车。","problem":"只要动手就迷茫，往往是缺一套‘从 0 到 1 的通用节奏’——不是缺知识，是缺流程。","need":"Vibe Coding 给了你一套可重复的流程：小步快跑、AI 写我审、先跑通再打磨、随时能回退。把前 17 课的知识装进这条流水线里，知识就开始变现。"},{"type":"oneline","text":"Vibe Coding = 用 AI 当结对程序员，以‘提出想法 → 让 AI 搭建 → 立刻跑起来 → 边用边改 → 测试收尾 → 部署上线’的高频小步节奏做产品；你负责方向、判断与验收，AI 负责快速产出与迭代。"},{"type":"intuition","blocks":[{"k":"用做饭来想","t":"传统开发像按菜谱做满汉全席：先备齐所有料、严格按步骤，做完才能吃。Vibe Coding 像‘边炒边尝’：先做最核心的一道菜，尝一口，再加料调整，食物永远在‘能吃’状态。"},{"k":"用盖房子要图纸来想","t":"即使最快的施工（AI），也需要一张图纸（你的需求与边界）。你的‘产品感’就是图纸；AI 的速度再快，没有图纸就只会到处乱建。"},{"k":"一句话记住","t":"Vibe Coding 不是‘AI 全自动’，而是‘AI 快、人稳’：人给方向与验收，AI 给速度与草稿。节奏高频，风险可控。"}]},{"type":"how","intro":"Vibe Coding 的标准节奏，六步。这也串起你学过的所有概念。","steps":[{"in":"① 定需求：一句话说清你要做什么（与为谁做）","process":"用一个最小可解决问题描述产品：谁的什么痛点、你的方案是什么。范围越小越容易成功（MVP 思维）。","out":"一句清晰的需求 + 一个最小可交付范围","note":"这一步靠你的产品判断，AI 不懂用户，只能帮你澄清。"},{"in":"② 让 AI 搭骨架","process":"把需求、技术选型、约束（用什么框架、跑在哪）交给 AI，让它生成初始代码骨架。给足上下文，产出一发即中的概率更高（上下文工程）。","out":"一份能跑起来的最初版本"},{"in":"③ 立刻跑起来，别等‘完美’","process":"马上去运行、点开看。Vibe Coding 的高频循环从这里开始：跑→看到问题→反馈给 AI→再跑。","out":"一个‘总是能动的’半成品"},{"in":"④ 边用边改：小步迭代","process":"每次只改一小块，用‘分层报错 + 清晰描述’喂给 AI（见 Vibe 路径第 ① 课）。别一次塞一堆改动。","out":"功能逐步齐全、稳定"},{"in":"⑤ 测试与收尾：让 AI 造假不了","process":"请 AI 一起写测试、补边界、检查安全与可维护性。把‘验证’从人肉重复劳动交给自动化（见 Vibe 路径第 ⑤ 课）。","out":"一个经测试、可交付的版本"},{"in":"⑥ 部署上线：让其他人也能用","process":"把本地能跑的版本部署到服务器/托管平台，配好域名与环境（见 Vibe 路径第 ⑦ 课）。至此产品真正‘是个产品’了。","out":"可被访问的线上产品"}]},{"type":"realworld","items":[{"name":"MVP（最小可用产品）","note":"先做一个最核心、能用的小版本，再迭代。Vibe Coding 天然适合这种节奏。"},{"name":"AI 出错的兜底","note":"AI 会挖坑（假依赖、过时 API、逻辑偏差）。用版本控制（Git）、测试、审查来兜底，见 Vibe 路径第 ②⑤ 课。"},{"name":"不要一次让 AI 写‘整个系统’","note":"一次一块，跑通一块。越大越容易失控，越小越好定位问题。"},{"name":"从想法到上线的路径","note":"这正是接下来 Vibe 路径 8 节课要带你走完的事：Web 链路 → Git → API → 数据库 → 测试 → 项目结构 → 部署 → 全流程实战。"}]},{"type":"compare","pairs":[{"a":"传统开发","b":"Vibe Coding","diff":"传统：先设计全、再写代码、周期长；Vibe：先跑通一点点、高频迭代、人审 AI 写。"},{"a":"AI 全自动","b":"Vibe Coding","diff":"全自动 = 没有人在关键处把关，风险失控；Vibe = 人在方向与验收把关，AI 提供速度。"},{"a":"学 AI 原理","b":"做 AI 产品","diff":"原理让你懂‘为什么’（前 17 课）；Vibe 让你会‘怎么做’（点出产品节奏）。两条腿都要有。"},{"a":"MVP","b":"大而全","diff":"MVP 聚焦最小核心、快速验证；大而全一次做完往往拖垮进度、难以验证。"}]},{"type":"mistakes","items":["以为 Vibe Coding = 让 AI 全自动、人撒手——结果是失控。","一次让 AI 生成整个复杂系统——分裂成小块、跑一块再下一块。","不给 AI 上下文就让它开工——需求、技术栈、约束都要交代清楚。","不做测试、不审查就合并——AI 挖的坑要由你填。","只会‘跑起来’不会‘收尾’——错过测试、部署与可维护性，产品永远停留在 Demo。"]},{"type":"deep","title":"深入一点：把前 17 课装进这条流水线（知识地图收束）","beginner":["这 18 节课其实是完整的一条线：看懂 AI → 懂学习 → 懂语言 → 会用 → 让 AI 做事 → 真正做产品。","Vibe Coding 是‘消费端’：把‘生成/原理端’学到的能力，落成产品动作。","你做产品遇到大部分概念难题，都可以回查前面课程找答案。"],"advanced":["从工程看 Vibe Coding：它是把『提示工程、上下文工程、工具调用、Agent 循环、测试、部署』整合成一个可重复的研发流程。","关键在『节奏』：高频小步 + 及时验收 = 风险最小化。每个循环都要有『可回滚』（Git）、『可验证』（测试）作为护栏。","对想长期做产品的人：Vibe Coding 是高效起点，但深入后仍要补工程基础（架构、性能、安全、数据），这正是 Vibe 路径后续内容。"]},{"type":"exercise","prompt":"你想做一个‘帮同事查快递’的小工具，第一次让 AI 动手前最该先做哪件事？","opts":["让 AI 直接写整个系统","先把需求压缩成一句话最大可交付（MVP），并想清楚边界与技术选型，再让 AI 搭骨架","先把代码写完再想需求","什么都不做"],"a":1,"explain":"Vibe Coding 第一步是定清需求与 MVP 边界，再交 AI 搭骨架；直接让 AI 写整个系统最容易失控。","jump":"sec5-step0","jumpLabel":"定需求这一步"},{"type":"check","title":"结课检测：Vibe Coding 方法学你掌握了吗","intro":"共 4 题。全部答对即可完成核心路径，进入 Vibe 路径动手。答错会带你回对应段落复习。","questions":[{"q":"Vibe Coding 的核心分工是？","opts":["AI 全自动，人不管","AI 出速度与草稿，人定方向、判断与验收","人和 AI 各写一半但互相看不懂","不用 AI"],"a":1,"explain":"Vibe Coding 是‘AI 快、人稳’：AI 负责产出与迭代速度，人负责方向、边界与验收。","jump":"sec5-step3","jumpLabel":"边用边改这一步"},{"q":"为什么 Vibe Coding 强调‘先跑起来，别等完美’？","opts":["因为跑起来就自动完美了","高频小步：先有个能用的骨架，边用边发现问题边改，风险最小","为了显得效率高","因为完美永远做不到"],"a":1,"explain":"先跑起来 + 小步迭代，让产品始终‘能动’，问题及时暴露，才不至于最后一次性翻车。","jump":"sec5-step2","jumpLabel":"立刻跑起来这一步"},{"q":"AI 产出的代码，靠什么兜底最靠谱？","opts":["全信不查","版本控制(Git) + 自动化测试 + 人工审查","多跑几次不失败就算对","让 AI 自己检查自己"],"a":1,"explain":"AI 会挖坑，用 Git 可回滚、测试可验证、人来审查，是最稳的兜底组合。","jump":"sec5-step4","jumpLabel":"测试与收尾这一步"},{"q":"本课所在的完整 18 课主线，最后一步指向哪里？","opts":["结束学习","进入 Vibe Coding 工程基础路径，从零动手到上线","再学一遍","去考试"],"a":1,"explain":"核心路径以《Vibe Coding 入门》收官，之后进入 Vibe 路径：从 Web → Git → API → 数据库 → 测试 → 项目结构 → 部署 → 全流程实战。","jump":"sec5-step5","jumpLabel":"部署上线这一步"}],"done":"恭喜你走完 18 课核心主线：从看懂 AI 世界，到懂学习、懂语言、会用、让 AI 干活，再到 Vibe Coding 方法学。下一步，进入 Vibe Coding 工程基础路径，亲手把第一个产品做出来。","nextLesson":"v01-web"},{"type":"connection","known":["AI 原理、训练、语言模型、RAG、Agent、AI 编程（前 17 课）"],"learned":["Vibe Coding = 人定方向 + AI 出速度的小步高频流程","定需求 → 搭骨架 → 跑起来 → 小步改 → 测试 → 部署 六步节奏","MVP、Git 兜底、测试护栏","与 Vibe 路径 8 节课的衔接"],"next":"下一课起进入《Vibe Coding 工程基础》路径：从①『一个 Web 产品是怎么跑起来的』开始，一路做到⑦『从本地 Demo 到正式上线』与⑧『全流程实战』。","links":[{"href":"#/lesson/v01-web","text":"进入 Vibe 路径 ①《一个 Web 产品是怎么跑起来的》"},{"href":"#/lesson/l22-ai-coding","text":"回看《AI Coding》"}]}]},"l22-ai-coding":{"id":"l22-ai-coding","title":"AI Coding：把 AI 变成你的结对程序员","subtitle":"从‘让 AI 补全一行’到‘让 Agent 自己把整个功能做完’，AI 编程正在改变开发方式。这一课讲清楚你的新‘结对程序员’该怎么用、边界在哪。","category":"c11-ai-coding","chapterTitle":"第五章 · 让 AI 干活","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["ai-coding","pair-programming","agentic-coding","codegen"],"prereqLessons":["l-agent"],"nextLesson":"l18-vibe-coding","sections":[{"type":"opening","question":"现在很多人‘说几句话就让 AI 写了个网站’。AI 编程到底能到哪一步？是补全几行，还是真能独立完成一整个项目？代码谁负责、谁检查？","guess":"有人以为有了 AI 就不需要会写代码，或以为 AI 写的一定完美。","next":"这一课把 AI 编程按‘参与度’分成几档：补全、生成块、Agent 干活。你会明白 AI 是强力加速器，但产品的主人仍是人——你要负责验收、判断、兜底。"},{"type":"why","before":"你看到同事用 AI 刷刷刷就把功能写完了，也想用起来，但不知道从哪些场景入手、AI 与自己怎么分工、会不会写出不可维护的代码。","problem":"要么把 AI 当‘会写代码的搜索引擎’用（只补全、效率低），要么完全交给 Agent（风险失控、不可维护）。两种极端都不对。","need":"我们建立清晰的协作模型：把 AI 当结对程序员——你定目标、看边界、审结果，它负责快速产草稿、查报错、做重复活。并讲清代码审查永远是人的责任。"},{"type":"oneline","text":"AI 编程 = 把 AI 当作结对程序员：它能极快生成代码、解释报错、重构小块、补齐模板，甚至（Agent 模式）自主跑完一个小任务；但它不负责‘理解真实需求与产品边界’，更不负责‘保证代码正确与安全’——这两条永远是你的职责。"},{"type":"intuition","blocks":[{"k":"用带实习生来想","t":"AI 像一位非常聪明、打字极快、但缺乏项目上下文的实习生：你交代清楚它干得又快又好，但你不审核，它就会把半成品、甚至跑偏的东西交上来。你是那个要验收的‘主管’。"},{"k":"用导航来想","t":"AI 代码生成像开车导航：它帮你规划路线、少走弯路，但最终握方向盘、看路障、负责任的还是你。导航偶尔带你进死胡同，你得会判断。"},{"k":"一句话记住","t":"AI 负责‘快’，人负责‘对’。需求、验收、边界、安全、可维护，这些‘产品感’必须由你把关。"}]},{"type":"how","intro":"按‘AI 参与深度’把 AI 编程分成三档，逐步升级。","steps":[{"in":"① 补全与问答：AI 当‘高级补全器’","process":"在 IDE 里，AI 根据你的上下文补全下一行、解释函数、改命名、写测试骨架。你仍在主导每一行。","out":"写代码更快，错误更少，思路延伸"},{"in":"② 整块生成：给需求要结果","process":"你描述清楚功能（+给上下文/约束），让 AI 生成一块完整代码（接口、函数、组件、配置）。适合模板化、独立、边界清晰的代码。","out":"从一句话到一块可运行代码"},{"in":"③ Agent 模式：让 AI 自己跑任务","process":"给 Agent 目标与工具（读文件、改代码、跑测试、看报错），它循环推进直到完成：读→改→测→看结果→再改。Vibe Coding 常用此模式。","out":"AI 自主完成一个小功能/修复，你只做验收","note":"三档没有绝对高低，按任务复杂度与风险选择：事小用补全，模块化用生成，端到端小任务用 Agent。"},{"in":"④ 无论哪档：验收都是人的责任","process":"AI 产出的代码要过一遍：能跑通吗？符合需求吗？有没有安全/边界问题？有没有不可维护的烂摊子？","out":"‘AI 生成 + 人把关’的可靠组合"}]},{"type":"realworld","items":[{"name":"IDE 补全（Copilot / 助手补全）","note":"在你写代码时实时补全与建议，提升速度，适合第一档使用。"},{"name":"Claude Code / Codex 等 Agent","note":"在终端里用对话让 Agent 自主读代码、改代码、跑测试、看报错并迭代。适合第三档的端到端小任务。"},{"name":"提示词注入与‘AI 挖坑’","note":"AI 可能带进不存在的库、过时 API、或往代码里注入不可靠内容。所以自动合并前要审查与测试。"},{"name":"测试的必要性","note":"AI 生成的代码尤其需要自动化测试兜底——让 AI 同时生成测试，或让测试流程把‘AI 挖的坑’抓出来。"}]},{"type":"compare","pairs":[{"a":"补全","b":"Agent 自主完成任务","diff":"补全由你主导逐行效率；Agent 自主循环完成任务，但风险与失控面也更大，验收更要跟上。"},{"a":"AI 生成","b":"人审查","diff":"生成求快，审查求稳；缺了审查，快只是把问题放大。人最终为代码负责。"},{"a":"上下文工程","b":"单纯提示","diff":"给 AI 越清晰的项目上下文（相关文件、约束、报错），产出越贴近需求；只有一句‘给我写个 XX’往往离题。"},{"a":"AI 编程","b":"传统手写","diff":"AI 加速明显，但可维护性、安全、清晰度仍需人把控。二者是‘助手’与‘主人’，不是替代。"}]},{"type":"mistakes","items":["以为 AI 写的代码多跑几次就完美——需要你验证需求、安全与可维护性。","不给 AI 上下文就让它‘整个写一个系统’——上下文不够，产出必然跑偏。","把 AI 生产的一个报错原样丢回去又问一次——结构化描述（分层+现象+代码+判断）才高效。","忽略测试——AI 生成的代码尤其要靠测试兜底。","让 Agent 无约束乱跑——要给目标、边界、可执行命令白名单，防它越界或引火烧身。"]},{"type":"deep","title":"深入一点：为什么说‘上下文工程’是 AI 编程的核心能力","beginner":["AI 对你代码库的了解，取决于你给了它多少相关上下文：文件、函数、依赖、约束。","把相关文件、报错、你的判断组织好喂给它，比‘但求一句提示’有效得多。","一段‘上下文+需求+验收标准’的提示，往往一次出对。"],"advanced":["Agentic Coding：Agent 通过工具主动读你的仓库（RAG/索引/搜索），自动定位相关文件，减少你手动喂上下文——但你要给它合理的边界与文件白名单。","评估与回归：好的 AI 编程流程是‘可选、可测、可回滚’的；用测试套件 + Git 回滚保证每步可控。","安全：AI 生成的依赖、命令、脚本要审查；警惕提示注入（仓库里的恶意内容诱导 Agent 执行危险操作）。","与 Vibe Coding 衔接：下一课 Vibe Coding 就是‘用 AI 做产品的完整方法学’——从想法到上线的全过程里，AI 编码只是其中一环。"]},{"type":"exercise","prompt":"你让 AI 给一个项目写了个完整功能，它直接贴给你一段很长的代码。最该做的下一步是？","opts":["不看不测直接用","先审查：能否跑通、符合需求吗、有没有安全/边界/可维护问题，再用测试验证","把代码藏起来","直接删掉项目"],"a":1,"explain":"AI 生成求快，人负责对。一定要过需求、跑测试、看边界与安全再合入——验收是人的责任。","jump":"sec5-step3","jumpLabel":"验收是人的责任这一步"},{"type":"check","title":"结课检测：AI 编程你怎么用才靠谱","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"把 AI 当‘结对程序员’，谁对最终代码负责？","opts":["AI","人（你）：负责需求、验收、边界、安全","编译器","没有人"],"a":1,"explain":"AI 提供速度与草稿，但正确性、安全性、可维护性与需求符合度，责任永远在人的验收。","jump":"sec5-step3","jumpLabel":"验收是人的责任这一步"},{"q":"能让 AI 一次产出更贴合需求的代码，最有效的是？","opts":["给足相关上下文、约束与验收标准，而不是一句模糊指令","多喊几句‘再改改’","关了网络","把需求藏起来"],"a":0,"explain":"上下文工程是核心：相关文件、约束、期望结果越清楚，产出一发即中的概率越大。","jump":"sec7","jumpLabel":"上下文工程段"},{"q":"AI 生成的代码尤其需要什么来兜底？","opts":["运气","自动化测试与审查","更多的注释","更长的提示"],"a":1,"explain":"测试能把 AI 挖的坑尽早抓出来；配合人的审查，才够可靠。","jump":"sec6","jumpLabel":"测试的必要性这一条"},{"q":"关于‘AI 挖坑’（引用不存在的库/过时 API），正确的态度是？","opts":["全信 AI","AI 可能出错，所以自动合并前要审查依赖与 API 是否存在、是否过时","因为是 AI 所以一定对","与 AI 无关"],"a":1,"explain":"AI 会编造看似合理的依赖或过时 API。合入前要核验，这也正是人把关的一环。","jump":"sec6","jumpLabel":"AI 挖坑这一条"}],"done":"你会用 AI 编程当加速器了。最后一课，把这些整合成方法论：《Vibe Coding 入门》——从想法到上线，用 AI 完整做产品的全过程。","nextLesson":"l18-vibe-coding"},{"type":"connection","known":["Agent 能让模型自主调用工具（上一课）","上下文窗口与 Prompt 工程（前几课）"],"learned":["AI 编程三档：补全 / 整块生成 / Agent 模式","人负责需求、验收、边界、安全","上下文工程是高效使用 AI 编程的核心","测试兜底与防 AI 挖坑"],"next":"下一步是本路径收官：《Vibe Coding 入门》——把 AI 编程、Agent、上下文这些能力整合成从零到上线的完整产品方法论。","links":[{"href":"#/lesson/l-agent","text":"复习《Agent 智能体》"},{"href":"#/lesson/l18-vibe-coding","text":"进入《Vibe Coding 入门》"}]}]},"pl-data":{"id":"pl-data","title":"数据、模型与参数：AI 学习的三件套","subtitle":"模型在拿什么学？答：数据是教材，模型是大脑结构，参数是大脑里无数个可调的小旋钮。这三者的关系，是理解一切 AI 的起点。","category":"c01-ai-world","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["data","model","parameter"],"prereqLessons":["pl-train-infer"],"nextLesson":"l05-gradient-descent","sections":[{"type":"opening","question":"总听人说『这个模型有 70B 参数』『训练数据有几十 TB』。参数、数据、模型——这三个词你天天见，但它们到底是什么、什么关系？为什么参数越多越厉害（但又更贵）？","guess":"有人以为『模型的全部本事都是数据里抄来的』，或者『参数越多就一定越好』。","next":"这一课我们从最底层的三件套讲起：数据（模型看什么）、模型（模型长什么样）、参数（模型的'旋钮'）。搞懂它们，你对『训练』『能力』『成本』的理解会瞬间落地。"},{"type":"why","before":"你想弄懂 AI 为什么能『学会』，于是去看资料，却总被『参数规模』『训练数据量』这些数字砸晕，不知道它们和『模型会不会用』有什么关系。","problem":"把数据、模型、参数三者混为一谈，就解释不了很多现象：为什么同样是鹦鹉学舌，有的模型聪明有的笨？为什么参数翻倍模型不一定翻倍聪明，但成本一定翻倍？为什么有时数据质量比数据量更重要？","need":"我们把三件套分清楚：数据是『给模型看的世界』，模型是『看世界的脑回路结构』，参数是『脑回路里无数个可微调的小值』。层层拆开，很多『为什么』都能对号入座。"},{"type":"oneline","text":"数据（Data）= 教材与习题；模型（Model）= 大脑的『结构设计』（有多少层、神经元怎么连）；参数（Parameter）= 大脑里数以亿计的『小旋钮』，训练就是把它们拧到最合适的位置。能力来自结构与数据，旋钮的数量决定模型的『规模』与成本。"},{"type":"intuition","blocks":[{"k":"用学生来想","t":"数据＝读过的书、做过的题（内容）；模型＝这位学生大脑的结构（聪明程度上限）；参数＝大脑里成千上万个可以不断微调的小连接。训练就是：用大量好书好题，把这几亿个小连接一点点调顺，让这个学生变强。"},{"k":"用收音机来想","t":"模型＝收音机的电路设计；数据＝收到的电台信号；参数＝面板上能拧的旋钮。一个收音机好不好，取决于电路设计（模型）+ 接收到的信号（数据）+ 旋钮拧得对不对（参数调得好不好）。"},{"k":"一句话记住","t":"结构（模型）定上限，数据定内容，参数定『具体怎么算』。参数越多，模型越『大』，理论上能学的东西越多，但训练成本与部署成本也越高。"}]},{"type":"how","intro":"把三件套分别拆开：它是什么、从哪来、为什么重要。","steps":[{"in":"① 数据 Data：模型的『世界』","process":"文本、图片、代码、语音等一切喂给模型的东西。训练数据的规模与质量，直接决定模型见没见过某类知识。数据要先清洗、去重、组织。","out":"『教材』：决定模型大概会什么、懂什么"},{"in":"② 模型 Model：大脑的『结构』","process":"神经网络『长什么样』——有多少层、每层多少神经元、神经元之间怎么连、用什么激活函数。这是架构设计，决定了模型理论上的能力上限。","out":"『脑回路设计』：决定上限与能学到的结构"},{"in":"③ 参数 Parameter：可调的『小旋钮』","process":"每条神经连接上的权重大小（几亿到几千亿个数字）。它们是训练真正在改的东西。参数量常被拿来衡量模型规模（如 7B、70B）。","out":"『旋钮集合』：决定『具体怎么算』与参数量级"},{"in":"三者如何协作","process":"训练时：把数据喂给具备结构的模型，反复调整参数，让输出尽量接近期望。三要素缺一不可：结构弱、数据差、或参数没调好，都会变成坏模型。","out":"一个『读过好书、结构良好、旋钮调准』的可用模型"}]},{"type":"realworld","items":[{"name":"参数规模 70B / 7B / 1.5B","note":"B 指 Billion（十亿），是模型参数量。大模型参数量常在几十亿到几千亿之间。参数量越大，模型『容量』越大，但训练与运行成本也越大。"},{"name":"为什么 GPT-4 系列这么强也这么贵","note":"越大参数 + 越多数据 = 能力更强，但训练要的算力和部署要的显存都剧增。能力与成本是一对不断权衡的对手。"},{"name":"『数据是新时代的石油』","note":"高质量、干净、多样的训练数据极关键。数据质量不足时，再大的模型也可能『吃垃圾吐垃圾』。这也是为什么很多公司拼命囤数据。"},{"name":"为什么中文模型注重中文语料","note":"模型的能力受训练数据影响很大。中文语料不足的模型，中文表现就差。这也是为什么国产大模型要专门堆中文高质量数据。"}]},{"type":"compare","pairs":[{"a":"数据 Data","b":"模型 Model","diff":"数据是『输入的世界/教材』，模型是『处理世界的结构』。同样的模型用不同数据学出不同特长；同样的数据放进不同结构，效果也不同。"},{"a":"模型 Model","b":"参数 Parameter","diff":"模型是结构设计（虚、相对固定），参数是结构里成千上万的具体数值（实、可训练调整）。可以把模型理解成『参数的容器与组织方式』。"},{"a":"参数量（规模）","b":"能力上限","diff":"参数量大能学更多，但不等于一定更聪明——还要数据够好、训练到位。规模是『容量』，能力是『用得好不好』。"},{"a":"数据质量","b":"数据量","diff":"质量差的数据量再大也可能有害；干净、多样、正确的高质量数据量，才真正提升模型水平。"}]},{"type":"mistakes","items":["以为『参数越多就一定越好』——参数量需要匹配数据量与算力，盲目堆参数不一定有效，反而成本爆炸。","以为『模型的知识是直接从数据抄来的』——模型学的是分布规律，不是存储原始数据（虽有少量记忆风险）。","以为『数据越多越好，质量无所谓』——脏数据、重复数据、错数据会教坏模型。","把『模型结构』和『参数值』混为一谈——结构造好后，真正的'学习'是调参数。","以为『只要模型大就什么都会』——数据覆盖不到的东西，模型就是不会，架构差异也有影响。"]},{"type":"deep","title":"深入一点：参数到底是个什么样的『数字』","beginner":["想象一张蜘蛛网，网上每条丝有一个数字表示‘这条丝重要/怎么影响下一个点’。","神经网络里，前一层每个神经元的输出，会乘以一个权重再传给下一层。这些权重就是参数。","模型‘学会’一件事，本质就是把这一大堆权重调到一个能很好完成任务的状态。"],"advanced":["一个参数通常指一个权重或偏置（bias）。训练即优化这些参数，使损失函数最小。","嵌入层、注意力矩阵、前馈网络的权重加起来构成参数量。LLM 的参数量主要集中在 Transformer 的注意力与前馈层。","‘参数高效微调’（如 LoRA）只训练一小部分新加的低秩参数来适配下游任务，从而大幅降低显存与成本——这就是为什么现在微调大模型很常见、成本可控。"]},{"type":"exercise","prompt":"两个模型参数量相同，但 A 用了更多更高质量的数学数据，B 用了大量杂乱重复的一般文本。哪个更可能在数学题上表现更好？","opts":["A，因为高质量、覆盖到数学的数据直接决定它懂多少数学","B，因为数据越多就一定越好","完全一样，因为参数量决定一切","无法判断，参数量完全无关"],"a":0,"explain":"模型的能力与训练数据的质量、覆盖度强相关。同样参数量下，喂了高质量数学数据、结构又合理的模型，在数学上通常更可靠。","jump":"sec5-step0","jumpLabel":"数据这一层"},{"type":"check","title":"结课检测：数据 / 模型 / 参数 你分得清吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"『模型的能力上限主要由结构决定』，这里的'结构'通常指什么？","opts":["训练数据的来源","神经网络有多少层、怎么连（模型架构）","电脑的内存大小","用户有没有会员"],"a":1,"explain":"结构即模型的架构设计（层数、连接方式等），决定了模型理论上能学到什么；数据决定内容，参数决定具体计算。","jump":"sec5-step1","jumpLabel":"模型结构这一层"},{"q":"训练时模型真正被反复修改的是什么？","opts":["训练数据本身","模型参数（权重/偏置）","显卡","网页样式"],"a":1,"explain":"训练就是用数据反复调整模型参数（权重），让输出接近期望；数据是输入，通常不因训练而改。","jump":"sec5-step2","jumpLabel":"参数这一层"},{"q":"『70B』指的是模型的什么？","opts":["训练数据条数","参数量（700 亿个参数）","网络延迟毫秒数","模型文件的行数"],"a":1,"explain":"B 代表 Billion（十亿），70B 即 700 亿个参数，是衡量模型规模（参数量）的常见指标。","jump":"sec5-step2","jumpLabel":"参数这一层"},{"q":"用三个词概括 AI 学习的『三件套』是？","opts":["CPU、内存、硬盘","数据、模型、参数","提问、回答、得分","字体、颜色、布局"],"a":1,"explain":"AI 学习的三件套是数据（教材）、模型（结构）、参数（旋钮），三者协作完成学习。","jump":"sec5-step3","jumpLabel":"三者协作这一层"}],"done":"三件套分清了：数据是教材、模型是结构、参数是旋钮。那训练到底怎样才能把这些旋钮越拧越准？下一课我们看训练的核心引擎——损失函数与梯度下降。","nextLesson":"l05-gradient-descent"},{"type":"connection","known":["模型是被训练出来的产物（上一课）"],"learned":["数据＝教材、模型＝结构、参数＝旋钮","参数量衡量模型规模，但不等于能力","数据质量与覆盖度直接影响模型水平","训练＝用数据反复调整参数"],"next":"旋钮往哪个方向拧、拧多少，靠什么判断？下一课《损失函数与梯度下降》：模型怎么知道自己错了，以及如何一步步『往下走』变聪明。","links":[{"href":"#/lesson/pl-train-infer","text":"复习《训练和使用模型》"},{"href":"#/lesson/l05-gradient-descent","text":"进入《损失函数与梯度下降》"}]}]},"pl-function-calling":{"id":"pl-function-calling","title":"Function Calling：让模型能『动手』","subtitle":"只会聊天的模型帮不了你太多。Function Calling 让模型学会‘调用你给的函数’——查天气、存取数据、操作外部系统。这是从‘会说’到‘会做’的关键一步。","category":"c06-llm-app","chapterTitle":"第四章 · 用起来","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["function-calling","tool-use","structured-output"],"prereqLessons":["pl-prompt"],"nextLesson":"l-agent","sections":[{"type":"opening","question":"你能让 ChatGPT 查天气、订机票、访问数据库吗？单靠聊天它做不到——但真正的产品里它做到了。秘密就是 Function Calling：让模型自己决定‘该不该调用某个函数’。","guess":"有人以为模型‘自己就能联网/操作一切’，或以为函数调用是魔法。","next":"这一课讲 Function Calling：把工具（函数）的说明告诉模型，模型需要时‘点名要调哪个、传什么参’，由你的程序真正执行并回传结果。看完你就懂所有 AI Agent 的底座能力。"},{"type":"why","before":"你想做一个真正‘能干事’的 AI 应用（查数据、调接口、改记录），但发现模型只会生成文本，无法直接操作系统。","problem":"不理解 Function Calling，你会把‘模型直接操作外部’想成理所当然，或把‘结构化输出’和‘函数调用’混为一谈，做出来的应用要么不可靠、要么全是伪需求。","need":"我们把这条链路讲透：工具描述 → 模型请求调用 → 程序执行 → 结果回喂。它是 Agent、工作流、一切会‘做事’的 AI 产品的地基。"},{"type":"oneline","text":"Function Calling = 你把一组‘函数（工具）的说明书’（名字、参数、作用）告诉模型；模型在回答时若需要，就输出一个结构化的‘调用请求’（调哪个函数、传什么参）；由你的程序真正执行并把结果回传给模型，模型再基于结果继续回答。"},{"type":"intuition","blocks":[{"k":"用餐厅点单来想","t":"菜单（工具说明）摆在桌上：有宫保鸡丁、酸辣汤。你问服务员‘有没有辣的’，服务员看了菜单说‘有，宫保鸡丁’。但真正做菜的是后厨，不是服务员。Function Calling 就是：模型是服务员（只会看菜单下单），后厨（你的程序）才真动手。"},{"k":"用给你配助理来想","t":"你有个助手（模型），但没配工具（函数）。你问他今天天气，他只能瞎编。给他配了‘查天气 API’这个工具并告诉他怎么用，他就能‘让我帮你查——把城市名传进去’，由真正的天气服务返回结果，他再念给你听。模型没联网，是‘调用工具’替他联网。"},{"k":"一句话记住","t":"模型不执行函数，它只‘决定要调哪个参数是多少’；你的程序确认执行，把结果喂回去。分工：模型负责决策，程序负责真实世界。"}]},{"type":"how","intro":"一次 Function Call 的完整闭环，五步。","steps":[{"in":"① 注册工具：告诉模型有哪些函数可用","process":"在 API 请求里传一份函数清单 JSON Schema：函数名、参数、说明。模型‘看到’这些说明，但看不到你的实现代码。","out":"模型知道有哪些‘菜单’可选"},{"in":"② 模型判断：本次回答要不要调工具","process":"用户提问后，模型判断是否需要某个工具才能更好地回答；需要则不会直接给最终答案，而是输出一个 function_call 请求。","out":"模型返回‘我建议调用 `get_weather`, 参数 {city: 北京}’"},{"in":"③ 你的程序执行真正的函数","process":"你的代码收到这个请求，去调用真实的天气 API（或数据库、业务接口），拿到实际结果。这一步是‘后厨在做菜’。","out":"真数据结果（如 26°C、晴）"},{"in":"④ 把结果回喂给模型","process":"把函数执行的输出（tool message）作为上下文返回给模型，并告诉它‘这是工具返回的结果’。","out":"模型‘看到’了真数据"},{"in":"⑤ 模型基于结果给出最终回答","process":"模型综合用户问题与工具结果，生成面向用户的最终答案。一次工具调用就完成了。","out":"‘北京今天 26°C，晴’——准确且真实"}]},{"type":"realworld","items":[{"name":"为什么强调‘由程序执行’","note":"模型本身不联网、不读写数据库，它输出的是‘调用意图’；真正执行必须在你可控的代码里做，这也是安全与权限的边界所在。"},{"name":"与结构化输出的关系","note":"Function Calling 依赖模型输出结构化 JSON（函数名+参数）。可以和‘JSON 模式’配合，让输出更规范可解析。"},{"name":"多个工具并行调用","note":"现代 API 允许模型一次请求同时调用多个函数（如同时查天气和订票），再由程序逐个执行、统一回喂。"},{"name":"Agent 的地基","note":"下一课的 Agent 本质上就是：模型 + 一组函数（工具）+ 一个循环（判断→调用→回看 → 再判断）。Function Calling 就是那个‘调用’原语。"}]},{"type":"compare","pairs":[{"a":"文本回答","b":"Function Call","diff":"常规回答只输出文字；function call 输出‘要调哪个函数及参数’的结构化指令，由程序去执行。"},{"a":"Function Calling","b":"你们自己写 if-else","diff":"if-else 是硬编码每个用户问法；Function Calling 让模型动态判断何时调哪个工具，覆盖自然语言里无穷的问法。"},{"a":"工具说明","b":"工具实现","diff":"给模型看的是说明书（名字/参数/作用，JSON Schema）；真实现跑在你侧，模型永远看不到也不该看到。"},{"a":"单轮调用","b":"多轮循环（Agent）","diff":"单次调用一次往返；Agent 会在‘调用→回看结果→再调用’之间循环多次，直到完成复杂任务。"}]},{"type":"mistakes","items":["以为模型‘自己会执行函数’——它只输出调用请求，执行权在你手里。","工具说明写得含糊——模型就传错参数。说明书越清楚（参数必填、类型、示例），调用越准。","把模型当成能直接读你数据库的存在——必须把查询做成工具并控好权限。","忽略安全边界——工具要校验入参、加权限，别让模型拿着能删库的工具乱来。","以为 Function Calling 就是‘发给一条消息’——它是‘决策→执行→回喂’的闭环，要你写执行与回填逻辑。"]},{"type":"deep","title":"深入一点：怎么把工具定义得让模型调得准","beginner":["对每个函数：写清函数名、参数列表（类型、是否必填）、一句话说明‘这个函数做什么、什么时候该调’。","用真实例子给参数取值作示范，能显著降低模型传错参的概率。","职责单一：一个函数只干一件事，便于模型准确调用。"],"advanced":["工具即接口契约：把函数写成 JSON Schema（OpenAI 的 tools 参数 / 各家 tool-use 协议一致）。类型、枚举、最大长度都对模型选择有价值。","并行与依赖：模型可一次输出多个 tool_calls；若存在依赖（第二步要用第一步结果）需多轮循环编排。","安全：白名单调用、输入校验、次数/预算限制、敏感操作二次确认。模型可能被提示注入诱导调用危险工具，要做好防护。","回退与容错：工具调用失败要能告诉模型‘调用失败了’，让它换参数重试或走人工，形成健壮的 Agent 循环。"]},{"type":"exercise","prompt":"你问 AI 助手‘杭州现在天气如何’，它说‘让我调一下天气服务’。实际上谁在执行这个调用？","opts":["AI 模型自己联网","你的程序收到模型的 function_call 请求，去调用真实天气 API 并回填结果","浏览器自动打开天气预报网站","没人执行，它直接编一个"],"a":1,"explain":"模型只输出‘建议调用 get_weather(city=杭州)’；真正访问天气 API 并回传结果的是你的程序，这就是 Function Calling 的分工。","jump":"sec5-step2","jumpLabel":"程序执行真正的函数这一步"},{"type":"check","title":"结课检测：Function Calling 你明白了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"Function Calling 中，模型主要负责？","opts":["真正执行函数、访问数据库","判断该调哪个函数并输出结构化的调用请求（函数名+参数）","编译代码","管理服务器"],"a":1,"explain":"模型承担决策角色：判断是否需要工具、输出‘调哪个、传什么参’；执行由你的程序完成。","jump":"sec5-step1","jumpLabel":"模型判断这一步"},{"q":"给模型看的‘函数清单’本质是什么？","opts":["函数的真实实现代码","函数的说明书（名字、参数、作用，通常是 JSON Schema）","服务器密码","数据库密码"],"a":1,"explain":"传给模型的是一份工具说明（JSON Schema），模型据此知道有哪些函数、怎么调；绝不给实现代码。","jump":"sec5-step0","jumpLabel":"注册工具这一步"},{"q":"一次完成的 Function Call 闭环顺序是？","opts":["执行→描述→决定→回喂","注册工具→模型决定调用→程序执行→结果回喂→模型回答","直接回答→不调用","回喂→执行→注册"],"a":1,"explain":"标准链路：注册工具 → 模型输出调用请求 → 程序执行真函数 → 结果回喂 → 模型给出最终答案。","jump":"sec5-step4","jumpLabel":"模型给出最终回答这一步"},{"q":"以下哪项是使用 Function Calling 时最重要的安全考量？","opts":["给工具强输入校验与权限控制，防止模型/注入调用危险操作","函数名越长越安全","禁止一切函数","只能让模型自己执行"],"a":0,"explain":"模型可能被诱导调用危险工具，所以要在执行侧做好入参校验、权限与配额控制、敏感操作确认。","jump":"sec7","jumpLabel":"安全段"}],"done":"模型学会了‘动手’——但它还不会自己决定‘一直做到完’。下一课把这些串成自动循环：《Agent 智能体》，让 AI 自己规划、调用、观察、再行动。","nextLesson":"l-agent"},{"type":"connection","known":["Prompt 四件套与上下文工程（上一课）","模型只能预测文本，不能直接操作外部"],"learned":["Function Calling = 模型输出调用请求，程序执行","工具说明（JSON Schema）决定调用质量","安全边界：校验、权限、配额","它是 Agent / 工作流的地基"],"next":"会调用了还不够，Agent 要‘自己决定一直做下去’。下一课《Agent 智能体》：目标→推理→调用→观察→再行动 的自动循环。","links":[{"href":"#/lesson/l-agent","text":"进入《Agent 智能体》"},{"href":"#/lesson/pl-prompt","text":"复习《Prompt 与上下文》"}]}]},"pl-prompt":{"id":"pl-prompt","title":"Prompt 与上下文：怎么和模型说清楚","subtitle":"同样的模型，有人问出平庸答案，有人问出惊艳答案——差别往往在 Prompt。这一课给你一套可复用的‘说清楚’框架。","category":"c05-llm","chapterTitle":"第四章 · 用起来","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["prompt","prompt-engineering","context"],"prereqLessons":["l12-context-window"],"nextLesson":"l-rag","sections":[{"type":"opening","question":"同样让 AI 写一份周报，有人得到一团废料，有人得到直接能用的。差别不在模型，而在你‘怎么说’。Prompt（提示词）到底有没有套路？","guess":"有人以为 Prompt 就是‘礼貌地多问几次’，或者要背一堆玄学咒语。","next":"这一课把 Prompt Engineering 的底层逻辑讲清楚：模型只会按你给的上下文做预测，所以‘把话说清楚、给足边界、给出期望格式’就是全部秘诀。再给你一套 Copy 就能用的模板。"},{"type":"why","before":"你用 AI 写东西、改代码、做总结，但经常要来回纠正它，效率很低。你想知道怎么一次就问出好结果。","problem":"把 Prompt 当玄学、乱堆关键词，或指望 AI‘读懂你的潜台词’，是常见的低效来源。你缺的是一套可复用的思考框架。","need":"Prompt 的本质是‘上下文工程’：你往窗口里放什么，它就拿什么推理。我给你角色-目标-约束-输出格式四件套，以及常见陷阱，让你一次问清。"},{"type":"oneline","text":"Prompt = 给模型一份清晰的‘工作说明书’：你是谁（角色）、要完成什么（目标）、边界是什么（约束/不要做什么）、交给我什么形状的结果（输出格式）。放进去的信息越清楚，拿出来的结果越可用。"},{"type":"intuition","blocks":[{"k":"用交代下属来想","t":"你给新下属派活：只说‘帮我把方案写了’＝他会一头雾水写出一堆没用的。说清楚‘背景、目标、条件、格式、例子’＝他才能一次做对。AI 就是你手下那个非常聪明但没有读心术的下属。"},{"k":"用下订单来想","t":"Prompt 像下外卖订单：你不写辣度、分量、备注，对方只能按默认做。写清楚‘不要辣、加个备注、送到了敲门’——结果才符合预期。"},{"k":"一句话记住","t":"给模型看的每句话都会影响它预测的走向。说得越明确、越有边界，输出越可控。"}]},{"type":"how","intro":"给出四件套框架，并用一个例子贯穿。","steps":[{"in":"① 角色 Role：告诉它‘你是谁、用什么视角’","process":"先设定身份与视角，例如‘你是一名有 10 年经验的数据库 DBA’‘你是小学老师’等。角色影响语气与知识取向。","out":"模型切换到对应语气与视角"},{"in":"② 目标 Task：明确要完成什么","process":"把任务说成一个清晰动词：总结、改写、翻译、设计、排查、写代码。一个 prompt 尽量只聚焦一个任务。","out":"模型知道该交付什么"},{"in":"③ 约束 Constraint：给出边界与不要做的事","process":"字数范围、语气、不要说教、不要编造、基于给定资料回答、保密等。边界越清楚，越不容易跑偏。","out":"输出被限制在期望范围"},{"in":"④ 输出格式 Format + 示例","process":"告诉它要什么形态：列表？表格？代码？JSON？给一个示例更好。格式明确后，结果可直接用、可直接解析。","out":"拿到结构化的、可用的输出"}]},{"type":"realworld","items":[{"name":"写周报的例子","note":"把四件套用上：角色‘你是我的助理’＋目标‘把本周工作整理成周报’＋约束‘不超过 8 条、语气正式’＋格式‘分 已完成/进行中/风险 三栏’——结果一步到位。"},{"name":"改代码的例子","note":"发报错原文 + 相关代码 + 你的判断（哪一层出的问题）＋要求‘说明原因并给出修复’，比只丢一个报错字串的高效得多。"},{"name":"系统提示词（System Prompt）","note":"在应用里，角色/约束常做成系统提示，每次请求都放在窗口最前，是产品级的 Prompt 管理。"},{"name":"Few-shot（给示例）","note":"在 Prompt 里附 1~2 个问答例子，模型照葫芦画瓢，输出更规范。这是提升稳定性的常用技巧。"}]},{"type":"compare","pairs":[{"a":"笼统提问","b":"四件套提问","diff":"笼统：信息少、边界模糊、结果随机；四件套：角色+目标+约束+格式，一次成功率大幅提升。"},{"a":"单向输出","b":"多轮追问","diff":"复杂任务一次难成，可把它拆成多轮：先生成骨架，再让它细化某部分。Prompt 也可以是流程。"},{"a":"Prompt","b":"微调","diff":"Prompt 不改模型，只改输入让它更好发挥；微调是改模型参数适配任务。能靠 Prompt 解决的先用 Prompt，成本低得多。"},{"a":"Prompt","b":"RAG","diff":"Prompt 靠话术组织上下文；RAG 靠检索把外部资料塞进上下文。二者常配合：先 RAG 取资料，再 Prompt 组织。"}]},{"type":"mistakes","items":["以为 Prompt 越华丽越有效——关键是信息密度与明确边界，不是堆砌形容词。","只给一句话任务，不给背景、约束、格式——模型只能自由发挥。","一次塞多个复杂任务——拆开更稳。","让模型‘自由发挥’却怪它跑偏——边界没给够。","忽略示例的价值——给一个例子常比解释十句更有效。"]},{"type":"deep","title":"深入一点：为什么 Prompt 会‘无中生有’与‘上下文工程’思想","beginner":["模型本质是在预测‘接下去最合理的文本’。Prompt 提供了‘上下文’，输出是被它引导的续写。","所以 Prompt 写得像什么风格，输出就容易是什么风格——这就是为什么示例（few-shot）很有效。","想知道模型为什么跑偏，先检查你给它的上下文是否误导了它。"],"advanced":["上下文工程（Context Engineering）：把产品要的上下文——系统提示、工具描述、检索片段、会话历史——按重要性排序并塞进有限窗口，是当前 AI 工程重头戏。","结构化 Prompt、Chain-of-Thought 引导、工具调用描述、输出 Schema 约束（如 JSON mode），都是控制生成的手段。","评估：好的 Prompt 应该‘可复现’——同一输入多次得到一致且合格的输出。用测试集回归验证 Prompt 改动，别靠手感。","警惕注入（Prompt Injection）：外部带来的文本可能被当作指令执行，产品要在边界上做隔离与校验。"]},{"type":"exercise","prompt":"你要让 AI 帮你把一段长文压缩成 3 条要点。下面哪个 Prompt 最可能一步到位？","opts":["‘帮我看看这段文字。’","‘你是我的助理。请把下面这段文字压缩成 3 条要点，每条不超过 30 字，直接给要点列表，不要其他说明。原文：…’","‘这段很厉害，你懂吧？’","‘写一篇更长的小说。’"],"a":1,"explain":"选项 B 给出了角色、目标、数量、长度、格式与材料，边界清晰，一次成功率最高。","jump":"sec5-step0","jumpLabel":"四件套框架这一段"},{"type":"check","title":"结课检测：Prompt 四件套你上手了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"Prompt 四件套通常指？","opts":["颜色、字体、布局、图标","角色、目标、约束、输出格式","开头、中段、结尾、落款","输入、输出、缓存、日志"],"a":1,"explain":"四件套：设定角色、说清目标、给边界约束、规定输出格式。","jump":"sec5-step0","jumpLabel":"角色这一步"},{"q":"为什么在 Prompt 里附 1~2 个示例（Few-shot）常能提升效果？","opts":["示例会让模型更听话","模型本质是预测续写，示例给它‘照这个风格来’的强引导","示例能扩容上下文","没有任何作用"],"a":1,"explain":"模型在预测‘接下来最合理的文本’，示例直接示范了期望的输出形态，引导作用很强。","jump":"sec6","jumpLabel":"Few-shot 这个现实话题"},{"q":"模型‘一本正经胡说八道’（幻觉）提示我们对 Prompt 该有哪种意识？","opts":["模型在预测续写而非核实事实，重要内容要靠资料（RAG）与检查","多夸它几句就不会胡说","与 Prompt 无关","改用更大的字号"],"a":0,"explain":"模型是预测性生成，不保证事实正确。关键信息要给它可靠资料并用 RAG，再要求它基于资料作答。","jump":"sec7","jumpLabel":"上下文工程与评估这一段"},{"q":"能靠 Prompt 解决的问题，为什么一般优先于微调？","opts":["因为 prompt 零成本、快、不改变模型","因为微调更慢但效果差","两者没有任何关系","因为 prompt 不可用"],"a":0,"explain":"Prompt 只改输入、不改模型，成本低、迭代快；微调要训练、成本高。能不改模型就优先用 Prompt。","jump":"sec7","jumpLabel":"上下文工程这一段"}],"done":"你会‘说清楚’了。但模型会瞎编——怎么让它基于你的真实资料回答？下一课《RAG》：让模型先查资料、再回答。","nextLesson":"l-rag"},{"type":"connection","known":["窗口里装什么是用户决定的（上一课）"],"learned":["Prompt = 上下文工程，四件套框架","Few-shot、系统提示、多轮拆解等技巧","幻觉的根源与用 RAG/检查对齐","Prompt 优先于微调的原因"],"next":"如果模型只会编，怎么让它‘基于你的资料’回答？下一课《RAG》揭晓把外部资料接进窗口的经典方案。","links":[{"href":"#/lesson/l12-context-window","text":"复习《上下文窗口与推理》"},{"href":"#/lesson/l-rag","text":"进入《RAG》"}]}]},"pl-train-infer":{"id":"pl-train-infer","title":"训练和使用模型有什么区别","subtitle":"模型的『上学阶段（训练）』和『上班阶段（使用/推理）』是完全不同的两回事。搞懂这个，你就不会再困惑『为什么 ChatGPT 每次回答还不一样』『为什么模型会一本正经胡说八道』。","category":"c01-ai-world","chapterTitle":"第一章 · 认识 AI","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["ai-ml-dl","training","inference"],"prereqLessons":["l01-ai-vs-ml-dl"],"nextLesson":"pl-data","sections":[{"type":"opening","question":"你打开 ChatGPT 问了个问题，它几秒内就回了你。但你可能没想过：它『学会说话』的那个过程（训练）和你使用它的过程（推理），根本不在一个时间、也不在一个量级。它们到底有什么不同？","guess":"有人觉得模型训练和使用是一回事，区别只在于快慢。","next":"这一课我们讲清训练（Training）与推理（Inference/使用）的本质区别：一个是在海量数据上『慢慢写作业、改答案』，另一个是『拿到考卷直接作答』。这是理解成本、速度、以及为什么大模型很贵的钥匙。"},{"type":"why","before":"你想知道：为什么训练一个 GPT 要花几百万美元、几千张显卡好几个月，而用的时候点一下就出结果？为什么同样的模型，每次回答会不一样？","problem":"如果不区分训练与推理，你会把『模型的成本』『模型的能力上限』和『一次回答的成本』混为一谈。你会奇怪：既然训练这么贵，为什么我用起来这么快？也会疑惑：模型到底是『提前背好了答案』还是『现场算出来的』？","need":"把训练 vs 推理分开，你就知道：模型的能力是训练阶段敲定的（一次性的），而每一次回答是推理阶段现算的（每次都要烧电）。所有关于『贵不贵、快不快、准不准』的问题，都要先问一句：你指的是训练还是推理。"},{"type":"oneline","text":"训练（Training）＝模型在海量数据上『写作业、对答案、改参数』的一次性重活，几个月、贵、改的是模型的『记忆与能力』；推理（Inference / 使用）＝训练完的模型每来一个输入就『现场作答』，每次都要算一遍，快、便宜但也不是免费。"},{"type":"intuition","blocks":[{"k":"用学生来想","t":"训练＝学生寒窗苦读，读了大量课本和例题，把知识『内化』成自己的答题能力。这个过程长、累、费钱（教材、学费）。推理＝拿到考卷直接作答，靠之前内化的能力秒写答案。学生毕业后的『能力』是训练决定的，每次考试只是把能力'调出来'用。"},{"k":"用厨师来想","t":"训练＝大厨经过多年练习，练出一身手艺（参数）。推理＝客人点菜，大厨现场动手做一盘。手艺是多年前'训练'出来的，但每一道菜都是现场'推理'做的——所以每次都要时间，且水平取决于那身手艺。"},{"k":"一句话记住","t":"训练：改参数、时间长、一次性、贵；推理：用参数、时间短、每次都算、有成本。一切 LLM 的『贵』都主要来自训练，但每一次对话的『算力』来自推理。"}]},{"type":"how","intro":"把一次训练和一次推理分别拆开，对比每一步。","steps":[{"in":"训练前：准备『教材』（数据和算力）","process":"采集海量文本/图片/代码作为训练数据，准备好大量 GPU/TPU 算力集群。数据要清洗、去重、组织成训练样本。","out":"一批质量过关的训练数据 + 一台算力集群"},{"in":"训练中：模型『写作业-对答案-改参数』反复迭代","process":"把数据分批喂给模型做预测，计算预测和真实答案的差距（Loss），再用反向传播一层层微调参数。重复亿万次，直到误差低到可接受。","out":"参数被反复调整，模型逐渐学会了规律"},{"in":"训练完：得到一个『固定』的模型文件","process":"训练结束后的参数被冻结，变成一个可以被调用、分发、部署的模型文件（权重）。此时能力已定型。","out":"一份可部署的模型权重（几十到上千 GB）"},{"in":"推理中：来一个输入，模型现场算一次","process":"你把问题给模型，模型把它编码成数字，经过神经网络前向计算一遍，输出答案。每次回答都是完整算一次，不改动任何参数。","out":"得到一次『当下』的回答，参数保持不变"},{"in":"推理的成本与速度","process":"每次推理都要占用显卡做一次前向计算，所以有延迟和成本。这也是为什么在线大模型按『Token 用量』收费。","out":"按用量计费、有延迟、有成本"}]},{"type":"realworld","items":[{"name":"ChatGPT 的回答『每次不完全一样』","note":"推理阶段有随机性（采样时温度大于 0），同样的问题每次选词的随机分布不同，所以回答会有细微差异。这不是『模型在变』，而是推理时的随机采样。"},{"name":"『训练一次要花几百万美元』","note":"指的就是训练阶段：几千张高端 GPU 连跑数周，电费、机房、人力都计入。GPT-4 级别的训练成本以千万美元计。"},{"name":"『按 Token 计费』","note":"你为每次推理付费：模型每处理一个 token（约一个字/词的一部分）都要做一次计算，供应商按用量收费，覆盖推理的算力成本。"},{"name":"『微调（Fine-tuning）』","note":"在已有模型基础上做一次『小规模训练』：拿少量领域数据再微调参数，让模型更适合某一任务。它介于『纯训练』和『纯推理』之间，本质仍是一次训练。"},{"name":"模型会『一本正经胡说八道』","note":"推理时模型只是在『预测下一串合理的词』，它并不理解对错，也不自知。能力在训练中定型，但每次回答都是预测，可能自信地编造。这就是幻觉（Hallucination）。"}]},{"type":"compare","pairs":[{"a":"训练 Training","b":"推理 Inference","diff":"训练改参数、时间长、一次性、成本高；推理用参数、时间短、每次都算、按量计费。"},{"a":"模型能力","b":"一次回答质量","diff":"能力上限在训练时定型；但单次回答可能受采样随机性影响，同一能力下每次具体答案可不同。"},{"a":"训练算力","b":"推理算力","diff":"训练需要大规模并行、一次跑很久；推理每次只需一次前向计算，量小但调用次数巨大。"},{"a":"预训练","b":"微调 Fine-tuning","diff":"预训练是在海量通用数据上从零或从基础训练；微调是在预训练权重上用少量领域数据再小规模训练，快速适配某一任务。"}]},{"type":"mistakes","items":["以为『每回答一次，模型就变聪明一点』——不，训练阶段才改参数，推理回答是只读调用。","以为『训练的成本 = 我用它的成本』——错，训练是一次性的昂贵投入，推理按量计费。","以为『模型每次回答不同＝模型在更新』——多数差异来自推理时的随机采样，不是参数在变。","以为『微调 = 推理』——微调本质是小规模训练（改参数），只是数据量小、时间短。","以为『模型能力不足时，靠多问几次就能提升』——能力在训练定型，用量不能改变能力上限，只能换策略或换模型。"]},{"type":"deep","title":"深入一点：参数、权重与『训练到底在改什么』","beginner":["一个神经网络由大量『神经连接』组成，每条连接有一个数字叫权重（参数）。模型的『知识』就存在这些数字的分布里。","训练就是反复调整这几亿甚至上千亿个数字，让它们最终能很好地完成预测任务。","'预训练'让模型具备通用语言能力；'微调'在此基础上小幅调整让它更听话或更专业。"],"advanced":["训练就是最优化：目标函数（Loss）对每个参数求梯度，用梯度下降更新，让 Loss 越来越小。这个『更新参数』的循环在训练阶段发生，推理阶段参数冻结不动。","推理只有『前向传播』：输入 → 逐层计算 → 输出，不更新任何参数。这也是为什么推理远快于训练——少了反向传播这一步。","工程视角：训练需要反向传播、梯度累积、学习率调度、数千张卡并行；推理需要 KV 缓存、量化、批处理、KV-cache 复用来降低延迟与成本。同一模型，训练与部署是两套完全不同的工程问题。"]},{"type":"exercise","prompt":"有人问你：『为什么我让同一个 AI 写一篇关于猫的文章，两次得到的开头不一样？』最合理的解释是？","opts":["模型在这期间偷偷重新训练了","推理阶段有随机采样，同样的输入可能得到不同的输出","因为我没联网","因为模型是我提问时才被造出来的"],"a":1,"explain":"训练阶段已定型，参数不变；两次回答的差异来自推理采样时的随机性（温度/采样），属于正常现象。","jump":"sec5-step3","jumpLabel":"推理中：来一个输入现场算一次"},{"type":"check","title":"结课检测：训练 vs 推理你分得清吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"训练阶段，模型在做什么？","opts":["逐层前向计算并给出答案（不改参数）","反复预测-对答案-调整参数，直到误差降低","什么都不做，只是被部署","只在用户提问时才运行"],"a":1,"explain":"训练的核心循环是『预测 → 算 Loss → 反向传播更新参数』，一直重复到误差可接受。推理阶段才不再改参数。","jump":"sec5-step1","jumpLabel":"训练中这一层"},{"q":"『按 Token 用量收费』，付的是哪个阶段的成本？","opts":["训练成本","每次使用的推理成本","买电脑的钱","数据采集成本"],"a":1,"explain":"线上大模型按你每次提问消耗的 token 计费，覆盖的是推理阶段每次前向计算的算力成本，不是一次性训练费。","jump":"sec5-step4","jumpLabel":"推理的成本与速度"},{"q":"微调（Fine-tuning）本质上更接近哪件事？","opts":["纯推理","一次小规模的训练","只是改提示词","重新从零预训练"],"a":1,"explain":"微调是在预训练权重上用少量数据再调整参数（反向传播），本质是一次数额小、数据少的训练。","jump":"sec6","jumpLabel":"微调这个现实案例"},{"q":"模型的『能力上限』主要由什么决定？","opts":["每次提问时的随机采样","训练阶段（数据、架构、规模）","用户的打字速度","网络的带宽"],"a":1,"explain":"能力在训练阶段定型；推理只是把已定型的参数拿出来做预测，不能提升能力上限。","jump":"sec5-step2","jumpLabel":"训练完这一层"}],"done":"现在你分清了『学（训练）』和『用（推理）』。可模型到底在拿什么『学』、在『学』什么？下一课我们把 AI 的三大原料——数据、模型、参数——逐个说透。","nextLesson":"pl-data"},{"type":"connection","known":["AI ⊃ ML ⊃ DL 的包含链（上一课）","模型是被训练出来的产物"],"learned":["训练 vs 推理的本质区别（改参数 vs 用参数）","训练一次性昂贵、推理按量计费","为什么同一模型每次回答可能不同（采样随机性）","微调 = 小规模训练；幻觉来自推理时预测而非自知"],"next":"训练的『原料』是什么？下一课《数据、模型与参数》告诉你 AI 学习的三要素，以及为什么『数据』往往比模型大小更关键。","links":[{"href":"#/lesson/l00-ai-world","text":"复习 AI 世界总图"},{"href":"#/lesson/l05-gradient-descent","text":"预看《损失函数与梯度下降》"}]}]},"v01-web":{"id":"v01-web","title":"一个 Web 产品是怎么跑起来的","subtitle":"你在浏览器里敲回车到内容出现，中间发生了什么？把这条链路看懂，你才谈得上『改对地方』。","course":"vibe","courseNo":"01","level":"base","estTime":"15-25 分钟","difficulty":1,"concepts":[],"prereqLessons":[],"nextLesson":"v02-git","sections":[{"type":"opening","question":"你每天打开网页、用 App、点外卖、刷视频——但有没有想过，你在浏览器地址栏输入一串字母并按下回车，到底是哪台机器、用哪段程序、按什么顺序，把你要的内容送到你面前的？","guess":"很多人会回答「就是电脑把网站打开了呀」。","next":"这节课我们不写代码，只把『一个 Web 产品』从头到尾拆开：前端、后端、数据库、服务器、浏览器、网络各是什么，数据是怎么一层层流动的，以及每一层出错时你该怀疑谁。学完你就能对着一屏『转圈』或一条报错，说出它大概死在哪个环节。"},{"type":"why","before":"你想用 AI 辅助做一个自己的小产品（一个网页、一个小工具、一个小网站）。AI 很会写代码，但你写完点开经常『跑不起来』或『一片空白』，你不知道该往哪看。","problem":"问题不在 AI 写的代码——而在于你对『这段代码在什么环境里跑、和谁通信』没有概念。你分不清『报错是我的 HTML 写错了』『还是服务器没启动』『还是数据库没连上』『还是网络被墙了』。于是只能把同样的问题反复丢给 AI，越问越乱。","need":"所以第一课先不碰一行代码，而是先建立『一台 Web 产品从上到下有哪些层、每层做什么』的骨架。当你把『前端 / 后端 / 数据库 / 服务器 / 浏览器 / 网络协议』这条链装进脑子，AI 给的报错就不再是天书，而是能对号入座的线索。"},{"type":"oneline","text":"一个 Web 产品 = 浏览器（前端，负责看得见摸得着的界面）+ 服务器上的程序（后端，负责处理逻辑和读写数据）+ 数据库（负责长期存数据），它们之间靠『网络请求』（HTTP）搬来搬去；而这一切最终都跑在『操作系统 + CPU/内存/磁盘』这台物理机器上。"},{"type":"visual","kind":"request-flow","title":"互动实验：点一次请求，看它走完整条路","hint":"点击『发送请求』，看一次『用户敲回车』的动作如何依次经过浏览器 → DNS 解析 → 网络 → 服务器 → 后端程序 → 数据库 → 再原路返回。每亮起一格就说明数据到了哪一层。"},{"type":"intuition","blocks":[{"k":"用点外卖来想","t":"前端＝你看得到的『点单 App 界面』；后端＝『餐厅后厨，负责接单、炒菜、出餐』；数据库＝『冷库里长期保存的食材和菜谱』；服务器＝『餐厅所在的整栋楼，有水电（CPU/内存/磁盘）』；浏览器就是那个帮你点单、再把菜端到你面前的『外卖小哥』。你看到的每一道菜，都是后厨＋冷库＋外卖小哥协作的结果。"},{"k":"用写信来想","t":"你在浏览器输入网址，就像写一封信：『地址』（域名）要翻译成具体的『门牌号 + 邮编』（IP + 端口），信通过『邮政网络』（网络/IP）送出去，邮局先查收信人住在哪（DNS 解析），送到后对方拆信、处理、再回信。回信能不能到，取决于信中地址写没写对。"},{"k":"一句话记住分层","t":"从上到下：浏览器（前端）→ 网络（DNS/IP/HTTP）→ 服务器 → 后端程序 → 数据库。数据请求沿这条链往下，响应再原路往上。出错时按这条链一层层排查，永远不要跳着乱试。"}]},{"type":"how","intro":"把『输入网址到页面出现』拆成一条 7 步因果链。每一步都回答『数据此刻在哪、谁在处理、为什么能做下一步』。","steps":[{"in":"① 你输入网址，按下回车","process":"浏览器得到一串人类好记的名字，比如 ai-learn.example.com。但网络本身不认名字，它只认数字地址（IP：像 203.0.113.7）。所以第一步要『翻译』。","out":"浏览器准备发起一次『网络请求』"},{"in":"② DNS 解析：把域名翻译成 IP","process":"浏览器向 DNS（域名系统）询问：ai-learn.example.com 对应哪个 IP？DNS 就像电话簿，查到后把『数字地址』告诉浏览器。没有这一步，浏览器不知道该把信寄到哪台机器。","out":"得到了服务器的 IP 地址 + 端口（默认 80/443）"},{"in":"③ 建立连接 + 发送 HTTP 请求","process":"浏览器通过 TCP（可靠的传输协议）连上服务器，然后发送一个『HTTP 请求』：里面写着『我要 GET 这个页面』，还带着浏览器自己是谁（User-Agent / Cookie）等信息。","out":"请求沿着网络，送到那台服务器的指定端口"},{"in":"④ 服务器接收并把请求交给后端程序","process":"这台机器上正跑着一个『服务器进程』（如 Nginx / Node / Python）。它把请求转交给对应后端程序；后端程序执行你自己的业务逻辑：查一查、算一算。","out":"后端程序开始处理：可能要读数据库"},{"in":"⑤ 后端读写数据库","process":"需要持久数据的，后端会去数据库查询或写入。数据库把结果（比如『这个用户的名字』）返回给后端。注意：数据库不住在浏览器里，它住在服务器那台机器上。","out":"后端拿到数据，拼出一份『响应』"},{"in":"⑥ 后端返回 HTTP 响应","process":"后端把生成的 HTML / JSON / 图片，打包成一条『HTTP 响应』发回去，附带状态码（200 成功 / 404 找不到 / 500 服务器出错）与响应头。","out":"响应沿着网络原路回到浏览器"},{"in":"⑦ 浏览器解析并渲染","process":"浏览器收到 HTML，逐行解析：先搭出页面结构，再拉取其中的 CSS/JS/图片等资源，最后把内容画到屏幕上。你这才『看到』了页面。","out":"页面出现在你眼前（一次完整的前后端往返）"}]},{"type":"realworld","items":[{"name":"你平时的网页 = 前端静态页","note":"很多『首页』其实只是浏览器直接渲染的一堆 HTML/CSS/JS 文件，可能根本没有后端。它依然需要前面的 ①②③⑦ 几步，但没有 ④⑤⑥。知道这一点，你排查为何『页面能开但功能没反应』时就能猜到问题多半在后端那段。."},{"name":"登录注册 = 必须有后端 + 数据库","note":"『注册新账号』必须把密码/信息写进数据库，所以必然经过完整的 ①→⑦。前端只是收集输入，真正的校验和存储都在后端 + 数据库。这是『看代码时』判断某功能是否需要后端的标尺。"},{"name":"动态内容（推荐、订单、消息）= 后端在返回数据","note":"你刷到的『为你推荐』是后端程序实时查库、算好、再以 JSON 返回给前端渲染的。这类功能换任何界面（网页/App/小程序）后端代码都基本相同——这也是为什么『前后端分离』这么常见。"},{"name":"云服务器 / 租一台机器","note":"你的产品真正上线后，就『住』在一台云服务器（如腾讯云、阿里云的 ECS）上，这台机器有操作系统、CPU、内存、磁盘，常年开机。你的前端文件、后端程序、数据库都装/跑在这上面。"}]},{"type":"compare","pairs":[{"a":"前端 Frontend","b":"后端 Backend","diff":"前端＝用户看到的界面（运行在浏览器/手机里，负责渲染和交互）；后端＝用户看不到、运行在服务器上的程序（负责业务逻辑、鉴权、读写数据库）。前端决定『长什么样、能不能点』，后端决定『数据对不对、安不安全』。"},{"a":"接口 API","b":"直接操作数据库","diff":"后端对外提供的是『接口（API）』——一个约定好的请求地址与返回格式；前端只调用接口，永远不直接连数据库。这样可以隔离权限、便于维护。这也是产品安全的第一道墙。"},{"a":"本地 localhost","b":"线上服务器","diff":"你在自己电脑上跑的前后端叫『本地环境』，地址常是 localhost:3000；部署上线后跑在云服务器上，是公网地址。很多『本地正常、线上挂』的问题，都源于两套环境不完全一样（如数据库没迁移、环境变量没配）。"},{"a":"TCP（可靠）","b":"UDP（快速但不可靠）","diff":"TCP 会确认每份数据都到达（网页、文件用），UDP 不确认、丢了就丢（实时音视频、游戏用）。Web 的 HTTP 默认走 TCP，所以网络差时表现为『加载慢/卡』而不是『内容错乱』。"}]},{"type":"mistakes","items":["以为『网页能打开 = 后端没问题』——错，很多页面是纯前端静态页，后端可能根本没启动。","报错时随手把错误原样丢给 AI，而不说清『发生在哪个层』——AI 只能瞎猜。正确做法是先定位：报错来自浏览器控制台、后端终端、还是数据库连接？","以为『改完代码点刷新就行』——前端改了刷新即可，后端改了常常要重启服务才能生效；数据库结构改了还要迁移。不知道该不该重启，等于不知道该层是否生效。","把 IP、域名、端口混为一谈——域名给人记，IP 给网络认，端口标识这台机器上『哪个程序在服务』。三者不同。","以为 AI 写的代码『放对文件夹就能跑』——代码必须在『正确的环境』（装好依赖、正确版本、正确目录、可执行的权限）里才能运行。环境对不上，代码再对也是白搭（这正是第 7 课上线的核心矛盾）。"]},{"type":"deep","title":"深入一点：把『机器、程序、运行方式』讲透","beginner":["这台电脑/服务器里面有什么？三样最关键的硬件：","**CPU**（中央处理器）：真正会『算』的部分，负责执行指令。它快、但几乎没有记忆。","**内存 RAM**：临时、高速的『草稿本』，程序运行时把正在用的东西放这里；一断电全清空。","**磁盘 Disk**：长期、慢速的『仓库』，文件、数据库、图片都躺在这；断电也保留。","三者关系：程序从『磁盘』读进来 → 在『内存』里运行 → 由『CPU』逐条执行。所以『进程/线程』就是运行中的程序在内存和 CPU 上的具体存在。","**操作系统（OS）**：介于硬件和你程序之间的大管家。它负责：管理文件、管理进程、分配内存、读写磁盘、管理网络与权限。你的程序不是直接拿 CPU 干活，而是『请操作系统帮你安排』。Windows / macOS / Linux 都是操作系统。"],"advanced":["**编译 (Compile) vs 解释 (Interpret)**：代码有两种变可执行的方式。编译型（如 C、Go）：先整体翻译成机器码，再运行，快但改后要重新编译；解释型（如 Python、JavaScript）：一边翻译一边运行，改了就生效，但慢。","**Runtime（运行时）**：指『解释器 / 虚拟机 / 平台环境』，如 Node.js（能让 JS 在服务器上跑）、Python 解释器、Java 虚拟机（JVM）、浏览器的 JS 引擎（V8）。同一个 JS 文件，在浏览器里和 Node 里跑，用的是不同 Runtime——所以『它在浏览器能跑，不代表服务器能跑』。","**进程 (Process) vs 线程 (Thread)**：进程＝一个独立运行的程序实例，有自己独立的内存（跑崩一个不影响别的）；线程＝进程内部可并发的轻量任务单元，共享进程内存。一个 Node 服务通常是一个进程，一次请求常会用到多个线程/异步任务来并行处理。","**文件 / 路径 / 权限**：一切配置、代码、静态资源都是『文件』，文件有『路径』（在哪个文件夹）和『权限』（谁能读/写/执行）。很多部署报错是『权限不够』（403）或『路径不对』（404）——这不是代码逻辑问题，而是环境问题。","**环境 (Environment)**：你的程序依赖很多东西：命令、依赖包、环境变量、数据库地址、端口。这些合称『运行环境』。第 7 课上线的本质，就是把『你本机那套环境』尽量一致地搬到服务器上。"]},{"type":"ask","title":"怎么用 AI 帮你改代码：先问清『第几层』","scenario":"你的页面打开了，但点击『登录』没反应，控制台报了个错。怎么把这个信息高效地交给 AI？","template":"[我要描述] 我在做一个登录功能，点击登录按钮后页面没反应。\n[它能观测到的现象] 浏览器控制台报错：Cannot read properties of undefined (reading 'catch')，出错在 main.js 第 42 行。\n[我判断在哪一层] 前端 JS 在做请求时出错（尚未到后端）。\n[请给我] 帮我定位 main.js 第 42 行为什么报错，并给出修复方案与原因。","acceptance":["AI 给的答案里是否指明了『问题所在的那一层』（前端/后端/数据库/网络/环境）？","修复方案是否同时告诉你『为什么之前会错』（因果），而不只是『把这段换成这段』？","改完是否教你该怎么验证（例如：刷新？重启后端？看哪个日志？）？","如果 AI 只给了代码而你仍不确定，是否会继续追问『这个报错出现在哪一层、我怎么验证』？"],"tip":"给 AI 的信息越『分好层』，它越能准确判断。‘分层 + 现象 + 报错 + 我的判断’ 四件套，能大幅减少来回试错。"},{"type":"exercise","prompt":"你在浏览器打开自己刚做的网站，页面显示出来了，但点『提交表单』后页面一点反应都没有，浏览器控制台也没报错。根据这一课的分层，你最应该先怀疑哪一层？","opts":["我的 HTML 结构写错了（前端静态层）","后端程序没启动或没连上（后端层）","我的屏幕/显卡坏了（硬件层）","域名没过期（网络层）"],"a":1,"explain":"页面能正常显示说明前端静态层基本没问题；但『提交表单』要发请求给后端，没反应最可能是后端没启动、路径不对、或请求根本没发出去。先检查后端服务在不在跑、接口地址对不对。","jump":"sec7-step3","jumpLabel":"第 ④ 步：服务器接收并把请求交给后端"},{"type":"check","title":"结课检测：你能给报错『分层』了吗","intro":"共 5 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"浏览器里 DNS 解析这一步骤主要解决什么问题？","opts":["把域名翻译成 IP 地址","把 HTML 渲染成画面","把代码编译成机器码","把密码加密"],"a":0,"explain":"网络只认数字 IP，DNS 负责把人类好记的域名翻译成 IP，浏览器才知道该把请求发到哪台机器。","jump":"sec5-step1"},{"q":"『注册新账号后数据能永久保存』，这件事主要由哪几层协作完成？","opts":["只有浏览器（前端）","后端程序 + 数据库，前端只负责收集输入","只有网络（TCP/IP）","只有操作系统"],"a":1,"explain":"注册必须把信息写入数据库才叫『永久保存』；后端程序负责接收并由数据库落盘，前端只是收集输入。","jump":"sec5-step4"},{"q":"『代码在浏览器能跑』是否代表『同样的代码在服务器上也能跑』？","opts":["一定可以","不一定，因为浏览器和 Node/Python 是不同的 Runtime","一定不可以","只和网速有关"],"a":1,"explain":"浏览器里的 JS 由浏览器 JS 引擎跑，服务器上的 JS 由 Node.js 跑，是不同的 Runtime，能力与可用模块不同。","jump":"sec7"},{"q":"一个『Web 产品』由前端、后端、数据库组成。下面哪句最准确？","opts":["前端能直接连接数据库","后端程序通过接口把数据给前端，数据库由后端访问","数据库必须放在浏览器里","后端程序只能写死数据，不能读数据库"],"a":1,"explain":"前端只调用后端提供的接口(API)，后端负责访问数据库并返回结果，这样能隔离权限、便于维护。","jump":"sec7-step5"},{"q":"某功能『本地 localhost 一切正常，部署到线上就报数据库连不上』，最可能是哪两类环境不一致？","opts":["前端字体大小不同","数据库地址/密码/环境变量，以及迁移状态不一致","屏幕分辨率不同","键盘语言不同"],"a":1,"explain":"本地与线上最多的差距是数据库连接信息（地址、账号、密码）、环境变量配置，以及数据库结构是否已迁移。","jump":"sec7"}],"done":"你现在能把『一个 Web 产品』按层拆开了——前端、后端、数据库、服务器、网络各归其位，报错也能分到对应层。下一课我们钻到『后端』这一层：HTTP 到底是什么，API 怎么写、怎么调。","nextLesson":"v03-api"},{"type":"connection","known":["（这是 Vibe Coding 路径的第一课，默认你已经上过《从零看懂 AI》路径或至少了解『模型/产品』概念。）"],"learned":["一个 Web 产品 = 前端 + 后端 + 数据库 + 服务器 + 网络，彼此通过 HTTP 通信","一次请求的 7 步因果链：输入地址 → DNS → 建立连接/HTTP → 服务器 → 后端 → 数据库 → 渲染返回","CPU / 内存 / 磁盘 / 操作系统 / 进程 / 线程 / 编译解释 / Runtime 的定位","前端 / 后端 / 接口 API / 本地 localhost / 线上 的区别","给 AI 提问前先给报错『分层』，能显著提高一次成功率"],"next":"下一步我们进入『后端』层。想了解 AI 生成/理解代码，可回看 AI 路径的《AI Coding》一课；想把这条链路里『数据是怎么被长期记住的』讲透，下一课（API 与后端）与再下一课（数据库、登录与安全）会分别展开。","links":[{"href":"#/lesson/l22-ai-coding","text":"回看 AI 路径《AI Coding：把 AI 变成结对程序员》"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},"v02-git":{"id":"v02-git","title":"Git 与版本控制：改坏了能回退","subtitle":"AI 会帮你写很多代码，也会帮你挖很多坑。Git 就是你的『时光机』：每次改动都能留下脚印，随时能回到任意一个能跑的状态。","course":"vibe","courseNo":"02","level":"base","estTime":"15-25 分钟","difficulty":1,"concepts":["git","version-control","commit","rollback"],"prereqLessons":["v01-web"],"nextLesson":"v03-api","sections":[{"type":"opening","question":"你让 AI 帮你改了三版代码，第三版比第一版还烂，可你已经不记得第一版长什么样了。或者，你一次『大手笔』改动了 20 个文件，结果整个网站跑不起来了，你该从哪开始往回找？","guess":"很多人会一边叹气一边‘硬改回来’，或者干脆重写一遍。","next":"这一课教你用 Git 给项目装一台时光机：学会『提交快照』、『回到过去』、『看谁改了什么』。从此，你再也不用怕 AI 挖坑——任何时候都能一键回退到能用的时候。"},{"type":"why","before":"你在 Vibe Coding 里高频迭代，AI 每天都在‘改这改那’，你分不清哪次改对了、哪次改坏了。","problem":"没有版本意识时，一切改动都是一次性赌注：改坏了只能干瞪眼，重写又怕丢东西，联合 AI 调试也像无头苍蝇。","need":"你需要一个能记录每次改动、允许你随时回到任何历史状态的工具。Git 就是这个工具——它是所有 AI 编程、团队协作、正式上线的地基。"},{"type":"oneline","text":"Git 是一个版本控制工具：它把项目的每一次改动分别保存成一个个『快照（提交/commit）』，你可以在任意两个快照之间来回切换、对比、合并与回退，相当于给整个代码库装了‘存档 + 读档’功能。"},{"type":"intuition","blocks":[{"k":"用游戏存档来想","t":"Git 就像游戏里的存档系统：每过一关（每次你确认‘行，就这样’）就存一次档。后来玩砸了（改坏了），不用从头再来，直接读档回到上一个存档点。存档点就是 commit。"},{"k":"用写作文改稿来想","t":"你写作文时会保留每一稿：初稿、改一稿、改二稿。每一个‘稿’都是一个版本，你随时能翻回去看最初写得多烂，也能一句句对比改了什么。Git 就是自动帮你留稿，还能任意回看。"},{"k":"三棵树记法","t":"Git 有‘三棵树’：工作区（你正在改的文件）、暂存区（你选定了要记录的改动）、版本库（已正式存档的历史）。顺序是：改文件 → 加进暂存区（git add）→ 提交存档（git commit）。‘提交’就是按下存盘键。"}]},{"type":"how","intro":"一套最简 Git 工作流，五步。你不需要记一堆命令，只记这条主干循环。","steps":[{"in":"① 初始化仓库：git init","process":"在项目根目录执行 git init，Git 就会开始悄悄跟踪这里的所有改动。这相当于宣布‘从今天起，这个文件夹纳入版本管理’。","out":"一个 git 仓库（.git 目录），开始记录历史"},{"in":"② 查看改动：git status","process":"随时运行 git status，Git 告诉你哪些文件被改了、哪些是新增的、哪些还没被跟踪。这是每次动手前后的‘体检’。","out":"清楚当前工作区里有哪些变动"},{"in":"③ 选定要记录的内容：git add","process":"把你想纳入这份快照的文件加入暂存区。可以全部加（git add .），也可以挑几个加。你决定‘这一份存档里要包含什么’。","out":"文件进入暂存区，等待被提交"},{"in":"④ 正式存档：git commit","process":"执行 git commit，并写一句说明（如‘修复登录按钮’）。这一步像按下存盘键，一个永久、可回退的版本节点就诞生了。","out":"一个带说明的历史版本（commit）"},{"in":"⑤ 回退与查看历史：git log / git checkout / git reset","process":"用 git log 看所有历史版本；改坏了用 git checkout 或 git reset 回到某个 commit；git diff 对比两个版本差别。这就是你的时光机操作台。","out":"随时能回到任意能跑的历史状态"}]},{"type":"realworld","items":[{"name":"每次‘能用’就提交","note":"Vibe Coding 的黄金习惯：只要当前版本能跑、你觉得 OK，就立刻 commit。这会形成一串‘安全的存档点’，让你随便折腾 AI。"},{"name":"提交信息写清楚","note":"写一句人话（‘加了登录’而不是‘改了点东西’），几周后你才知道每个存档里装了什么。AI 生成的代码更要写清楚，否则回退都不知道回到哪。"},{"name":"分支 branch：开一条平行世界","note":"你想大胆试一个新功能又不想搞乱主版本时，开一个分支去折腾，成了再合并回来，毁了就丢。这是团队协作和探索新玩法的基础。"},{"name":"GitHub 远程仓库","note":"把本地仓库推到 GitHub（git push），你的代码就有了云端备份，也方便和 AI/他人协作。这是后续‘部署上线’的前置步骤。"}]},{"type":"compare","pairs":[{"a":"git add","b":"git commit","diff":"add 是把改动选进‘暂存区’（决定存哪些），commit 是正式存档（生成一个永久历史节点）。add 可反复调整，commit 一按即生效。"},{"a":"git checkout","b":"git reset","diff":"checkout 常用于切到某版本查看/恢复单文件，偏‘只管当前状态’；reset 会把仓库指针移回某提交，可能连带影响历史。新手优先用 checkout 更安全。"},{"a":"本地仓库","b":"远程仓库(GitHub)","diff":"本地仓库在你电脑上，随改随存；远程仓库在云端，用于备份、协作、部署。两者靠 push/pull 同步。"},{"a":"没有 Git","b":"有 Git","diff":"没有 Git，改坏了只能靠记忆或重写；有 Git，随便改、随时回退、随手对比，风险大幅降低。"}]},{"type":"mistakes","items":["只在‘做坏了’才想起 git——其实应该在‘做对了’（能跑）时就提交，形成安全存档点。","提交信息乱写甚至不写——几周后完全看不懂每个存档是干嘛的。","把 node_modules、.env 密码等不该提交的文件也提交了——这些要么巨大要么含敏感信息。","一次提交塞了 20 个文件的无关改动——回退和排查时一团乱。每份提交尽量单一、聚焦。","以为 git 会‘自动保存’——不会！你得手动 add + commit。忘了提交 = 没存档。"]},{"type":"ask","title":"怎么用 AI 帮你处理 Git：把报错和意图一起给","scenario":"你想回退一个改动，但不太确定用哪个命令，或者 git 报了一大串英文错误。","template":"[我的意图] 我想把刚改坏的登录功能回到『能跑』的那个版本。\n[我做了什么] 刚刚 commit 了一个修复登录的版本，现在想回到上一个能跑的版本。\n[我看到的报错] git 提示：error: Your local changes to the following files would be overwritten by checkout...\n[请给我] 告诉我这个报错是什么意思，应该用哪个命令安全回退，并且不要丢我现在还没提交的改动。","acceptance":["AI 是否先解释了报错的含义，而不是直接丢命令？","是否提示了‘会覆盖未提交改动’这类风险，让你确认后再执行？","是否给出安全回退的具体命令序列？","是否提醒你在回退前先 commit 或 stash，避免丢失当前工作？"],"tip":"亲手学会 git 三个核心动作（add/commit/checkout），其余的交给 AI 也行——但你要能看懂它在给你做什么、会不会有风险。"},{"type":"exercise","prompt":"你让 AI 改了代码，然后手动运行发现网站跑不起来了。你希望回到‘之前的能跑版本’。下面哪个动作是你应该先确认的？","opts":["立刻 git commit，把坏掉的也存档一份","先 git log 找到最近一个能跑版本的提交编号，再据此回退","直接删掉整个项目文件夹重新开始","啥也不做继续改"],"a":1,"explain":"正确做法是先 git log 定位到能跑的那次提交，再用 git checkout / reset 回退到该版本。把坏版本也 commit 存档（选项 1）反而制造了更多坏存档，不是首选。","jump":"sec5-step4","jumpLabel":"回退与查看历史这一步步"},{"type":"check","title":"结课检测：你掌握 Git 时光机了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回对应段落复习。","questions":[{"q":"Git 里‘存档点’的正式名称是什么？","opts":["分支","提交 (commit)","暂存区","工作区"],"a":1,"explain":"commit（提交）就是保存一个可回退的历史快照，相当于游戏存档点。","jump":"sec5-step3"},{"q":"正确的‘三棵树’操作顺序是？","opts":["commit → add → 修改","修改文件 → git add → git commit","git add → 修改 → git commit","git commit → git checkout"],"a":1,"explain":"顺序是：先在工作区修改文件，再用 git add 选入暂存区，最后 git commit 正式存档。","jump":"sec5-step2"},{"q":"为什么 Vibe Coding 强调‘能跑就立刻 commit’？","opts":["为了显得专业","形成安全存档点，之后随便让 AI 折腾都能回退","提交越多代码越少","Git 会自动备份"],"a":1,"explain":"每个能跑的 commit 都是一个安全存档点，AI 后续怎么改坏了都能一键回到这个状态。","jump":"sec5-step4"},{"q":"下面哪类文件最不应该被提交到仓库？","opts":["源码 js 文件","含密码/密钥的 .env 等敏感配置","html 页面","readme 说明"],"a":1,"explain":"敏感配置（.env 含密钥）绝不应提交，否则会被泄露；这类通常放进 .gitignore。","jump":"sec6"}],"done":"你现在有了自己的时光机：能存档、能回退、能对比，再也不怕 AI 挖坑了。下一课进入后端：API 到底是什么，前后端怎么在 HTTP 里对话。","nextLesson":"v03-api"},{"type":"connection","known":["你已了解一个 Web 产品的分层（v01）、AI 会挖坑的风险（Vibe 课核心）"],"learned":["Git = 版本控制的存档系统，add/commit/checkout 主干循环","‘能跑就提交’形成安全存档点，是 AI 编程的兜底","分支、远程仓库、.gitignore 等进阶用法","给 AI 处理 Git 报错时的安全提问方式"],"next":"自这一步开始，你的每次改动都有据可查。下一课我们进入后端层：API 与 HTTP——前后端到底是怎么说话的。","links":[{"href":"#/lesson/v03-api","text":"下一课：《API 与后端：前后端怎么对话》"},{"href":"#/lesson/v01-web","text":"回看《一个 Web 产品是怎么跑起来的》"}]}]},"v03-api":{"id":"v03-api","title":"API 与后端：前后端怎么『对话』","subtitle":"前端要数据、后端给数据，靠的是一套约定好的『暗号』——HTTP 方法与状态码。看懂它对 AI 来说轻而易举，对你是判断代码靠不靠谱的分水岭。","course":"vibe","courseNo":"03","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web"],"nextLesson":"v04-db","sections":[{"type":"opening","question":"你的 App 在前端里点了个『收藏』按钮，后端怎么知道你要『新增一条收藏』而不是『删除一条』？同样是敲同一个接口地址，凭什么这次是加分、那次是删东西？","guess":"很多人会说『靠传一个名字不一样的按钮』。","next":"答案藏在 HTTP 的『方法（Method）』里。这一课我们把前后端之间的对话协议——HTTP 方法和状态码——彻底讲透：GET 和 POST 到底差在哪，200/404/500 各代表什么，什么是 API、什么是 JSON。学完你会开始『读』接口而不是『猜』接口。"},{"type":"why","before":"AI 写了个后端接口，前端也调了。你看着代码：有一堆 `app.get('/api/friends')`、`app.post('/api/friends')`、`req.body`、`res.json(...)`。你不懂为什么有的用 get 有的用 post，也不知道返回的 `{status:'ok', data:[...]}` 是什么。","problem":"不懂 HTTP 方法与状态码，你会犯两种错：要么把『该用 POST 写数据的操作』写成了 GET，导致数据带在 URL 里、既不安全又不支持大内容；要么拿到报错号 404/500 完全没概念，不知道该看前端还是后端。AI 生成的代码你再不敢动，一改就崩。","need":"把 HTTP 的『动词』（方法）、『回执』（状态码）、『货单』（请求/响应头与正文 JSON）看明白，你就拥有了『判断一段接口代码对不对』的最小能力：方法对不对、状态码合不合理、参数传没传对。这正是把 AI 代码从『能跑』升级到『可靠』的一步。"},{"type":"oneline","text":"API 是后端对外开的一扇扇门（URL），你用『HTTP 方法』说明你想干嘛（GET 拿数据 / POST 新增 / PUT 整体更新 / PATCH 部分更新 / DELETE 删除），后端用『状态码』告诉你结果（2xx 成功 / 4xx 你这边的问题 / 5xx 服务器的问题），数据通常以 JSON 格式在请求和响应里传递。"},{"type":"visual","kind":"http-viewer","title":"互动实验：HTTP 查看器，亲手发一个请求","hint":"选一个方法、填一个地址（或点预设接口），点『发送』。它会向你展示：这次请求带了哪些方法/头部/参数，服务器会返回什么状态码与 JSON 正文，以及每个状态码对应的含义。体会『同一个 URL，方法不同 = 动作不同』。"},{"type":"intuition","blocks":[{"k":"用餐厅点菜来想","t":"API 地址（URL）＝餐厅的『窗口名』，比如『/api/friends』是『朋友窗口』；HTTP 方法＝你点菜的动作——‘看看今天的菜单’（GET）、‘点一个菜’（POST）、‘把整个菜换掉’（PUT）、‘加个辣’（PATCH）、‘退掉这个菜’（DELETE）。后端（厨师）按你的动作处理，再用状态码告诉你：‘上菜了’（200）、‘这个菜没有’（404）、‘厨房炸了’（500）。"},{"k":"用寄快递来想","t":"GET 就像‘查单号’——只读，不改变任何东西，可以来很多次；POST 就像‘下单寄件’——会产生一个新的快递（新增数据）。所以‘收藏、下单、注册、发帖’这些会新增数据的操作用 POST，而‘翻页、搜索’这种只看不动的用 GET。"},{"k":"一句话记住状态码","t":"2 开头的都成功；3 开头的是‘让你去别处看’（重定向）；4 开头的是‘你（客户端）的问题’（404 找不到、401 没登录、403 没权限、400 请求写错）；5 开头的是‘服务器（后端）的问题’（500 内部出错）。看到 4 或 5，你就能立刻判断该检查哪一边。"}]},{"type":"how","intro":"把一个 HTTP 请求拆成 5 个部分，从头到尾走一遍『前端 → 后端 → 响应回前端』。","steps":[{"in":"① 请求行：方法 + URL","process":"前端发起一行字：`POST /api/friends`。前半是方法（动作），后半是接口地址（去哪扇门）。这决定了后端接下来执行哪段逻辑。","out":"例如 POST = 新增；GET = 查询；DELETE = 删除"},{"in":"② 请求头 Headers","process":"附带的一堆元信息：Content-Type（正文是 JSON 还是表单）、Authorization（登录凭证，如 Bearer token）、Accept（你想要什么格式）、携带的 Cookie 等。后端靠这些判断『你是谁、你给的是什么』。","out":"身份与格式声明"},{"in":"③ 请求正文 Body","process":"POST / PUT 需要把要写入的数据放进正文，通常是 JSON：`{\"name\":\"小明\",\"phone\":\"138...\"}`。GET 一般没有正文，参数放在 URL 查询串里（?name=小明）。","out":"数据内容（多为 JSON）"},{"in":"④ 后端处理并返回状态码","process":"后端读到方法+地址+头+正文，跑对应的逻辑，无论成败都返回一个状态码：成功 200/201，找不到 404，参数错 400，没登录 401，服务器异常 500。","out":"状态码：2xx / 4xx / 5xx"},{"in":"⑤ 响应正文 + 响应头","process":"成功后后端通常返回一个 JSON：`{\"ok\":true,\"data\":{...}}`，前端拿到这个结构再决定如何渲染。响应头里也常有 Set-Cookie、Cache-Control 等控制信息。","out":"前端拿到 JSON，渲染到界面"}]},{"type":"realworld","items":[{"name":"浏览器开发者工具 Network 面板","note":"按 F12 → Network，你能亲眼看到每一笔请求：方法、URL、状态码、耗时、请求/响应头与 JSON。这是『读接口』最重要的工具，AI 给不了你，但它能解释你从里面截到的任何一行。"},{"name":"REST 设计风格","note":"REST 是一套流行的接口组织约定：把『资源』当名词放 URL（/users、/posts），把动作当方法（GET/POST/PUT/DELETE）。例如 GET /users/5 读用户5，DELETE /users/5 删用户5。看懂 REST，你便看懂了大半后端代码的结构。"},{"name":"第三方开放 API（天气/支付/地图）","note":"你在产品里调的天气、支付、地图接口，就是对面公司后端暴露的 API。你会看到它要求固定方法、固定鉴权头（Authorization/ApiKey）、返回固定 JSON 结构。会读 API 文档 = 会接第三方能力。"},{"name":"前后端分离项目","note":"很多现代项目前端与后端是两个独立工程，只通过一组 API 契约对接。只要接口约定不变，前端可以换成任何形态（网页/App/小程序），后端完全不用改。这也解释了为什么『接口规范』如此重要。"}]},{"type":"compare","pairs":[{"a":"GET","b":"POST","diff":"GET 用于『读』数据：参数放 URL，可分享/可缓存，不应产生副作用（不会改服务器的数据）；POST 用于『写』数据：参数放正文，用于新增/提交，会产生副作用。安全与不大数据量的操作用 GET，会改数据的操作用 POST。"},{"a":"状态码 4xx","b":"状态码 5xx","diff":"4xx 是『客户端问题』：请求写错、没登录（401）、没权限（403）、找不到（404）——请检查你前端发出去的请求；5xx 是『服务器问题』：后端代码异常（500）、超时（504）——请检查后端日志。"},{"a":"REST API","b":"GraphQL","diff":"REST 靠『多个端点 URL + 方法』组织接口；GraphQL 靠『一个端点 + 查询语句』按需取字段。REST 更简单通用、生态大；GraphQL 更灵活但要学查询语法。入门从 REST 开始最稳。"},{"a":"JSON","b":"表单 Form-encoded","diff":"JSON 是一种结构化文本（{\"k\":v}），后端好解析、支持嵌套，是现代 API 主流；传统表单格式（a=1&b=2）较简单但在复杂数据前吃力。看到 Content-Type: application/json 就知道后面是 JSON。"}]},{"type":"mistakes","items":["AI 常犯（也常让你中招）的错误案例①：把『该用 POST 的新增操作』写成了 GET，导致密码等敏感数据出现在 URL / 日志里，既不安全又不支持大内容。","错误案例②：删改操作应返回合适状态码，却一律返回 200——前端永远‘成功’，数据却没被真正删掉。看到代码里所有分支都 res.json({ok:true}) 且不看状态码，就要警惕。","错误案例③：前端没把 token/Cookie 带上（没设置 headers.Authorization），导致后端每次回 401；前端却把锅甩给‘后端 bug’。判断法：看 Network 里那次请求的请求头带没带凭证。","把 404 理解成‘页面不见了’就完事——404 也可能是‘接口地址写错’，要不检查前端 URL，要不检查后端路由。/api/users 与 /api/user 差一个字母就是两个世界。","盲目照抄 AI 生成的接口而不看返回结构：前端拿 res.data.data 却和接口对不上，出来全是 undefined。学会看 Network 里真实的 JSON 结构再写渲染。"]},{"type":"deep","title":"深入一点：怎么判读一段 AI 写的接口代码","beginner":["拿到 AI 写的后端接口，按下面三问逐一看，就能快速判断靠不靠谱：","**一问方法**：这个操作该不该用这个 HTTP 方法？读操作用 GET，写操作用 POST/PUT/DELETE。方法不对 = 语义错。","**二问状态码**：成功路径返回 2xx 吗？参数错返回 400 吗？没登录返回 401 吗？没有的数据返回 404 吗？服务器异常会抛 500 吗？一个只返回 200 的接口是不合格的。","**三问数据流**：后端取参数的字段名，和前端传的字段名一致吗（body.name）？返回的 JSON 结构和前端 res.data.xxx 对得上吗？对不上就是坑。"],"advanced":["**express（Node 后端框架最小示例）**：","```js\napp.get('/api/users/:id', async (req, res) => {\n  const user = await db.one('SELECT * FROM users WHERE id=$1', [req.params.id]);\n  res.status(200).json({ ok: true, data: user });\n});\n```","注意三件事：`:id` 是路径参数（req.params.id）；操作是读 → 用 GET；成功返回 200。若查不到应 `return res.status(404).json({ok:false})`，而不是硬返回 200 空对象。","**错误处理缺失是最大隐患**：AI 常写出‘只管成功不管失败’的接口。可靠接口要捕获异常并返回 5xx：","```js\napp.post('/api/users', async (req, res) => {\n  try { await db.insert('users', req.body); res.status(201).json({ok:true}); }\n  catch (e) { console.error(e); res.status(500).json({ok:false, msg:'写入失败'}); }\n});\n```","**‘如何向 AI 验收一个接口’**：让 AI 给出‘该方法、正常/异常状态码、请求/响应 JSON 示例’三件套；你再对照 方法→语义 是否正确。能给出完整三件套的接口定义，才值得写进产品。"]},{"type":"ask","title":"怎么用 AI 帮你写/改一个接口","scenario":"你让 AI 写一个‘新增好友’的后端接口，并希望它可靠、前后端好对接。","template":"[我要做一个] POST /api/friends 的新增好友接口。\n[我希望的入参] JSON：{ nickname, remark }。\n[我希望的结果] 成功后返回 201 + {ok,data};昵称为空返回 400;后端异常返回 500。\n[请给我] 完整的 Node/Express 代码（含错误处理），并附：请求示例 JSON、成功/失败状态码与返回体、以及前端如何 fetch 调用的示例。","acceptance":["接口是否用对了 HTTP 方法（新增→POST）？","是否覆盖了成功(201)、参数错(400)、服务器错(500) 至少三类状态码？","请求与响应 JSON 结构是否给出、且前后端字段名一致？","是否包含 try/catch 错误处理而不是只管成功？用浏览器 Network 面板实测一下接口是否按文档返回。"],"tip":"把‘我要什么入参 + 我要什么结果 + 我要什么状态码’写成模板，AI 生成的接口会立刻规范很多；再用 Network 面板实测验证，别只看它嘴上说‘OK’。"},{"type":"exercise","prompt":"你在前端写了一个请求，点按钮后 Network 面板显示某请求返回 401。你最应该先检查什么？","opts":["后端 SQL 写错了","前端这次请求有没有带上登录凭证（Authorization/Cookie）","服务器机器坏了","网络 DNS 解析失败"],"a":1,"explain":"401 = 未认证/未登录，最常见原因就是请求没带凭证。去看 Network 里这一次请求的请求头，确认是否带了 token 或 Cookie。","jump":"sec5-step1","jumpLabel":"第 ② 步：请求头 Headers"},{"type":"check","title":"结课检测：你会读 API 了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"‘把一条收藏记录保存起来’应该用哪个 HTTP 方法？","opts":["GET","POST","PUT","DELETE"],"a":1,"explain":"产生新数据的写操作应该用 POST；GET 只用于读，不该产生副作用。","jump":"sec5-step0"},{"q":"状态码 401 表示什么？","opts":["找不到页面","未认证/未登录","服务器内部错误","请求太大"],"a":1,"explain":"401 Unauthorized = 未认证，需要登录凭证；403 才是‘已登录但没权限’。","jump":"sec5-step4"},{"q":"看到返回 500，你优先怀疑哪一层？","opts":["前端渲染","浏览器缓存","后端程序异常","CSS 样式"],"a":2,"explain":"500 = Internal Server Error，是服务器（后端）处理出错，去查后端日志与代码。","jump":"sec5-step4"},{"q":"REST 接口中，URL 里的名词代表什么？","opts":["动作（增删改查）","资源（如 /users、/posts）","设计者名字","数据库类型"],"a":1,"explain":"REST 把资源当名词放 URL，动作由 HTTP 方法表达。GET /users/5 是‘读用户5’。","jump":"sec6"},{"q":"前端请求里，登录凭证通常放在哪个位置？","opts":["URL 查询串","请求头 Headers（如 Authorization）","CSS 文件","浏览器书签"],"a":1,"explain":"凭证（token/Cookie）一般放在请求头里，如 Authorization: Bearer xxx；不放会导致 401。","jump":"sec5-step1"}],"done":"你已经能读懂前后端之间的‘暗号’了：方法定动作、状态码定结果、JSON 传数据。下一课我们把线的另一头——数据本身——讲清楚：数据库怎么设计，登录与安全怎么做。","nextLesson":"v04-db"},{"type":"connection","known":["你已经知道一个 Web 产品 = 前端 + 后端 + 数据库，通过 HTTP 通信（上一课）。","你已经会调用模型/看得懂 AI 相关 API 的基础概念（AI 路径）。"],"learned":["HTTP 方法：GET 读 / POST 写 / PUT 整体更新 / PATCH 局部更新 / DELETE 删除","状态码：2xx 成功 / 4xx 客户端问题 / 5xx 服务器问题","请求 = 方法 + URL + 头 + 正文(JSON)；响应 = 状态码 + JSON","REST 设计：名词当资源，方法当动作","给 AI 描述接口需求时，用‘入参+结果+状态码’三件套模板"],"next":"接口是承上启下的：它把‘数据’从后端递给前端。可数据从哪来、怎么存、怎么保证安全？这正是下一课《数据库、登录与安全》要解决的。和 AI 路径的联系：你调用大模型 API 的本质也是‘前端→HTTP→别人家后端的接口’，底层逻辑完全相同。","links":[{"href":"#/lesson/l16-llm-api","text":"回看 AI 路径《用 API 把模型接进你的产品》(规划中)"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},"v04-db":{"id":"v04-db","title":"数据库、登录与安全","subtitle":"数据是产品的命，登录是产品的门。这一课把‘数据怎么存’、‘你怎么证明是你’、‘怎么防坏人’讲透。","course":"vibe","courseNo":"04","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api"],"nextLesson":"v05-test","sections":[{"type":"opening","question":"用户注册了账号、收藏了文章、下了单——这些数据如果不做任何抽象地乱放在一起，会出什么问题？‘收藏’和‘用户’之间到底是什么关系？而你按下‘登录’，服务器凭什么相信你就是那个人，而不是冒充的？","guess":"很多人觉得‘数据随便存个文件不就行了，登录就是在数据库里对一下密码’。","next":"这一课回答三件事：①数据用‘关系表’组织才不乱（表、列、主键、外键、索引、SQL）；②‘登录’不是查一下密码那么简单——Session、JWT、OAuth 各是怎么证明‘你是谁’的；③坏人会怎么攻击（SQL 注入、XSS），以及怎么守住（参数化、转义、加密/哈希、最小权限）。"},{"type":"why","before":"AI 帮你生成登录/注册/收藏/下单功能，里面全是你不认识的词：SQL、primary key、foreign key、index、session、token、bcrypt、JWT、OAuth、SQL 注入。你照抄能跑，但出问题时完全无法判断是‘表没建对’‘还是登录逻辑错’‘还是被人攻击了’。","problem":"数据库设计与安全是‘你几乎不会让 AI 自己随便发挥’的地方——因为数据是用户资产、登录是安全边界。如果不懂“为什么用户表要 id 做主键”“为什么密码要哈希不能存明文”“为什么 SQL 要参数化防止注入”，你根本没法验收 AI 的代码，等于把产品最关键的部分交出去赌运气，早晚出事。","need":"这一课把最少必备的数据库设计与安全知识补上：会看表结构、会写最基础的 SQL、能对比 Session / JWT / OAuth、知道 SQL 注入和 XSS 是什么并知道对应防御。这样当 AI 给出表结构和登录代码，你能像审稿人一样快速挑出明显错误。"},{"type":"oneline","text":"产品数据大多存在关系型数据库（如 PostgreSQL/MySQL）：数据按‘表’组织，每行一条记录，靠‘主键’唯一标识，表与表用‘外键’建立关系，用 SQL 增删改查；登录靠加密凭证证明身份（Session 服务端记、JWT 它自己证明、OAuth 让第三方背书）；安全的核心三件事——密码要哈希不要明文、SQL 用参数化防注入、输出要转义防 XSS。"},{"type":"visual","kind":"db-designer","title":"互动实验：设计一张数据库表","hint":"这是一个迷你‘表设计器’：你决定表有哪些列、哪列是主键、要不要加索引、要不要存密码明文。点击‘预览 SQL / 检查问题’，它会告诉你这张表会不会踩主键、密码明文、可空、无索引等常见坑。体会‘多花一分钟设计，省无数 bug’。"},{"type":"intuition","blocks":[{"k":"用班级花名册来想","t":"数据库里的‘表’就像一张花名册：‘列’是表头（学号、姓名、班级），‘行’是一条记录（某个同学）。‘主键（primary key）’＝学号——全班唯一，靠它能精准找到某个人；‘外键（foreign key）’＝‘本班编号’——它指向另一张‘班级表’的主键，从而把两张表关联起来。没有主键，你用‘姓名’找人会遇到重名；没有外键，班级和学生就接不上。"},{"k":"用门禁卡来想登录","t":"Session＝你在前台刷了一次脸后，前台给你一把只在这栋楼有效的临时钥匙，钥匙上是你进门时发的一个号码（sessionId），门卫每次核对后台名单；JWT＝一把自带信息的加密卡片，上面写着‘我是小明，3 小时后过期’，门卫验签名就放行，不用每次查后台；OAuth＝你出示‘微信已认证’的凭证，门卫信微信的背书就让你进。三种都是‘证明你是你’，只是证明的方式和存放地点不同。"},{"k":"一句话记住安全","t":"密码只存哈希（加盐），不存明文；SQL 永远用参数化（?/$1 占位符），别拼字符串；输出到页面要转义（防 XSS）；后端始终校验，前端校验只是体验。记住这四条，你能挡住绝大多数入门级攻击。"}]},{"type":"visual","kind":"auth-compare","title":"互动实验：Session / JWT / OAuth 三种登录横评","hint":"点击三种登录方式，看同一个‘登录→鉴权→访问’场景在后台是怎么不同的：状态存在哪、怎么验证、有没有跨端问题、优缺点一目了然。帮你给产品选对登录方案。"},{"type":"how","intro":"把‘数据入库 + 登录鉴权’拆成两条因果链：先看一张表从设计到查询怎么走，再看一次登录如何完成。","steps":[{"in":"① 设计表结构（Schema）","process":"确定这张表存什么：用户表要有 id（主键）、username、password_hash、created_at。列的类型要选对（数字用 integer、文本用 varchar）。先想好‘要回答什么问题’，再定表，否则后面改结构（迁移）很麻烦。","out":"一张结构清晰的表 + 主键"},{"in":"② 建表 + 加索引","process":"用 SQL 建表；对‘经常按它来查’的列（如 username）加上索引（index），否则数据多了每次都全表扫描、慢到卡死。索引=书的目录，能加速查找。","out":"表建好，查询有索引加持"},{"in":"③ 用 SQL 增删改查","process":"INSERT 插入、SELECT 查询、UPDATE 更新、DELETE 删除。查询可加 WHERE 过滤、JOIN 关联别表。这是后端操作数据库的日常。","out":"数据被正确写入/读出"},{"in":"④ 表和表用外键建立关系","process":"比如‘收藏表’里放一个 user_id 外键指向用户表、一个 article_id 指向文章表，就能表达‘这个用户收藏了那篇文章’的关系。","out":"数据之间有明确关联，不重复、不乱"},{"in":"⑤ 登录：验证 + 发凭证","process":"用户输入密码 → 后端把输入的密码加盐哈希，和库里存的那个哈希比对 → 相同则信任，创建会话凭证（Session 存服务端 / JWT 返回一个 token / OAuth 走第三方）。","out":"前端拿到凭证，后续请求都带上它"},{"in":"⑥ 访问控制：每步鉴权","process":"后续每个需要身份的请求，后端都校验凭证 → 合法才放行，非法返回 401。同时用权限逻辑控制在‘只能动自己的数据’（不能改别人的）。","out":"只有合法用户能访问其权限内的数据"}]},{"type":"realworld","items":[{"name":"用户系统崩了=数据库没备份/没迁移","note":"很多线上事故是数据库结构改了没做迁移，或连接串配错。知道‘表结构=产品地基’，你就会让 AI 在改表时同步给迁移脚本（ALTER TABLE…），并先在本地/测试库验证。"},{"name":"密码泄露事件=明文存储的代价","note":"反复出现的‘XX 网站密码库泄露’事故，根源常是明文或弱哈希存密码。正确做法：bcrypt/scrypt 加盐哈希。这是判断 AI 登录代码‘安全与否’的第一眼标准。"},{"name":"登录方案选择=产品形态决定","note":"简单网页用 Session 就够；前后端分离/多端（App+网页+小程序）常用 JWT；要‘微信一键登录’就用 OAuth。你会常看到这三者在真实项目里混用（如 JWT 登录 + 微信 OAuth 授权）。"},{"name":"防火墙/最小权限=运维层防御","note":"生产数据库通常不直接暴露公网，只允许服务器内网访问；应用账号只给它需要的库表权限。这是安全纵深的一部分，和‘代码那次注入’互补。"}]},{"type":"compare","pairs":[{"a":"Session（服务端会话）","b":"JWT（令牌）","diff":"Session 把状态存在服务器（内存/Redis/库），客户端只持一个 sessionId，好处是可随时踢人/注销；JWT 把身份信息加密签进 token 给客户端，服务器无状态，好处是天然适合多端与分布式，缺点是一旦签发难在过期前吊销。选型：传统/单一服务用 Session，前后端分离多端多用 JWT。"},{"a":"JWT","b":"OAuth","diff":"JWT 是一种‘凭证格式’（我信任它的签名）；OAuth 是一种‘授权协议’（用户把权限授予第三方，如‘微信允许这个 App 读我的昵称头像’）。OAuth 常把 JWT 当作其中一种 access_token 的载体。"},{"a":"哈希 Hash（单向）","b":"加密 Encrypt（可逆）","diff":"哈希不可逆：密码只做比对，任何人（包括你自己）都无法还原，适合存密码；加密可逆：能解回原文，适合传输敏感信息（但要妥善保管密钥）。拿加密去存密码是常见误区。"},{"a":"SQL 注入","b":"XSS 跨站脚本","diff":"注入是‘坏人把 SQL 代码塞进输入，骗后端执行’，防御靠参数化查询；XSS 是‘坏人把脚本塞进页面内容，骗浏览器执行’，防御靠输出转义。一个打数据库、一个打浏览器，都要防。"}]},{"type":"mistakes","items":["错误案例①（AI 高频）：密码用明文存进数据库列 `password`。正确是 `password_hash` 且用 bcrypt/scrypt 加盐哈希。看到列名叫 password 就要警觉。","错误案例②（致命）：SQL 用字符串拼接——`SELECT * FROM users WHERE name = '` + input + `'`。坏人输入 `' OR '1'='1` 就能登录一切人。必须改成参数化：`WHERE name = $1`（PG）或 `?`（MySQL）。","错误案例③：用户表没有主键，或把‘用户名’当唯一标识——重名就会数据错乱。主键必须稳定唯一（通常用自增 id 或 UUID）。","错误案例④：前端校验当安全边界——‘我在前端限制了只能填数字’并不能挡住直接调接口的攻击者。真正的校验必须在后端。","错误案例⑤：把 token 存 localStorage 又不设过期、也不校验是不是当前用户——一旦 XSS 就能偷走凭证。安全要‘防御纵深’，别只做一层。"]},{"type":"deep","title":"深入一点：手把手判读一张 AI 建的‘用户表’和登录接口","beginner":["看一张 AI 生成的用户表，先问五件事：","**有没有主键？** 要有 id（或 UUID）作主键，能唯一稳定地定位记录。","**密码是不是哈希列？** 应该叫 password_hash / password_digest，用 bcrypt，绝不存明文。","**必填列有没有 NOT NULL？** 用户名、密码哈希不能为空。","**会不会被注入？** 查询语句是不是参数化的（用占位符而非拼接）？","**有没有做访问控制？** 比如‘只能读自己的数据’，而不是任何人传个 id 就能读到别人的。"],"advanced":["**合法但可以更好的设计**：除了基础列，常加 created_at/updated_at 时间戳（审计用）；经常按 username 查就加唯一索引 `UNIQUE(username)`；邮箱/手机号单独存或用正则后端校验。","**登录接口应返回什么**：成功后（201/200）返回凭证；密码错返回 401；账号不存在也返回 401（而不是 404，避免暴露‘这账号存在’）。失败要记日志，但日志里别打明文密码。","**一个可参考的 SQL 建表**：","```sql\nCREATE TABLE users (\n  id BIGSERIAL PRIMARY KEY,\n  username VARCHAR(50) NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n```","**登录校验（参数化防注入的示范）**：","```js\nconst row = await db.oneOrNone('SELECT * FROM users WHERE username=$1', [username]);\nconst ok = row && await bcrypt.compare(password, row.password_hash);\nif (!ok) return res.status(401).json({ ok:false, msg:'用户名或密码错误' });\n```","注意 `$1` 占位符 + `[username]` 参数数组 = 参数化，SQL 注入无从下手。"]},{"type":"ask","title":"怎么用 AI 帮你设计数据库和登录","scenario":"你做了一个‘用户能注册、能收藏文章’的小产品，想让 AI 一次性给出靠谱的表设计和登录方案。","template":"[产品场景] 用户注册登录后，可以收藏文章（一个用户可收藏多篇文章）。\n[请帮我设计] ①用户表与收藏表的结构（含主键、外键、索引）；②注册/登录后端代码，密码用 bcrypt 加盐哈希、SQL 用参数化防注入；③返回 401/201 等状态码。\n[验收标准] 请说明：主键是谁、外键怎么关联、密码如何存储、如何防 SQL 注入、登录凭证用 Session 还是 JWT 并说明理由。","acceptance":["表结构是否给出了主键、外键和需要加的索引？","密码是否明确用了 bcrypt 之类加盐哈希而非明文？","SQL 是否参数化（占位符）而非字符串拼接？","登录凭证方案是否说明了 Session/JWT 的选择及理由？是否覆盖成功与失败状态码？"],"tip":"涉及数据库和安全，务必让 AI 把‘为什么这么做’讲出来，而不能只给代码。你再用上面的‘五问’走一遍，就能当半个审查。"},{"type":"exercise","prompt":"你的登录接口被人用输入 `' OR '1'='1` 打穿了，任何密码都能登进去。这最可能是下面哪种代码导致的？","opts":["用 bcrypt 哈希密码","SQL 用了字符串拼接用户输入（未参数化）","给 username 加了唯一索引","登录返回了 401"],"a":1,"explain":"把用户输入直接拼进 SQL 会造成 SQL 注入——输入里含有的引号和 OR 让查询恒真，从而绕过密码。改成参数化查询即可堵住。","jump":"sec8","jumpLabel":"深入一点的 SQL 注入示范段"},{"type":"check","title":"结课检测：数据库与安全你真的懂了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"用户的‘收藏表’要关联用户和文章，最正规的做法的核心是？","opts":["把所有用户名和文章名塞进同一列","用外键 user_id 和 article_id 分别指向用户表、文章表的主键","每次复制一份用户表","收藏不存数据库"],"a":1,"explain":"用外键指向各自表的主键，才能表达‘哪个用户收藏了哪篇文章’的关系且不重复存储。","jump":"sec5-step3"},{"q":"密码正确的存储方式是？","opts":["明文存进 password 列","加密（可逆）后存","加盐哈希（如 bcrypt）后存，且不存明文","存进 cookie"],"a":2,"explain":"哈希是不可逆的，任何人不包括你自己都无法还原密码，只能用于比对；加盐防止相同密码产生相同哈希。","jump":"sec5-step4"},{"q":"SQL 注入的根本防御是？","opts":["在前端把输入框禁用","用参数化查询（占位符）","把数据库放到公网","把 SQL 写成大写字母"],"a":1,"explain":"参数化查询把用户输入当作数据而不是可执行的 SQL 代码，因此注入失效。","jump":"sec8"},{"q":"Session 与 JWT 的区别，哪句最准确？","opts":["Session 把状态存服务器，JWT 把身份信息加密进令牌交给客户端","两者完全一样","JWT 不能加密","Session 只用于 HTTPS"],"a":0,"explain":"Session 服务端有状态、可随时注销；JWT 无状态、令牌自证身份，适合多端，但签发后较难在过期前撤销。","jump":"sec6"},{"q":"别人的博客里嵌了你的登录页代码，结果是坏人代码执行——这属于用什么方式防御的问题？","opts":["SQL 注入","XSS 跨站脚本","数据库索引","密码哈希"],"a":1,"explain":"把脚本塞进页面内容让浏览器执行的是 XSS，防御靠输出转义 + CSP 等；这不是 SQL 注入（那是打数据库的）。","jump":"sec6"}],"done":"你现在能看懂表结构、能审 AI 的建表与登录代码、知道 Session/JWT/OAuth 怎么选、也知道 SQL 注入/XSS 怎么防。下一课我们把这一切真正‘送上线’：从本地 Demo 变成一台公网可访问、稳定可回滚的真实产品。","nextLesson":"v07-deploy"},{"type":"connection","known":["你知道后端通过 API 和数据库交互（上一课）。","你知道数据要长期保存、要按关系组织（本课）。"],"learned":["数据库用表组织数据：列、行、主键唯一、外键关联、索引加速","SQL 增删改查与参数化防注入","登录三方案：Session 存服务端 / JWT 自证令牌 / OAuth 第三方授权","安全四原则：密码哈希、SQL 参数化、输出转义、后端校验"],"next":"数据和身份都准备好了，下一步是把它们‘送上线’。这与 AI 路径的联系：当你要做的是 AI 产品（如 RAG 问答），RAG 的向量库也是一种‘数据库’，登录/安全同样适用。下一课《从本地 Demo 到正式上线》会把 部署、健康检查、回滚 讲透。","links":[{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——了解向量数据库在 AI 产品里的角色"},{"href":"#/lesson/l20-ai-eng","text":"回看 AI 路径《AI 工程：从原型到生产》(规划中)"}]}]},"v05-test":{"id":"v05-test","title":"测试与调试：让 bug 无处可藏","subtitle":"AI 写的代码‘看起来对’不代表真的对。测试就是给代码挂号看病：把你担心的每一种情况写成‘处方’，让机器自动反复验证。","course":"vibe","courseNo":"05","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":["testing","debugging","test-driven","error-handling"],"prereqLessons":["v04-db"],"nextLesson":"v06-arch","sections":[{"type":"opening","question":"AI 帮你写完功能，你点了一下‘看起来正常’。但这只证明‘这一种情况正常’。如果用户传了空值、超长文本、重复提交，或者网速很慢时呢？它会不会悄悄出错？","guess":"很多人把‘点一下没坏’当成‘没问题’，等上线后才被用户骂出 bug。","next":"这一课让你从‘靠感觉’升级到‘靠验证’：学会写测试，让机器替你一遍遍检查；学会高效调试，遇到 bug 能用工具精准定位而不是瞎猜。"},{"type":"why","before":"你用 AI 快速堆了很多功能，但每次改一处就怕另一处坏，全靠人工点来点去，又慢又容易漏。","problem":"没有测试时，回归风险（改这坏那）全靠人肉；bug 只在线上被用户撞到；调试时踢‘玄学’，分不清是前端、后端还是数据。","need":"你需要一套‘自动验证’体系：把正常/极限/出错的情况固化成测试，任何改动跑一遍就知道坏没坏；再加一套科学的调试流程，快速锁定问题根因。"},{"type":"oneline","text":"测试 = 用代码检查代码：把你关心的输入和期望输出写成断言，让程序自动运行并告诉我们‘通过’还是‘失败’；调试 = 当失败发生时，用日志、断点、报错信息逐层缩小范围，找到并修掉根因，再补一条测试防止它复发。"},{"type":"visual","kind":"http-viewer","title":"互动实验：把一次请求拆开‘调试’","hint":"查看一次请求的完整信息（请求方法/参数/状态码/响应体）。当功能表现不对时，先看请求对不对、状态码对不对、响应对不对——绝大多数 bug 都能在这一层现行。"},{"type":"intuition","blocks":[{"k":"用医生体检来想","t":"测试就像定期体检：你不是‘感觉健康’，而是用仪器（测试用例）一项项量。体检结果红灯/绿灯，告诉你哪里该治。改完代码再‘体检’一次，确认没有新问题（回归）。"},{"k":"用过安检来想","t":"每次上线前，测试就是‘安检门’：正常行李、液体、打火机、可疑物品各走一遍（边界与异常用例）。安检没拦下问题，才会漏到线上。"},{"k":"一句话记住","t":"测试管‘它该不该错’（验证正确性），调试管‘它为什么错’（找根因）。两者配套：写了测试的 bug 更好调，调完的 bug 最好补测试防复发。"}]},{"type":"how","intro":"科学调试 + 自动测试的完整闭环，六步。","steps":[{"in":"① 复现：先让它稳定地出错","process":"调试第一步是把 bug 稳定复现——找出输入、操作、环境的组合。‘偶现’的 bug 最难调，先尽量锁定触发条件。","out":"一个能稳定触发问题的操作路径"},{"in":"② 读报错：从报错和日志定位层","process":"查看报错来自哪一层（前端控制台/后端终端/数据库）。报错信息 + 堆栈 + 日志是缩小范围的雷达。","out":"判断问题最可能在哪一层、哪个文件哪一行"},{"in":"③ 缩小范围：二分法 / 断点","process":"在可疑处打断点或加日志，看变量值是否符合预期。用二分法：先确认一半流程没问题，再把怀疑区切半，快速收敛。","out":"定位到具体的错误代码位置"},{"in":"④ 修复 + 写一条测试","process":"修掉根因（不是表面掩盖），然后写一个能复现此 bug 的测试用例，确保以后不会再犯（回归测试）。","out":"修复完成，且有测试保驾护航"},{"in":"⑤ 跑测试套件","process":"运行整套测试，确认修复没弄坏别的地方。测试套件就是你的‘回归安检门’。","out":"红灯/绿灯：全部通过则放心，有红灯继续修"},{"in":"⑥ 交给 AI 辅助：带着上下文提问","process":"把‘复现步骤 + 报错 + 相关代码 + 我试过的’交给 AI，让它给假设与修复建议；你验证后再落地。","out":"更快地解决复杂疑难 bug"}]},{"type":"realworld","items":[{"name":"单元测试（最小函数）","note":"测一个函数/一个输入输出对：‘输入 3 和 4，应当返回 7’。粒度最小、跑得最快、最稳。"},{"name":"集成测试（多个模块配合）","note":"测‘后端接口读数据库再返回正确结构’这种跨模块流程，确认各部分协作正确。"},{"name":"端到端测试（模拟真实用户）","note":"自动开浏览器，模拟用户点按钮、填表单、走完整流程，确认产品级行为正常。"},{"name":"让 AI 帮你写测试","note":"把函数/接口描述给 AI，让它生成覆盖正常、边界、异常的测试用例。再由你补充‘你的产品里最怕坏的那几条’。"}]},{"type":"compare","pairs":[{"a":"单元测试","b":"端到端测试","diff":"单元测试只测单个小函数，快而稳；端到端测试模拟整个真实流程，覆盖广而慢。两者互补，前者定位快，后者保整体。"},{"a":"调试","b":"测试","diff":"调试是当下找并修现有 bug 的根因；测试是把‘该对的不变错’固化成自动化验证，防止未来回归。调试解决‘现在’，测试守住‘以后’。"},{"a":"人肉点验","b":"自动化测试","diff":"人肉点验靠眼、易漏、难重复；自动化测试靠代码、可重复、可长时间回归。AI 时代的快节奏尤其需要自动化兜底。"},{"a":"掩耳修 bug","b":"修根因","diff":"表面掩盖（如删掉报错）下个输入还会炸；修根因 + 补测试才是一劳永逸。"}]},{"type":"mistakes","items":["只测‘正常情况’，不测空值/超长/重复/超时等边界——线上都是在边界炸的。","改完代码不重跑测试——回归 bug 悄悄溜回去。","看到报错就贴给 AI，不先自己读——先定位‘哪一层、哪个文件’，AI 才能精准。","写测试只求‘通过’不求‘有意义’——骗过自己的测试没有价值。","把 .env 密码打进日志——泄露风险大于 bug 本身。"]},{"type":"ask","title":"怎么用 AI 帮你调试：给足四件套","scenario":"你的接口偶尔返回错误，你想让 AI 帮你定位。","template":"[现象] 点击保存后约 20% 概率报 500 错误，多数时候正常。\n[复现] 连续快速点两次保存，必现。\n[报错] 后端日志：TypeError: Cannot read properties of undefined (reading 'id') at line 88.\n[我试过] 单次保存正常；怀疑是重复提交/竞态导致请求对象未就绪。\n[请给我] 判断根因最可能是什么，并给出修复 + 回归测试方案。","acceptance":["AI 是否先确认了复现条件与报错层级？","是否给出根因判断而非简单贴代码？","是否提供修复 + 一条防复发的测试？","是否提醒测试边界（重复提交/空值）？"],"tip":"调试提问的黄金四件套：现象 + 复现 + 报错 + 我试过的。越具体，AI 越能帮你一击命中。"},{"type":"exercise","prompt":"你的功能‘在本地点一下没问题’，但你最担心上线后被用户遇到奇怪输入就崩。下面哪个做法最能防患于未然？","opts":["相信 AI 写的没问题，不测","补上正常/边界/异常的自动化测试，并在每次改动后重跑","只在发布当天人工多点点","把报错用 try-catch 吞掉不上报"],"a":1,"explain":"把担心的情况固化成自动化测试（正常/边界/异常）并持续回归，才是防患于未然的正道；try-catch 吞错只会掩盖问题。","jump":"sec5-step4","jumpLabel":"补测试防复发这一步步"},{"type":"check","title":"结课检测：你会给代码看病了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回对应段落复习。","questions":[{"q":"‘回归测试’主要为了防止什么？","opts":["新增功能太少","改了这处却弄坏了之前能用的功能","代码写了注释","部署变慢"],"a":1,"explain":"回归测试是在每次改动后重跑，确保‘不该变错’的旧功能没被新改动弄坏。","jump":"sec5-step4"},{"q":"调试一个‘偶发’bug 的第一步是什么？","opts":["直接重写整个模块","先想办法稳定复现它，锁定触发条件","立刻上线再观察","删掉报错"],"a":1,"explain":"先稳定复现并锁定触发条件，才能进一步定位；偶发 bug 最难调，复现是第一步。","jump":"sec5-step0"},{"q":"下面哪一类测试粒度最小、跑得最快？","opts":["端到端测试","单元测试","集成测试","人工测试"],"a":1,"explain":"单元测试只测单个小函数，粒度最小、最快最稳；端到端最慢。","jump":"sec6"},{"q":"把 bug 交个 AI 之前，最有效的准备是？","opts":["只发一句‘它坏了帮我修’","提供现象 + 复现步骤 + 报错 + 我试过的","什么都不说让 AI 猜","先删掉相关代码"],"a":1,"explain":"四件套（现象/复现/报错/已试过）让 AI 快速定位根因，避免无效往返。","jump":"sec7"}],"done":"你现在既能用测试预防 bug，又能用科学流程调试 bug，还能让 AI 高效地帮你。下一课把目光放回代码本身：怎么组织项目结构，让一开头乱成一团的代码变得清晰可维护。","nextLesson":"v06-arch"},{"type":"connection","known":["你已了解后端 API、数据库（v03/v04）与分层思想（v01）"],"learned":["测试 = 自动验证正确性；调试 = 定位并修根因，两者互补","复现→定位→修复→补测试→回归的科学调试闭环","单元/集成/端到端测试的区别与分工","给 AI 调试提问的黄金四件套"],"next":"测试守住质量底线，下一步我们要管好代码本身的结构：让工程量变大时依然清晰、好扩展、好维护。","links":[{"href":"#/lesson/v06-arch","text":"下一课：《项目结构与代码组织》"},{"href":"#/lesson/v04-db","text":"回看《数据库、登录与安全》"}]}]},"v06-arch":{"id":"v06-arch","title":"项目结构与代码组织","subtitle":"AI 会把所有代码一股脑塞进一两个文件。功能少时没事，功能一多就变成没人敢动的‘意大利面’。这节课教你给项目‘装修’，让它清晰、好扩展、好维护。","course":"vibe","courseNo":"06","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":["project-structure","code-organization","modularity","refactoring"],"prereqLessons":["v05-test"],"nextLesson":"v07-deploy","sections":[{"type":"opening","question":"你的项目从 2 个文件长到了 20 个文件。现在你想加一个‘分享’功能，却要改 6 个文件，每改一处都怕碰坏别处。AI 也越帮越乱——它不知道你的项目现在长什么样。","guess":"很多人选择‘忍’，或者干脆重写一个更乱的项目。","next":"这一课教你如何规划项目结构：怎么分文件夹、怎么分层、怎么拆分组件，让代码像整理好的衣橱一样‘东西各有其位’。结构清晰，AI 才能准确帮你改，你才不会改一处崩三处。"},{"type":"why","before":"你在 Vibe Coding 里让 AI 快速堆功能，很快发现文件多、职责乱、命名随意，连你都不敢轻易动。","problem":"结构混乱的代价：改一处崩三处、加功能要动一堆文件、AI 因为看不懂全貌而瞎改、你无法确认改动影响面。","need":"你需要一个清晰的项目骨架：明确的分层、职责单一的模块、合理的命名与目录。这样无论是你还是 AI，都能‘小范围定位、大胆改动、放心验证’。"},{"type":"oneline","text":"好的项目结构 = 按‘职责’而不是‘随意’组织的代码摆放：前端/后端/数据分层清晰，每个模块只做一件事，文件命名即职责，改动影响面小、可测试、可替换。它是让‘小项目’能长大成‘可维护产品’的地基。"},{"type":"intuition","blocks":[{"k":"用整理衣柜来想","t":"衣柜分格：上衣一格、裤子一格、袜子一格，找衣服（找代码）快、放回去不乱。如果把所有衣服扔进一个大抽屉（一个 giant 文件），找什么都翻半天，还容易拿错。"},{"k":"用餐厅分工来想","t":"一个好的餐厅有明确分工：前台点单、后厨做菜、仓库备料、财务算账，各司其职。一个烂餐厅‘一个人啥都干’，热闹时必崩。代码分层同理：页面只管展示，逻辑只管处理，数据只管存取。"},{"k":"一句话记住","t":"‘职责单一 + 分层清晰 + 命名即职责’。看到文件名就知道它管什么；改一个功能只动最少文件。这就是可维护性的全部秘密。"}]},{"type":"how","intro":"从混乱到清晰的三步整理法。","steps":[{"in":"① 按层分目录（横向分层）","process":"按‘类型/职责’分开：前端代码、后端代码、数据库相关、配置、测试、静态资源各放各目录。例：src/、api/、db/、tests/、config/、public/。","out":"横向分层清晰，一眼看懂项目由哪几块组成"},{"in":"② 按功能分模块（纵向拆块）","process":"在一个层内部再按功能拆分：比如‘用户’、‘订单’、‘分享’各自成模块，模块内部再包含自己的逻辑/子文件。一个文件只负责一个功能点。","out":"纵向模块化，加功能影响面收窄到单一模块"},{"in":"③ 命名即职责 + 收敛公共部分","process":"文件/函数命名说清职责（userService.js 管用户逻辑、db.js 管连接）。把重复出现的代码抽成公共函数，避免复制粘贴三遍。","out":"可读性提升，改动点集中，易于测试与替换"},{"in":"④ 找 AI 重构（带着结构上下文）","process":"把‘当前目录结构 + 你要的目标结构/问题’给 AI，让它帮你拆分、抽取、重命名。分小步做，每步后跑测试验证。","out":"借助 AI 快速完成结构整理且不破坏功能"}]},{"type":"realworld","items":[{"name":"前后端分离","note":"前端代码和后端服务分开目录（甚至分开仓库/部署），职责完全不同，各自独立演化与测试。"},{"name":"一个文件只做一件事","note":"giant 文件是最大的敌人：几百行的单一文件难读难测难改。拆成职责清晰的小文件/函数。"},{"name":"配置与代码分离","note":"数据库地址、密钥、端口等‘环境相关’配置放 config 或环境变量，别硬编码进代码，便于本地/线上切换。"},{"name":"测试与源码平行","note":"测试文件和被测代码放在对应/平行的目录，改动时容易同步维护。结构清晰才能让‘改这里测那里’成为日常。"}]},{"type":"compare","pairs":[{"a":"扁平大文件","b":"分层分模块","diff":"扁平把所有逻辑塞一起，难读难测；分层次、分模块按职责归位，定位快、影响面小。"},{"a":"复制粘贴复用","b":"抽取公共函数","diff":"复制粘贴三遍，改一处要改三处且易漏；抽成公共函数单点维护，一处改动全局生效。"},{"a":"随意命名","b":"命名即职责","diff":"随意命名（a/b/temp）看不懂；命名即职责（saveUser）看到名字就知道干什么、改哪找哪。"},{"a":"硬编码配置","b":"配置分离","diff":"硬编码密钥/地址难切换且易泄露；配置分离便于本地/线上切换与安全。"}]},{"type":"mistakes","items":["把所有代码塞进一个 main 文件——看一眼就头大，AI 也会改错。","不设目录分层，东放一个西放一个——找不到文件该在哪。","命名随意（a/b/test12）——神仙也看不懂。","一个函数干八件事——难测难调。职责单一才可测。","重构一上来就大动干戈——高风险。小步重构 + 每步测试，才稳。"]},{"type":"ask","title":"怎么用 AI 帮你整理结构：把当前全貌给出去","scenario":"你的项目文件越来越乱，想请 AI 帮你重构组织。","template":"[现状] 我的项目目前文件都在根目录：main.js（约 300 行）、utils.js、data-handler.js… 没有分目录。\n[目标] 我想整理成前端/后端/配置/测试分层的清晰结构，并让每个文件职责单一。\n[约束] 不能破坏现有功能，我有测试可以验证；请分小步提出重构方案，每一步不要动太多。\n[请给我] 先给出目标目录结构与分工建议，再给按小步执行的拆分清单。","acceptance":["AI 是否先了解现有结构再动手？","是否给出分层/模块化的目标结构，而不只是‘把文件挪一挪’？","是否建议小步重构 + 测试验证，避免一次性大动？","是否提醒命名即职责、公共部分收敛？"],"tip":"把‘当前结构 + 目标 + 约束（不能坏、有测试）+ 请小步’交给 AI，它会给你靠谱的重构方案。别让它‘直接重构’，要先给方案。"},{"type":"exercise","prompt":"你的项目所有逻辑都挤在一个 400 行的 main.js 里，想让它便于维护。下面哪个做法是正确第一步？","opts":["一次性把 400 行全部重写成多个文件再跑","先按职责切分，小步把一块块功能抽到独立模块，并保持每次都还能跑 + 测试通过","继续加在一个文件里，方便 AI 找","删掉重写"],"a":1,"explain":"正确做法是小步按职责拆分，每拆一块仍能跑、测试仍过，逐步收敛；一次性大重写风险极高。","jump":"sec5-step3","jumpLabel":"找 AI 重构这一步步"},{"type":"check","title":"结课检测：你会给项目‘装修’了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回对应段落复习。","questions":[{"q":"项目结构清晰的主要好处是？","opts":["代码变少了","改动影响面小、定位快、易测试易维护","运行更快","AI 不需要了"],"a":1,"explain":"结构清晰的本质是降低‘改动成本与风险’：定位快、影响面小、可测、可维护。","jump":"sec5-step0"},{"q":"下面哪个符合‘职责单一’？","opts":["一个函数既渲染页面又查数据库还保存文件","一个模块只负责一件事：比如用户模块只管用户","把所有逻辑写一个函数里","一个文件放所有样式和逻辑"],"a":1,"explain":"职责单一 = 每块代码只做一件清楚的事，这样才好测、好改、好复用。","jump":"sec5-step2"},{"q":"数据库地址、密钥这类配置应该放在哪里？","opts":["硬编码写死在代码里","放在 config/环境变量，与代码分离","放到前端页面","写进提交日志"],"a":1,"explain":"环境相关配置应与代码分离（config/环境变量）：便于本地/线上切换，也避免密钥泄露到代码与仓库。","jump":"sec6"},{"q":"重复出现三遍的同一段代码，最好怎么处理？","opts":["继续复制粘贴","抽成一个公共函数，单点维护","每次都重写一遍","交给 AI 不管"],"a":1,"explain":"抽成公共函数，一处改动全局生效，避免三处不同步的隐患。","jump":"sec5-step2"}],"done":"你的项目从‘意大利面’变成了‘有格子的衣橱’，自己和 AI 都能快速定位、安心改动。最后一关：怎么把这套东西从你电脑搬到真正的线上服务器，让全世界都能访问。","nextLesson":"v07-deploy"},{"type":"connection","known":["你已了解分层（v01）、后端 API（v03）、数据库（v04）、测试（v05）"],"learned":["结构清晰 = 职责单一 + 分层模块化 + 命名即职责","从混乱到清晰的整理法：分层→分模块→命名/收敛公共→AI 辅助小步重构","前后端分离、配置分离、测试平行摆放","小步重构 + 测试验证的原则"],"next":"结构理清了，最后一步就是把它送上线：怎么从‘本地能跑’变成‘人人能访问’。部署是 Vibe 路径的临门一脚。","links":[{"href":"#/lesson/v07-deploy","text":"下一课：《从本地 Demo 到正式上线》"},{"href":"#/lesson/v05-test","text":"回看《测试与调试》"}]}]},"v07-deploy":{"id":"v07-deploy","title":"从本地 Demo 到正式上线","subtitle":"代码在你自己电脑上能跑，不算数；让全世界都能访问、且挂了能快速恢复，才是‘上线’。这一课讲清楚那条从 localhost 到公网的最后一公里。","course":"vibe","courseNo":"07","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api","v04-db"],"nextLesson":"v08-workflow","sections":[{"type":"opening","question":"你的产品在自己电脑上跑得欢，你联调、测试都通过了。现在要把它放到公网，让外地、外网、别家浏览器都能访问——为什么这件事永远比想象中麻烦？常见的‘本地正常、线上挂掉’到底差在哪？","guess":"很多人以为‘上线就是把文件传到服务器上，然后就能用了’。","next":"这一课我们拆解上线全流程：环境如何保持一致（环境变量）、如何把项目部署到服务器/云平台、域名与 HTTPS 怎么配、上线后怎么确认它是‘健康的’（健康检查）、出问题怎么快速回滚、以及要不要上 CI/CD。学完后你拥有的能力是：把 AI 做的 Demo 安全地变成可上线产品，并知道每一步万一失败该怎么退回来。"},{"type":"why","before":"你写好了产品，AI 也说‘好了，部署吧’。可你一部署，报‘连接数据库失败’‘端口被占用’‘找不到 .env’‘静态资源 404’……你完全不知道从哪查起，只能一遍遍粘日志给 AI，反复重装环境。","problem":"本地与线上天然不同：路径不同、数据库地址不同、端口不同、依赖版本可能不同、还要面对公网连接、域名、HTTPS 证书、防火墙。如果你没有‘环境一致性’与‘可回滚’的意识，即使这次勉强跑起来，下次改动也会随时把线上搞挂而无法恢复。","need":"掌握上线的最小可靠流程：用环境变量（.env）把差异集中管理；部署常走三大路径（静态托管 / PaaS 平台 / 自管服务器）分别怎么选；配域名 + HTTPS；加‘健康检查’让系统自己喊救命；上线清单与回滚流程让‘挂了也能退回去’。这是把 Demo 变成产品的临门一脚。"},{"type":"oneline","text":"上线 = 把代码 + 环境一致地搬上公网机器 + 配好域名/HTTPS + 挂上健康检查 + 准备好一键回滚。核心三句话：环境用变量隔离差异（不同环境不同值）、部署用脚本/平台保证可重复（别靠手敲）、发布用‘灰度/可回滚’控制风险（挂了能退）。"},{"type":"visual","kind":"deploy-console","title":"互动实验：部署控制台，看一次完整上线","hint":"这是一个模拟部署终端：点‘部署’会经历 构建 → 迁移 → 健康检查 → 流量切换；如果健康检查失败，系统会拒绝放量并自动回滚到上一个版本。你还能故意制造‘健康检查失败’来亲眼看到回滚是怎么保命的。"},{"type":"intuition","blocks":[{"k":"用开餐厅来想","t":"本地 Demo 像在你的厨房试菜——火候是你自己调好的、食材在你冰箱里。上线＝在商业街上开正式的餐厅：要租店面（服务器）、接水电气（网络/HTTPS）、换统一采购的食材（数据库搬到线上）、店员按标准作业（健康检查/监控）、万一某天厨房着火（服务挂）要能立刻换上备用后厨（回滚/容灾）。‘本地试菜’和‘正式营业’根本不是一回事。"},{"k":"用电梯/红绿灯来想健康检查","t":"健康检查＝系统自己定时喊一嗓子‘我还活着’（探测 /health 接口）。就像电梯每隔几秒报一次运行状态。如果它不喊了，编排系统（如负载均衡）就把它踢出队伍并拉起一个新的——而不是让用户对着白屏干等。"},{"k":"一句话记住上线","t":"环境变量隔离差异 → 构建产物可重复 → 部署到线上 → 健康检查确认活着 → 出问题回滚上个版本。五个动作，缺一不可；其中‘能回滚’是你最后的保险绳。"}]},{"type":"visual","kind":"llm-retry","title":"互动实验：给 LLM 调用加上超时 + 重试 + 回退","hint":"你的产品里调了大模型 API（这也是你 AI 产品的‘后厨’）。网络抖动/超时/限流在线上是家常便饭。这个实验模拟‘调用 → 超时 → 重试 → 回退(fallback)’，体会电商级 API 调用为什么要设计超时与降级。这也是 Vibe Coding 路径与 AI 路径的连接点。"},{"type":"how","intro":"把一次‘安全上线’拆成 6 步：每一步都有明确的‘成功标志’和‘失败补救’。","steps":[{"in":"① 环境变量：把差异抽出来","process":"本地/测试/线上需要不同的数据库地址、密钥、端口。把它们写进环境变量（如 .env 文件或平台面板），代码里用 process.env.XXX（Node）/ os.environ（Python）读取，而不是写死。","out":"代码与环境解耦：同一份代码换环境即可"},{"in":"② 构建 + 迁移","process":"前端打包成静态文件（npm run build → dist/）；数据库结构变化用迁移脚本（migration）跑一遍。构建产物要是‘可重复’的——同一份源码应产出同样的产物。","out":"得到一个可直接发布的‘构建物’+ 数据库就绪"},{"in":"③ 部署到线上","process":"三大路径：静态托管（页面纯前端，丢到 GitHub Pages/CF Pages/OSS 即可）；PaaS 平台（Vercel/Netlify/Railway/Render，把代码推送即可自动部署，适合新手与中等项目）；自管服务器（买 ECS/VPS，自己配 Nginx + 进程守护如 PM2/systemd）。新手从 PaaS 起步最稳。","out":"公网可以访问你的服务"},{"in":"④ 域名 + HTTPS","process":"买个域名，把 DNS 解析到你的服务（A 记录指向 IP / CNAME 指向平台）；再签 HTTPS 证书（平台自动，或云厂商+Letʼs Encrypt），让访问走 https:// 加密。浏览器地址栏的小锁 = 加密。","out":"用户通过好记的 https://你的域名 访问"},{"in":"⑤ 健康检查 + 监控","process":"后端提供 /health 接口（返回 200 + 状态）。负载均衡/编排平台每 X 秒探测它：活着→正常放量；不活→摘除并重启该实例，同时报给你（监控告警）。","out":"系统自己‘喊救命’，而不是等用户来报"},{"in":"⑥ 发布即回滚预案","process":"大型发布用‘灰度’：先 10% 流量验证，稳妥再全量；每版都保留上一个版本，发现异常立刻一键回滚（切回旧版本）。回滚能力 = 你改线上时的底气。","out":"即使新版本有问题，也可在几分钟内恢复"}]},{"type":"realworld","items":[{"name":"GitHub Pages（本站就是这么上线的）","note":"纯前端静态站可直接推到 GitHub Pages，免费公网、自带 HTTPS。适合‘文档/演示/静态首页’。注意它只托管静态资源，没有后端/数据库——需要后端的要另选 PaaS 或 VPS。"},{"name":"Vercel / Render / Railway（PaaS）","note":"‘连上 Git 仓库，push 即部署’：自动构建、自动 HTTPS、给环境变量面板、自动健康检查与回滚。是前端+轻后端产品（含 Next.js 全栈）最省心的上线方式。"},{"name":"云服务器 + 进程守护（VPS）","note":"腾讯云/阿里云的 ECS 上装 Node/Python、用 PM2/systemd 守护进程、Nginx 反代 + HTTPS。灵活可控但维护成本高。适合要自己掌控环境、或者后端较重/要连自己数据库的产品。"},{"name":"CI/CD（持续集成/持续部署）","note":"把‘测试 → 构建 → 部署’做成流水线：你 push 代码，系统自动跑测试并部署。好处是上线行为可重复、可审计；新手至少理解它的存在，平滑后再引入 (如 GitHub Actions)。"}]},{"type":"compare","pairs":[{"a":"静态托管（GitHub Pages/OSS）","b":"PaaS 平台（Vercel/Render）","diff":"静态托管只能放纯前端静态文件、无后端、一般免费；PaaS 能托管前端+后端（有的带数据库），源码推送自动构建/部署/HTTPS，更适合‘有后端的完整产品’。纯静态选前者，有后端选后者。"},{"a":"PaaS 平台","b":"自管云服务器（VPS+PM2+Nginx）","diff":"PaaS 帮你管环境、自动部署、内置回滚，省心但灵活度有限；VPS 完全可控（能装任意软件）但要自己维护系统、进程守护、HTTPS、备份，运维成本高。新手/中小产品从 PaaS 起步，要深度控制再上 VPS。"},{"a":"环境变量 .env","b":"写死在代码里","diff":"环境变量让同一份代码在不同环境（本地/测试/线上）用不同配置，且密钥不进代码库；写死会导致‘本地行、线上不行’，且密钥泄露风险大。必须用环境变量管理差异与密钥。"},{"a":"健康检查 /health","b":"用户报错才知道挂了","diff":"健康检查是主动、自动、秒级的探活，挂了立刻摘除重启并告警；等用户报告则被动、慢、伤口碑。生产环境必须有健康检查。"}]},{"type":"mistakes","items":["错误案例①：把数据库连接串、API 密钥写死在代码/前端里并 push 到公开仓库——等于把保险柜密码贴在门口。密钥必须进环境变量并严格保密。","错误案例②：没有环境意识，‘本地跑通了就认为线上能跑’。正确的验证方式：线上部署后跑一遍健康检查 + 真实浏览器访问，而不是‘本地 200 就完事’。","错误案例③：上线直接改线上数据库结构却不做迁移回滚——出事退不回去。数据库结构变更要保留迁移脚本、可逆可回退。","错误案例④：追逐‘最新框架/功能’把线上当实验场，改一次崩一次却没有任何回滚按钮。生产稳定 > 炫技；改版前后都要有一键回滚能力。","错误案例⑤：把‘调大模型 API’当成不会失败——线上网络抖动、超时、限流很常见。不给 API 调用加超时/重试/回退(fallback) 的 AI 功能，用户会频繁看到转圈/报错。"]},{"type":"deep","title":"深入一点：一次失败的线上事故是怎么被救回来的","beginner":["把‘回滚像不像重装系统’想明白：回滚不是把线上机器清空重装，而是‘把流量切回上一个已知良好的版本镜像/构建物’。现代平台（PaaS、容器编排）都保留旧版本，一键切换即可，秒级恢复。","健康检查的 /health 接口长什么样？就是一个后端路由，返回 200 和一个简单的 JSON：`{status:'ok'}`。它常常还会顺带检查数据库能否连上。如果数据库挂了，/health 也会返回失败——这样编排系统才会判断这台机器‘不健康’并把它踢出去。"],"advanced":["**一次事故的完整剧本**：新版本把数据库连接串写错 → 部署平台探测 /health → 数据库连不上 → /health 返回 500 → 平台判定‘不健康’→ 拒绝放量 / 自动回滚到旧版本 → 监控告警发到你手机 → 你看日志定位到环境变量拼错 → 修正后重新部署。全程用户几乎无感知。这就是‘健康检查 + 回滚 + 监控’三件套的价值。","**LLM 调用的可靠性设计（与 AI 路径的接口）**：真实产品调大模型 API 时，用模式是‘超时 + 指数退避重试 + 回退（缓存结果 / 备用模型 / 返回友好提示）’：","```js\nconst response = await fetchLLMWithRetry({\n  prompt, timeoutMs: 8000,            // 超时：8 秒没回应就放弃重试\n  retries: 3, backoffMs: 1000,         // 重试 3 次，指数退避\n  fallback: () => cache.get(key)       // 兜底：用缓存或降级文案\n});\n```","**上线检查清单（Checklist）**：①环境变量配全了吗？②数据库迁移跑了吗？③HTTPS 生效了吗（浏览器锁）？④/health 探针过吗？⑤日志与告警接了吗？⑥旧版本能一键回滚吗？⑦真实浏览器/多设备验证了吗？全部打勾，才算一次‘可上线发布’。"]},{"type":"ask","title":"怎么让 AI 帮你安全上线","scenario":"你的产品要第一次上线，不确定从哪下手、怕把线上搞挂。","template":"[我的产品] 是一个 [前端 + Node 后端 + PostgreSQL] 的小产品，目前只在本地能跑。\n[请给我] 一份最小可靠的上线方案：推荐用哪种托管方式（静态/PaaS/VPS）并说明理由；列出需要的环境变量清单；给出数据库迁移与开启 HTTPS 的步骤；提供 /health 接口示例与回滚预案。\n[验收标准] 每一步是否有明确操作与验证方法？是否包含失败时的回滚步骤？","acceptance":["部署方案是否说明了选型理由（静态/PaaS/VPS）与本产品的适配性？","环境变量清单是否完整且不包含明文密钥？","是否提供了可复现的部署步骤与验证方式（健康检查/浏览器访问）？","是否有明确的回滚/恢复预案，而不是‘挂了重装’？先小范围(灰度)验证再全量了吗？"],"tip":"上线是最不能‘赌一把’的环节。让 AI 给出‘选型 + 环境变量 + 验证 + 回滚’全套，再逐项打勾验收；任何一步读不懂就让 AI 解释‘为什么这样做’，直到你能复述为止。"},{"type":"exercise","prompt":"你上线了新版本，负载均衡探测 /health 连续几次都返回 500。接下来最正确的自动动作是什么？","opts":["继续放大流量，等用户反馈","把该实例摘除并自动回滚到上一个良好版本","重启浏览器","删掉数据库"],"a":1,"explain":"健康检查失败说明新版不健康，应把它踢出流量并回滚到上一版本，让用户在无感知的情况下继续使用。","jump":"sec7-step4","jumpLabel":"第 ⑤ 步：健康检查 + 监控"},{"type":"check","title":"结课检测：你的上线观念成立了吗","intro":"共 5 题。全部答对可进入下一节后续课程（或视为完成本路径第一批）。","questions":[{"q":"‘本地跑通 = 线上一定能跑’这句话？","opts":["完全正确","错误，本地与线上环境(变量/依赖/数据库)常不同，需部署后验证","只对前端成立","只对数据库成立"],"a":1,"explain":"环境差异（连接串、密钥、依赖版本、端口）是‘本地行、线上挂’的常见原因，必须部署后做健康检查与真实访问验证。","jump":"sec4"},{"q":"数据库地址、API 密钥这类差异应当怎么管？","opts":["写死在代码里方便","放进环境变量按环境区分，且密钥不进代码库","藏在注释里","放前端页面里"],"a":1,"explain":"环境变量让同一代码适应不同环境、密钥不进仓库，安全且可维护。","jump":"sec5-step0"},{"q":"完全不会写代码、只想让前端+后端都能自动上线，最省心的选项是？","opts":["自建机房","PaaS 平台（如 Vercel/Render），连 Git push 即部署","用纯记事本手写服务器脚本","不部署"],"a":1,"explain":"PaaS 负责构建、部署、HTTPS、健康检查与回滚，对新手最友好；VPS 更适合要深度控制的高级场景。","jump":"sec7"},{"q":"/health 健康检查的探测失败时，编排系统最合理的动作是？","opts":["什么都不做","摘除不健康实例并重启/拉起新的，必要时候选回滚","把数据库清空","关掉域名"],"a":1,"explain":"自动摘除+重启，必要时回滚旧版本，让用户几乎无感知；同时告警提醒你排查。","jump":"sec7-step4"},{"q":"调用大模型 API 时，‘超时 + 重试 + 回退(fallback)’组合主要防范什么？","opts":["防止代码有语法错误","线上网络抖动、超时、限流导致的偶发失败","防止数据库被删","防止前端样式错乱"],"a":1,"explain":"线上第三方 API 偶发失败是常态，超时避免无限等待、重试提高成功率、回退(缓存/备用/友好提示)兜底，保证用户体验不崩。","jump":"sec7"}],"done":"你已经掌握了从 localhost 到公网‘最后一百米’的全部关键：环境变量隔离、部署三路径选型、域名+HTTPS、健康检查、回滚预案、上线清单。Vibe Coding 第一批四门课到此收官——你已经能看懂代码结构、判断接口与数据库靠不靠谱、把 Demo 安全上线了。","nextLesson":""},{"type":"connection","known":["你知道一个 Web 产品如何分层（课1）、前后端怎么通信（课3）、数据怎么存与登录安全（课4）。","你会调大模型 API / 了解 RAG、Agent（AI 路径）。"],"learned":["环境变量隔离本地/测试/线上差异，密钥不进代码库","部署三路径：静态托管 / PaaS / 自管 VPS，以及各自适用场景","域名 + HTTPS（浏览器小锁）怎么配","健康检查(/health)探活 + 监控告警，挂了自动摘除","灰度 + 一键回滚 = 改线上时的底气；上线检查清单"],"next":"Vibe Coding 第一批四个环节到此闭环：看懂 → 懂接口 → 懂数据/安全 → 懂上线。下一步安排：第二批课程将覆盖 前端与语言基础（课2）、终端与 Git（课5）、存储缓存与测试排错（课6）、系统设计与 AI 产品工程（课8）。与本路径之外的联系：AI 产品的上线同样遵循本课原则，且多了‘LLM 调用可靠性’（超时/重试/回退）这一环——已在课 7 实验里有真机感受。","links":[{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"},{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——AI 产品上线的数据侧"},{"href":"#/lesson/l-agent","text":"回看 AI 路径《Agent：让 AI 自己动手做事》——Agent 产品化时的可靠性思考"}]}]},"v08-workflow":{"id":"v08-workflow","title":"用 AI 完整做一个产品：全流程实战","subtitle":"前面七课把每一块都讲透了。这一课把它们串成一场完整实战：从一句话想法开始，走完立项、搭建、版本、联调、测试、部署，最终上线一个能给朋友用的真产品。","course":"vibe","courseNo":"08","level":"pro","estTime":"25-40 分钟","difficulty":3,"concepts":["full-workflow","product-launch","vibe-coding","mdv"],"prereqLessons":["v07-deploy"],"nextLesson":"","sections":[{"type":"opening","question":"你学完了：Web 链路、Git、API、数据库、测试、结构、部署。现在你把七块拼起来，用 AI 从零做一个真产品——比如‘家庭记账本’。你心里有完整的路线图，但你知道第一步该做什么、每一步怎么验收、在哪里最容易翻车吗？","guess":"很多人学完每课都很手痒，但真开始就面临‘从哪入手、怎么保证不烂尾、怎么保证上线安全’三大问题。","next":"这一课是收官实战：给你一套可直接照做的‘从想法到上线’端到端清单，串起前七课的全部能力。做完这课，你就是真正‘用 AI 独立做一个上线产品’的人了。"},{"type":"why","before":"你各环节都会一点，但没试过‘一口气走完全程’，担心翻车、烂尾、不知道每步到什么程度算 OK。","problem":"做一个真产品和做 demo 的区别：要能经受真实用户、真实数据、真实安全与真实故障。缺一个可照做的端到端流程，就容易卡在某一环或上线后翻车。","need":"你需要一条完整的实战流水线：每个阶段有明确目标、明确验收标准、明确翻车点与对策。学完立刻能复制到任意新项目。"},{"type":"oneline","text":"全流程实战 = 立项（一句话 + MVP）→ 骨架搭建 → 版本控制 → 前后端联调 → 数据与安全 → 测试 → 部署上线 → 上线后观察。八个阶段各含‘目标/验收/雷区’，串起来就是一套可复制的‘AI 产品生产线’。"},{"type":"visual","kind":"request-flow","title":"互动实验：走一遍上线后的一次完整请求","hint":"点‘发送请求’，用一个真实上线产品的视角，重走一次 用户→浏览器→DNS→网络→服务器→后端→数据库→回显，把 v01 到 v07 学的每一层验收一遍。这就是你上线产品每天在被执行的事。"},{"type":"intuition","blocks":[{"k":"用盖一栋楼来想","t":"立项=出图纸，骨架=打地基，Git=施工日志，联调=水电管线对接，测试=竣工验收，部署=交付入住，上线观察=回访保修。任何一步省掉，楼都住不安稳。"},{"k":"用做一顿饭来想","t":"备料（数据）、切配（分模块）、下锅（写功能）、尝味（测试）、装盘（部署）、上桌（上线）。每步都能‘尝一口’，别憋到最后才开火。"},{"k":"一句话记住","t":"小步快跑 + 每步验收 + 能回退 + 有测试防回归。把这四个关键词刻在流程里，任何项目都不会翻车。"}]},{"type":"how","intro":"从想法到上线的八阶段实战清单。每阶段都有验收标准。","steps":[{"in":"① 立项：一句话 + 最小 MVP","process":"把想法压缩成一句话：为谁解决什么。锁定最小可用范围（核心 1-2 个功能），暂不做锦上添花。","out":"一句需求 + MVP 边界清单","note":"这一阶段是产品判断，交给 AI 前先自己想清楚。"},{"in":"② 搭骨架：让 AI 生成基础工程","process":"把需求、技术选型、运行环境给 AI，让它一键生成可运行的基础工程（页面+后端+GIT 初始）。","out":"能跑的最小骨架","note":"把 v06 结构思想直接要求 AI 遵守。"},{"in":"③ 版本控制：立刻 git init + 首次提交","process":"骨架一跑通就 commit。自此每个‘能跑’版本都存档（v02），为后续折腾提供安全网。","out":"一个安全起点：首个可回退 commit","note":"‘能跑就提交’从第一步就开始做。"},{"in":"④ 前后端联调：核心功能跑通","process":"实现 MVP 的核心交互：前端调用 API（v03）、后端存取数据库（v04），把‘保存一条记录→回显’走通。","out":"核心功能端到端可用","note":"每接通一个接口就验证一次；别攒到最后一起测。"},{"in":"⑤ 数据与安全：别裸奔上线","process":"检查输入校验、密码加密、权限控制、.env 隐藏（v04）。把密钥放进环境变量并 .gitignore，绝不暴露在代码里。","out":"基础安全加固：校验+加密+权限+密钥隔离","note":"上线前必须过这一关。"},{"in":"⑥ 测试与收尾：补边界 + 回归","process":"写关键路径测试（v05）：正常/边界/异常用例；修 bug 补回归测试；整理结构让小步可维护（v06）。","out":"有自动化验证、可在后续改动中反复确认","note":"上线前至少覆盖核心链路。"},{"in":"⑦ 部署上线：搬到公网","process":"把本地跑通的版本部署到托管平台/服务器，配好环境变量、域名与 HTTPS（v07）。","out":"一个公网可访问的真实 URL","note":"本地没问题≠线上没问题，上线后立刻用真实地址自测。"},{"in":"⑧ 上线后观察：日志 + 收集反馈 + 迭代","process":"观察访问日志/报错，收集第一批真实用户反馈，按‘小步迭代’节奏继续发布新版本。","out":"持续迭代的活产品，而非一次性的 demo","note":"产品是‘上线才开始’，不是‘上线就结束’。"}]},{"type":"realworld","items":[{"name":"第一个版本只需要一个核心功能","note":"MVP 越小越容易成功上线。纪念版、仪表盘、多用户等先放 TODO，上线后再加。"},{"name":"让 AI 分模块生成","note":"不要一句‘帮我做个记账系统’；而是按 v06 结构分功能/分接口给 AI，逐个生成、逐个联调、逐个测试。"},{"name":"上线前过一遍安全清单","note":"输入校验、密钥不入库、权限默认拒绝、HTTPS——四条底线守住，避免上线即翻车。"},{"name":"把流程固化成模板","note":"把这 8 阶段存成自己的 CheckList，以后每个新项目都照跑一遍，效率和质量双保险。"}]},{"type":"compare","pairs":[{"a":"做 Demo","b":"做真产品","diff":"Demo 只要能演示关键功能；真产品要能扛真实用户、真实数据、安全与故障。流程完整、版本可控、测试兜底、安全到位。"},{"a":"一次性大开发","b":"八阶段小步","diff":"一次性憋大版本风险高、难回退；八阶段小步每步有验收与存档，翻车可回退。"},{"a":"先写代码","b":"先立项","diff":"先写代码容易做偏；先一句话立项 + MVP 边界，保证做得对再做得快。"},{"a":"上线即结束","b":"上线才开始","diff":"把上线当终点会烂尾；当做起点则持续观察、收集反馈、迭代，产品才越来越好用。"}]},{"type":"mistakes","items":["一上来就让 AI 写‘整个系统’——八成失控。按阶段、按模块小步走。","跳过大安全清单就上线——密钥泄露、可被随意改数据，上线即事故。","本地 OK 就当上线 OK——不部署真实地址自测，线上环境不同照样翻车。","不 commit / 不写测试——改坏了没法回退、回归全靠人肉，返工翻倍。","上线后不观察日志 ——用户报了 bug 你还不知道，产品口碑崩塌。"]},{"type":"ask","title":"怎么用 AI 全程辅助一个真实项目：阶段化提问","scenario":"你想做‘家庭记账本’，在不同阶段分别怎么向 AI 提问。","template":"[阶段①立项] 帮我把‘记录家庭每笔支出并生成月度统计’压缩成一个最小 MVP，给出核心功能清单和不要做的部分。\n[阶段④联调] 我的记账接口 GET /entries 报 500，报错在 db.js 第 20 行，这是日志：...，请定位根因并给修复+回归测试。\n[阶段⑦部署] 我用 Vercel 部署 Node 后端，连接本地 MongoDB，请给部署清单，指出本地与线上的环境差异点。","acceptance":["AI 是否理解你处于哪个阶段并给相应输出？","是否给出‘目标/验收/雷区’式回答，而不只是贴代码？","是否把上一阶段的产物作为下一阶段的输入？","是否提醒每步都 commit + 测试，安全清单上线前必过？"],"tip":"把项目拆成阶段，每阶段单独、具体地追问 AI：立项就问范围、联调就问具体报错、部署就问环境清单。越分阶段，越精准。"},{"type":"exercise","prompt":"你要做一个‘打卡习惯’小程序，刚从头开始。按本课流程，你第一步最该做什么？","opts":["让 AI 一次性生成完整系统","先把想法压缩成一句话 MVP 与边界，再让 AI 搭可跑骨架并立即 git commit","直接部署一个空文件夹","先写数据库表"],"a":1,"explain":"正确开局：一句话立项锁定 MVP → AI 搭可跑骨架 → 立刻 git 存档建立安全起点。之后再联调、测试、部署。","jump":"sec5-step0","jumpLabel":"立项这一步"},{"type":"check","title":"结课检测：你能独立走完一条产品生产线了吗","intro":"共 4 题。全部答对即可完成整条 Vibe Coding 工程基础路径。答错会带你回对应段落复习。","questions":[{"q":"从想法到上线，八个阶段的第一步是？","opts":["写代码","一句话立项 + 锁定最小 MVP 边界","部署服务器","写测试"],"a":1,"explain":"先想清楚‘为谁解决什么、最小做哪些’，再动手。立项是地基。","jump":"sec5-step0"},{"q":"‘本地 OK 不等于线上 OK’主要指什么风险？","opts":["线上网速更快","环境配置、依赖版本、数据库连接等与本地不一致","线上没有显示器","线上代码自动更好"],"a":1,"explain":"环境不一致是头号翻车点（密钥/数据库/版本/路径），上线后必须用真实地址自测。","jump":"sec5-step6"},{"q":"上线前必须过的基本安全底线包含？","opts":["页面好看","输入校验 + 密钥不入库(.env 隔离) + 权限控制 + HTTPS","代码注释多","视频教程"],"a":1,"explain":"输入校验防注入、密钥隔离防泄露、权限控制防越权、HTTPS 防窃听——四条底线。","jump":"sec5-step4"},{"q":"为什么每个‘能跑’的版本都要 git commit？","opts":["显得专业","形成安全存档点，后续小步迭代随时能回退，防翻车","省磁盘","为了提交给 AI 看"],"a":1,"explain":"能跑就提交，把迭代变成可回退的小步，翻车永远是‘回到上一版’而不是‘重头再来’。","jump":"sec5-step2"}],"done":"恭喜你走完 Vibe Coding 工程基础整条路径！你从‘看懂一个 Web 产品’一路走到了‘能独立用 AI 做出一个上线产品’。记住这条生产线：立项→骨架→版本→联调→安全→测试→部署→观察。现在，去做出你的第一个真产品吧。","nextLesson":""},{"type":"connection","known":["Vibe 路径前七课：Web 链路 / Git / API / 数据库 / 测试 / 结构 / 部署"],"learned":["从想法到上线的八阶段生产线与各自验收标准","每个阶段怎么把对应课程能力用上、怎么防翻车","上线只是开始，观察与迭代才是产品的常态","把流程固化成个人 CheckList 的方法"],"next":"这是 Vibe Coding 工程基础的最后一课，也是你独立做产品的起点。可以回到《从零看懂 AI》路径或继续探索更进阶的工程主题。祝你做出第一个真正上线的产品！","links":[{"href":"#/lesson/v07-deploy","text":"回看《从本地 Demo 到正式上线》"},{"href":"#/lesson/l18-vibe-coding","text":"回到核心路径《Vibe Coding 入门》"}]}]}},"byId":{"l-agent":{"id":"l-agent","title":"Agent｜让 AI 自己动手做事","subtitle":"为什么 ChatGPT 只能在对话框里打字，而 Codex 能改你的代码、跑你的测试、提交 PR？Agent 就是把『会说话』的模型，变成『会做事』的执行者。","category":"c08-agent","chapterTitle":"第一章 · 从会说到会做","level":"base","estTime":"25-30 分钟","difficulty":2,"concepts":["agent-intro","agent-loop","tool-use","agent-planning","agent-memory","agent-reflection"],"prereqLessons":["l-rag","l-transformer"],"nextLesson":"l22-ai-coding","sections":[{"type":"opening","question":"你已经能让 ChatGPT 把某个概念讲得头头是道，也能用 RAG 让它查你的资料。但如果你说『去我 GitHub 仓库里把那个测试失败修掉』——为什么 ChatGPT 只能在对话框里给建议，而 Codex 却能真的打开文件、改代码、跑测试、把活干完？","guess":"有人会说「Codex 的模型更聪明」。","next":"这节课揭穿这个误会：Agent 的厉害不在模型智商，而在于给模型装上一个『决策循环 + 一双能动手的工具』。学完你就掌握 Agent = 模型 + 工具 + 循环这条主线。"},{"type":"why","before":"到这一课，我们有了很聪明的模型、也有了让它查资料的 RAG。但你还是有个困扰：让 ChatGPT 整理个表格它倒是能，让它『去我仓库里改掉那个 bug』，它做不到。","problem":"因为聊天模型只有一张嘴：它只能输出文字，看不见你的文件、读不了你的代码、跑不了测试命令。你让它操作仓库，它连仓库在哪都不知道。","need":"Model（思考）+ Tools（手和眼）+ Loop（循环驱动）= Agent。它想一下 → 动一下 → 看一眼结果 → 再想 → 再动。这就是 ChatGPT 和 Codex 的分水岭。","visualNote":"下面这个循环图就是 Agent 的灵魂——你可以亲手点不同工具，看它每一步怎么决策、怎么应对失败。"},{"type":"oneline","text":"Agent（智能体）不是换个更厉害的模型，而是给模型装上一个『决策循环』：它会自己拆目标、自己调用工具（读写文件、执行代码、搜网页）、观察结果、再决定下一步，如此循环直到把事情做完。同样一个模型，套上这个循环，就从『只会回答』变成了『会做事』。"},{"type":"visual","kind":"agent-loop","title":"Agent 循环模拟器：想 → 做 → 看 → 再想（可交互）","hint":"这是一个升级版交互模拟器：你扮演一个修复 bug 的 Codex Agent，在每个步骤从几个工具里选一个。选对了推进，选错了会得到失败反馈，教你『Agent 正是靠不断试错修正才把活干完』。"},{"type":"intuition","blocks":[{"k":"计算器只会算，助理会办事","t":"普通聊天模型像一台高级计算器：你问它答。Agent 像你的助理：你交代一件事，它自己拆步骤、打电话（调工具）、核对结果，办完给你汇报。"},{"k":"不是变聪明，是变『能动』","t":"它没有比 ChatGPT 更聪明——它只是多了一圈『能动手、能看反馈、能再试』的回路。代码还是那个代码，差别在于它学会了执行-反馈-调整。"},{"k":"有钥匙的实习生 vs 没钥匙的实习生","t":"ChatGPT 是没钥匙的实习生：看到门（需要改文件）只会描述『你应该去改那个文件』。Agent 是有钥匙的实习生：自己开门、改文件、跑测试、看结果、再改。"}]},{"type":"how","intro":"一个 Agent 改 bug 的完整工作过程。核心就一句话：目标 → 循环（想 + 做 + 看）→ 交付。这也是本课的骨架。","steps":[{"in":"理解目标","process":"用户下达：『修好注册页面的 bug』。模型先把模糊目标翻译成具体子任务列表。","out":"一个可执行的任务清单"},{"in":"规划 Planning","process":"它推理出步骤：先找到注册页代码 → 读源码定位问题 → 想怎么改 → 改 → 跑测试验证。","out":"Agenda：找代码 → 读 → 改 → 测"},{"in":"调用工具 Tool Use（做）","process":"它请求调用工具：read_file 读代码、edit_file 修改、run_command 跑测试。工具返回结果。","out":"一次具体的『动手』"},{"in":"观察结果 Observe（看）","process":"看到工具返回值：测试报错，或编译失败。它读到反馈，判断是否达到目标。","out":"对『刚才做对没有』的感知"},{"in":"循环 Loop：再想再做","process":"若未达成，回到『想』：根据报错调整方案，再调用工具。如此循环直到测试通过或放弃。","out":"反复的 agent loop（这正是与 ChatGPT 的本质区别）"},{"in":"交付与汇报","process":"任务完成：向用户总结改了什么、测试结果，甚至主动提交 PR、申请权限。","out":"一件完成的事，而不是一段话"}]},{"type":"realworld","items":[{"name":"Codex / Claude Code","note":"Agentic Coding 的典型：能读你的仓库、找 bug、改代码、跑测试、提交 PR。这就是『ChatGPT 做不到、它做得到』的原因——它装了代码工具 + agent loop。"},{"name":"Cursor / Windsurf","note":"IDE 里的 Agent：理解整个项目上下文，跨多个文件完成重构，而不只是一行行补全。"},{"name":"浏览器 Agent（Browser Use / Operator）","note":"自己打开网页、读取、点击、填表，把逛网页办事自动化。"},{"name":"n8n / 工作流编排","note":"让 Agent 串联多个工具/API 完成端到端业务流程（取数 → 处理 → 发通知）。"}]},{"type":"compare","pairs":[{"a":"Chatbot（聊天机器人）","b":"Agent（智能体）","diff":"Chatbot 只输出文字、终结于回答；Agent 拆目标、调工具、看结果、循环迭代，终结于做成事。"},{"a":"单次工具调用","b":"多步 Agent Loop","diff":"会调一个工具的助手只是初级；真正的 Agent 会根据结果决定下一调用，持续多轮直到完成。"},{"a":"RPA（脚本化机器人）","b":"LLM Agent","diff":"RPA 按写死的剧本执行、一变就崩；Agent 动态推理、能处理没见过的异常情况。"},{"a":"Agent","b":"RAG","diff":"Agent 是『多步决策、自己调用工具的循环』；RAG 是『查资料再回答的单步机制』。Agent 需要信息时常用 RAG 当其中一个工具。"}]},{"type":"mistakes","items":["以为 Agent 只是换了个更聪明的模型。本质差别在『循环 + 工具』，不是模型本身。","以为 Agent 能无限可靠地自主执行。它也会反复失败、会犯错，所以需要权限门槛（approval gate）、观测和护栏。","忽视权限与安全。放任 Agent 删文件/发数据/花钱是最危险的坑，生产环境必须加授权与审计。","把会调用工具当成有规划和反思。会调一个函数 ≠ 会拆解复杂目标并自我修正，后者才是 Agent 的进阶。","以为多 Agent 一定更好。多数场景单 Agent 更简单可控，盲目堆 Agent 只会带来编排复杂度和成本。"]},{"type":"deep","title":"深入一点：Agent 的工程骨架","beginner":["Agent Loop 不是魔法：本质就是模型的 for/while 循环——决定下一步 → 调用工具 → 看结果 → 决定再下一步。","工具（Tool）就是一个函数：read_file、write_file、run_command、web_search。模型学会了在合适时机调用它们。","最朴素的 Agent = LLM + 工具集 + 一个决定何时停止的循环。它也可以有记忆和规划，但核心就是这个循环。"],"advanced":["Tool Use / Function Calling：模型输出结构化的『要调用哪个函数、传什么参数』，由系统执行并把结果喂回去，形成闭环。","记忆分两层：短期（当前任务的对话/工具历史）与长期（跨对话的项目知识、偏好，常存向量库）。","Planning 范式：ReAct（Reason + Act 交替）、Plan-and-Execute（先定计划再逐步执行，plan 可被动态修订）、Tree-of-Thought 等。","权限与安全 Permission：Agent 不会无限乱来——危险操作（删文件、花钱、外发数据）要求用户授权（approval gate）。","MCP（Model Context Protocol）：统一工具/数据源接入协议，让一个 Agent 能标准化接入文件系统、数据库、浏览器等多种工具，避免每家写一套私有接口。","Reflection 反思：让 Agent 回顾刚才失败的原因再调整，显著提升长任务可靠性。多 Agent 协作则是多个专业 Agent 分工。",{"code":"# 概念示意：Agent 循环的骨架，就长这样\nwhile not goal_reached:\n    thought = model.think(state, memory)      # 想：我要做哪一步？\n    if thought.should_stop: break              # 判断是否完成\n    tool_result = call_tool(thought.tool_call) # 做：调用工具\n    state.append(tool_result)                  # 看：把结果存进上下文\n    memory.update(state)                       # 记住教训\n# 交付\nreport(model.summarize(state))","lang":"python"}]},{"type":"exercise","prompt":"你（作为 Codex Agent）被要求『修好登录页的 bug』。你读完代码，发现登录按钮点击后有报错。现在到了『做』这一步——猜一猜，Agent 下一步最合理的选择是哪个？","opts":["直接凭记忆改掉一行代码","先运行测试/查看报错日志，定位错误来源，再决定改哪里","马上发邮件问用户想怎么改","直接重新写整个登录页"],"a":1,"explain":"正确动作是先『看』——运行测试或读日志拿到报错信息，有了反馈才知道要改哪。这正是 Agent loop 里『做』与『看』的配合：不观察就动手，等于闭眼改代码。","jump":"sec5-step3","jumpLabel":"观察结果 Observe 这一步"},{"type":"check","title":"结课检测：你真的理解 Agent 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 ChatGPT 不能操作你的仓库，而 Codex 可以？","opts":["因为 Codex 的模型更聪明","因为 Codex 被接上了工具（读写文件/跑命令）+ Agent 循环，ChatGPT 只有对话输出","因为 ChatGPT 没联网","因为模型大小不同"],"a":1,"explain":"决定性差异不是模型智能，而是 Agent 结构：工具让它能动手，循环让它能做→看→修正直到完成。","jump":"sec2","jumpLabel":"一句话理解 Agent 那条"},{"q":"Agent Loop 的核心循环顺序是？","opts":["看 → 做 → 想","想 → 做 → 看 → 再想","只做不看不回头","想 → 想 → 想"],"a":1,"explain":"标准 agent loop：决定下一步（想）→ 调用工具（做）→ 观察结果（看）→ 根据结果再决定下一步（再想），循环到目标达成。","jump":"sec5-step4","jumpLabel":"循环 Loop 这一步"},{"q":"MCP（Model Context Protocol）主要解决什么问题？","opts":["让模型跑得更快","统一 Agent 接入工具/数据源的接口标准，避免各家用私有协议","代替向量数据库","让模型更聪明"],"a":1,"explain":"MCP 是 Agent 与文件、数据库、浏览器等外部工具的标准化接入协议，一次接入、到处复用。","jump":"sec9","jumpLabel":"深入节里 MCP 那条"},{"q":"下面哪个最能代表『Agent 与 Chatbot 的本质区别』？","opts":["Agent 文字更长","Agent 会拆目标、调工具、看反馈并循环，终结于做成事；Chatbot 只回复文字","Agent 不需要模型","Chatbot 也能调用工具"],"a":1,"explain":"Chatbot 止于回答；Agent 以『做成事』为目标，通过循环驱动工具完成多步任务。","jump":"sec7","jumpLabel":"对比区 Chatbot vs Agent"},{"q":"为什么生产环境里 Agent 的危险操作要加『授权门槛（approval gate）』？","opts":["为了拖慢速度","Agent 也会犯错，删文件/花钱/外发数据必须先经用户确认，防止不可逆损失","模型必须要人帮它思考","为了多收费"],"a":1,"explain":"Agent 并非无限可靠，危险动作必须先授权再执行，是落地安全的关键护栏。","jump":"sec8","jumpLabel":"『忽视权限与安全』那条误区"}],"done":"你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。最后一章会带你顺着这条主线进入真正的 AI 编程实践。","nextLesson":"l22-ai-coding"},{"type":"connection","known":["Transformer：模型怎么生成内容","RAG：怎么让模型查资料","工具调用 Function Calling"],"learned":["Agent = 模型 + 工具 + 循环（想→做→看→再想）","它能拆目标、规划、调用工具、观察反馈、反复修正","关键工程点：Tool Use / Memory / Planning / Permission / MCP / Reflection","Chatbot 回答问题，Agent 做成事"],"next":"到这里，你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。想继续深入，建议顺着目标分支走：做产品学 LLM 应用与 RAG，写代码就进入 AI 编程（Agentic Coding / Claude Code）那一章——用 Agent 亲自改代码、跑测试、提交 PR。"}]},"l-attention":{"id":"l-attention","title":"Attention｜模型为什么知道该关注哪个词","subtitle":"当模型读到『它』，怎么知道是猫还是狗？为什么句子再长，模型也能把前后的词对上号？","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["attention","qkv","multihead","attention-long"],"prereqLessons":["l-embedding"],"nextLesson":"l-transformer","sections":[{"type":"opening","question":"请读这句话：「小狗跑向小猫，因为它害怕小狗。」这个『它』指的到底是小猫还是小狗？只盯着『它』一个词，谁也说不清——那 ChatGPT 是怎么判断出来的呢？","guess":"有人会说「代词当然指前面离得最近的动物」。但中文里『它』常跨好几个词、甚至跨好几句指代，光看位置根本猜不准。","next":"这节课要讲的就是模型的『读心术』——Attention 注意力机制。它让模型在处理『它』时，回头看一眼整句话，自己判断该靠哪些词来理解『它』。"},{"type":"why","before":"上节课我们把每个词变成了向量。但词是孤立的：『猫』『追』『狗』『它』，每一个都只是单独的一串数字。","problem":"真正的语言是互相指代的。『猫追狗，它跑得飞快』——这个『它』是谁？只看『它』这个词本身，根本答不上来。更糟的是：在 Attention 出现以前，老式模型（RNN）看长句时，越靠前的词就越『记不清』。","need":"我们需要一个机制：在处理任何一个词时，能直接『回看』整句话里的所有词，按相关程度加权吸收它们的信息。这就是 Attention——『注意力』，它解决了『远距离指代』和『长句遗忘』两大难题。","visualNote":"下面你可以亲手造一句中文，点任何一个词，看它把注意力分给了谁。"},{"type":"oneline","text":"Attention 是这样一种机制：模型在理解某个词时，会『回头看一眼』句子里的每一个词，给它们分别打一个权重分——分数越高的词，模型花越多注意力在它身上。于是『它』到底指猫还是狗，模型有了办法分清。"},{"type":"visual","kind":"attention-heatmap","title":"Attention 热力图：点一个词，看它关注谁","hint":"输入一句话，点任意一个词（比如那棵/那株），热力图会显示这个词对其它词的『关注权重』——颜色越深，越关注。试试改动量词，体验权重如何跟着语义线索移动。"},{"type":"intuition","blocks":[{"k":"老师点名：每读一个词都在点名","t":"读到『它』这个词时，模型其实在问：『谁能告诉我『它』指谁？』——它把问题抛向所有词，然后重点听『猫』『跑』这些最相关的答案。"},{"k":"查字典：不是顺序读，而是跳着看","t":"Attention 最反直觉的一点：它不老老实实从左往右读。读到『它』，它像翻开一本字典快速扫过所有词条，直接锁定『猫』『跑』，记下『我主要靠这几个词来理解自己』。"},{"k":"聚光灯：每个词都举着无数盏灯","t":"句子里每个词都举着一盏聚光灯照向其它词。灯越亮，代表『我理解你时越依赖你』。Attention 就是计算这盏灯亮度的过程。远近都一样亮——这是它比老方法强的地方。"}]},{"type":"how","intro":"Attention 到底怎么『算』注意力？核心就一句话：每个词同时扮演三个角色——Query（我找谁）、Key（我是谁）、Value（我的内容），然后『找相似、按相似加权吸收』。","steps":[{"in":"乘上三个矩阵，得到 Q / K / V","process":"每个词的向量分别乘以三个不同的矩阵，变成三个新向量：Query『我要去匹配谁』、Key『我是谁，请拿我来匹配』、Value『我的有效内容』。","out":"单词 → (Query, Key, Value) 三件套"},{"in":"用 Query 和所有 Key 算相似度","process":"以『它』的 Query 为例，和句子里每个词的 Key 做点积（就是 Embedding 课学过的『方向越像越接近』）。","out":"得到分数列表：它 vs 猫 = 高分，它 vs 跑 = 中等……"},{"in":"Softmax 归一化成权重","process":"把所有分数经过 softmax，变成『加起来等于 100%』的权重。这一步保证分数变成可比较、可加权的概率。","out":"注意力权重：猫 0.6、跑 0.25、飞快 0.15……"},{"in":"用权重 × Value 加权求和","process":"把每个词的 Value 乘上对应权重再全部相加。权重大的词，内容在结果里占的份量就大。","out":"『它』的新向量 = 主要吸收了『猫』的信息 → 模型知道『它≈猫』"},{"in":"每个词同时做，得到上下文向量","process":"句子里每个词都执行同一套操作，得到一批『结合了全局上下文的新向量』。","out":"整句话从一串孤立向量 → 一串互相理解的向量"},{"in":"多个头并行（多头注意力）","process":"为了不只从一种角度看，模型并行做多组 Q/K/V（不同随机初始化的矩阵），相当于多个不同视角同时观察。","out":"一个头看指代关系、另一个头看语法结构、再一个看长度……组合出更丰富的理解"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude 生成每个词","note":"每生成一个 token，模型都要对上下文做一次 Attention：决定下一个词更依赖前面的哪部分。这是生成的核心动作。"},{"name":"翻译模型的对齐","note":"把『I love you』翻成中文时，Attention 让『love』和『爱』自动对上号，哪怕位置完全错开（这就是 Cross-Attention 用武之地）。"},{"name":"代码补全","note":"补全函数体时，Attention 帮模型盯住几千行前的函数签名和参数定义，而不是只看到最近几行。"},{"name":"长文档问答","note":"在长文章里问『第三部分的结论是？』，Attention 让模型跳过大段无关内容，直接聚焦第三部分的句子。"}]},{"type":"compare","pairs":[{"a":"RNN 顺序处理","b":"Attention 全局直连","diff":"RNN 必须一个字一个字按顺序传，远处信息会衰减；Attention 让任意两个位置直接相连，没有距离衰减。"},{"a":"Self-Attention","b":"Cross-Attention","diff":"Self 是同句话内部互相理解；Cross 是让一方去『读』另一方（翻译、RAG 上下文注入都用它）。"},{"a":"单头注意力","b":"多头注意力","diff":"单头只有一种看法；多头并行多组 Q/K/V，相当于同时用多个角度理解，效果明显更好。"},{"a":"注意力（Attention）","b":"记忆（Memory）","diff":"注意力是每次计算时动态算出的关注权重，不存下来；记忆是存下来的长期信息。很多人把注意力误当成记忆。"}]},{"type":"mistakes","items":["以为 Attention 是『看一遍就记住』的长期记忆。它不是记忆，而是每次计算时动态分配的关注权重——每次都要重新算，不会存下来。","以为注意力可视化等于模型的可解释性。权重高代表统计上相关，不代表模型逻辑上『是因为这个』。","把『注意力』和『上下文窗口』混为一谈。窗口决定能看多远，Attention 决定窗口内怎么分配关注。","以为只看『最近几个词』。Attention 恰恰是全局的——它牺牲计算量，换来的是真正看全上下文。","以为 Attention 零成本。它的核心开销是 O(n²)：n 个词两两算一遍。这正是上下文窗口成为瓶颈的原因。"]},{"type":"deep","title":"深入一点：从直觉到公式","beginner":["注意力权重加起来等于 1（100%）。Softmax 就是把一坨分数变成『加起来为 1、且大的更大』的数。","不必纠结矩阵怎么算，你只需记住一句口诀：『Query 找人，Key 被找，Value 是内容，三者相乘加权求和』。","它最厉害的地方：任意两个词无论隔多远都能直接相关——远处那个词和眼前这个词，算注意力的成本完全一样，这是它战胜 RNN 的根本原因。"],"advanced":["核心公式：Attention(Q, K, V) = softmax( (Q·Kᵀ) / √d ) · V。除以 √d（d 是向量维度）是为了防止点积过大把 softmax 压死、导致梯度消失。","Self-Attention 的 Q/K/V 都来自同一句话，让句子内部互相理解；Cross-Attention 的 Q 来自一方、K/V 来自另一方（如翻译、RAG 上下文注入）。","复杂度 O(n²)：n 个词两两都算一遍。这正是上下文窗口成为瓶颈的原因，也是稀疏注意力、局部注意力、线性注意力研究的动机。","不要神化注意力可视化：权重高 ≠ 模型真『懂』了，它更多是统计相关而非可解释的因果。",{"code":"# 概念示意：手工算一次注意力（极简 2 词版）\nimport math\n\ndef softmax(xs):\n    ex = [math.exp(x) for x in xs]\n    s = sum(ex)\n    return [e / s for e in ex]\n\nq = [1.0, 0.0]  # 我是『它』的 Query\nks = {\"猫\": [0.9, 0.1], \"狗\": [0.2, 0.8]}  # 两个词的 Key\n\nscores = {w: round(q[0]*k[0] + q[1]*k[1], 3) for w, k in ks.items()}\nprint(\"点积分数:\", scores)\nweights = dict(zip(scores, softmax(list(scores.values()))))\nprint(\"softmax 权重:\", {w: round(v,3) for w,v in weights.items()})\n# 猫的权重明显更高 → 模型认为『它』更像猫","lang":"python"}]},{"type":"exercise","prompt":"「它拿起了那支笔，因为【　】太亮了。」这个【　】里的词，会让『太亮了』把更多注意力分给『笔』而不是『它』，你能猜出最合理的一个词吗？","opts":["灯","笔帽","手","桌"],"a":0,"explain":"『灯太亮了』语义合理，Attention 会让『亮』和『灯』形成高权重连接；而『笔帽太亮了』虽然通顺，但更重要是体会：有了『亮』这个线索，Attention 会去找『最配得上的名词』。模型正是靠大量这样的共现线索来分配注意力。","jump":"sec5-step1","jumpLabel":"用 Query 和 Key 算相似度这一步"},{"type":"check","title":"结课检测：你真的理解 Attention 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"Attention 中 Query、Key、Value 各自的作用，最准确的说法是？","opts":["Q 是内容，K 是找人，V 是被找","Q 在找人，K 是被找的标签，V 是被吸收的内容","三者完全相同","Q 是权重，K 是分数，V 是标签"],"a":1,"explain":"Q（Query）发起匹配去『找谁』；K（Key）告诉别人『我是谁』供匹配；V（Value）是被加权吸收进的真正内容。","jump":"sec5-step0","jumpLabel":"乘上三个矩阵得到 Q/K/V 这一步"},{"q":"为什么说 Attention 解决了 RNN『记不住长句』的问题？","opts":["因为它是顺序处理的","因为任意两个词都可以直接相关，不随距离衰减","因为它把句子变短了","因为它只关心最近的词"],"a":1,"explain":"RNN 依赖顺序传递、距离远信息衰减；Attention 让任意两个位置直接相连、远近一视同仁。","jump":"sec8","jumpLabel":"『以为只看最近几个词』那条误区"},{"q":"把注意力分数做 softmax 是为了什么？","opts":["让负数变成正数","让分数变成加和为 1 的权重，且强调大的","让计算更快","让向量变短"],"a":1,"explain":"Softmax 把一坨任意分数变成『加起来为 1』、且大者更大的概率分布，这样加权求和才合理、可解释。","jump":"sec5-step2","jumpLabel":"Softmax 归一化成权重这一步"},{"q":"Self-Attention 与 Cross-Attention 的区别是？","opts":["没有区别","Self 是同句话内部互相理解；Cross 是让一方去读另一方","Self 只用于图片，Cross 只用于文字","Self 更快，Cross 更慢"],"a":1,"explain":"Self-Attention 的 Q/K/V 来自同一句话；Cross-Attention 的 Q 来自一方、K/V 来自另一方（翻译、RAG 都用）。","jump":"sec7","jumpLabel":"对比区里的 Self vs Cross 那一条"},{"q":"多头注意力（Multi-Head）的本质好处是？","opts":["让模型更快","让模型从多个不同视角同时理解，组合出更丰富的语义","让上下文窗口变长一倍","省掉 Softmax"],"a":1,"explain":"把模型注意力想象成多个不同的专家，各看一面（指代、语法、距离），最后合并，理解更全面。","jump":"sec5-step5","jumpLabel":"多个头并行这一步"}],"done":"你已经理解 Attention 是 Transformer 的心脏。这个『找相似、加权吸收』的机制，也是后面 RAG 把检索结果喂进模型时的同一套逻辑。","nextLesson":"l-transformer"},{"type":"connection","known":["词 → 向量（Embedding）","向量方向越像、语义越近（余弦相似度）"],"learned":["每个词同时扮演 Query / Key / Value 三角色","注意力 = 相似度分数 → softmax 权重 → 加权求和","Self-Attention 让句子内部互相理解，多头提供多视角","Attention 任意位置直连、无距离衰减，解决了长句遗忘"],"next":"Attention 是 Transformer 的心脏。下一课我们把这套注意力装进一个完整的架构：位置编码、多头、归一化……看看它怎么组成一个能真正训练、能翻译能写诗的大模型——Transformer。"}]},"l-embedding":{"id":"l-embedding","title":"Embedding｜怎么把词变成电脑能懂的数字","subtitle":"为什么文字不能直接进神经网络？为什么不是给每个词编个号？为什么意思相近的词离得更近？","category":"c02-essentials","chapterTitle":"第一章 · 向量与语义","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["embedding","vector","cosine-similarity","emb-vector-store"],"prereqLessons":["l00-ai-world"],"nextLesson":"l-attention","sections":[{"type":"opening","question":"你让 ChatGPT 翻译『苹果很好吃』，它内部第一件事不是『读懂』这句话，而是把『苹果』变成了一串数字。猜一猜：为什么电脑不能用『苹果』这两个汉字直接思考，非得多此一举先转成数字？","guess":"有人会想：给猫=1、狗=2、苹果=3 编个号不就行了？","next":"这节课就回答『为什么不能简单编号』，以及真正的 Embedding 是怎么做到『意思相近的词，数字也相近』的。"},{"type":"why","before":"神经网络只会做数学运算：加法、乘法、比较大小、算距离。它天生看不懂『猫』『狗』『苹果』这些文字。","problem":"如果文字根本送不进神经网络，那后面的一切——翻译、对话、理解、检索——全都是空中楼阁。这是所有语言模型的『第一道门』，绕不过去。","need":"所以我们必须在『文字』和『数字』之间搭一座桥，让电脑既能「算」文字，又能保留文字的含义。这座桥就是 Embedding。","visualNote":"下面这张 2D 语义空间图，就是你要带走的直觉：位置 = 语义。"},{"type":"oneline","text":"Embedding 就是把『一个词』变成『一串数字（向量）』，并且让意思相近的词，数字串长得也相近——于是电脑就能『算』语义了。"},{"type":"visual","kind":"embedding-space","title":"Embedding 2D 语义空间（可交互）","hint":"这是把词『压扁』到二维的示意：意思相近的词会聚在一起。观察猫/狗/狮子聚在『动物角』，苹果/香蕉聚在『食物角』。试试输入几个词，看它落在哪一群。"},{"type":"intuition","blocks":[{"k":"为什么不能直接给词编号？","t":"你可能会想：猫=1、狗=2、苹果=3 不就行了？但问题是：2 和 3 只差 1，可『狗』和『苹果』的语义差得十万八千里。编号把『数字距离』和『语义距离』完全搞乱了——电脑会误以为狗和苹果几乎一样。"},{"k":"用一张坐标纸来想","t":"想象一张地图，横轴是『是不是动物』，纵轴是『是不是食物』。『猫』放左边靠上，『狗』紧挨它，『苹果』放右上角。位置越近，意思越像。Embedding 本质就是在几百上千维的『坐标纸』上，给每个词找个位置。"},{"k":"一个生活类比","t":"就像地理坐标：北京和天津坐标很近，所以在空间里相邻；语义相近的词，在 Embedding 空间里坐标也相邻。"}]},{"type":"how","intro":"Embedding 是怎么『学』出来的？核心思想只有一句话：一个词的含义 = 它经常和哪些词一起出现。","steps":[{"in":"收集海量文本","process":"从整个互联网语料里，观察『猫』总是和『狗、宠物、喵、毛』一起出现，而『苹果』总跟『水果、吃、红色』一起出现。","out":"得到每个词在语料里的『共现模式』"},{"in":"用共现模式训练向量","process":"训练一开始给每个词一组随机数字，然后不断调整，让『经常一起出现』的词向量越走越近，『从不一起出现』的词向量越走越远。","out":"每个词最终固定成一个固定长度的向量（如 300 或 768 维）"},{"in":"用向量距离比较语义","process":"两个词的向量越接近（夹角越小、余弦相似度越高），语义越相近。电脑从此『算得出』猫≈狗、苹果≠猫。","out":"文字第一次可以被数值比较"},{"in":"送入下游模型","process":"这个数字向量就是神经网络的输入。LLM 只认数字，现在它『看得懂』词了，可以开始做翻译、对话、生成。","out":"模型能对词做运算、比较、生成"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude","note":"内部第一件事就是把你的每个 Token 转成 Embedding 向量，再送进 Transformer 网络。"},{"name":"搜索引擎语义检索","note":"把『怎么养猫』和『养宠物指南』都向量化，语义相近就能互相匹配，不必字面相同也能搜到。"},{"name":"NotebookLM / RAG","note":"把你的资料切成块并向量化，用户提问时在向量空间里『找最像的那几块』再交给模型回答——这就是 RAG 的地基。"}]},{"type":"compare","pairs":[{"a":"Token","b":"Embedding","diff":"Token 是文字切出的『小块』（词/子词）；Embedding 是把每个小块变成的『数字向量』。先切 Token，再做 Embedding。"},{"a":"Embedding 模型","b":"LLM","diff":"Embedding 模型把文本压成『定位向量』（不生成文字）；LLM 生成文字。一个是『编码员』，一个是『作家』。"},{"a":"One-hot 编号","b":"Embedding","diff":"One-hot 让所有词互相『等距』、无法表达语义；Embedding 让相近的词更近，真正抓住含义。"}]},{"type":"mistakes","items":["以为 Embedding 只是『给每个词一个数字』。其实是一整串数字（向量），且数字之间存在『相似关系』——这才是关键。","以为 Embedding 模型和 LLM 是同一个东西。它们是分工不同的两个模型：一个负责编码相似度，一个负责生成文字。","以为向量维度越高一定越好。维度越高表达力越强，但更贵、更易过拟合，常见几百维就够用。","以为 Embedding 能『理解逻辑』。它只捕捉统计上的相似，不保证逻辑正确——所以光靠 Embedding 做问答会答非所问。"]},{"type":"deep","title":"深入一点：从二维直觉到真实向量空间","beginner":["Embedding 在工程上就是『查表』：模型里有一张巨大的表，每个词一行，那一行数字就是它的向量。训练好了之后，直接用查到的数字即可。","维度越高，能表达的语义越细腻，但计算越贵。常见几百维就够处理大多数任务。","真正常用的是一种叫『子词』的粒度：一个字被拆成更小的片段（如 'unbreakable' → 'un' + 'break' + 'able'），这样遇到没见过的词也能拼出向量。"],"advanced":["向量不只给每个词一个『标签』，它把语义结构编进了几何里：经典例子 king − man + woman ≈ queen，说明向量『方向』也承载意义。","Embedding 模型（如 text-embedding 系列）与 LLM 是不同模型：前者把文本压缩成『定位码』，后者生成文字。它们可以分开训练、分开使用。","计算两个向量有多像，最常用的指标是**余弦相似度** cos(θ)：只看方向、不看长度，数值越接近 1 越像。",{"code":"# 余弦相似度：越大越像\nimport numpy as np\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\ncat   = np.array([0.9, 0.1])   # 靠近动物方向\napple = np.array([0.1, 0.9])   # 靠近食物方向\ndog   = np.array([0.85, 0.15]) # 很接近猫\n\nprint(round(cosine(cat, apple), 2))  # 0.22  → 语义远\nprint(round(cosine(cat, dog), 2))    # 1.0   → 语义很近","lang":"python"},"维度本质：真实 Embedding（如 OpenAI text-embedding-3）常达上千维，一个词就是一个上千维空间里的点。降维可视化（t-SNE / PCA）只是把上千维『压扁』到 2D 方便人看。"]},{"type":"exercise","prompt":"在一个语义空间里，『国王』向量减去『男人』向量，再加上『女人』向量，猜一猜结果最可能靠近下面哪个词？","opts":["王子","女王（皇后）","父亲","阿姨"],"a":1,"explain":"这正是著名的 king − man + woman ≈ queen 现象：向量的方向承载意义，『王 - 男 + 女』就指向『女王』的方向。它说明 Embedding 抓到的不是孤立的词，而是语义结构。","jump":"sec5-step3","jumpLabel":"用向量距离比较语义这一步"},{"type":"check","title":"结课检测：你真正理解 Embedding 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么不能直接给每个词编个号（猫=1，狗=2，苹果=3）？","opts":["因为编号会让相近的词距离更近","因为编号会破坏语义距离：狗和苹果只差 1，但语义差很远","因为编号需要太多内存","因为编号不能用于神经网络"],"a":1,"explain":"编号把数字距离和语义距离搞混了：狗(2)和苹果(3)只差1会被当成很相似，但它们的含义毫无关系。","jump":"sec4","jumpLabel":"『为什么不能直接给词编号』这一段"},{"q":"两个 Embedding 向量夹角越小（余弦相似度越高），说明什么？","opts":["两个词的语义越相近","两个词的字符串越长越像","两个词出现频率越接近","两个词的长度越接近"],"a":0,"explain":"夹角越小，向量在空间里越靠近，代表语义越相近。这就是『用距离算语义』。","jump":"sec5-step2","jumpLabel":"『用向量距离比较语义』这一步"},{"q":"关于 Embedding 模型与 LLM 的关系，正确的是？","opts":["它们是同一个模型","Embedding 模型把文本变向量、LLM 生成文字，二者分工不同","LLM 内部根本不做 Embedding","Embedding 模型能直接写文章"],"a":1,"explain":"Embedding 模型负责『编码相似度』，LLM 负责『生成内容』，是两个可分开训练的模型。","jump":"sec7","jumpLabel":"『Embedding 模型 vs LLM』那一条对比"},{"q":"Embedding 的『含义』主要来自哪里？","opts":["每个字在字典里的官方解释","这个模型『预测下一个词』时学到的共现模式","开发者手写的规则","词的笔画数"],"a":1,"explain":"一个词的含义 = 它常和哪些词一起出现。模型在大量文本上学到的正是这种共现模式。","jump":"sec5-step0","jumpLabel":"『收集海量文本』这一步"},{"q":"下面哪句关于向量维度的说法正确？","opts":["维度越高一定越好，越细越好","维度越低越好，因为一定更便宜","维度是表达力与成本的权衡，常见几百维就够用，过高更贵且易过拟合","维度只影响颜色不影响语义"],"a":2,"explain":"维度是权衡的结果：高维表达强但贵且易过拟合，低维省但表达粗糙。实际常用几百维。","jump":"sec9","jumpLabel":"深入一节关于维度的说明"}],"done":"你已经理解了『文字 → 数字向量 → 算距离』这条链路，这是 RAG、搜索、推荐共同的地基。","nextLesson":"l-attention"},{"type":"connection","known":["AI 世界全景：模型只能处理数字","Embedding 是文字进入模型的第一道门"],"learned":["文字 → 向量，让电脑能算语义","相近的词向量距离更近，用余弦相似度衡量","Embedding 模型与 LLM 分工不同","向量方向也能承载意义（king − man + woman ≈ queen）"],"next":"有了『每个词是一个数字向量』，下一步就是大招：Attention——模型怎么在一句话里决定『该重点关注哪个词』。这决定了模型能不能读懂『这只狗没咬那只猫，是因为它怕它』里『它』到底指谁。"}]},"l-rag":{"id":"l-rag","title":"RAG｜让模型『查资料』再回答","subtitle":"为什么 ChatGPT 不知道你的私有文档？怎么让模型『翻开你的资料』再回答？从切块到生成，一条流水线看懂 RAG。","category":"c07-rag","chapterTitle":"第一章 · RAG 全流程","level":"base","estTime":"30-35 分钟","difficulty":2,"concepts":["rag-pain","rag-pipeline","chunking","emb-vector-store","vector-search","rerank"],"prereqLessons":["l-transformer","l-embedding"],"nextLesson":"pl-function-calling","sections":[{"type":"opening","question":"你的同事把公司 80 页的员工手册发给你，让你问 ChatGPT『年假到底有几天』。但 ChatGPT 根本没见过这本手册——你猜它是会照着手册答，还是自己编一个答案？如果它答错了，该怎么办？","guess":"很多人觉得「那就把整本手册贴上问它」。但手册几十万字，靠粘贴根本塞不进一次对话，而且重点会淹没在噪声里。","next":"这节课要讲的就是正解：RAG 检索增强生成。它让模型在回答前，先去你的资料库里『只挑最相关的几段』，再照着这几段回答——既答得准，又附出处。"},{"type":"why","before":"经过前面几课，我们已经有了一个很聪明的模型（Decoder-only Transformer）。但它有一个致命限制：它只知道训练时见过的东西，而且经常一本正经地编造（幻觉）。","problem":"1) 你的合同、内部 SOP、论文——模型训练时根本没看过；2) 即使看过，版本也早就过期了；3) 让它硬答私有问题，它大概率会编。而重新训练整个模型，又贵又慢又不可能频繁做。","need":"与其改模型的『脑子』，不如每次回答时给它配一本『说明书』：先把相关的资料找出来喂给它，让它照着说。这个思路就是 RAG——简单、便宜、资料随时能更新。","visualNote":"下面这条流水线是 RAG 的完整精神：切块 → 向量化 → 检索 → 重排 → 组装 → 生成。你可以点『运行』亲手体验。"},{"type":"oneline","text":"RAG（检索增强生成）就是：让模型在回答之前，先去你的资料库里检索相关内容，把查到的片段拼进上下文，再让模型照着一小份『精选资料』作答。于是它能回答自己没学过的私有知识，还能顺便指出出处。"},{"type":"visual","kind":"rag-pipeline","title":"RAG 完整流水线：从文档到回答（可交互）","hint":"这就是升级版可交互 RAG 实验：左边填一份『你要提问的文档』，下面输问题，点【▶ 运行 RAG】。观察系统如何切块 → 向量化 → 检索 → 重排 → 组装上下文 → 生成带引用的回答。"},{"type":"intuition","blocks":[{"k":"开卷考试 vs 闭卷考试","t":"普通 LLM 是闭卷考试：只凭脑子里的记忆答题，记不住就编。RAG 是开卷考试：允许你翻资料，翻到相关的那页再答。显然开卷更可靠、更可核对。"},{"k":"图书馆查书再回答","t":"你问『公司年假制度是什么』。RAG 不会直接在记忆里编，而是先去公司知识库检索年假相关文档，找到后引用着回答。"},{"k":"不是变聪明，是带了参考书","t":"RAG 不提升模型智商，而是每次回答都带着最新、属于你的资料。资料一更新，回答立刻跟着更新，完全不用重新训练模型。"}]},{"type":"how","intro":"RAG 分两个阶段：『入库』（离线，把文档变成可检索的向量库）和『查询』（在线，用户提问时检索 + 生成）。下面是完整流程，也是本课的主干。","steps":[{"in":"先想清楚：为什么要用 RAG","process":"场景判断：需要回答私有/最新/超长知识，或答案需要可溯源时用 RAG。如果模型自带答案且内容不敏感，也许不需要 RAG。","out":"RAG 解决『知识更新与私有化』，不是『让模型变聪明』"},{"in":"解析 Parsing","process":"把原始文档（PDF、Word、网页）用解析器抽取出结构化文本，去掉页眉页脚、图表残渣，必要时做 OCR。","out":"干净、可用的纯文本"},{"in":"切块 Chunking","process":"把长的文本切成几百到上千字的小块。切多大、是否重叠、按什么切（标题/段落）直接影响检索质量。","out":"文档 → 若干 chunk（带来源、页码等元数据）"},{"in":"向量化 Embedding","process":"用 Embedding 模型把每个 chunk 变成一个向量（语义相近的向量相近）。","out":"每个 chunk → 一个向量"},{"in":"存入向量库 VectorDB","process":"把『向量 + 原文 + 元数据』存进向量数据库（FAISS、Milvus、pgvector、Qdrant），并建好索引以便毫秒级检索。","out":"可快速相似检索的向量库"},{"in":"检索 Retrieval（含 Top-K）","process":"用户提问时，把问题也向量化，在向量库里找最像的『Top-K 块』（通常 K=5~20，按余弦相似度排名）。","out":"问题 → 排好序的 N 个候选 chunk"},{"in":"重排序 Rerank","process":"初筛的 Top-K 往往有噪音。用一个更精细的模型把 K 个候选再精排，把真正相关的提到最前、滤掉无关项。","out":"更精准的少量片段（通常取前 3~5 块）"},{"in":"组装上下文 + 生成","process":"把精选 chunks 拼进 Prompt，附上问题，提示模型『只依据下面资料回答并引用出处』。LLM 据此生成带引用的回答。","out":"有出处、可更新、针对私有知识的回答"}]},{"type":"realworld","items":[{"name":"NotebookLM","note":"你上传 PDF/视频，它检索你的资料再回答，还能生成带引用的播客、摘要。教科书级 RAG 产品。"},{"name":"企业内部知识库客服","note":"把 SOP、产品手册向量化，客服 AI 查文档再回答，而不是对着空气编。"},{"name":"Claude Projects / 附件上传","note":"给对话挂上资料，模型按需检索引用，本质是一套轻量 RAG。"},{"name":"搜索增强的 ChatGPT / Perplexity","note":"它先联网检索实时网页，再基于检索结果回答——用互联网当『向量库』的 RAG。"}]},{"type":"compare","pairs":[{"a":"RAG","b":"微调 Fine-tuning","diff":"RAG 每次查最新资料、可溯源、便宜、可随时更新；微调是改模型脑子、更适合学风格学格式。知识类更新首选 RAG。"},{"a":"向量检索（语义）","b":"关键词检索（BM25）","diff":"向量找语义相近（换个说法也能找到）；关键词精准匹配字面（找人名/编号更稳）。生产常用『混合检索』互补。"},{"a":"RAG","b":"超长上下文","diff":"RAG 主动挑最相关片段、便宜快速；超长上下文把整本书塞进去、贵且重点容易淹没。大资料库优先 RAG。"},{"a":"RAG","b":"Agent","diff":"RAG 是『查资料再回答的单步机制』；Agent 是『多步决策、自己调用工具的循环』。两者常配合：Agent 需要信息时用 RAG。"}]},{"type":"mistakes","items":["以为 RAG = 把文档一股脑塞进提示词。真正的 RAG 要先切块、向量化、检索、重排，只喂最相关的几块。","忽略 chunking 质量。切坏了，再好的模型也答不准——检索进来自的都是垃圾，这叫『垃圾进、垃圾出』。","以为检索到就完了、不必做 rerank。初检的 Top-K 常有噪音，重排能明显提高准确率。","忘记引用溯源。落地到医疗/法务/企业等严肃场景，没有出处等于不可信。","把 RAG 当成解决幻觉的万灵药。资料里没有、或检索失败时，模型照样可能编——还要做『越权拒答』『检索兜底』。","只在单文档上跑 RAG 就上生产。跨多文档局部推理（关系、总分结构）需要更进阶的方案（如 GraphRAG、切分策略优化）。"]},{"type":"deep","title":"深入一点：把 RAG 的每一个零件都拆开","beginner":["chunk 太小 → 语义不完整；chunk 太大 → 噪音多、可能被截断。常见几百~一千字，配合 20%~50% 重叠（overlap）避免把完整语义在边界切断。","向量相似 ≠ 字面相似：换个说法（『年假』vs『带薪假期』）有时也能检索到，这是向量检索比关键词强的地方。","RAG 不会凭空创造知识，它只会引用你给的东西——资料库质量 ≈ 回答质量。","Top-K 的含义：K 是取前几个相似块。K 太小漏信息，K 太大引入噪音挤占上下文，通常 5~20 之间调。"],"advanced":["混合检索（Hybrid）：向量检索（语义）+ 关键词检索（BM25，精确匹配人名/编号）并行，再用加权或 RRF 融合，互补漏检。","Rerank 为什么必要：初检向量健壮但不精，专门的 rerank 模型（cross-encoder）能逐对精判相关性，显著提升准确率和最终回答质量。","引用溯源（Citation / Grounding）：让模型输出带片段编号，用户可核对来源；对合规落地几乎是刚需。","切分进阶：按章节/标题等『结构感知』切块（structure-aware chunking）、父子块（parent-child）、滚动窗口，都比盲目按字数切更好。","评估：用『召回率（该找到的找到没）+ 准确率（找到的是不是都相关）』评价检索，用『忠实度/有据率』评价最终回答，还要做『检索失败与拒答』的兜底。","Agentic RAG：把检索从单次升级成『多轮自主规划』——Agent 先判断需要什么信息、决定检索哪几个库、必要时多轮追问或修正查询词，而不是一次检索定死。",{"code":"# 概念示意：RAG 里最核心的一步——向量检索（伪代码思路）\nimport numpy as np\n\nchunks = [\"年假制度：入职满一年享 5 天…\", \"报销流程：金额低于 1000 走 OA…\"]\nchunk_vecs = [np.array([0.9, 0.1]), np.array([0.1, 0.9])]  # 示意向量\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\nquery_vec = np.array([0.85, 0.15])  # 用户问题『年假有几天』向量化\ntop_k = 1\nranked = sorted(((cosine(query_vec, v), i) for i, v in enumerate(chunk_vecs)),\n                reverse=True)[:top_k]\nprint('最相关的资料块:', chunks[ranked[0][1]])\n# → 年假制度那一段","lang":"python"}]},{"type":"exercise","prompt":"继上一课：公司手册 80 页，你的知识库已经把它切成几百块并存好向量。现在问『年假有几天』，系统检索返回了 8 个候选块，其中第 3 块是『员工福利总览』、第 7 块是『请假制度细则』。下一步系统应该做什么？","opts":["直接把 8 块全部塞进提示词","对 8 块做 Rerank 精排，只取最相关的 3~5 块再喂给模型","不用检索了，直接让模型猜","把 8 块向量相加存回库里"],"a":1,"explain":"初检的 Top-K 常有噪音。正确做法是先 Rerank 精排，把真正相关的『请假制度』提到最前、滤掉无关的『福利总览』，再只喂少量精选块给模型——既省上下文又更准。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"type":"check","title":"结课检测：你真的理解 RAG 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"RAG 解决的核心问题是？","opts":["让模型数学更好","让模型能回答私有/最新知识并可溯源，而不用重新训练","让模型更快生成","让模型学会编程"],"a":1,"explain":"RAG 的核心价值：用检索到的外部资料补充模型没学过的知识，便宜、可更新、可引用。","jump":"sec5-step0","jumpLabel":"先想清楚为什么要用 RAG 这一步"},{"q":"RAG 的『入库』阶段，正确的顺序是？","opts":["向量化 → 切块 → 存库","切块 → 向量化 → 存库","存库 → 向量化 → 切块","检索 → 切块 → 向量化"],"a":1,"explain":"先把长文档切成 chunk，再逐块向量化，最后连向量带原文存进向量库。检索是查询阶段的事。","jump":"sec5-step2","jumpLabel":"切块 Chunking 这一步"},{"q":"『切块太大（比如把整章当一个块）』最可能带来什么问题？","opts":["向量库存不下","块内噪声多、关键信息被淹没，检索和回答变差","一定比小块更准","会让模型忘掉上下文"],"a":1,"explain":"块太大噪声多、语义杂，检索命中后无关内容挤占上下文，回答质量下降。所以要用合适的块大小 + 重叠。","jump":"sec9","jumpLabel":"深入节里关于 chunk 大小/重叠的说明"},{"q":"为什么生产系统里还要做 Rerank 重排？","opts":["为了多花一点算力","初检的 Top-K 常有噪音，用更精细的模型重排能显著提升相关性与准确率","为了把回答变长","为了跳过 Embedding"],"a":1,"explain":"向量初检健壮但不精，专门的 rerank 模型能逐对精判，把真正相关的片段提到最前。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"q":"资料库里根本没有答案时，一个设计良好的 RAG 系统应该？","opts":["强行编一个最像的答案","在引用不到出处时明确『资料中未找到』或拒答，做检索兜底","把用户问题原样丢回","删掉这个问题"],"a":1,"explain":"RAG 不是幻觉万灵药。检索不到可靠出处时应『越权拒答/检索兜底』，而不是硬编。","jump":"sec8","jumpLabel":"『把 RAG 当万灵药』那条误区"}],"done":"你已经掌握 RAG 的完整流水线和调优要点。现在模型会查资料了，但它还是『你问一句、它答一句』。最后一课，我们让它自己动起手来。","nextLesson":"l-agent"},{"type":"connection","known":["Embedding：文字 → 向量，语义相近的向量相近","Transformer：模型的脑子","上下文窗口：模型一次能看多少"],"learned":["RAG 让模型先检索资料再回答，解决私有/最新/可溯源","完整流程：解析 → 切块 → 向量化 → 向量库 → 检索 Top-K → 重排 → 组装 → 生成 + 引用","chunk 大小/重叠、混合检索、Top-K、rerank、评估、Agentic RAG 等调优点","RAG vs 微调 vs 长上下文 vs Agent 的取舍"],"next":"RAG 让模型会查资料，但模型仍停在你说一句、它应一句。下一课是这个旅程的终点也是新起点：Agent——让模型自己拆目标、自己调用工具、根据反馈循环，把一整件事独立做完。"}]},"l-transformer":{"id":"l-transformer","title":"Transformer｜大模型的地基架构","subtitle":"为什么 2017 年诞生的它，能横扫翻译、写作、代码、对话？一个 20 分钟看懂『大模型的心脏是怎么拼出来的』。","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"25-30 分钟","difficulty":3,"concepts":["transformer","position-enc","multihead","attention"],"prereqLessons":["l-attention"],"nextLesson":"l12-context-window","sections":[{"type":"opening","question":"上一课我们有了 Attention，它能让任何两个词互相关注。但只用 Attention 还是没法当一个能工作的模型——它不知道『第 5 个词和第 2 个词』谁先谁后，也堆不了很深。猜一猜：研究人员 2017 年到底在 Attention 外面『加了哪些零件』，才把它拼成了横扫一切的 Transformer？","guess":"很多人以为 Transformer = Attention，觉得『注意力』就是全部。","next":"这节课我们把注意力装进完整的大脑：位置编码、多头、残差、归一化、前馈网络、N 层堆叠。学完你就明白，为什么它能取代 RNN、成为所有大模型的共同地基。"},{"type":"why","before":"上一课我们有了 Attention：任何两个词都能直接互相关注。但这只是一块『积木』，离一个能真正工作的模型还差很远。","problem":"只靠 Attention 不够：1) 它不知道词的位置——『猫追狗』和『狗追猫』词全一样；2) 一层注意力学到的东西有限；3) 想堆深又容易训练不动（梯度消失）。","need":"Transformer 就是给 Attention 配上『位置感、深度、稳定训练』三件装备，把一块积木组装成一台可以训练、可以并行、可以堆得极深的机器。它是 ChatGPT、Claude、Gemini 的共同地基。","visualNote":"下面这张图是 Transformer 的主干流水线，你可以一步一步点开看每一层在干什么。"},{"type":"oneline","text":"Transformer 是 2017 年提出的一个『把注意力机制组装成完整大脑』的架构：它用『多头注意力 + 前馈网络 + 残差连接 + 位置编码』堆成一层又一层的模块，能并行、能训练得非常深，从此成为所有现代大语言模型的共同地基。"},{"type":"visual","kind":"transformer-flow","title":"Transformer 主干流水线：一步一步看","hint":"点击【下一步】，观察一个词从数字向量走到预测下一个词的完整过程：输入 → 位置编码 → 多头注意力 → 残差+归一化 → 前馈网络 → 重复堆叠 → 输出。"},{"type":"intuition","blocks":[{"k":"一个加工厂流水线","t":"把 Transformer 想成一家加工厂：原料是一串向量。每个工位（层）做两件事——同事协作（注意力，大家互通信息）+ 个人精加工（前馈网络，每个词独自想更深）。一层做完送下一层，共 N 层。"},{"k":"用乐高积木来想","t":"Attention 只是其中一块积木。Transformer 是说明书：告诉你这一层要怎么拼——注意力 + 残差 + 归一化 + 前馈，然后复制粘贴 N 次。"},{"k":"办公室里的并行会议","t":"RNN 像只有一个话筒的圆桌，每人必须轮流说（慢）；Transformer 像微信群——所有人同时发言、同时收听（并行快），谁跟谁相关自己匹配（注意力）。这就是它又快又强的秘密。"}]},{"type":"how","intro":"一个词在 Transformer 里的完整旅程。每一步都围绕同一批向量做变换，最后模型学会『预测下一个词』。","steps":[{"in":"输入：词向量 + 位置编码","process":"每个词先查表得到 Embedding 向量。但向量本身不含位置，所以再加一个位置信息（位置编码），让模型知道『这是第 5 个词』。","out":"每个词都带上位置的向量"},{"in":"多头注意力层（同事协作）","process":"这一层让每个词结合全局上下文：用上节课的 Q/K/V 机制，多组并行，输出再拼接。词的『含义』从此包含了周围所有词。","out":"每个词变成理解上下文后的新向量"},{"in":"残差连接 + 归一化（稳定训练）","process":"把『进来的向量 + 注意力算完的向量』加在一起（残差），再做归一化。这就像修了一条高速公路：信息不衰减地直接流过深层。","out":"浅层信息能无损抄近道到达深层，网络可以堆得深"},{"in":"前馈网络 FFN（个人精加工）","process":"一个两层全连接网络，对每个词独立做非线性变换，让模型有能力表达更复杂的关系。","out":"每个词被再想一想，表达能力增强"},{"in":"重复堆叠 N 层","process":"把『注意力 + 残差 + 归一化 + 前馈』复制 N 次叠起来（GPT 有十到上百层）。每层都让词的表示更抽象、更接近任务。","out":"深层的向量已经浓缩了整句话的语义"},{"in":"输出：预测下一个词","process":"最后一层接线性层 + softmax，把向量变成词典里每个词的概率，取概率最高的作为下一个词。","out":"生成一个词 → 拼回输入 → 继续预测下一个词"}]},{"type":"realworld","items":[{"name":"ChatGPT / GPT 系列","note":"Decoder-only Transformer：单纯地一层层预测下一个词，就长出了对话和推理能力。"},{"name":"Claude / Gemini","note":"同一架构的不同工程实现：同样的多头注意力 + 深层堆叠，在尺度与训练技巧上各有差异。"},{"name":"翻译与摘要模型（T5/BART）","note":"Encoder-Decoder 结构：编码器读懂全文，解码器再一句句生成译文或摘要。"},{"name":"代码补全（Codex 前身/Copilot）","note":"把代码当另一种语言喂给 Decoder-only Transformer，学会了补全、续写、改 bug。"}]},{"type":"compare","pairs":[{"a":"RNN","b":"Transformer","diff":"RNN 顺序串行、远处信息衰减、难并行；Transformer 全局直连、天然并行、能堆深。2017 后几乎完全取代 RNN。"},{"a":"Encoder-only（BERT）","b":"Decoder-only（GPT）","diff":"前者双向读全文、擅长理解（分类/检索）；后者只能从左往右、擅长生成（对话/写作/代码）。"},{"a":"单层注意力","b":"N 层堆叠的 Transformer","diff":"单层只做一次互相看；Transformer 把多次『互相看 + 精加工』叠起来，让表示一层比一层抽象。"},{"a":"Transformer","b":"Attention","diff":"Attention 是其中的一个子模块；Transformer 是包含注意力在内的一整套完整架构。很多人把两者画等号，其实 Attention ⊆ Transformer。"}]},{"type":"mistakes","items":["以为『Transformer = Attention』。Attention 只是其中一个子模块，完整架构还包括残差、归一化、前馈、位置编码。","以为 BERT 和 GPT 一样。BERT 双向理解、GPT 单向生成，职权完全不同。","以为层数越多一定越好。层越深效果提升有边际，还带来更大算力和训练难度。","把『位置编码』当可选项。没有它，『猫追狗』和『狗追猫』对模型来说完全一样——这可是天壤之别。","以为 ChatGPT 用的是完整 Encoder-Decoder。GPT 只用 Decoder-only，这是它和 T5 这类翻译模型的关键区别。"]},{"type":"deep","title":"深入一点：从直觉到架构细节","beginner":["位置编码就是给每个词加一个『第几个』的记号，否则『猫追狗』和『狗追猫』对模型来说字全一样。","残差连接简单说就是『进来和出去加一起』，像搭桥——让深层的梯度不会消失，模型才能堆数十上百层。","前馈网络 FFN 是给每个词单独换个角度想一遍，和注意力（词与词协作）分工不同、缺一不可。","GPT 其实只用了 Transformer 的一半：只有解码器那套（Decoder-only），用来不停地预测下一个词。"],"advanced":["核心是 Decoder：每个 token 只看自己和前面（因果掩码 causal mask），保证预测时不偷看未来。这是它和编码器的最大区别。","缩放点积注意力：Attention = softmax( (Q·Kᵀ) / √d )·V。除以 √d 防点积过大导致梯度消失 / softmax 饱和。","三种架构：Encoder-only（BERT：理解）、Decoder-only（GPT：生成）、Encoder-Decoder（T5：翻译/转换）。ChatGPT 系清一色 Decoder-only。","残差连接 + LayerNorm（常采用 Pre-LN 顺序：先归一化再进子层）是训练稳定性的关键工程细节，是它能堆到千亿参数的原因之一。","复杂度 O(n²)：上下文窗口越大成本越高——这直接决定了长上下文为什么贵、为什么要引入 RAG。",{"code":"# 概念示意：位置编码的经典公式（体会它想表达什么即可）\nimport math\n\ndef pos_encoding(pos, d_model=8):\n    vec = []\n    for i in range(d_model):\n        angle = pos / (10000 ** (2 * (i // 2) / d_model))\n        vec.append(round(math.sin(angle), 3) if i % 2 == 0 else round(math.cos(angle), 3))\n    return vec\n\nfor p in [0, 1, 2, 3]:\n    print(f\"第{p}个词的位置: {pos_encoding(p)}\")\n# 每个位置生成一组各不相同的位置向量 → 模型据此知道先后顺序","lang":"python"}]},{"type":"exercise","prompt":"如果完全不给模型位置编码，只给它 Attention，那么『猫追狗』和『狗追猫』这两句话，模型会怎么看待？","opts":["认为它们语义完全不同（追的方向相反）","认为它们几乎一样（词完全相同，注意力无差别混合）","认为它们字数不同","完全无法处理两个词以上的句子"],"a":1,"explain":"注意力是把所有词互相加权求和，本质记不得先后顺序。没有位置编码，模型会认为两句话『字都一样所以差不多』，分不清谁追谁。这正是位置编码存在的意义。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"type":"check","title":"结课检测：你真的理解 Transformer 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 Transformer 需要位置编码？","opts":["为了让向量维度变大","因为注意力本身不含位置信息，没有它『狗追猫』和『猫追狗』无法区分","为了加快计算","为了让训练更快收敛"],"a":1,"explain":"注意力把所有词互相加权、天然不记顺序；位置编码把『第几个』注入向量，模型才知道先后。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"q":"残差连接（Residual）的主要作用是？","opts":["增加参数数量","让信息能无损跨层传递，网络可以堆得很深且训练稳定","让模型更快生成","代替位置编码"],"a":1,"explain":"把输入与输出相加，像搭桥一样让信息直达深层，缓解梯度消失，是能堆几十上百层的关键。","jump":"sec5-step2","jumpLabel":"残差连接 + 归一化这一步"},{"q":"GPT 属于哪种结构？","opts":["Encoder-only","Decoder-only","Encoder-Decoder","既不是编码器也不是解码器"],"a":1,"explain":"GPT 只用解码器（带因果掩码、从左往右生成），反复预测下一个词。","jump":"sec9","jumpLabel":"深入节里 GPT=Decoder-only 那条"},{"q":"Attention 和 Transformer 的正确关系是？","opts":["它们是同一个东西","Transformer 是 Attention 的一个零件","Attention 是 Transformer 的一个子系统，Transformer 是完整架构","完全没有关系"],"a":2,"explain":"Attention ⊆ Transformer：Transformer 在 Attention 之外还包含残差、归一化、前馈、位置编码等。","jump":"sec8","jumpLabel":"『以为 Transformer=Attention』那条误区"},{"q":"为什么说 Transformer 比 RNN 快（并行）？","opts":["因为它跳过了很多词","因为它让所有词同时参与计算，不用一个字一个字排队","因为它更短","因为它的层更少"],"a":1,"explain":"RNN 必须按顺序串行处理每个词；Transformer 所有位置并行计算，谁跟谁相关靠注意力自己匹配。","jump":"sec7","jumpLabel":"对比区 RNN vs Transformer"}],"done":"你已经明白大模型的地基长什么样了。但这个『什么都会的模型』只记得训练时的知识——它不知道你公司的最新政策。下一课解决这个问题。","nextLesson":"l-rag"},{"type":"connection","known":["Attention：Q/K/V 加权求和，让词与词互相关注","词是向量，语义可算相似度"],"learned":["Transformer = 多头注意力 + 残差 + 归一化 + 前馈网络的 N 层堆叠","位置编码让模型感知顺序，否则猫追狗 = 狗追猫","GPT 是 Decoder-only，靠预测下一个词长出能力","O(n²) 复杂度是长上下文贵的根源，引出 RAG"],"next":"Transformer 有了，模型『什么都懂但只记得训练时的知识』。下一课我们解决这个关键问题：RAG——怎么让模型在回答前先到你的资料库查资料，从而答出它没学过的私有内容。"}]},"l00-ai-world":{"id":"l00-ai-world","title":"一张图看懂整个 AI 世界","subtitle":"在学任何一个概念之前，先拿到整张地图：你现在站在哪里，接下来要走到哪里。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"15-20 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl","ai-apps","ai-limits"],"prereqLessons":[],"nextLesson":"l01-ai-vs-ml-dl","sections":[{"type":"opening","question":"你每天听到的 ChatGPT、大语言模型（LLM）、Transformer、Agent、RAG……它们到底谁包含谁、谁建在谁之上？如果你现在只能用一句话回答「它们是什么关系」，你会怎么说？","guess":"很多人会脱口而出「都是一回事，就是 AI」。","next":"这节课不教任何公式，只画一张总地图。学完你不仅能说清这些词的关系，还能知道接下来 5 节旗舰课各自站在这张地图的哪个格子里。"},{"type":"why","before":"你在标题、文章、面试里反复遇到 Token、Attention、Transformer、RAG、Agent、Fine-tune……每个词单独看都懂一点，但凑在一起就乱。","problem":"初学者最大的障碍不是「不够努力」，而是没有地图：他不知道现在学的东西将来会连到哪里，于是学一个忘一个，越学越焦虑。","need":"所以第一节课我们不讲任何实现细节，只建立骨架：AI 世界分哪几层、每一层由什么构成、你将来要学的每一块长在哪个位置。地图在手里，后面的路才走得稳。"},{"type":"oneline","text":"AI（人工智能）是整片森林；机器学习是其中『会自己从数据里找规律』的那片林子；深度学习是最能长的那几棵大树；大语言模型（LLM）是最近最抢眼、能和你聊天的那一棵；而 RAG、Agent 这些，是围绕这棵树搭起来的『脚手架』——让树上的果子更好摘。"},{"type":"visual","kind":"ai-world-map","title":"AI 世界全景图","hint":"从最外层的 AI 一路收缩到 LLM，再向外展开 Vision / Speech / Agent / RAG 等应用方向。点击让你看明白的节点，就能往下一层走。"},{"type":"intuition","blocks":[{"k":"用俄罗斯套娃来想","t":"AI 是最大的套娃，机器学习是里面一层，深度学习再里面一层，LLM 是最小最精致的那层。每往里一层，都建立在外层之上——这叫『包含』，不是『并列』。"},{"k":"用搭积木来想","t":"只给你一个 LLM 你只能『聊天』。但当你往它外面搭『检索』（RAG）、『工具调用』（Agent）、『工作流编排』（Workflow）这些积木，你就从『会聊天』升级成『会办事』。产品形态 = 模型 + 一层层积木。"},{"k":"一句话记住主干","t":"AI ⊃ ML ⊃ DeepLearning ⊃ Foundation Model ⊃ LLM。这一个箭头链，就是整张地图的主干，也串起了你即将学的六节课。"}]},{"type":"how","intro":"把 AI 世界拆成「五层结构」与「五大应用方向」，你学完至少知道每块知识的归属，再也不会把它们混为一谈。","steps":[{"in":"第 0 层 · AI（人工智能）","process":"最上层总称：让机器表现出智能的一切技术，包括早期靠人写规则、搜索、专家系统。","out":"范围最大，是『目标』而不是某一门具体技术"},{"in":"第 1 层 · Machine Learning 机器学习","process":"不再靠人写死规则，而是让机器从数据里『自己找规律』，再拿规律去做预测。","out":"监督学习 / 无监督学习 / 强化学习 三大流派"},{"in":"第 2 层 · Deep Learning 深度学习","process":"用『多层神经网络』来自动提取特征，是机器学习的子集，能力更强：不用人手设计特征。","out":"CNN（图像）、RNN/Transformer（序列）、扩散模型（生成）等结构"},{"in":"第 3 层 · Foundation Model 基础模型","process":"在大规模数据上预训练好的『通用大脑』，可以微调或直接复用到很多不同任务。","out":"LLM（语言）、视觉基础模型、多模态基础模型"},{"in":"第 4 层 · LLM 大语言模型","process":"把『预测下一个词』当唯一训练目标，靠海量文本硬学出来的语言模型，意外获得了语言与世界的知识。","out":"ChatGPT、Claude、Gemini 背后的模型本体"},{"in":"围绕 LLM 的『脚手架』与应用架构","process":"光会聊天不够，为了让模型能办成事，在外面叠加外围技术。","out":"Prompt 提示 · RAG 检索增强 · Workflow 工作流 · Agent 智能体 · 多模态"}]},{"type":"realworld","items":[{"name":"ChatGPT","note":"「纯 LLM 对话产品」：你打字，它预测下一段话。它本身不做检索也不调工具，是最纯粹的一层。"},{"name":"Claude / Gemini","note":"同样是 LLM 驱动的对话产品，但在模型能力与对齐上做得不同，代表『同一个塔、不同的果』。"},{"name":"NotebookLM / 企业知识库问答","note":"「LLM + RAG」：你上传私有资料，系统先检索相关片段，再让模型基于这些片段回答，杜绝凭空编造。"},{"name":"Workflow 编排（如 Zapier AI / Coze 工作流）","note":"「LLM + 规则流程」：把『先做A、判断结果再做B』写成固定流水线，模型只负责其中某一环。"},{"name":"Codex / Claude Code","note":"「LLM + Agent 智能体」：不只是回答，还能自主决定『读文件→改代码→跑测试→看报错→再改』，直到把活干完。"},{"name":"Midjourney / Sora","note":"「不是 LLM 的另一棵树」：用扩散模型做图像/视频生成。提醒你 AI 世界不只有语言这一棵大树。"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是「目标——机器有智能」；机器学习是实现它的一种主流手段（用数据学出来）。早期用规则实现的人工智能，不属于机器学习，但仍然属于 AI。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是「从数据学习」；机器学习范围更大（含决策树、SVM 等传统算法），深度学习专指用多层神经网络，能自动提取特征，是机器学习的一个子集。"},{"a":"LLM","b":"Foundation Model","diff":"LLM 是专做语言的基础模型；Foundation Model 是更大的类，还包括视觉、多模态基础模型。LLM ⊂ 基础模型。"},{"a":"RAG","b":"Agent","diff":"RAG 是『给模型外接资料库』的检索增强；Agent 是『让模型自主决策与调用工具』的智能体。两者常配合：Agent 需要信息时用 RAG 检索。它们都不是模型本身，而是脚手架。"},{"a":"模型（Model）","b":"产品（Product）","diff":"模型是被训练出来的『大脑』；产品是把这个大脑装进界面、加上检索/记忆/工具后的完整应用。你用的是产品，不直接是模型。"}]},{"type":"mistakes","items":["把「AI、机器学习、深度学习、LLM」当同义词——它们是一层层包含关系，不是并列。","以为 ChatGPT = 整个 AI。ChatGPT 只是 LLM 的一颗果实；AI 世界还有视觉、语音、生成、机器人、Agent 等一大片。","以为 RAG 和 Agent 是「模型」。它们是在模型外面搭的脚手架/架构，本身没有『大脑』。","以为只有学完高等数学才能开始。第一门旗舰课（Embedding）就能带你把概念走通，数学按「够用」给，不是研究生讲义。","以为 Fine-tuning（微调）和 RAG 是一回事。前者改模型自身权重，后者不改模型、只改给它看的外部资料——它们解决不同问题。"]},{"type":"deep","title":"深入一点：把「领域 / 模型 / 技术 / 应用架构 / 产品形态」五顶帽子分清楚","beginner":["用「帽子」来记：同一个东西，问问题的角度不同，答案就不同。","「这属于哪个**领域**？」—— 问的是地图范围（AI、ML、DL 是领域/学科级）。","「这是个什么**模型**？」—— 问的是被训练出来的产物（LLM、扩散模型、视觉模型是模型级）。","「用了什么**技术/算法**？」—— 问的是怎么做（Attention、Transformer、RAG 检索是技术级）。","「这是什么**应用架构**？」—— 问的是怎么组合（RAG 架构、Agent 循环、Workflow 流水线是架构级）。","「最终做成什么**产品**？」—— 问的是用户能用的东西（ChatGPT、Codex、NotebookLM 是产品级）。"],"advanced":["用一条「从模型到产品」的抽象层次链来定位任何 AI 名词：","「AI 世界 = 领域层（AI⊃ML⊃DL）→ 模型层（Foundation Model→LLM/Diffusion/多模态）→ 技术层（Attention、位置编码、损失函数）→ 架构层（RAG、Agent、Workflow、多智能体协作）→ 产品层（ChatGPT、Claude Code）」。","判断法则：问「它能不能被『训练』出来」？能 → 模型层或更深；问「它是不是一个『零件/接法』」？能 → 技术层或架构层。训练产物是模型，接法是架构。","示例定位：Transformer 是技术层（一种网络结构）；GPT 系列是基于 Transformer 训练出来的模型（模型层）；把 GPT 接上检索= RAG 架构（架构层）；打包成网站= ChatGPT 产品（产品层）。","顺带一个工程事实：你平时说的「大模型」绝大多数指 LLM 或基础模型；而「智能体」「Agent」在业界常被定义为『模型 + 记忆 + 规划 + 工具调用』，是一个架构概念而非单个模型。"]},{"type":"exercise","prompt":"你现在打开了一款「企业知识库问答」App，上传公司政策文件后提了个问题，系统给出的回答里标注了「依据文件第 3 页」。你觉得它最可能是下面哪种组合？","opts":["只有 LLM，全靠模型自己编","LLM + RAG（先检索你的文件，再基于片段回答）","LLM + Agent（让模型自己去改代码）","纯扩散模型"],"a":1,"explain":"回答『依据你上传的文件』并带引用，正是 RAG 的典型特征：先检索相关片段，再让模型基于片段生成答案。","jump":"sec5-step5","jumpLabel":"围绕 LLM 的脚手架（RAG 检索）这一段"},{"type":"check","title":"结课检测：你真的懂这幅地图了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"下面哪条包含关系是正确的？","opts":["AI ⊃ LLM ⊃ Deep Learning ⊃ ML","AI ⊃ ML ⊃ Deep Learning ⊃ LLM","LLM ⊃ AI ⊃ ML ⊃ Deep","Deep Learning ⊃ ML ⊃ AI ⊃ LLM"],"a":1,"explain":"AI 包含机器学习，机器学习包含深度学习，LLM 是深度学习上长出的具体模型。","jump":"sec5-step0","jumpLabel":"五层结构第一步"},{"q":"ChatGPT 最准确地说是下面哪一个？","opts":["一个 Agent 智能体","一个纯 LLM 对话产品","一个 RAG 系统","一个视觉模型"],"a":1,"explain":"ChatGPT 的核心就是大语言模型：输入→预测下一段。RAG/Agent 是对它的增强，而不是它的本质。","jump":"sec5-step4","jumpLabel":"第 4 层 LLM 这一段"},{"q":"「NotebookLM 先查你上传的资料再回答」主要用到了哪项技术？","opts":["RAG 检索增强生成","纯预训练","扩散模型","只靠提示词"],"a":0,"explain":"针对私有资料，RAG 让模型先检索相关片段再回答，这正是 NotebookLM 类产品的核心。","jump":"sec5-step5","jumpLabel":"脚手架之 RAG 这一段"},{"q":"Codex「自己读代码、改代码、跑测试、看报错再重试」的能力，对应哪种架构？","opts":["RAG 检索增强","Agent 智能体循环","纯一次性生成","工作流固定流水线"],"a":1,"explain":"自主决策 + 调用工具 + 根据反馈循环，这正是 Agent 的核心：想→做→看→再想。","jump":"sec5-step5","jumpLabel":"脚手架之 Agent 这一段"},{"q":"「Midjourney 能生成图片」用到的模型，和 ChatGPT 的 LLM 是什么关系？","opts":["同一个模型","都是 LLM","Midjourney 用的是扩散模型，是 AI 世界里另一棵大树","Midjourney 不用 AI"],"a":2,"explain":"图像生成多靠扩散模型（Diffusion），与语言类的 LLM 是并列的不同模型，提醒你 AI 世界不止语言一棵树。","jump":"sec6","jumpLabel":"现实应用里的 Midjourney / Sora"}],"done":"现在你手里有整张地图了。接下来我们要下到模型的正下方——先搞清楚：电脑到底怎么把一句话变成它算得动的『数字』。","nextLesson":"l-embedding"},{"type":"connection","known":["（这是第一节课，还没有前置知识）"],"learned":["AI → ML → DL → Foundation Model → LLM 的主干链条（包含关系）","领域 / 模型 / 技术 / 应用架构 / 产品形态 五顶帽子怎么分","RAG、Agent、Workflow 是围绕 LLM 的脚手架，不是模型","ChatGPT、Claude（LLM产品）、NotebookLM（RAG）、Coze（工作流）、Codex（Agent）、Midjourney（扩散）各代表一类"],"next":"下一课我们钻到模型正下方：Embedding——电脑怎么把『一句话』变成『一串数字』。这是理解 LLM 的第一块砖，也是 RAG、搜索、推荐的地基。"}]},"l01-ai-vs-ml-dl":{"id":"l01-ai-vs-ml-dl","title":"AI / Machine Learning / Deep Learning 到底什么关系","subtitle":"三个天天混着用的词，其实是三层包含关系。把它们理清，你才不会再被『这不是深度学习吗』『这算 AI 吗』这类问题卡住。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl"],"prereqLessons":["l00-ai-world"],"nextLesson":"pl-train-infer","sections":[{"type":"opening","question":"面试、文章、和同行聊天里，你几乎天天听到『AI』『机器学习』『深度学习』这三个词。它们到底是同义词，还是完全不同的东西？下面的说法，哪句最接近事实？","guess":"很多人觉得它们是同一件事的不同叫法，可以随便混用。","next":"上一课你拿到了整张 AI 世界地图。这一课我们只解决一个词根问题：AI、机器学习（ML）、深度学习（DL）谁包含谁。理清这层包含关系后，后面讲到神经网络、大模型时，你就知道它们各自站在哪一层。"},{"type":"why","before":"你读了文章，看到『用机器学习做了个推荐』，又看到『深度学习模型碾压传统算法』，还有『人工智能正在改变世界』。三个词来回出现，你分不清它们是不是一回事。","problem":"如果不理清，你会把它们当成可互换的词。结果就是：该用『AI 这个概念』时却拿『深度学习』去套，理解错位，越学越混乱。更关键的是，它影响了你的地图感——你不知道每一个具体技术在大结构里的归属。","need":"所以我们要把『包含关系』这条线彻底拉直：AI 是最外层的大概念，机器学习是实现 AI 的主流手段，深度学习又是机器学习里最强的一个分支。记住这一个箭头链，比背一百个术语都有用。"},{"type":"oneline","text":"AI（人工智能）是整片森林；机器学习（ML）是森林里『让程序从数据中自己找规律』这一派；深度学习（DL）是这一派里靠『多层神经网络』自动提取特征、效果最强的一支；而大语言模型（LLM）是深度学习在语言上结出的果子。"},{"type":"intuition","blocks":[{"k":"用俄罗斯套娃想","t":"AI 是最外面的大套娃，机器学习是里面一层，深度学习再里面一层。每一个内层都建立在外层之上。『它是 AI 吗？』——所有机器学习、深度学习都属于 AI；但『它是机器学习吗？』——只有 AI 的一部分才是。"},{"k":"用交通工具想","t":"AI＝『交通工具』这个大分类；机器学习＝其中『能自己开的车』；深度学习＝车里面『最豪华、自动驾驶能力最强的那批』。你要去的地方（目标）叫 AI，但真正驱动现在的靠的是深度学习这辆快车。"},{"k":"一句话记住","t":"AI ⊃ ML ⊃ DL。哪个词越大，哪一个就越『含』后面的。说『大模型是深度学习』正确，说『深度学习就是 AI』则太窄。"}]},{"type":"how","intro":"把三层关系拆开看：每一层『是什么、靠什么实现、典型代表是谁』。","steps":[{"in":"第 0 层 · AI 人工智能（最外圈）","process":"让机器表现出智能的一切技术。范围最广，既包括学出来的，也包括早期靠人写规则、专家系统、搜索的『传统 AI』。","out":"AI 是一个『目标 / 领域』，不是某一门固定技术"},{"in":"第 1 层 · 机器学习 ML","process":"AI 的一条主流路径：不再由人写死规则，而是给程序大量数据，让它自己找出规律，再拿规律预测没见过的新数据。","out":"监督学习 / 无监督学习 / 强化学习 三大流派"},{"in":"第 2 层 · 深度学习 DL","process":"机器学习里靠『多层神经网络』的那一支。区别在于：它无需人手设计特征，网络自己逐层提取。数据、算力上去后，效果远超传统 ML。","out":"CNN（图像）、RNN、Transformer、扩散模型等现代结构"},{"in":"果实 · 大语言模型 LLM","process":"把深度学习用在语言上，用『预测下一个词』的目标在海量文字上训练出来的模型。它是当下 AI 浪潮最亮眼的具体成果。","out":"ChatGPT、Claude、Gemini 背后的模型本体"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是目标——机器有智能；ML 是达成目标的主流手段——从数据里学规律。早期用规则实现的人工智能属于 AI、但不属于 ML。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是『从数据学习』；ML 范围更大（含决策树、SVM 等传统算法），DL 专指用多层神经网络，能自动提取特征，是 ML 的子集，也是当下主力。"},{"a":"DL","b":"LLM","diff":"DL 是方法（多层神经网络）；LLM 是用 DL 专门处理语言、以预测下一个词为目标的产物。LLM 是 DL 在语言上的具体应用果实。"},{"a":"传统规则 AI","b":"机器学习","diff":"传统规则 AI 是人手动写 if-else 规则，机器不会自己学；ML 让机器从数据里学规则。前者『别人给孩子吃』，后者『教孩子自己找吃的』。"}]},{"type":"mistakes","items":["把三个词当同义词——它们是包含关系：AI ⊃ ML ⊃ DL。","以为『只要用了 AI 就是深度学习』——很多产品底层还是传统机器学习（决策树、统计方法）。","以为『深度学习之外的东西都不是 AI』——AI 的范围比 DL 大得多。","把『大语言模型』直接等同于『全面工智能』——LLM 只是 AI 世界一小棵树上结的果。","纠结『这到底算不算 AI』这种分类洁癖——关键是理解它在哪一层、解决什么问题，而不是给它贴哪个标签。"]},{"type":"deep","title":"深入一点：为什么近十年忽然『深度学习』最火","beginner":["不是说传统机器学习不好，而是深度学习在『大规模数据 + 强大 GPU』的条件下，能力曲线突然反超。","三点原因：①数据足够多，神经网络学得动；②GPU 让多层网络算得动（训练从几周缩到几小时）；③多层网络能自动学特征，不用人手工设计。","一句话：深度学习强的不是『智能』，是『在足够数据下自动找到规律的能力』。"],"advanced":["技术脉络：2006 年深度信念网络证明深层训练可行 → 2012 年 AlexNet 用 CNN 赢下 ImageNet，深度学习在视觉上引爆 → 2017 年 Transformer 论文出现，注意力机制取代循环结构，为语言大模型铺路 → 2022 年 ChatGPT 把『预测下一个词』放大到规模对话，大众才真正感知到。","一个判断技巧：当文章说『神经网络』『层数』『激活函数』『反向传播』时，多半在讲 DL；说『特征工程』『决策树』『SVM』时，多半是传统 ML。","从 DL 到 LLM 的桥梁就是『词元 + 注意力』：把语言切碎成 token，再用自注意力建模词与词的关系。这将在后文《Tokenization》《Attention》《Transformer》三课展开。"]},{"type":"exercise","prompt":"一位朋友说：『我帮公司做了个深度学习项目，所以我在做人工智能。』这句话的问题在哪？","opts":["完全正确，深度学习就是 AI 的全部","只对一部分：深度学习确实是 AI，但不能反过来说『AI = 深度学习』，AI 的范围大得多","完全错误，深度学习不算 AI","深度学习是机器学习之外的技术，和 AI 无关"],"a":1,"explain":"深度学习是 AI 的子集（AI ⊃ ML ⊃ DL），所以『做深度学习就是在做 AI』正确；但把它当成 AI 的全部就错了，因为 AI 还包括传统 ML、规则系统等许多内容。","jump":"sec5-step0","jumpLabel":"第 0 层 AI 这一段"},{"type":"check","title":"结课检测：三层包含关系你拉直了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"下面哪条包含关系是正确的？","opts":["AI ⊃ ML ⊃ DL","ML ⊃ AI ⊃ DL","DL ⊃ ML ⊃ AI","AI ⊃ DL ⊃ ML"],"a":0,"explain":"AI 是最外层目标，机器学习是其内一层主流手段，深度学习又是机器学习里最强的一个分支。","jump":"sec5-step0","jumpLabel":"三层关系这一段"},{"q":"『决策树 / SVM』这类经典算法，通常归属于哪一层？","opts":["深度学习 DL","传统机器学习 ML（但不一定是 DL）","纯规则 AI（非学习）","大语言模型 LLM"],"a":1,"explain":"决策树、SVM 属于机器学习，但它们不靠多层神经网络，所以不算深度学习，也称不上 DL。","jump":"sec5-step1","jumpLabel":"机器学习这一层"},{"q":"『多层神经网络 + 自动提取特征』，最准确对应的概念是？","opts":["传统规则 AI","深度学习 DL","数据库","网络通信"],"a":1,"explain":"利用多层神经网络、无需人工设计特征自动学习，正是深度学习区别于传统 ML 的核心。","jump":"sec5-step2","jumpLabel":"深度学习这一层"},{"q":"大语言模型（LLM）与深度学习的关系是？","opts":["它们是同一件事的两个名字","LLM 是深度学习在语言上结出的具体果实","LLM 与深度学习毫无关系","LLM 属于传统机器学习"],"a":1,"explain":"LLM 用深度学习的方法专门处理语言，以『预测下一个词』为目标训练出来，是 DL 在语言上的具体应用。","jump":"sec5-step3","jumpLabel":"LLM 这一层"}],"done":"现在 AI、ML、DL、LLM 四者的包含关系你彻底拉直了。可这些高大上的模型到底怎么『学』出来的？下一课我们就回答最根本的一问：训练（Training）和使用（Inference）到底有什么区别。","nextLesson":"pl-train-infer"},{"type":"connection","known":["AI 是包含 ML、DL 的最外层大概念（来自上一课《一张图看懂整个 AI 世界》的地图骨架）"],"learned":["AI ⊃ ML ⊃ DL ⊃ LLM 的清晰包含链","三者的定义、实现手段与典型代表","为什么深度学习在数据与算力充足时成为主力","LLM 是深度学习在语言上的果实"],"next":"下一步我们回答『学习』这件事本身：模型『训练』时和『使用』时，到底发生了什么、有什么本质区别。这是理解一切 AI 应用的前提。","links":[{"href":"#/lesson/l00-ai-world","text":"回看《一张图看懂整个 AI 世界》"},{"href":"#/lesson/l08-neural-network","text":"提前了解《神经网络》一课"}]}]},"l05-gradient-descent":{"id":"l05-gradient-descent","title":"损失函数与梯度下降：模型怎么自己变聪明","subtitle":"训练的核心不是『照抄答案』，而是给错误『打分』，然后沿着『下山最快』的方向一步步调整参数。看懂这一步，你就真懂了 AI 的『学习』。","category":"c03-ml","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["loss","gradient","gradient-descent"],"prereqLessons":["pl-data"],"nextLesson":"l08-neural-network","sections":[{"type":"opening","question":"上一课我们说训练就是『反复调整参数』。可模型该往哪个方向调、调多少？它怎么知道自己『猜错了』？这里有一个非常优雅的核心机制——损失函数 + 梯度下降。","guess":"有人以为训练就是不断『枚举试错』，或模型直接记住正确答案。","next":"这一课我们讲训练最核心的两个概念：损失函数（给错误打分）和梯度下降（沿下山最快的路调整参数）。这是所有深度学习『自带学习』的根本。"},{"type":"why","before":"你想真正理解 AI 怎么『学会』的（而不是只会背结论），于是查『训练』『反向传播』，却看到一堆数学公式，被梯度、导数吓退。","problem":"不理解损失与梯度下降，你就只能把训练当『黑盒』——不知道模型为什么学会、为什么有时候学不会、为什么训练会发散或过拟合。后续看一切『调参』话题都会费劲。","need":"我们把核心讲得足够直观：损失＝错得有多离谱的比分；梯度＝每个旋钮往哪个方向拧能让误差下降最快。有了这两把钥匙，训练不再是黑盒。"},{"type":"oneline","text":"损失函数（Loss）= 给模型当前『错得多离谱』打的一个分数，越小越好；梯度下降（Gradient Descent）= 算出每个参数要让误差下降，应该往哪个方向拧、拧多少，然后沿『下山最快』的方向反复更新，直到误差降不下去。"},{"type":"intuition","blocks":[{"k":"用下山来想","t":"想象你被蒙着眼站在一座山上，目标是最低点（误差最小）。你每走一步就摸摸脚下的坡度（梯度：哪里更陡地往下）。你就朝最陡的下坡方向迈一小步，反复走，就一步步接近山谷最低点。这就是梯度下降。"},{"k":"用射箭来想","t":"损失函数＝你射偏的距离（离靶心多远）。梯度＝『往东偏了，该往西调一点』的修正提示。每一轮你根据偏差方向和大小校正弓，越射越准。"},{"k":"一句话记住","t":"损失＝错得有多远；梯度＝该往哪调、调多少。训练＝沿着『误差下降最快』的方向一次次微调参数，走出一座‘误差之山’。"}]},{"type":"how","intro":"把一次训练迭代（一步学习）拆成四步。","steps":[{"in":"① 前向预测：模型猜一次","process":"喂一批数据，模型按当前参数算出一批预测结果（如：这张图是猫的概率、下一个词是哪个）。","out":"得到模型的『猜测』输出"},{"in":"② 计算损失：给错误打分","process":"拿猜测和真实答案对比，用一个损失函数算出数值：差得多分数高，差得少分数低。这就是 Loss。","out":"一个代表错得多离谱的数值（Loss）"},{"in":"③ 反向计算梯度：找下降方向","process":"用微分/反向传播算出：每个参数向哪个方向微调会让 Loss 变小、大概变小多少。这就是梯度（下山方向）。","out":"每个参数对应的『修正方向 + 幅度』"},{"in":"④ 更新参数：沿梯度走一小步","process":"按学习率（步长）把每个参数往梯度方向调一点。重复 ①②③④ 成千上万次，Loss 逐渐下降。","out":"一轮一轮的微调后，误差越来越小，模型变聪明"}]},{"type":"realworld","items":[{"name":"学习率（Learning Rate）","note":"决定每步走多大。太大容易在山谷两边来回震荡甚至发散；太小走到山谷要很久。调学习率是训练头号工程问题。"},{"name":"为什么训练会『过拟合』","note":"下山下过头，模型把训练数据的噪声也背下来，对没见过的数据反而变差。这需要正则、早停、更多数据来约束。"},{"name":"批量大小（Batch）","note":"一次用多少样本算梯度。太小震荡大、太大太慢。是训练的重要超参数。"},{"name":"为什么有的模型『训练发散』（Loss 变 NaN）","note":"梯度爆炸或学习率过大，参数一步跳得太远，误差爆炸。工程上要加梯度裁剪、合理初始化。"}]},{"type":"compare","pairs":[{"a":"损失函数 Loss","b":"梯度 Gradient","diff":"Loss 是『错得多远』的分数（一个数）；梯度是『该往哪调、调多少』的方向信息。先有 Loss，才有 Gradient。"},{"a":"梯度下降","b":"随机梯度下降 SGD","diff":"梯度下降每步用全部数据算梯度（准但慢）；SGD 每次只用一小批数据算梯度（快但有噪声，实践中更常用）。"},{"a":"学习率大","b":"学习率小","diff":"大步长收敛快但易震荡/发散；小步长稳但慢。要平衡。"},{"a":"训练 Loss","b":"验证 Loss","diff":"训练 Loss 是模型背题目的程度；验证 Loss 是它在没见过的题上的表现。后者才是真正关心的泛化能力。"}]},{"type":"mistakes","items":["以为训练是『背答案』——不，是学规律后用梯度一点点靠近最优参数。","以为『Loss 越低越好到越低就越强』——训练 Loss 降得太低常意味着过拟合，真正看验证 Loss。","以为梯度下降只有一条最优路径——它是启发式最优化，可能卡在局部极小值，且对超参数敏感。","把『梯度』和『参数值』混为一谈——梯度是方向信息，参数才是被更新的值。","以为学习率越大越快——过大会发散，这不是勇气，是翻车。"]},{"type":"deep","title":"深入一点：数学直觉（给愿意往下钻的你）","beginner":["梯度就是『误差对每个参数的偏导数』：把参数稍微动一点点，看 Loss 变多少。","梯度方向是 Loss 上升最快的方向，所以沿它的反方向走，就是下降最快的方向。","更新公式一眼看懂：新参数 = 旧参数 − 学习率 × 梯度。"],"advanced":["优化目标是最小化 L(θ)。更新：θ ← θ − η∇L(θ)。η 是学习率，∇L 是梯度。","深度学习用的多是 Adam 等自适应优化器：为每个参数自动调整学习率，能加速收敛、更稳。","对 LLM，预训练用海量数据做较长时间的大规模梯度下降；微调用小数据小学习率。现代还加入 LoRA 等参数高效方式只更新低秩子空间。","需要警惕的工程陷阱：梯度爆炸/消失（影响深层网络）、学习率 warmup、loss 尺度不一等。"]},{"type":"exercise","prompt":"训练中你看到 Loss 一会儿 4.8、一会儿 4.2、一会儿又 5.1，总体没怎么降。最可能是哪类问题？","opts":["模型已经过拟合了","学习率过大或数据太吵，导致震荡、收敛困难","数据量太多","显卡坏了"],"a":1,"explain":"Loss 来回震荡不下滑，常是学习率过大、批量太小导致的噪声，或需要调整超参数让训练稳定下来。","jump":"sec5-step3","jumpLabel":"更新参数这一步"},{"type":"check","title":"结课检测：损失与梯度下降你懂了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"损失函数（Loss）的作用是？","opts":["给模型的错误打一个分，越小越好","让显卡更热","控制网页颜色","增加参数量"],"a":0,"explain":"Loss 衡量模型预测与真实答案的差距，是训练的‘成绩单’，目标是把它降到尽可能低。","jump":"sec5-step1","jumpLabel":"计算损失这一步"},{"q":"梯度（Gradient）告诉模型什么？","opts":["正确答案本身","每个参数该往哪个方向调能让误差下降","模型的名字","数据的来源"],"a":1,"explain":"梯度是误差对参数的偏导方向信息，模型沿其反方向（下降最快）调整参数。","jump":"sec5-step2","jumpLabel":"反向计算梯度这一步"},{"q":"下面的参数更新思路，哪项正确？","opts":["新参数 = 旧参数 + 学习率 × 梯度（反了）","新参数 = 旧参数 − 学习率 × 梯度","新参数和旧参数无关","只在推理时改参数"],"a":1,"explain":"沿梯度反方向（下降方向）走，所以是减去学习率乘梯度。训练改参数、推理只读。","jump":"sec5-step3","jumpLabel":"更新参数这一步"},{"q":"学习率设得过大，最常见的后果是？","opts":["训练更快且更好","参数一步跳太远，Loss 震荡甚至发散","模型变成大模型","不需要数据了"],"a":1,"explain":"步长过大容易在最优附近来回跳过，甚至梯度爆炸导致 Loss 发散。","jump":"sec6","jumpLabel":"学习率这个现实话题"}],"done":"你知道了训练是怎么『一步步下山』的：给错误打分，沿梯度往误差下降的方向拧参数。下一课我们把镜头拉回模型本身——神经网络到底长什么样、神经元是怎么组成可学习网络的。","nextLesson":"l08-neural-network"},{"type":"connection","known":["数据、模型、参数三件套（上一课）","训练＝反复调整参数"],"learned":["损失函数＝给错误打分，目标是降低","梯度＝哪个方向能最快降低误差","梯度下降＝沿下山最快方向反复微调参数","学习率、过拟合、训练/验证 Loss 这些关键概念"],"next":"梯度下降要在『模型』上发挥作用，可这个模型到底长什么样？下一课《神经网络》：神经元、层、激活函数，理解模型的躯体。","links":[{"href":"#/lesson/pl-data","text":"复习《数据、模型与参数》"},{"href":"#/lesson/l08-neural-network","text":"进入《神经网络》"}]}]},"l08-neural-network":{"id":"l08-neural-network","title":"神经网络：神经元如何组成可学习的网络","subtitle":"深度学习的大脑＝一层层神经元。看懂『神经元怎么算、层怎么堆、信息怎么流动』，你就拥有了理解几乎所有现代模型的基础底盘。","category":"c04-dl","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["neural-network","neuron","layer","activation"],"prereqLessons":["l05-gradient-descent"],"nextLesson":"l09-backprop","sections":[{"type":"opening","question":"『神经网络』你听了无数遍，可它到底长什么样？是不是真和大脑一样？为什么『一堆神经元连起来』就能写诗、识图、跟你聊天？","guess":"有人以为神经网络真的模仿大脑生物结构，或以为它是魔法般‘突然会了’。","next":"这一课我们拆开神经网络的正脸：一个神经元在算什么、一层层怎么叠加、信息怎么从输入流到输出。你会惊讶它其实是由‘乘加 + 激活’这种超级简单的运算堆出来的。"},{"type":"why","before":"你想真正理解深度学习，而不是只会说‘神经网络很厉害’。可一打开网上资料就全是神经元、权重、激活函数、层，不知道它们是怎么组成一个能干活的整体。","problem":"不搞懂神经网络的基本结构，后续看 Attention、Transformer 时会完全跟不上——因为那些都是在这个底盘上加的新花样。","need":"我们先用最直观的方式把神经网络‘长什么样’讲清楚：神经元怎么算、为什么需要非线性（激活）、层越多能学到越抽象的东西。地基打牢，后面全是加分项。"},{"type":"oneline","text":"神经网络＝把大量『简单神经元』分层堆叠：每个神经元把上一层传来的数字加权求和，再过一道非线性激活函数输出；一层接一层，把原始输入逐渐加工成可用的结果。学习就是在训练中不断调这些权重（配合上一课的梯度下降）。"},{"type":"intuition","blocks":[{"k":"用力工流水线来想","t":"神经网络像一条多工序的工厂流水线：原料（像素/文字）进第一道工序，每道工序负责提取一个层面的特征，成品在最后一道工序出来。层数越多，能提取的特征越高维越抽象——从‘一小片边’到‘一只眼睛’到‘一张脸’。"},{"k":"用算盘/计算器来想","t":"每个神经元本质就是一个‘小计算器’：把几个输入各自乘一个权重再加起来，然后决定要不要‘被激活’。网络就是成千上万个小计算器排队协作。"},{"k":"一句话记住","t":"神经元＝乘加 + 激活；层＝一批神经元；深度＝有多少层。层数越多，学到的东西越抽象；而训练负责把这些‘乘加里的权重’调好。"}]},{"type":"how","intro":"从单个神经元讲到整张网络，四步走。","steps":[{"in":"① 单个神经元：一次性小计算","process":"一个神经元接收上一层传来的多个数字，每个数字乘一个权重，求和，再加一个偏置，得到一个‘原始得分’。","out":"一个加权求和后的数字（还没加工完）"},{"in":"② 激活函数：引入非线性","process":"把原始得分过一道激活函数（如 ReLU：负数归零、正数保留）。没有这步，再多层也等价于一层，学不了复杂东西。非线性是关键。","out":"一个‘激活后’的输出值，传给下一层"},{"in":"③ 分层堆叠：从底层特征到高层语义","process":"把很多神经元放一层，再叠很多层。第一层学边缘/局部，中间层学部件/模式，高层学整体语义（对着图那就是‘脸’‘猫’）。","out":"一个能逐层提取特征、层层抽象的网络"},{"in":"④ 输出层 → 预测","process":"最后一层把中间表示转换成最终答案：分类（各类概率）、回归（一个数）、或语言模型的‘下一个词的概率分布’。","out":"可解释成‘预测/概率’的输出"}]},{"type":"realworld","items":[{"name":"全连接层（MLP）","note":"每一层的每个神经元都和上一层所有神经元相连，是最基础的结构。Transformer 里的前馈网络就是一种 MLP。"},{"name":"CNN（卷积网络）","note":"用小的卷积核在图像上滑动提取局部特征，擅长图像。AlexNet 靠它在 2012 年引爆深度学习。"},{"name":"RNN / LSTM（循环网络）","note":"为序列而生，靠循环传递上个时间步的状态。后来在处理长文本上被 Transformer 取代。"},{"name":"Transformer","note":"不用循环，全靠注意力机制并行处理序列，是现在所有大语言模型的地基。后面专门一课讲。"}]},{"type":"compare","pairs":[{"a":"浅层网络","b":"深层网络","diff":"浅层只能学到简单特征与关系；深层能逐步抽象，能力更强，但更难训练、更容易梯度消失，需要残差连接等设计。"},{"a":"线性（无激活）","b":"非线性（有激活）","diff":"没有非线性，再多层叠加仍是线性变换，学不了复杂函数。激活函数带来非线性表达能力。"},{"a":"卷积 CNN","b":"全连接 FC","diff":"CNN 用局部连接+卷积核，参数少、适合图像；FC 全连接，参数多，通用。"},{"a":"RNN","b":"Transformer","diff":"RNN 串行逐步处理，难并行、长距离记忆弱；Transformer 一次看全部、可并行、长距离强，是现代主流。"}]},{"type":"mistakes","items":["以为神经网络真和大脑生物神经元一样——它只是受启发，用的是数学上的‘人工神经元’，比大脑简单得多。","以为层越多一定越好——过深反而不易训练、易过拟合，需要配套技巧（归一化、残差、正则）。","以为激活函数可有可无——少了非线性，层数再多也等价于一层线性，模型能力骤降。","把神经网络的‘参数’和‘权重’搞混——权重就是参数的一种，它们才是训练要调的。","以为网络是‘背下所有答案’——它学的是从输入映射到输出的规律（通过调权重）。"]},{"type":"deep","title":"深入一点：深度为什么有用、又为什么难训练","beginner":["深度带来‘分层表示’：浅层学局部细节，深层学整体概念。这种层级抽象是深度网络能力强的关键。","但也带来训练难点：层太深，梯度在回传时容易‘消失’（乘很多小值趋近 0），最底层学不到东西。","于是有了残差连接（把上一层的值直接跳到后面）等设计来缓解。"],"advanced":["神经网络的万能近似：只要神经元够多、激活非线性，理论上能逼近任意连续函数。","深度网络优于浅层网络在于‘表示效率’：同样的表达能力，深层所需参数往往更少、泛化更好。","现代大模型（Transformer）本质也是神经网络：多头注意力 + 前馈层，只是给它堆了海量参数与数据。","反向传播（下一课）就是在这样的网络上高效算出每一个权重的梯度，让梯度下降在大规模场景下可行。"]},{"type":"exercise","prompt":"一个由多层线性变换（无激活函数）堆叠成的‘网络’，实际效果等价于？","opts":["一个强大的深层网络","一个单层线性模型（因为没有非线性，层数等于白叠）","一定会比深层网络强","无法训练"],"a":1,"explain":"没有非线性激活，多层线性变换可以合并成一个线性变换，等于只有一个线性层，能力有限。非线性是关键。","jump":"sec5-step1","jumpLabel":"激活函数这一步"},{"type":"check","title":"结课检测：神经网络的地基你打牢了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"单个神经元最基本的运算组合是？","opts":["加权求和 + 激活函数","排序 + 去重","加密 + 解密","复制 + 粘贴"],"a":0,"explain":"神经元把输入加权求和得到原始得分，再经激活函数引入非线性。这是最基本的组成单位。","jump":"sec5-step0","jumpLabel":"单个神经元这一步"},{"q":"为什么神经网络需要非线性的激活函数？","opts":["为了更美观","没有非线性，多层也等价于一层线性变换，学不了复杂规律","为了增加参数数量","因为 CPU 喜欢"],"a":1,"explain":"非线性让网络能逼近复杂函数；没有它，多层网络被压缩成一层，表达能力大跌。","jump":"sec5-step1","jumpLabel":"激活函数这一步"},{"q":"『深度网络善于提取越来越抽象的特征』，这个抽象层次受益于？","opts":["只有一层","层层堆叠、逐层抽象","加越多噪声越好","不训练"],"a":1,"explain":"多层结构让浅层学细节、深层学整体语义，形成层级抽象，是深度的价值。","jump":"sec5-step2","jumpLabel":"分层堆叠这一步"},{"q":"神经网络训练时要调的主要是？","opts":["每层的神经元数量结构","连接上的权重（参数）","用户的界面","网络的波长"],"a":1,"explain":"结构（层数、神经元数）通常在训练前定好；训练反复调整的是连接权重这些参数（配合梯度下降）。","jump":"sec6","jumpLabel":"全连接层这个话题"}],"done":"你认识了神经网络的躯体：神经元加权求和 + 激活，分层堆叠提取特征。那训练时，误差到底是怎么‘传回去’改每一层权重的？下一课《反向传播》揭晓。","nextLesson":"l09-backprop"},{"type":"connection","known":["梯度下降＝沿误差下降方向调整参数（上一课）"],"learned":["神经元＝加权求和 + 激活函数","层、深度、非线性为什么关键","CNN / RNN / Transformer 各自擅长的场景","网络通过对大量权重调参来学习"],"next":"误差要传回每一层去改权重的那个高效方法，就是下一课的核心。准备好了吗？《反向传播：误差如何传回去改参数》。","links":[{"href":"#/lesson/l05-gradient-descent","text":"复习《损失函数与梯度下降》"},{"href":"#/lesson/l09-backprop","text":"进入《反向传播》"}]}]},"l09-backprop":{"id":"l09-backprop","title":"反向传播：误差如何传回去改参数","subtitle":"深度网络有几亿参数，梯度下降却要算出每一个该往哪调。反向传播就是那个能在一次计算里，高效把所有梯度算出来的巧妙方法。","category":"c04-dl","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["backpropagation","gradient","chain-rule"],"prereqLessons":["l08-neural-network","l05-gradient-descent"],"nextLesson":"l11-tokenization","sections":[{"type":"opening","question":"一个 70B 参数的大模型，训练时要为每个参数算出‘该往哪调、调多少’。如果一个个算，几辈子都算不完。可训练只花几个星期就完成了——靠的是反向传播这个精巧机制。它是怎么做到的？","guess":"有人以为训练是‘挨个试’每个参数，或以为靠的是超级电脑大力出奇迹。","next":"这一课讲反向传播：误差如何从输出端‘倒着传回去’，用一条链式法则，一次性算出所有参数该调整的方向与幅度。看懂它，训练不再神秘。"},{"type":"why","before":"你接受了‘训练要调几亿个参数’这个设定，但马上困惑：神经网络的每层都互相影响，怎么知道到底是哪一层、哪个权重该为错误负责？","problem":"如果不理解反向传播，你会觉得大规模训练是魔法；也无法理解为什么深度学习速度这么快、为什么需要特殊硬件（GPU）、为什么梯度会‘消失’。","need":"反向传播把‘如何高效地给每个参数下发修正指令’这件事讲透了：从输出端倒推，每层把自己应负的责任传给上一层。这是理解训练提速、梯度消失、以及对 Transformer 训练的一切认知的钥匙。"},{"type":"oneline","text":"反向传播 = 先从输出端算出‘错得有多远’，再沿着计算的反方向，用链式法则把这份‘责任’逐层传回每一层的每个权重，一次算出所有梯度，让梯度下降可以批量更新整个网络。"},{"type":"intuition","blocks":[{"k":"用传话游戏来想","t":"信息正向往前传（输入→输出），误差反向往回传（输出→输入）。就像把你每一句话造成的最终偏差，逆着报给每一位讲话的人，告诉他该改多少。"},{"k":"用差评溯源来想","t":"一道菜难吃（大 Loss），要找到是哪个厨师、哪道工序的问题。你从成品倒着往回查：出锅太咸可能是调味这步，而调味又是前面采购/配比叠加的结果。反向传播就是这样从输出端把责任一路分派回每一层。"},{"k":"一句话记住","t":"正向传信息，反向传误差。反向传播用链式法则在一次回传里同时算出上亿个梯度，让深度学习训练成为可能。"}]},{"type":"how","intro":"把反向传播拆成一次‘四步回传’。","steps":[{"in":"① 正向算出误差","process":"网络前向算一遍，得到输出，与真实答案比较，得到 Loss（上一课已讲）。","out":"一个总误差数值"},{"in":"② 从最后一层往回，算‘谁的责任’","process":"从输出层开始，问：每个神经元的输出变化一点，Loss 变化多少？这就是梯度。","out":"最外层每个参数的梯度"},{"in":"③ 用链式法则逐层回传","process":"靠链式法则，把上一层的梯度乘上本层的局部导数，就得到更前一层的梯度。一路从输出传到输入，每一层都拿到自己的‘修正指令’。","out":"每一层每个权重都得到一个梯度"},{"in":"④ 汇总更新，再来一轮","process":"把所有层的梯度汇总，沿梯度反方向更新全部参数（梯度下降）。然后对下一批数据再来一轮。","out":"一次更新完成，误差整体下降一点"}]},{"type":"realworld","items":[{"name":"为什么需要 GPU","note":"反向传播涉及大量矩阵乘法和链式求导，GPU 能上千核并行，把训练从‘不可行’变成‘几周完成’。这是深度学习兴起的关键硬件。"},{"name":"梯度消失 / 梯度爆炸","note":"层太深时，梯度一层层相乘可能越来越小（消失）或爆炸。反向传播因此难以训练极深网络，催生了残差连接、归一化等设计。"},{"name":"自动微分框架（PyTorch / TensorFlow）","note":"你把网络搭好、写个 Loss，框架会自动帮你做反向传播求梯度。平时训练根本不手写链式法则。"},{"name":"大模型训练同理","note":"Transformer、GPT 的训练底层仍然是反向传播 + 梯度下降，规模放大而已。理解它，你就懂整个深度学习训练的统一范式。"}]},{"type":"compare","pairs":[{"a":"前向传播","b":"反向传播","diff":"前向：输入 → 输出，用于给出预测；反向：输出误差 → 层层回传梯度，用于更新参数。推理只用前向，训练两者都用。"},{"a":"数值求导（逐个试）","b":"反向传播（链式一次算完）","diff":"数值求导每个参数试一下、极慢；反向传播靠链式法则一次回传算完全部梯度，快几个量级。"},{"a":"局部梯度","b":"全局梯度","diff":"局部是单步的输出对输入的变化率；全局经链式法则把路径上所有局部梯度连起来，才得到最终要用的梯度。"},{"a":"训练 Loss","b":"测试表现","diff":"反向传播降的是训练 Loss；真正目标是让验证/测试也变好（泛化），二者并不总一致。"}]},{"type":"mistakes","items":["以为反向传播是一种‘独立的训练算法’——它只是高效算梯度的办法，配合梯度下降做更新。","以为反向传播会‘改变数据’——它改的是参数，数据只是被读取。","以为每次更新‘重算一遍整个网络’——它就是一次前向加一次反向后向，是训练一轮的标准动作。","把链式法则当作负担——它恰恰是把‘上亿次求导’压缩成一次回传的功臣。","以为推理阶段也在反向传播——推理只做前向，反向传播只在训练阶段发生。"]},{"type":"deep","title":"深入一点：链式法则为什么能一次算完所有梯度","beginner":["想象很多齿轮咬合在一起，转动第一个会带动一系列变化。链式法则就是：要知道第一个变化对最后结果影响多大，把每一段齿轮的传动比连乘起来。","反向传播正因为是‘倒着’算，每一层的中间结果能复用给前一层，所以只回传一次就拿到所有梯度。","这就是为什么训练深度网络是可行的：代价只是一次前向 + 一次反向后向的两次‘完整扫过’。"],"advanced":["数学上：∂L/∂θ 通过链式法则逐层展开，如 ∂L/∂W² = ∂L/∂ŷ · ∂ŷ/∂h² · ∂h²/∂W²，其中 ∂L/∂h 从上一层传下来被复用。","反向传播的本质是‘反向模式的自动微分’，与机器学习框架的自动微分是同一套东西。","内存成本：正向要保存每层的中间激活供反向使用，所以训练显存常是推理的好几倍——这也是为什么训练和部署对显存要求差别巨大。","工程技巧：混合精度、梯度累加、梯度裁剪、残差与归一化，都是为了在反向传播时保持数值稳定、让梯度健康流动。"]},{"type":"exercise","prompt":"为什么说反向传播能在‘一次回传’里算出所有参数的梯度，而不是一个个试？","opts":["因为它用了链式法则，把中间结果逐层复用给前一层","因为它只更新一个参数","因为它不计算梯度，靠猜","因为反向传播其实是推理阶段做的事"],"a":0,"explain":"反向传播从输出端倒推，每一层的中间结果可被前一层复用，所以沿链式法则一次回传就获得全部梯度。","jump":"sec5-step2","jumpLabel":"链式法则逐层回传这一步"},{"type":"check","title":"结课检测：反向传播你弄懂了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"反向传播是在哪个阶段发生的？","opts":["只有在推理时","只在训练阶段，用来算梯度","随时都在发生","只在上线后"],"a":1,"explain":"反向传播只在训练时用（算梯度供梯度下降），推理阶段只做前向传播。","jump":"sec5-step0","jumpLabel":"正向算误差这一步"},{"q":"反向传播高效的关键在于？","opts":["暴力逐个试参数","链式法则把中间结果复用、一次回传算全部梯度","不计算梯度","只算一个神经元"],"a":1,"explain":"链式法则＋逐层复用让一次反向回传就能得到所有参数的梯度，从而高效。","jump":"sec5-step2","jumpLabel":"链式法则逐层回传这一步"},{"q":"『梯度消失』问题主要出现在？","opts":["只有一层的网络","层太深、梯度逐层相乘越来越小","训练数据太少","没有激活函数"],"a":1,"explain":"层数过多时梯度经链式反向往回传越乘越小，导致深层最底层几乎学不到东西——这就是梯度消失。","jump":"sec6","jumpLabel":"梯度消失这个现实话题"},{"q":"训练时为什么显存占用往往远高于推理？","opts":["因为屏幕更亮","正向要保存各层中间激活供反向使用","因为数据更大","因为反向传播用不了串行"],"a":1,"explain":"反向传播需要正向阶段的中间激活，这些要存起来，所以训练显存需求远高于只做前向的推理。","jump":"sec7","jumpLabel":"内存成本这一段"}],"done":"你知道了误差是怎么‘倒着传回去’高效改每一层参数的。至此我们讲完了模型的学习机制。下一大步：这些原理在语言模型上怎么落地？先从最底层的『切词』开始——Tokenization。","nextLesson":"l11-tokenization"},{"type":"connection","known":["神经网络的结构（一层层神经元）","梯度下降＝沿误差下降方向调参数"],"learned":["反向传播＝误差从输出端倒着传回每一层","链式法则让一次回传算完所有梯度","为什么大规模训练可行、为什么需要 GPU","梯度消失/爆炸、训练显存为何更大"],"next":"模型的‘通用学习引擎’讲完了。现在进入语言的世界：文字是怎么被喂进模型、变成数字的？下一课《Tokenization》。","links":[{"href":"#/lesson/l08-neural-network","text":"复习《神经网络》"},{"href":"#/lesson/l11-tokenization","text":"进入《Tokenization》"}]}]},"l11-tokenization":{"id":"l11-tokenization","title":"Tokenization：大模型是怎么『读』文字的","subtitle":"模型不直接‘看字’，而是先把文字切成一小块一小块的 Token，再变成数字。理解了 Token，你就理解了计费、长度限制、以及为什么某些词会被‘拆开’。","category":"c05-llm","chapterTitle":"第三章 · 语言进入模型","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["tokenization","token","bpe"],"prereqLessons":["l09-backprop"],"nextLesson":"l-embedding","sections":[{"type":"opening","question":"你经常看到『这个模型上下文 128K』『这次对话用了 3 万个 token』。Token 到底是什么？为什么不是按‘字’或‘词’计？模型到底是怎么把整段中文读进去的？","guess":"有人以为 token 就是字，或者以为模型直接读整个单词。","next":"这一课讲 Tokenization——把文字切成基本面片（Token），并把它变成模型能算的数字的前半段（后半段是下一课的 Embedding）。这一课你看懂『切词』。"},{"type":"why","before":"你想弄懂大模型到底在‘读’什么，但看到‘token’‘BPE’‘词表’这些词就头大，甚至搞不清 token 和字、词的区别。","problem":"不理解 Tokenization，你就看不懂计费为什么按 token、为什么输入太长会被截断、为什么个别词会被拆得‘很怪’，以及为什么不同分词器能力差别这么大。","need":"我们把‘切词’这件事讲透：先切成 Token，再查词表变数字。基础知识一到手，计费、上下文、词表这些概念全部能对号入座。"},{"type":"oneline","text":"Tokenization = 把一段文字按词表切成一连串 Token（大部分 Token 是常见词或词的一小段），再为每个 Token 分配一个编号；模型读的是这一串编号。Token 通常不等于“字”，一个英文单词多被切成 1~2 个 token。"},{"type":"intuition","blocks":[{"k":"用超市小票来想","t":"词表＝超市商品的条码目录；每件商品（常见词/词组）有固定条码。文字就是选购清单，Tokenizer 把清单拆成一件件能扫的商品（Token），每个扫出一个条码号。模型只见条码，不见商品。"},{"k":"用给单词编学号来想","t":"你给全班每个同学发学号，老师点名说学号而不是名字。Token 就是‘语言的学号’：把海量语言变成有限的一本学号册（词表），每个词/词片对应一个编号。"},{"k":"一句话记住","t":"Token 是模型能读的最小语言单位（常见词或词的一小段），每个 token 有编号。Token 数量≈你对模型说的话的‘字数账单’。"}]},{"type":"how","intro":"把一段文字从‘人看的’变成‘模型算的’，四步。","steps":[{"in":"① 准备词表（Vocabulary）","process":"训练前统计海量语料，用算法（如 BPE）找出最常用的一批‘词/词片’，编成词表（如 5 万~20 万个 token）。","out":"一本固定的‘条码目录’（词表）"},{"in":"② 切分（Tokenize）","process":"把输入文字按词表切成一连串 token。常见词整词成一个 token；生僻、低频的长词会被切成一两段。","out":"一串 token 编号"},{"in":"③ 变数字（映射到索引）","process":"每个 token 查它在词表里的位置，输出一个整数编号。这串整数就是模型真正‘看到’的输入。","out":"一串数字索引（模型输入）"},{"in":"④ 进入 Embedding（下一课）","process":"每个编号再被映射成一个稠密向量（Embedding），进入神经网络。注意：token 是‘编号’，向量是那棵树的下一层。","out":"可被神经网络计算的高维向量序列"}]},{"type":"realworld","items":[{"name":"为什么按 Token 计费","note":"模型的计算量正比于 token 数量——输入、输出都要为每个 token 过一次计算，所以 API 按 token 计费。"},{"name":"为什么中文更‘烧’ token","note":"中文字符一般每个字约占 1~1.5 个 token，英文常见的 1 个词常只占 1 个 token 左右。同样‘一段话’，中英 token 数差别明显。"},{"name":"为什么输入太长会被截断","note":"模型有上下文长度上限（如 128K token）。超出部分会被丢掉或报错，所以长文档要先剪裁。"},{"name":"为什么有的词被拆得奇怪","note":"词表有限，低频长词只能被切成几段。你看到 tokenizer 演示里把长词拆开，是正常操作。"}]},{"type":"compare","pairs":[{"a":"字（Character）","b":"Token","diff":"字是按书写单元；Token 是模型的分词单元，一个 token 常等于一个词或词的一部分，跟字不一一对应。"},{"a":"词（Word）","b":"Token","diff":"常见词一个词≈一个 token；但生僻词可能切成一两个 token 片段，tokenizer 不保证按词切。"},{"a":"Token 编号","b":"Embedding 向量","diff":"编号是‘这是谁’；Embedding 是把这个 token 变成一个携带语义的向量（下一课讲）。编号在前面，向量在后面。"},{"a":"不同模型词表","b":"同一模型词表","diff":"不同分词器/模型的词表不同，同一个词在不同模型的 token 数可能不同；这也是跨模型比较长度时要小心的点。"}]},{"type":"mistakes","items":["以为 token = 字数或单个字——一个 token 常是一词或词的一部分，中文约一字多 token。","以为 token 就是向量——token 是先编号，向量是下一层（Embedding）。","以为所有模型分词方式一样——不同模型词表和切分差异很大。","以为加长输入不花钱——输入要按 token 计费，上下文越长越贵。","给模型喂’整本小说‘——超出上下文窗口会被截断，要靠检索/摘要后再喂。"]},{"type":"deep","title":"深入一点：BPE 到底怎么切词（直观版）","beginner":["BPE（Byte Pair Encoding）思路：先把文字拆成最细单位，再反复把‘出现次数最多的相邻对’合并成一个新 token，直到词汇表够大。","结果：高频常见词是整词 token，低频长词被切成若干常用片段组合。","好处：既覆盖常见词，又能拼出任意新词（不生僻词就拼接），内存与效率平衡。"],"advanced":["更现代的有 SentencePiece / tiktoken 等，支持不依赖空格的中文、日文切分，并常对字节级做回退保证任何输入都可表达。","词表规模是权衡：太大则嵌入矩阵大、训练/部署内存高；太小则文本被切得更碎、每句 token 数变多。","指令/特殊 token（如 \u003c|start|>、\u003ceos>）也在词表里，模型输出时也会生成这些控制 token。","工程：API 的 max_tokens、上下文窗口、计费都与 tokenizer 强绑定，读文档时先看它用哪种 tokenizer。"]},{"type":"exercise","prompt":"你调用一个 LLM API，回答收到一本 200 页的小说说‘超长’。为什么？","opts":["小说太‘重’，服务器磁盘满了","文本 token 数超过了模型的上下文窗口上限，被截断或报错","小说是中文所以坏了","token 与长度无关"],"a":1,"explain":"模型能读的 token 总量有上限（上下文窗口）。200 页小说 token 数超限，所以被拒绝/截断。","jump":"sec5-step2","jumpLabel":"切分这一步"},{"type":"check","title":"结课检测：Token 你切明白了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"Token 最准确的理解是？","opts":["一个汉字或英文字母","模型能读的最小语言单位（常见词或词的一部分）","一个句子","一张图片"],"a":1,"explain":"Token 是分词后的单元，通常是常见词或词的一部分；不是字也不是句子。","jump":"sec5-step1","jumpLabel":"准备词表这一步"},{"q":"一段英文通常比同样内容的中文 token 数？","opts":["中文每字约占 1~1.5 token，英文常见 1 个词约 1 token，因此同样内容中英 token 数不同","完全一样","英文一定少","中文一定少"],"a":0,"explain":"不同语言的 token 化效率不同，同样语义中英所需 token 数有差别，这也影响计费与上下文占用。","jump":"sec6","jumpLabel":"中文更烧 token 这个点"},{"q":"模型计费为什么按 token？","opts":["因为 token 比较好看","模型计算量正比于 token 数，输入输出都按 token 消耗算力与成本","与算力无关，只是习惯","只有输出按 token"],"a":1,"explain":"每个 token 都要经过模型计算，所以输入输出都按 token 计费。上下文越长成本越高。","jump":"sec5-step3","jumpLabel":"进入 Embedding 这一步"},{"q":"Token 编号和 Embedding 向量的关系是？","opts":["二者是同一个东西","token 先编号，再映射成向量（Embedding），是两步","embedding 在 token 前面","没有关系"],"a":1,"explain":"先切词得到 token 编号，再把编号映射成稠密向量（Embedding）进入网络。编号是第一步，向量是第二层。","jump":"sec5-step3","jumpLabel":"进入 Embedding 这一步"}],"done":"文字被切成了 token 编号。可编号只是‘学号’，怎么变成‘有语义的数字’？下一课《Embedding》——把词变成电脑能懂、能算相似度的向量。","nextLesson":"l-embedding"},{"type":"connection","known":["神经网络只能处理数字（前面几课）"],"learned":["Token = 模型能读的最小语言单位","词表 + 切分 → token 编号","计费、上下文窗口、中文 token 化差异","BPE / SentencePiece 的思路"],"next":"拿到了 token 编号，下一课让它们‘变得有意义’：《Embedding》教你如何把每个 token 变成携带语义、能算相似度的向量。","links":[{"href":"#/lesson/l-embedding","text":"进入《Embedding》"},{"href":"#/lesson/l12-context-window","text":"相关：《上下文窗口与推理》"}]}]},"l12-context-window":{"id":"l12-context-window","title":"上下文窗口与推理：模型一次能『看见』多少","subtitle":"模型不是全知全能的——它一次只能‘看见’上下文窗口里的那点内容。搞懂窗口、记忆与推理，你就明白了为什么模型‘记不住上句’、以及长对话为什么会『健忘』。","category":"c05-llm","chapterTitle":"第三章 · 语言进入模型","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["context-window","inference","token"],"prereqLessons":["l11-tokenization"],"nextLesson":"pl-prompt","sections":[{"type":"opening","question":"你问模型‘还记得我们刚才说的那件事吗’，它却像失忆。可它明明能把长文档读得很好。这种‘时而记得、时而忘记’是怎么回事？关键就在‘上下文窗口’。","guess":"有人以为模型像人一样有持久记忆，或者把所有历史都一直记着。","next":"这一课讲上下文窗口（一次能读多少 token）、以及推理时模型怎么用它。你会明白：模型的‘记忆’不是永久的，而是每次只装进窗口里的内容。"},{"type":"why","before":"你想让模型处理长文档、维持长对话，可它总是‘忘’前文，或说‘超出长度’。你需要知道模型的看得见范围到底由什么决定。","problem":"不理解上下文窗口，你会误以为模型‘记性差是 bug’，或把太长内容硬塞进去导致被截断、变慢、变贵。","need":"我们把窗口和记忆讲清楚：模型每一轮都只看窗口内 token，历史要么‘还装得下’、要么被截断或靠摘要/检索补充。这是产品设计里管理长上下文的必修课。"},{"type":"oneline","text":"上下文窗口 = 模型处理一次输入时能同时‘看见’的 token 总量上限（如 8K / 128K）。模型没有永久记忆：每次回答都只基于【当前提问 + 窗口里装得下的前文】来推理；超出的部分会被忽略或截断。"},{"type":"intuition","blocks":[{"k":"用餐桌来想","t":"上下文窗口＝一张固定的餐桌，一次只能摆下这么多菜（token）。你点的菜超过桌面，就只能摆一部分，多余的放不下（被截断/挤掉）。想让模型‘看见’更多前文，就得在桌面腾位置。"},{"k":"用近视眼来想","t":"模型像只能看清眼前一页的近视读者：它‘当下’能读到的就是窗口内这一页（token）。你翻页太快、或书太长，它就只能看到最近一页，前面就模糊/记不住了。"},{"k":"一句话记住","t":"窗口决定‘这一次能看多少’；推理时模型只用窗口内信息作答。管理好窗口＝控制成本、长度与质量。"}]},{"type":"how","intro":"把‘一次推理’如何用上下文窗口拆开。","steps":[{"in":"① 组装输入：系统提示 + 历史对话 + 当前问题","process":"把要模型‘看到’的内容（系统指令、历史轮次、当前提问）全部转成 token，拼在一起。","out":"一串待处理的 token"},{"in":"② 检查是否超窗：超出则截断/丢弃","process":"如果这串 token 超过上下文窗口，就要截断——通常去掉最早的部分（把最旧历史丢掉）或报错。","out":"窗口内的 token 序列（旧的被挤掉）"},{"in":"③ 模型基于窗口推理：只看眼前这些","process":"模型对窗口内 token 做前向计算，生成输出。它看到的‘世界’仅限于窗口内的内容。","out":"一个基于窗口内容的回答"},{"in":"④ 输出也占窗口：新一轮把回答加进历史","process":"新生成的回答也消耗 token，下一轮会把它并进历史一起送入窗口。窗口放不下时，最老的内容再次被挤掉。","out":"对话一轮轮推进，历史越久越可能被挤走"}]},{"type":"realworld","items":[{"name":"系统提示（System Prompt）","note":"放在窗口最前面的‘设定’，指导模型身份与行为。它一直占用窗口空间，越长越‘挤占’可用的对话空间。"},{"name":"长对话为什么会‘忘’","note":"窗口有限，塞满了就从最早的开始丢。所以你说‘刚才那事’时，如果它早已被挤出窗口，模型就‘失忆’了。"},{"name":"RAG / 摘要来救场","note":"为了解决窗口有限，常用检索增强（把相关资料塞进窗口）或把历史先摘要再放进去，让模型‘看到’最关键的内容。"},{"name":"为什么窗口越大越贵","note":"窗口越大，每次处理 token 越多，计算和成本越高，延迟也越高。所以要在‘装得下’和‘别太贵’之间权衡。"}]},{"type":"compare","pairs":[{"a":"上下文窗口","b":"长期记忆","diff":"窗口是一次处理能看到的上限，用完即丢；长期记忆（如数据库/向量库）是把历史存在外部，需要时再取回塞进窗口。"},{"a":"窗口大","b":"窗口小","diff":"大窗口能装更多历史、处理长文档，但更贵更慢；小窗口便宜快，但容易丢失远历史。"},{"a":"截断最老","b":"截断最新","diff":"为保住当前问题和关键指令，通常优先丢最早的旧历史；但设计截断策略是产品细节。"},{"a":"窗口内的 token","b":"窗口外的内容","diff":"窗口内模型能‘看到’，窗口外对本次推理透明。管理好‘哪些进窗口’是做好 AI 应用的核心。"}]},{"type":"mistakes","items":["以为模型有永久记忆——它每轮只看窗口内内容，不主动记到外部。","把超长内容硬塞——会截断或报错、变贵变慢，应该先摘要/检索。","以为窗口越大越好——越大越贵越慢，够用就好。","忽略系统提示占用——过长的 system prompt 会挤占对话空间。","以为‘上轮内容必定还在窗口’——长对话久了旧内容会被挤出。"]},{"type":"deep","title":"深入一点：怎么把‘再多的历史’塞进有限窗口","beginner":["三个常用办法：①截断（只留最近）；②摘要（把旧历史浓缩成几句再放进去）；③检索（RAG，只把相关的片段取回）。","这样有限窗口能处理远超其长度的内容——不是全看，而是挑重点看。","本质：把‘无限的过去’压缩成‘有限但有信息量’的内容。"],"advanced":["KV 缓存：推理时为每个历史 token 缓存注意力 Key/Value，新轮次只需对新 token 计算，从而复用历史、提速。缓存也占用显存，受窗口与批大小影响。","窗口的‘有效长度’与注意力机制相关：超长上下文下模型对窗口中部的内容注意力会衰减，所以不是窗口越大‘有效信息’就越多。","工程：滑动窗口、压缩记忆、多轮摘要、RAG 是处理长上下文的四大主流手段；商用 API 要对 max_tokens、上下文上限、成本三者一起规划。"]},{"type":"exercise","prompt":"你的 AI 助手很奇怪：昨天聊了 500 条，今天一问‘咱昨天说的方案是啥’，它答不上来。为什么？","opts":["它丢了硬盘","500 条历史远超上下文窗口，最早的早已被挤出，今天只剩窗口内的内容","它故意装傻","因为模型只能记住今天的话"],"a":1,"explain":"模型无永久记忆，每轮只看窗口内 token。昨天 500 条早已超出窗口被挤掉，所以它‘忘’了——除非你用摘要或检索把关键内容放回窗口。","jump":"sec5-step3","jumpLabel":"模型基于窗口推理这一步"},{"type":"check","title":"结课检测：上下文窗口你懂了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"上下文窗口指的是？","opts":["模型一次能同时看到的 token 量上限","浏览器窗口大小","训练数据的来源","硬盘剩余空间"],"a":0,"explain":"上下文窗口是模型一次处理时能‘看见’的 token 总量上限，决定它能读到多少前文。","jump":"sec5-step0","jumpLabel":"组装输入这一步"},{"q":"输入超过上下文窗口时，最常发生的是？","opts":["模型偷偷多学一点","截断（通常丢最早的历史）或报错","自动扩容到无限","毫无影响"],"a":1,"explain":"超窗后通常从最早部分开始截断，或直接报错；不会无限扩容。","jump":"sec5-step1","jumpLabel":"检查是否超窗这一步"},{"q":"模型为什么‘记不住’很久以前的对话？","opts":["没有永久记忆，长对话旧内容会被挤出窗口","因为对话太长会伤显卡","模型只记一天","因为没人提醒它"],"a":0,"explain":"模型每轮只基于窗口内 token 作答，旧历史放不下就被挤掉，所以会‘健忘’。","jump":"sec5-step3","jumpLabel":"模型基于窗口推理这一步"},{"q":"处理远超窗口的长文档，常用哪种做法？","opts":["整本硬塞，靠运气","先切块/检索（RAG）把最相关的部分放进窗口","让模型用放大镜","把窗口变小"],"a":1,"explain":"用切块检索（RAG）或摘要，把关键内容装进有限窗口，是处理超长内容的主流手段。","jump":"sec8","jumpLabel":"长对话救场这一段"}],"done":"你明白了窗口的边界与记忆的关系。那怎么把‘想表达的东西’在有限窗口里说得最清楚？下一课《Prompt 与上下文》——怎么和模型说清楚。","nextLesson":"pl-prompt"},{"type":"connection","known":["Token 是计费与长度的基本单位（上一课）"],"learned":["上下文窗口 = 一次能看到的 token 上限","模型无永久记忆，只看窗口内","长对话为何会‘忘’、如何用摘要/检索救场","窗口越大越贵、KV 缓存等工程细节"],"next":"窗口里装什么是你说了算的。下一课《Prompt 与上下文》：如何把提示词组织好，让模型在窗口里看到最有用的信息。","links":[{"href":"#/lesson/l11-tokenization","text":"复习《Tokenization》"},{"href":"#/lesson/pl-prompt","text":"进入《Prompt 与上下文》"}]}]},"l18-vibe-coding":{"id":"l18-vibe-coding","title":"Vibe Coding 入门：用 AI 直接做出产品","subtitle":"十八节课的终点，也是‘你真的能做出东西’的起点。Vibe Coding 就是：把 AI 当结对程序员，用‘先跑起来、边做边改’的节奏，从零做出一个能上线的产品。","category":"c11-ai-coding","chapterTitle":"第五章 · 让 AI 干活","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["vibe-coding","ai-coding","product-building"],"prereqLessons":["l22-ai-coding"],"nextLesson":"v01-web","sections":[{"type":"opening","question":"你把 AI 的原理、模型、Agent、AI 编程都学了一遍。现在只剩下最后一个问题：我到底怎么靠 AI，做出一个真正能给别人用的产品？","guess":"有人以为要做产品必须先写几年代码，或以为‘让 AI 全自动’就能直接上线。","next":"这一课收官：Vibe Coding 方法学——从想法到上线的五步节奏，以及它与前 17 课的知识怎么连成一条线。学完这课，你就可以直接进入 Vibe 路径，一步步动手了。"},{"type":"why","before":"你懂了很多概念，却感到‘知识到产品’之间有道坎：真上手做，不知道从哪里开始、怎么保证不翻车。","problem":"只要动手就迷茫，往往是缺一套‘从 0 到 1 的通用节奏’——不是缺知识，是缺流程。","need":"Vibe Coding 给了你一套可重复的流程：小步快跑、AI 写我审、先跑通再打磨、随时能回退。把前 17 课的知识装进这条流水线里，知识就开始变现。"},{"type":"oneline","text":"Vibe Coding = 用 AI 当结对程序员，以‘提出想法 → 让 AI 搭建 → 立刻跑起来 → 边用边改 → 测试收尾 → 部署上线’的高频小步节奏做产品；你负责方向、判断与验收，AI 负责快速产出与迭代。"},{"type":"intuition","blocks":[{"k":"用做饭来想","t":"传统开发像按菜谱做满汉全席：先备齐所有料、严格按步骤，做完才能吃。Vibe Coding 像‘边炒边尝’：先做最核心的一道菜，尝一口，再加料调整，食物永远在‘能吃’状态。"},{"k":"用盖房子要图纸来想","t":"即使最快的施工（AI），也需要一张图纸（你的需求与边界）。你的‘产品感’就是图纸；AI 的速度再快，没有图纸就只会到处乱建。"},{"k":"一句话记住","t":"Vibe Coding 不是‘AI 全自动’，而是‘AI 快、人稳’：人给方向与验收，AI 给速度与草稿。节奏高频，风险可控。"}]},{"type":"how","intro":"Vibe Coding 的标准节奏，六步。这也串起你学过的所有概念。","steps":[{"in":"① 定需求：一句话说清你要做什么（与为谁做）","process":"用一个最小可解决问题描述产品：谁的什么痛点、你的方案是什么。范围越小越容易成功（MVP 思维）。","out":"一句清晰的需求 + 一个最小可交付范围","note":"这一步靠你的产品判断，AI 不懂用户，只能帮你澄清。"},{"in":"② 让 AI 搭骨架","process":"把需求、技术选型、约束（用什么框架、跑在哪）交给 AI，让它生成初始代码骨架。给足上下文，产出一发即中的概率更高（上下文工程）。","out":"一份能跑起来的最初版本"},{"in":"③ 立刻跑起来，别等‘完美’","process":"马上去运行、点开看。Vibe Coding 的高频循环从这里开始：跑→看到问题→反馈给 AI→再跑。","out":"一个‘总是能动的’半成品"},{"in":"④ 边用边改：小步迭代","process":"每次只改一小块，用‘分层报错 + 清晰描述’喂给 AI（见 Vibe 路径第 ① 课）。别一次塞一堆改动。","out":"功能逐步齐全、稳定"},{"in":"⑤ 测试与收尾：让 AI 造假不了","process":"请 AI 一起写测试、补边界、检查安全与可维护性。把‘验证’从人肉重复劳动交给自动化（见 Vibe 路径第 ⑤ 课）。","out":"一个经测试、可交付的版本"},{"in":"⑥ 部署上线：让其他人也能用","process":"把本地能跑的版本部署到服务器/托管平台，配好域名与环境（见 Vibe 路径第 ⑦ 课）。至此产品真正‘是个产品’了。","out":"可被访问的线上产品"}]},{"type":"realworld","items":[{"name":"MVP（最小可用产品）","note":"先做一个最核心、能用的小版本，再迭代。Vibe Coding 天然适合这种节奏。"},{"name":"AI 出错的兜底","note":"AI 会挖坑（假依赖、过时 API、逻辑偏差）。用版本控制（Git）、测试、审查来兜底，见 Vibe 路径第 ②⑤ 课。"},{"name":"不要一次让 AI 写‘整个系统’","note":"一次一块，跑通一块。越大越容易失控，越小越好定位问题。"},{"name":"从想法到上线的路径","note":"这正是接下来 Vibe 路径 8 节课要带你走完的事：Web 链路 → Git → API → 数据库 → 测试 → 项目结构 → 部署 → 全流程实战。"}]},{"type":"compare","pairs":[{"a":"传统开发","b":"Vibe Coding","diff":"传统：先设计全、再写代码、周期长；Vibe：先跑通一点点、高频迭代、人审 AI 写。"},{"a":"AI 全自动","b":"Vibe Coding","diff":"全自动 = 没有人在关键处把关，风险失控；Vibe = 人在方向与验收把关，AI 提供速度。"},{"a":"学 AI 原理","b":"做 AI 产品","diff":"原理让你懂‘为什么’（前 17 课）；Vibe 让你会‘怎么做’（点出产品节奏）。两条腿都要有。"},{"a":"MVP","b":"大而全","diff":"MVP 聚焦最小核心、快速验证；大而全一次做完往往拖垮进度、难以验证。"}]},{"type":"mistakes","items":["以为 Vibe Coding = 让 AI 全自动、人撒手——结果是失控。","一次让 AI 生成整个复杂系统——分裂成小块、跑一块再下一块。","不给 AI 上下文就让它开工——需求、技术栈、约束都要交代清楚。","不做测试、不审查就合并——AI 挖的坑要由你填。","只会‘跑起来’不会‘收尾’——错过测试、部署与可维护性，产品永远停留在 Demo。"]},{"type":"deep","title":"深入一点：把前 17 课装进这条流水线（知识地图收束）","beginner":["这 18 节课其实是完整的一条线：看懂 AI → 懂学习 → 懂语言 → 会用 → 让 AI 做事 → 真正做产品。","Vibe Coding 是‘消费端’：把‘生成/原理端’学到的能力，落成产品动作。","你做产品遇到大部分概念难题，都可以回查前面课程找答案。"],"advanced":["从工程看 Vibe Coding：它是把『提示工程、上下文工程、工具调用、Agent 循环、测试、部署』整合成一个可重复的研发流程。","关键在『节奏』：高频小步 + 及时验收 = 风险最小化。每个循环都要有『可回滚』（Git）、『可验证』（测试）作为护栏。","对想长期做产品的人：Vibe Coding 是高效起点，但深入后仍要补工程基础（架构、性能、安全、数据），这正是 Vibe 路径后续内容。"]},{"type":"exercise","prompt":"你想做一个‘帮同事查快递’的小工具，第一次让 AI 动手前最该先做哪件事？","opts":["让 AI 直接写整个系统","先把需求压缩成一句话最大可交付（MVP），并想清楚边界与技术选型，再让 AI 搭骨架","先把代码写完再想需求","什么都不做"],"a":1,"explain":"Vibe Coding 第一步是定清需求与 MVP 边界，再交 AI 搭骨架；直接让 AI 写整个系统最容易失控。","jump":"sec5-step0","jumpLabel":"定需求这一步"},{"type":"check","title":"结课检测：Vibe Coding 方法学你掌握了吗","intro":"共 4 题。全部答对即可完成核心路径，进入 Vibe 路径动手。答错会带你回对应段落复习。","questions":[{"q":"Vibe Coding 的核心分工是？","opts":["AI 全自动，人不管","AI 出速度与草稿，人定方向、判断与验收","人和 AI 各写一半但互相看不懂","不用 AI"],"a":1,"explain":"Vibe Coding 是‘AI 快、人稳’：AI 负责产出与迭代速度，人负责方向、边界与验收。","jump":"sec5-step3","jumpLabel":"边用边改这一步"},{"q":"为什么 Vibe Coding 强调‘先跑起来，别等完美’？","opts":["因为跑起来就自动完美了","高频小步：先有个能用的骨架，边用边发现问题边改，风险最小","为了显得效率高","因为完美永远做不到"],"a":1,"explain":"先跑起来 + 小步迭代，让产品始终‘能动’，问题及时暴露，才不至于最后一次性翻车。","jump":"sec5-step2","jumpLabel":"立刻跑起来这一步"},{"q":"AI 产出的代码，靠什么兜底最靠谱？","opts":["全信不查","版本控制(Git) + 自动化测试 + 人工审查","多跑几次不失败就算对","让 AI 自己检查自己"],"a":1,"explain":"AI 会挖坑，用 Git 可回滚、测试可验证、人来审查，是最稳的兜底组合。","jump":"sec5-step4","jumpLabel":"测试与收尾这一步"},{"q":"本课所在的完整 18 课主线，最后一步指向哪里？","opts":["结束学习","进入 Vibe Coding 工程基础路径，从零动手到上线","再学一遍","去考试"],"a":1,"explain":"核心路径以《Vibe Coding 入门》收官，之后进入 Vibe 路径：从 Web → Git → API → 数据库 → 测试 → 项目结构 → 部署 → 全流程实战。","jump":"sec5-step5","jumpLabel":"部署上线这一步"}],"done":"恭喜你走完 18 课核心主线：从看懂 AI 世界，到懂学习、懂语言、会用、让 AI 干活，再到 Vibe Coding 方法学。下一步，进入 Vibe Coding 工程基础路径，亲手把第一个产品做出来。","nextLesson":"v01-web"},{"type":"connection","known":["AI 原理、训练、语言模型、RAG、Agent、AI 编程（前 17 课）"],"learned":["Vibe Coding = 人定方向 + AI 出速度的小步高频流程","定需求 → 搭骨架 → 跑起来 → 小步改 → 测试 → 部署 六步节奏","MVP、Git 兜底、测试护栏","与 Vibe 路径 8 节课的衔接"],"next":"下一课起进入《Vibe Coding 工程基础》路径：从①『一个 Web 产品是怎么跑起来的』开始，一路做到⑦『从本地 Demo 到正式上线』与⑧『全流程实战』。","links":[{"href":"#/lesson/v01-web","text":"进入 Vibe 路径 ①《一个 Web 产品是怎么跑起来的》"},{"href":"#/lesson/l22-ai-coding","text":"回看《AI Coding》"}]}]},"l22-ai-coding":{"id":"l22-ai-coding","title":"AI Coding：把 AI 变成你的结对程序员","subtitle":"从‘让 AI 补全一行’到‘让 Agent 自己把整个功能做完’，AI 编程正在改变开发方式。这一课讲清楚你的新‘结对程序员’该怎么用、边界在哪。","category":"c11-ai-coding","chapterTitle":"第五章 · 让 AI 干活","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["ai-coding","pair-programming","agentic-coding","codegen"],"prereqLessons":["l-agent"],"nextLesson":"l18-vibe-coding","sections":[{"type":"opening","question":"现在很多人‘说几句话就让 AI 写了个网站’。AI 编程到底能到哪一步？是补全几行，还是真能独立完成一整个项目？代码谁负责、谁检查？","guess":"有人以为有了 AI 就不需要会写代码，或以为 AI 写的一定完美。","next":"这一课把 AI 编程按‘参与度’分成几档：补全、生成块、Agent 干活。你会明白 AI 是强力加速器，但产品的主人仍是人——你要负责验收、判断、兜底。"},{"type":"why","before":"你看到同事用 AI 刷刷刷就把功能写完了，也想用起来，但不知道从哪些场景入手、AI 与自己怎么分工、会不会写出不可维护的代码。","problem":"要么把 AI 当‘会写代码的搜索引擎’用（只补全、效率低），要么完全交给 Agent（风险失控、不可维护）。两种极端都不对。","need":"我们建立清晰的协作模型：把 AI 当结对程序员——你定目标、看边界、审结果，它负责快速产草稿、查报错、做重复活。并讲清代码审查永远是人的责任。"},{"type":"oneline","text":"AI 编程 = 把 AI 当作结对程序员：它能极快生成代码、解释报错、重构小块、补齐模板，甚至（Agent 模式）自主跑完一个小任务；但它不负责‘理解真实需求与产品边界’，更不负责‘保证代码正确与安全’——这两条永远是你的职责。"},{"type":"intuition","blocks":[{"k":"用带实习生来想","t":"AI 像一位非常聪明、打字极快、但缺乏项目上下文的实习生：你交代清楚它干得又快又好，但你不审核，它就会把半成品、甚至跑偏的东西交上来。你是那个要验收的‘主管’。"},{"k":"用导航来想","t":"AI 代码生成像开车导航：它帮你规划路线、少走弯路，但最终握方向盘、看路障、负责任的还是你。导航偶尔带你进死胡同，你得会判断。"},{"k":"一句话记住","t":"AI 负责‘快’，人负责‘对’。需求、验收、边界、安全、可维护，这些‘产品感’必须由你把关。"}]},{"type":"how","intro":"按‘AI 参与深度’把 AI 编程分成三档，逐步升级。","steps":[{"in":"① 补全与问答：AI 当‘高级补全器’","process":"在 IDE 里，AI 根据你的上下文补全下一行、解释函数、改命名、写测试骨架。你仍在主导每一行。","out":"写代码更快，错误更少，思路延伸"},{"in":"② 整块生成：给需求要结果","process":"你描述清楚功能（+给上下文/约束），让 AI 生成一块完整代码（接口、函数、组件、配置）。适合模板化、独立、边界清晰的代码。","out":"从一句话到一块可运行代码"},{"in":"③ Agent 模式：让 AI 自己跑任务","process":"给 Agent 目标与工具（读文件、改代码、跑测试、看报错），它循环推进直到完成：读→改→测→看结果→再改。Vibe Coding 常用此模式。","out":"AI 自主完成一个小功能/修复，你只做验收","note":"三档没有绝对高低，按任务复杂度与风险选择：事小用补全，模块化用生成，端到端小任务用 Agent。"},{"in":"④ 无论哪档：验收都是人的责任","process":"AI 产出的代码要过一遍：能跑通吗？符合需求吗？有没有安全/边界问题？有没有不可维护的烂摊子？","out":"‘AI 生成 + 人把关’的可靠组合"}]},{"type":"realworld","items":[{"name":"IDE 补全（Copilot / 助手补全）","note":"在你写代码时实时补全与建议，提升速度，适合第一档使用。"},{"name":"Claude Code / Codex 等 Agent","note":"在终端里用对话让 Agent 自主读代码、改代码、跑测试、看报错并迭代。适合第三档的端到端小任务。"},{"name":"提示词注入与‘AI 挖坑’","note":"AI 可能带进不存在的库、过时 API、或往代码里注入不可靠内容。所以自动合并前要审查与测试。"},{"name":"测试的必要性","note":"AI 生成的代码尤其需要自动化测试兜底——让 AI 同时生成测试，或让测试流程把‘AI 挖的坑’抓出来。"}]},{"type":"compare","pairs":[{"a":"补全","b":"Agent 自主完成任务","diff":"补全由你主导逐行效率；Agent 自主循环完成任务，但风险与失控面也更大，验收更要跟上。"},{"a":"AI 生成","b":"人审查","diff":"生成求快，审查求稳；缺了审查，快只是把问题放大。人最终为代码负责。"},{"a":"上下文工程","b":"单纯提示","diff":"给 AI 越清晰的项目上下文（相关文件、约束、报错），产出越贴近需求；只有一句‘给我写个 XX’往往离题。"},{"a":"AI 编程","b":"传统手写","diff":"AI 加速明显，但可维护性、安全、清晰度仍需人把控。二者是‘助手’与‘主人’，不是替代。"}]},{"type":"mistakes","items":["以为 AI 写的代码多跑几次就完美——需要你验证需求、安全与可维护性。","不给 AI 上下文就让它‘整个写一个系统’——上下文不够，产出必然跑偏。","把 AI 生产的一个报错原样丢回去又问一次——结构化描述（分层+现象+代码+判断）才高效。","忽略测试——AI 生成的代码尤其要靠测试兜底。","让 Agent 无约束乱跑——要给目标、边界、可执行命令白名单，防它越界或引火烧身。"]},{"type":"deep","title":"深入一点：为什么说‘上下文工程’是 AI 编程的核心能力","beginner":["AI 对你代码库的了解，取决于你给了它多少相关上下文：文件、函数、依赖、约束。","把相关文件、报错、你的判断组织好喂给它，比‘但求一句提示’有效得多。","一段‘上下文+需求+验收标准’的提示，往往一次出对。"],"advanced":["Agentic Coding：Agent 通过工具主动读你的仓库（RAG/索引/搜索），自动定位相关文件，减少你手动喂上下文——但你要给它合理的边界与文件白名单。","评估与回归：好的 AI 编程流程是‘可选、可测、可回滚’的；用测试套件 + Git 回滚保证每步可控。","安全：AI 生成的依赖、命令、脚本要审查；警惕提示注入（仓库里的恶意内容诱导 Agent 执行危险操作）。","与 Vibe Coding 衔接：下一课 Vibe Coding 就是‘用 AI 做产品的完整方法学’——从想法到上线的全过程里，AI 编码只是其中一环。"]},{"type":"exercise","prompt":"你让 AI 给一个项目写了个完整功能，它直接贴给你一段很长的代码。最该做的下一步是？","opts":["不看不测直接用","先审查：能否跑通、符合需求吗、有没有安全/边界/可维护问题，再用测试验证","把代码藏起来","直接删掉项目"],"a":1,"explain":"AI 生成求快，人负责对。一定要过需求、跑测试、看边界与安全再合入——验收是人的责任。","jump":"sec5-step3","jumpLabel":"验收是人的责任这一步"},{"type":"check","title":"结课检测：AI 编程你怎么用才靠谱","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"把 AI 当‘结对程序员’，谁对最终代码负责？","opts":["AI","人（你）：负责需求、验收、边界、安全","编译器","没有人"],"a":1,"explain":"AI 提供速度与草稿，但正确性、安全性、可维护性与需求符合度，责任永远在人的验收。","jump":"sec5-step3","jumpLabel":"验收是人的责任这一步"},{"q":"能让 AI 一次产出更贴合需求的代码，最有效的是？","opts":["给足相关上下文、约束与验收标准，而不是一句模糊指令","多喊几句‘再改改’","关了网络","把需求藏起来"],"a":0,"explain":"上下文工程是核心：相关文件、约束、期望结果越清楚，产出一发即中的概率越大。","jump":"sec7","jumpLabel":"上下文工程段"},{"q":"AI 生成的代码尤其需要什么来兜底？","opts":["运气","自动化测试与审查","更多的注释","更长的提示"],"a":1,"explain":"测试能把 AI 挖的坑尽早抓出来；配合人的审查，才够可靠。","jump":"sec6","jumpLabel":"测试的必要性这一条"},{"q":"关于‘AI 挖坑’（引用不存在的库/过时 API），正确的态度是？","opts":["全信 AI","AI 可能出错，所以自动合并前要审查依赖与 API 是否存在、是否过时","因为是 AI 所以一定对","与 AI 无关"],"a":1,"explain":"AI 会编造看似合理的依赖或过时 API。合入前要核验，这也正是人把关的一环。","jump":"sec6","jumpLabel":"AI 挖坑这一条"}],"done":"你会用 AI 编程当加速器了。最后一课，把这些整合成方法论：《Vibe Coding 入门》——从想法到上线，用 AI 完整做产品的全过程。","nextLesson":"l18-vibe-coding"},{"type":"connection","known":["Agent 能让模型自主调用工具（上一课）","上下文窗口与 Prompt 工程（前几课）"],"learned":["AI 编程三档：补全 / 整块生成 / Agent 模式","人负责需求、验收、边界、安全","上下文工程是高效使用 AI 编程的核心","测试兜底与防 AI 挖坑"],"next":"下一步是本路径收官：《Vibe Coding 入门》——把 AI 编程、Agent、上下文这些能力整合成从零到上线的完整产品方法论。","links":[{"href":"#/lesson/l-agent","text":"复习《Agent 智能体》"},{"href":"#/lesson/l18-vibe-coding","text":"进入《Vibe Coding 入门》"}]}]},"pl-data":{"id":"pl-data","title":"数据、模型与参数：AI 学习的三件套","subtitle":"模型在拿什么学？答：数据是教材，模型是大脑结构，参数是大脑里无数个可调的小旋钮。这三者的关系，是理解一切 AI 的起点。","category":"c01-ai-world","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["data","model","parameter"],"prereqLessons":["pl-train-infer"],"nextLesson":"l05-gradient-descent","sections":[{"type":"opening","question":"总听人说『这个模型有 70B 参数』『训练数据有几十 TB』。参数、数据、模型——这三个词你天天见，但它们到底是什么、什么关系？为什么参数越多越厉害（但又更贵）？","guess":"有人以为『模型的全部本事都是数据里抄来的』，或者『参数越多就一定越好』。","next":"这一课我们从最底层的三件套讲起：数据（模型看什么）、模型（模型长什么样）、参数（模型的'旋钮'）。搞懂它们，你对『训练』『能力』『成本』的理解会瞬间落地。"},{"type":"why","before":"你想弄懂 AI 为什么能『学会』，于是去看资料，却总被『参数规模』『训练数据量』这些数字砸晕，不知道它们和『模型会不会用』有什么关系。","problem":"把数据、模型、参数三者混为一谈，就解释不了很多现象：为什么同样是鹦鹉学舌，有的模型聪明有的笨？为什么参数翻倍模型不一定翻倍聪明，但成本一定翻倍？为什么有时数据质量比数据量更重要？","need":"我们把三件套分清楚：数据是『给模型看的世界』，模型是『看世界的脑回路结构』，参数是『脑回路里无数个可微调的小值』。层层拆开，很多『为什么』都能对号入座。"},{"type":"oneline","text":"数据（Data）= 教材与习题；模型（Model）= 大脑的『结构设计』（有多少层、神经元怎么连）；参数（Parameter）= 大脑里数以亿计的『小旋钮』，训练就是把它们拧到最合适的位置。能力来自结构与数据，旋钮的数量决定模型的『规模』与成本。"},{"type":"intuition","blocks":[{"k":"用学生来想","t":"数据＝读过的书、做过的题（内容）；模型＝这位学生大脑的结构（聪明程度上限）；参数＝大脑里成千上万个可以不断微调的小连接。训练就是：用大量好书好题，把这几亿个小连接一点点调顺，让这个学生变强。"},{"k":"用收音机来想","t":"模型＝收音机的电路设计；数据＝收到的电台信号；参数＝面板上能拧的旋钮。一个收音机好不好，取决于电路设计（模型）+ 接收到的信号（数据）+ 旋钮拧得对不对（参数调得好不好）。"},{"k":"一句话记住","t":"结构（模型）定上限，数据定内容，参数定『具体怎么算』。参数越多，模型越『大』，理论上能学的东西越多，但训练成本与部署成本也越高。"}]},{"type":"how","intro":"把三件套分别拆开：它是什么、从哪来、为什么重要。","steps":[{"in":"① 数据 Data：模型的『世界』","process":"文本、图片、代码、语音等一切喂给模型的东西。训练数据的规模与质量，直接决定模型见没见过某类知识。数据要先清洗、去重、组织。","out":"『教材』：决定模型大概会什么、懂什么"},{"in":"② 模型 Model：大脑的『结构』","process":"神经网络『长什么样』——有多少层、每层多少神经元、神经元之间怎么连、用什么激活函数。这是架构设计，决定了模型理论上的能力上限。","out":"『脑回路设计』：决定上限与能学到的结构"},{"in":"③ 参数 Parameter：可调的『小旋钮』","process":"每条神经连接上的权重大小（几亿到几千亿个数字）。它们是训练真正在改的东西。参数量常被拿来衡量模型规模（如 7B、70B）。","out":"『旋钮集合』：决定『具体怎么算』与参数量级"},{"in":"三者如何协作","process":"训练时：把数据喂给具备结构的模型，反复调整参数，让输出尽量接近期望。三要素缺一不可：结构弱、数据差、或参数没调好，都会变成坏模型。","out":"一个『读过好书、结构良好、旋钮调准』的可用模型"}]},{"type":"realworld","items":[{"name":"参数规模 70B / 7B / 1.5B","note":"B 指 Billion（十亿），是模型参数量。大模型参数量常在几十亿到几千亿之间。参数量越大，模型『容量』越大，但训练与运行成本也越大。"},{"name":"为什么 GPT-4 系列这么强也这么贵","note":"越大参数 + 越多数据 = 能力更强，但训练要的算力和部署要的显存都剧增。能力与成本是一对不断权衡的对手。"},{"name":"『数据是新时代的石油』","note":"高质量、干净、多样的训练数据极关键。数据质量不足时，再大的模型也可能『吃垃圾吐垃圾』。这也是为什么很多公司拼命囤数据。"},{"name":"为什么中文模型注重中文语料","note":"模型的能力受训练数据影响很大。中文语料不足的模型，中文表现就差。这也是为什么国产大模型要专门堆中文高质量数据。"}]},{"type":"compare","pairs":[{"a":"数据 Data","b":"模型 Model","diff":"数据是『输入的世界/教材』，模型是『处理世界的结构』。同样的模型用不同数据学出不同特长；同样的数据放进不同结构，效果也不同。"},{"a":"模型 Model","b":"参数 Parameter","diff":"模型是结构设计（虚、相对固定），参数是结构里成千上万的具体数值（实、可训练调整）。可以把模型理解成『参数的容器与组织方式』。"},{"a":"参数量（规模）","b":"能力上限","diff":"参数量大能学更多，但不等于一定更聪明——还要数据够好、训练到位。规模是『容量』，能力是『用得好不好』。"},{"a":"数据质量","b":"数据量","diff":"质量差的数据量再大也可能有害；干净、多样、正确的高质量数据量，才真正提升模型水平。"}]},{"type":"mistakes","items":["以为『参数越多就一定越好』——参数量需要匹配数据量与算力，盲目堆参数不一定有效，反而成本爆炸。","以为『模型的知识是直接从数据抄来的』——模型学的是分布规律，不是存储原始数据（虽有少量记忆风险）。","以为『数据越多越好，质量无所谓』——脏数据、重复数据、错数据会教坏模型。","把『模型结构』和『参数值』混为一谈——结构造好后，真正的'学习'是调参数。","以为『只要模型大就什么都会』——数据覆盖不到的东西，模型就是不会，架构差异也有影响。"]},{"type":"deep","title":"深入一点：参数到底是个什么样的『数字』","beginner":["想象一张蜘蛛网，网上每条丝有一个数字表示‘这条丝重要/怎么影响下一个点’。","神经网络里，前一层每个神经元的输出，会乘以一个权重再传给下一层。这些权重就是参数。","模型‘学会’一件事，本质就是把这一大堆权重调到一个能很好完成任务的状态。"],"advanced":["一个参数通常指一个权重或偏置（bias）。训练即优化这些参数，使损失函数最小。","嵌入层、注意力矩阵、前馈网络的权重加起来构成参数量。LLM 的参数量主要集中在 Transformer 的注意力与前馈层。","‘参数高效微调’（如 LoRA）只训练一小部分新加的低秩参数来适配下游任务，从而大幅降低显存与成本——这就是为什么现在微调大模型很常见、成本可控。"]},{"type":"exercise","prompt":"两个模型参数量相同，但 A 用了更多更高质量的数学数据，B 用了大量杂乱重复的一般文本。哪个更可能在数学题上表现更好？","opts":["A，因为高质量、覆盖到数学的数据直接决定它懂多少数学","B，因为数据越多就一定越好","完全一样，因为参数量决定一切","无法判断，参数量完全无关"],"a":0,"explain":"模型的能力与训练数据的质量、覆盖度强相关。同样参数量下，喂了高质量数学数据、结构又合理的模型，在数学上通常更可靠。","jump":"sec5-step0","jumpLabel":"数据这一层"},{"type":"check","title":"结课检测：数据 / 模型 / 参数 你分得清吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"『模型的能力上限主要由结构决定』，这里的'结构'通常指什么？","opts":["训练数据的来源","神经网络有多少层、怎么连（模型架构）","电脑的内存大小","用户有没有会员"],"a":1,"explain":"结构即模型的架构设计（层数、连接方式等），决定了模型理论上能学到什么；数据决定内容，参数决定具体计算。","jump":"sec5-step1","jumpLabel":"模型结构这一层"},{"q":"训练时模型真正被反复修改的是什么？","opts":["训练数据本身","模型参数（权重/偏置）","显卡","网页样式"],"a":1,"explain":"训练就是用数据反复调整模型参数（权重），让输出接近期望；数据是输入，通常不因训练而改。","jump":"sec5-step2","jumpLabel":"参数这一层"},{"q":"『70B』指的是模型的什么？","opts":["训练数据条数","参数量（700 亿个参数）","网络延迟毫秒数","模型文件的行数"],"a":1,"explain":"B 代表 Billion（十亿），70B 即 700 亿个参数，是衡量模型规模（参数量）的常见指标。","jump":"sec5-step2","jumpLabel":"参数这一层"},{"q":"用三个词概括 AI 学习的『三件套』是？","opts":["CPU、内存、硬盘","数据、模型、参数","提问、回答、得分","字体、颜色、布局"],"a":1,"explain":"AI 学习的三件套是数据（教材）、模型（结构）、参数（旋钮），三者协作完成学习。","jump":"sec5-step3","jumpLabel":"三者协作这一层"}],"done":"三件套分清了：数据是教材、模型是结构、参数是旋钮。那训练到底怎样才能把这些旋钮越拧越准？下一课我们看训练的核心引擎——损失函数与梯度下降。","nextLesson":"l05-gradient-descent"},{"type":"connection","known":["模型是被训练出来的产物（上一课）"],"learned":["数据＝教材、模型＝结构、参数＝旋钮","参数量衡量模型规模，但不等于能力","数据质量与覆盖度直接影响模型水平","训练＝用数据反复调整参数"],"next":"旋钮往哪个方向拧、拧多少，靠什么判断？下一课《损失函数与梯度下降》：模型怎么知道自己错了，以及如何一步步『往下走』变聪明。","links":[{"href":"#/lesson/pl-train-infer","text":"复习《训练和使用模型》"},{"href":"#/lesson/l05-gradient-descent","text":"进入《损失函数与梯度下降》"}]}]},"pl-function-calling":{"id":"pl-function-calling","title":"Function Calling：让模型能『动手』","subtitle":"只会聊天的模型帮不了你太多。Function Calling 让模型学会‘调用你给的函数’——查天气、存取数据、操作外部系统。这是从‘会说’到‘会做’的关键一步。","category":"c06-llm-app","chapterTitle":"第四章 · 用起来","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["function-calling","tool-use","structured-output"],"prereqLessons":["pl-prompt"],"nextLesson":"l-agent","sections":[{"type":"opening","question":"你能让 ChatGPT 查天气、订机票、访问数据库吗？单靠聊天它做不到——但真正的产品里它做到了。秘密就是 Function Calling：让模型自己决定‘该不该调用某个函数’。","guess":"有人以为模型‘自己就能联网/操作一切’，或以为函数调用是魔法。","next":"这一课讲 Function Calling：把工具（函数）的说明告诉模型，模型需要时‘点名要调哪个、传什么参’，由你的程序真正执行并回传结果。看完你就懂所有 AI Agent 的底座能力。"},{"type":"why","before":"你想做一个真正‘能干事’的 AI 应用（查数据、调接口、改记录），但发现模型只会生成文本，无法直接操作系统。","problem":"不理解 Function Calling，你会把‘模型直接操作外部’想成理所当然，或把‘结构化输出’和‘函数调用’混为一谈，做出来的应用要么不可靠、要么全是伪需求。","need":"我们把这条链路讲透：工具描述 → 模型请求调用 → 程序执行 → 结果回喂。它是 Agent、工作流、一切会‘做事’的 AI 产品的地基。"},{"type":"oneline","text":"Function Calling = 你把一组‘函数（工具）的说明书’（名字、参数、作用）告诉模型；模型在回答时若需要，就输出一个结构化的‘调用请求’（调哪个函数、传什么参）；由你的程序真正执行并把结果回传给模型，模型再基于结果继续回答。"},{"type":"intuition","blocks":[{"k":"用餐厅点单来想","t":"菜单（工具说明）摆在桌上：有宫保鸡丁、酸辣汤。你问服务员‘有没有辣的’，服务员看了菜单说‘有，宫保鸡丁’。但真正做菜的是后厨，不是服务员。Function Calling 就是：模型是服务员（只会看菜单下单），后厨（你的程序）才真动手。"},{"k":"用给你配助理来想","t":"你有个助手（模型），但没配工具（函数）。你问他今天天气，他只能瞎编。给他配了‘查天气 API’这个工具并告诉他怎么用，他就能‘让我帮你查——把城市名传进去’，由真正的天气服务返回结果，他再念给你听。模型没联网，是‘调用工具’替他联网。"},{"k":"一句话记住","t":"模型不执行函数，它只‘决定要调哪个参数是多少’；你的程序确认执行，把结果喂回去。分工：模型负责决策，程序负责真实世界。"}]},{"type":"how","intro":"一次 Function Call 的完整闭环，五步。","steps":[{"in":"① 注册工具：告诉模型有哪些函数可用","process":"在 API 请求里传一份函数清单 JSON Schema：函数名、参数、说明。模型‘看到’这些说明，但看不到你的实现代码。","out":"模型知道有哪些‘菜单’可选"},{"in":"② 模型判断：本次回答要不要调工具","process":"用户提问后，模型判断是否需要某个工具才能更好地回答；需要则不会直接给最终答案，而是输出一个 function_call 请求。","out":"模型返回‘我建议调用 `get_weather`, 参数 {city: 北京}’"},{"in":"③ 你的程序执行真正的函数","process":"你的代码收到这个请求，去调用真实的天气 API（或数据库、业务接口），拿到实际结果。这一步是‘后厨在做菜’。","out":"真数据结果（如 26°C、晴）"},{"in":"④ 把结果回喂给模型","process":"把函数执行的输出（tool message）作为上下文返回给模型，并告诉它‘这是工具返回的结果’。","out":"模型‘看到’了真数据"},{"in":"⑤ 模型基于结果给出最终回答","process":"模型综合用户问题与工具结果，生成面向用户的最终答案。一次工具调用就完成了。","out":"‘北京今天 26°C，晴’——准确且真实"}]},{"type":"realworld","items":[{"name":"为什么强调‘由程序执行’","note":"模型本身不联网、不读写数据库，它输出的是‘调用意图’；真正执行必须在你可控的代码里做，这也是安全与权限的边界所在。"},{"name":"与结构化输出的关系","note":"Function Calling 依赖模型输出结构化 JSON（函数名+参数）。可以和‘JSON 模式’配合，让输出更规范可解析。"},{"name":"多个工具并行调用","note":"现代 API 允许模型一次请求同时调用多个函数（如同时查天气和订票），再由程序逐个执行、统一回喂。"},{"name":"Agent 的地基","note":"下一课的 Agent 本质上就是：模型 + 一组函数（工具）+ 一个循环（判断→调用→回看 → 再判断）。Function Calling 就是那个‘调用’原语。"}]},{"type":"compare","pairs":[{"a":"文本回答","b":"Function Call","diff":"常规回答只输出文字；function call 输出‘要调哪个函数及参数’的结构化指令，由程序去执行。"},{"a":"Function Calling","b":"你们自己写 if-else","diff":"if-else 是硬编码每个用户问法；Function Calling 让模型动态判断何时调哪个工具，覆盖自然语言里无穷的问法。"},{"a":"工具说明","b":"工具实现","diff":"给模型看的是说明书（名字/参数/作用，JSON Schema）；真实现跑在你侧，模型永远看不到也不该看到。"},{"a":"单轮调用","b":"多轮循环（Agent）","diff":"单次调用一次往返；Agent 会在‘调用→回看结果→再调用’之间循环多次，直到完成复杂任务。"}]},{"type":"mistakes","items":["以为模型‘自己会执行函数’——它只输出调用请求，执行权在你手里。","工具说明写得含糊——模型就传错参数。说明书越清楚（参数必填、类型、示例），调用越准。","把模型当成能直接读你数据库的存在——必须把查询做成工具并控好权限。","忽略安全边界——工具要校验入参、加权限，别让模型拿着能删库的工具乱来。","以为 Function Calling 就是‘发给一条消息’——它是‘决策→执行→回喂’的闭环，要你写执行与回填逻辑。"]},{"type":"deep","title":"深入一点：怎么把工具定义得让模型调得准","beginner":["对每个函数：写清函数名、参数列表（类型、是否必填）、一句话说明‘这个函数做什么、什么时候该调’。","用真实例子给参数取值作示范，能显著降低模型传错参的概率。","职责单一：一个函数只干一件事，便于模型准确调用。"],"advanced":["工具即接口契约：把函数写成 JSON Schema（OpenAI 的 tools 参数 / 各家 tool-use 协议一致）。类型、枚举、最大长度都对模型选择有价值。","并行与依赖：模型可一次输出多个 tool_calls；若存在依赖（第二步要用第一步结果）需多轮循环编排。","安全：白名单调用、输入校验、次数/预算限制、敏感操作二次确认。模型可能被提示注入诱导调用危险工具，要做好防护。","回退与容错：工具调用失败要能告诉模型‘调用失败了’，让它换参数重试或走人工，形成健壮的 Agent 循环。"]},{"type":"exercise","prompt":"你问 AI 助手‘杭州现在天气如何’，它说‘让我调一下天气服务’。实际上谁在执行这个调用？","opts":["AI 模型自己联网","你的程序收到模型的 function_call 请求，去调用真实天气 API 并回填结果","浏览器自动打开天气预报网站","没人执行，它直接编一个"],"a":1,"explain":"模型只输出‘建议调用 get_weather(city=杭州)’；真正访问天气 API 并回传结果的是你的程序，这就是 Function Calling 的分工。","jump":"sec5-step2","jumpLabel":"程序执行真正的函数这一步"},{"type":"check","title":"结课检测：Function Calling 你明白了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"Function Calling 中，模型主要负责？","opts":["真正执行函数、访问数据库","判断该调哪个函数并输出结构化的调用请求（函数名+参数）","编译代码","管理服务器"],"a":1,"explain":"模型承担决策角色：判断是否需要工具、输出‘调哪个、传什么参’；执行由你的程序完成。","jump":"sec5-step1","jumpLabel":"模型判断这一步"},{"q":"给模型看的‘函数清单’本质是什么？","opts":["函数的真实实现代码","函数的说明书（名字、参数、作用，通常是 JSON Schema）","服务器密码","数据库密码"],"a":1,"explain":"传给模型的是一份工具说明（JSON Schema），模型据此知道有哪些函数、怎么调；绝不给实现代码。","jump":"sec5-step0","jumpLabel":"注册工具这一步"},{"q":"一次完成的 Function Call 闭环顺序是？","opts":["执行→描述→决定→回喂","注册工具→模型决定调用→程序执行→结果回喂→模型回答","直接回答→不调用","回喂→执行→注册"],"a":1,"explain":"标准链路：注册工具 → 模型输出调用请求 → 程序执行真函数 → 结果回喂 → 模型给出最终答案。","jump":"sec5-step4","jumpLabel":"模型给出最终回答这一步"},{"q":"以下哪项是使用 Function Calling 时最重要的安全考量？","opts":["给工具强输入校验与权限控制，防止模型/注入调用危险操作","函数名越长越安全","禁止一切函数","只能让模型自己执行"],"a":0,"explain":"模型可能被诱导调用危险工具，所以要在执行侧做好入参校验、权限与配额控制、敏感操作确认。","jump":"sec7","jumpLabel":"安全段"}],"done":"模型学会了‘动手’——但它还不会自己决定‘一直做到完’。下一课把这些串成自动循环：《Agent 智能体》，让 AI 自己规划、调用、观察、再行动。","nextLesson":"l-agent"},{"type":"connection","known":["Prompt 四件套与上下文工程（上一课）","模型只能预测文本，不能直接操作外部"],"learned":["Function Calling = 模型输出调用请求，程序执行","工具说明（JSON Schema）决定调用质量","安全边界：校验、权限、配额","它是 Agent / 工作流的地基"],"next":"会调用了还不够，Agent 要‘自己决定一直做下去’。下一课《Agent 智能体》：目标→推理→调用→观察→再行动 的自动循环。","links":[{"href":"#/lesson/l-agent","text":"进入《Agent 智能体》"},{"href":"#/lesson/pl-prompt","text":"复习《Prompt 与上下文》"}]}]},"pl-prompt":{"id":"pl-prompt","title":"Prompt 与上下文：怎么和模型说清楚","subtitle":"同样的模型，有人问出平庸答案，有人问出惊艳答案——差别往往在 Prompt。这一课给你一套可复用的‘说清楚’框架。","category":"c05-llm","chapterTitle":"第四章 · 用起来","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["prompt","prompt-engineering","context"],"prereqLessons":["l12-context-window"],"nextLesson":"l-rag","sections":[{"type":"opening","question":"同样让 AI 写一份周报，有人得到一团废料，有人得到直接能用的。差别不在模型，而在你‘怎么说’。Prompt（提示词）到底有没有套路？","guess":"有人以为 Prompt 就是‘礼貌地多问几次’，或者要背一堆玄学咒语。","next":"这一课把 Prompt Engineering 的底层逻辑讲清楚：模型只会按你给的上下文做预测，所以‘把话说清楚、给足边界、给出期望格式’就是全部秘诀。再给你一套 Copy 就能用的模板。"},{"type":"why","before":"你用 AI 写东西、改代码、做总结，但经常要来回纠正它，效率很低。你想知道怎么一次就问出好结果。","problem":"把 Prompt 当玄学、乱堆关键词，或指望 AI‘读懂你的潜台词’，是常见的低效来源。你缺的是一套可复用的思考框架。","need":"Prompt 的本质是‘上下文工程’：你往窗口里放什么，它就拿什么推理。我给你角色-目标-约束-输出格式四件套，以及常见陷阱，让你一次问清。"},{"type":"oneline","text":"Prompt = 给模型一份清晰的‘工作说明书’：你是谁（角色）、要完成什么（目标）、边界是什么（约束/不要做什么）、交给我什么形状的结果（输出格式）。放进去的信息越清楚，拿出来的结果越可用。"},{"type":"intuition","blocks":[{"k":"用交代下属来想","t":"你给新下属派活：只说‘帮我把方案写了’＝他会一头雾水写出一堆没用的。说清楚‘背景、目标、条件、格式、例子’＝他才能一次做对。AI 就是你手下那个非常聪明但没有读心术的下属。"},{"k":"用下订单来想","t":"Prompt 像下外卖订单：你不写辣度、分量、备注，对方只能按默认做。写清楚‘不要辣、加个备注、送到了敲门’——结果才符合预期。"},{"k":"一句话记住","t":"给模型看的每句话都会影响它预测的走向。说得越明确、越有边界，输出越可控。"}]},{"type":"how","intro":"给出四件套框架，并用一个例子贯穿。","steps":[{"in":"① 角色 Role：告诉它‘你是谁、用什么视角’","process":"先设定身份与视角，例如‘你是一名有 10 年经验的数据库 DBA’‘你是小学老师’等。角色影响语气与知识取向。","out":"模型切换到对应语气与视角"},{"in":"② 目标 Task：明确要完成什么","process":"把任务说成一个清晰动词：总结、改写、翻译、设计、排查、写代码。一个 prompt 尽量只聚焦一个任务。","out":"模型知道该交付什么"},{"in":"③ 约束 Constraint：给出边界与不要做的事","process":"字数范围、语气、不要说教、不要编造、基于给定资料回答、保密等。边界越清楚，越不容易跑偏。","out":"输出被限制在期望范围"},{"in":"④ 输出格式 Format + 示例","process":"告诉它要什么形态：列表？表格？代码？JSON？给一个示例更好。格式明确后，结果可直接用、可直接解析。","out":"拿到结构化的、可用的输出"}]},{"type":"realworld","items":[{"name":"写周报的例子","note":"把四件套用上：角色‘你是我的助理’＋目标‘把本周工作整理成周报’＋约束‘不超过 8 条、语气正式’＋格式‘分 已完成/进行中/风险 三栏’——结果一步到位。"},{"name":"改代码的例子","note":"发报错原文 + 相关代码 + 你的判断（哪一层出的问题）＋要求‘说明原因并给出修复’，比只丢一个报错字串的高效得多。"},{"name":"系统提示词（System Prompt）","note":"在应用里，角色/约束常做成系统提示，每次请求都放在窗口最前，是产品级的 Prompt 管理。"},{"name":"Few-shot（给示例）","note":"在 Prompt 里附 1~2 个问答例子，模型照葫芦画瓢，输出更规范。这是提升稳定性的常用技巧。"}]},{"type":"compare","pairs":[{"a":"笼统提问","b":"四件套提问","diff":"笼统：信息少、边界模糊、结果随机；四件套：角色+目标+约束+格式，一次成功率大幅提升。"},{"a":"单向输出","b":"多轮追问","diff":"复杂任务一次难成，可把它拆成多轮：先生成骨架，再让它细化某部分。Prompt 也可以是流程。"},{"a":"Prompt","b":"微调","diff":"Prompt 不改模型，只改输入让它更好发挥；微调是改模型参数适配任务。能靠 Prompt 解决的先用 Prompt，成本低得多。"},{"a":"Prompt","b":"RAG","diff":"Prompt 靠话术组织上下文；RAG 靠检索把外部资料塞进上下文。二者常配合：先 RAG 取资料，再 Prompt 组织。"}]},{"type":"mistakes","items":["以为 Prompt 越华丽越有效——关键是信息密度与明确边界，不是堆砌形容词。","只给一句话任务，不给背景、约束、格式——模型只能自由发挥。","一次塞多个复杂任务——拆开更稳。","让模型‘自由发挥’却怪它跑偏——边界没给够。","忽略示例的价值——给一个例子常比解释十句更有效。"]},{"type":"deep","title":"深入一点：为什么 Prompt 会‘无中生有’与‘上下文工程’思想","beginner":["模型本质是在预测‘接下去最合理的文本’。Prompt 提供了‘上下文’，输出是被它引导的续写。","所以 Prompt 写得像什么风格，输出就容易是什么风格——这就是为什么示例（few-shot）很有效。","想知道模型为什么跑偏，先检查你给它的上下文是否误导了它。"],"advanced":["上下文工程（Context Engineering）：把产品要的上下文——系统提示、工具描述、检索片段、会话历史——按重要性排序并塞进有限窗口，是当前 AI 工程重头戏。","结构化 Prompt、Chain-of-Thought 引导、工具调用描述、输出 Schema 约束（如 JSON mode），都是控制生成的手段。","评估：好的 Prompt 应该‘可复现’——同一输入多次得到一致且合格的输出。用测试集回归验证 Prompt 改动，别靠手感。","警惕注入（Prompt Injection）：外部带来的文本可能被当作指令执行，产品要在边界上做隔离与校验。"]},{"type":"exercise","prompt":"你要让 AI 帮你把一段长文压缩成 3 条要点。下面哪个 Prompt 最可能一步到位？","opts":["‘帮我看看这段文字。’","‘你是我的助理。请把下面这段文字压缩成 3 条要点，每条不超过 30 字，直接给要点列表，不要其他说明。原文：…’","‘这段很厉害，你懂吧？’","‘写一篇更长的小说。’"],"a":1,"explain":"选项 B 给出了角色、目标、数量、长度、格式与材料，边界清晰，一次成功率最高。","jump":"sec5-step0","jumpLabel":"四件套框架这一段"},{"type":"check","title":"结课检测：Prompt 四件套你上手了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"Prompt 四件套通常指？","opts":["颜色、字体、布局、图标","角色、目标、约束、输出格式","开头、中段、结尾、落款","输入、输出、缓存、日志"],"a":1,"explain":"四件套：设定角色、说清目标、给边界约束、规定输出格式。","jump":"sec5-step0","jumpLabel":"角色这一步"},{"q":"为什么在 Prompt 里附 1~2 个示例（Few-shot）常能提升效果？","opts":["示例会让模型更听话","模型本质是预测续写，示例给它‘照这个风格来’的强引导","示例能扩容上下文","没有任何作用"],"a":1,"explain":"模型在预测‘接下来最合理的文本’，示例直接示范了期望的输出形态，引导作用很强。","jump":"sec6","jumpLabel":"Few-shot 这个现实话题"},{"q":"模型‘一本正经胡说八道’（幻觉）提示我们对 Prompt 该有哪种意识？","opts":["模型在预测续写而非核实事实，重要内容要靠资料（RAG）与检查","多夸它几句就不会胡说","与 Prompt 无关","改用更大的字号"],"a":0,"explain":"模型是预测性生成，不保证事实正确。关键信息要给它可靠资料并用 RAG，再要求它基于资料作答。","jump":"sec7","jumpLabel":"上下文工程与评估这一段"},{"q":"能靠 Prompt 解决的问题，为什么一般优先于微调？","opts":["因为 prompt 零成本、快、不改变模型","因为微调更慢但效果差","两者没有任何关系","因为 prompt 不可用"],"a":0,"explain":"Prompt 只改输入、不改模型，成本低、迭代快；微调要训练、成本高。能不改模型就优先用 Prompt。","jump":"sec7","jumpLabel":"上下文工程这一段"}],"done":"你会‘说清楚’了。但模型会瞎编——怎么让它基于你的真实资料回答？下一课《RAG》：让模型先查资料、再回答。","nextLesson":"l-rag"},{"type":"connection","known":["窗口里装什么是用户决定的（上一课）"],"learned":["Prompt = 上下文工程，四件套框架","Few-shot、系统提示、多轮拆解等技巧","幻觉的根源与用 RAG/检查对齐","Prompt 优先于微调的原因"],"next":"如果模型只会编，怎么让它‘基于你的资料’回答？下一课《RAG》揭晓把外部资料接进窗口的经典方案。","links":[{"href":"#/lesson/l12-context-window","text":"复习《上下文窗口与推理》"},{"href":"#/lesson/l-rag","text":"进入《RAG》"}]}]},"pl-train-infer":{"id":"pl-train-infer","title":"训练和使用模型有什么区别","subtitle":"模型的『上学阶段（训练）』和『上班阶段（使用/推理）』是完全不同的两回事。搞懂这个，你就不会再困惑『为什么 ChatGPT 每次回答还不一样』『为什么模型会一本正经胡说八道』。","category":"c01-ai-world","chapterTitle":"第一章 · 认识 AI","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["ai-ml-dl","training","inference"],"prereqLessons":["l01-ai-vs-ml-dl"],"nextLesson":"pl-data","sections":[{"type":"opening","question":"你打开 ChatGPT 问了个问题，它几秒内就回了你。但你可能没想过：它『学会说话』的那个过程（训练）和你使用它的过程（推理），根本不在一个时间、也不在一个量级。它们到底有什么不同？","guess":"有人觉得模型训练和使用是一回事，区别只在于快慢。","next":"这一课我们讲清训练（Training）与推理（Inference/使用）的本质区别：一个是在海量数据上『慢慢写作业、改答案』，另一个是『拿到考卷直接作答』。这是理解成本、速度、以及为什么大模型很贵的钥匙。"},{"type":"why","before":"你想知道：为什么训练一个 GPT 要花几百万美元、几千张显卡好几个月，而用的时候点一下就出结果？为什么同样的模型，每次回答会不一样？","problem":"如果不区分训练与推理，你会把『模型的成本』『模型的能力上限』和『一次回答的成本』混为一谈。你会奇怪：既然训练这么贵，为什么我用起来这么快？也会疑惑：模型到底是『提前背好了答案』还是『现场算出来的』？","need":"把训练 vs 推理分开，你就知道：模型的能力是训练阶段敲定的（一次性的），而每一次回答是推理阶段现算的（每次都要烧电）。所有关于『贵不贵、快不快、准不准』的问题，都要先问一句：你指的是训练还是推理。"},{"type":"oneline","text":"训练（Training）＝模型在海量数据上『写作业、对答案、改参数』的一次性重活，几个月、贵、改的是模型的『记忆与能力』；推理（Inference / 使用）＝训练完的模型每来一个输入就『现场作答』，每次都要算一遍，快、便宜但也不是免费。"},{"type":"intuition","blocks":[{"k":"用学生来想","t":"训练＝学生寒窗苦读，读了大量课本和例题，把知识『内化』成自己的答题能力。这个过程长、累、费钱（教材、学费）。推理＝拿到考卷直接作答，靠之前内化的能力秒写答案。学生毕业后的『能力』是训练决定的，每次考试只是把能力'调出来'用。"},{"k":"用厨师来想","t":"训练＝大厨经过多年练习，练出一身手艺（参数）。推理＝客人点菜，大厨现场动手做一盘。手艺是多年前'训练'出来的，但每一道菜都是现场'推理'做的——所以每次都要时间，且水平取决于那身手艺。"},{"k":"一句话记住","t":"训练：改参数、时间长、一次性、贵；推理：用参数、时间短、每次都算、有成本。一切 LLM 的『贵』都主要来自训练，但每一次对话的『算力』来自推理。"}]},{"type":"how","intro":"把一次训练和一次推理分别拆开，对比每一步。","steps":[{"in":"训练前：准备『教材』（数据和算力）","process":"采集海量文本/图片/代码作为训练数据，准备好大量 GPU/TPU 算力集群。数据要清洗、去重、组织成训练样本。","out":"一批质量过关的训练数据 + 一台算力集群"},{"in":"训练中：模型『写作业-对答案-改参数』反复迭代","process":"把数据分批喂给模型做预测，计算预测和真实答案的差距（Loss），再用反向传播一层层微调参数。重复亿万次，直到误差低到可接受。","out":"参数被反复调整，模型逐渐学会了规律"},{"in":"训练完：得到一个『固定』的模型文件","process":"训练结束后的参数被冻结，变成一个可以被调用、分发、部署的模型文件（权重）。此时能力已定型。","out":"一份可部署的模型权重（几十到上千 GB）"},{"in":"推理中：来一个输入，模型现场算一次","process":"你把问题给模型，模型把它编码成数字，经过神经网络前向计算一遍，输出答案。每次回答都是完整算一次，不改动任何参数。","out":"得到一次『当下』的回答，参数保持不变"},{"in":"推理的成本与速度","process":"每次推理都要占用显卡做一次前向计算，所以有延迟和成本。这也是为什么在线大模型按『Token 用量』收费。","out":"按用量计费、有延迟、有成本"}]},{"type":"realworld","items":[{"name":"ChatGPT 的回答『每次不完全一样』","note":"推理阶段有随机性（采样时温度大于 0），同样的问题每次选词的随机分布不同，所以回答会有细微差异。这不是『模型在变』，而是推理时的随机采样。"},{"name":"『训练一次要花几百万美元』","note":"指的就是训练阶段：几千张高端 GPU 连跑数周，电费、机房、人力都计入。GPT-4 级别的训练成本以千万美元计。"},{"name":"『按 Token 计费』","note":"你为每次推理付费：模型每处理一个 token（约一个字/词的一部分）都要做一次计算，供应商按用量收费，覆盖推理的算力成本。"},{"name":"『微调（Fine-tuning）』","note":"在已有模型基础上做一次『小规模训练』：拿少量领域数据再微调参数，让模型更适合某一任务。它介于『纯训练』和『纯推理』之间，本质仍是一次训练。"},{"name":"模型会『一本正经胡说八道』","note":"推理时模型只是在『预测下一串合理的词』，它并不理解对错，也不自知。能力在训练中定型，但每次回答都是预测，可能自信地编造。这就是幻觉（Hallucination）。"}]},{"type":"compare","pairs":[{"a":"训练 Training","b":"推理 Inference","diff":"训练改参数、时间长、一次性、成本高；推理用参数、时间短、每次都算、按量计费。"},{"a":"模型能力","b":"一次回答质量","diff":"能力上限在训练时定型；但单次回答可能受采样随机性影响，同一能力下每次具体答案可不同。"},{"a":"训练算力","b":"推理算力","diff":"训练需要大规模并行、一次跑很久；推理每次只需一次前向计算，量小但调用次数巨大。"},{"a":"预训练","b":"微调 Fine-tuning","diff":"预训练是在海量通用数据上从零或从基础训练；微调是在预训练权重上用少量领域数据再小规模训练，快速适配某一任务。"}]},{"type":"mistakes","items":["以为『每回答一次，模型就变聪明一点』——不，训练阶段才改参数，推理回答是只读调用。","以为『训练的成本 = 我用它的成本』——错，训练是一次性的昂贵投入，推理按量计费。","以为『模型每次回答不同＝模型在更新』——多数差异来自推理时的随机采样，不是参数在变。","以为『微调 = 推理』——微调本质是小规模训练（改参数），只是数据量小、时间短。","以为『模型能力不足时，靠多问几次就能提升』——能力在训练定型，用量不能改变能力上限，只能换策略或换模型。"]},{"type":"deep","title":"深入一点：参数、权重与『训练到底在改什么』","beginner":["一个神经网络由大量『神经连接』组成，每条连接有一个数字叫权重（参数）。模型的『知识』就存在这些数字的分布里。","训练就是反复调整这几亿甚至上千亿个数字，让它们最终能很好地完成预测任务。","'预训练'让模型具备通用语言能力；'微调'在此基础上小幅调整让它更听话或更专业。"],"advanced":["训练就是最优化：目标函数（Loss）对每个参数求梯度，用梯度下降更新，让 Loss 越来越小。这个『更新参数』的循环在训练阶段发生，推理阶段参数冻结不动。","推理只有『前向传播』：输入 → 逐层计算 → 输出，不更新任何参数。这也是为什么推理远快于训练——少了反向传播这一步。","工程视角：训练需要反向传播、梯度累积、学习率调度、数千张卡并行；推理需要 KV 缓存、量化、批处理、KV-cache 复用来降低延迟与成本。同一模型，训练与部署是两套完全不同的工程问题。"]},{"type":"exercise","prompt":"有人问你：『为什么我让同一个 AI 写一篇关于猫的文章，两次得到的开头不一样？』最合理的解释是？","opts":["模型在这期间偷偷重新训练了","推理阶段有随机采样，同样的输入可能得到不同的输出","因为我没联网","因为模型是我提问时才被造出来的"],"a":1,"explain":"训练阶段已定型，参数不变；两次回答的差异来自推理采样时的随机性（温度/采样），属于正常现象。","jump":"sec5-step3","jumpLabel":"推理中：来一个输入现场算一次"},{"type":"check","title":"结课检测：训练 vs 推理你分得清吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"训练阶段，模型在做什么？","opts":["逐层前向计算并给出答案（不改参数）","反复预测-对答案-调整参数，直到误差降低","什么都不做，只是被部署","只在用户提问时才运行"],"a":1,"explain":"训练的核心循环是『预测 → 算 Loss → 反向传播更新参数』，一直重复到误差可接受。推理阶段才不再改参数。","jump":"sec5-step1","jumpLabel":"训练中这一层"},{"q":"『按 Token 用量收费』，付的是哪个阶段的成本？","opts":["训练成本","每次使用的推理成本","买电脑的钱","数据采集成本"],"a":1,"explain":"线上大模型按你每次提问消耗的 token 计费，覆盖的是推理阶段每次前向计算的算力成本，不是一次性训练费。","jump":"sec5-step4","jumpLabel":"推理的成本与速度"},{"q":"微调（Fine-tuning）本质上更接近哪件事？","opts":["纯推理","一次小规模的训练","只是改提示词","重新从零预训练"],"a":1,"explain":"微调是在预训练权重上用少量数据再调整参数（反向传播），本质是一次数额小、数据少的训练。","jump":"sec6","jumpLabel":"微调这个现实案例"},{"q":"模型的『能力上限』主要由什么决定？","opts":["每次提问时的随机采样","训练阶段（数据、架构、规模）","用户的打字速度","网络的带宽"],"a":1,"explain":"能力在训练阶段定型；推理只是把已定型的参数拿出来做预测，不能提升能力上限。","jump":"sec5-step2","jumpLabel":"训练完这一层"}],"done":"现在你分清了『学（训练）』和『用（推理）』。可模型到底在拿什么『学』、在『学』什么？下一课我们把 AI 的三大原料——数据、模型、参数——逐个说透。","nextLesson":"pl-data"},{"type":"connection","known":["AI ⊃ ML ⊃ DL 的包含链（上一课）","模型是被训练出来的产物"],"learned":["训练 vs 推理的本质区别（改参数 vs 用参数）","训练一次性昂贵、推理按量计费","为什么同一模型每次回答可能不同（采样随机性）","微调 = 小规模训练；幻觉来自推理时预测而非自知"],"next":"训练的『原料』是什么？下一课《数据、模型与参数》告诉你 AI 学习的三要素，以及为什么『数据』往往比模型大小更关键。","links":[{"href":"#/lesson/l00-ai-world","text":"复习 AI 世界总图"},{"href":"#/lesson/l05-gradient-descent","text":"预看《损失函数与梯度下降》"}]}]},"v01-web":{"id":"v01-web","title":"一个 Web 产品是怎么跑起来的","subtitle":"你在浏览器里敲回车到内容出现，中间发生了什么？把这条链路看懂，你才谈得上『改对地方』。","course":"vibe","courseNo":"01","level":"base","estTime":"15-25 分钟","difficulty":1,"concepts":[],"prereqLessons":[],"nextLesson":"v02-git","sections":[{"type":"opening","question":"你每天打开网页、用 App、点外卖、刷视频——但有没有想过，你在浏览器地址栏输入一串字母并按下回车，到底是哪台机器、用哪段程序、按什么顺序，把你要的内容送到你面前的？","guess":"很多人会回答「就是电脑把网站打开了呀」。","next":"这节课我们不写代码，只把『一个 Web 产品』从头到尾拆开：前端、后端、数据库、服务器、浏览器、网络各是什么，数据是怎么一层层流动的，以及每一层出错时你该怀疑谁。学完你就能对着一屏『转圈』或一条报错，说出它大概死在哪个环节。"},{"type":"why","before":"你想用 AI 辅助做一个自己的小产品（一个网页、一个小工具、一个小网站）。AI 很会写代码，但你写完点开经常『跑不起来』或『一片空白』，你不知道该往哪看。","problem":"问题不在 AI 写的代码——而在于你对『这段代码在什么环境里跑、和谁通信』没有概念。你分不清『报错是我的 HTML 写错了』『还是服务器没启动』『还是数据库没连上』『还是网络被墙了』。于是只能把同样的问题反复丢给 AI，越问越乱。","need":"所以第一课先不碰一行代码，而是先建立『一台 Web 产品从上到下有哪些层、每层做什么』的骨架。当你把『前端 / 后端 / 数据库 / 服务器 / 浏览器 / 网络协议』这条链装进脑子，AI 给的报错就不再是天书，而是能对号入座的线索。"},{"type":"oneline","text":"一个 Web 产品 = 浏览器（前端，负责看得见摸得着的界面）+ 服务器上的程序（后端，负责处理逻辑和读写数据）+ 数据库（负责长期存数据），它们之间靠『网络请求』（HTTP）搬来搬去；而这一切最终都跑在『操作系统 + CPU/内存/磁盘』这台物理机器上。"},{"type":"visual","kind":"request-flow","title":"互动实验：点一次请求，看它走完整条路","hint":"点击『发送请求』，看一次『用户敲回车』的动作如何依次经过浏览器 → DNS 解析 → 网络 → 服务器 → 后端程序 → 数据库 → 再原路返回。每亮起一格就说明数据到了哪一层。"},{"type":"intuition","blocks":[{"k":"用点外卖来想","t":"前端＝你看得到的『点单 App 界面』；后端＝『餐厅后厨，负责接单、炒菜、出餐』；数据库＝『冷库里长期保存的食材和菜谱』；服务器＝『餐厅所在的整栋楼，有水电（CPU/内存/磁盘）』；浏览器就是那个帮你点单、再把菜端到你面前的『外卖小哥』。你看到的每一道菜，都是后厨＋冷库＋外卖小哥协作的结果。"},{"k":"用写信来想","t":"你在浏览器输入网址，就像写一封信：『地址』（域名）要翻译成具体的『门牌号 + 邮编』（IP + 端口），信通过『邮政网络』（网络/IP）送出去，邮局先查收信人住在哪（DNS 解析），送到后对方拆信、处理、再回信。回信能不能到，取决于信中地址写没写对。"},{"k":"一句话记住分层","t":"从上到下：浏览器（前端）→ 网络（DNS/IP/HTTP）→ 服务器 → 后端程序 → 数据库。数据请求沿这条链往下，响应再原路往上。出错时按这条链一层层排查，永远不要跳着乱试。"}]},{"type":"how","intro":"把『输入网址到页面出现』拆成一条 7 步因果链。每一步都回答『数据此刻在哪、谁在处理、为什么能做下一步』。","steps":[{"in":"① 你输入网址，按下回车","process":"浏览器得到一串人类好记的名字，比如 ai-learn.example.com。但网络本身不认名字，它只认数字地址（IP：像 203.0.113.7）。所以第一步要『翻译』。","out":"浏览器准备发起一次『网络请求』"},{"in":"② DNS 解析：把域名翻译成 IP","process":"浏览器向 DNS（域名系统）询问：ai-learn.example.com 对应哪个 IP？DNS 就像电话簿，查到后把『数字地址』告诉浏览器。没有这一步，浏览器不知道该把信寄到哪台机器。","out":"得到了服务器的 IP 地址 + 端口（默认 80/443）"},{"in":"③ 建立连接 + 发送 HTTP 请求","process":"浏览器通过 TCP（可靠的传输协议）连上服务器，然后发送一个『HTTP 请求』：里面写着『我要 GET 这个页面』，还带着浏览器自己是谁（User-Agent / Cookie）等信息。","out":"请求沿着网络，送到那台服务器的指定端口"},{"in":"④ 服务器接收并把请求交给后端程序","process":"这台机器上正跑着一个『服务器进程』（如 Nginx / Node / Python）。它把请求转交给对应后端程序；后端程序执行你自己的业务逻辑：查一查、算一算。","out":"后端程序开始处理：可能要读数据库"},{"in":"⑤ 后端读写数据库","process":"需要持久数据的，后端会去数据库查询或写入。数据库把结果（比如『这个用户的名字』）返回给后端。注意：数据库不住在浏览器里，它住在服务器那台机器上。","out":"后端拿到数据，拼出一份『响应』"},{"in":"⑥ 后端返回 HTTP 响应","process":"后端把生成的 HTML / JSON / 图片，打包成一条『HTTP 响应』发回去，附带状态码（200 成功 / 404 找不到 / 500 服务器出错）与响应头。","out":"响应沿着网络原路回到浏览器"},{"in":"⑦ 浏览器解析并渲染","process":"浏览器收到 HTML，逐行解析：先搭出页面结构，再拉取其中的 CSS/JS/图片等资源，最后把内容画到屏幕上。你这才『看到』了页面。","out":"页面出现在你眼前（一次完整的前后端往返）"}]},{"type":"realworld","items":[{"name":"你平时的网页 = 前端静态页","note":"很多『首页』其实只是浏览器直接渲染的一堆 HTML/CSS/JS 文件，可能根本没有后端。它依然需要前面的 ①②③⑦ 几步，但没有 ④⑤⑥。知道这一点，你排查为何『页面能开但功能没反应』时就能猜到问题多半在后端那段。."},{"name":"登录注册 = 必须有后端 + 数据库","note":"『注册新账号』必须把密码/信息写进数据库，所以必然经过完整的 ①→⑦。前端只是收集输入，真正的校验和存储都在后端 + 数据库。这是『看代码时』判断某功能是否需要后端的标尺。"},{"name":"动态内容（推荐、订单、消息）= 后端在返回数据","note":"你刷到的『为你推荐』是后端程序实时查库、算好、再以 JSON 返回给前端渲染的。这类功能换任何界面（网页/App/小程序）后端代码都基本相同——这也是为什么『前后端分离』这么常见。"},{"name":"云服务器 / 租一台机器","note":"你的产品真正上线后，就『住』在一台云服务器（如腾讯云、阿里云的 ECS）上，这台机器有操作系统、CPU、内存、磁盘，常年开机。你的前端文件、后端程序、数据库都装/跑在这上面。"}]},{"type":"compare","pairs":[{"a":"前端 Frontend","b":"后端 Backend","diff":"前端＝用户看到的界面（运行在浏览器/手机里，负责渲染和交互）；后端＝用户看不到、运行在服务器上的程序（负责业务逻辑、鉴权、读写数据库）。前端决定『长什么样、能不能点』，后端决定『数据对不对、安不安全』。"},{"a":"接口 API","b":"直接操作数据库","diff":"后端对外提供的是『接口（API）』——一个约定好的请求地址与返回格式；前端只调用接口，永远不直接连数据库。这样可以隔离权限、便于维护。这也是产品安全的第一道墙。"},{"a":"本地 localhost","b":"线上服务器","diff":"你在自己电脑上跑的前后端叫『本地环境』，地址常是 localhost:3000；部署上线后跑在云服务器上，是公网地址。很多『本地正常、线上挂』的问题，都源于两套环境不完全一样（如数据库没迁移、环境变量没配）。"},{"a":"TCP（可靠）","b":"UDP（快速但不可靠）","diff":"TCP 会确认每份数据都到达（网页、文件用），UDP 不确认、丢了就丢（实时音视频、游戏用）。Web 的 HTTP 默认走 TCP，所以网络差时表现为『加载慢/卡』而不是『内容错乱』。"}]},{"type":"mistakes","items":["以为『网页能打开 = 后端没问题』——错，很多页面是纯前端静态页，后端可能根本没启动。","报错时随手把错误原样丢给 AI，而不说清『发生在哪个层』——AI 只能瞎猜。正确做法是先定位：报错来自浏览器控制台、后端终端、还是数据库连接？","以为『改完代码点刷新就行』——前端改了刷新即可，后端改了常常要重启服务才能生效；数据库结构改了还要迁移。不知道该不该重启，等于不知道该层是否生效。","把 IP、域名、端口混为一谈——域名给人记，IP 给网络认，端口标识这台机器上『哪个程序在服务』。三者不同。","以为 AI 写的代码『放对文件夹就能跑』——代码必须在『正确的环境』（装好依赖、正确版本、正确目录、可执行的权限）里才能运行。环境对不上，代码再对也是白搭（这正是第 7 课上线的核心矛盾）。"]},{"type":"deep","title":"深入一点：把『机器、程序、运行方式』讲透","beginner":["这台电脑/服务器里面有什么？三样最关键的硬件：","**CPU**（中央处理器）：真正会『算』的部分，负责执行指令。它快、但几乎没有记忆。","**内存 RAM**：临时、高速的『草稿本』，程序运行时把正在用的东西放这里；一断电全清空。","**磁盘 Disk**：长期、慢速的『仓库』，文件、数据库、图片都躺在这；断电也保留。","三者关系：程序从『磁盘』读进来 → 在『内存』里运行 → 由『CPU』逐条执行。所以『进程/线程』就是运行中的程序在内存和 CPU 上的具体存在。","**操作系统（OS）**：介于硬件和你程序之间的大管家。它负责：管理文件、管理进程、分配内存、读写磁盘、管理网络与权限。你的程序不是直接拿 CPU 干活，而是『请操作系统帮你安排』。Windows / macOS / Linux 都是操作系统。"],"advanced":["**编译 (Compile) vs 解释 (Interpret)**：代码有两种变可执行的方式。编译型（如 C、Go）：先整体翻译成机器码，再运行，快但改后要重新编译；解释型（如 Python、JavaScript）：一边翻译一边运行，改了就生效，但慢。","**Runtime（运行时）**：指『解释器 / 虚拟机 / 平台环境』，如 Node.js（能让 JS 在服务器上跑）、Python 解释器、Java 虚拟机（JVM）、浏览器的 JS 引擎（V8）。同一个 JS 文件，在浏览器里和 Node 里跑，用的是不同 Runtime——所以『它在浏览器能跑，不代表服务器能跑』。","**进程 (Process) vs 线程 (Thread)**：进程＝一个独立运行的程序实例，有自己独立的内存（跑崩一个不影响别的）；线程＝进程内部可并发的轻量任务单元，共享进程内存。一个 Node 服务通常是一个进程，一次请求常会用到多个线程/异步任务来并行处理。","**文件 / 路径 / 权限**：一切配置、代码、静态资源都是『文件』，文件有『路径』（在哪个文件夹）和『权限』（谁能读/写/执行）。很多部署报错是『权限不够』（403）或『路径不对』（404）——这不是代码逻辑问题，而是环境问题。","**环境 (Environment)**：你的程序依赖很多东西：命令、依赖包、环境变量、数据库地址、端口。这些合称『运行环境』。第 7 课上线的本质，就是把『你本机那套环境』尽量一致地搬到服务器上。"]},{"type":"ask","title":"怎么用 AI 帮你改代码：先问清『第几层』","scenario":"你的页面打开了，但点击『登录』没反应，控制台报了个错。怎么把这个信息高效地交给 AI？","template":"[我要描述] 我在做一个登录功能，点击登录按钮后页面没反应。\n[它能观测到的现象] 浏览器控制台报错：Cannot read properties of undefined (reading 'catch')，出错在 main.js 第 42 行。\n[我判断在哪一层] 前端 JS 在做请求时出错（尚未到后端）。\n[请给我] 帮我定位 main.js 第 42 行为什么报错，并给出修复方案与原因。","acceptance":["AI 给的答案里是否指明了『问题所在的那一层』（前端/后端/数据库/网络/环境）？","修复方案是否同时告诉你『为什么之前会错』（因果），而不只是『把这段换成这段』？","改完是否教你该怎么验证（例如：刷新？重启后端？看哪个日志？）？","如果 AI 只给了代码而你仍不确定，是否会继续追问『这个报错出现在哪一层、我怎么验证』？"],"tip":"给 AI 的信息越『分好层』，它越能准确判断。‘分层 + 现象 + 报错 + 我的判断’ 四件套，能大幅减少来回试错。"},{"type":"exercise","prompt":"你在浏览器打开自己刚做的网站，页面显示出来了，但点『提交表单』后页面一点反应都没有，浏览器控制台也没报错。根据这一课的分层，你最应该先怀疑哪一层？","opts":["我的 HTML 结构写错了（前端静态层）","后端程序没启动或没连上（后端层）","我的屏幕/显卡坏了（硬件层）","域名没过期（网络层）"],"a":1,"explain":"页面能正常显示说明前端静态层基本没问题；但『提交表单』要发请求给后端，没反应最可能是后端没启动、路径不对、或请求根本没发出去。先检查后端服务在不在跑、接口地址对不对。","jump":"sec7-step3","jumpLabel":"第 ④ 步：服务器接收并把请求交给后端"},{"type":"check","title":"结课检测：你能给报错『分层』了吗","intro":"共 5 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"浏览器里 DNS 解析这一步骤主要解决什么问题？","opts":["把域名翻译成 IP 地址","把 HTML 渲染成画面","把代码编译成机器码","把密码加密"],"a":0,"explain":"网络只认数字 IP，DNS 负责把人类好记的域名翻译成 IP，浏览器才知道该把请求发到哪台机器。","jump":"sec5-step1"},{"q":"『注册新账号后数据能永久保存』，这件事主要由哪几层协作完成？","opts":["只有浏览器（前端）","后端程序 + 数据库，前端只负责收集输入","只有网络（TCP/IP）","只有操作系统"],"a":1,"explain":"注册必须把信息写入数据库才叫『永久保存』；后端程序负责接收并由数据库落盘，前端只是收集输入。","jump":"sec5-step4"},{"q":"『代码在浏览器能跑』是否代表『同样的代码在服务器上也能跑』？","opts":["一定可以","不一定，因为浏览器和 Node/Python 是不同的 Runtime","一定不可以","只和网速有关"],"a":1,"explain":"浏览器里的 JS 由浏览器 JS 引擎跑，服务器上的 JS 由 Node.js 跑，是不同的 Runtime，能力与可用模块不同。","jump":"sec7"},{"q":"一个『Web 产品』由前端、后端、数据库组成。下面哪句最准确？","opts":["前端能直接连接数据库","后端程序通过接口把数据给前端，数据库由后端访问","数据库必须放在浏览器里","后端程序只能写死数据，不能读数据库"],"a":1,"explain":"前端只调用后端提供的接口(API)，后端负责访问数据库并返回结果，这样能隔离权限、便于维护。","jump":"sec7-step5"},{"q":"某功能『本地 localhost 一切正常，部署到线上就报数据库连不上』，最可能是哪两类环境不一致？","opts":["前端字体大小不同","数据库地址/密码/环境变量，以及迁移状态不一致","屏幕分辨率不同","键盘语言不同"],"a":1,"explain":"本地与线上最多的差距是数据库连接信息（地址、账号、密码）、环境变量配置，以及数据库结构是否已迁移。","jump":"sec7"}],"done":"你现在能把『一个 Web 产品』按层拆开了——前端、后端、数据库、服务器、网络各归其位，报错也能分到对应层。下一课我们钻到『后端』这一层：HTTP 到底是什么，API 怎么写、怎么调。","nextLesson":"v03-api"},{"type":"connection","known":["（这是 Vibe Coding 路径的第一课，默认你已经上过《从零看懂 AI》路径或至少了解『模型/产品』概念。）"],"learned":["一个 Web 产品 = 前端 + 后端 + 数据库 + 服务器 + 网络，彼此通过 HTTP 通信","一次请求的 7 步因果链：输入地址 → DNS → 建立连接/HTTP → 服务器 → 后端 → 数据库 → 渲染返回","CPU / 内存 / 磁盘 / 操作系统 / 进程 / 线程 / 编译解释 / Runtime 的定位","前端 / 后端 / 接口 API / 本地 localhost / 线上 的区别","给 AI 提问前先给报错『分层』，能显著提高一次成功率"],"next":"下一步我们进入『后端』层。想了解 AI 生成/理解代码，可回看 AI 路径的《AI Coding》一课；想把这条链路里『数据是怎么被长期记住的』讲透，下一课（API 与后端）与再下一课（数据库、登录与安全）会分别展开。","links":[{"href":"#/lesson/l22-ai-coding","text":"回看 AI 路径《AI Coding：把 AI 变成结对程序员》"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},"v02-git":{"id":"v02-git","title":"Git 与版本控制：改坏了能回退","subtitle":"AI 会帮你写很多代码，也会帮你挖很多坑。Git 就是你的『时光机』：每次改动都能留下脚印，随时能回到任意一个能跑的状态。","course":"vibe","courseNo":"02","level":"base","estTime":"15-25 分钟","difficulty":1,"concepts":["git","version-control","commit","rollback"],"prereqLessons":["v01-web"],"nextLesson":"v03-api","sections":[{"type":"opening","question":"你让 AI 帮你改了三版代码，第三版比第一版还烂，可你已经不记得第一版长什么样了。或者，你一次『大手笔』改动了 20 个文件，结果整个网站跑不起来了，你该从哪开始往回找？","guess":"很多人会一边叹气一边‘硬改回来’，或者干脆重写一遍。","next":"这一课教你用 Git 给项目装一台时光机：学会『提交快照』、『回到过去』、『看谁改了什么』。从此，你再也不用怕 AI 挖坑——任何时候都能一键回退到能用的时候。"},{"type":"why","before":"你在 Vibe Coding 里高频迭代，AI 每天都在‘改这改那’，你分不清哪次改对了、哪次改坏了。","problem":"没有版本意识时，一切改动都是一次性赌注：改坏了只能干瞪眼，重写又怕丢东西，联合 AI 调试也像无头苍蝇。","need":"你需要一个能记录每次改动、允许你随时回到任何历史状态的工具。Git 就是这个工具——它是所有 AI 编程、团队协作、正式上线的地基。"},{"type":"oneline","text":"Git 是一个版本控制工具：它把项目的每一次改动分别保存成一个个『快照（提交/commit）』，你可以在任意两个快照之间来回切换、对比、合并与回退，相当于给整个代码库装了‘存档 + 读档’功能。"},{"type":"intuition","blocks":[{"k":"用游戏存档来想","t":"Git 就像游戏里的存档系统：每过一关（每次你确认‘行，就这样’）就存一次档。后来玩砸了（改坏了），不用从头再来，直接读档回到上一个存档点。存档点就是 commit。"},{"k":"用写作文改稿来想","t":"你写作文时会保留每一稿：初稿、改一稿、改二稿。每一个‘稿’都是一个版本，你随时能翻回去看最初写得多烂，也能一句句对比改了什么。Git 就是自动帮你留稿，还能任意回看。"},{"k":"三棵树记法","t":"Git 有‘三棵树’：工作区（你正在改的文件）、暂存区（你选定了要记录的改动）、版本库（已正式存档的历史）。顺序是：改文件 → 加进暂存区（git add）→ 提交存档（git commit）。‘提交’就是按下存盘键。"}]},{"type":"how","intro":"一套最简 Git 工作流，五步。你不需要记一堆命令，只记这条主干循环。","steps":[{"in":"① 初始化仓库：git init","process":"在项目根目录执行 git init，Git 就会开始悄悄跟踪这里的所有改动。这相当于宣布‘从今天起，这个文件夹纳入版本管理’。","out":"一个 git 仓库（.git 目录），开始记录历史"},{"in":"② 查看改动：git status","process":"随时运行 git status，Git 告诉你哪些文件被改了、哪些是新增的、哪些还没被跟踪。这是每次动手前后的‘体检’。","out":"清楚当前工作区里有哪些变动"},{"in":"③ 选定要记录的内容：git add","process":"把你想纳入这份快照的文件加入暂存区。可以全部加（git add .），也可以挑几个加。你决定‘这一份存档里要包含什么’。","out":"文件进入暂存区，等待被提交"},{"in":"④ 正式存档：git commit","process":"执行 git commit，并写一句说明（如‘修复登录按钮’）。这一步像按下存盘键，一个永久、可回退的版本节点就诞生了。","out":"一个带说明的历史版本（commit）"},{"in":"⑤ 回退与查看历史：git log / git checkout / git reset","process":"用 git log 看所有历史版本；改坏了用 git checkout 或 git reset 回到某个 commit；git diff 对比两个版本差别。这就是你的时光机操作台。","out":"随时能回到任意能跑的历史状态"}]},{"type":"realworld","items":[{"name":"每次‘能用’就提交","note":"Vibe Coding 的黄金习惯：只要当前版本能跑、你觉得 OK，就立刻 commit。这会形成一串‘安全的存档点’，让你随便折腾 AI。"},{"name":"提交信息写清楚","note":"写一句人话（‘加了登录’而不是‘改了点东西’），几周后你才知道每个存档里装了什么。AI 生成的代码更要写清楚，否则回退都不知道回到哪。"},{"name":"分支 branch：开一条平行世界","note":"你想大胆试一个新功能又不想搞乱主版本时，开一个分支去折腾，成了再合并回来，毁了就丢。这是团队协作和探索新玩法的基础。"},{"name":"GitHub 远程仓库","note":"把本地仓库推到 GitHub（git push），你的代码就有了云端备份，也方便和 AI/他人协作。这是后续‘部署上线’的前置步骤。"}]},{"type":"compare","pairs":[{"a":"git add","b":"git commit","diff":"add 是把改动选进‘暂存区’（决定存哪些），commit 是正式存档（生成一个永久历史节点）。add 可反复调整，commit 一按即生效。"},{"a":"git checkout","b":"git reset","diff":"checkout 常用于切到某版本查看/恢复单文件，偏‘只管当前状态’；reset 会把仓库指针移回某提交，可能连带影响历史。新手优先用 checkout 更安全。"},{"a":"本地仓库","b":"远程仓库(GitHub)","diff":"本地仓库在你电脑上，随改随存；远程仓库在云端，用于备份、协作、部署。两者靠 push/pull 同步。"},{"a":"没有 Git","b":"有 Git","diff":"没有 Git，改坏了只能靠记忆或重写；有 Git，随便改、随时回退、随手对比，风险大幅降低。"}]},{"type":"mistakes","items":["只在‘做坏了’才想起 git——其实应该在‘做对了’（能跑）时就提交，形成安全存档点。","提交信息乱写甚至不写——几周后完全看不懂每个存档是干嘛的。","把 node_modules、.env 密码等不该提交的文件也提交了——这些要么巨大要么含敏感信息。","一次提交塞了 20 个文件的无关改动——回退和排查时一团乱。每份提交尽量单一、聚焦。","以为 git 会‘自动保存’——不会！你得手动 add + commit。忘了提交 = 没存档。"]},{"type":"ask","title":"怎么用 AI 帮你处理 Git：把报错和意图一起给","scenario":"你想回退一个改动，但不太确定用哪个命令，或者 git 报了一大串英文错误。","template":"[我的意图] 我想把刚改坏的登录功能回到『能跑』的那个版本。\n[我做了什么] 刚刚 commit 了一个修复登录的版本，现在想回到上一个能跑的版本。\n[我看到的报错] git 提示：error: Your local changes to the following files would be overwritten by checkout...\n[请给我] 告诉我这个报错是什么意思，应该用哪个命令安全回退，并且不要丢我现在还没提交的改动。","acceptance":["AI 是否先解释了报错的含义，而不是直接丢命令？","是否提示了‘会覆盖未提交改动’这类风险，让你确认后再执行？","是否给出安全回退的具体命令序列？","是否提醒你在回退前先 commit 或 stash，避免丢失当前工作？"],"tip":"亲手学会 git 三个核心动作（add/commit/checkout），其余的交给 AI 也行——但你要能看懂它在给你做什么、会不会有风险。"},{"type":"exercise","prompt":"你让 AI 改了代码，然后手动运行发现网站跑不起来了。你希望回到‘之前的能跑版本’。下面哪个动作是你应该先确认的？","opts":["立刻 git commit，把坏掉的也存档一份","先 git log 找到最近一个能跑版本的提交编号，再据此回退","直接删掉整个项目文件夹重新开始","啥也不做继续改"],"a":1,"explain":"正确做法是先 git log 定位到能跑的那次提交，再用 git checkout / reset 回退到该版本。把坏版本也 commit 存档（选项 1）反而制造了更多坏存档，不是首选。","jump":"sec5-step4","jumpLabel":"回退与查看历史这一步步"},{"type":"check","title":"结课检测：你掌握 Git 时光机了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回对应段落复习。","questions":[{"q":"Git 里‘存档点’的正式名称是什么？","opts":["分支","提交 (commit)","暂存区","工作区"],"a":1,"explain":"commit（提交）就是保存一个可回退的历史快照，相当于游戏存档点。","jump":"sec5-step3"},{"q":"正确的‘三棵树’操作顺序是？","opts":["commit → add → 修改","修改文件 → git add → git commit","git add → 修改 → git commit","git commit → git checkout"],"a":1,"explain":"顺序是：先在工作区修改文件，再用 git add 选入暂存区，最后 git commit 正式存档。","jump":"sec5-step2"},{"q":"为什么 Vibe Coding 强调‘能跑就立刻 commit’？","opts":["为了显得专业","形成安全存档点，之后随便让 AI 折腾都能回退","提交越多代码越少","Git 会自动备份"],"a":1,"explain":"每个能跑的 commit 都是一个安全存档点，AI 后续怎么改坏了都能一键回到这个状态。","jump":"sec5-step4"},{"q":"下面哪类文件最不应该被提交到仓库？","opts":["源码 js 文件","含密码/密钥的 .env 等敏感配置","html 页面","readme 说明"],"a":1,"explain":"敏感配置（.env 含密钥）绝不应提交，否则会被泄露；这类通常放进 .gitignore。","jump":"sec6"}],"done":"你现在有了自己的时光机：能存档、能回退、能对比，再也不怕 AI 挖坑了。下一课进入后端：API 到底是什么，前后端怎么在 HTTP 里对话。","nextLesson":"v03-api"},{"type":"connection","known":["你已了解一个 Web 产品的分层（v01）、AI 会挖坑的风险（Vibe 课核心）"],"learned":["Git = 版本控制的存档系统，add/commit/checkout 主干循环","‘能跑就提交’形成安全存档点，是 AI 编程的兜底","分支、远程仓库、.gitignore 等进阶用法","给 AI 处理 Git 报错时的安全提问方式"],"next":"自这一步开始，你的每次改动都有据可查。下一课我们进入后端层：API 与 HTTP——前后端到底是怎么说话的。","links":[{"href":"#/lesson/v03-api","text":"下一课：《API 与后端：前后端怎么对话》"},{"href":"#/lesson/v01-web","text":"回看《一个 Web 产品是怎么跑起来的》"}]}]},"v03-api":{"id":"v03-api","title":"API 与后端：前后端怎么『对话』","subtitle":"前端要数据、后端给数据，靠的是一套约定好的『暗号』——HTTP 方法与状态码。看懂它对 AI 来说轻而易举，对你是判断代码靠不靠谱的分水岭。","course":"vibe","courseNo":"03","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web"],"nextLesson":"v04-db","sections":[{"type":"opening","question":"你的 App 在前端里点了个『收藏』按钮，后端怎么知道你要『新增一条收藏』而不是『删除一条』？同样是敲同一个接口地址，凭什么这次是加分、那次是删东西？","guess":"很多人会说『靠传一个名字不一样的按钮』。","next":"答案藏在 HTTP 的『方法（Method）』里。这一课我们把前后端之间的对话协议——HTTP 方法和状态码——彻底讲透：GET 和 POST 到底差在哪，200/404/500 各代表什么，什么是 API、什么是 JSON。学完你会开始『读』接口而不是『猜』接口。"},{"type":"why","before":"AI 写了个后端接口，前端也调了。你看着代码：有一堆 `app.get('/api/friends')`、`app.post('/api/friends')`、`req.body`、`res.json(...)`。你不懂为什么有的用 get 有的用 post，也不知道返回的 `{status:'ok', data:[...]}` 是什么。","problem":"不懂 HTTP 方法与状态码，你会犯两种错：要么把『该用 POST 写数据的操作』写成了 GET，导致数据带在 URL 里、既不安全又不支持大内容；要么拿到报错号 404/500 完全没概念，不知道该看前端还是后端。AI 生成的代码你再不敢动，一改就崩。","need":"把 HTTP 的『动词』（方法）、『回执』（状态码）、『货单』（请求/响应头与正文 JSON）看明白，你就拥有了『判断一段接口代码对不对』的最小能力：方法对不对、状态码合不合理、参数传没传对。这正是把 AI 代码从『能跑』升级到『可靠』的一步。"},{"type":"oneline","text":"API 是后端对外开的一扇扇门（URL），你用『HTTP 方法』说明你想干嘛（GET 拿数据 / POST 新增 / PUT 整体更新 / PATCH 部分更新 / DELETE 删除），后端用『状态码』告诉你结果（2xx 成功 / 4xx 你这边的问题 / 5xx 服务器的问题），数据通常以 JSON 格式在请求和响应里传递。"},{"type":"visual","kind":"http-viewer","title":"互动实验：HTTP 查看器，亲手发一个请求","hint":"选一个方法、填一个地址（或点预设接口），点『发送』。它会向你展示：这次请求带了哪些方法/头部/参数，服务器会返回什么状态码与 JSON 正文，以及每个状态码对应的含义。体会『同一个 URL，方法不同 = 动作不同』。"},{"type":"intuition","blocks":[{"k":"用餐厅点菜来想","t":"API 地址（URL）＝餐厅的『窗口名』，比如『/api/friends』是『朋友窗口』；HTTP 方法＝你点菜的动作——‘看看今天的菜单’（GET）、‘点一个菜’（POST）、‘把整个菜换掉’（PUT）、‘加个辣’（PATCH）、‘退掉这个菜’（DELETE）。后端（厨师）按你的动作处理，再用状态码告诉你：‘上菜了’（200）、‘这个菜没有’（404）、‘厨房炸了’（500）。"},{"k":"用寄快递来想","t":"GET 就像‘查单号’——只读，不改变任何东西，可以来很多次；POST 就像‘下单寄件’——会产生一个新的快递（新增数据）。所以‘收藏、下单、注册、发帖’这些会新增数据的操作用 POST，而‘翻页、搜索’这种只看不动的用 GET。"},{"k":"一句话记住状态码","t":"2 开头的都成功；3 开头的是‘让你去别处看’（重定向）；4 开头的是‘你（客户端）的问题’（404 找不到、401 没登录、403 没权限、400 请求写错）；5 开头的是‘服务器（后端）的问题’（500 内部出错）。看到 4 或 5，你就能立刻判断该检查哪一边。"}]},{"type":"how","intro":"把一个 HTTP 请求拆成 5 个部分，从头到尾走一遍『前端 → 后端 → 响应回前端』。","steps":[{"in":"① 请求行：方法 + URL","process":"前端发起一行字：`POST /api/friends`。前半是方法（动作），后半是接口地址（去哪扇门）。这决定了后端接下来执行哪段逻辑。","out":"例如 POST = 新增；GET = 查询；DELETE = 删除"},{"in":"② 请求头 Headers","process":"附带的一堆元信息：Content-Type（正文是 JSON 还是表单）、Authorization（登录凭证，如 Bearer token）、Accept（你想要什么格式）、携带的 Cookie 等。后端靠这些判断『你是谁、你给的是什么』。","out":"身份与格式声明"},{"in":"③ 请求正文 Body","process":"POST / PUT 需要把要写入的数据放进正文，通常是 JSON：`{\"name\":\"小明\",\"phone\":\"138...\"}`。GET 一般没有正文，参数放在 URL 查询串里（?name=小明）。","out":"数据内容（多为 JSON）"},{"in":"④ 后端处理并返回状态码","process":"后端读到方法+地址+头+正文，跑对应的逻辑，无论成败都返回一个状态码：成功 200/201，找不到 404，参数错 400，没登录 401，服务器异常 500。","out":"状态码：2xx / 4xx / 5xx"},{"in":"⑤ 响应正文 + 响应头","process":"成功后后端通常返回一个 JSON：`{\"ok\":true,\"data\":{...}}`，前端拿到这个结构再决定如何渲染。响应头里也常有 Set-Cookie、Cache-Control 等控制信息。","out":"前端拿到 JSON，渲染到界面"}]},{"type":"realworld","items":[{"name":"浏览器开发者工具 Network 面板","note":"按 F12 → Network，你能亲眼看到每一笔请求：方法、URL、状态码、耗时、请求/响应头与 JSON。这是『读接口』最重要的工具，AI 给不了你，但它能解释你从里面截到的任何一行。"},{"name":"REST 设计风格","note":"REST 是一套流行的接口组织约定：把『资源』当名词放 URL（/users、/posts），把动作当方法（GET/POST/PUT/DELETE）。例如 GET /users/5 读用户5，DELETE /users/5 删用户5。看懂 REST，你便看懂了大半后端代码的结构。"},{"name":"第三方开放 API（天气/支付/地图）","note":"你在产品里调的天气、支付、地图接口，就是对面公司后端暴露的 API。你会看到它要求固定方法、固定鉴权头（Authorization/ApiKey）、返回固定 JSON 结构。会读 API 文档 = 会接第三方能力。"},{"name":"前后端分离项目","note":"很多现代项目前端与后端是两个独立工程，只通过一组 API 契约对接。只要接口约定不变，前端可以换成任何形态（网页/App/小程序），后端完全不用改。这也解释了为什么『接口规范』如此重要。"}]},{"type":"compare","pairs":[{"a":"GET","b":"POST","diff":"GET 用于『读』数据：参数放 URL，可分享/可缓存，不应产生副作用（不会改服务器的数据）；POST 用于『写』数据：参数放正文，用于新增/提交，会产生副作用。安全与不大数据量的操作用 GET，会改数据的操作用 POST。"},{"a":"状态码 4xx","b":"状态码 5xx","diff":"4xx 是『客户端问题』：请求写错、没登录（401）、没权限（403）、找不到（404）——请检查你前端发出去的请求；5xx 是『服务器问题』：后端代码异常（500）、超时（504）——请检查后端日志。"},{"a":"REST API","b":"GraphQL","diff":"REST 靠『多个端点 URL + 方法』组织接口；GraphQL 靠『一个端点 + 查询语句』按需取字段。REST 更简单通用、生态大；GraphQL 更灵活但要学查询语法。入门从 REST 开始最稳。"},{"a":"JSON","b":"表单 Form-encoded","diff":"JSON 是一种结构化文本（{\"k\":v}），后端好解析、支持嵌套，是现代 API 主流；传统表单格式（a=1&b=2）较简单但在复杂数据前吃力。看到 Content-Type: application/json 就知道后面是 JSON。"}]},{"type":"mistakes","items":["AI 常犯（也常让你中招）的错误案例①：把『该用 POST 的新增操作』写成了 GET，导致密码等敏感数据出现在 URL / 日志里，既不安全又不支持大内容。","错误案例②：删改操作应返回合适状态码，却一律返回 200——前端永远‘成功’，数据却没被真正删掉。看到代码里所有分支都 res.json({ok:true}) 且不看状态码，就要警惕。","错误案例③：前端没把 token/Cookie 带上（没设置 headers.Authorization），导致后端每次回 401；前端却把锅甩给‘后端 bug’。判断法：看 Network 里那次请求的请求头带没带凭证。","把 404 理解成‘页面不见了’就完事——404 也可能是‘接口地址写错’，要不检查前端 URL，要不检查后端路由。/api/users 与 /api/user 差一个字母就是两个世界。","盲目照抄 AI 生成的接口而不看返回结构：前端拿 res.data.data 却和接口对不上，出来全是 undefined。学会看 Network 里真实的 JSON 结构再写渲染。"]},{"type":"deep","title":"深入一点：怎么判读一段 AI 写的接口代码","beginner":["拿到 AI 写的后端接口，按下面三问逐一看，就能快速判断靠不靠谱：","**一问方法**：这个操作该不该用这个 HTTP 方法？读操作用 GET，写操作用 POST/PUT/DELETE。方法不对 = 语义错。","**二问状态码**：成功路径返回 2xx 吗？参数错返回 400 吗？没登录返回 401 吗？没有的数据返回 404 吗？服务器异常会抛 500 吗？一个只返回 200 的接口是不合格的。","**三问数据流**：后端取参数的字段名，和前端传的字段名一致吗（body.name）？返回的 JSON 结构和前端 res.data.xxx 对得上吗？对不上就是坑。"],"advanced":["**express（Node 后端框架最小示例）**：","```js\napp.get('/api/users/:id', async (req, res) => {\n  const user = await db.one('SELECT * FROM users WHERE id=$1', [req.params.id]);\n  res.status(200).json({ ok: true, data: user });\n});\n```","注意三件事：`:id` 是路径参数（req.params.id）；操作是读 → 用 GET；成功返回 200。若查不到应 `return res.status(404).json({ok:false})`，而不是硬返回 200 空对象。","**错误处理缺失是最大隐患**：AI 常写出‘只管成功不管失败’的接口。可靠接口要捕获异常并返回 5xx：","```js\napp.post('/api/users', async (req, res) => {\n  try { await db.insert('users', req.body); res.status(201).json({ok:true}); }\n  catch (e) { console.error(e); res.status(500).json({ok:false, msg:'写入失败'}); }\n});\n```","**‘如何向 AI 验收一个接口’**：让 AI 给出‘该方法、正常/异常状态码、请求/响应 JSON 示例’三件套；你再对照 方法→语义 是否正确。能给出完整三件套的接口定义，才值得写进产品。"]},{"type":"ask","title":"怎么用 AI 帮你写/改一个接口","scenario":"你让 AI 写一个‘新增好友’的后端接口，并希望它可靠、前后端好对接。","template":"[我要做一个] POST /api/friends 的新增好友接口。\n[我希望的入参] JSON：{ nickname, remark }。\n[我希望的结果] 成功后返回 201 + {ok,data};昵称为空返回 400;后端异常返回 500。\n[请给我] 完整的 Node/Express 代码（含错误处理），并附：请求示例 JSON、成功/失败状态码与返回体、以及前端如何 fetch 调用的示例。","acceptance":["接口是否用对了 HTTP 方法（新增→POST）？","是否覆盖了成功(201)、参数错(400)、服务器错(500) 至少三类状态码？","请求与响应 JSON 结构是否给出、且前后端字段名一致？","是否包含 try/catch 错误处理而不是只管成功？用浏览器 Network 面板实测一下接口是否按文档返回。"],"tip":"把‘我要什么入参 + 我要什么结果 + 我要什么状态码’写成模板，AI 生成的接口会立刻规范很多；再用 Network 面板实测验证，别只看它嘴上说‘OK’。"},{"type":"exercise","prompt":"你在前端写了一个请求，点按钮后 Network 面板显示某请求返回 401。你最应该先检查什么？","opts":["后端 SQL 写错了","前端这次请求有没有带上登录凭证（Authorization/Cookie）","服务器机器坏了","网络 DNS 解析失败"],"a":1,"explain":"401 = 未认证/未登录，最常见原因就是请求没带凭证。去看 Network 里这一次请求的请求头，确认是否带了 token 或 Cookie。","jump":"sec5-step1","jumpLabel":"第 ② 步：请求头 Headers"},{"type":"check","title":"结课检测：你会读 API 了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"‘把一条收藏记录保存起来’应该用哪个 HTTP 方法？","opts":["GET","POST","PUT","DELETE"],"a":1,"explain":"产生新数据的写操作应该用 POST；GET 只用于读，不该产生副作用。","jump":"sec5-step0"},{"q":"状态码 401 表示什么？","opts":["找不到页面","未认证/未登录","服务器内部错误","请求太大"],"a":1,"explain":"401 Unauthorized = 未认证，需要登录凭证；403 才是‘已登录但没权限’。","jump":"sec5-step4"},{"q":"看到返回 500，你优先怀疑哪一层？","opts":["前端渲染","浏览器缓存","后端程序异常","CSS 样式"],"a":2,"explain":"500 = Internal Server Error，是服务器（后端）处理出错，去查后端日志与代码。","jump":"sec5-step4"},{"q":"REST 接口中，URL 里的名词代表什么？","opts":["动作（增删改查）","资源（如 /users、/posts）","设计者名字","数据库类型"],"a":1,"explain":"REST 把资源当名词放 URL，动作由 HTTP 方法表达。GET /users/5 是‘读用户5’。","jump":"sec6"},{"q":"前端请求里，登录凭证通常放在哪个位置？","opts":["URL 查询串","请求头 Headers（如 Authorization）","CSS 文件","浏览器书签"],"a":1,"explain":"凭证（token/Cookie）一般放在请求头里，如 Authorization: Bearer xxx；不放会导致 401。","jump":"sec5-step1"}],"done":"你已经能读懂前后端之间的‘暗号’了：方法定动作、状态码定结果、JSON 传数据。下一课我们把线的另一头——数据本身——讲清楚：数据库怎么设计，登录与安全怎么做。","nextLesson":"v04-db"},{"type":"connection","known":["你已经知道一个 Web 产品 = 前端 + 后端 + 数据库，通过 HTTP 通信（上一课）。","你已经会调用模型/看得懂 AI 相关 API 的基础概念（AI 路径）。"],"learned":["HTTP 方法：GET 读 / POST 写 / PUT 整体更新 / PATCH 局部更新 / DELETE 删除","状态码：2xx 成功 / 4xx 客户端问题 / 5xx 服务器问题","请求 = 方法 + URL + 头 + 正文(JSON)；响应 = 状态码 + JSON","REST 设计：名词当资源，方法当动作","给 AI 描述接口需求时，用‘入参+结果+状态码’三件套模板"],"next":"接口是承上启下的：它把‘数据’从后端递给前端。可数据从哪来、怎么存、怎么保证安全？这正是下一课《数据库、登录与安全》要解决的。和 AI 路径的联系：你调用大模型 API 的本质也是‘前端→HTTP→别人家后端的接口’，底层逻辑完全相同。","links":[{"href":"#/lesson/l16-llm-api","text":"回看 AI 路径《用 API 把模型接进你的产品》(规划中)"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},"v04-db":{"id":"v04-db","title":"数据库、登录与安全","subtitle":"数据是产品的命，登录是产品的门。这一课把‘数据怎么存’、‘你怎么证明是你’、‘怎么防坏人’讲透。","course":"vibe","courseNo":"04","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api"],"nextLesson":"v05-test","sections":[{"type":"opening","question":"用户注册了账号、收藏了文章、下了单——这些数据如果不做任何抽象地乱放在一起，会出什么问题？‘收藏’和‘用户’之间到底是什么关系？而你按下‘登录’，服务器凭什么相信你就是那个人，而不是冒充的？","guess":"很多人觉得‘数据随便存个文件不就行了，登录就是在数据库里对一下密码’。","next":"这一课回答三件事：①数据用‘关系表’组织才不乱（表、列、主键、外键、索引、SQL）；②‘登录’不是查一下密码那么简单——Session、JWT、OAuth 各是怎么证明‘你是谁’的；③坏人会怎么攻击（SQL 注入、XSS），以及怎么守住（参数化、转义、加密/哈希、最小权限）。"},{"type":"why","before":"AI 帮你生成登录/注册/收藏/下单功能，里面全是你不认识的词：SQL、primary key、foreign key、index、session、token、bcrypt、JWT、OAuth、SQL 注入。你照抄能跑，但出问题时完全无法判断是‘表没建对’‘还是登录逻辑错’‘还是被人攻击了’。","problem":"数据库设计与安全是‘你几乎不会让 AI 自己随便发挥’的地方——因为数据是用户资产、登录是安全边界。如果不懂“为什么用户表要 id 做主键”“为什么密码要哈希不能存明文”“为什么 SQL 要参数化防止注入”，你根本没法验收 AI 的代码，等于把产品最关键的部分交出去赌运气，早晚出事。","need":"这一课把最少必备的数据库设计与安全知识补上：会看表结构、会写最基础的 SQL、能对比 Session / JWT / OAuth、知道 SQL 注入和 XSS 是什么并知道对应防御。这样当 AI 给出表结构和登录代码，你能像审稿人一样快速挑出明显错误。"},{"type":"oneline","text":"产品数据大多存在关系型数据库（如 PostgreSQL/MySQL）：数据按‘表’组织，每行一条记录，靠‘主键’唯一标识，表与表用‘外键’建立关系，用 SQL 增删改查；登录靠加密凭证证明身份（Session 服务端记、JWT 它自己证明、OAuth 让第三方背书）；安全的核心三件事——密码要哈希不要明文、SQL 用参数化防注入、输出要转义防 XSS。"},{"type":"visual","kind":"db-designer","title":"互动实验：设计一张数据库表","hint":"这是一个迷你‘表设计器’：你决定表有哪些列、哪列是主键、要不要加索引、要不要存密码明文。点击‘预览 SQL / 检查问题’，它会告诉你这张表会不会踩主键、密码明文、可空、无索引等常见坑。体会‘多花一分钟设计，省无数 bug’。"},{"type":"intuition","blocks":[{"k":"用班级花名册来想","t":"数据库里的‘表’就像一张花名册：‘列’是表头（学号、姓名、班级），‘行’是一条记录（某个同学）。‘主键（primary key）’＝学号——全班唯一，靠它能精准找到某个人；‘外键（foreign key）’＝‘本班编号’——它指向另一张‘班级表’的主键，从而把两张表关联起来。没有主键，你用‘姓名’找人会遇到重名；没有外键，班级和学生就接不上。"},{"k":"用门禁卡来想登录","t":"Session＝你在前台刷了一次脸后，前台给你一把只在这栋楼有效的临时钥匙，钥匙上是你进门时发的一个号码（sessionId），门卫每次核对后台名单；JWT＝一把自带信息的加密卡片，上面写着‘我是小明，3 小时后过期’，门卫验签名就放行，不用每次查后台；OAuth＝你出示‘微信已认证’的凭证，门卫信微信的背书就让你进。三种都是‘证明你是你’，只是证明的方式和存放地点不同。"},{"k":"一句话记住安全","t":"密码只存哈希（加盐），不存明文；SQL 永远用参数化（?/$1 占位符），别拼字符串；输出到页面要转义（防 XSS）；后端始终校验，前端校验只是体验。记住这四条，你能挡住绝大多数入门级攻击。"}]},{"type":"visual","kind":"auth-compare","title":"互动实验：Session / JWT / OAuth 三种登录横评","hint":"点击三种登录方式，看同一个‘登录→鉴权→访问’场景在后台是怎么不同的：状态存在哪、怎么验证、有没有跨端问题、优缺点一目了然。帮你给产品选对登录方案。"},{"type":"how","intro":"把‘数据入库 + 登录鉴权’拆成两条因果链：先看一张表从设计到查询怎么走，再看一次登录如何完成。","steps":[{"in":"① 设计表结构（Schema）","process":"确定这张表存什么：用户表要有 id（主键）、username、password_hash、created_at。列的类型要选对（数字用 integer、文本用 varchar）。先想好‘要回答什么问题’，再定表，否则后面改结构（迁移）很麻烦。","out":"一张结构清晰的表 + 主键"},{"in":"② 建表 + 加索引","process":"用 SQL 建表；对‘经常按它来查’的列（如 username）加上索引（index），否则数据多了每次都全表扫描、慢到卡死。索引=书的目录，能加速查找。","out":"表建好，查询有索引加持"},{"in":"③ 用 SQL 增删改查","process":"INSERT 插入、SELECT 查询、UPDATE 更新、DELETE 删除。查询可加 WHERE 过滤、JOIN 关联别表。这是后端操作数据库的日常。","out":"数据被正确写入/读出"},{"in":"④ 表和表用外键建立关系","process":"比如‘收藏表’里放一个 user_id 外键指向用户表、一个 article_id 指向文章表，就能表达‘这个用户收藏了那篇文章’的关系。","out":"数据之间有明确关联，不重复、不乱"},{"in":"⑤ 登录：验证 + 发凭证","process":"用户输入密码 → 后端把输入的密码加盐哈希，和库里存的那个哈希比对 → 相同则信任，创建会话凭证（Session 存服务端 / JWT 返回一个 token / OAuth 走第三方）。","out":"前端拿到凭证，后续请求都带上它"},{"in":"⑥ 访问控制：每步鉴权","process":"后续每个需要身份的请求，后端都校验凭证 → 合法才放行，非法返回 401。同时用权限逻辑控制在‘只能动自己的数据’（不能改别人的）。","out":"只有合法用户能访问其权限内的数据"}]},{"type":"realworld","items":[{"name":"用户系统崩了=数据库没备份/没迁移","note":"很多线上事故是数据库结构改了没做迁移，或连接串配错。知道‘表结构=产品地基’，你就会让 AI 在改表时同步给迁移脚本（ALTER TABLE…），并先在本地/测试库验证。"},{"name":"密码泄露事件=明文存储的代价","note":"反复出现的‘XX 网站密码库泄露’事故，根源常是明文或弱哈希存密码。正确做法：bcrypt/scrypt 加盐哈希。这是判断 AI 登录代码‘安全与否’的第一眼标准。"},{"name":"登录方案选择=产品形态决定","note":"简单网页用 Session 就够；前后端分离/多端（App+网页+小程序）常用 JWT；要‘微信一键登录’就用 OAuth。你会常看到这三者在真实项目里混用（如 JWT 登录 + 微信 OAuth 授权）。"},{"name":"防火墙/最小权限=运维层防御","note":"生产数据库通常不直接暴露公网，只允许服务器内网访问；应用账号只给它需要的库表权限。这是安全纵深的一部分，和‘代码那次注入’互补。"}]},{"type":"compare","pairs":[{"a":"Session（服务端会话）","b":"JWT（令牌）","diff":"Session 把状态存在服务器（内存/Redis/库），客户端只持一个 sessionId，好处是可随时踢人/注销；JWT 把身份信息加密签进 token 给客户端，服务器无状态，好处是天然适合多端与分布式，缺点是一旦签发难在过期前吊销。选型：传统/单一服务用 Session，前后端分离多端多用 JWT。"},{"a":"JWT","b":"OAuth","diff":"JWT 是一种‘凭证格式’（我信任它的签名）；OAuth 是一种‘授权协议’（用户把权限授予第三方，如‘微信允许这个 App 读我的昵称头像’）。OAuth 常把 JWT 当作其中一种 access_token 的载体。"},{"a":"哈希 Hash（单向）","b":"加密 Encrypt（可逆）","diff":"哈希不可逆：密码只做比对，任何人（包括你自己）都无法还原，适合存密码；加密可逆：能解回原文，适合传输敏感信息（但要妥善保管密钥）。拿加密去存密码是常见误区。"},{"a":"SQL 注入","b":"XSS 跨站脚本","diff":"注入是‘坏人把 SQL 代码塞进输入，骗后端执行’，防御靠参数化查询；XSS 是‘坏人把脚本塞进页面内容，骗浏览器执行’，防御靠输出转义。一个打数据库、一个打浏览器，都要防。"}]},{"type":"mistakes","items":["错误案例①（AI 高频）：密码用明文存进数据库列 `password`。正确是 `password_hash` 且用 bcrypt/scrypt 加盐哈希。看到列名叫 password 就要警觉。","错误案例②（致命）：SQL 用字符串拼接——`SELECT * FROM users WHERE name = '` + input + `'`。坏人输入 `' OR '1'='1` 就能登录一切人。必须改成参数化：`WHERE name = $1`（PG）或 `?`（MySQL）。","错误案例③：用户表没有主键，或把‘用户名’当唯一标识——重名就会数据错乱。主键必须稳定唯一（通常用自增 id 或 UUID）。","错误案例④：前端校验当安全边界——‘我在前端限制了只能填数字’并不能挡住直接调接口的攻击者。真正的校验必须在后端。","错误案例⑤：把 token 存 localStorage 又不设过期、也不校验是不是当前用户——一旦 XSS 就能偷走凭证。安全要‘防御纵深’，别只做一层。"]},{"type":"deep","title":"深入一点：手把手判读一张 AI 建的‘用户表’和登录接口","beginner":["看一张 AI 生成的用户表，先问五件事：","**有没有主键？** 要有 id（或 UUID）作主键，能唯一稳定地定位记录。","**密码是不是哈希列？** 应该叫 password_hash / password_digest，用 bcrypt，绝不存明文。","**必填列有没有 NOT NULL？** 用户名、密码哈希不能为空。","**会不会被注入？** 查询语句是不是参数化的（用占位符而非拼接）？","**有没有做访问控制？** 比如‘只能读自己的数据’，而不是任何人传个 id 就能读到别人的。"],"advanced":["**合法但可以更好的设计**：除了基础列，常加 created_at/updated_at 时间戳（审计用）；经常按 username 查就加唯一索引 `UNIQUE(username)`；邮箱/手机号单独存或用正则后端校验。","**登录接口应返回什么**：成功后（201/200）返回凭证；密码错返回 401；账号不存在也返回 401（而不是 404，避免暴露‘这账号存在’）。失败要记日志，但日志里别打明文密码。","**一个可参考的 SQL 建表**：","```sql\nCREATE TABLE users (\n  id BIGSERIAL PRIMARY KEY,\n  username VARCHAR(50) NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n```","**登录校验（参数化防注入的示范）**：","```js\nconst row = await db.oneOrNone('SELECT * FROM users WHERE username=$1', [username]);\nconst ok = row && await bcrypt.compare(password, row.password_hash);\nif (!ok) return res.status(401).json({ ok:false, msg:'用户名或密码错误' });\n```","注意 `$1` 占位符 + `[username]` 参数数组 = 参数化，SQL 注入无从下手。"]},{"type":"ask","title":"怎么用 AI 帮你设计数据库和登录","scenario":"你做了一个‘用户能注册、能收藏文章’的小产品，想让 AI 一次性给出靠谱的表设计和登录方案。","template":"[产品场景] 用户注册登录后，可以收藏文章（一个用户可收藏多篇文章）。\n[请帮我设计] ①用户表与收藏表的结构（含主键、外键、索引）；②注册/登录后端代码，密码用 bcrypt 加盐哈希、SQL 用参数化防注入；③返回 401/201 等状态码。\n[验收标准] 请说明：主键是谁、外键怎么关联、密码如何存储、如何防 SQL 注入、登录凭证用 Session 还是 JWT 并说明理由。","acceptance":["表结构是否给出了主键、外键和需要加的索引？","密码是否明确用了 bcrypt 之类加盐哈希而非明文？","SQL 是否参数化（占位符）而非字符串拼接？","登录凭证方案是否说明了 Session/JWT 的选择及理由？是否覆盖成功与失败状态码？"],"tip":"涉及数据库和安全，务必让 AI 把‘为什么这么做’讲出来，而不能只给代码。你再用上面的‘五问’走一遍，就能当半个审查。"},{"type":"exercise","prompt":"你的登录接口被人用输入 `' OR '1'='1` 打穿了，任何密码都能登进去。这最可能是下面哪种代码导致的？","opts":["用 bcrypt 哈希密码","SQL 用了字符串拼接用户输入（未参数化）","给 username 加了唯一索引","登录返回了 401"],"a":1,"explain":"把用户输入直接拼进 SQL 会造成 SQL 注入——输入里含有的引号和 OR 让查询恒真，从而绕过密码。改成参数化查询即可堵住。","jump":"sec8","jumpLabel":"深入一点的 SQL 注入示范段"},{"type":"check","title":"结课检测：数据库与安全你真的懂了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"用户的‘收藏表’要关联用户和文章，最正规的做法的核心是？","opts":["把所有用户名和文章名塞进同一列","用外键 user_id 和 article_id 分别指向用户表、文章表的主键","每次复制一份用户表","收藏不存数据库"],"a":1,"explain":"用外键指向各自表的主键，才能表达‘哪个用户收藏了哪篇文章’的关系且不重复存储。","jump":"sec5-step3"},{"q":"密码正确的存储方式是？","opts":["明文存进 password 列","加密（可逆）后存","加盐哈希（如 bcrypt）后存，且不存明文","存进 cookie"],"a":2,"explain":"哈希是不可逆的，任何人不包括你自己都无法还原密码，只能用于比对；加盐防止相同密码产生相同哈希。","jump":"sec5-step4"},{"q":"SQL 注入的根本防御是？","opts":["在前端把输入框禁用","用参数化查询（占位符）","把数据库放到公网","把 SQL 写成大写字母"],"a":1,"explain":"参数化查询把用户输入当作数据而不是可执行的 SQL 代码，因此注入失效。","jump":"sec8"},{"q":"Session 与 JWT 的区别，哪句最准确？","opts":["Session 把状态存服务器，JWT 把身份信息加密进令牌交给客户端","两者完全一样","JWT 不能加密","Session 只用于 HTTPS"],"a":0,"explain":"Session 服务端有状态、可随时注销；JWT 无状态、令牌自证身份，适合多端，但签发后较难在过期前撤销。","jump":"sec6"},{"q":"别人的博客里嵌了你的登录页代码，结果是坏人代码执行——这属于用什么方式防御的问题？","opts":["SQL 注入","XSS 跨站脚本","数据库索引","密码哈希"],"a":1,"explain":"把脚本塞进页面内容让浏览器执行的是 XSS，防御靠输出转义 + CSP 等；这不是 SQL 注入（那是打数据库的）。","jump":"sec6"}],"done":"你现在能看懂表结构、能审 AI 的建表与登录代码、知道 Session/JWT/OAuth 怎么选、也知道 SQL 注入/XSS 怎么防。下一课我们把这一切真正‘送上线’：从本地 Demo 变成一台公网可访问、稳定可回滚的真实产品。","nextLesson":"v07-deploy"},{"type":"connection","known":["你知道后端通过 API 和数据库交互（上一课）。","你知道数据要长期保存、要按关系组织（本课）。"],"learned":["数据库用表组织数据：列、行、主键唯一、外键关联、索引加速","SQL 增删改查与参数化防注入","登录三方案：Session 存服务端 / JWT 自证令牌 / OAuth 第三方授权","安全四原则：密码哈希、SQL 参数化、输出转义、后端校验"],"next":"数据和身份都准备好了，下一步是把它们‘送上线’。这与 AI 路径的联系：当你要做的是 AI 产品（如 RAG 问答），RAG 的向量库也是一种‘数据库’，登录/安全同样适用。下一课《从本地 Demo 到正式上线》会把 部署、健康检查、回滚 讲透。","links":[{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——了解向量数据库在 AI 产品里的角色"},{"href":"#/lesson/l20-ai-eng","text":"回看 AI 路径《AI 工程：从原型到生产》(规划中)"}]}]},"v05-test":{"id":"v05-test","title":"测试与调试：让 bug 无处可藏","subtitle":"AI 写的代码‘看起来对’不代表真的对。测试就是给代码挂号看病：把你担心的每一种情况写成‘处方’，让机器自动反复验证。","course":"vibe","courseNo":"05","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":["testing","debugging","test-driven","error-handling"],"prereqLessons":["v04-db"],"nextLesson":"v06-arch","sections":[{"type":"opening","question":"AI 帮你写完功能，你点了一下‘看起来正常’。但这只证明‘这一种情况正常’。如果用户传了空值、超长文本、重复提交，或者网速很慢时呢？它会不会悄悄出错？","guess":"很多人把‘点一下没坏’当成‘没问题’，等上线后才被用户骂出 bug。","next":"这一课让你从‘靠感觉’升级到‘靠验证’：学会写测试，让机器替你一遍遍检查；学会高效调试，遇到 bug 能用工具精准定位而不是瞎猜。"},{"type":"why","before":"你用 AI 快速堆了很多功能，但每次改一处就怕另一处坏，全靠人工点来点去，又慢又容易漏。","problem":"没有测试时，回归风险（改这坏那）全靠人肉；bug 只在线上被用户撞到；调试时踢‘玄学’，分不清是前端、后端还是数据。","need":"你需要一套‘自动验证’体系：把正常/极限/出错的情况固化成测试，任何改动跑一遍就知道坏没坏；再加一套科学的调试流程，快速锁定问题根因。"},{"type":"oneline","text":"测试 = 用代码检查代码：把你关心的输入和期望输出写成断言，让程序自动运行并告诉我们‘通过’还是‘失败’；调试 = 当失败发生时，用日志、断点、报错信息逐层缩小范围，找到并修掉根因，再补一条测试防止它复发。"},{"type":"visual","kind":"http-viewer","title":"互动实验：把一次请求拆开‘调试’","hint":"查看一次请求的完整信息（请求方法/参数/状态码/响应体）。当功能表现不对时，先看请求对不对、状态码对不对、响应对不对——绝大多数 bug 都能在这一层现行。"},{"type":"intuition","blocks":[{"k":"用医生体检来想","t":"测试就像定期体检：你不是‘感觉健康’，而是用仪器（测试用例）一项项量。体检结果红灯/绿灯，告诉你哪里该治。改完代码再‘体检’一次，确认没有新问题（回归）。"},{"k":"用过安检来想","t":"每次上线前，测试就是‘安检门’：正常行李、液体、打火机、可疑物品各走一遍（边界与异常用例）。安检没拦下问题，才会漏到线上。"},{"k":"一句话记住","t":"测试管‘它该不该错’（验证正确性），调试管‘它为什么错’（找根因）。两者配套：写了测试的 bug 更好调，调完的 bug 最好补测试防复发。"}]},{"type":"how","intro":"科学调试 + 自动测试的完整闭环，六步。","steps":[{"in":"① 复现：先让它稳定地出错","process":"调试第一步是把 bug 稳定复现——找出输入、操作、环境的组合。‘偶现’的 bug 最难调，先尽量锁定触发条件。","out":"一个能稳定触发问题的操作路径"},{"in":"② 读报错：从报错和日志定位层","process":"查看报错来自哪一层（前端控制台/后端终端/数据库）。报错信息 + 堆栈 + 日志是缩小范围的雷达。","out":"判断问题最可能在哪一层、哪个文件哪一行"},{"in":"③ 缩小范围：二分法 / 断点","process":"在可疑处打断点或加日志，看变量值是否符合预期。用二分法：先确认一半流程没问题，再把怀疑区切半，快速收敛。","out":"定位到具体的错误代码位置"},{"in":"④ 修复 + 写一条测试","process":"修掉根因（不是表面掩盖），然后写一个能复现此 bug 的测试用例，确保以后不会再犯（回归测试）。","out":"修复完成，且有测试保驾护航"},{"in":"⑤ 跑测试套件","process":"运行整套测试，确认修复没弄坏别的地方。测试套件就是你的‘回归安检门’。","out":"红灯/绿灯：全部通过则放心，有红灯继续修"},{"in":"⑥ 交给 AI 辅助：带着上下文提问","process":"把‘复现步骤 + 报错 + 相关代码 + 我试过的’交给 AI，让它给假设与修复建议；你验证后再落地。","out":"更快地解决复杂疑难 bug"}]},{"type":"realworld","items":[{"name":"单元测试（最小函数）","note":"测一个函数/一个输入输出对：‘输入 3 和 4，应当返回 7’。粒度最小、跑得最快、最稳。"},{"name":"集成测试（多个模块配合）","note":"测‘后端接口读数据库再返回正确结构’这种跨模块流程，确认各部分协作正确。"},{"name":"端到端测试（模拟真实用户）","note":"自动开浏览器，模拟用户点按钮、填表单、走完整流程，确认产品级行为正常。"},{"name":"让 AI 帮你写测试","note":"把函数/接口描述给 AI，让它生成覆盖正常、边界、异常的测试用例。再由你补充‘你的产品里最怕坏的那几条’。"}]},{"type":"compare","pairs":[{"a":"单元测试","b":"端到端测试","diff":"单元测试只测单个小函数，快而稳；端到端测试模拟整个真实流程，覆盖广而慢。两者互补，前者定位快，后者保整体。"},{"a":"调试","b":"测试","diff":"调试是当下找并修现有 bug 的根因；测试是把‘该对的不变错’固化成自动化验证，防止未来回归。调试解决‘现在’，测试守住‘以后’。"},{"a":"人肉点验","b":"自动化测试","diff":"人肉点验靠眼、易漏、难重复；自动化测试靠代码、可重复、可长时间回归。AI 时代的快节奏尤其需要自动化兜底。"},{"a":"掩耳修 bug","b":"修根因","diff":"表面掩盖（如删掉报错）下个输入还会炸；修根因 + 补测试才是一劳永逸。"}]},{"type":"mistakes","items":["只测‘正常情况’，不测空值/超长/重复/超时等边界——线上都是在边界炸的。","改完代码不重跑测试——回归 bug 悄悄溜回去。","看到报错就贴给 AI，不先自己读——先定位‘哪一层、哪个文件’，AI 才能精准。","写测试只求‘通过’不求‘有意义’——骗过自己的测试没有价值。","把 .env 密码打进日志——泄露风险大于 bug 本身。"]},{"type":"ask","title":"怎么用 AI 帮你调试：给足四件套","scenario":"你的接口偶尔返回错误，你想让 AI 帮你定位。","template":"[现象] 点击保存后约 20% 概率报 500 错误，多数时候正常。\n[复现] 连续快速点两次保存，必现。\n[报错] 后端日志：TypeError: Cannot read properties of undefined (reading 'id') at line 88.\n[我试过] 单次保存正常；怀疑是重复提交/竞态导致请求对象未就绪。\n[请给我] 判断根因最可能是什么，并给出修复 + 回归测试方案。","acceptance":["AI 是否先确认了复现条件与报错层级？","是否给出根因判断而非简单贴代码？","是否提供修复 + 一条防复发的测试？","是否提醒测试边界（重复提交/空值）？"],"tip":"调试提问的黄金四件套：现象 + 复现 + 报错 + 我试过的。越具体，AI 越能帮你一击命中。"},{"type":"exercise","prompt":"你的功能‘在本地点一下没问题’，但你最担心上线后被用户遇到奇怪输入就崩。下面哪个做法最能防患于未然？","opts":["相信 AI 写的没问题，不测","补上正常/边界/异常的自动化测试，并在每次改动后重跑","只在发布当天人工多点点","把报错用 try-catch 吞掉不上报"],"a":1,"explain":"把担心的情况固化成自动化测试（正常/边界/异常）并持续回归，才是防患于未然的正道；try-catch 吞错只会掩盖问题。","jump":"sec5-step4","jumpLabel":"补测试防复发这一步步"},{"type":"check","title":"结课检测：你会给代码看病了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回对应段落复习。","questions":[{"q":"‘回归测试’主要为了防止什么？","opts":["新增功能太少","改了这处却弄坏了之前能用的功能","代码写了注释","部署变慢"],"a":1,"explain":"回归测试是在每次改动后重跑，确保‘不该变错’的旧功能没被新改动弄坏。","jump":"sec5-step4"},{"q":"调试一个‘偶发’bug 的第一步是什么？","opts":["直接重写整个模块","先想办法稳定复现它，锁定触发条件","立刻上线再观察","删掉报错"],"a":1,"explain":"先稳定复现并锁定触发条件，才能进一步定位；偶发 bug 最难调，复现是第一步。","jump":"sec5-step0"},{"q":"下面哪一类测试粒度最小、跑得最快？","opts":["端到端测试","单元测试","集成测试","人工测试"],"a":1,"explain":"单元测试只测单个小函数，粒度最小、最快最稳；端到端最慢。","jump":"sec6"},{"q":"把 bug 交个 AI 之前，最有效的准备是？","opts":["只发一句‘它坏了帮我修’","提供现象 + 复现步骤 + 报错 + 我试过的","什么都不说让 AI 猜","先删掉相关代码"],"a":1,"explain":"四件套（现象/复现/报错/已试过）让 AI 快速定位根因，避免无效往返。","jump":"sec7"}],"done":"你现在既能用测试预防 bug，又能用科学流程调试 bug，还能让 AI 高效地帮你。下一课把目光放回代码本身：怎么组织项目结构，让一开头乱成一团的代码变得清晰可维护。","nextLesson":"v06-arch"},{"type":"connection","known":["你已了解后端 API、数据库（v03/v04）与分层思想（v01）"],"learned":["测试 = 自动验证正确性；调试 = 定位并修根因，两者互补","复现→定位→修复→补测试→回归的科学调试闭环","单元/集成/端到端测试的区别与分工","给 AI 调试提问的黄金四件套"],"next":"测试守住质量底线，下一步我们要管好代码本身的结构：让工程量变大时依然清晰、好扩展、好维护。","links":[{"href":"#/lesson/v06-arch","text":"下一课：《项目结构与代码组织》"},{"href":"#/lesson/v04-db","text":"回看《数据库、登录与安全》"}]}]},"v06-arch":{"id":"v06-arch","title":"项目结构与代码组织","subtitle":"AI 会把所有代码一股脑塞进一两个文件。功能少时没事，功能一多就变成没人敢动的‘意大利面’。这节课教你给项目‘装修’，让它清晰、好扩展、好维护。","course":"vibe","courseNo":"06","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":["project-structure","code-organization","modularity","refactoring"],"prereqLessons":["v05-test"],"nextLesson":"v07-deploy","sections":[{"type":"opening","question":"你的项目从 2 个文件长到了 20 个文件。现在你想加一个‘分享’功能，却要改 6 个文件，每改一处都怕碰坏别处。AI 也越帮越乱——它不知道你的项目现在长什么样。","guess":"很多人选择‘忍’，或者干脆重写一个更乱的项目。","next":"这一课教你如何规划项目结构：怎么分文件夹、怎么分层、怎么拆分组件，让代码像整理好的衣橱一样‘东西各有其位’。结构清晰，AI 才能准确帮你改，你才不会改一处崩三处。"},{"type":"why","before":"你在 Vibe Coding 里让 AI 快速堆功能，很快发现文件多、职责乱、命名随意，连你都不敢轻易动。","problem":"结构混乱的代价：改一处崩三处、加功能要动一堆文件、AI 因为看不懂全貌而瞎改、你无法确认改动影响面。","need":"你需要一个清晰的项目骨架：明确的分层、职责单一的模块、合理的命名与目录。这样无论是你还是 AI，都能‘小范围定位、大胆改动、放心验证’。"},{"type":"oneline","text":"好的项目结构 = 按‘职责’而不是‘随意’组织的代码摆放：前端/后端/数据分层清晰，每个模块只做一件事，文件命名即职责，改动影响面小、可测试、可替换。它是让‘小项目’能长大成‘可维护产品’的地基。"},{"type":"intuition","blocks":[{"k":"用整理衣柜来想","t":"衣柜分格：上衣一格、裤子一格、袜子一格，找衣服（找代码）快、放回去不乱。如果把所有衣服扔进一个大抽屉（一个 giant 文件），找什么都翻半天，还容易拿错。"},{"k":"用餐厅分工来想","t":"一个好的餐厅有明确分工：前台点单、后厨做菜、仓库备料、财务算账，各司其职。一个烂餐厅‘一个人啥都干’，热闹时必崩。代码分层同理：页面只管展示，逻辑只管处理，数据只管存取。"},{"k":"一句话记住","t":"‘职责单一 + 分层清晰 + 命名即职责’。看到文件名就知道它管什么；改一个功能只动最少文件。这就是可维护性的全部秘密。"}]},{"type":"how","intro":"从混乱到清晰的三步整理法。","steps":[{"in":"① 按层分目录（横向分层）","process":"按‘类型/职责’分开：前端代码、后端代码、数据库相关、配置、测试、静态资源各放各目录。例：src/、api/、db/、tests/、config/、public/。","out":"横向分层清晰，一眼看懂项目由哪几块组成"},{"in":"② 按功能分模块（纵向拆块）","process":"在一个层内部再按功能拆分：比如‘用户’、‘订单’、‘分享’各自成模块，模块内部再包含自己的逻辑/子文件。一个文件只负责一个功能点。","out":"纵向模块化，加功能影响面收窄到单一模块"},{"in":"③ 命名即职责 + 收敛公共部分","process":"文件/函数命名说清职责（userService.js 管用户逻辑、db.js 管连接）。把重复出现的代码抽成公共函数，避免复制粘贴三遍。","out":"可读性提升，改动点集中，易于测试与替换"},{"in":"④ 找 AI 重构（带着结构上下文）","process":"把‘当前目录结构 + 你要的目标结构/问题’给 AI，让它帮你拆分、抽取、重命名。分小步做，每步后跑测试验证。","out":"借助 AI 快速完成结构整理且不破坏功能"}]},{"type":"realworld","items":[{"name":"前后端分离","note":"前端代码和后端服务分开目录（甚至分开仓库/部署），职责完全不同，各自独立演化与测试。"},{"name":"一个文件只做一件事","note":"giant 文件是最大的敌人：几百行的单一文件难读难测难改。拆成职责清晰的小文件/函数。"},{"name":"配置与代码分离","note":"数据库地址、密钥、端口等‘环境相关’配置放 config 或环境变量，别硬编码进代码，便于本地/线上切换。"},{"name":"测试与源码平行","note":"测试文件和被测代码放在对应/平行的目录，改动时容易同步维护。结构清晰才能让‘改这里测那里’成为日常。"}]},{"type":"compare","pairs":[{"a":"扁平大文件","b":"分层分模块","diff":"扁平把所有逻辑塞一起，难读难测；分层次、分模块按职责归位，定位快、影响面小。"},{"a":"复制粘贴复用","b":"抽取公共函数","diff":"复制粘贴三遍，改一处要改三处且易漏；抽成公共函数单点维护，一处改动全局生效。"},{"a":"随意命名","b":"命名即职责","diff":"随意命名（a/b/temp）看不懂；命名即职责（saveUser）看到名字就知道干什么、改哪找哪。"},{"a":"硬编码配置","b":"配置分离","diff":"硬编码密钥/地址难切换且易泄露；配置分离便于本地/线上切换与安全。"}]},{"type":"mistakes","items":["把所有代码塞进一个 main 文件——看一眼就头大，AI 也会改错。","不设目录分层，东放一个西放一个——找不到文件该在哪。","命名随意（a/b/test12）——神仙也看不懂。","一个函数干八件事——难测难调。职责单一才可测。","重构一上来就大动干戈——高风险。小步重构 + 每步测试，才稳。"]},{"type":"ask","title":"怎么用 AI 帮你整理结构：把当前全貌给出去","scenario":"你的项目文件越来越乱，想请 AI 帮你重构组织。","template":"[现状] 我的项目目前文件都在根目录：main.js（约 300 行）、utils.js、data-handler.js… 没有分目录。\n[目标] 我想整理成前端/后端/配置/测试分层的清晰结构，并让每个文件职责单一。\n[约束] 不能破坏现有功能，我有测试可以验证；请分小步提出重构方案，每一步不要动太多。\n[请给我] 先给出目标目录结构与分工建议，再给按小步执行的拆分清单。","acceptance":["AI 是否先了解现有结构再动手？","是否给出分层/模块化的目标结构，而不只是‘把文件挪一挪’？","是否建议小步重构 + 测试验证，避免一次性大动？","是否提醒命名即职责、公共部分收敛？"],"tip":"把‘当前结构 + 目标 + 约束（不能坏、有测试）+ 请小步’交给 AI，它会给你靠谱的重构方案。别让它‘直接重构’，要先给方案。"},{"type":"exercise","prompt":"你的项目所有逻辑都挤在一个 400 行的 main.js 里，想让它便于维护。下面哪个做法是正确第一步？","opts":["一次性把 400 行全部重写成多个文件再跑","先按职责切分，小步把一块块功能抽到独立模块，并保持每次都还能跑 + 测试通过","继续加在一个文件里，方便 AI 找","删掉重写"],"a":1,"explain":"正确做法是小步按职责拆分，每拆一块仍能跑、测试仍过，逐步收敛；一次性大重写风险极高。","jump":"sec5-step3","jumpLabel":"找 AI 重构这一步步"},{"type":"check","title":"结课检测：你会给项目‘装修’了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回对应段落复习。","questions":[{"q":"项目结构清晰的主要好处是？","opts":["代码变少了","改动影响面小、定位快、易测试易维护","运行更快","AI 不需要了"],"a":1,"explain":"结构清晰的本质是降低‘改动成本与风险’：定位快、影响面小、可测、可维护。","jump":"sec5-step0"},{"q":"下面哪个符合‘职责单一’？","opts":["一个函数既渲染页面又查数据库还保存文件","一个模块只负责一件事：比如用户模块只管用户","把所有逻辑写一个函数里","一个文件放所有样式和逻辑"],"a":1,"explain":"职责单一 = 每块代码只做一件清楚的事，这样才好测、好改、好复用。","jump":"sec5-step2"},{"q":"数据库地址、密钥这类配置应该放在哪里？","opts":["硬编码写死在代码里","放在 config/环境变量，与代码分离","放到前端页面","写进提交日志"],"a":1,"explain":"环境相关配置应与代码分离（config/环境变量）：便于本地/线上切换，也避免密钥泄露到代码与仓库。","jump":"sec6"},{"q":"重复出现三遍的同一段代码，最好怎么处理？","opts":["继续复制粘贴","抽成一个公共函数，单点维护","每次都重写一遍","交给 AI 不管"],"a":1,"explain":"抽成公共函数，一处改动全局生效，避免三处不同步的隐患。","jump":"sec5-step2"}],"done":"你的项目从‘意大利面’变成了‘有格子的衣橱’，自己和 AI 都能快速定位、安心改动。最后一关：怎么把这套东西从你电脑搬到真正的线上服务器，让全世界都能访问。","nextLesson":"v07-deploy"},{"type":"connection","known":["你已了解分层（v01）、后端 API（v03）、数据库（v04）、测试（v05）"],"learned":["结构清晰 = 职责单一 + 分层模块化 + 命名即职责","从混乱到清晰的整理法：分层→分模块→命名/收敛公共→AI 辅助小步重构","前后端分离、配置分离、测试平行摆放","小步重构 + 测试验证的原则"],"next":"结构理清了，最后一步就是把它送上线：怎么从‘本地能跑’变成‘人人能访问’。部署是 Vibe 路径的临门一脚。","links":[{"href":"#/lesson/v07-deploy","text":"下一课：《从本地 Demo 到正式上线》"},{"href":"#/lesson/v05-test","text":"回看《测试与调试》"}]}]},"v07-deploy":{"id":"v07-deploy","title":"从本地 Demo 到正式上线","subtitle":"代码在你自己电脑上能跑，不算数；让全世界都能访问、且挂了能快速恢复，才是‘上线’。这一课讲清楚那条从 localhost 到公网的最后一公里。","course":"vibe","courseNo":"07","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api","v04-db"],"nextLesson":"v08-workflow","sections":[{"type":"opening","question":"你的产品在自己电脑上跑得欢，你联调、测试都通过了。现在要把它放到公网，让外地、外网、别家浏览器都能访问——为什么这件事永远比想象中麻烦？常见的‘本地正常、线上挂掉’到底差在哪？","guess":"很多人以为‘上线就是把文件传到服务器上，然后就能用了’。","next":"这一课我们拆解上线全流程：环境如何保持一致（环境变量）、如何把项目部署到服务器/云平台、域名与 HTTPS 怎么配、上线后怎么确认它是‘健康的’（健康检查）、出问题怎么快速回滚、以及要不要上 CI/CD。学完后你拥有的能力是：把 AI 做的 Demo 安全地变成可上线产品，并知道每一步万一失败该怎么退回来。"},{"type":"why","before":"你写好了产品，AI 也说‘好了，部署吧’。可你一部署，报‘连接数据库失败’‘端口被占用’‘找不到 .env’‘静态资源 404’……你完全不知道从哪查起，只能一遍遍粘日志给 AI，反复重装环境。","problem":"本地与线上天然不同：路径不同、数据库地址不同、端口不同、依赖版本可能不同、还要面对公网连接、域名、HTTPS 证书、防火墙。如果你没有‘环境一致性’与‘可回滚’的意识，即使这次勉强跑起来，下次改动也会随时把线上搞挂而无法恢复。","need":"掌握上线的最小可靠流程：用环境变量（.env）把差异集中管理；部署常走三大路径（静态托管 / PaaS 平台 / 自管服务器）分别怎么选；配域名 + HTTPS；加‘健康检查’让系统自己喊救命；上线清单与回滚流程让‘挂了也能退回去’。这是把 Demo 变成产品的临门一脚。"},{"type":"oneline","text":"上线 = 把代码 + 环境一致地搬上公网机器 + 配好域名/HTTPS + 挂上健康检查 + 准备好一键回滚。核心三句话：环境用变量隔离差异（不同环境不同值）、部署用脚本/平台保证可重复（别靠手敲）、发布用‘灰度/可回滚’控制风险（挂了能退）。"},{"type":"visual","kind":"deploy-console","title":"互动实验：部署控制台，看一次完整上线","hint":"这是一个模拟部署终端：点‘部署’会经历 构建 → 迁移 → 健康检查 → 流量切换；如果健康检查失败，系统会拒绝放量并自动回滚到上一个版本。你还能故意制造‘健康检查失败’来亲眼看到回滚是怎么保命的。"},{"type":"intuition","blocks":[{"k":"用开餐厅来想","t":"本地 Demo 像在你的厨房试菜——火候是你自己调好的、食材在你冰箱里。上线＝在商业街上开正式的餐厅：要租店面（服务器）、接水电气（网络/HTTPS）、换统一采购的食材（数据库搬到线上）、店员按标准作业（健康检查/监控）、万一某天厨房着火（服务挂）要能立刻换上备用后厨（回滚/容灾）。‘本地试菜’和‘正式营业’根本不是一回事。"},{"k":"用电梯/红绿灯来想健康检查","t":"健康检查＝系统自己定时喊一嗓子‘我还活着’（探测 /health 接口）。就像电梯每隔几秒报一次运行状态。如果它不喊了，编排系统（如负载均衡）就把它踢出队伍并拉起一个新的——而不是让用户对着白屏干等。"},{"k":"一句话记住上线","t":"环境变量隔离差异 → 构建产物可重复 → 部署到线上 → 健康检查确认活着 → 出问题回滚上个版本。五个动作，缺一不可；其中‘能回滚’是你最后的保险绳。"}]},{"type":"visual","kind":"llm-retry","title":"互动实验：给 LLM 调用加上超时 + 重试 + 回退","hint":"你的产品里调了大模型 API（这也是你 AI 产品的‘后厨’）。网络抖动/超时/限流在线上是家常便饭。这个实验模拟‘调用 → 超时 → 重试 → 回退(fallback)’，体会电商级 API 调用为什么要设计超时与降级。这也是 Vibe Coding 路径与 AI 路径的连接点。"},{"type":"how","intro":"把一次‘安全上线’拆成 6 步：每一步都有明确的‘成功标志’和‘失败补救’。","steps":[{"in":"① 环境变量：把差异抽出来","process":"本地/测试/线上需要不同的数据库地址、密钥、端口。把它们写进环境变量（如 .env 文件或平台面板），代码里用 process.env.XXX（Node）/ os.environ（Python）读取，而不是写死。","out":"代码与环境解耦：同一份代码换环境即可"},{"in":"② 构建 + 迁移","process":"前端打包成静态文件（npm run build → dist/）；数据库结构变化用迁移脚本（migration）跑一遍。构建产物要是‘可重复’的——同一份源码应产出同样的产物。","out":"得到一个可直接发布的‘构建物’+ 数据库就绪"},{"in":"③ 部署到线上","process":"三大路径：静态托管（页面纯前端，丢到 GitHub Pages/CF Pages/OSS 即可）；PaaS 平台（Vercel/Netlify/Railway/Render，把代码推送即可自动部署，适合新手与中等项目）；自管服务器（买 ECS/VPS，自己配 Nginx + 进程守护如 PM2/systemd）。新手从 PaaS 起步最稳。","out":"公网可以访问你的服务"},{"in":"④ 域名 + HTTPS","process":"买个域名，把 DNS 解析到你的服务（A 记录指向 IP / CNAME 指向平台）；再签 HTTPS 证书（平台自动，或云厂商+Letʼs Encrypt），让访问走 https:// 加密。浏览器地址栏的小锁 = 加密。","out":"用户通过好记的 https://你的域名 访问"},{"in":"⑤ 健康检查 + 监控","process":"后端提供 /health 接口（返回 200 + 状态）。负载均衡/编排平台每 X 秒探测它：活着→正常放量；不活→摘除并重启该实例，同时报给你（监控告警）。","out":"系统自己‘喊救命’，而不是等用户来报"},{"in":"⑥ 发布即回滚预案","process":"大型发布用‘灰度’：先 10% 流量验证，稳妥再全量；每版都保留上一个版本，发现异常立刻一键回滚（切回旧版本）。回滚能力 = 你改线上时的底气。","out":"即使新版本有问题，也可在几分钟内恢复"}]},{"type":"realworld","items":[{"name":"GitHub Pages（本站就是这么上线的）","note":"纯前端静态站可直接推到 GitHub Pages，免费公网、自带 HTTPS。适合‘文档/演示/静态首页’。注意它只托管静态资源，没有后端/数据库——需要后端的要另选 PaaS 或 VPS。"},{"name":"Vercel / Render / Railway（PaaS）","note":"‘连上 Git 仓库，push 即部署’：自动构建、自动 HTTPS、给环境变量面板、自动健康检查与回滚。是前端+轻后端产品（含 Next.js 全栈）最省心的上线方式。"},{"name":"云服务器 + 进程守护（VPS）","note":"腾讯云/阿里云的 ECS 上装 Node/Python、用 PM2/systemd 守护进程、Nginx 反代 + HTTPS。灵活可控但维护成本高。适合要自己掌控环境、或者后端较重/要连自己数据库的产品。"},{"name":"CI/CD（持续集成/持续部署）","note":"把‘测试 → 构建 → 部署’做成流水线：你 push 代码，系统自动跑测试并部署。好处是上线行为可重复、可审计；新手至少理解它的存在，平滑后再引入 (如 GitHub Actions)。"}]},{"type":"compare","pairs":[{"a":"静态托管（GitHub Pages/OSS）","b":"PaaS 平台（Vercel/Render）","diff":"静态托管只能放纯前端静态文件、无后端、一般免费；PaaS 能托管前端+后端（有的带数据库），源码推送自动构建/部署/HTTPS，更适合‘有后端的完整产品’。纯静态选前者，有后端选后者。"},{"a":"PaaS 平台","b":"自管云服务器（VPS+PM2+Nginx）","diff":"PaaS 帮你管环境、自动部署、内置回滚，省心但灵活度有限；VPS 完全可控（能装任意软件）但要自己维护系统、进程守护、HTTPS、备份，运维成本高。新手/中小产品从 PaaS 起步，要深度控制再上 VPS。"},{"a":"环境变量 .env","b":"写死在代码里","diff":"环境变量让同一份代码在不同环境（本地/测试/线上）用不同配置，且密钥不进代码库；写死会导致‘本地行、线上不行’，且密钥泄露风险大。必须用环境变量管理差异与密钥。"},{"a":"健康检查 /health","b":"用户报错才知道挂了","diff":"健康检查是主动、自动、秒级的探活，挂了立刻摘除重启并告警；等用户报告则被动、慢、伤口碑。生产环境必须有健康检查。"}]},{"type":"mistakes","items":["错误案例①：把数据库连接串、API 密钥写死在代码/前端里并 push 到公开仓库——等于把保险柜密码贴在门口。密钥必须进环境变量并严格保密。","错误案例②：没有环境意识，‘本地跑通了就认为线上能跑’。正确的验证方式：线上部署后跑一遍健康检查 + 真实浏览器访问，而不是‘本地 200 就完事’。","错误案例③：上线直接改线上数据库结构却不做迁移回滚——出事退不回去。数据库结构变更要保留迁移脚本、可逆可回退。","错误案例④：追逐‘最新框架/功能’把线上当实验场，改一次崩一次却没有任何回滚按钮。生产稳定 > 炫技；改版前后都要有一键回滚能力。","错误案例⑤：把‘调大模型 API’当成不会失败——线上网络抖动、超时、限流很常见。不给 API 调用加超时/重试/回退(fallback) 的 AI 功能，用户会频繁看到转圈/报错。"]},{"type":"deep","title":"深入一点：一次失败的线上事故是怎么被救回来的","beginner":["把‘回滚像不像重装系统’想明白：回滚不是把线上机器清空重装，而是‘把流量切回上一个已知良好的版本镜像/构建物’。现代平台（PaaS、容器编排）都保留旧版本，一键切换即可，秒级恢复。","健康检查的 /health 接口长什么样？就是一个后端路由，返回 200 和一个简单的 JSON：`{status:'ok'}`。它常常还会顺带检查数据库能否连上。如果数据库挂了，/health 也会返回失败——这样编排系统才会判断这台机器‘不健康’并把它踢出去。"],"advanced":["**一次事故的完整剧本**：新版本把数据库连接串写错 → 部署平台探测 /health → 数据库连不上 → /health 返回 500 → 平台判定‘不健康’→ 拒绝放量 / 自动回滚到旧版本 → 监控告警发到你手机 → 你看日志定位到环境变量拼错 → 修正后重新部署。全程用户几乎无感知。这就是‘健康检查 + 回滚 + 监控’三件套的价值。","**LLM 调用的可靠性设计（与 AI 路径的接口）**：真实产品调大模型 API 时，用模式是‘超时 + 指数退避重试 + 回退（缓存结果 / 备用模型 / 返回友好提示）’：","```js\nconst response = await fetchLLMWithRetry({\n  prompt, timeoutMs: 8000,            // 超时：8 秒没回应就放弃重试\n  retries: 3, backoffMs: 1000,         // 重试 3 次，指数退避\n  fallback: () => cache.get(key)       // 兜底：用缓存或降级文案\n});\n```","**上线检查清单（Checklist）**：①环境变量配全了吗？②数据库迁移跑了吗？③HTTPS 生效了吗（浏览器锁）？④/health 探针过吗？⑤日志与告警接了吗？⑥旧版本能一键回滚吗？⑦真实浏览器/多设备验证了吗？全部打勾，才算一次‘可上线发布’。"]},{"type":"ask","title":"怎么让 AI 帮你安全上线","scenario":"你的产品要第一次上线，不确定从哪下手、怕把线上搞挂。","template":"[我的产品] 是一个 [前端 + Node 后端 + PostgreSQL] 的小产品，目前只在本地能跑。\n[请给我] 一份最小可靠的上线方案：推荐用哪种托管方式（静态/PaaS/VPS）并说明理由；列出需要的环境变量清单；给出数据库迁移与开启 HTTPS 的步骤；提供 /health 接口示例与回滚预案。\n[验收标准] 每一步是否有明确操作与验证方法？是否包含失败时的回滚步骤？","acceptance":["部署方案是否说明了选型理由（静态/PaaS/VPS）与本产品的适配性？","环境变量清单是否完整且不包含明文密钥？","是否提供了可复现的部署步骤与验证方式（健康检查/浏览器访问）？","是否有明确的回滚/恢复预案，而不是‘挂了重装’？先小范围(灰度)验证再全量了吗？"],"tip":"上线是最不能‘赌一把’的环节。让 AI 给出‘选型 + 环境变量 + 验证 + 回滚’全套，再逐项打勾验收；任何一步读不懂就让 AI 解释‘为什么这样做’，直到你能复述为止。"},{"type":"exercise","prompt":"你上线了新版本，负载均衡探测 /health 连续几次都返回 500。接下来最正确的自动动作是什么？","opts":["继续放大流量，等用户反馈","把该实例摘除并自动回滚到上一个良好版本","重启浏览器","删掉数据库"],"a":1,"explain":"健康检查失败说明新版不健康，应把它踢出流量并回滚到上一版本，让用户在无感知的情况下继续使用。","jump":"sec7-step4","jumpLabel":"第 ⑤ 步：健康检查 + 监控"},{"type":"check","title":"结课检测：你的上线观念成立了吗","intro":"共 5 题。全部答对可进入下一节后续课程（或视为完成本路径第一批）。","questions":[{"q":"‘本地跑通 = 线上一定能跑’这句话？","opts":["完全正确","错误，本地与线上环境(变量/依赖/数据库)常不同，需部署后验证","只对前端成立","只对数据库成立"],"a":1,"explain":"环境差异（连接串、密钥、依赖版本、端口）是‘本地行、线上挂’的常见原因，必须部署后做健康检查与真实访问验证。","jump":"sec4"},{"q":"数据库地址、API 密钥这类差异应当怎么管？","opts":["写死在代码里方便","放进环境变量按环境区分，且密钥不进代码库","藏在注释里","放前端页面里"],"a":1,"explain":"环境变量让同一代码适应不同环境、密钥不进仓库，安全且可维护。","jump":"sec5-step0"},{"q":"完全不会写代码、只想让前端+后端都能自动上线，最省心的选项是？","opts":["自建机房","PaaS 平台（如 Vercel/Render），连 Git push 即部署","用纯记事本手写服务器脚本","不部署"],"a":1,"explain":"PaaS 负责构建、部署、HTTPS、健康检查与回滚，对新手最友好；VPS 更适合要深度控制的高级场景。","jump":"sec7"},{"q":"/health 健康检查的探测失败时，编排系统最合理的动作是？","opts":["什么都不做","摘除不健康实例并重启/拉起新的，必要时候选回滚","把数据库清空","关掉域名"],"a":1,"explain":"自动摘除+重启，必要时回滚旧版本，让用户几乎无感知；同时告警提醒你排查。","jump":"sec7-step4"},{"q":"调用大模型 API 时，‘超时 + 重试 + 回退(fallback)’组合主要防范什么？","opts":["防止代码有语法错误","线上网络抖动、超时、限流导致的偶发失败","防止数据库被删","防止前端样式错乱"],"a":1,"explain":"线上第三方 API 偶发失败是常态，超时避免无限等待、重试提高成功率、回退(缓存/备用/友好提示)兜底，保证用户体验不崩。","jump":"sec7"}],"done":"你已经掌握了从 localhost 到公网‘最后一百米’的全部关键：环境变量隔离、部署三路径选型、域名+HTTPS、健康检查、回滚预案、上线清单。Vibe Coding 第一批四门课到此收官——你已经能看懂代码结构、判断接口与数据库靠不靠谱、把 Demo 安全上线了。","nextLesson":""},{"type":"connection","known":["你知道一个 Web 产品如何分层（课1）、前后端怎么通信（课3）、数据怎么存与登录安全（课4）。","你会调大模型 API / 了解 RAG、Agent（AI 路径）。"],"learned":["环境变量隔离本地/测试/线上差异，密钥不进代码库","部署三路径：静态托管 / PaaS / 自管 VPS，以及各自适用场景","域名 + HTTPS（浏览器小锁）怎么配","健康检查(/health)探活 + 监控告警，挂了自动摘除","灰度 + 一键回滚 = 改线上时的底气；上线检查清单"],"next":"Vibe Coding 第一批四个环节到此闭环：看懂 → 懂接口 → 懂数据/安全 → 懂上线。下一步安排：第二批课程将覆盖 前端与语言基础（课2）、终端与 Git（课5）、存储缓存与测试排错（课6）、系统设计与 AI 产品工程（课8）。与本路径之外的联系：AI 产品的上线同样遵循本课原则，且多了‘LLM 调用可靠性’（超时/重试/回退）这一环——已在课 7 实验里有真机感受。","links":[{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"},{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——AI 产品上线的数据侧"},{"href":"#/lesson/l-agent","text":"回看 AI 路径《Agent：让 AI 自己动手做事》——Agent 产品化时的可靠性思考"}]}]},"v08-workflow":{"id":"v08-workflow","title":"用 AI 完整做一个产品：全流程实战","subtitle":"前面七课把每一块都讲透了。这一课把它们串成一场完整实战：从一句话想法开始，走完立项、搭建、版本、联调、测试、部署，最终上线一个能给朋友用的真产品。","course":"vibe","courseNo":"08","level":"pro","estTime":"25-40 分钟","difficulty":3,"concepts":["full-workflow","product-launch","vibe-coding","mdv"],"prereqLessons":["v07-deploy"],"nextLesson":"","sections":[{"type":"opening","question":"你学完了：Web 链路、Git、API、数据库、测试、结构、部署。现在你把七块拼起来，用 AI 从零做一个真产品——比如‘家庭记账本’。你心里有完整的路线图，但你知道第一步该做什么、每一步怎么验收、在哪里最容易翻车吗？","guess":"很多人学完每课都很手痒，但真开始就面临‘从哪入手、怎么保证不烂尾、怎么保证上线安全’三大问题。","next":"这一课是收官实战：给你一套可直接照做的‘从想法到上线’端到端清单，串起前七课的全部能力。做完这课，你就是真正‘用 AI 独立做一个上线产品’的人了。"},{"type":"why","before":"你各环节都会一点，但没试过‘一口气走完全程’，担心翻车、烂尾、不知道每步到什么程度算 OK。","problem":"做一个真产品和做 demo 的区别：要能经受真实用户、真实数据、真实安全与真实故障。缺一个可照做的端到端流程，就容易卡在某一环或上线后翻车。","need":"你需要一条完整的实战流水线：每个阶段有明确目标、明确验收标准、明确翻车点与对策。学完立刻能复制到任意新项目。"},{"type":"oneline","text":"全流程实战 = 立项（一句话 + MVP）→ 骨架搭建 → 版本控制 → 前后端联调 → 数据与安全 → 测试 → 部署上线 → 上线后观察。八个阶段各含‘目标/验收/雷区’，串起来就是一套可复制的‘AI 产品生产线’。"},{"type":"visual","kind":"request-flow","title":"互动实验：走一遍上线后的一次完整请求","hint":"点‘发送请求’，用一个真实上线产品的视角，重走一次 用户→浏览器→DNS→网络→服务器→后端→数据库→回显，把 v01 到 v07 学的每一层验收一遍。这就是你上线产品每天在被执行的事。"},{"type":"intuition","blocks":[{"k":"用盖一栋楼来想","t":"立项=出图纸，骨架=打地基，Git=施工日志，联调=水电管线对接，测试=竣工验收，部署=交付入住，上线观察=回访保修。任何一步省掉，楼都住不安稳。"},{"k":"用做一顿饭来想","t":"备料（数据）、切配（分模块）、下锅（写功能）、尝味（测试）、装盘（部署）、上桌（上线）。每步都能‘尝一口’，别憋到最后才开火。"},{"k":"一句话记住","t":"小步快跑 + 每步验收 + 能回退 + 有测试防回归。把这四个关键词刻在流程里，任何项目都不会翻车。"}]},{"type":"how","intro":"从想法到上线的八阶段实战清单。每阶段都有验收标准。","steps":[{"in":"① 立项：一句话 + 最小 MVP","process":"把想法压缩成一句话：为谁解决什么。锁定最小可用范围（核心 1-2 个功能），暂不做锦上添花。","out":"一句需求 + MVP 边界清单","note":"这一阶段是产品判断，交给 AI 前先自己想清楚。"},{"in":"② 搭骨架：让 AI 生成基础工程","process":"把需求、技术选型、运行环境给 AI，让它一键生成可运行的基础工程（页面+后端+GIT 初始）。","out":"能跑的最小骨架","note":"把 v06 结构思想直接要求 AI 遵守。"},{"in":"③ 版本控制：立刻 git init + 首次提交","process":"骨架一跑通就 commit。自此每个‘能跑’版本都存档（v02），为后续折腾提供安全网。","out":"一个安全起点：首个可回退 commit","note":"‘能跑就提交’从第一步就开始做。"},{"in":"④ 前后端联调：核心功能跑通","process":"实现 MVP 的核心交互：前端调用 API（v03）、后端存取数据库（v04），把‘保存一条记录→回显’走通。","out":"核心功能端到端可用","note":"每接通一个接口就验证一次；别攒到最后一起测。"},{"in":"⑤ 数据与安全：别裸奔上线","process":"检查输入校验、密码加密、权限控制、.env 隐藏（v04）。把密钥放进环境变量并 .gitignore，绝不暴露在代码里。","out":"基础安全加固：校验+加密+权限+密钥隔离","note":"上线前必须过这一关。"},{"in":"⑥ 测试与收尾：补边界 + 回归","process":"写关键路径测试（v05）：正常/边界/异常用例；修 bug 补回归测试；整理结构让小步可维护（v06）。","out":"有自动化验证、可在后续改动中反复确认","note":"上线前至少覆盖核心链路。"},{"in":"⑦ 部署上线：搬到公网","process":"把本地跑通的版本部署到托管平台/服务器，配好环境变量、域名与 HTTPS（v07）。","out":"一个公网可访问的真实 URL","note":"本地没问题≠线上没问题，上线后立刻用真实地址自测。"},{"in":"⑧ 上线后观察：日志 + 收集反馈 + 迭代","process":"观察访问日志/报错，收集第一批真实用户反馈，按‘小步迭代’节奏继续发布新版本。","out":"持续迭代的活产品，而非一次性的 demo","note":"产品是‘上线才开始’，不是‘上线就结束’。"}]},{"type":"realworld","items":[{"name":"第一个版本只需要一个核心功能","note":"MVP 越小越容易成功上线。纪念版、仪表盘、多用户等先放 TODO，上线后再加。"},{"name":"让 AI 分模块生成","note":"不要一句‘帮我做个记账系统’；而是按 v06 结构分功能/分接口给 AI，逐个生成、逐个联调、逐个测试。"},{"name":"上线前过一遍安全清单","note":"输入校验、密钥不入库、权限默认拒绝、HTTPS——四条底线守住，避免上线即翻车。"},{"name":"把流程固化成模板","note":"把这 8 阶段存成自己的 CheckList，以后每个新项目都照跑一遍，效率和质量双保险。"}]},{"type":"compare","pairs":[{"a":"做 Demo","b":"做真产品","diff":"Demo 只要能演示关键功能；真产品要能扛真实用户、真实数据、安全与故障。流程完整、版本可控、测试兜底、安全到位。"},{"a":"一次性大开发","b":"八阶段小步","diff":"一次性憋大版本风险高、难回退；八阶段小步每步有验收与存档，翻车可回退。"},{"a":"先写代码","b":"先立项","diff":"先写代码容易做偏；先一句话立项 + MVP 边界，保证做得对再做得快。"},{"a":"上线即结束","b":"上线才开始","diff":"把上线当终点会烂尾；当做起点则持续观察、收集反馈、迭代，产品才越来越好用。"}]},{"type":"mistakes","items":["一上来就让 AI 写‘整个系统’——八成失控。按阶段、按模块小步走。","跳过大安全清单就上线——密钥泄露、可被随意改数据，上线即事故。","本地 OK 就当上线 OK——不部署真实地址自测，线上环境不同照样翻车。","不 commit / 不写测试——改坏了没法回退、回归全靠人肉，返工翻倍。","上线后不观察日志 ——用户报了 bug 你还不知道，产品口碑崩塌。"]},{"type":"ask","title":"怎么用 AI 全程辅助一个真实项目：阶段化提问","scenario":"你想做‘家庭记账本’，在不同阶段分别怎么向 AI 提问。","template":"[阶段①立项] 帮我把‘记录家庭每笔支出并生成月度统计’压缩成一个最小 MVP，给出核心功能清单和不要做的部分。\n[阶段④联调] 我的记账接口 GET /entries 报 500，报错在 db.js 第 20 行，这是日志：...，请定位根因并给修复+回归测试。\n[阶段⑦部署] 我用 Vercel 部署 Node 后端，连接本地 MongoDB，请给部署清单，指出本地与线上的环境差异点。","acceptance":["AI 是否理解你处于哪个阶段并给相应输出？","是否给出‘目标/验收/雷区’式回答，而不只是贴代码？","是否把上一阶段的产物作为下一阶段的输入？","是否提醒每步都 commit + 测试，安全清单上线前必过？"],"tip":"把项目拆成阶段，每阶段单独、具体地追问 AI：立项就问范围、联调就问具体报错、部署就问环境清单。越分阶段，越精准。"},{"type":"exercise","prompt":"你要做一个‘打卡习惯’小程序，刚从头开始。按本课流程，你第一步最该做什么？","opts":["让 AI 一次性生成完整系统","先把想法压缩成一句话 MVP 与边界，再让 AI 搭可跑骨架并立即 git commit","直接部署一个空文件夹","先写数据库表"],"a":1,"explain":"正确开局：一句话立项锁定 MVP → AI 搭可跑骨架 → 立刻 git 存档建立安全起点。之后再联调、测试、部署。","jump":"sec5-step0","jumpLabel":"立项这一步"},{"type":"check","title":"结课检测：你能独立走完一条产品生产线了吗","intro":"共 4 题。全部答对即可完成整条 Vibe Coding 工程基础路径。答错会带你回对应段落复习。","questions":[{"q":"从想法到上线，八个阶段的第一步是？","opts":["写代码","一句话立项 + 锁定最小 MVP 边界","部署服务器","写测试"],"a":1,"explain":"先想清楚‘为谁解决什么、最小做哪些’，再动手。立项是地基。","jump":"sec5-step0"},{"q":"‘本地 OK 不等于线上 OK’主要指什么风险？","opts":["线上网速更快","环境配置、依赖版本、数据库连接等与本地不一致","线上没有显示器","线上代码自动更好"],"a":1,"explain":"环境不一致是头号翻车点（密钥/数据库/版本/路径），上线后必须用真实地址自测。","jump":"sec5-step6"},{"q":"上线前必须过的基本安全底线包含？","opts":["页面好看","输入校验 + 密钥不入库(.env 隔离) + 权限控制 + HTTPS","代码注释多","视频教程"],"a":1,"explain":"输入校验防注入、密钥隔离防泄露、权限控制防越权、HTTPS 防窃听——四条底线。","jump":"sec5-step4"},{"q":"为什么每个‘能跑’的版本都要 git commit？","opts":["显得专业","形成安全存档点，后续小步迭代随时能回退，防翻车","省磁盘","为了提交给 AI 看"],"a":1,"explain":"能跑就提交，把迭代变成可回退的小步，翻车永远是‘回到上一版’而不是‘重头再来’。","jump":"sec5-step2"}],"done":"恭喜你走完 Vibe Coding 工程基础整条路径！你从‘看懂一个 Web 产品’一路走到了‘能独立用 AI 做出一个上线产品’。记住这条生产线：立项→骨架→版本→联调→安全→测试→部署→观察。现在，去做出你的第一个真产品吧。","nextLesson":""},{"type":"connection","known":["Vibe 路径前七课：Web 链路 / Git / API / 数据库 / 测试 / 结构 / 部署"],"learned":["从想法到上线的八阶段生产线与各自验收标准","每个阶段怎么把对应课程能力用上、怎么防翻车","上线只是开始，观察与迭代才是产品的常态","把流程固化成个人 CheckList 的方法"],"next":"这是 Vibe Coding 工程基础的最后一课，也是你独立做产品的起点。可以回到《从零看懂 AI》路径或继续探索更进阶的工程主题。祝你做出第一个真正上线的产品！","links":[{"href":"#/lesson/v07-deploy","text":"回看《从本地 Demo 到正式上线》"},{"href":"#/lesson/l18-vibe-coding","text":"回到核心路径《Vibe Coding 入门》"}]}]}},"lessonsByCat":{"c08-agent":[{"id":"l-agent","title":"Agent｜让 AI 自己动手做事","subtitle":"为什么 ChatGPT 只能在对话框里打字，而 Codex 能改你的代码、跑你的测试、提交 PR？Agent 就是把『会说话』的模型，变成『会做事』的执行者。","category":"c08-agent","chapterTitle":"第一章 · 从会说到会做","level":"base","estTime":"25-30 分钟","difficulty":2,"concepts":["agent-intro","agent-loop","tool-use","agent-planning","agent-memory","agent-reflection"],"prereqLessons":["l-rag","l-transformer"],"nextLesson":"l22-ai-coding","sections":[{"type":"opening","question":"你已经能让 ChatGPT 把某个概念讲得头头是道，也能用 RAG 让它查你的资料。但如果你说『去我 GitHub 仓库里把那个测试失败修掉』——为什么 ChatGPT 只能在对话框里给建议，而 Codex 却能真的打开文件、改代码、跑测试、把活干完？","guess":"有人会说「Codex 的模型更聪明」。","next":"这节课揭穿这个误会：Agent 的厉害不在模型智商，而在于给模型装上一个『决策循环 + 一双能动手的工具』。学完你就掌握 Agent = 模型 + 工具 + 循环这条主线。"},{"type":"why","before":"到这一课，我们有了很聪明的模型、也有了让它查资料的 RAG。但你还是有个困扰：让 ChatGPT 整理个表格它倒是能，让它『去我仓库里改掉那个 bug』，它做不到。","problem":"因为聊天模型只有一张嘴：它只能输出文字，看不见你的文件、读不了你的代码、跑不了测试命令。你让它操作仓库，它连仓库在哪都不知道。","need":"Model（思考）+ Tools（手和眼）+ Loop（循环驱动）= Agent。它想一下 → 动一下 → 看一眼结果 → 再想 → 再动。这就是 ChatGPT 和 Codex 的分水岭。","visualNote":"下面这个循环图就是 Agent 的灵魂——你可以亲手点不同工具，看它每一步怎么决策、怎么应对失败。"},{"type":"oneline","text":"Agent（智能体）不是换个更厉害的模型，而是给模型装上一个『决策循环』：它会自己拆目标、自己调用工具（读写文件、执行代码、搜网页）、观察结果、再决定下一步，如此循环直到把事情做完。同样一个模型，套上这个循环，就从『只会回答』变成了『会做事』。"},{"type":"visual","kind":"agent-loop","title":"Agent 循环模拟器：想 → 做 → 看 → 再想（可交互）","hint":"这是一个升级版交互模拟器：你扮演一个修复 bug 的 Codex Agent，在每个步骤从几个工具里选一个。选对了推进，选错了会得到失败反馈，教你『Agent 正是靠不断试错修正才把活干完』。"},{"type":"intuition","blocks":[{"k":"计算器只会算，助理会办事","t":"普通聊天模型像一台高级计算器：你问它答。Agent 像你的助理：你交代一件事，它自己拆步骤、打电话（调工具）、核对结果，办完给你汇报。"},{"k":"不是变聪明，是变『能动』","t":"它没有比 ChatGPT 更聪明——它只是多了一圈『能动手、能看反馈、能再试』的回路。代码还是那个代码，差别在于它学会了执行-反馈-调整。"},{"k":"有钥匙的实习生 vs 没钥匙的实习生","t":"ChatGPT 是没钥匙的实习生：看到门（需要改文件）只会描述『你应该去改那个文件』。Agent 是有钥匙的实习生：自己开门、改文件、跑测试、看结果、再改。"}]},{"type":"how","intro":"一个 Agent 改 bug 的完整工作过程。核心就一句话：目标 → 循环（想 + 做 + 看）→ 交付。这也是本课的骨架。","steps":[{"in":"理解目标","process":"用户下达：『修好注册页面的 bug』。模型先把模糊目标翻译成具体子任务列表。","out":"一个可执行的任务清单"},{"in":"规划 Planning","process":"它推理出步骤：先找到注册页代码 → 读源码定位问题 → 想怎么改 → 改 → 跑测试验证。","out":"Agenda：找代码 → 读 → 改 → 测"},{"in":"调用工具 Tool Use（做）","process":"它请求调用工具：read_file 读代码、edit_file 修改、run_command 跑测试。工具返回结果。","out":"一次具体的『动手』"},{"in":"观察结果 Observe（看）","process":"看到工具返回值：测试报错，或编译失败。它读到反馈，判断是否达到目标。","out":"对『刚才做对没有』的感知"},{"in":"循环 Loop：再想再做","process":"若未达成，回到『想』：根据报错调整方案，再调用工具。如此循环直到测试通过或放弃。","out":"反复的 agent loop（这正是与 ChatGPT 的本质区别）"},{"in":"交付与汇报","process":"任务完成：向用户总结改了什么、测试结果，甚至主动提交 PR、申请权限。","out":"一件完成的事，而不是一段话"}]},{"type":"realworld","items":[{"name":"Codex / Claude Code","note":"Agentic Coding 的典型：能读你的仓库、找 bug、改代码、跑测试、提交 PR。这就是『ChatGPT 做不到、它做得到』的原因——它装了代码工具 + agent loop。"},{"name":"Cursor / Windsurf","note":"IDE 里的 Agent：理解整个项目上下文，跨多个文件完成重构，而不只是一行行补全。"},{"name":"浏览器 Agent（Browser Use / Operator）","note":"自己打开网页、读取、点击、填表，把逛网页办事自动化。"},{"name":"n8n / 工作流编排","note":"让 Agent 串联多个工具/API 完成端到端业务流程（取数 → 处理 → 发通知）。"}]},{"type":"compare","pairs":[{"a":"Chatbot（聊天机器人）","b":"Agent（智能体）","diff":"Chatbot 只输出文字、终结于回答；Agent 拆目标、调工具、看结果、循环迭代，终结于做成事。"},{"a":"单次工具调用","b":"多步 Agent Loop","diff":"会调一个工具的助手只是初级；真正的 Agent 会根据结果决定下一调用，持续多轮直到完成。"},{"a":"RPA（脚本化机器人）","b":"LLM Agent","diff":"RPA 按写死的剧本执行、一变就崩；Agent 动态推理、能处理没见过的异常情况。"},{"a":"Agent","b":"RAG","diff":"Agent 是『多步决策、自己调用工具的循环』；RAG 是『查资料再回答的单步机制』。Agent 需要信息时常用 RAG 当其中一个工具。"}]},{"type":"mistakes","items":["以为 Agent 只是换了个更聪明的模型。本质差别在『循环 + 工具』，不是模型本身。","以为 Agent 能无限可靠地自主执行。它也会反复失败、会犯错，所以需要权限门槛（approval gate）、观测和护栏。","忽视权限与安全。放任 Agent 删文件/发数据/花钱是最危险的坑，生产环境必须加授权与审计。","把会调用工具当成有规划和反思。会调一个函数 ≠ 会拆解复杂目标并自我修正，后者才是 Agent 的进阶。","以为多 Agent 一定更好。多数场景单 Agent 更简单可控，盲目堆 Agent 只会带来编排复杂度和成本。"]},{"type":"deep","title":"深入一点：Agent 的工程骨架","beginner":["Agent Loop 不是魔法：本质就是模型的 for/while 循环——决定下一步 → 调用工具 → 看结果 → 决定再下一步。","工具（Tool）就是一个函数：read_file、write_file、run_command、web_search。模型学会了在合适时机调用它们。","最朴素的 Agent = LLM + 工具集 + 一个决定何时停止的循环。它也可以有记忆和规划，但核心就是这个循环。"],"advanced":["Tool Use / Function Calling：模型输出结构化的『要调用哪个函数、传什么参数』，由系统执行并把结果喂回去，形成闭环。","记忆分两层：短期（当前任务的对话/工具历史）与长期（跨对话的项目知识、偏好，常存向量库）。","Planning 范式：ReAct（Reason + Act 交替）、Plan-and-Execute（先定计划再逐步执行，plan 可被动态修订）、Tree-of-Thought 等。","权限与安全 Permission：Agent 不会无限乱来——危险操作（删文件、花钱、外发数据）要求用户授权（approval gate）。","MCP（Model Context Protocol）：统一工具/数据源接入协议，让一个 Agent 能标准化接入文件系统、数据库、浏览器等多种工具，避免每家写一套私有接口。","Reflection 反思：让 Agent 回顾刚才失败的原因再调整，显著提升长任务可靠性。多 Agent 协作则是多个专业 Agent 分工。",{"code":"# 概念示意：Agent 循环的骨架，就长这样\nwhile not goal_reached:\n    thought = model.think(state, memory)      # 想：我要做哪一步？\n    if thought.should_stop: break              # 判断是否完成\n    tool_result = call_tool(thought.tool_call) # 做：调用工具\n    state.append(tool_result)                  # 看：把结果存进上下文\n    memory.update(state)                       # 记住教训\n# 交付\nreport(model.summarize(state))","lang":"python"}]},{"type":"exercise","prompt":"你（作为 Codex Agent）被要求『修好登录页的 bug』。你读完代码，发现登录按钮点击后有报错。现在到了『做』这一步——猜一猜，Agent 下一步最合理的选择是哪个？","opts":["直接凭记忆改掉一行代码","先运行测试/查看报错日志，定位错误来源，再决定改哪里","马上发邮件问用户想怎么改","直接重新写整个登录页"],"a":1,"explain":"正确动作是先『看』——运行测试或读日志拿到报错信息，有了反馈才知道要改哪。这正是 Agent loop 里『做』与『看』的配合：不观察就动手，等于闭眼改代码。","jump":"sec5-step3","jumpLabel":"观察结果 Observe 这一步"},{"type":"check","title":"结课检测：你真的理解 Agent 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 ChatGPT 不能操作你的仓库，而 Codex 可以？","opts":["因为 Codex 的模型更聪明","因为 Codex 被接上了工具（读写文件/跑命令）+ Agent 循环，ChatGPT 只有对话输出","因为 ChatGPT 没联网","因为模型大小不同"],"a":1,"explain":"决定性差异不是模型智能，而是 Agent 结构：工具让它能动手，循环让它能做→看→修正直到完成。","jump":"sec2","jumpLabel":"一句话理解 Agent 那条"},{"q":"Agent Loop 的核心循环顺序是？","opts":["看 → 做 → 想","想 → 做 → 看 → 再想","只做不看不回头","想 → 想 → 想"],"a":1,"explain":"标准 agent loop：决定下一步（想）→ 调用工具（做）→ 观察结果（看）→ 根据结果再决定下一步（再想），循环到目标达成。","jump":"sec5-step4","jumpLabel":"循环 Loop 这一步"},{"q":"MCP（Model Context Protocol）主要解决什么问题？","opts":["让模型跑得更快","统一 Agent 接入工具/数据源的接口标准，避免各家用私有协议","代替向量数据库","让模型更聪明"],"a":1,"explain":"MCP 是 Agent 与文件、数据库、浏览器等外部工具的标准化接入协议，一次接入、到处复用。","jump":"sec9","jumpLabel":"深入节里 MCP 那条"},{"q":"下面哪个最能代表『Agent 与 Chatbot 的本质区别』？","opts":["Agent 文字更长","Agent 会拆目标、调工具、看反馈并循环，终结于做成事；Chatbot 只回复文字","Agent 不需要模型","Chatbot 也能调用工具"],"a":1,"explain":"Chatbot 止于回答；Agent 以『做成事』为目标，通过循环驱动工具完成多步任务。","jump":"sec7","jumpLabel":"对比区 Chatbot vs Agent"},{"q":"为什么生产环境里 Agent 的危险操作要加『授权门槛（approval gate）』？","opts":["为了拖慢速度","Agent 也会犯错，删文件/花钱/外发数据必须先经用户确认，防止不可逆损失","模型必须要人帮它思考","为了多收费"],"a":1,"explain":"Agent 并非无限可靠，危险动作必须先授权再执行，是落地安全的关键护栏。","jump":"sec8","jumpLabel":"『忽视权限与安全』那条误区"}],"done":"你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。最后一章会带你顺着这条主线进入真正的 AI 编程实践。","nextLesson":"l22-ai-coding"},{"type":"connection","known":["Transformer：模型怎么生成内容","RAG：怎么让模型查资料","工具调用 Function Calling"],"learned":["Agent = 模型 + 工具 + 循环（想→做→看→再想）","它能拆目标、规划、调用工具、观察反馈、反复修正","关键工程点：Tool Use / Memory / Planning / Permission / MCP / Reflection","Chatbot 回答问题，Agent 做成事"],"next":"到这里，你已经走完了从『什么是 AI』到『AI 自己会做事』的完整主线。想继续深入，建议顺着目标分支走：做产品学 LLM 应用与 RAG，写代码就进入 AI 编程（Agentic Coding / Claude Code）那一章——用 Agent 亲自改代码、跑测试、提交 PR。"}]}],"c05-llm":[{"id":"l-attention","title":"Attention｜模型为什么知道该关注哪个词","subtitle":"当模型读到『它』，怎么知道是猫还是狗？为什么句子再长，模型也能把前后的词对上号？","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["attention","qkv","multihead","attention-long"],"prereqLessons":["l-embedding"],"nextLesson":"l-transformer","sections":[{"type":"opening","question":"请读这句话：「小狗跑向小猫，因为它害怕小狗。」这个『它』指的到底是小猫还是小狗？只盯着『它』一个词，谁也说不清——那 ChatGPT 是怎么判断出来的呢？","guess":"有人会说「代词当然指前面离得最近的动物」。但中文里『它』常跨好几个词、甚至跨好几句指代，光看位置根本猜不准。","next":"这节课要讲的就是模型的『读心术』——Attention 注意力机制。它让模型在处理『它』时，回头看一眼整句话，自己判断该靠哪些词来理解『它』。"},{"type":"why","before":"上节课我们把每个词变成了向量。但词是孤立的：『猫』『追』『狗』『它』，每一个都只是单独的一串数字。","problem":"真正的语言是互相指代的。『猫追狗，它跑得飞快』——这个『它』是谁？只看『它』这个词本身，根本答不上来。更糟的是：在 Attention 出现以前，老式模型（RNN）看长句时，越靠前的词就越『记不清』。","need":"我们需要一个机制：在处理任何一个词时，能直接『回看』整句话里的所有词，按相关程度加权吸收它们的信息。这就是 Attention——『注意力』，它解决了『远距离指代』和『长句遗忘』两大难题。","visualNote":"下面你可以亲手造一句中文，点任何一个词，看它把注意力分给了谁。"},{"type":"oneline","text":"Attention 是这样一种机制：模型在理解某个词时，会『回头看一眼』句子里的每一个词，给它们分别打一个权重分——分数越高的词，模型花越多注意力在它身上。于是『它』到底指猫还是狗，模型有了办法分清。"},{"type":"visual","kind":"attention-heatmap","title":"Attention 热力图：点一个词，看它关注谁","hint":"输入一句话，点任意一个词（比如那棵/那株），热力图会显示这个词对其它词的『关注权重』——颜色越深，越关注。试试改动量词，体验权重如何跟着语义线索移动。"},{"type":"intuition","blocks":[{"k":"老师点名：每读一个词都在点名","t":"读到『它』这个词时，模型其实在问：『谁能告诉我『它』指谁？』——它把问题抛向所有词，然后重点听『猫』『跑』这些最相关的答案。"},{"k":"查字典：不是顺序读，而是跳着看","t":"Attention 最反直觉的一点：它不老老实实从左往右读。读到『它』，它像翻开一本字典快速扫过所有词条，直接锁定『猫』『跑』，记下『我主要靠这几个词来理解自己』。"},{"k":"聚光灯：每个词都举着无数盏灯","t":"句子里每个词都举着一盏聚光灯照向其它词。灯越亮，代表『我理解你时越依赖你』。Attention 就是计算这盏灯亮度的过程。远近都一样亮——这是它比老方法强的地方。"}]},{"type":"how","intro":"Attention 到底怎么『算』注意力？核心就一句话：每个词同时扮演三个角色——Query（我找谁）、Key（我是谁）、Value（我的内容），然后『找相似、按相似加权吸收』。","steps":[{"in":"乘上三个矩阵，得到 Q / K / V","process":"每个词的向量分别乘以三个不同的矩阵，变成三个新向量：Query『我要去匹配谁』、Key『我是谁，请拿我来匹配』、Value『我的有效内容』。","out":"单词 → (Query, Key, Value) 三件套"},{"in":"用 Query 和所有 Key 算相似度","process":"以『它』的 Query 为例，和句子里每个词的 Key 做点积（就是 Embedding 课学过的『方向越像越接近』）。","out":"得到分数列表：它 vs 猫 = 高分，它 vs 跑 = 中等……"},{"in":"Softmax 归一化成权重","process":"把所有分数经过 softmax，变成『加起来等于 100%』的权重。这一步保证分数变成可比较、可加权的概率。","out":"注意力权重：猫 0.6、跑 0.25、飞快 0.15……"},{"in":"用权重 × Value 加权求和","process":"把每个词的 Value 乘上对应权重再全部相加。权重大的词，内容在结果里占的份量就大。","out":"『它』的新向量 = 主要吸收了『猫』的信息 → 模型知道『它≈猫』"},{"in":"每个词同时做，得到上下文向量","process":"句子里每个词都执行同一套操作，得到一批『结合了全局上下文的新向量』。","out":"整句话从一串孤立向量 → 一串互相理解的向量"},{"in":"多个头并行（多头注意力）","process":"为了不只从一种角度看，模型并行做多组 Q/K/V（不同随机初始化的矩阵），相当于多个不同视角同时观察。","out":"一个头看指代关系、另一个头看语法结构、再一个看长度……组合出更丰富的理解"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude 生成每个词","note":"每生成一个 token，模型都要对上下文做一次 Attention：决定下一个词更依赖前面的哪部分。这是生成的核心动作。"},{"name":"翻译模型的对齐","note":"把『I love you』翻成中文时，Attention 让『love』和『爱』自动对上号，哪怕位置完全错开（这就是 Cross-Attention 用武之地）。"},{"name":"代码补全","note":"补全函数体时，Attention 帮模型盯住几千行前的函数签名和参数定义，而不是只看到最近几行。"},{"name":"长文档问答","note":"在长文章里问『第三部分的结论是？』，Attention 让模型跳过大段无关内容，直接聚焦第三部分的句子。"}]},{"type":"compare","pairs":[{"a":"RNN 顺序处理","b":"Attention 全局直连","diff":"RNN 必须一个字一个字按顺序传，远处信息会衰减；Attention 让任意两个位置直接相连，没有距离衰减。"},{"a":"Self-Attention","b":"Cross-Attention","diff":"Self 是同句话内部互相理解；Cross 是让一方去『读』另一方（翻译、RAG 上下文注入都用它）。"},{"a":"单头注意力","b":"多头注意力","diff":"单头只有一种看法；多头并行多组 Q/K/V，相当于同时用多个角度理解，效果明显更好。"},{"a":"注意力（Attention）","b":"记忆（Memory）","diff":"注意力是每次计算时动态算出的关注权重，不存下来；记忆是存下来的长期信息。很多人把注意力误当成记忆。"}]},{"type":"mistakes","items":["以为 Attention 是『看一遍就记住』的长期记忆。它不是记忆，而是每次计算时动态分配的关注权重——每次都要重新算，不会存下来。","以为注意力可视化等于模型的可解释性。权重高代表统计上相关，不代表模型逻辑上『是因为这个』。","把『注意力』和『上下文窗口』混为一谈。窗口决定能看多远，Attention 决定窗口内怎么分配关注。","以为只看『最近几个词』。Attention 恰恰是全局的——它牺牲计算量，换来的是真正看全上下文。","以为 Attention 零成本。它的核心开销是 O(n²)：n 个词两两算一遍。这正是上下文窗口成为瓶颈的原因。"]},{"type":"deep","title":"深入一点：从直觉到公式","beginner":["注意力权重加起来等于 1（100%）。Softmax 就是把一坨分数变成『加起来为 1、且大的更大』的数。","不必纠结矩阵怎么算，你只需记住一句口诀：『Query 找人，Key 被找，Value 是内容，三者相乘加权求和』。","它最厉害的地方：任意两个词无论隔多远都能直接相关——远处那个词和眼前这个词，算注意力的成本完全一样，这是它战胜 RNN 的根本原因。"],"advanced":["核心公式：Attention(Q, K, V) = softmax( (Q·Kᵀ) / √d ) · V。除以 √d（d 是向量维度）是为了防止点积过大把 softmax 压死、导致梯度消失。","Self-Attention 的 Q/K/V 都来自同一句话，让句子内部互相理解；Cross-Attention 的 Q 来自一方、K/V 来自另一方（如翻译、RAG 上下文注入）。","复杂度 O(n²)：n 个词两两都算一遍。这正是上下文窗口成为瓶颈的原因，也是稀疏注意力、局部注意力、线性注意力研究的动机。","不要神化注意力可视化：权重高 ≠ 模型真『懂』了，它更多是统计相关而非可解释的因果。",{"code":"# 概念示意：手工算一次注意力（极简 2 词版）\nimport math\n\ndef softmax(xs):\n    ex = [math.exp(x) for x in xs]\n    s = sum(ex)\n    return [e / s for e in ex]\n\nq = [1.0, 0.0]  # 我是『它』的 Query\nks = {\"猫\": [0.9, 0.1], \"狗\": [0.2, 0.8]}  # 两个词的 Key\n\nscores = {w: round(q[0]*k[0] + q[1]*k[1], 3) for w, k in ks.items()}\nprint(\"点积分数:\", scores)\nweights = dict(zip(scores, softmax(list(scores.values()))))\nprint(\"softmax 权重:\", {w: round(v,3) for w,v in weights.items()})\n# 猫的权重明显更高 → 模型认为『它』更像猫","lang":"python"}]},{"type":"exercise","prompt":"「它拿起了那支笔，因为【　】太亮了。」这个【　】里的词，会让『太亮了』把更多注意力分给『笔』而不是『它』，你能猜出最合理的一个词吗？","opts":["灯","笔帽","手","桌"],"a":0,"explain":"『灯太亮了』语义合理，Attention 会让『亮』和『灯』形成高权重连接；而『笔帽太亮了』虽然通顺，但更重要是体会：有了『亮』这个线索，Attention 会去找『最配得上的名词』。模型正是靠大量这样的共现线索来分配注意力。","jump":"sec5-step1","jumpLabel":"用 Query 和 Key 算相似度这一步"},{"type":"check","title":"结课检测：你真的理解 Attention 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"Attention 中 Query、Key、Value 各自的作用，最准确的说法是？","opts":["Q 是内容，K 是找人，V 是被找","Q 在找人，K 是被找的标签，V 是被吸收的内容","三者完全相同","Q 是权重，K 是分数，V 是标签"],"a":1,"explain":"Q（Query）发起匹配去『找谁』；K（Key）告诉别人『我是谁』供匹配；V（Value）是被加权吸收进的真正内容。","jump":"sec5-step0","jumpLabel":"乘上三个矩阵得到 Q/K/V 这一步"},{"q":"为什么说 Attention 解决了 RNN『记不住长句』的问题？","opts":["因为它是顺序处理的","因为任意两个词都可以直接相关，不随距离衰减","因为它把句子变短了","因为它只关心最近的词"],"a":1,"explain":"RNN 依赖顺序传递、距离远信息衰减；Attention 让任意两个位置直接相连、远近一视同仁。","jump":"sec8","jumpLabel":"『以为只看最近几个词』那条误区"},{"q":"把注意力分数做 softmax 是为了什么？","opts":["让负数变成正数","让分数变成加和为 1 的权重，且强调大的","让计算更快","让向量变短"],"a":1,"explain":"Softmax 把一坨任意分数变成『加起来为 1』、且大者更大的概率分布，这样加权求和才合理、可解释。","jump":"sec5-step2","jumpLabel":"Softmax 归一化成权重这一步"},{"q":"Self-Attention 与 Cross-Attention 的区别是？","opts":["没有区别","Self 是同句话内部互相理解；Cross 是让一方去读另一方","Self 只用于图片，Cross 只用于文字","Self 更快，Cross 更慢"],"a":1,"explain":"Self-Attention 的 Q/K/V 来自同一句话；Cross-Attention 的 Q 来自一方、K/V 来自另一方（翻译、RAG 都用）。","jump":"sec7","jumpLabel":"对比区里的 Self vs Cross 那一条"},{"q":"多头注意力（Multi-Head）的本质好处是？","opts":["让模型更快","让模型从多个不同视角同时理解，组合出更丰富的语义","让上下文窗口变长一倍","省掉 Softmax"],"a":1,"explain":"把模型注意力想象成多个不同的专家，各看一面（指代、语法、距离），最后合并，理解更全面。","jump":"sec5-step5","jumpLabel":"多个头并行这一步"}],"done":"你已经理解 Attention 是 Transformer 的心脏。这个『找相似、加权吸收』的机制，也是后面 RAG 把检索结果喂进模型时的同一套逻辑。","nextLesson":"l-transformer"},{"type":"connection","known":["词 → 向量（Embedding）","向量方向越像、语义越近（余弦相似度）"],"learned":["每个词同时扮演 Query / Key / Value 三角色","注意力 = 相似度分数 → softmax 权重 → 加权求和","Self-Attention 让句子内部互相理解，多头提供多视角","Attention 任意位置直连、无距离衰减，解决了长句遗忘"],"next":"Attention 是 Transformer 的心脏。下一课我们把这套注意力装进一个完整的架构：位置编码、多头、归一化……看看它怎么组成一个能真正训练、能翻译能写诗的大模型——Transformer。"}]},{"id":"l-transformer","title":"Transformer｜大模型的地基架构","subtitle":"为什么 2017 年诞生的它，能横扫翻译、写作、代码、对话？一个 20 分钟看懂『大模型的心脏是怎么拼出来的』。","category":"c05-llm","chapterTitle":"第二章 · Transformer","level":"base","estTime":"25-30 分钟","difficulty":3,"concepts":["transformer","position-enc","multihead","attention"],"prereqLessons":["l-attention"],"nextLesson":"l12-context-window","sections":[{"type":"opening","question":"上一课我们有了 Attention，它能让任何两个词互相关注。但只用 Attention 还是没法当一个能工作的模型——它不知道『第 5 个词和第 2 个词』谁先谁后，也堆不了很深。猜一猜：研究人员 2017 年到底在 Attention 外面『加了哪些零件』，才把它拼成了横扫一切的 Transformer？","guess":"很多人以为 Transformer = Attention，觉得『注意力』就是全部。","next":"这节课我们把注意力装进完整的大脑：位置编码、多头、残差、归一化、前馈网络、N 层堆叠。学完你就明白，为什么它能取代 RNN、成为所有大模型的共同地基。"},{"type":"why","before":"上一课我们有了 Attention：任何两个词都能直接互相关注。但这只是一块『积木』，离一个能真正工作的模型还差很远。","problem":"只靠 Attention 不够：1) 它不知道词的位置——『猫追狗』和『狗追猫』词全一样；2) 一层注意力学到的东西有限；3) 想堆深又容易训练不动（梯度消失）。","need":"Transformer 就是给 Attention 配上『位置感、深度、稳定训练』三件装备，把一块积木组装成一台可以训练、可以并行、可以堆得极深的机器。它是 ChatGPT、Claude、Gemini 的共同地基。","visualNote":"下面这张图是 Transformer 的主干流水线，你可以一步一步点开看每一层在干什么。"},{"type":"oneline","text":"Transformer 是 2017 年提出的一个『把注意力机制组装成完整大脑』的架构：它用『多头注意力 + 前馈网络 + 残差连接 + 位置编码』堆成一层又一层的模块，能并行、能训练得非常深，从此成为所有现代大语言模型的共同地基。"},{"type":"visual","kind":"transformer-flow","title":"Transformer 主干流水线：一步一步看","hint":"点击【下一步】，观察一个词从数字向量走到预测下一个词的完整过程：输入 → 位置编码 → 多头注意力 → 残差+归一化 → 前馈网络 → 重复堆叠 → 输出。"},{"type":"intuition","blocks":[{"k":"一个加工厂流水线","t":"把 Transformer 想成一家加工厂：原料是一串向量。每个工位（层）做两件事——同事协作（注意力，大家互通信息）+ 个人精加工（前馈网络，每个词独自想更深）。一层做完送下一层，共 N 层。"},{"k":"用乐高积木来想","t":"Attention 只是其中一块积木。Transformer 是说明书：告诉你这一层要怎么拼——注意力 + 残差 + 归一化 + 前馈，然后复制粘贴 N 次。"},{"k":"办公室里的并行会议","t":"RNN 像只有一个话筒的圆桌，每人必须轮流说（慢）；Transformer 像微信群——所有人同时发言、同时收听（并行快），谁跟谁相关自己匹配（注意力）。这就是它又快又强的秘密。"}]},{"type":"how","intro":"一个词在 Transformer 里的完整旅程。每一步都围绕同一批向量做变换，最后模型学会『预测下一个词』。","steps":[{"in":"输入：词向量 + 位置编码","process":"每个词先查表得到 Embedding 向量。但向量本身不含位置，所以再加一个位置信息（位置编码），让模型知道『这是第 5 个词』。","out":"每个词都带上位置的向量"},{"in":"多头注意力层（同事协作）","process":"这一层让每个词结合全局上下文：用上节课的 Q/K/V 机制，多组并行，输出再拼接。词的『含义』从此包含了周围所有词。","out":"每个词变成理解上下文后的新向量"},{"in":"残差连接 + 归一化（稳定训练）","process":"把『进来的向量 + 注意力算完的向量』加在一起（残差），再做归一化。这就像修了一条高速公路：信息不衰减地直接流过深层。","out":"浅层信息能无损抄近道到达深层，网络可以堆得深"},{"in":"前馈网络 FFN（个人精加工）","process":"一个两层全连接网络，对每个词独立做非线性变换，让模型有能力表达更复杂的关系。","out":"每个词被再想一想，表达能力增强"},{"in":"重复堆叠 N 层","process":"把『注意力 + 残差 + 归一化 + 前馈』复制 N 次叠起来（GPT 有十到上百层）。每层都让词的表示更抽象、更接近任务。","out":"深层的向量已经浓缩了整句话的语义"},{"in":"输出：预测下一个词","process":"最后一层接线性层 + softmax，把向量变成词典里每个词的概率，取概率最高的作为下一个词。","out":"生成一个词 → 拼回输入 → 继续预测下一个词"}]},{"type":"realworld","items":[{"name":"ChatGPT / GPT 系列","note":"Decoder-only Transformer：单纯地一层层预测下一个词，就长出了对话和推理能力。"},{"name":"Claude / Gemini","note":"同一架构的不同工程实现：同样的多头注意力 + 深层堆叠，在尺度与训练技巧上各有差异。"},{"name":"翻译与摘要模型（T5/BART）","note":"Encoder-Decoder 结构：编码器读懂全文，解码器再一句句生成译文或摘要。"},{"name":"代码补全（Codex 前身/Copilot）","note":"把代码当另一种语言喂给 Decoder-only Transformer，学会了补全、续写、改 bug。"}]},{"type":"compare","pairs":[{"a":"RNN","b":"Transformer","diff":"RNN 顺序串行、远处信息衰减、难并行；Transformer 全局直连、天然并行、能堆深。2017 后几乎完全取代 RNN。"},{"a":"Encoder-only（BERT）","b":"Decoder-only（GPT）","diff":"前者双向读全文、擅长理解（分类/检索）；后者只能从左往右、擅长生成（对话/写作/代码）。"},{"a":"单层注意力","b":"N 层堆叠的 Transformer","diff":"单层只做一次互相看；Transformer 把多次『互相看 + 精加工』叠起来，让表示一层比一层抽象。"},{"a":"Transformer","b":"Attention","diff":"Attention 是其中的一个子模块；Transformer 是包含注意力在内的一整套完整架构。很多人把两者画等号，其实 Attention ⊆ Transformer。"}]},{"type":"mistakes","items":["以为『Transformer = Attention』。Attention 只是其中一个子模块，完整架构还包括残差、归一化、前馈、位置编码。","以为 BERT 和 GPT 一样。BERT 双向理解、GPT 单向生成，职权完全不同。","以为层数越多一定越好。层越深效果提升有边际，还带来更大算力和训练难度。","把『位置编码』当可选项。没有它，『猫追狗』和『狗追猫』对模型来说完全一样——这可是天壤之别。","以为 ChatGPT 用的是完整 Encoder-Decoder。GPT 只用 Decoder-only，这是它和 T5 这类翻译模型的关键区别。"]},{"type":"deep","title":"深入一点：从直觉到架构细节","beginner":["位置编码就是给每个词加一个『第几个』的记号，否则『猫追狗』和『狗追猫』对模型来说字全一样。","残差连接简单说就是『进来和出去加一起』，像搭桥——让深层的梯度不会消失，模型才能堆数十上百层。","前馈网络 FFN 是给每个词单独换个角度想一遍，和注意力（词与词协作）分工不同、缺一不可。","GPT 其实只用了 Transformer 的一半：只有解码器那套（Decoder-only），用来不停地预测下一个词。"],"advanced":["核心是 Decoder：每个 token 只看自己和前面（因果掩码 causal mask），保证预测时不偷看未来。这是它和编码器的最大区别。","缩放点积注意力：Attention = softmax( (Q·Kᵀ) / √d )·V。除以 √d 防点积过大导致梯度消失 / softmax 饱和。","三种架构：Encoder-only（BERT：理解）、Decoder-only（GPT：生成）、Encoder-Decoder（T5：翻译/转换）。ChatGPT 系清一色 Decoder-only。","残差连接 + LayerNorm（常采用 Pre-LN 顺序：先归一化再进子层）是训练稳定性的关键工程细节，是它能堆到千亿参数的原因之一。","复杂度 O(n²)：上下文窗口越大成本越高——这直接决定了长上下文为什么贵、为什么要引入 RAG。",{"code":"# 概念示意：位置编码的经典公式（体会它想表达什么即可）\nimport math\n\ndef pos_encoding(pos, d_model=8):\n    vec = []\n    for i in range(d_model):\n        angle = pos / (10000 ** (2 * (i // 2) / d_model))\n        vec.append(round(math.sin(angle), 3) if i % 2 == 0 else round(math.cos(angle), 3))\n    return vec\n\nfor p in [0, 1, 2, 3]:\n    print(f\"第{p}个词的位置: {pos_encoding(p)}\")\n# 每个位置生成一组各不相同的位置向量 → 模型据此知道先后顺序","lang":"python"}]},{"type":"exercise","prompt":"如果完全不给模型位置编码，只给它 Attention，那么『猫追狗』和『狗追猫』这两句话，模型会怎么看待？","opts":["认为它们语义完全不同（追的方向相反）","认为它们几乎一样（词完全相同，注意力无差别混合）","认为它们字数不同","完全无法处理两个词以上的句子"],"a":1,"explain":"注意力是把所有词互相加权求和，本质记不得先后顺序。没有位置编码，模型会认为两句话『字都一样所以差不多』，分不清谁追谁。这正是位置编码存在的意义。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"type":"check","title":"结课检测：你真的理解 Transformer 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么 Transformer 需要位置编码？","opts":["为了让向量维度变大","因为注意力本身不含位置信息，没有它『狗追猫』和『猫追狗』无法区分","为了加快计算","为了让训练更快收敛"],"a":1,"explain":"注意力把所有词互相加权、天然不记顺序；位置编码把『第几个』注入向量，模型才知道先后。","jump":"sec5-step0","jumpLabel":"输入：词向量 + 位置编码这一步"},{"q":"残差连接（Residual）的主要作用是？","opts":["增加参数数量","让信息能无损跨层传递，网络可以堆得很深且训练稳定","让模型更快生成","代替位置编码"],"a":1,"explain":"把输入与输出相加，像搭桥一样让信息直达深层，缓解梯度消失，是能堆几十上百层的关键。","jump":"sec5-step2","jumpLabel":"残差连接 + 归一化这一步"},{"q":"GPT 属于哪种结构？","opts":["Encoder-only","Decoder-only","Encoder-Decoder","既不是编码器也不是解码器"],"a":1,"explain":"GPT 只用解码器（带因果掩码、从左往右生成），反复预测下一个词。","jump":"sec9","jumpLabel":"深入节里 GPT=Decoder-only 那条"},{"q":"Attention 和 Transformer 的正确关系是？","opts":["它们是同一个东西","Transformer 是 Attention 的一个零件","Attention 是 Transformer 的一个子系统，Transformer 是完整架构","完全没有关系"],"a":2,"explain":"Attention ⊆ Transformer：Transformer 在 Attention 之外还包含残差、归一化、前馈、位置编码等。","jump":"sec8","jumpLabel":"『以为 Transformer=Attention』那条误区"},{"q":"为什么说 Transformer 比 RNN 快（并行）？","opts":["因为它跳过了很多词","因为它让所有词同时参与计算，不用一个字一个字排队","因为它更短","因为它的层更少"],"a":1,"explain":"RNN 必须按顺序串行处理每个词；Transformer 所有位置并行计算，谁跟谁相关靠注意力自己匹配。","jump":"sec7","jumpLabel":"对比区 RNN vs Transformer"}],"done":"你已经明白大模型的地基长什么样了。但这个『什么都会的模型』只记得训练时的知识——它不知道你公司的最新政策。下一课解决这个问题。","nextLesson":"l-rag"},{"type":"connection","known":["Attention：Q/K/V 加权求和，让词与词互相关注","词是向量，语义可算相似度"],"learned":["Transformer = 多头注意力 + 残差 + 归一化 + 前馈网络的 N 层堆叠","位置编码让模型感知顺序，否则猫追狗 = 狗追猫","GPT 是 Decoder-only，靠预测下一个词长出能力","O(n²) 复杂度是长上下文贵的根源，引出 RAG"],"next":"Transformer 有了，模型『什么都懂但只记得训练时的知识』。下一课我们解决这个关键问题：RAG——怎么让模型在回答前先到你的资料库查资料，从而答出它没学过的私有内容。"}]},{"id":"l11-tokenization","title":"Tokenization：大模型是怎么『读』文字的","subtitle":"模型不直接‘看字’，而是先把文字切成一小块一小块的 Token，再变成数字。理解了 Token，你就理解了计费、长度限制、以及为什么某些词会被‘拆开’。","category":"c05-llm","chapterTitle":"第三章 · 语言进入模型","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["tokenization","token","bpe"],"prereqLessons":["l09-backprop"],"nextLesson":"l-embedding","sections":[{"type":"opening","question":"你经常看到『这个模型上下文 128K』『这次对话用了 3 万个 token』。Token 到底是什么？为什么不是按‘字’或‘词’计？模型到底是怎么把整段中文读进去的？","guess":"有人以为 token 就是字，或者以为模型直接读整个单词。","next":"这一课讲 Tokenization——把文字切成基本面片（Token），并把它变成模型能算的数字的前半段（后半段是下一课的 Embedding）。这一课你看懂『切词』。"},{"type":"why","before":"你想弄懂大模型到底在‘读’什么，但看到‘token’‘BPE’‘词表’这些词就头大，甚至搞不清 token 和字、词的区别。","problem":"不理解 Tokenization，你就看不懂计费为什么按 token、为什么输入太长会被截断、为什么个别词会被拆得‘很怪’，以及为什么不同分词器能力差别这么大。","need":"我们把‘切词’这件事讲透：先切成 Token，再查词表变数字。基础知识一到手，计费、上下文、词表这些概念全部能对号入座。"},{"type":"oneline","text":"Tokenization = 把一段文字按词表切成一连串 Token（大部分 Token 是常见词或词的一小段），再为每个 Token 分配一个编号；模型读的是这一串编号。Token 通常不等于“字”，一个英文单词多被切成 1~2 个 token。"},{"type":"intuition","blocks":[{"k":"用超市小票来想","t":"词表＝超市商品的条码目录；每件商品（常见词/词组）有固定条码。文字就是选购清单，Tokenizer 把清单拆成一件件能扫的商品（Token），每个扫出一个条码号。模型只见条码，不见商品。"},{"k":"用给单词编学号来想","t":"你给全班每个同学发学号，老师点名说学号而不是名字。Token 就是‘语言的学号’：把海量语言变成有限的一本学号册（词表），每个词/词片对应一个编号。"},{"k":"一句话记住","t":"Token 是模型能读的最小语言单位（常见词或词的一小段），每个 token 有编号。Token 数量≈你对模型说的话的‘字数账单’。"}]},{"type":"how","intro":"把一段文字从‘人看的’变成‘模型算的’，四步。","steps":[{"in":"① 准备词表（Vocabulary）","process":"训练前统计海量语料，用算法（如 BPE）找出最常用的一批‘词/词片’，编成词表（如 5 万~20 万个 token）。","out":"一本固定的‘条码目录’（词表）"},{"in":"② 切分（Tokenize）","process":"把输入文字按词表切成一连串 token。常见词整词成一个 token；生僻、低频的长词会被切成一两段。","out":"一串 token 编号"},{"in":"③ 变数字（映射到索引）","process":"每个 token 查它在词表里的位置，输出一个整数编号。这串整数就是模型真正‘看到’的输入。","out":"一串数字索引（模型输入）"},{"in":"④ 进入 Embedding（下一课）","process":"每个编号再被映射成一个稠密向量（Embedding），进入神经网络。注意：token 是‘编号’，向量是那棵树的下一层。","out":"可被神经网络计算的高维向量序列"}]},{"type":"realworld","items":[{"name":"为什么按 Token 计费","note":"模型的计算量正比于 token 数量——输入、输出都要为每个 token 过一次计算，所以 API 按 token 计费。"},{"name":"为什么中文更‘烧’ token","note":"中文字符一般每个字约占 1~1.5 个 token，英文常见的 1 个词常只占 1 个 token 左右。同样‘一段话’，中英 token 数差别明显。"},{"name":"为什么输入太长会被截断","note":"模型有上下文长度上限（如 128K token）。超出部分会被丢掉或报错，所以长文档要先剪裁。"},{"name":"为什么有的词被拆得奇怪","note":"词表有限，低频长词只能被切成几段。你看到 tokenizer 演示里把长词拆开，是正常操作。"}]},{"type":"compare","pairs":[{"a":"字（Character）","b":"Token","diff":"字是按书写单元；Token 是模型的分词单元，一个 token 常等于一个词或词的一部分，跟字不一一对应。"},{"a":"词（Word）","b":"Token","diff":"常见词一个词≈一个 token；但生僻词可能切成一两个 token 片段，tokenizer 不保证按词切。"},{"a":"Token 编号","b":"Embedding 向量","diff":"编号是‘这是谁’；Embedding 是把这个 token 变成一个携带语义的向量（下一课讲）。编号在前面，向量在后面。"},{"a":"不同模型词表","b":"同一模型词表","diff":"不同分词器/模型的词表不同，同一个词在不同模型的 token 数可能不同；这也是跨模型比较长度时要小心的点。"}]},{"type":"mistakes","items":["以为 token = 字数或单个字——一个 token 常是一词或词的一部分，中文约一字多 token。","以为 token 就是向量——token 是先编号，向量是下一层（Embedding）。","以为所有模型分词方式一样——不同模型词表和切分差异很大。","以为加长输入不花钱——输入要按 token 计费，上下文越长越贵。","给模型喂’整本小说‘——超出上下文窗口会被截断，要靠检索/摘要后再喂。"]},{"type":"deep","title":"深入一点：BPE 到底怎么切词（直观版）","beginner":["BPE（Byte Pair Encoding）思路：先把文字拆成最细单位，再反复把‘出现次数最多的相邻对’合并成一个新 token，直到词汇表够大。","结果：高频常见词是整词 token，低频长词被切成若干常用片段组合。","好处：既覆盖常见词，又能拼出任意新词（不生僻词就拼接），内存与效率平衡。"],"advanced":["更现代的有 SentencePiece / tiktoken 等，支持不依赖空格的中文、日文切分，并常对字节级做回退保证任何输入都可表达。","词表规模是权衡：太大则嵌入矩阵大、训练/部署内存高；太小则文本被切得更碎、每句 token 数变多。","指令/特殊 token（如 \u003c|start|>、\u003ceos>）也在词表里，模型输出时也会生成这些控制 token。","工程：API 的 max_tokens、上下文窗口、计费都与 tokenizer 强绑定，读文档时先看它用哪种 tokenizer。"]},{"type":"exercise","prompt":"你调用一个 LLM API，回答收到一本 200 页的小说说‘超长’。为什么？","opts":["小说太‘重’，服务器磁盘满了","文本 token 数超过了模型的上下文窗口上限，被截断或报错","小说是中文所以坏了","token 与长度无关"],"a":1,"explain":"模型能读的 token 总量有上限（上下文窗口）。200 页小说 token 数超限，所以被拒绝/截断。","jump":"sec5-step2","jumpLabel":"切分这一步"},{"type":"check","title":"结课检测：Token 你切明白了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"Token 最准确的理解是？","opts":["一个汉字或英文字母","模型能读的最小语言单位（常见词或词的一部分）","一个句子","一张图片"],"a":1,"explain":"Token 是分词后的单元，通常是常见词或词的一部分；不是字也不是句子。","jump":"sec5-step1","jumpLabel":"准备词表这一步"},{"q":"一段英文通常比同样内容的中文 token 数？","opts":["中文每字约占 1~1.5 token，英文常见 1 个词约 1 token，因此同样内容中英 token 数不同","完全一样","英文一定少","中文一定少"],"a":0,"explain":"不同语言的 token 化效率不同，同样语义中英所需 token 数有差别，这也影响计费与上下文占用。","jump":"sec6","jumpLabel":"中文更烧 token 这个点"},{"q":"模型计费为什么按 token？","opts":["因为 token 比较好看","模型计算量正比于 token 数，输入输出都按 token 消耗算力与成本","与算力无关，只是习惯","只有输出按 token"],"a":1,"explain":"每个 token 都要经过模型计算，所以输入输出都按 token 计费。上下文越长成本越高。","jump":"sec5-step3","jumpLabel":"进入 Embedding 这一步"},{"q":"Token 编号和 Embedding 向量的关系是？","opts":["二者是同一个东西","token 先编号，再映射成向量（Embedding），是两步","embedding 在 token 前面","没有关系"],"a":1,"explain":"先切词得到 token 编号，再把编号映射成稠密向量（Embedding）进入网络。编号是第一步，向量是第二层。","jump":"sec5-step3","jumpLabel":"进入 Embedding 这一步"}],"done":"文字被切成了 token 编号。可编号只是‘学号’，怎么变成‘有语义的数字’？下一课《Embedding》——把词变成电脑能懂、能算相似度的向量。","nextLesson":"l-embedding"},{"type":"connection","known":["神经网络只能处理数字（前面几课）"],"learned":["Token = 模型能读的最小语言单位","词表 + 切分 → token 编号","计费、上下文窗口、中文 token 化差异","BPE / SentencePiece 的思路"],"next":"拿到了 token 编号，下一课让它们‘变得有意义’：《Embedding》教你如何把每个 token 变成携带语义、能算相似度的向量。","links":[{"href":"#/lesson/l-embedding","text":"进入《Embedding》"},{"href":"#/lesson/l12-context-window","text":"相关：《上下文窗口与推理》"}]}]},{"id":"l12-context-window","title":"上下文窗口与推理：模型一次能『看见』多少","subtitle":"模型不是全知全能的——它一次只能‘看见’上下文窗口里的那点内容。搞懂窗口、记忆与推理，你就明白了为什么模型‘记不住上句’、以及长对话为什么会『健忘』。","category":"c05-llm","chapterTitle":"第三章 · 语言进入模型","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["context-window","inference","token"],"prereqLessons":["l11-tokenization"],"nextLesson":"pl-prompt","sections":[{"type":"opening","question":"你问模型‘还记得我们刚才说的那件事吗’，它却像失忆。可它明明能把长文档读得很好。这种‘时而记得、时而忘记’是怎么回事？关键就在‘上下文窗口’。","guess":"有人以为模型像人一样有持久记忆，或者把所有历史都一直记着。","next":"这一课讲上下文窗口（一次能读多少 token）、以及推理时模型怎么用它。你会明白：模型的‘记忆’不是永久的，而是每次只装进窗口里的内容。"},{"type":"why","before":"你想让模型处理长文档、维持长对话，可它总是‘忘’前文，或说‘超出长度’。你需要知道模型的看得见范围到底由什么决定。","problem":"不理解上下文窗口，你会误以为模型‘记性差是 bug’，或把太长内容硬塞进去导致被截断、变慢、变贵。","need":"我们把窗口和记忆讲清楚：模型每一轮都只看窗口内 token，历史要么‘还装得下’、要么被截断或靠摘要/检索补充。这是产品设计里管理长上下文的必修课。"},{"type":"oneline","text":"上下文窗口 = 模型处理一次输入时能同时‘看见’的 token 总量上限（如 8K / 128K）。模型没有永久记忆：每次回答都只基于【当前提问 + 窗口里装得下的前文】来推理；超出的部分会被忽略或截断。"},{"type":"intuition","blocks":[{"k":"用餐桌来想","t":"上下文窗口＝一张固定的餐桌，一次只能摆下这么多菜（token）。你点的菜超过桌面，就只能摆一部分，多余的放不下（被截断/挤掉）。想让模型‘看见’更多前文，就得在桌面腾位置。"},{"k":"用近视眼来想","t":"模型像只能看清眼前一页的近视读者：它‘当下’能读到的就是窗口内这一页（token）。你翻页太快、或书太长，它就只能看到最近一页，前面就模糊/记不住了。"},{"k":"一句话记住","t":"窗口决定‘这一次能看多少’；推理时模型只用窗口内信息作答。管理好窗口＝控制成本、长度与质量。"}]},{"type":"how","intro":"把‘一次推理’如何用上下文窗口拆开。","steps":[{"in":"① 组装输入：系统提示 + 历史对话 + 当前问题","process":"把要模型‘看到’的内容（系统指令、历史轮次、当前提问）全部转成 token，拼在一起。","out":"一串待处理的 token"},{"in":"② 检查是否超窗：超出则截断/丢弃","process":"如果这串 token 超过上下文窗口，就要截断——通常去掉最早的部分（把最旧历史丢掉）或报错。","out":"窗口内的 token 序列（旧的被挤掉）"},{"in":"③ 模型基于窗口推理：只看眼前这些","process":"模型对窗口内 token 做前向计算，生成输出。它看到的‘世界’仅限于窗口内的内容。","out":"一个基于窗口内容的回答"},{"in":"④ 输出也占窗口：新一轮把回答加进历史","process":"新生成的回答也消耗 token，下一轮会把它并进历史一起送入窗口。窗口放不下时，最老的内容再次被挤掉。","out":"对话一轮轮推进，历史越久越可能被挤走"}]},{"type":"realworld","items":[{"name":"系统提示（System Prompt）","note":"放在窗口最前面的‘设定’，指导模型身份与行为。它一直占用窗口空间，越长越‘挤占’可用的对话空间。"},{"name":"长对话为什么会‘忘’","note":"窗口有限，塞满了就从最早的开始丢。所以你说‘刚才那事’时，如果它早已被挤出窗口，模型就‘失忆’了。"},{"name":"RAG / 摘要来救场","note":"为了解决窗口有限，常用检索增强（把相关资料塞进窗口）或把历史先摘要再放进去，让模型‘看到’最关键的内容。"},{"name":"为什么窗口越大越贵","note":"窗口越大，每次处理 token 越多，计算和成本越高，延迟也越高。所以要在‘装得下’和‘别太贵’之间权衡。"}]},{"type":"compare","pairs":[{"a":"上下文窗口","b":"长期记忆","diff":"窗口是一次处理能看到的上限，用完即丢；长期记忆（如数据库/向量库）是把历史存在外部，需要时再取回塞进窗口。"},{"a":"窗口大","b":"窗口小","diff":"大窗口能装更多历史、处理长文档，但更贵更慢；小窗口便宜快，但容易丢失远历史。"},{"a":"截断最老","b":"截断最新","diff":"为保住当前问题和关键指令，通常优先丢最早的旧历史；但设计截断策略是产品细节。"},{"a":"窗口内的 token","b":"窗口外的内容","diff":"窗口内模型能‘看到’，窗口外对本次推理透明。管理好‘哪些进窗口’是做好 AI 应用的核心。"}]},{"type":"mistakes","items":["以为模型有永久记忆——它每轮只看窗口内内容，不主动记到外部。","把超长内容硬塞——会截断或报错、变贵变慢，应该先摘要/检索。","以为窗口越大越好——越大越贵越慢，够用就好。","忽略系统提示占用——过长的 system prompt 会挤占对话空间。","以为‘上轮内容必定还在窗口’——长对话久了旧内容会被挤出。"]},{"type":"deep","title":"深入一点：怎么把‘再多的历史’塞进有限窗口","beginner":["三个常用办法：①截断（只留最近）；②摘要（把旧历史浓缩成几句再放进去）；③检索（RAG，只把相关的片段取回）。","这样有限窗口能处理远超其长度的内容——不是全看，而是挑重点看。","本质：把‘无限的过去’压缩成‘有限但有信息量’的内容。"],"advanced":["KV 缓存：推理时为每个历史 token 缓存注意力 Key/Value，新轮次只需对新 token 计算，从而复用历史、提速。缓存也占用显存，受窗口与批大小影响。","窗口的‘有效长度’与注意力机制相关：超长上下文下模型对窗口中部的内容注意力会衰减，所以不是窗口越大‘有效信息’就越多。","工程：滑动窗口、压缩记忆、多轮摘要、RAG 是处理长上下文的四大主流手段；商用 API 要对 max_tokens、上下文上限、成本三者一起规划。"]},{"type":"exercise","prompt":"你的 AI 助手很奇怪：昨天聊了 500 条，今天一问‘咱昨天说的方案是啥’，它答不上来。为什么？","opts":["它丢了硬盘","500 条历史远超上下文窗口，最早的早已被挤出，今天只剩窗口内的内容","它故意装傻","因为模型只能记住今天的话"],"a":1,"explain":"模型无永久记忆，每轮只看窗口内 token。昨天 500 条早已超出窗口被挤掉，所以它‘忘’了——除非你用摘要或检索把关键内容放回窗口。","jump":"sec5-step3","jumpLabel":"模型基于窗口推理这一步"},{"type":"check","title":"结课检测：上下文窗口你懂了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"上下文窗口指的是？","opts":["模型一次能同时看到的 token 量上限","浏览器窗口大小","训练数据的来源","硬盘剩余空间"],"a":0,"explain":"上下文窗口是模型一次处理时能‘看见’的 token 总量上限，决定它能读到多少前文。","jump":"sec5-step0","jumpLabel":"组装输入这一步"},{"q":"输入超过上下文窗口时，最常发生的是？","opts":["模型偷偷多学一点","截断（通常丢最早的历史）或报错","自动扩容到无限","毫无影响"],"a":1,"explain":"超窗后通常从最早部分开始截断，或直接报错；不会无限扩容。","jump":"sec5-step1","jumpLabel":"检查是否超窗这一步"},{"q":"模型为什么‘记不住’很久以前的对话？","opts":["没有永久记忆，长对话旧内容会被挤出窗口","因为对话太长会伤显卡","模型只记一天","因为没人提醒它"],"a":0,"explain":"模型每轮只基于窗口内 token 作答，旧历史放不下就被挤掉，所以会‘健忘’。","jump":"sec5-step3","jumpLabel":"模型基于窗口推理这一步"},{"q":"处理远超窗口的长文档，常用哪种做法？","opts":["整本硬塞，靠运气","先切块/检索（RAG）把最相关的部分放进窗口","让模型用放大镜","把窗口变小"],"a":1,"explain":"用切块检索（RAG）或摘要，把关键内容装进有限窗口，是处理超长内容的主流手段。","jump":"sec8","jumpLabel":"长对话救场这一段"}],"done":"你明白了窗口的边界与记忆的关系。那怎么把‘想表达的东西’在有限窗口里说得最清楚？下一课《Prompt 与上下文》——怎么和模型说清楚。","nextLesson":"pl-prompt"},{"type":"connection","known":["Token 是计费与长度的基本单位（上一课）"],"learned":["上下文窗口 = 一次能看到的 token 上限","模型无永久记忆，只看窗口内","长对话为何会‘忘’、如何用摘要/检索救场","窗口越大越贵、KV 缓存等工程细节"],"next":"窗口里装什么是你说了算的。下一课《Prompt 与上下文》：如何把提示词组织好，让模型在窗口里看到最有用的信息。","links":[{"href":"#/lesson/l11-tokenization","text":"复习《Tokenization》"},{"href":"#/lesson/pl-prompt","text":"进入《Prompt 与上下文》"}]}]},{"id":"pl-prompt","title":"Prompt 与上下文：怎么和模型说清楚","subtitle":"同样的模型，有人问出平庸答案，有人问出惊艳答案——差别往往在 Prompt。这一课给你一套可复用的‘说清楚’框架。","category":"c05-llm","chapterTitle":"第四章 · 用起来","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["prompt","prompt-engineering","context"],"prereqLessons":["l12-context-window"],"nextLesson":"l-rag","sections":[{"type":"opening","question":"同样让 AI 写一份周报，有人得到一团废料，有人得到直接能用的。差别不在模型，而在你‘怎么说’。Prompt（提示词）到底有没有套路？","guess":"有人以为 Prompt 就是‘礼貌地多问几次’，或者要背一堆玄学咒语。","next":"这一课把 Prompt Engineering 的底层逻辑讲清楚：模型只会按你给的上下文做预测，所以‘把话说清楚、给足边界、给出期望格式’就是全部秘诀。再给你一套 Copy 就能用的模板。"},{"type":"why","before":"你用 AI 写东西、改代码、做总结，但经常要来回纠正它，效率很低。你想知道怎么一次就问出好结果。","problem":"把 Prompt 当玄学、乱堆关键词，或指望 AI‘读懂你的潜台词’，是常见的低效来源。你缺的是一套可复用的思考框架。","need":"Prompt 的本质是‘上下文工程’：你往窗口里放什么，它就拿什么推理。我给你角色-目标-约束-输出格式四件套，以及常见陷阱，让你一次问清。"},{"type":"oneline","text":"Prompt = 给模型一份清晰的‘工作说明书’：你是谁（角色）、要完成什么（目标）、边界是什么（约束/不要做什么）、交给我什么形状的结果（输出格式）。放进去的信息越清楚，拿出来的结果越可用。"},{"type":"intuition","blocks":[{"k":"用交代下属来想","t":"你给新下属派活：只说‘帮我把方案写了’＝他会一头雾水写出一堆没用的。说清楚‘背景、目标、条件、格式、例子’＝他才能一次做对。AI 就是你手下那个非常聪明但没有读心术的下属。"},{"k":"用下订单来想","t":"Prompt 像下外卖订单：你不写辣度、分量、备注，对方只能按默认做。写清楚‘不要辣、加个备注、送到了敲门’——结果才符合预期。"},{"k":"一句话记住","t":"给模型看的每句话都会影响它预测的走向。说得越明确、越有边界，输出越可控。"}]},{"type":"how","intro":"给出四件套框架，并用一个例子贯穿。","steps":[{"in":"① 角色 Role：告诉它‘你是谁、用什么视角’","process":"先设定身份与视角，例如‘你是一名有 10 年经验的数据库 DBA’‘你是小学老师’等。角色影响语气与知识取向。","out":"模型切换到对应语气与视角"},{"in":"② 目标 Task：明确要完成什么","process":"把任务说成一个清晰动词：总结、改写、翻译、设计、排查、写代码。一个 prompt 尽量只聚焦一个任务。","out":"模型知道该交付什么"},{"in":"③ 约束 Constraint：给出边界与不要做的事","process":"字数范围、语气、不要说教、不要编造、基于给定资料回答、保密等。边界越清楚，越不容易跑偏。","out":"输出被限制在期望范围"},{"in":"④ 输出格式 Format + 示例","process":"告诉它要什么形态：列表？表格？代码？JSON？给一个示例更好。格式明确后，结果可直接用、可直接解析。","out":"拿到结构化的、可用的输出"}]},{"type":"realworld","items":[{"name":"写周报的例子","note":"把四件套用上：角色‘你是我的助理’＋目标‘把本周工作整理成周报’＋约束‘不超过 8 条、语气正式’＋格式‘分 已完成/进行中/风险 三栏’——结果一步到位。"},{"name":"改代码的例子","note":"发报错原文 + 相关代码 + 你的判断（哪一层出的问题）＋要求‘说明原因并给出修复’，比只丢一个报错字串的高效得多。"},{"name":"系统提示词（System Prompt）","note":"在应用里，角色/约束常做成系统提示，每次请求都放在窗口最前，是产品级的 Prompt 管理。"},{"name":"Few-shot（给示例）","note":"在 Prompt 里附 1~2 个问答例子，模型照葫芦画瓢，输出更规范。这是提升稳定性的常用技巧。"}]},{"type":"compare","pairs":[{"a":"笼统提问","b":"四件套提问","diff":"笼统：信息少、边界模糊、结果随机；四件套：角色+目标+约束+格式，一次成功率大幅提升。"},{"a":"单向输出","b":"多轮追问","diff":"复杂任务一次难成，可把它拆成多轮：先生成骨架，再让它细化某部分。Prompt 也可以是流程。"},{"a":"Prompt","b":"微调","diff":"Prompt 不改模型，只改输入让它更好发挥；微调是改模型参数适配任务。能靠 Prompt 解决的先用 Prompt，成本低得多。"},{"a":"Prompt","b":"RAG","diff":"Prompt 靠话术组织上下文；RAG 靠检索把外部资料塞进上下文。二者常配合：先 RAG 取资料，再 Prompt 组织。"}]},{"type":"mistakes","items":["以为 Prompt 越华丽越有效——关键是信息密度与明确边界，不是堆砌形容词。","只给一句话任务，不给背景、约束、格式——模型只能自由发挥。","一次塞多个复杂任务——拆开更稳。","让模型‘自由发挥’却怪它跑偏——边界没给够。","忽略示例的价值——给一个例子常比解释十句更有效。"]},{"type":"deep","title":"深入一点：为什么 Prompt 会‘无中生有’与‘上下文工程’思想","beginner":["模型本质是在预测‘接下去最合理的文本’。Prompt 提供了‘上下文’，输出是被它引导的续写。","所以 Prompt 写得像什么风格，输出就容易是什么风格——这就是为什么示例（few-shot）很有效。","想知道模型为什么跑偏，先检查你给它的上下文是否误导了它。"],"advanced":["上下文工程（Context Engineering）：把产品要的上下文——系统提示、工具描述、检索片段、会话历史——按重要性排序并塞进有限窗口，是当前 AI 工程重头戏。","结构化 Prompt、Chain-of-Thought 引导、工具调用描述、输出 Schema 约束（如 JSON mode），都是控制生成的手段。","评估：好的 Prompt 应该‘可复现’——同一输入多次得到一致且合格的输出。用测试集回归验证 Prompt 改动，别靠手感。","警惕注入（Prompt Injection）：外部带来的文本可能被当作指令执行，产品要在边界上做隔离与校验。"]},{"type":"exercise","prompt":"你要让 AI 帮你把一段长文压缩成 3 条要点。下面哪个 Prompt 最可能一步到位？","opts":["‘帮我看看这段文字。’","‘你是我的助理。请把下面这段文字压缩成 3 条要点，每条不超过 30 字，直接给要点列表，不要其他说明。原文：…’","‘这段很厉害，你懂吧？’","‘写一篇更长的小说。’"],"a":1,"explain":"选项 B 给出了角色、目标、数量、长度、格式与材料，边界清晰，一次成功率最高。","jump":"sec5-step0","jumpLabel":"四件套框架这一段"},{"type":"check","title":"结课检测：Prompt 四件套你上手了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"Prompt 四件套通常指？","opts":["颜色、字体、布局、图标","角色、目标、约束、输出格式","开头、中段、结尾、落款","输入、输出、缓存、日志"],"a":1,"explain":"四件套：设定角色、说清目标、给边界约束、规定输出格式。","jump":"sec5-step0","jumpLabel":"角色这一步"},{"q":"为什么在 Prompt 里附 1~2 个示例（Few-shot）常能提升效果？","opts":["示例会让模型更听话","模型本质是预测续写，示例给它‘照这个风格来’的强引导","示例能扩容上下文","没有任何作用"],"a":1,"explain":"模型在预测‘接下来最合理的文本’，示例直接示范了期望的输出形态，引导作用很强。","jump":"sec6","jumpLabel":"Few-shot 这个现实话题"},{"q":"模型‘一本正经胡说八道’（幻觉）提示我们对 Prompt 该有哪种意识？","opts":["模型在预测续写而非核实事实，重要内容要靠资料（RAG）与检查","多夸它几句就不会胡说","与 Prompt 无关","改用更大的字号"],"a":0,"explain":"模型是预测性生成，不保证事实正确。关键信息要给它可靠资料并用 RAG，再要求它基于资料作答。","jump":"sec7","jumpLabel":"上下文工程与评估这一段"},{"q":"能靠 Prompt 解决的问题，为什么一般优先于微调？","opts":["因为 prompt 零成本、快、不改变模型","因为微调更慢但效果差","两者没有任何关系","因为 prompt 不可用"],"a":0,"explain":"Prompt 只改输入、不改模型，成本低、迭代快；微调要训练、成本高。能不改模型就优先用 Prompt。","jump":"sec7","jumpLabel":"上下文工程这一段"}],"done":"你会‘说清楚’了。但模型会瞎编——怎么让它基于你的真实资料回答？下一课《RAG》：让模型先查资料、再回答。","nextLesson":"l-rag"},{"type":"connection","known":["窗口里装什么是用户决定的（上一课）"],"learned":["Prompt = 上下文工程，四件套框架","Few-shot、系统提示、多轮拆解等技巧","幻觉的根源与用 RAG/检查对齐","Prompt 优先于微调的原因"],"next":"如果模型只会编，怎么让它‘基于你的资料’回答？下一课《RAG》揭晓把外部资料接进窗口的经典方案。","links":[{"href":"#/lesson/l12-context-window","text":"复习《上下文窗口与推理》"},{"href":"#/lesson/l-rag","text":"进入《RAG》"}]}]}],"c02-essentials":[{"id":"l-embedding","title":"Embedding｜怎么把词变成电脑能懂的数字","subtitle":"为什么文字不能直接进神经网络？为什么不是给每个词编个号？为什么意思相近的词离得更近？","category":"c02-essentials","chapterTitle":"第一章 · 向量与语义","level":"base","estTime":"20-25 分钟","difficulty":2,"concepts":["embedding","vector","cosine-similarity","emb-vector-store"],"prereqLessons":["l00-ai-world"],"nextLesson":"l-attention","sections":[{"type":"opening","question":"你让 ChatGPT 翻译『苹果很好吃』，它内部第一件事不是『读懂』这句话，而是把『苹果』变成了一串数字。猜一猜：为什么电脑不能用『苹果』这两个汉字直接思考，非得多此一举先转成数字？","guess":"有人会想：给猫=1、狗=2、苹果=3 编个号不就行了？","next":"这节课就回答『为什么不能简单编号』，以及真正的 Embedding 是怎么做到『意思相近的词，数字也相近』的。"},{"type":"why","before":"神经网络只会做数学运算：加法、乘法、比较大小、算距离。它天生看不懂『猫』『狗』『苹果』这些文字。","problem":"如果文字根本送不进神经网络，那后面的一切——翻译、对话、理解、检索——全都是空中楼阁。这是所有语言模型的『第一道门』，绕不过去。","need":"所以我们必须在『文字』和『数字』之间搭一座桥，让电脑既能「算」文字，又能保留文字的含义。这座桥就是 Embedding。","visualNote":"下面这张 2D 语义空间图，就是你要带走的直觉：位置 = 语义。"},{"type":"oneline","text":"Embedding 就是把『一个词』变成『一串数字（向量）』，并且让意思相近的词，数字串长得也相近——于是电脑就能『算』语义了。"},{"type":"visual","kind":"embedding-space","title":"Embedding 2D 语义空间（可交互）","hint":"这是把词『压扁』到二维的示意：意思相近的词会聚在一起。观察猫/狗/狮子聚在『动物角』，苹果/香蕉聚在『食物角』。试试输入几个词，看它落在哪一群。"},{"type":"intuition","blocks":[{"k":"为什么不能直接给词编号？","t":"你可能会想：猫=1、狗=2、苹果=3 不就行了？但问题是：2 和 3 只差 1，可『狗』和『苹果』的语义差得十万八千里。编号把『数字距离』和『语义距离』完全搞乱了——电脑会误以为狗和苹果几乎一样。"},{"k":"用一张坐标纸来想","t":"想象一张地图，横轴是『是不是动物』，纵轴是『是不是食物』。『猫』放左边靠上，『狗』紧挨它，『苹果』放右上角。位置越近，意思越像。Embedding 本质就是在几百上千维的『坐标纸』上，给每个词找个位置。"},{"k":"一个生活类比","t":"就像地理坐标：北京和天津坐标很近，所以在空间里相邻；语义相近的词，在 Embedding 空间里坐标也相邻。"}]},{"type":"how","intro":"Embedding 是怎么『学』出来的？核心思想只有一句话：一个词的含义 = 它经常和哪些词一起出现。","steps":[{"in":"收集海量文本","process":"从整个互联网语料里，观察『猫』总是和『狗、宠物、喵、毛』一起出现，而『苹果』总跟『水果、吃、红色』一起出现。","out":"得到每个词在语料里的『共现模式』"},{"in":"用共现模式训练向量","process":"训练一开始给每个词一组随机数字，然后不断调整，让『经常一起出现』的词向量越走越近，『从不一起出现』的词向量越走越远。","out":"每个词最终固定成一个固定长度的向量（如 300 或 768 维）"},{"in":"用向量距离比较语义","process":"两个词的向量越接近（夹角越小、余弦相似度越高），语义越相近。电脑从此『算得出』猫≈狗、苹果≠猫。","out":"文字第一次可以被数值比较"},{"in":"送入下游模型","process":"这个数字向量就是神经网络的输入。LLM 只认数字，现在它『看得懂』词了，可以开始做翻译、对话、生成。","out":"模型能对词做运算、比较、生成"}]},{"type":"realworld","items":[{"name":"ChatGPT / Claude","note":"内部第一件事就是把你的每个 Token 转成 Embedding 向量，再送进 Transformer 网络。"},{"name":"搜索引擎语义检索","note":"把『怎么养猫』和『养宠物指南』都向量化，语义相近就能互相匹配，不必字面相同也能搜到。"},{"name":"NotebookLM / RAG","note":"把你的资料切成块并向量化，用户提问时在向量空间里『找最像的那几块』再交给模型回答——这就是 RAG 的地基。"}]},{"type":"compare","pairs":[{"a":"Token","b":"Embedding","diff":"Token 是文字切出的『小块』（词/子词）；Embedding 是把每个小块变成的『数字向量』。先切 Token，再做 Embedding。"},{"a":"Embedding 模型","b":"LLM","diff":"Embedding 模型把文本压成『定位向量』（不生成文字）；LLM 生成文字。一个是『编码员』，一个是『作家』。"},{"a":"One-hot 编号","b":"Embedding","diff":"One-hot 让所有词互相『等距』、无法表达语义；Embedding 让相近的词更近，真正抓住含义。"}]},{"type":"mistakes","items":["以为 Embedding 只是『给每个词一个数字』。其实是一整串数字（向量），且数字之间存在『相似关系』——这才是关键。","以为 Embedding 模型和 LLM 是同一个东西。它们是分工不同的两个模型：一个负责编码相似度，一个负责生成文字。","以为向量维度越高一定越好。维度越高表达力越强，但更贵、更易过拟合，常见几百维就够用。","以为 Embedding 能『理解逻辑』。它只捕捉统计上的相似，不保证逻辑正确——所以光靠 Embedding 做问答会答非所问。"]},{"type":"deep","title":"深入一点：从二维直觉到真实向量空间","beginner":["Embedding 在工程上就是『查表』：模型里有一张巨大的表，每个词一行，那一行数字就是它的向量。训练好了之后，直接用查到的数字即可。","维度越高，能表达的语义越细腻，但计算越贵。常见几百维就够处理大多数任务。","真正常用的是一种叫『子词』的粒度：一个字被拆成更小的片段（如 'unbreakable' → 'un' + 'break' + 'able'），这样遇到没见过的词也能拼出向量。"],"advanced":["向量不只给每个词一个『标签』，它把语义结构编进了几何里：经典例子 king − man + woman ≈ queen，说明向量『方向』也承载意义。","Embedding 模型（如 text-embedding 系列）与 LLM 是不同模型：前者把文本压缩成『定位码』，后者生成文字。它们可以分开训练、分开使用。","计算两个向量有多像，最常用的指标是**余弦相似度** cos(θ)：只看方向、不看长度，数值越接近 1 越像。",{"code":"# 余弦相似度：越大越像\nimport numpy as np\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\ncat   = np.array([0.9, 0.1])   # 靠近动物方向\napple = np.array([0.1, 0.9])   # 靠近食物方向\ndog   = np.array([0.85, 0.15]) # 很接近猫\n\nprint(round(cosine(cat, apple), 2))  # 0.22  → 语义远\nprint(round(cosine(cat, dog), 2))    # 1.0   → 语义很近","lang":"python"},"维度本质：真实 Embedding（如 OpenAI text-embedding-3）常达上千维，一个词就是一个上千维空间里的点。降维可视化（t-SNE / PCA）只是把上千维『压扁』到 2D 方便人看。"]},{"type":"exercise","prompt":"在一个语义空间里，『国王』向量减去『男人』向量，再加上『女人』向量，猜一猜结果最可能靠近下面哪个词？","opts":["王子","女王（皇后）","父亲","阿姨"],"a":1,"explain":"这正是著名的 king − man + woman ≈ queen 现象：向量的方向承载意义，『王 - 男 + 女』就指向『女王』的方向。它说明 Embedding 抓到的不是孤立的词，而是语义结构。","jump":"sec5-step3","jumpLabel":"用向量距离比较语义这一步"},{"type":"check","title":"结课检测：你真正理解 Embedding 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"为什么不能直接给每个词编个号（猫=1，狗=2，苹果=3）？","opts":["因为编号会让相近的词距离更近","因为编号会破坏语义距离：狗和苹果只差 1，但语义差很远","因为编号需要太多内存","因为编号不能用于神经网络"],"a":1,"explain":"编号把数字距离和语义距离搞混了：狗(2)和苹果(3)只差1会被当成很相似，但它们的含义毫无关系。","jump":"sec4","jumpLabel":"『为什么不能直接给词编号』这一段"},{"q":"两个 Embedding 向量夹角越小（余弦相似度越高），说明什么？","opts":["两个词的语义越相近","两个词的字符串越长越像","两个词出现频率越接近","两个词的长度越接近"],"a":0,"explain":"夹角越小，向量在空间里越靠近，代表语义越相近。这就是『用距离算语义』。","jump":"sec5-step2","jumpLabel":"『用向量距离比较语义』这一步"},{"q":"关于 Embedding 模型与 LLM 的关系，正确的是？","opts":["它们是同一个模型","Embedding 模型把文本变向量、LLM 生成文字，二者分工不同","LLM 内部根本不做 Embedding","Embedding 模型能直接写文章"],"a":1,"explain":"Embedding 模型负责『编码相似度』，LLM 负责『生成内容』，是两个可分开训练的模型。","jump":"sec7","jumpLabel":"『Embedding 模型 vs LLM』那一条对比"},{"q":"Embedding 的『含义』主要来自哪里？","opts":["每个字在字典里的官方解释","这个模型『预测下一个词』时学到的共现模式","开发者手写的规则","词的笔画数"],"a":1,"explain":"一个词的含义 = 它常和哪些词一起出现。模型在大量文本上学到的正是这种共现模式。","jump":"sec5-step0","jumpLabel":"『收集海量文本』这一步"},{"q":"下面哪句关于向量维度的说法正确？","opts":["维度越高一定越好，越细越好","维度越低越好，因为一定更便宜","维度是表达力与成本的权衡，常见几百维就够用，过高更贵且易过拟合","维度只影响颜色不影响语义"],"a":2,"explain":"维度是权衡的结果：高维表达强但贵且易过拟合，低维省但表达粗糙。实际常用几百维。","jump":"sec9","jumpLabel":"深入一节关于维度的说明"}],"done":"你已经理解了『文字 → 数字向量 → 算距离』这条链路，这是 RAG、搜索、推荐共同的地基。","nextLesson":"l-attention"},{"type":"connection","known":["AI 世界全景：模型只能处理数字","Embedding 是文字进入模型的第一道门"],"learned":["文字 → 向量，让电脑能算语义","相近的词向量距离更近，用余弦相似度衡量","Embedding 模型与 LLM 分工不同","向量方向也能承载意义（king − man + woman ≈ queen）"],"next":"有了『每个词是一个数字向量』，下一步就是大招：Attention——模型怎么在一句话里决定『该重点关注哪个词』。这决定了模型能不能读懂『这只狗没咬那只猫，是因为它怕它』里『它』到底指谁。"}]}],"c07-rag":[{"id":"l-rag","title":"RAG｜让模型『查资料』再回答","subtitle":"为什么 ChatGPT 不知道你的私有文档？怎么让模型『翻开你的资料』再回答？从切块到生成，一条流水线看懂 RAG。","category":"c07-rag","chapterTitle":"第一章 · RAG 全流程","level":"base","estTime":"30-35 分钟","difficulty":2,"concepts":["rag-pain","rag-pipeline","chunking","emb-vector-store","vector-search","rerank"],"prereqLessons":["l-transformer","l-embedding"],"nextLesson":"pl-function-calling","sections":[{"type":"opening","question":"你的同事把公司 80 页的员工手册发给你，让你问 ChatGPT『年假到底有几天』。但 ChatGPT 根本没见过这本手册——你猜它是会照着手册答，还是自己编一个答案？如果它答错了，该怎么办？","guess":"很多人觉得「那就把整本手册贴上问它」。但手册几十万字，靠粘贴根本塞不进一次对话，而且重点会淹没在噪声里。","next":"这节课要讲的就是正解：RAG 检索增强生成。它让模型在回答前，先去你的资料库里『只挑最相关的几段』，再照着这几段回答——既答得准，又附出处。"},{"type":"why","before":"经过前面几课，我们已经有了一个很聪明的模型（Decoder-only Transformer）。但它有一个致命限制：它只知道训练时见过的东西，而且经常一本正经地编造（幻觉）。","problem":"1) 你的合同、内部 SOP、论文——模型训练时根本没看过；2) 即使看过，版本也早就过期了；3) 让它硬答私有问题，它大概率会编。而重新训练整个模型，又贵又慢又不可能频繁做。","need":"与其改模型的『脑子』，不如每次回答时给它配一本『说明书』：先把相关的资料找出来喂给它，让它照着说。这个思路就是 RAG——简单、便宜、资料随时能更新。","visualNote":"下面这条流水线是 RAG 的完整精神：切块 → 向量化 → 检索 → 重排 → 组装 → 生成。你可以点『运行』亲手体验。"},{"type":"oneline","text":"RAG（检索增强生成）就是：让模型在回答之前，先去你的资料库里检索相关内容，把查到的片段拼进上下文，再让模型照着一小份『精选资料』作答。于是它能回答自己没学过的私有知识，还能顺便指出出处。"},{"type":"visual","kind":"rag-pipeline","title":"RAG 完整流水线：从文档到回答（可交互）","hint":"这就是升级版可交互 RAG 实验：左边填一份『你要提问的文档』，下面输问题，点【▶ 运行 RAG】。观察系统如何切块 → 向量化 → 检索 → 重排 → 组装上下文 → 生成带引用的回答。"},{"type":"intuition","blocks":[{"k":"开卷考试 vs 闭卷考试","t":"普通 LLM 是闭卷考试：只凭脑子里的记忆答题，记不住就编。RAG 是开卷考试：允许你翻资料，翻到相关的那页再答。显然开卷更可靠、更可核对。"},{"k":"图书馆查书再回答","t":"你问『公司年假制度是什么』。RAG 不会直接在记忆里编，而是先去公司知识库检索年假相关文档，找到后引用着回答。"},{"k":"不是变聪明，是带了参考书","t":"RAG 不提升模型智商，而是每次回答都带着最新、属于你的资料。资料一更新，回答立刻跟着更新，完全不用重新训练模型。"}]},{"type":"how","intro":"RAG 分两个阶段：『入库』（离线，把文档变成可检索的向量库）和『查询』（在线，用户提问时检索 + 生成）。下面是完整流程，也是本课的主干。","steps":[{"in":"先想清楚：为什么要用 RAG","process":"场景判断：需要回答私有/最新/超长知识，或答案需要可溯源时用 RAG。如果模型自带答案且内容不敏感，也许不需要 RAG。","out":"RAG 解决『知识更新与私有化』，不是『让模型变聪明』"},{"in":"解析 Parsing","process":"把原始文档（PDF、Word、网页）用解析器抽取出结构化文本，去掉页眉页脚、图表残渣，必要时做 OCR。","out":"干净、可用的纯文本"},{"in":"切块 Chunking","process":"把长的文本切成几百到上千字的小块。切多大、是否重叠、按什么切（标题/段落）直接影响检索质量。","out":"文档 → 若干 chunk（带来源、页码等元数据）"},{"in":"向量化 Embedding","process":"用 Embedding 模型把每个 chunk 变成一个向量（语义相近的向量相近）。","out":"每个 chunk → 一个向量"},{"in":"存入向量库 VectorDB","process":"把『向量 + 原文 + 元数据』存进向量数据库（FAISS、Milvus、pgvector、Qdrant），并建好索引以便毫秒级检索。","out":"可快速相似检索的向量库"},{"in":"检索 Retrieval（含 Top-K）","process":"用户提问时，把问题也向量化，在向量库里找最像的『Top-K 块』（通常 K=5~20，按余弦相似度排名）。","out":"问题 → 排好序的 N 个候选 chunk"},{"in":"重排序 Rerank","process":"初筛的 Top-K 往往有噪音。用一个更精细的模型把 K 个候选再精排，把真正相关的提到最前、滤掉无关项。","out":"更精准的少量片段（通常取前 3~5 块）"},{"in":"组装上下文 + 生成","process":"把精选 chunks 拼进 Prompt，附上问题，提示模型『只依据下面资料回答并引用出处』。LLM 据此生成带引用的回答。","out":"有出处、可更新、针对私有知识的回答"}]},{"type":"realworld","items":[{"name":"NotebookLM","note":"你上传 PDF/视频，它检索你的资料再回答，还能生成带引用的播客、摘要。教科书级 RAG 产品。"},{"name":"企业内部知识库客服","note":"把 SOP、产品手册向量化，客服 AI 查文档再回答，而不是对着空气编。"},{"name":"Claude Projects / 附件上传","note":"给对话挂上资料，模型按需检索引用，本质是一套轻量 RAG。"},{"name":"搜索增强的 ChatGPT / Perplexity","note":"它先联网检索实时网页，再基于检索结果回答——用互联网当『向量库』的 RAG。"}]},{"type":"compare","pairs":[{"a":"RAG","b":"微调 Fine-tuning","diff":"RAG 每次查最新资料、可溯源、便宜、可随时更新；微调是改模型脑子、更适合学风格学格式。知识类更新首选 RAG。"},{"a":"向量检索（语义）","b":"关键词检索（BM25）","diff":"向量找语义相近（换个说法也能找到）；关键词精准匹配字面（找人名/编号更稳）。生产常用『混合检索』互补。"},{"a":"RAG","b":"超长上下文","diff":"RAG 主动挑最相关片段、便宜快速；超长上下文把整本书塞进去、贵且重点容易淹没。大资料库优先 RAG。"},{"a":"RAG","b":"Agent","diff":"RAG 是『查资料再回答的单步机制』；Agent 是『多步决策、自己调用工具的循环』。两者常配合：Agent 需要信息时用 RAG。"}]},{"type":"mistakes","items":["以为 RAG = 把文档一股脑塞进提示词。真正的 RAG 要先切块、向量化、检索、重排，只喂最相关的几块。","忽略 chunking 质量。切坏了，再好的模型也答不准——检索进来自的都是垃圾，这叫『垃圾进、垃圾出』。","以为检索到就完了、不必做 rerank。初检的 Top-K 常有噪音，重排能明显提高准确率。","忘记引用溯源。落地到医疗/法务/企业等严肃场景，没有出处等于不可信。","把 RAG 当成解决幻觉的万灵药。资料里没有、或检索失败时，模型照样可能编——还要做『越权拒答』『检索兜底』。","只在单文档上跑 RAG 就上生产。跨多文档局部推理（关系、总分结构）需要更进阶的方案（如 GraphRAG、切分策略优化）。"]},{"type":"deep","title":"深入一点：把 RAG 的每一个零件都拆开","beginner":["chunk 太小 → 语义不完整；chunk 太大 → 噪音多、可能被截断。常见几百~一千字，配合 20%~50% 重叠（overlap）避免把完整语义在边界切断。","向量相似 ≠ 字面相似：换个说法（『年假』vs『带薪假期』）有时也能检索到，这是向量检索比关键词强的地方。","RAG 不会凭空创造知识，它只会引用你给的东西——资料库质量 ≈ 回答质量。","Top-K 的含义：K 是取前几个相似块。K 太小漏信息，K 太大引入噪音挤占上下文，通常 5~20 之间调。"],"advanced":["混合检索（Hybrid）：向量检索（语义）+ 关键词检索（BM25，精确匹配人名/编号）并行，再用加权或 RRF 融合，互补漏检。","Rerank 为什么必要：初检向量健壮但不精，专门的 rerank 模型（cross-encoder）能逐对精判相关性，显著提升准确率和最终回答质量。","引用溯源（Citation / Grounding）：让模型输出带片段编号，用户可核对来源；对合规落地几乎是刚需。","切分进阶：按章节/标题等『结构感知』切块（structure-aware chunking）、父子块（parent-child）、滚动窗口，都比盲目按字数切更好。","评估：用『召回率（该找到的找到没）+ 准确率（找到的是不是都相关）』评价检索，用『忠实度/有据率』评价最终回答，还要做『检索失败与拒答』的兜底。","Agentic RAG：把检索从单次升级成『多轮自主规划』——Agent 先判断需要什么信息、决定检索哪几个库、必要时多轮追问或修正查询词，而不是一次检索定死。",{"code":"# 概念示意：RAG 里最核心的一步——向量检索（伪代码思路）\nimport numpy as np\n\nchunks = [\"年假制度：入职满一年享 5 天…\", \"报销流程：金额低于 1000 走 OA…\"]\nchunk_vecs = [np.array([0.9, 0.1]), np.array([0.1, 0.9])]  # 示意向量\n\ndef cosine(a, b):\n    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))\n\nquery_vec = np.array([0.85, 0.15])  # 用户问题『年假有几天』向量化\ntop_k = 1\nranked = sorted(((cosine(query_vec, v), i) for i, v in enumerate(chunk_vecs)),\n                reverse=True)[:top_k]\nprint('最相关的资料块:', chunks[ranked[0][1]])\n# → 年假制度那一段","lang":"python"}]},{"type":"exercise","prompt":"继上一课：公司手册 80 页，你的知识库已经把它切成几百块并存好向量。现在问『年假有几天』，系统检索返回了 8 个候选块，其中第 3 块是『员工福利总览』、第 7 块是『请假制度细则』。下一步系统应该做什么？","opts":["直接把 8 块全部塞进提示词","对 8 块做 Rerank 精排，只取最相关的 3~5 块再喂给模型","不用检索了，直接让模型猜","把 8 块向量相加存回库里"],"a":1,"explain":"初检的 Top-K 常有噪音。正确做法是先 Rerank 精排，把真正相关的『请假制度』提到最前、滤掉无关的『福利总览』，再只喂少量精选块给模型——既省上下文又更准。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"type":"check","title":"结课检测：你真的理解 RAG 了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"RAG 解决的核心问题是？","opts":["让模型数学更好","让模型能回答私有/最新知识并可溯源，而不用重新训练","让模型更快生成","让模型学会编程"],"a":1,"explain":"RAG 的核心价值：用检索到的外部资料补充模型没学过的知识，便宜、可更新、可引用。","jump":"sec5-step0","jumpLabel":"先想清楚为什么要用 RAG 这一步"},{"q":"RAG 的『入库』阶段，正确的顺序是？","opts":["向量化 → 切块 → 存库","切块 → 向量化 → 存库","存库 → 向量化 → 切块","检索 → 切块 → 向量化"],"a":1,"explain":"先把长文档切成 chunk，再逐块向量化，最后连向量带原文存进向量库。检索是查询阶段的事。","jump":"sec5-step2","jumpLabel":"切块 Chunking 这一步"},{"q":"『切块太大（比如把整章当一个块）』最可能带来什么问题？","opts":["向量库存不下","块内噪声多、关键信息被淹没，检索和回答变差","一定比小块更准","会让模型忘掉上下文"],"a":1,"explain":"块太大噪声多、语义杂，检索命中后无关内容挤占上下文，回答质量下降。所以要用合适的块大小 + 重叠。","jump":"sec9","jumpLabel":"深入节里关于 chunk 大小/重叠的说明"},{"q":"为什么生产系统里还要做 Rerank 重排？","opts":["为了多花一点算力","初检的 Top-K 常有噪音，用更精细的模型重排能显著提升相关性与准确率","为了把回答变长","为了跳过 Embedding"],"a":1,"explain":"向量初检健壮但不精，专门的 rerank 模型能逐对精判，把真正相关的片段提到最前。","jump":"sec5-step6","jumpLabel":"重排序 Rerank 这一步"},{"q":"资料库里根本没有答案时，一个设计良好的 RAG 系统应该？","opts":["强行编一个最像的答案","在引用不到出处时明确『资料中未找到』或拒答，做检索兜底","把用户问题原样丢回","删掉这个问题"],"a":1,"explain":"RAG 不是幻觉万灵药。检索不到可靠出处时应『越权拒答/检索兜底』，而不是硬编。","jump":"sec8","jumpLabel":"『把 RAG 当万灵药』那条误区"}],"done":"你已经掌握 RAG 的完整流水线和调优要点。现在模型会查资料了，但它还是『你问一句、它答一句』。最后一课，我们让它自己动起手来。","nextLesson":"l-agent"},{"type":"connection","known":["Embedding：文字 → 向量，语义相近的向量相近","Transformer：模型的脑子","上下文窗口：模型一次能看多少"],"learned":["RAG 让模型先检索资料再回答，解决私有/最新/可溯源","完整流程：解析 → 切块 → 向量化 → 向量库 → 检索 Top-K → 重排 → 组装 → 生成 + 引用","chunk 大小/重叠、混合检索、Top-K、rerank、评估、Agentic RAG 等调优点","RAG vs 微调 vs 长上下文 vs Agent 的取舍"],"next":"RAG 让模型会查资料，但模型仍停在你说一句、它应一句。下一课是这个旅程的终点也是新起点：Agent——让模型自己拆目标、自己调用工具、根据反馈循环，把一整件事独立做完。"}]}],"c01-ai-world":[{"id":"l00-ai-world","title":"一张图看懂整个 AI 世界","subtitle":"在学任何一个概念之前，先拿到整张地图：你现在站在哪里，接下来要走到哪里。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"15-20 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl","ai-apps","ai-limits"],"prereqLessons":[],"nextLesson":"l01-ai-vs-ml-dl","sections":[{"type":"opening","question":"你每天听到的 ChatGPT、大语言模型（LLM）、Transformer、Agent、RAG……它们到底谁包含谁、谁建在谁之上？如果你现在只能用一句话回答「它们是什么关系」，你会怎么说？","guess":"很多人会脱口而出「都是一回事，就是 AI」。","next":"这节课不教任何公式，只画一张总地图。学完你不仅能说清这些词的关系，还能知道接下来 5 节旗舰课各自站在这张地图的哪个格子里。"},{"type":"why","before":"你在标题、文章、面试里反复遇到 Token、Attention、Transformer、RAG、Agent、Fine-tune……每个词单独看都懂一点，但凑在一起就乱。","problem":"初学者最大的障碍不是「不够努力」，而是没有地图：他不知道现在学的东西将来会连到哪里，于是学一个忘一个，越学越焦虑。","need":"所以第一节课我们不讲任何实现细节，只建立骨架：AI 世界分哪几层、每一层由什么构成、你将来要学的每一块长在哪个位置。地图在手里，后面的路才走得稳。"},{"type":"oneline","text":"AI（人工智能）是整片森林；机器学习是其中『会自己从数据里找规律』的那片林子；深度学习是最能长的那几棵大树；大语言模型（LLM）是最近最抢眼、能和你聊天的那一棵；而 RAG、Agent 这些，是围绕这棵树搭起来的『脚手架』——让树上的果子更好摘。"},{"type":"visual","kind":"ai-world-map","title":"AI 世界全景图","hint":"从最外层的 AI 一路收缩到 LLM，再向外展开 Vision / Speech / Agent / RAG 等应用方向。点击让你看明白的节点，就能往下一层走。"},{"type":"intuition","blocks":[{"k":"用俄罗斯套娃来想","t":"AI 是最大的套娃，机器学习是里面一层，深度学习再里面一层，LLM 是最小最精致的那层。每往里一层，都建立在外层之上——这叫『包含』，不是『并列』。"},{"k":"用搭积木来想","t":"只给你一个 LLM 你只能『聊天』。但当你往它外面搭『检索』（RAG）、『工具调用』（Agent）、『工作流编排』（Workflow）这些积木，你就从『会聊天』升级成『会办事』。产品形态 = 模型 + 一层层积木。"},{"k":"一句话记住主干","t":"AI ⊃ ML ⊃ DeepLearning ⊃ Foundation Model ⊃ LLM。这一个箭头链，就是整张地图的主干，也串起了你即将学的六节课。"}]},{"type":"how","intro":"把 AI 世界拆成「五层结构」与「五大应用方向」，你学完至少知道每块知识的归属，再也不会把它们混为一谈。","steps":[{"in":"第 0 层 · AI（人工智能）","process":"最上层总称：让机器表现出智能的一切技术，包括早期靠人写规则、搜索、专家系统。","out":"范围最大，是『目标』而不是某一门具体技术"},{"in":"第 1 层 · Machine Learning 机器学习","process":"不再靠人写死规则，而是让机器从数据里『自己找规律』，再拿规律去做预测。","out":"监督学习 / 无监督学习 / 强化学习 三大流派"},{"in":"第 2 层 · Deep Learning 深度学习","process":"用『多层神经网络』来自动提取特征，是机器学习的子集，能力更强：不用人手设计特征。","out":"CNN（图像）、RNN/Transformer（序列）、扩散模型（生成）等结构"},{"in":"第 3 层 · Foundation Model 基础模型","process":"在大规模数据上预训练好的『通用大脑』，可以微调或直接复用到很多不同任务。","out":"LLM（语言）、视觉基础模型、多模态基础模型"},{"in":"第 4 层 · LLM 大语言模型","process":"把『预测下一个词』当唯一训练目标，靠海量文本硬学出来的语言模型，意外获得了语言与世界的知识。","out":"ChatGPT、Claude、Gemini 背后的模型本体"},{"in":"围绕 LLM 的『脚手架』与应用架构","process":"光会聊天不够，为了让模型能办成事，在外面叠加外围技术。","out":"Prompt 提示 · RAG 检索增强 · Workflow 工作流 · Agent 智能体 · 多模态"}]},{"type":"realworld","items":[{"name":"ChatGPT","note":"「纯 LLM 对话产品」：你打字，它预测下一段话。它本身不做检索也不调工具，是最纯粹的一层。"},{"name":"Claude / Gemini","note":"同样是 LLM 驱动的对话产品，但在模型能力与对齐上做得不同，代表『同一个塔、不同的果』。"},{"name":"NotebookLM / 企业知识库问答","note":"「LLM + RAG」：你上传私有资料，系统先检索相关片段，再让模型基于这些片段回答，杜绝凭空编造。"},{"name":"Workflow 编排（如 Zapier AI / Coze 工作流）","note":"「LLM + 规则流程」：把『先做A、判断结果再做B』写成固定流水线，模型只负责其中某一环。"},{"name":"Codex / Claude Code","note":"「LLM + Agent 智能体」：不只是回答，还能自主决定『读文件→改代码→跑测试→看报错→再改』，直到把活干完。"},{"name":"Midjourney / Sora","note":"「不是 LLM 的另一棵树」：用扩散模型做图像/视频生成。提醒你 AI 世界不只有语言这一棵大树。"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是「目标——机器有智能」；机器学习是实现它的一种主流手段（用数据学出来）。早期用规则实现的人工智能，不属于机器学习，但仍然属于 AI。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是「从数据学习」；机器学习范围更大（含决策树、SVM 等传统算法），深度学习专指用多层神经网络，能自动提取特征，是机器学习的一个子集。"},{"a":"LLM","b":"Foundation Model","diff":"LLM 是专做语言的基础模型；Foundation Model 是更大的类，还包括视觉、多模态基础模型。LLM ⊂ 基础模型。"},{"a":"RAG","b":"Agent","diff":"RAG 是『给模型外接资料库』的检索增强；Agent 是『让模型自主决策与调用工具』的智能体。两者常配合：Agent 需要信息时用 RAG 检索。它们都不是模型本身，而是脚手架。"},{"a":"模型（Model）","b":"产品（Product）","diff":"模型是被训练出来的『大脑』；产品是把这个大脑装进界面、加上检索/记忆/工具后的完整应用。你用的是产品，不直接是模型。"}]},{"type":"mistakes","items":["把「AI、机器学习、深度学习、LLM」当同义词——它们是一层层包含关系，不是并列。","以为 ChatGPT = 整个 AI。ChatGPT 只是 LLM 的一颗果实；AI 世界还有视觉、语音、生成、机器人、Agent 等一大片。","以为 RAG 和 Agent 是「模型」。它们是在模型外面搭的脚手架/架构，本身没有『大脑』。","以为只有学完高等数学才能开始。第一门旗舰课（Embedding）就能带你把概念走通，数学按「够用」给，不是研究生讲义。","以为 Fine-tuning（微调）和 RAG 是一回事。前者改模型自身权重，后者不改模型、只改给它看的外部资料——它们解决不同问题。"]},{"type":"deep","title":"深入一点：把「领域 / 模型 / 技术 / 应用架构 / 产品形态」五顶帽子分清楚","beginner":["用「帽子」来记：同一个东西，问问题的角度不同，答案就不同。","「这属于哪个**领域**？」—— 问的是地图范围（AI、ML、DL 是领域/学科级）。","「这是个什么**模型**？」—— 问的是被训练出来的产物（LLM、扩散模型、视觉模型是模型级）。","「用了什么**技术/算法**？」—— 问的是怎么做（Attention、Transformer、RAG 检索是技术级）。","「这是什么**应用架构**？」—— 问的是怎么组合（RAG 架构、Agent 循环、Workflow 流水线是架构级）。","「最终做成什么**产品**？」—— 问的是用户能用的东西（ChatGPT、Codex、NotebookLM 是产品级）。"],"advanced":["用一条「从模型到产品」的抽象层次链来定位任何 AI 名词：","「AI 世界 = 领域层（AI⊃ML⊃DL）→ 模型层（Foundation Model→LLM/Diffusion/多模态）→ 技术层（Attention、位置编码、损失函数）→ 架构层（RAG、Agent、Workflow、多智能体协作）→ 产品层（ChatGPT、Claude Code）」。","判断法则：问「它能不能被『训练』出来」？能 → 模型层或更深；问「它是不是一个『零件/接法』」？能 → 技术层或架构层。训练产物是模型，接法是架构。","示例定位：Transformer 是技术层（一种网络结构）；GPT 系列是基于 Transformer 训练出来的模型（模型层）；把 GPT 接上检索= RAG 架构（架构层）；打包成网站= ChatGPT 产品（产品层）。","顺带一个工程事实：你平时说的「大模型」绝大多数指 LLM 或基础模型；而「智能体」「Agent」在业界常被定义为『模型 + 记忆 + 规划 + 工具调用』，是一个架构概念而非单个模型。"]},{"type":"exercise","prompt":"你现在打开了一款「企业知识库问答」App，上传公司政策文件后提了个问题，系统给出的回答里标注了「依据文件第 3 页」。你觉得它最可能是下面哪种组合？","opts":["只有 LLM，全靠模型自己编","LLM + RAG（先检索你的文件，再基于片段回答）","LLM + Agent（让模型自己去改代码）","纯扩散模型"],"a":1,"explain":"回答『依据你上传的文件』并带引用，正是 RAG 的典型特征：先检索相关片段，再让模型基于片段生成答案。","jump":"sec5-step5","jumpLabel":"围绕 LLM 的脚手架（RAG 检索）这一段"},{"type":"check","title":"结课检测：你真的懂这幅地图了吗","intro":"共 5 题。答错的题会带你回到对应段落复习。","questions":[{"q":"下面哪条包含关系是正确的？","opts":["AI ⊃ LLM ⊃ Deep Learning ⊃ ML","AI ⊃ ML ⊃ Deep Learning ⊃ LLM","LLM ⊃ AI ⊃ ML ⊃ Deep","Deep Learning ⊃ ML ⊃ AI ⊃ LLM"],"a":1,"explain":"AI 包含机器学习，机器学习包含深度学习，LLM 是深度学习上长出的具体模型。","jump":"sec5-step0","jumpLabel":"五层结构第一步"},{"q":"ChatGPT 最准确地说是下面哪一个？","opts":["一个 Agent 智能体","一个纯 LLM 对话产品","一个 RAG 系统","一个视觉模型"],"a":1,"explain":"ChatGPT 的核心就是大语言模型：输入→预测下一段。RAG/Agent 是对它的增强，而不是它的本质。","jump":"sec5-step4","jumpLabel":"第 4 层 LLM 这一段"},{"q":"「NotebookLM 先查你上传的资料再回答」主要用到了哪项技术？","opts":["RAG 检索增强生成","纯预训练","扩散模型","只靠提示词"],"a":0,"explain":"针对私有资料，RAG 让模型先检索相关片段再回答，这正是 NotebookLM 类产品的核心。","jump":"sec5-step5","jumpLabel":"脚手架之 RAG 这一段"},{"q":"Codex「自己读代码、改代码、跑测试、看报错再重试」的能力，对应哪种架构？","opts":["RAG 检索增强","Agent 智能体循环","纯一次性生成","工作流固定流水线"],"a":1,"explain":"自主决策 + 调用工具 + 根据反馈循环，这正是 Agent 的核心：想→做→看→再想。","jump":"sec5-step5","jumpLabel":"脚手架之 Agent 这一段"},{"q":"「Midjourney 能生成图片」用到的模型，和 ChatGPT 的 LLM 是什么关系？","opts":["同一个模型","都是 LLM","Midjourney 用的是扩散模型，是 AI 世界里另一棵大树","Midjourney 不用 AI"],"a":2,"explain":"图像生成多靠扩散模型（Diffusion），与语言类的 LLM 是并列的不同模型，提醒你 AI 世界不止语言一棵树。","jump":"sec6","jumpLabel":"现实应用里的 Midjourney / Sora"}],"done":"现在你手里有整张地图了。接下来我们要下到模型的正下方——先搞清楚：电脑到底怎么把一句话变成它算得动的『数字』。","nextLesson":"l-embedding"},{"type":"connection","known":["（这是第一节课，还没有前置知识）"],"learned":["AI → ML → DL → Foundation Model → LLM 的主干链条（包含关系）","领域 / 模型 / 技术 / 应用架构 / 产品形态 五顶帽子怎么分","RAG、Agent、Workflow 是围绕 LLM 的脚手架，不是模型","ChatGPT、Claude（LLM产品）、NotebookLM（RAG）、Coze（工作流）、Codex（Agent）、Midjourney（扩散）各代表一类"],"next":"下一课我们钻到模型正下方：Embedding——电脑怎么把『一句话』变成『一串数字』。这是理解 LLM 的第一块砖，也是 RAG、搜索、推荐的地基。"}]},{"id":"l01-ai-vs-ml-dl","title":"AI / Machine Learning / Deep Learning 到底什么关系","subtitle":"三个天天混着用的词，其实是三层包含关系。把它们理清，你才不会再被『这不是深度学习吗』『这算 AI 吗』这类问题卡住。","category":"c01-ai-world","chapterTitle":"第一章 · AI 全景","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["ai-what","ai-ml-dl"],"prereqLessons":["l00-ai-world"],"nextLesson":"pl-train-infer","sections":[{"type":"opening","question":"面试、文章、和同行聊天里，你几乎天天听到『AI』『机器学习』『深度学习』这三个词。它们到底是同义词，还是完全不同的东西？下面的说法，哪句最接近事实？","guess":"很多人觉得它们是同一件事的不同叫法，可以随便混用。","next":"上一课你拿到了整张 AI 世界地图。这一课我们只解决一个词根问题：AI、机器学习（ML）、深度学习（DL）谁包含谁。理清这层包含关系后，后面讲到神经网络、大模型时，你就知道它们各自站在哪一层。"},{"type":"why","before":"你读了文章，看到『用机器学习做了个推荐』，又看到『深度学习模型碾压传统算法』，还有『人工智能正在改变世界』。三个词来回出现，你分不清它们是不是一回事。","problem":"如果不理清，你会把它们当成可互换的词。结果就是：该用『AI 这个概念』时却拿『深度学习』去套，理解错位，越学越混乱。更关键的是，它影响了你的地图感——你不知道每一个具体技术在大结构里的归属。","need":"所以我们要把『包含关系』这条线彻底拉直：AI 是最外层的大概念，机器学习是实现 AI 的主流手段，深度学习又是机器学习里最强的一个分支。记住这一个箭头链，比背一百个术语都有用。"},{"type":"oneline","text":"AI（人工智能）是整片森林；机器学习（ML）是森林里『让程序从数据中自己找规律』这一派；深度学习（DL）是这一派里靠『多层神经网络』自动提取特征、效果最强的一支；而大语言模型（LLM）是深度学习在语言上结出的果子。"},{"type":"intuition","blocks":[{"k":"用俄罗斯套娃想","t":"AI 是最外面的大套娃，机器学习是里面一层，深度学习再里面一层。每一个内层都建立在外层之上。『它是 AI 吗？』——所有机器学习、深度学习都属于 AI；但『它是机器学习吗？』——只有 AI 的一部分才是。"},{"k":"用交通工具想","t":"AI＝『交通工具』这个大分类；机器学习＝其中『能自己开的车』；深度学习＝车里面『最豪华、自动驾驶能力最强的那批』。你要去的地方（目标）叫 AI，但真正驱动现在的靠的是深度学习这辆快车。"},{"k":"一句话记住","t":"AI ⊃ ML ⊃ DL。哪个词越大，哪一个就越『含』后面的。说『大模型是深度学习』正确，说『深度学习就是 AI』则太窄。"}]},{"type":"how","intro":"把三层关系拆开看：每一层『是什么、靠什么实现、典型代表是谁』。","steps":[{"in":"第 0 层 · AI 人工智能（最外圈）","process":"让机器表现出智能的一切技术。范围最广，既包括学出来的，也包括早期靠人写规则、专家系统、搜索的『传统 AI』。","out":"AI 是一个『目标 / 领域』，不是某一门固定技术"},{"in":"第 1 层 · 机器学习 ML","process":"AI 的一条主流路径：不再由人写死规则，而是给程序大量数据，让它自己找出规律，再拿规律预测没见过的新数据。","out":"监督学习 / 无监督学习 / 强化学习 三大流派"},{"in":"第 2 层 · 深度学习 DL","process":"机器学习里靠『多层神经网络』的那一支。区别在于：它无需人手设计特征，网络自己逐层提取。数据、算力上去后，效果远超传统 ML。","out":"CNN（图像）、RNN、Transformer、扩散模型等现代结构"},{"in":"果实 · 大语言模型 LLM","process":"把深度学习用在语言上，用『预测下一个词』的目标在海量文字上训练出来的模型。它是当下 AI 浪潮最亮眼的具体成果。","out":"ChatGPT、Claude、Gemini 背后的模型本体"}]},{"type":"compare","pairs":[{"a":"AI","b":"Machine Learning","diff":"AI 是目标——机器有智能；ML 是达成目标的主流手段——从数据里学规律。早期用规则实现的人工智能属于 AI、但不属于 ML。"},{"a":"Machine Learning","b":"Deep Learning","diff":"都是『从数据学习』；ML 范围更大（含决策树、SVM 等传统算法），DL 专指用多层神经网络，能自动提取特征，是 ML 的子集，也是当下主力。"},{"a":"DL","b":"LLM","diff":"DL 是方法（多层神经网络）；LLM 是用 DL 专门处理语言、以预测下一个词为目标的产物。LLM 是 DL 在语言上的具体应用果实。"},{"a":"传统规则 AI","b":"机器学习","diff":"传统规则 AI 是人手动写 if-else 规则，机器不会自己学；ML 让机器从数据里学规则。前者『别人给孩子吃』，后者『教孩子自己找吃的』。"}]},{"type":"mistakes","items":["把三个词当同义词——它们是包含关系：AI ⊃ ML ⊃ DL。","以为『只要用了 AI 就是深度学习』——很多产品底层还是传统机器学习（决策树、统计方法）。","以为『深度学习之外的东西都不是 AI』——AI 的范围比 DL 大得多。","把『大语言模型』直接等同于『全面工智能』——LLM 只是 AI 世界一小棵树上结的果。","纠结『这到底算不算 AI』这种分类洁癖——关键是理解它在哪一层、解决什么问题，而不是给它贴哪个标签。"]},{"type":"deep","title":"深入一点：为什么近十年忽然『深度学习』最火","beginner":["不是说传统机器学习不好，而是深度学习在『大规模数据 + 强大 GPU』的条件下，能力曲线突然反超。","三点原因：①数据足够多，神经网络学得动；②GPU 让多层网络算得动（训练从几周缩到几小时）；③多层网络能自动学特征，不用人手工设计。","一句话：深度学习强的不是『智能』，是『在足够数据下自动找到规律的能力』。"],"advanced":["技术脉络：2006 年深度信念网络证明深层训练可行 → 2012 年 AlexNet 用 CNN 赢下 ImageNet，深度学习在视觉上引爆 → 2017 年 Transformer 论文出现，注意力机制取代循环结构，为语言大模型铺路 → 2022 年 ChatGPT 把『预测下一个词』放大到规模对话，大众才真正感知到。","一个判断技巧：当文章说『神经网络』『层数』『激活函数』『反向传播』时，多半在讲 DL；说『特征工程』『决策树』『SVM』时，多半是传统 ML。","从 DL 到 LLM 的桥梁就是『词元 + 注意力』：把语言切碎成 token，再用自注意力建模词与词的关系。这将在后文《Tokenization》《Attention》《Transformer》三课展开。"]},{"type":"exercise","prompt":"一位朋友说：『我帮公司做了个深度学习项目，所以我在做人工智能。』这句话的问题在哪？","opts":["完全正确，深度学习就是 AI 的全部","只对一部分：深度学习确实是 AI，但不能反过来说『AI = 深度学习』，AI 的范围大得多","完全错误，深度学习不算 AI","深度学习是机器学习之外的技术，和 AI 无关"],"a":1,"explain":"深度学习是 AI 的子集（AI ⊃ ML ⊃ DL），所以『做深度学习就是在做 AI』正确；但把它当成 AI 的全部就错了，因为 AI 还包括传统 ML、规则系统等许多内容。","jump":"sec5-step0","jumpLabel":"第 0 层 AI 这一段"},{"type":"check","title":"结课检测：三层包含关系你拉直了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"下面哪条包含关系是正确的？","opts":["AI ⊃ ML ⊃ DL","ML ⊃ AI ⊃ DL","DL ⊃ ML ⊃ AI","AI ⊃ DL ⊃ ML"],"a":0,"explain":"AI 是最外层目标，机器学习是其内一层主流手段，深度学习又是机器学习里最强的一个分支。","jump":"sec5-step0","jumpLabel":"三层关系这一段"},{"q":"『决策树 / SVM』这类经典算法，通常归属于哪一层？","opts":["深度学习 DL","传统机器学习 ML（但不一定是 DL）","纯规则 AI（非学习）","大语言模型 LLM"],"a":1,"explain":"决策树、SVM 属于机器学习，但它们不靠多层神经网络，所以不算深度学习，也称不上 DL。","jump":"sec5-step1","jumpLabel":"机器学习这一层"},{"q":"『多层神经网络 + 自动提取特征』，最准确对应的概念是？","opts":["传统规则 AI","深度学习 DL","数据库","网络通信"],"a":1,"explain":"利用多层神经网络、无需人工设计特征自动学习，正是深度学习区别于传统 ML 的核心。","jump":"sec5-step2","jumpLabel":"深度学习这一层"},{"q":"大语言模型（LLM）与深度学习的关系是？","opts":["它们是同一件事的两个名字","LLM 是深度学习在语言上结出的具体果实","LLM 与深度学习毫无关系","LLM 属于传统机器学习"],"a":1,"explain":"LLM 用深度学习的方法专门处理语言，以『预测下一个词』为目标训练出来，是 DL 在语言上的具体应用。","jump":"sec5-step3","jumpLabel":"LLM 这一层"}],"done":"现在 AI、ML、DL、LLM 四者的包含关系你彻底拉直了。可这些高大上的模型到底怎么『学』出来的？下一课我们就回答最根本的一问：训练（Training）和使用（Inference）到底有什么区别。","nextLesson":"pl-train-infer"},{"type":"connection","known":["AI 是包含 ML、DL 的最外层大概念（来自上一课《一张图看懂整个 AI 世界》的地图骨架）"],"learned":["AI ⊃ ML ⊃ DL ⊃ LLM 的清晰包含链","三者的定义、实现手段与典型代表","为什么深度学习在数据与算力充足时成为主力","LLM 是深度学习在语言上的果实"],"next":"下一步我们回答『学习』这件事本身：模型『训练』时和『使用』时，到底发生了什么、有什么本质区别。这是理解一切 AI 应用的前提。","links":[{"href":"#/lesson/l00-ai-world","text":"回看《一张图看懂整个 AI 世界》"},{"href":"#/lesson/l08-neural-network","text":"提前了解《神经网络》一课"}]}]},{"id":"pl-data","title":"数据、模型与参数：AI 学习的三件套","subtitle":"模型在拿什么学？答：数据是教材，模型是大脑结构，参数是大脑里无数个可调的小旋钮。这三者的关系，是理解一切 AI 的起点。","category":"c01-ai-world","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["data","model","parameter"],"prereqLessons":["pl-train-infer"],"nextLesson":"l05-gradient-descent","sections":[{"type":"opening","question":"总听人说『这个模型有 70B 参数』『训练数据有几十 TB』。参数、数据、模型——这三个词你天天见，但它们到底是什么、什么关系？为什么参数越多越厉害（但又更贵）？","guess":"有人以为『模型的全部本事都是数据里抄来的』，或者『参数越多就一定越好』。","next":"这一课我们从最底层的三件套讲起：数据（模型看什么）、模型（模型长什么样）、参数（模型的'旋钮'）。搞懂它们，你对『训练』『能力』『成本』的理解会瞬间落地。"},{"type":"why","before":"你想弄懂 AI 为什么能『学会』，于是去看资料，却总被『参数规模』『训练数据量』这些数字砸晕，不知道它们和『模型会不会用』有什么关系。","problem":"把数据、模型、参数三者混为一谈，就解释不了很多现象：为什么同样是鹦鹉学舌，有的模型聪明有的笨？为什么参数翻倍模型不一定翻倍聪明，但成本一定翻倍？为什么有时数据质量比数据量更重要？","need":"我们把三件套分清楚：数据是『给模型看的世界』，模型是『看世界的脑回路结构』，参数是『脑回路里无数个可微调的小值』。层层拆开，很多『为什么』都能对号入座。"},{"type":"oneline","text":"数据（Data）= 教材与习题；模型（Model）= 大脑的『结构设计』（有多少层、神经元怎么连）；参数（Parameter）= 大脑里数以亿计的『小旋钮』，训练就是把它们拧到最合适的位置。能力来自结构与数据，旋钮的数量决定模型的『规模』与成本。"},{"type":"intuition","blocks":[{"k":"用学生来想","t":"数据＝读过的书、做过的题（内容）；模型＝这位学生大脑的结构（聪明程度上限）；参数＝大脑里成千上万个可以不断微调的小连接。训练就是：用大量好书好题，把这几亿个小连接一点点调顺，让这个学生变强。"},{"k":"用收音机来想","t":"模型＝收音机的电路设计；数据＝收到的电台信号；参数＝面板上能拧的旋钮。一个收音机好不好，取决于电路设计（模型）+ 接收到的信号（数据）+ 旋钮拧得对不对（参数调得好不好）。"},{"k":"一句话记住","t":"结构（模型）定上限，数据定内容，参数定『具体怎么算』。参数越多，模型越『大』，理论上能学的东西越多，但训练成本与部署成本也越高。"}]},{"type":"how","intro":"把三件套分别拆开：它是什么、从哪来、为什么重要。","steps":[{"in":"① 数据 Data：模型的『世界』","process":"文本、图片、代码、语音等一切喂给模型的东西。训练数据的规模与质量，直接决定模型见没见过某类知识。数据要先清洗、去重、组织。","out":"『教材』：决定模型大概会什么、懂什么"},{"in":"② 模型 Model：大脑的『结构』","process":"神经网络『长什么样』——有多少层、每层多少神经元、神经元之间怎么连、用什么激活函数。这是架构设计，决定了模型理论上的能力上限。","out":"『脑回路设计』：决定上限与能学到的结构"},{"in":"③ 参数 Parameter：可调的『小旋钮』","process":"每条神经连接上的权重大小（几亿到几千亿个数字）。它们是训练真正在改的东西。参数量常被拿来衡量模型规模（如 7B、70B）。","out":"『旋钮集合』：决定『具体怎么算』与参数量级"},{"in":"三者如何协作","process":"训练时：把数据喂给具备结构的模型，反复调整参数，让输出尽量接近期望。三要素缺一不可：结构弱、数据差、或参数没调好，都会变成坏模型。","out":"一个『读过好书、结构良好、旋钮调准』的可用模型"}]},{"type":"realworld","items":[{"name":"参数规模 70B / 7B / 1.5B","note":"B 指 Billion（十亿），是模型参数量。大模型参数量常在几十亿到几千亿之间。参数量越大，模型『容量』越大，但训练与运行成本也越大。"},{"name":"为什么 GPT-4 系列这么强也这么贵","note":"越大参数 + 越多数据 = 能力更强，但训练要的算力和部署要的显存都剧增。能力与成本是一对不断权衡的对手。"},{"name":"『数据是新时代的石油』","note":"高质量、干净、多样的训练数据极关键。数据质量不足时，再大的模型也可能『吃垃圾吐垃圾』。这也是为什么很多公司拼命囤数据。"},{"name":"为什么中文模型注重中文语料","note":"模型的能力受训练数据影响很大。中文语料不足的模型，中文表现就差。这也是为什么国产大模型要专门堆中文高质量数据。"}]},{"type":"compare","pairs":[{"a":"数据 Data","b":"模型 Model","diff":"数据是『输入的世界/教材』，模型是『处理世界的结构』。同样的模型用不同数据学出不同特长；同样的数据放进不同结构，效果也不同。"},{"a":"模型 Model","b":"参数 Parameter","diff":"模型是结构设计（虚、相对固定），参数是结构里成千上万的具体数值（实、可训练调整）。可以把模型理解成『参数的容器与组织方式』。"},{"a":"参数量（规模）","b":"能力上限","diff":"参数量大能学更多，但不等于一定更聪明——还要数据够好、训练到位。规模是『容量』，能力是『用得好不好』。"},{"a":"数据质量","b":"数据量","diff":"质量差的数据量再大也可能有害；干净、多样、正确的高质量数据量，才真正提升模型水平。"}]},{"type":"mistakes","items":["以为『参数越多就一定越好』——参数量需要匹配数据量与算力，盲目堆参数不一定有效，反而成本爆炸。","以为『模型的知识是直接从数据抄来的』——模型学的是分布规律，不是存储原始数据（虽有少量记忆风险）。","以为『数据越多越好，质量无所谓』——脏数据、重复数据、错数据会教坏模型。","把『模型结构』和『参数值』混为一谈——结构造好后，真正的'学习'是调参数。","以为『只要模型大就什么都会』——数据覆盖不到的东西，模型就是不会，架构差异也有影响。"]},{"type":"deep","title":"深入一点：参数到底是个什么样的『数字』","beginner":["想象一张蜘蛛网，网上每条丝有一个数字表示‘这条丝重要/怎么影响下一个点’。","神经网络里，前一层每个神经元的输出，会乘以一个权重再传给下一层。这些权重就是参数。","模型‘学会’一件事，本质就是把这一大堆权重调到一个能很好完成任务的状态。"],"advanced":["一个参数通常指一个权重或偏置（bias）。训练即优化这些参数，使损失函数最小。","嵌入层、注意力矩阵、前馈网络的权重加起来构成参数量。LLM 的参数量主要集中在 Transformer 的注意力与前馈层。","‘参数高效微调’（如 LoRA）只训练一小部分新加的低秩参数来适配下游任务，从而大幅降低显存与成本——这就是为什么现在微调大模型很常见、成本可控。"]},{"type":"exercise","prompt":"两个模型参数量相同，但 A 用了更多更高质量的数学数据，B 用了大量杂乱重复的一般文本。哪个更可能在数学题上表现更好？","opts":["A，因为高质量、覆盖到数学的数据直接决定它懂多少数学","B，因为数据越多就一定越好","完全一样，因为参数量决定一切","无法判断，参数量完全无关"],"a":0,"explain":"模型的能力与训练数据的质量、覆盖度强相关。同样参数量下，喂了高质量数学数据、结构又合理的模型，在数学上通常更可靠。","jump":"sec5-step0","jumpLabel":"数据这一层"},{"type":"check","title":"结课检测：数据 / 模型 / 参数 你分得清吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"『模型的能力上限主要由结构决定』，这里的'结构'通常指什么？","opts":["训练数据的来源","神经网络有多少层、怎么连（模型架构）","电脑的内存大小","用户有没有会员"],"a":1,"explain":"结构即模型的架构设计（层数、连接方式等），决定了模型理论上能学到什么；数据决定内容，参数决定具体计算。","jump":"sec5-step1","jumpLabel":"模型结构这一层"},{"q":"训练时模型真正被反复修改的是什么？","opts":["训练数据本身","模型参数（权重/偏置）","显卡","网页样式"],"a":1,"explain":"训练就是用数据反复调整模型参数（权重），让输出接近期望；数据是输入，通常不因训练而改。","jump":"sec5-step2","jumpLabel":"参数这一层"},{"q":"『70B』指的是模型的什么？","opts":["训练数据条数","参数量（700 亿个参数）","网络延迟毫秒数","模型文件的行数"],"a":1,"explain":"B 代表 Billion（十亿），70B 即 700 亿个参数，是衡量模型规模（参数量）的常见指标。","jump":"sec5-step2","jumpLabel":"参数这一层"},{"q":"用三个词概括 AI 学习的『三件套』是？","opts":["CPU、内存、硬盘","数据、模型、参数","提问、回答、得分","字体、颜色、布局"],"a":1,"explain":"AI 学习的三件套是数据（教材）、模型（结构）、参数（旋钮），三者协作完成学习。","jump":"sec5-step3","jumpLabel":"三者协作这一层"}],"done":"三件套分清了：数据是教材、模型是结构、参数是旋钮。那训练到底怎样才能把这些旋钮越拧越准？下一课我们看训练的核心引擎——损失函数与梯度下降。","nextLesson":"l05-gradient-descent"},{"type":"connection","known":["模型是被训练出来的产物（上一课）"],"learned":["数据＝教材、模型＝结构、参数＝旋钮","参数量衡量模型规模，但不等于能力","数据质量与覆盖度直接影响模型水平","训练＝用数据反复调整参数"],"next":"旋钮往哪个方向拧、拧多少，靠什么判断？下一课《损失函数与梯度下降》：模型怎么知道自己错了，以及如何一步步『往下走』变聪明。","links":[{"href":"#/lesson/pl-train-infer","text":"复习《训练和使用模型》"},{"href":"#/lesson/l05-gradient-descent","text":"进入《损失函数与梯度下降》"}]}]},{"id":"pl-train-infer","title":"训练和使用模型有什么区别","subtitle":"模型的『上学阶段（训练）』和『上班阶段（使用/推理）』是完全不同的两回事。搞懂这个，你就不会再困惑『为什么 ChatGPT 每次回答还不一样』『为什么模型会一本正经胡说八道』。","category":"c01-ai-world","chapterTitle":"第一章 · 认识 AI","level":"base","estTime":"10-15 分钟","difficulty":1,"concepts":["ai-ml-dl","training","inference"],"prereqLessons":["l01-ai-vs-ml-dl"],"nextLesson":"pl-data","sections":[{"type":"opening","question":"你打开 ChatGPT 问了个问题，它几秒内就回了你。但你可能没想过：它『学会说话』的那个过程（训练）和你使用它的过程（推理），根本不在一个时间、也不在一个量级。它们到底有什么不同？","guess":"有人觉得模型训练和使用是一回事，区别只在于快慢。","next":"这一课我们讲清训练（Training）与推理（Inference/使用）的本质区别：一个是在海量数据上『慢慢写作业、改答案』，另一个是『拿到考卷直接作答』。这是理解成本、速度、以及为什么大模型很贵的钥匙。"},{"type":"why","before":"你想知道：为什么训练一个 GPT 要花几百万美元、几千张显卡好几个月，而用的时候点一下就出结果？为什么同样的模型，每次回答会不一样？","problem":"如果不区分训练与推理，你会把『模型的成本』『模型的能力上限』和『一次回答的成本』混为一谈。你会奇怪：既然训练这么贵，为什么我用起来这么快？也会疑惑：模型到底是『提前背好了答案』还是『现场算出来的』？","need":"把训练 vs 推理分开，你就知道：模型的能力是训练阶段敲定的（一次性的），而每一次回答是推理阶段现算的（每次都要烧电）。所有关于『贵不贵、快不快、准不准』的问题，都要先问一句：你指的是训练还是推理。"},{"type":"oneline","text":"训练（Training）＝模型在海量数据上『写作业、对答案、改参数』的一次性重活，几个月、贵、改的是模型的『记忆与能力』；推理（Inference / 使用）＝训练完的模型每来一个输入就『现场作答』，每次都要算一遍，快、便宜但也不是免费。"},{"type":"intuition","blocks":[{"k":"用学生来想","t":"训练＝学生寒窗苦读，读了大量课本和例题，把知识『内化』成自己的答题能力。这个过程长、累、费钱（教材、学费）。推理＝拿到考卷直接作答，靠之前内化的能力秒写答案。学生毕业后的『能力』是训练决定的，每次考试只是把能力'调出来'用。"},{"k":"用厨师来想","t":"训练＝大厨经过多年练习，练出一身手艺（参数）。推理＝客人点菜，大厨现场动手做一盘。手艺是多年前'训练'出来的，但每一道菜都是现场'推理'做的——所以每次都要时间，且水平取决于那身手艺。"},{"k":"一句话记住","t":"训练：改参数、时间长、一次性、贵；推理：用参数、时间短、每次都算、有成本。一切 LLM 的『贵』都主要来自训练，但每一次对话的『算力』来自推理。"}]},{"type":"how","intro":"把一次训练和一次推理分别拆开，对比每一步。","steps":[{"in":"训练前：准备『教材』（数据和算力）","process":"采集海量文本/图片/代码作为训练数据，准备好大量 GPU/TPU 算力集群。数据要清洗、去重、组织成训练样本。","out":"一批质量过关的训练数据 + 一台算力集群"},{"in":"训练中：模型『写作业-对答案-改参数』反复迭代","process":"把数据分批喂给模型做预测，计算预测和真实答案的差距（Loss），再用反向传播一层层微调参数。重复亿万次，直到误差低到可接受。","out":"参数被反复调整，模型逐渐学会了规律"},{"in":"训练完：得到一个『固定』的模型文件","process":"训练结束后的参数被冻结，变成一个可以被调用、分发、部署的模型文件（权重）。此时能力已定型。","out":"一份可部署的模型权重（几十到上千 GB）"},{"in":"推理中：来一个输入，模型现场算一次","process":"你把问题给模型，模型把它编码成数字，经过神经网络前向计算一遍，输出答案。每次回答都是完整算一次，不改动任何参数。","out":"得到一次『当下』的回答，参数保持不变"},{"in":"推理的成本与速度","process":"每次推理都要占用显卡做一次前向计算，所以有延迟和成本。这也是为什么在线大模型按『Token 用量』收费。","out":"按用量计费、有延迟、有成本"}]},{"type":"realworld","items":[{"name":"ChatGPT 的回答『每次不完全一样』","note":"推理阶段有随机性（采样时温度大于 0），同样的问题每次选词的随机分布不同，所以回答会有细微差异。这不是『模型在变』，而是推理时的随机采样。"},{"name":"『训练一次要花几百万美元』","note":"指的就是训练阶段：几千张高端 GPU 连跑数周，电费、机房、人力都计入。GPT-4 级别的训练成本以千万美元计。"},{"name":"『按 Token 计费』","note":"你为每次推理付费：模型每处理一个 token（约一个字/词的一部分）都要做一次计算，供应商按用量收费，覆盖推理的算力成本。"},{"name":"『微调（Fine-tuning）』","note":"在已有模型基础上做一次『小规模训练』：拿少量领域数据再微调参数，让模型更适合某一任务。它介于『纯训练』和『纯推理』之间，本质仍是一次训练。"},{"name":"模型会『一本正经胡说八道』","note":"推理时模型只是在『预测下一串合理的词』，它并不理解对错，也不自知。能力在训练中定型，但每次回答都是预测，可能自信地编造。这就是幻觉（Hallucination）。"}]},{"type":"compare","pairs":[{"a":"训练 Training","b":"推理 Inference","diff":"训练改参数、时间长、一次性、成本高；推理用参数、时间短、每次都算、按量计费。"},{"a":"模型能力","b":"一次回答质量","diff":"能力上限在训练时定型；但单次回答可能受采样随机性影响，同一能力下每次具体答案可不同。"},{"a":"训练算力","b":"推理算力","diff":"训练需要大规模并行、一次跑很久；推理每次只需一次前向计算，量小但调用次数巨大。"},{"a":"预训练","b":"微调 Fine-tuning","diff":"预训练是在海量通用数据上从零或从基础训练；微调是在预训练权重上用少量领域数据再小规模训练，快速适配某一任务。"}]},{"type":"mistakes","items":["以为『每回答一次，模型就变聪明一点』——不，训练阶段才改参数，推理回答是只读调用。","以为『训练的成本 = 我用它的成本』——错，训练是一次性的昂贵投入，推理按量计费。","以为『模型每次回答不同＝模型在更新』——多数差异来自推理时的随机采样，不是参数在变。","以为『微调 = 推理』——微调本质是小规模训练（改参数），只是数据量小、时间短。","以为『模型能力不足时，靠多问几次就能提升』——能力在训练定型，用量不能改变能力上限，只能换策略或换模型。"]},{"type":"deep","title":"深入一点：参数、权重与『训练到底在改什么』","beginner":["一个神经网络由大量『神经连接』组成，每条连接有一个数字叫权重（参数）。模型的『知识』就存在这些数字的分布里。","训练就是反复调整这几亿甚至上千亿个数字，让它们最终能很好地完成预测任务。","'预训练'让模型具备通用语言能力；'微调'在此基础上小幅调整让它更听话或更专业。"],"advanced":["训练就是最优化：目标函数（Loss）对每个参数求梯度，用梯度下降更新，让 Loss 越来越小。这个『更新参数』的循环在训练阶段发生，推理阶段参数冻结不动。","推理只有『前向传播』：输入 → 逐层计算 → 输出，不更新任何参数。这也是为什么推理远快于训练——少了反向传播这一步。","工程视角：训练需要反向传播、梯度累积、学习率调度、数千张卡并行；推理需要 KV 缓存、量化、批处理、KV-cache 复用来降低延迟与成本。同一模型，训练与部署是两套完全不同的工程问题。"]},{"type":"exercise","prompt":"有人问你：『为什么我让同一个 AI 写一篇关于猫的文章，两次得到的开头不一样？』最合理的解释是？","opts":["模型在这期间偷偷重新训练了","推理阶段有随机采样，同样的输入可能得到不同的输出","因为我没联网","因为模型是我提问时才被造出来的"],"a":1,"explain":"训练阶段已定型，参数不变；两次回答的差异来自推理采样时的随机性（温度/采样），属于正常现象。","jump":"sec5-step3","jumpLabel":"推理中：来一个输入现场算一次"},{"type":"check","title":"结课检测：训练 vs 推理你分得清吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"训练阶段，模型在做什么？","opts":["逐层前向计算并给出答案（不改参数）","反复预测-对答案-调整参数，直到误差降低","什么都不做，只是被部署","只在用户提问时才运行"],"a":1,"explain":"训练的核心循环是『预测 → 算 Loss → 反向传播更新参数』，一直重复到误差可接受。推理阶段才不再改参数。","jump":"sec5-step1","jumpLabel":"训练中这一层"},{"q":"『按 Token 用量收费』，付的是哪个阶段的成本？","opts":["训练成本","每次使用的推理成本","买电脑的钱","数据采集成本"],"a":1,"explain":"线上大模型按你每次提问消耗的 token 计费，覆盖的是推理阶段每次前向计算的算力成本，不是一次性训练费。","jump":"sec5-step4","jumpLabel":"推理的成本与速度"},{"q":"微调（Fine-tuning）本质上更接近哪件事？","opts":["纯推理","一次小规模的训练","只是改提示词","重新从零预训练"],"a":1,"explain":"微调是在预训练权重上用少量数据再调整参数（反向传播），本质是一次数额小、数据少的训练。","jump":"sec6","jumpLabel":"微调这个现实案例"},{"q":"模型的『能力上限』主要由什么决定？","opts":["每次提问时的随机采样","训练阶段（数据、架构、规模）","用户的打字速度","网络的带宽"],"a":1,"explain":"能力在训练阶段定型；推理只是把已定型的参数拿出来做预测，不能提升能力上限。","jump":"sec5-step2","jumpLabel":"训练完这一层"}],"done":"现在你分清了『学（训练）』和『用（推理）』。可模型到底在拿什么『学』、在『学』什么？下一课我们把 AI 的三大原料——数据、模型、参数——逐个说透。","nextLesson":"pl-data"},{"type":"connection","known":["AI ⊃ ML ⊃ DL 的包含链（上一课）","模型是被训练出来的产物"],"learned":["训练 vs 推理的本质区别（改参数 vs 用参数）","训练一次性昂贵、推理按量计费","为什么同一模型每次回答可能不同（采样随机性）","微调 = 小规模训练；幻觉来自推理时预测而非自知"],"next":"训练的『原料』是什么？下一课《数据、模型与参数》告诉你 AI 学习的三要素，以及为什么『数据』往往比模型大小更关键。","links":[{"href":"#/lesson/l00-ai-world","text":"复习 AI 世界总图"},{"href":"#/lesson/l05-gradient-descent","text":"预看《损失函数与梯度下降》"}]}]}],"c03-ml":[{"id":"l05-gradient-descent","title":"损失函数与梯度下降：模型怎么自己变聪明","subtitle":"训练的核心不是『照抄答案』，而是给错误『打分』，然后沿着『下山最快』的方向一步步调整参数。看懂这一步，你就真懂了 AI 的『学习』。","category":"c03-ml","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["loss","gradient","gradient-descent"],"prereqLessons":["pl-data"],"nextLesson":"l08-neural-network","sections":[{"type":"opening","question":"上一课我们说训练就是『反复调整参数』。可模型该往哪个方向调、调多少？它怎么知道自己『猜错了』？这里有一个非常优雅的核心机制——损失函数 + 梯度下降。","guess":"有人以为训练就是不断『枚举试错』，或模型直接记住正确答案。","next":"这一课我们讲训练最核心的两个概念：损失函数（给错误打分）和梯度下降（沿下山最快的路调整参数）。这是所有深度学习『自带学习』的根本。"},{"type":"why","before":"你想真正理解 AI 怎么『学会』的（而不是只会背结论），于是查『训练』『反向传播』，却看到一堆数学公式，被梯度、导数吓退。","problem":"不理解损失与梯度下降，你就只能把训练当『黑盒』——不知道模型为什么学会、为什么有时候学不会、为什么训练会发散或过拟合。后续看一切『调参』话题都会费劲。","need":"我们把核心讲得足够直观：损失＝错得有多离谱的比分；梯度＝每个旋钮往哪个方向拧能让误差下降最快。有了这两把钥匙，训练不再是黑盒。"},{"type":"oneline","text":"损失函数（Loss）= 给模型当前『错得多离谱』打的一个分数，越小越好；梯度下降（Gradient Descent）= 算出每个参数要让误差下降，应该往哪个方向拧、拧多少，然后沿『下山最快』的方向反复更新，直到误差降不下去。"},{"type":"intuition","blocks":[{"k":"用下山来想","t":"想象你被蒙着眼站在一座山上，目标是最低点（误差最小）。你每走一步就摸摸脚下的坡度（梯度：哪里更陡地往下）。你就朝最陡的下坡方向迈一小步，反复走，就一步步接近山谷最低点。这就是梯度下降。"},{"k":"用射箭来想","t":"损失函数＝你射偏的距离（离靶心多远）。梯度＝『往东偏了，该往西调一点』的修正提示。每一轮你根据偏差方向和大小校正弓，越射越准。"},{"k":"一句话记住","t":"损失＝错得有多远；梯度＝该往哪调、调多少。训练＝沿着『误差下降最快』的方向一次次微调参数，走出一座‘误差之山’。"}]},{"type":"how","intro":"把一次训练迭代（一步学习）拆成四步。","steps":[{"in":"① 前向预测：模型猜一次","process":"喂一批数据，模型按当前参数算出一批预测结果（如：这张图是猫的概率、下一个词是哪个）。","out":"得到模型的『猜测』输出"},{"in":"② 计算损失：给错误打分","process":"拿猜测和真实答案对比，用一个损失函数算出数值：差得多分数高，差得少分数低。这就是 Loss。","out":"一个代表错得多离谱的数值（Loss）"},{"in":"③ 反向计算梯度：找下降方向","process":"用微分/反向传播算出：每个参数向哪个方向微调会让 Loss 变小、大概变小多少。这就是梯度（下山方向）。","out":"每个参数对应的『修正方向 + 幅度』"},{"in":"④ 更新参数：沿梯度走一小步","process":"按学习率（步长）把每个参数往梯度方向调一点。重复 ①②③④ 成千上万次，Loss 逐渐下降。","out":"一轮一轮的微调后，误差越来越小，模型变聪明"}]},{"type":"realworld","items":[{"name":"学习率（Learning Rate）","note":"决定每步走多大。太大容易在山谷两边来回震荡甚至发散；太小走到山谷要很久。调学习率是训练头号工程问题。"},{"name":"为什么训练会『过拟合』","note":"下山下过头，模型把训练数据的噪声也背下来，对没见过的数据反而变差。这需要正则、早停、更多数据来约束。"},{"name":"批量大小（Batch）","note":"一次用多少样本算梯度。太小震荡大、太大太慢。是训练的重要超参数。"},{"name":"为什么有的模型『训练发散』（Loss 变 NaN）","note":"梯度爆炸或学习率过大，参数一步跳得太远，误差爆炸。工程上要加梯度裁剪、合理初始化。"}]},{"type":"compare","pairs":[{"a":"损失函数 Loss","b":"梯度 Gradient","diff":"Loss 是『错得多远』的分数（一个数）；梯度是『该往哪调、调多少』的方向信息。先有 Loss，才有 Gradient。"},{"a":"梯度下降","b":"随机梯度下降 SGD","diff":"梯度下降每步用全部数据算梯度（准但慢）；SGD 每次只用一小批数据算梯度（快但有噪声，实践中更常用）。"},{"a":"学习率大","b":"学习率小","diff":"大步长收敛快但易震荡/发散；小步长稳但慢。要平衡。"},{"a":"训练 Loss","b":"验证 Loss","diff":"训练 Loss 是模型背题目的程度；验证 Loss 是它在没见过的题上的表现。后者才是真正关心的泛化能力。"}]},{"type":"mistakes","items":["以为训练是『背答案』——不，是学规律后用梯度一点点靠近最优参数。","以为『Loss 越低越好到越低就越强』——训练 Loss 降得太低常意味着过拟合，真正看验证 Loss。","以为梯度下降只有一条最优路径——它是启发式最优化，可能卡在局部极小值，且对超参数敏感。","把『梯度』和『参数值』混为一谈——梯度是方向信息，参数才是被更新的值。","以为学习率越大越快——过大会发散，这不是勇气，是翻车。"]},{"type":"deep","title":"深入一点：数学直觉（给愿意往下钻的你）","beginner":["梯度就是『误差对每个参数的偏导数』：把参数稍微动一点点，看 Loss 变多少。","梯度方向是 Loss 上升最快的方向，所以沿它的反方向走，就是下降最快的方向。","更新公式一眼看懂：新参数 = 旧参数 − 学习率 × 梯度。"],"advanced":["优化目标是最小化 L(θ)。更新：θ ← θ − η∇L(θ)。η 是学习率，∇L 是梯度。","深度学习用的多是 Adam 等自适应优化器：为每个参数自动调整学习率，能加速收敛、更稳。","对 LLM，预训练用海量数据做较长时间的大规模梯度下降；微调用小数据小学习率。现代还加入 LoRA 等参数高效方式只更新低秩子空间。","需要警惕的工程陷阱：梯度爆炸/消失（影响深层网络）、学习率 warmup、loss 尺度不一等。"]},{"type":"exercise","prompt":"训练中你看到 Loss 一会儿 4.8、一会儿 4.2、一会儿又 5.1，总体没怎么降。最可能是哪类问题？","opts":["模型已经过拟合了","学习率过大或数据太吵，导致震荡、收敛困难","数据量太多","显卡坏了"],"a":1,"explain":"Loss 来回震荡不下滑，常是学习率过大、批量太小导致的噪声，或需要调整超参数让训练稳定下来。","jump":"sec5-step3","jumpLabel":"更新参数这一步"},{"type":"check","title":"结课检测：损失与梯度下降你懂了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"损失函数（Loss）的作用是？","opts":["给模型的错误打一个分，越小越好","让显卡更热","控制网页颜色","增加参数量"],"a":0,"explain":"Loss 衡量模型预测与真实答案的差距，是训练的‘成绩单’，目标是把它降到尽可能低。","jump":"sec5-step1","jumpLabel":"计算损失这一步"},{"q":"梯度（Gradient）告诉模型什么？","opts":["正确答案本身","每个参数该往哪个方向调能让误差下降","模型的名字","数据的来源"],"a":1,"explain":"梯度是误差对参数的偏导方向信息，模型沿其反方向（下降最快）调整参数。","jump":"sec5-step2","jumpLabel":"反向计算梯度这一步"},{"q":"下面的参数更新思路，哪项正确？","opts":["新参数 = 旧参数 + 学习率 × 梯度（反了）","新参数 = 旧参数 − 学习率 × 梯度","新参数和旧参数无关","只在推理时改参数"],"a":1,"explain":"沿梯度反方向（下降方向）走，所以是减去学习率乘梯度。训练改参数、推理只读。","jump":"sec5-step3","jumpLabel":"更新参数这一步"},{"q":"学习率设得过大，最常见的后果是？","opts":["训练更快且更好","参数一步跳太远，Loss 震荡甚至发散","模型变成大模型","不需要数据了"],"a":1,"explain":"步长过大容易在最优附近来回跳过，甚至梯度爆炸导致 Loss 发散。","jump":"sec6","jumpLabel":"学习率这个现实话题"}],"done":"你知道了训练是怎么『一步步下山』的：给错误打分，沿梯度往误差下降的方向拧参数。下一课我们把镜头拉回模型本身——神经网络到底长什么样、神经元是怎么组成可学习网络的。","nextLesson":"l08-neural-network"},{"type":"connection","known":["数据、模型、参数三件套（上一课）","训练＝反复调整参数"],"learned":["损失函数＝给错误打分，目标是降低","梯度＝哪个方向能最快降低误差","梯度下降＝沿下山最快方向反复微调参数","学习率、过拟合、训练/验证 Loss 这些关键概念"],"next":"梯度下降要在『模型』上发挥作用，可这个模型到底长什么样？下一课《神经网络》：神经元、层、激活函数，理解模型的躯体。","links":[{"href":"#/lesson/pl-data","text":"复习《数据、模型与参数》"},{"href":"#/lesson/l08-neural-network","text":"进入《神经网络》"}]}]}],"c04-dl":[{"id":"l08-neural-network","title":"神经网络：神经元如何组成可学习的网络","subtitle":"深度学习的大脑＝一层层神经元。看懂『神经元怎么算、层怎么堆、信息怎么流动』，你就拥有了理解几乎所有现代模型的基础底盘。","category":"c04-dl","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["neural-network","neuron","layer","activation"],"prereqLessons":["l05-gradient-descent"],"nextLesson":"l09-backprop","sections":[{"type":"opening","question":"『神经网络』你听了无数遍，可它到底长什么样？是不是真和大脑一样？为什么『一堆神经元连起来』就能写诗、识图、跟你聊天？","guess":"有人以为神经网络真的模仿大脑生物结构，或以为它是魔法般‘突然会了’。","next":"这一课我们拆开神经网络的正脸：一个神经元在算什么、一层层怎么叠加、信息怎么从输入流到输出。你会惊讶它其实是由‘乘加 + 激活’这种超级简单的运算堆出来的。"},{"type":"why","before":"你想真正理解深度学习，而不是只会说‘神经网络很厉害’。可一打开网上资料就全是神经元、权重、激活函数、层，不知道它们是怎么组成一个能干活的整体。","problem":"不搞懂神经网络的基本结构，后续看 Attention、Transformer 时会完全跟不上——因为那些都是在这个底盘上加的新花样。","need":"我们先用最直观的方式把神经网络‘长什么样’讲清楚：神经元怎么算、为什么需要非线性（激活）、层越多能学到越抽象的东西。地基打牢，后面全是加分项。"},{"type":"oneline","text":"神经网络＝把大量『简单神经元』分层堆叠：每个神经元把上一层传来的数字加权求和，再过一道非线性激活函数输出；一层接一层，把原始输入逐渐加工成可用的结果。学习就是在训练中不断调这些权重（配合上一课的梯度下降）。"},{"type":"intuition","blocks":[{"k":"用力工流水线来想","t":"神经网络像一条多工序的工厂流水线：原料（像素/文字）进第一道工序，每道工序负责提取一个层面的特征，成品在最后一道工序出来。层数越多，能提取的特征越高维越抽象——从‘一小片边’到‘一只眼睛’到‘一张脸’。"},{"k":"用算盘/计算器来想","t":"每个神经元本质就是一个‘小计算器’：把几个输入各自乘一个权重再加起来，然后决定要不要‘被激活’。网络就是成千上万个小计算器排队协作。"},{"k":"一句话记住","t":"神经元＝乘加 + 激活；层＝一批神经元；深度＝有多少层。层数越多，学到的东西越抽象；而训练负责把这些‘乘加里的权重’调好。"}]},{"type":"how","intro":"从单个神经元讲到整张网络，四步走。","steps":[{"in":"① 单个神经元：一次性小计算","process":"一个神经元接收上一层传来的多个数字，每个数字乘一个权重，求和，再加一个偏置，得到一个‘原始得分’。","out":"一个加权求和后的数字（还没加工完）"},{"in":"② 激活函数：引入非线性","process":"把原始得分过一道激活函数（如 ReLU：负数归零、正数保留）。没有这步，再多层也等价于一层，学不了复杂东西。非线性是关键。","out":"一个‘激活后’的输出值，传给下一层"},{"in":"③ 分层堆叠：从底层特征到高层语义","process":"把很多神经元放一层，再叠很多层。第一层学边缘/局部，中间层学部件/模式，高层学整体语义（对着图那就是‘脸’‘猫’）。","out":"一个能逐层提取特征、层层抽象的网络"},{"in":"④ 输出层 → 预测","process":"最后一层把中间表示转换成最终答案：分类（各类概率）、回归（一个数）、或语言模型的‘下一个词的概率分布’。","out":"可解释成‘预测/概率’的输出"}]},{"type":"realworld","items":[{"name":"全连接层（MLP）","note":"每一层的每个神经元都和上一层所有神经元相连，是最基础的结构。Transformer 里的前馈网络就是一种 MLP。"},{"name":"CNN（卷积网络）","note":"用小的卷积核在图像上滑动提取局部特征，擅长图像。AlexNet 靠它在 2012 年引爆深度学习。"},{"name":"RNN / LSTM（循环网络）","note":"为序列而生，靠循环传递上个时间步的状态。后来在处理长文本上被 Transformer 取代。"},{"name":"Transformer","note":"不用循环，全靠注意力机制并行处理序列，是现在所有大语言模型的地基。后面专门一课讲。"}]},{"type":"compare","pairs":[{"a":"浅层网络","b":"深层网络","diff":"浅层只能学到简单特征与关系；深层能逐步抽象，能力更强，但更难训练、更容易梯度消失，需要残差连接等设计。"},{"a":"线性（无激活）","b":"非线性（有激活）","diff":"没有非线性，再多层叠加仍是线性变换，学不了复杂函数。激活函数带来非线性表达能力。"},{"a":"卷积 CNN","b":"全连接 FC","diff":"CNN 用局部连接+卷积核，参数少、适合图像；FC 全连接，参数多，通用。"},{"a":"RNN","b":"Transformer","diff":"RNN 串行逐步处理，难并行、长距离记忆弱；Transformer 一次看全部、可并行、长距离强，是现代主流。"}]},{"type":"mistakes","items":["以为神经网络真和大脑生物神经元一样——它只是受启发，用的是数学上的‘人工神经元’，比大脑简单得多。","以为层越多一定越好——过深反而不易训练、易过拟合，需要配套技巧（归一化、残差、正则）。","以为激活函数可有可无——少了非线性，层数再多也等价于一层线性，模型能力骤降。","把神经网络的‘参数’和‘权重’搞混——权重就是参数的一种，它们才是训练要调的。","以为网络是‘背下所有答案’——它学的是从输入映射到输出的规律（通过调权重）。"]},{"type":"deep","title":"深入一点：深度为什么有用、又为什么难训练","beginner":["深度带来‘分层表示’：浅层学局部细节，深层学整体概念。这种层级抽象是深度网络能力强的关键。","但也带来训练难点：层太深，梯度在回传时容易‘消失’（乘很多小值趋近 0），最底层学不到东西。","于是有了残差连接（把上一层的值直接跳到后面）等设计来缓解。"],"advanced":["神经网络的万能近似：只要神经元够多、激活非线性，理论上能逼近任意连续函数。","深度网络优于浅层网络在于‘表示效率’：同样的表达能力，深层所需参数往往更少、泛化更好。","现代大模型（Transformer）本质也是神经网络：多头注意力 + 前馈层，只是给它堆了海量参数与数据。","反向传播（下一课）就是在这样的网络上高效算出每一个权重的梯度，让梯度下降在大规模场景下可行。"]},{"type":"exercise","prompt":"一个由多层线性变换（无激活函数）堆叠成的‘网络’，实际效果等价于？","opts":["一个强大的深层网络","一个单层线性模型（因为没有非线性，层数等于白叠）","一定会比深层网络强","无法训练"],"a":1,"explain":"没有非线性激活，多层线性变换可以合并成一个线性变换，等于只有一个线性层，能力有限。非线性是关键。","jump":"sec5-step1","jumpLabel":"激活函数这一步"},{"type":"check","title":"结课检测：神经网络的地基你打牢了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"单个神经元最基本的运算组合是？","opts":["加权求和 + 激活函数","排序 + 去重","加密 + 解密","复制 + 粘贴"],"a":0,"explain":"神经元把输入加权求和得到原始得分，再经激活函数引入非线性。这是最基本的组成单位。","jump":"sec5-step0","jumpLabel":"单个神经元这一步"},{"q":"为什么神经网络需要非线性的激活函数？","opts":["为了更美观","没有非线性，多层也等价于一层线性变换，学不了复杂规律","为了增加参数数量","因为 CPU 喜欢"],"a":1,"explain":"非线性让网络能逼近复杂函数；没有它，多层网络被压缩成一层，表达能力大跌。","jump":"sec5-step1","jumpLabel":"激活函数这一步"},{"q":"『深度网络善于提取越来越抽象的特征』，这个抽象层次受益于？","opts":["只有一层","层层堆叠、逐层抽象","加越多噪声越好","不训练"],"a":1,"explain":"多层结构让浅层学细节、深层学整体语义，形成层级抽象，是深度的价值。","jump":"sec5-step2","jumpLabel":"分层堆叠这一步"},{"q":"神经网络训练时要调的主要是？","opts":["每层的神经元数量结构","连接上的权重（参数）","用户的界面","网络的波长"],"a":1,"explain":"结构（层数、神经元数）通常在训练前定好；训练反复调整的是连接权重这些参数（配合梯度下降）。","jump":"sec6","jumpLabel":"全连接层这个话题"}],"done":"你认识了神经网络的躯体：神经元加权求和 + 激活，分层堆叠提取特征。那训练时，误差到底是怎么‘传回去’改每一层权重的？下一课《反向传播》揭晓。","nextLesson":"l09-backprop"},{"type":"connection","known":["梯度下降＝沿误差下降方向调整参数（上一课）"],"learned":["神经元＝加权求和 + 激活函数","层、深度、非线性为什么关键","CNN / RNN / Transformer 各自擅长的场景","网络通过对大量权重调参来学习"],"next":"误差要传回每一层去改权重的那个高效方法，就是下一课的核心。准备好了吗？《反向传播：误差如何传回去改参数》。","links":[{"href":"#/lesson/l05-gradient-descent","text":"复习《损失函数与梯度下降》"},{"href":"#/lesson/l09-backprop","text":"进入《反向传播》"}]}]},{"id":"l09-backprop","title":"反向传播：误差如何传回去改参数","subtitle":"深度网络有几亿参数，梯度下降却要算出每一个该往哪调。反向传播就是那个能在一次计算里，高效把所有梯度算出来的巧妙方法。","category":"c04-dl","chapterTitle":"第二章 · 数据与学习","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["backpropagation","gradient","chain-rule"],"prereqLessons":["l08-neural-network","l05-gradient-descent"],"nextLesson":"l11-tokenization","sections":[{"type":"opening","question":"一个 70B 参数的大模型，训练时要为每个参数算出‘该往哪调、调多少’。如果一个个算，几辈子都算不完。可训练只花几个星期就完成了——靠的是反向传播这个精巧机制。它是怎么做到的？","guess":"有人以为训练是‘挨个试’每个参数，或以为靠的是超级电脑大力出奇迹。","next":"这一课讲反向传播：误差如何从输出端‘倒着传回去’，用一条链式法则，一次性算出所有参数该调整的方向与幅度。看懂它，训练不再神秘。"},{"type":"why","before":"你接受了‘训练要调几亿个参数’这个设定，但马上困惑：神经网络的每层都互相影响，怎么知道到底是哪一层、哪个权重该为错误负责？","problem":"如果不理解反向传播，你会觉得大规模训练是魔法；也无法理解为什么深度学习速度这么快、为什么需要特殊硬件（GPU）、为什么梯度会‘消失’。","need":"反向传播把‘如何高效地给每个参数下发修正指令’这件事讲透了：从输出端倒推，每层把自己应负的责任传给上一层。这是理解训练提速、梯度消失、以及对 Transformer 训练的一切认知的钥匙。"},{"type":"oneline","text":"反向传播 = 先从输出端算出‘错得有多远’，再沿着计算的反方向，用链式法则把这份‘责任’逐层传回每一层的每个权重，一次算出所有梯度，让梯度下降可以批量更新整个网络。"},{"type":"intuition","blocks":[{"k":"用传话游戏来想","t":"信息正向往前传（输入→输出），误差反向往回传（输出→输入）。就像把你每一句话造成的最终偏差，逆着报给每一位讲话的人，告诉他该改多少。"},{"k":"用差评溯源来想","t":"一道菜难吃（大 Loss），要找到是哪个厨师、哪道工序的问题。你从成品倒着往回查：出锅太咸可能是调味这步，而调味又是前面采购/配比叠加的结果。反向传播就是这样从输出端把责任一路分派回每一层。"},{"k":"一句话记住","t":"正向传信息，反向传误差。反向传播用链式法则在一次回传里同时算出上亿个梯度，让深度学习训练成为可能。"}]},{"type":"how","intro":"把反向传播拆成一次‘四步回传’。","steps":[{"in":"① 正向算出误差","process":"网络前向算一遍，得到输出，与真实答案比较，得到 Loss（上一课已讲）。","out":"一个总误差数值"},{"in":"② 从最后一层往回，算‘谁的责任’","process":"从输出层开始，问：每个神经元的输出变化一点，Loss 变化多少？这就是梯度。","out":"最外层每个参数的梯度"},{"in":"③ 用链式法则逐层回传","process":"靠链式法则，把上一层的梯度乘上本层的局部导数，就得到更前一层的梯度。一路从输出传到输入，每一层都拿到自己的‘修正指令’。","out":"每一层每个权重都得到一个梯度"},{"in":"④ 汇总更新，再来一轮","process":"把所有层的梯度汇总，沿梯度反方向更新全部参数（梯度下降）。然后对下一批数据再来一轮。","out":"一次更新完成，误差整体下降一点"}]},{"type":"realworld","items":[{"name":"为什么需要 GPU","note":"反向传播涉及大量矩阵乘法和链式求导，GPU 能上千核并行，把训练从‘不可行’变成‘几周完成’。这是深度学习兴起的关键硬件。"},{"name":"梯度消失 / 梯度爆炸","note":"层太深时，梯度一层层相乘可能越来越小（消失）或爆炸。反向传播因此难以训练极深网络，催生了残差连接、归一化等设计。"},{"name":"自动微分框架（PyTorch / TensorFlow）","note":"你把网络搭好、写个 Loss，框架会自动帮你做反向传播求梯度。平时训练根本不手写链式法则。"},{"name":"大模型训练同理","note":"Transformer、GPT 的训练底层仍然是反向传播 + 梯度下降，规模放大而已。理解它，你就懂整个深度学习训练的统一范式。"}]},{"type":"compare","pairs":[{"a":"前向传播","b":"反向传播","diff":"前向：输入 → 输出，用于给出预测；反向：输出误差 → 层层回传梯度，用于更新参数。推理只用前向，训练两者都用。"},{"a":"数值求导（逐个试）","b":"反向传播（链式一次算完）","diff":"数值求导每个参数试一下、极慢；反向传播靠链式法则一次回传算完全部梯度，快几个量级。"},{"a":"局部梯度","b":"全局梯度","diff":"局部是单步的输出对输入的变化率；全局经链式法则把路径上所有局部梯度连起来，才得到最终要用的梯度。"},{"a":"训练 Loss","b":"测试表现","diff":"反向传播降的是训练 Loss；真正目标是让验证/测试也变好（泛化），二者并不总一致。"}]},{"type":"mistakes","items":["以为反向传播是一种‘独立的训练算法’——它只是高效算梯度的办法，配合梯度下降做更新。","以为反向传播会‘改变数据’——它改的是参数，数据只是被读取。","以为每次更新‘重算一遍整个网络’——它就是一次前向加一次反向后向，是训练一轮的标准动作。","把链式法则当作负担——它恰恰是把‘上亿次求导’压缩成一次回传的功臣。","以为推理阶段也在反向传播——推理只做前向，反向传播只在训练阶段发生。"]},{"type":"deep","title":"深入一点：链式法则为什么能一次算完所有梯度","beginner":["想象很多齿轮咬合在一起，转动第一个会带动一系列变化。链式法则就是：要知道第一个变化对最后结果影响多大，把每一段齿轮的传动比连乘起来。","反向传播正因为是‘倒着’算，每一层的中间结果能复用给前一层，所以只回传一次就拿到所有梯度。","这就是为什么训练深度网络是可行的：代价只是一次前向 + 一次反向后向的两次‘完整扫过’。"],"advanced":["数学上：∂L/∂θ 通过链式法则逐层展开，如 ∂L/∂W² = ∂L/∂ŷ · ∂ŷ/∂h² · ∂h²/∂W²，其中 ∂L/∂h 从上一层传下来被复用。","反向传播的本质是‘反向模式的自动微分’，与机器学习框架的自动微分是同一套东西。","内存成本：正向要保存每层的中间激活供反向使用，所以训练显存常是推理的好几倍——这也是为什么训练和部署对显存要求差别巨大。","工程技巧：混合精度、梯度累加、梯度裁剪、残差与归一化，都是为了在反向传播时保持数值稳定、让梯度健康流动。"]},{"type":"exercise","prompt":"为什么说反向传播能在‘一次回传’里算出所有参数的梯度，而不是一个个试？","opts":["因为它用了链式法则，把中间结果逐层复用给前一层","因为它只更新一个参数","因为它不计算梯度，靠猜","因为反向传播其实是推理阶段做的事"],"a":0,"explain":"反向传播从输出端倒推，每一层的中间结果可被前一层复用，所以沿链式法则一次回传就获得全部梯度。","jump":"sec5-step2","jumpLabel":"链式法则逐层回传这一步"},{"type":"check","title":"结课检测：反向传播你弄懂了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"反向传播是在哪个阶段发生的？","opts":["只有在推理时","只在训练阶段，用来算梯度","随时都在发生","只在上线后"],"a":1,"explain":"反向传播只在训练时用（算梯度供梯度下降），推理阶段只做前向传播。","jump":"sec5-step0","jumpLabel":"正向算误差这一步"},{"q":"反向传播高效的关键在于？","opts":["暴力逐个试参数","链式法则把中间结果复用、一次回传算全部梯度","不计算梯度","只算一个神经元"],"a":1,"explain":"链式法则＋逐层复用让一次反向回传就能得到所有参数的梯度，从而高效。","jump":"sec5-step2","jumpLabel":"链式法则逐层回传这一步"},{"q":"『梯度消失』问题主要出现在？","opts":["只有一层的网络","层太深、梯度逐层相乘越来越小","训练数据太少","没有激活函数"],"a":1,"explain":"层数过多时梯度经链式反向往回传越乘越小，导致深层最底层几乎学不到东西——这就是梯度消失。","jump":"sec6","jumpLabel":"梯度消失这个现实话题"},{"q":"训练时为什么显存占用往往远高于推理？","opts":["因为屏幕更亮","正向要保存各层中间激活供反向使用","因为数据更大","因为反向传播用不了串行"],"a":1,"explain":"反向传播需要正向阶段的中间激活，这些要存起来，所以训练显存需求远高于只做前向的推理。","jump":"sec7","jumpLabel":"内存成本这一段"}],"done":"你知道了误差是怎么‘倒着传回去’高效改每一层参数的。至此我们讲完了模型的学习机制。下一大步：这些原理在语言模型上怎么落地？先从最底层的『切词』开始——Tokenization。","nextLesson":"l11-tokenization"},{"type":"connection","known":["神经网络的结构（一层层神经元）","梯度下降＝沿误差下降方向调参数"],"learned":["反向传播＝误差从输出端倒着传回每一层","链式法则让一次回传算完所有梯度","为什么大规模训练可行、为什么需要 GPU","梯度消失/爆炸、训练显存为何更大"],"next":"模型的‘通用学习引擎’讲完了。现在进入语言的世界：文字是怎么被喂进模型、变成数字的？下一课《Tokenization》。","links":[{"href":"#/lesson/l08-neural-network","text":"复习《神经网络》"},{"href":"#/lesson/l11-tokenization","text":"进入《Tokenization》"}]}]}],"c11-ai-coding":[{"id":"l18-vibe-coding","title":"Vibe Coding 入门：用 AI 直接做出产品","subtitle":"十八节课的终点，也是‘你真的能做出东西’的起点。Vibe Coding 就是：把 AI 当结对程序员，用‘先跑起来、边做边改’的节奏，从零做出一个能上线的产品。","category":"c11-ai-coding","chapterTitle":"第五章 · 让 AI 干活","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["vibe-coding","ai-coding","product-building"],"prereqLessons":["l22-ai-coding"],"nextLesson":"v01-web","sections":[{"type":"opening","question":"你把 AI 的原理、模型、Agent、AI 编程都学了一遍。现在只剩下最后一个问题：我到底怎么靠 AI，做出一个真正能给别人用的产品？","guess":"有人以为要做产品必须先写几年代码，或以为‘让 AI 全自动’就能直接上线。","next":"这一课收官：Vibe Coding 方法学——从想法到上线的五步节奏，以及它与前 17 课的知识怎么连成一条线。学完这课，你就可以直接进入 Vibe 路径，一步步动手了。"},{"type":"why","before":"你懂了很多概念，却感到‘知识到产品’之间有道坎：真上手做，不知道从哪里开始、怎么保证不翻车。","problem":"只要动手就迷茫，往往是缺一套‘从 0 到 1 的通用节奏’——不是缺知识，是缺流程。","need":"Vibe Coding 给了你一套可重复的流程：小步快跑、AI 写我审、先跑通再打磨、随时能回退。把前 17 课的知识装进这条流水线里，知识就开始变现。"},{"type":"oneline","text":"Vibe Coding = 用 AI 当结对程序员，以‘提出想法 → 让 AI 搭建 → 立刻跑起来 → 边用边改 → 测试收尾 → 部署上线’的高频小步节奏做产品；你负责方向、判断与验收，AI 负责快速产出与迭代。"},{"type":"intuition","blocks":[{"k":"用做饭来想","t":"传统开发像按菜谱做满汉全席：先备齐所有料、严格按步骤，做完才能吃。Vibe Coding 像‘边炒边尝’：先做最核心的一道菜，尝一口，再加料调整，食物永远在‘能吃’状态。"},{"k":"用盖房子要图纸来想","t":"即使最快的施工（AI），也需要一张图纸（你的需求与边界）。你的‘产品感’就是图纸；AI 的速度再快，没有图纸就只会到处乱建。"},{"k":"一句话记住","t":"Vibe Coding 不是‘AI 全自动’，而是‘AI 快、人稳’：人给方向与验收，AI 给速度与草稿。节奏高频，风险可控。"}]},{"type":"how","intro":"Vibe Coding 的标准节奏，六步。这也串起你学过的所有概念。","steps":[{"in":"① 定需求：一句话说清你要做什么（与为谁做）","process":"用一个最小可解决问题描述产品：谁的什么痛点、你的方案是什么。范围越小越容易成功（MVP 思维）。","out":"一句清晰的需求 + 一个最小可交付范围","note":"这一步靠你的产品判断，AI 不懂用户，只能帮你澄清。"},{"in":"② 让 AI 搭骨架","process":"把需求、技术选型、约束（用什么框架、跑在哪）交给 AI，让它生成初始代码骨架。给足上下文，产出一发即中的概率更高（上下文工程）。","out":"一份能跑起来的最初版本"},{"in":"③ 立刻跑起来，别等‘完美’","process":"马上去运行、点开看。Vibe Coding 的高频循环从这里开始：跑→看到问题→反馈给 AI→再跑。","out":"一个‘总是能动的’半成品"},{"in":"④ 边用边改：小步迭代","process":"每次只改一小块，用‘分层报错 + 清晰描述’喂给 AI（见 Vibe 路径第 ① 课）。别一次塞一堆改动。","out":"功能逐步齐全、稳定"},{"in":"⑤ 测试与收尾：让 AI 造假不了","process":"请 AI 一起写测试、补边界、检查安全与可维护性。把‘验证’从人肉重复劳动交给自动化（见 Vibe 路径第 ⑤ 课）。","out":"一个经测试、可交付的版本"},{"in":"⑥ 部署上线：让其他人也能用","process":"把本地能跑的版本部署到服务器/托管平台，配好域名与环境（见 Vibe 路径第 ⑦ 课）。至此产品真正‘是个产品’了。","out":"可被访问的线上产品"}]},{"type":"realworld","items":[{"name":"MVP（最小可用产品）","note":"先做一个最核心、能用的小版本，再迭代。Vibe Coding 天然适合这种节奏。"},{"name":"AI 出错的兜底","note":"AI 会挖坑（假依赖、过时 API、逻辑偏差）。用版本控制（Git）、测试、审查来兜底，见 Vibe 路径第 ②⑤ 课。"},{"name":"不要一次让 AI 写‘整个系统’","note":"一次一块，跑通一块。越大越容易失控，越小越好定位问题。"},{"name":"从想法到上线的路径","note":"这正是接下来 Vibe 路径 8 节课要带你走完的事：Web 链路 → Git → API → 数据库 → 测试 → 项目结构 → 部署 → 全流程实战。"}]},{"type":"compare","pairs":[{"a":"传统开发","b":"Vibe Coding","diff":"传统：先设计全、再写代码、周期长；Vibe：先跑通一点点、高频迭代、人审 AI 写。"},{"a":"AI 全自动","b":"Vibe Coding","diff":"全自动 = 没有人在关键处把关，风险失控；Vibe = 人在方向与验收把关，AI 提供速度。"},{"a":"学 AI 原理","b":"做 AI 产品","diff":"原理让你懂‘为什么’（前 17 课）；Vibe 让你会‘怎么做’（点出产品节奏）。两条腿都要有。"},{"a":"MVP","b":"大而全","diff":"MVP 聚焦最小核心、快速验证；大而全一次做完往往拖垮进度、难以验证。"}]},{"type":"mistakes","items":["以为 Vibe Coding = 让 AI 全自动、人撒手——结果是失控。","一次让 AI 生成整个复杂系统——分裂成小块、跑一块再下一块。","不给 AI 上下文就让它开工——需求、技术栈、约束都要交代清楚。","不做测试、不审查就合并——AI 挖的坑要由你填。","只会‘跑起来’不会‘收尾’——错过测试、部署与可维护性，产品永远停留在 Demo。"]},{"type":"deep","title":"深入一点：把前 17 课装进这条流水线（知识地图收束）","beginner":["这 18 节课其实是完整的一条线：看懂 AI → 懂学习 → 懂语言 → 会用 → 让 AI 做事 → 真正做产品。","Vibe Coding 是‘消费端’：把‘生成/原理端’学到的能力，落成产品动作。","你做产品遇到大部分概念难题，都可以回查前面课程找答案。"],"advanced":["从工程看 Vibe Coding：它是把『提示工程、上下文工程、工具调用、Agent 循环、测试、部署』整合成一个可重复的研发流程。","关键在『节奏』：高频小步 + 及时验收 = 风险最小化。每个循环都要有『可回滚』（Git）、『可验证』（测试）作为护栏。","对想长期做产品的人：Vibe Coding 是高效起点，但深入后仍要补工程基础（架构、性能、安全、数据），这正是 Vibe 路径后续内容。"]},{"type":"exercise","prompt":"你想做一个‘帮同事查快递’的小工具，第一次让 AI 动手前最该先做哪件事？","opts":["让 AI 直接写整个系统","先把需求压缩成一句话最大可交付（MVP），并想清楚边界与技术选型，再让 AI 搭骨架","先把代码写完再想需求","什么都不做"],"a":1,"explain":"Vibe Coding 第一步是定清需求与 MVP 边界，再交 AI 搭骨架；直接让 AI 写整个系统最容易失控。","jump":"sec5-step0","jumpLabel":"定需求这一步"},{"type":"check","title":"结课检测：Vibe Coding 方法学你掌握了吗","intro":"共 4 题。全部答对即可完成核心路径，进入 Vibe 路径动手。答错会带你回对应段落复习。","questions":[{"q":"Vibe Coding 的核心分工是？","opts":["AI 全自动，人不管","AI 出速度与草稿，人定方向、判断与验收","人和 AI 各写一半但互相看不懂","不用 AI"],"a":1,"explain":"Vibe Coding 是‘AI 快、人稳’：AI 负责产出与迭代速度，人负责方向、边界与验收。","jump":"sec5-step3","jumpLabel":"边用边改这一步"},{"q":"为什么 Vibe Coding 强调‘先跑起来，别等完美’？","opts":["因为跑起来就自动完美了","高频小步：先有个能用的骨架，边用边发现问题边改，风险最小","为了显得效率高","因为完美永远做不到"],"a":1,"explain":"先跑起来 + 小步迭代，让产品始终‘能动’，问题及时暴露，才不至于最后一次性翻车。","jump":"sec5-step2","jumpLabel":"立刻跑起来这一步"},{"q":"AI 产出的代码，靠什么兜底最靠谱？","opts":["全信不查","版本控制(Git) + 自动化测试 + 人工审查","多跑几次不失败就算对","让 AI 自己检查自己"],"a":1,"explain":"AI 会挖坑，用 Git 可回滚、测试可验证、人来审查，是最稳的兜底组合。","jump":"sec5-step4","jumpLabel":"测试与收尾这一步"},{"q":"本课所在的完整 18 课主线，最后一步指向哪里？","opts":["结束学习","进入 Vibe Coding 工程基础路径，从零动手到上线","再学一遍","去考试"],"a":1,"explain":"核心路径以《Vibe Coding 入门》收官，之后进入 Vibe 路径：从 Web → Git → API → 数据库 → 测试 → 项目结构 → 部署 → 全流程实战。","jump":"sec5-step5","jumpLabel":"部署上线这一步"}],"done":"恭喜你走完 18 课核心主线：从看懂 AI 世界，到懂学习、懂语言、会用、让 AI 干活，再到 Vibe Coding 方法学。下一步，进入 Vibe Coding 工程基础路径，亲手把第一个产品做出来。","nextLesson":"v01-web"},{"type":"connection","known":["AI 原理、训练、语言模型、RAG、Agent、AI 编程（前 17 课）"],"learned":["Vibe Coding = 人定方向 + AI 出速度的小步高频流程","定需求 → 搭骨架 → 跑起来 → 小步改 → 测试 → 部署 六步节奏","MVP、Git 兜底、测试护栏","与 Vibe 路径 8 节课的衔接"],"next":"下一课起进入《Vibe Coding 工程基础》路径：从①『一个 Web 产品是怎么跑起来的』开始，一路做到⑦『从本地 Demo 到正式上线』与⑧『全流程实战』。","links":[{"href":"#/lesson/v01-web","text":"进入 Vibe 路径 ①《一个 Web 产品是怎么跑起来的》"},{"href":"#/lesson/l22-ai-coding","text":"回看《AI Coding》"}]}]},{"id":"l22-ai-coding","title":"AI Coding：把 AI 变成你的结对程序员","subtitle":"从‘让 AI 补全一行’到‘让 Agent 自己把整个功能做完’，AI 编程正在改变开发方式。这一课讲清楚你的新‘结对程序员’该怎么用、边界在哪。","category":"c11-ai-coding","chapterTitle":"第五章 · 让 AI 干活","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["ai-coding","pair-programming","agentic-coding","codegen"],"prereqLessons":["l-agent"],"nextLesson":"l18-vibe-coding","sections":[{"type":"opening","question":"现在很多人‘说几句话就让 AI 写了个网站’。AI 编程到底能到哪一步？是补全几行，还是真能独立完成一整个项目？代码谁负责、谁检查？","guess":"有人以为有了 AI 就不需要会写代码，或以为 AI 写的一定完美。","next":"这一课把 AI 编程按‘参与度’分成几档：补全、生成块、Agent 干活。你会明白 AI 是强力加速器，但产品的主人仍是人——你要负责验收、判断、兜底。"},{"type":"why","before":"你看到同事用 AI 刷刷刷就把功能写完了，也想用起来，但不知道从哪些场景入手、AI 与自己怎么分工、会不会写出不可维护的代码。","problem":"要么把 AI 当‘会写代码的搜索引擎’用（只补全、效率低），要么完全交给 Agent（风险失控、不可维护）。两种极端都不对。","need":"我们建立清晰的协作模型：把 AI 当结对程序员——你定目标、看边界、审结果，它负责快速产草稿、查报错、做重复活。并讲清代码审查永远是人的责任。"},{"type":"oneline","text":"AI 编程 = 把 AI 当作结对程序员：它能极快生成代码、解释报错、重构小块、补齐模板，甚至（Agent 模式）自主跑完一个小任务；但它不负责‘理解真实需求与产品边界’，更不负责‘保证代码正确与安全’——这两条永远是你的职责。"},{"type":"intuition","blocks":[{"k":"用带实习生来想","t":"AI 像一位非常聪明、打字极快、但缺乏项目上下文的实习生：你交代清楚它干得又快又好，但你不审核，它就会把半成品、甚至跑偏的东西交上来。你是那个要验收的‘主管’。"},{"k":"用导航来想","t":"AI 代码生成像开车导航：它帮你规划路线、少走弯路，但最终握方向盘、看路障、负责任的还是你。导航偶尔带你进死胡同，你得会判断。"},{"k":"一句话记住","t":"AI 负责‘快’，人负责‘对’。需求、验收、边界、安全、可维护，这些‘产品感’必须由你把关。"}]},{"type":"how","intro":"按‘AI 参与深度’把 AI 编程分成三档，逐步升级。","steps":[{"in":"① 补全与问答：AI 当‘高级补全器’","process":"在 IDE 里，AI 根据你的上下文补全下一行、解释函数、改命名、写测试骨架。你仍在主导每一行。","out":"写代码更快，错误更少，思路延伸"},{"in":"② 整块生成：给需求要结果","process":"你描述清楚功能（+给上下文/约束），让 AI 生成一块完整代码（接口、函数、组件、配置）。适合模板化、独立、边界清晰的代码。","out":"从一句话到一块可运行代码"},{"in":"③ Agent 模式：让 AI 自己跑任务","process":"给 Agent 目标与工具（读文件、改代码、跑测试、看报错），它循环推进直到完成：读→改→测→看结果→再改。Vibe Coding 常用此模式。","out":"AI 自主完成一个小功能/修复，你只做验收","note":"三档没有绝对高低，按任务复杂度与风险选择：事小用补全，模块化用生成，端到端小任务用 Agent。"},{"in":"④ 无论哪档：验收都是人的责任","process":"AI 产出的代码要过一遍：能跑通吗？符合需求吗？有没有安全/边界问题？有没有不可维护的烂摊子？","out":"‘AI 生成 + 人把关’的可靠组合"}]},{"type":"realworld","items":[{"name":"IDE 补全（Copilot / 助手补全）","note":"在你写代码时实时补全与建议，提升速度，适合第一档使用。"},{"name":"Claude Code / Codex 等 Agent","note":"在终端里用对话让 Agent 自主读代码、改代码、跑测试、看报错并迭代。适合第三档的端到端小任务。"},{"name":"提示词注入与‘AI 挖坑’","note":"AI 可能带进不存在的库、过时 API、或往代码里注入不可靠内容。所以自动合并前要审查与测试。"},{"name":"测试的必要性","note":"AI 生成的代码尤其需要自动化测试兜底——让 AI 同时生成测试，或让测试流程把‘AI 挖的坑’抓出来。"}]},{"type":"compare","pairs":[{"a":"补全","b":"Agent 自主完成任务","diff":"补全由你主导逐行效率；Agent 自主循环完成任务，但风险与失控面也更大，验收更要跟上。"},{"a":"AI 生成","b":"人审查","diff":"生成求快，审查求稳；缺了审查，快只是把问题放大。人最终为代码负责。"},{"a":"上下文工程","b":"单纯提示","diff":"给 AI 越清晰的项目上下文（相关文件、约束、报错），产出越贴近需求；只有一句‘给我写个 XX’往往离题。"},{"a":"AI 编程","b":"传统手写","diff":"AI 加速明显，但可维护性、安全、清晰度仍需人把控。二者是‘助手’与‘主人’，不是替代。"}]},{"type":"mistakes","items":["以为 AI 写的代码多跑几次就完美——需要你验证需求、安全与可维护性。","不给 AI 上下文就让它‘整个写一个系统’——上下文不够，产出必然跑偏。","把 AI 生产的一个报错原样丢回去又问一次——结构化描述（分层+现象+代码+判断）才高效。","忽略测试——AI 生成的代码尤其要靠测试兜底。","让 Agent 无约束乱跑——要给目标、边界、可执行命令白名单，防它越界或引火烧身。"]},{"type":"deep","title":"深入一点：为什么说‘上下文工程’是 AI 编程的核心能力","beginner":["AI 对你代码库的了解，取决于你给了它多少相关上下文：文件、函数、依赖、约束。","把相关文件、报错、你的判断组织好喂给它，比‘但求一句提示’有效得多。","一段‘上下文+需求+验收标准’的提示，往往一次出对。"],"advanced":["Agentic Coding：Agent 通过工具主动读你的仓库（RAG/索引/搜索），自动定位相关文件，减少你手动喂上下文——但你要给它合理的边界与文件白名单。","评估与回归：好的 AI 编程流程是‘可选、可测、可回滚’的；用测试套件 + Git 回滚保证每步可控。","安全：AI 生成的依赖、命令、脚本要审查；警惕提示注入（仓库里的恶意内容诱导 Agent 执行危险操作）。","与 Vibe Coding 衔接：下一课 Vibe Coding 就是‘用 AI 做产品的完整方法学’——从想法到上线的全过程里，AI 编码只是其中一环。"]},{"type":"exercise","prompt":"你让 AI 给一个项目写了个完整功能，它直接贴给你一段很长的代码。最该做的下一步是？","opts":["不看不测直接用","先审查：能否跑通、符合需求吗、有没有安全/边界/可维护问题，再用测试验证","把代码藏起来","直接删掉项目"],"a":1,"explain":"AI 生成求快，人负责对。一定要过需求、跑测试、看边界与安全再合入——验收是人的责任。","jump":"sec5-step3","jumpLabel":"验收是人的责任这一步"},{"type":"check","title":"结课检测：AI 编程你怎么用才靠谱","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"把 AI 当‘结对程序员’，谁对最终代码负责？","opts":["AI","人（你）：负责需求、验收、边界、安全","编译器","没有人"],"a":1,"explain":"AI 提供速度与草稿，但正确性、安全性、可维护性与需求符合度，责任永远在人的验收。","jump":"sec5-step3","jumpLabel":"验收是人的责任这一步"},{"q":"能让 AI 一次产出更贴合需求的代码，最有效的是？","opts":["给足相关上下文、约束与验收标准，而不是一句模糊指令","多喊几句‘再改改’","关了网络","把需求藏起来"],"a":0,"explain":"上下文工程是核心：相关文件、约束、期望结果越清楚，产出一发即中的概率越大。","jump":"sec7","jumpLabel":"上下文工程段"},{"q":"AI 生成的代码尤其需要什么来兜底？","opts":["运气","自动化测试与审查","更多的注释","更长的提示"],"a":1,"explain":"测试能把 AI 挖的坑尽早抓出来；配合人的审查，才够可靠。","jump":"sec6","jumpLabel":"测试的必要性这一条"},{"q":"关于‘AI 挖坑’（引用不存在的库/过时 API），正确的态度是？","opts":["全信 AI","AI 可能出错，所以自动合并前要审查依赖与 API 是否存在、是否过时","因为是 AI 所以一定对","与 AI 无关"],"a":1,"explain":"AI 会编造看似合理的依赖或过时 API。合入前要核验，这也正是人把关的一环。","jump":"sec6","jumpLabel":"AI 挖坑这一条"}],"done":"你会用 AI 编程当加速器了。最后一课，把这些整合成方法论：《Vibe Coding 入门》——从想法到上线，用 AI 完整做产品的全过程。","nextLesson":"l18-vibe-coding"},{"type":"connection","known":["Agent 能让模型自主调用工具（上一课）","上下文窗口与 Prompt 工程（前几课）"],"learned":["AI 编程三档：补全 / 整块生成 / Agent 模式","人负责需求、验收、边界、安全","上下文工程是高效使用 AI 编程的核心","测试兜底与防 AI 挖坑"],"next":"下一步是本路径收官：《Vibe Coding 入门》——把 AI 编程、Agent、上下文这些能力整合成从零到上线的完整产品方法论。","links":[{"href":"#/lesson/l-agent","text":"复习《Agent 智能体》"},{"href":"#/lesson/l18-vibe-coding","text":"进入《Vibe Coding 入门》"}]}]}],"c06-llm-app":[{"id":"pl-function-calling","title":"Function Calling：让模型能『动手』","subtitle":"只会聊天的模型帮不了你太多。Function Calling 让模型学会‘调用你给的函数’——查天气、存取数据、操作外部系统。这是从‘会说’到‘会做’的关键一步。","category":"c06-llm-app","chapterTitle":"第四章 · 用起来","level":"base","estTime":"12-18 分钟","difficulty":2,"concepts":["function-calling","tool-use","structured-output"],"prereqLessons":["pl-prompt"],"nextLesson":"l-agent","sections":[{"type":"opening","question":"你能让 ChatGPT 查天气、订机票、访问数据库吗？单靠聊天它做不到——但真正的产品里它做到了。秘密就是 Function Calling：让模型自己决定‘该不该调用某个函数’。","guess":"有人以为模型‘自己就能联网/操作一切’，或以为函数调用是魔法。","next":"这一课讲 Function Calling：把工具（函数）的说明告诉模型，模型需要时‘点名要调哪个、传什么参’，由你的程序真正执行并回传结果。看完你就懂所有 AI Agent 的底座能力。"},{"type":"why","before":"你想做一个真正‘能干事’的 AI 应用（查数据、调接口、改记录），但发现模型只会生成文本，无法直接操作系统。","problem":"不理解 Function Calling，你会把‘模型直接操作外部’想成理所当然，或把‘结构化输出’和‘函数调用’混为一谈，做出来的应用要么不可靠、要么全是伪需求。","need":"我们把这条链路讲透：工具描述 → 模型请求调用 → 程序执行 → 结果回喂。它是 Agent、工作流、一切会‘做事’的 AI 产品的地基。"},{"type":"oneline","text":"Function Calling = 你把一组‘函数（工具）的说明书’（名字、参数、作用）告诉模型；模型在回答时若需要，就输出一个结构化的‘调用请求’（调哪个函数、传什么参）；由你的程序真正执行并把结果回传给模型，模型再基于结果继续回答。"},{"type":"intuition","blocks":[{"k":"用餐厅点单来想","t":"菜单（工具说明）摆在桌上：有宫保鸡丁、酸辣汤。你问服务员‘有没有辣的’，服务员看了菜单说‘有，宫保鸡丁’。但真正做菜的是后厨，不是服务员。Function Calling 就是：模型是服务员（只会看菜单下单），后厨（你的程序）才真动手。"},{"k":"用给你配助理来想","t":"你有个助手（模型），但没配工具（函数）。你问他今天天气，他只能瞎编。给他配了‘查天气 API’这个工具并告诉他怎么用，他就能‘让我帮你查——把城市名传进去’，由真正的天气服务返回结果，他再念给你听。模型没联网，是‘调用工具’替他联网。"},{"k":"一句话记住","t":"模型不执行函数，它只‘决定要调哪个参数是多少’；你的程序确认执行，把结果喂回去。分工：模型负责决策，程序负责真实世界。"}]},{"type":"how","intro":"一次 Function Call 的完整闭环，五步。","steps":[{"in":"① 注册工具：告诉模型有哪些函数可用","process":"在 API 请求里传一份函数清单 JSON Schema：函数名、参数、说明。模型‘看到’这些说明，但看不到你的实现代码。","out":"模型知道有哪些‘菜单’可选"},{"in":"② 模型判断：本次回答要不要调工具","process":"用户提问后，模型判断是否需要某个工具才能更好地回答；需要则不会直接给最终答案，而是输出一个 function_call 请求。","out":"模型返回‘我建议调用 `get_weather`, 参数 {city: 北京}’"},{"in":"③ 你的程序执行真正的函数","process":"你的代码收到这个请求，去调用真实的天气 API（或数据库、业务接口），拿到实际结果。这一步是‘后厨在做菜’。","out":"真数据结果（如 26°C、晴）"},{"in":"④ 把结果回喂给模型","process":"把函数执行的输出（tool message）作为上下文返回给模型，并告诉它‘这是工具返回的结果’。","out":"模型‘看到’了真数据"},{"in":"⑤ 模型基于结果给出最终回答","process":"模型综合用户问题与工具结果，生成面向用户的最终答案。一次工具调用就完成了。","out":"‘北京今天 26°C，晴’——准确且真实"}]},{"type":"realworld","items":[{"name":"为什么强调‘由程序执行’","note":"模型本身不联网、不读写数据库，它输出的是‘调用意图’；真正执行必须在你可控的代码里做，这也是安全与权限的边界所在。"},{"name":"与结构化输出的关系","note":"Function Calling 依赖模型输出结构化 JSON（函数名+参数）。可以和‘JSON 模式’配合，让输出更规范可解析。"},{"name":"多个工具并行调用","note":"现代 API 允许模型一次请求同时调用多个函数（如同时查天气和订票），再由程序逐个执行、统一回喂。"},{"name":"Agent 的地基","note":"下一课的 Agent 本质上就是：模型 + 一组函数（工具）+ 一个循环（判断→调用→回看 → 再判断）。Function Calling 就是那个‘调用’原语。"}]},{"type":"compare","pairs":[{"a":"文本回答","b":"Function Call","diff":"常规回答只输出文字；function call 输出‘要调哪个函数及参数’的结构化指令，由程序去执行。"},{"a":"Function Calling","b":"你们自己写 if-else","diff":"if-else 是硬编码每个用户问法；Function Calling 让模型动态判断何时调哪个工具，覆盖自然语言里无穷的问法。"},{"a":"工具说明","b":"工具实现","diff":"给模型看的是说明书（名字/参数/作用，JSON Schema）；真实现跑在你侧，模型永远看不到也不该看到。"},{"a":"单轮调用","b":"多轮循环（Agent）","diff":"单次调用一次往返；Agent 会在‘调用→回看结果→再调用’之间循环多次，直到完成复杂任务。"}]},{"type":"mistakes","items":["以为模型‘自己会执行函数’——它只输出调用请求，执行权在你手里。","工具说明写得含糊——模型就传错参数。说明书越清楚（参数必填、类型、示例），调用越准。","把模型当成能直接读你数据库的存在——必须把查询做成工具并控好权限。","忽略安全边界——工具要校验入参、加权限，别让模型拿着能删库的工具乱来。","以为 Function Calling 就是‘发给一条消息’——它是‘决策→执行→回喂’的闭环，要你写执行与回填逻辑。"]},{"type":"deep","title":"深入一点：怎么把工具定义得让模型调得准","beginner":["对每个函数：写清函数名、参数列表（类型、是否必填）、一句话说明‘这个函数做什么、什么时候该调’。","用真实例子给参数取值作示范，能显著降低模型传错参的概率。","职责单一：一个函数只干一件事，便于模型准确调用。"],"advanced":["工具即接口契约：把函数写成 JSON Schema（OpenAI 的 tools 参数 / 各家 tool-use 协议一致）。类型、枚举、最大长度都对模型选择有价值。","并行与依赖：模型可一次输出多个 tool_calls；若存在依赖（第二步要用第一步结果）需多轮循环编排。","安全：白名单调用、输入校验、次数/预算限制、敏感操作二次确认。模型可能被提示注入诱导调用危险工具，要做好防护。","回退与容错：工具调用失败要能告诉模型‘调用失败了’，让它换参数重试或走人工，形成健壮的 Agent 循环。"]},{"type":"exercise","prompt":"你问 AI 助手‘杭州现在天气如何’，它说‘让我调一下天气服务’。实际上谁在执行这个调用？","opts":["AI 模型自己联网","你的程序收到模型的 function_call 请求，去调用真实天气 API 并回填结果","浏览器自动打开天气预报网站","没人执行，它直接编一个"],"a":1,"explain":"模型只输出‘建议调用 get_weather(city=杭州)’；真正访问天气 API 并回传结果的是你的程序，这就是 Function Calling 的分工。","jump":"sec5-step2","jumpLabel":"程序执行真正的函数这一步"},{"type":"check","title":"结课检测：Function Calling 你明白了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"Function Calling 中，模型主要负责？","opts":["真正执行函数、访问数据库","判断该调哪个函数并输出结构化的调用请求（函数名+参数）","编译代码","管理服务器"],"a":1,"explain":"模型承担决策角色：判断是否需要工具、输出‘调哪个、传什么参’；执行由你的程序完成。","jump":"sec5-step1","jumpLabel":"模型判断这一步"},{"q":"给模型看的‘函数清单’本质是什么？","opts":["函数的真实实现代码","函数的说明书（名字、参数、作用，通常是 JSON Schema）","服务器密码","数据库密码"],"a":1,"explain":"传给模型的是一份工具说明（JSON Schema），模型据此知道有哪些函数、怎么调；绝不给实现代码。","jump":"sec5-step0","jumpLabel":"注册工具这一步"},{"q":"一次完成的 Function Call 闭环顺序是？","opts":["执行→描述→决定→回喂","注册工具→模型决定调用→程序执行→结果回喂→模型回答","直接回答→不调用","回喂→执行→注册"],"a":1,"explain":"标准链路：注册工具 → 模型输出调用请求 → 程序执行真函数 → 结果回喂 → 模型给出最终答案。","jump":"sec5-step4","jumpLabel":"模型给出最终回答这一步"},{"q":"以下哪项是使用 Function Calling 时最重要的安全考量？","opts":["给工具强输入校验与权限控制，防止模型/注入调用危险操作","函数名越长越安全","禁止一切函数","只能让模型自己执行"],"a":0,"explain":"模型可能被诱导调用危险工具，所以要在执行侧做好入参校验、权限与配额控制、敏感操作确认。","jump":"sec7","jumpLabel":"安全段"}],"done":"模型学会了‘动手’——但它还不会自己决定‘一直做到完’。下一课把这些串成自动循环：《Agent 智能体》，让 AI 自己规划、调用、观察、再行动。","nextLesson":"l-agent"},{"type":"connection","known":["Prompt 四件套与上下文工程（上一课）","模型只能预测文本，不能直接操作外部"],"learned":["Function Calling = 模型输出调用请求，程序执行","工具说明（JSON Schema）决定调用质量","安全边界：校验、权限、配额","它是 Agent / 工作流的地基"],"next":"会调用了还不够，Agent 要‘自己决定一直做下去’。下一课《Agent 智能体》：目标→推理→调用→观察→再行动 的自动循环。","links":[{"href":"#/lesson/l-agent","text":"进入《Agent 智能体》"},{"href":"#/lesson/pl-prompt","text":"复习《Prompt 与上下文》"}]}]}],"undefined":[{"id":"v01-web","title":"一个 Web 产品是怎么跑起来的","subtitle":"你在浏览器里敲回车到内容出现，中间发生了什么？把这条链路看懂，你才谈得上『改对地方』。","course":"vibe","courseNo":"01","level":"base","estTime":"15-25 分钟","difficulty":1,"concepts":[],"prereqLessons":[],"nextLesson":"v02-git","sections":[{"type":"opening","question":"你每天打开网页、用 App、点外卖、刷视频——但有没有想过，你在浏览器地址栏输入一串字母并按下回车，到底是哪台机器、用哪段程序、按什么顺序，把你要的内容送到你面前的？","guess":"很多人会回答「就是电脑把网站打开了呀」。","next":"这节课我们不写代码，只把『一个 Web 产品』从头到尾拆开：前端、后端、数据库、服务器、浏览器、网络各是什么，数据是怎么一层层流动的，以及每一层出错时你该怀疑谁。学完你就能对着一屏『转圈』或一条报错，说出它大概死在哪个环节。"},{"type":"why","before":"你想用 AI 辅助做一个自己的小产品（一个网页、一个小工具、一个小网站）。AI 很会写代码，但你写完点开经常『跑不起来』或『一片空白』，你不知道该往哪看。","problem":"问题不在 AI 写的代码——而在于你对『这段代码在什么环境里跑、和谁通信』没有概念。你分不清『报错是我的 HTML 写错了』『还是服务器没启动』『还是数据库没连上』『还是网络被墙了』。于是只能把同样的问题反复丢给 AI，越问越乱。","need":"所以第一课先不碰一行代码，而是先建立『一台 Web 产品从上到下有哪些层、每层做什么』的骨架。当你把『前端 / 后端 / 数据库 / 服务器 / 浏览器 / 网络协议』这条链装进脑子，AI 给的报错就不再是天书，而是能对号入座的线索。"},{"type":"oneline","text":"一个 Web 产品 = 浏览器（前端，负责看得见摸得着的界面）+ 服务器上的程序（后端，负责处理逻辑和读写数据）+ 数据库（负责长期存数据），它们之间靠『网络请求』（HTTP）搬来搬去；而这一切最终都跑在『操作系统 + CPU/内存/磁盘』这台物理机器上。"},{"type":"visual","kind":"request-flow","title":"互动实验：点一次请求，看它走完整条路","hint":"点击『发送请求』，看一次『用户敲回车』的动作如何依次经过浏览器 → DNS 解析 → 网络 → 服务器 → 后端程序 → 数据库 → 再原路返回。每亮起一格就说明数据到了哪一层。"},{"type":"intuition","blocks":[{"k":"用点外卖来想","t":"前端＝你看得到的『点单 App 界面』；后端＝『餐厅后厨，负责接单、炒菜、出餐』；数据库＝『冷库里长期保存的食材和菜谱』；服务器＝『餐厅所在的整栋楼，有水电（CPU/内存/磁盘）』；浏览器就是那个帮你点单、再把菜端到你面前的『外卖小哥』。你看到的每一道菜，都是后厨＋冷库＋外卖小哥协作的结果。"},{"k":"用写信来想","t":"你在浏览器输入网址，就像写一封信：『地址』（域名）要翻译成具体的『门牌号 + 邮编』（IP + 端口），信通过『邮政网络』（网络/IP）送出去，邮局先查收信人住在哪（DNS 解析），送到后对方拆信、处理、再回信。回信能不能到，取决于信中地址写没写对。"},{"k":"一句话记住分层","t":"从上到下：浏览器（前端）→ 网络（DNS/IP/HTTP）→ 服务器 → 后端程序 → 数据库。数据请求沿这条链往下，响应再原路往上。出错时按这条链一层层排查，永远不要跳着乱试。"}]},{"type":"how","intro":"把『输入网址到页面出现』拆成一条 7 步因果链。每一步都回答『数据此刻在哪、谁在处理、为什么能做下一步』。","steps":[{"in":"① 你输入网址，按下回车","process":"浏览器得到一串人类好记的名字，比如 ai-learn.example.com。但网络本身不认名字，它只认数字地址（IP：像 203.0.113.7）。所以第一步要『翻译』。","out":"浏览器准备发起一次『网络请求』"},{"in":"② DNS 解析：把域名翻译成 IP","process":"浏览器向 DNS（域名系统）询问：ai-learn.example.com 对应哪个 IP？DNS 就像电话簿，查到后把『数字地址』告诉浏览器。没有这一步，浏览器不知道该把信寄到哪台机器。","out":"得到了服务器的 IP 地址 + 端口（默认 80/443）"},{"in":"③ 建立连接 + 发送 HTTP 请求","process":"浏览器通过 TCP（可靠的传输协议）连上服务器，然后发送一个『HTTP 请求』：里面写着『我要 GET 这个页面』，还带着浏览器自己是谁（User-Agent / Cookie）等信息。","out":"请求沿着网络，送到那台服务器的指定端口"},{"in":"④ 服务器接收并把请求交给后端程序","process":"这台机器上正跑着一个『服务器进程』（如 Nginx / Node / Python）。它把请求转交给对应后端程序；后端程序执行你自己的业务逻辑：查一查、算一算。","out":"后端程序开始处理：可能要读数据库"},{"in":"⑤ 后端读写数据库","process":"需要持久数据的，后端会去数据库查询或写入。数据库把结果（比如『这个用户的名字』）返回给后端。注意：数据库不住在浏览器里，它住在服务器那台机器上。","out":"后端拿到数据，拼出一份『响应』"},{"in":"⑥ 后端返回 HTTP 响应","process":"后端把生成的 HTML / JSON / 图片，打包成一条『HTTP 响应』发回去，附带状态码（200 成功 / 404 找不到 / 500 服务器出错）与响应头。","out":"响应沿着网络原路回到浏览器"},{"in":"⑦ 浏览器解析并渲染","process":"浏览器收到 HTML，逐行解析：先搭出页面结构，再拉取其中的 CSS/JS/图片等资源，最后把内容画到屏幕上。你这才『看到』了页面。","out":"页面出现在你眼前（一次完整的前后端往返）"}]},{"type":"realworld","items":[{"name":"你平时的网页 = 前端静态页","note":"很多『首页』其实只是浏览器直接渲染的一堆 HTML/CSS/JS 文件，可能根本没有后端。它依然需要前面的 ①②③⑦ 几步，但没有 ④⑤⑥。知道这一点，你排查为何『页面能开但功能没反应』时就能猜到问题多半在后端那段。."},{"name":"登录注册 = 必须有后端 + 数据库","note":"『注册新账号』必须把密码/信息写进数据库，所以必然经过完整的 ①→⑦。前端只是收集输入，真正的校验和存储都在后端 + 数据库。这是『看代码时』判断某功能是否需要后端的标尺。"},{"name":"动态内容（推荐、订单、消息）= 后端在返回数据","note":"你刷到的『为你推荐』是后端程序实时查库、算好、再以 JSON 返回给前端渲染的。这类功能换任何界面（网页/App/小程序）后端代码都基本相同——这也是为什么『前后端分离』这么常见。"},{"name":"云服务器 / 租一台机器","note":"你的产品真正上线后，就『住』在一台云服务器（如腾讯云、阿里云的 ECS）上，这台机器有操作系统、CPU、内存、磁盘，常年开机。你的前端文件、后端程序、数据库都装/跑在这上面。"}]},{"type":"compare","pairs":[{"a":"前端 Frontend","b":"后端 Backend","diff":"前端＝用户看到的界面（运行在浏览器/手机里，负责渲染和交互）；后端＝用户看不到、运行在服务器上的程序（负责业务逻辑、鉴权、读写数据库）。前端决定『长什么样、能不能点』，后端决定『数据对不对、安不安全』。"},{"a":"接口 API","b":"直接操作数据库","diff":"后端对外提供的是『接口（API）』——一个约定好的请求地址与返回格式；前端只调用接口，永远不直接连数据库。这样可以隔离权限、便于维护。这也是产品安全的第一道墙。"},{"a":"本地 localhost","b":"线上服务器","diff":"你在自己电脑上跑的前后端叫『本地环境』，地址常是 localhost:3000；部署上线后跑在云服务器上，是公网地址。很多『本地正常、线上挂』的问题，都源于两套环境不完全一样（如数据库没迁移、环境变量没配）。"},{"a":"TCP（可靠）","b":"UDP（快速但不可靠）","diff":"TCP 会确认每份数据都到达（网页、文件用），UDP 不确认、丢了就丢（实时音视频、游戏用）。Web 的 HTTP 默认走 TCP，所以网络差时表现为『加载慢/卡』而不是『内容错乱』。"}]},{"type":"mistakes","items":["以为『网页能打开 = 后端没问题』——错，很多页面是纯前端静态页，后端可能根本没启动。","报错时随手把错误原样丢给 AI，而不说清『发生在哪个层』——AI 只能瞎猜。正确做法是先定位：报错来自浏览器控制台、后端终端、还是数据库连接？","以为『改完代码点刷新就行』——前端改了刷新即可，后端改了常常要重启服务才能生效；数据库结构改了还要迁移。不知道该不该重启，等于不知道该层是否生效。","把 IP、域名、端口混为一谈——域名给人记，IP 给网络认，端口标识这台机器上『哪个程序在服务』。三者不同。","以为 AI 写的代码『放对文件夹就能跑』——代码必须在『正确的环境』（装好依赖、正确版本、正确目录、可执行的权限）里才能运行。环境对不上，代码再对也是白搭（这正是第 7 课上线的核心矛盾）。"]},{"type":"deep","title":"深入一点：把『机器、程序、运行方式』讲透","beginner":["这台电脑/服务器里面有什么？三样最关键的硬件：","**CPU**（中央处理器）：真正会『算』的部分，负责执行指令。它快、但几乎没有记忆。","**内存 RAM**：临时、高速的『草稿本』，程序运行时把正在用的东西放这里；一断电全清空。","**磁盘 Disk**：长期、慢速的『仓库』，文件、数据库、图片都躺在这；断电也保留。","三者关系：程序从『磁盘』读进来 → 在『内存』里运行 → 由『CPU』逐条执行。所以『进程/线程』就是运行中的程序在内存和 CPU 上的具体存在。","**操作系统（OS）**：介于硬件和你程序之间的大管家。它负责：管理文件、管理进程、分配内存、读写磁盘、管理网络与权限。你的程序不是直接拿 CPU 干活，而是『请操作系统帮你安排』。Windows / macOS / Linux 都是操作系统。"],"advanced":["**编译 (Compile) vs 解释 (Interpret)**：代码有两种变可执行的方式。编译型（如 C、Go）：先整体翻译成机器码，再运行，快但改后要重新编译；解释型（如 Python、JavaScript）：一边翻译一边运行，改了就生效，但慢。","**Runtime（运行时）**：指『解释器 / 虚拟机 / 平台环境』，如 Node.js（能让 JS 在服务器上跑）、Python 解释器、Java 虚拟机（JVM）、浏览器的 JS 引擎（V8）。同一个 JS 文件，在浏览器里和 Node 里跑，用的是不同 Runtime——所以『它在浏览器能跑，不代表服务器能跑』。","**进程 (Process) vs 线程 (Thread)**：进程＝一个独立运行的程序实例，有自己独立的内存（跑崩一个不影响别的）；线程＝进程内部可并发的轻量任务单元，共享进程内存。一个 Node 服务通常是一个进程，一次请求常会用到多个线程/异步任务来并行处理。","**文件 / 路径 / 权限**：一切配置、代码、静态资源都是『文件』，文件有『路径』（在哪个文件夹）和『权限』（谁能读/写/执行）。很多部署报错是『权限不够』（403）或『路径不对』（404）——这不是代码逻辑问题，而是环境问题。","**环境 (Environment)**：你的程序依赖很多东西：命令、依赖包、环境变量、数据库地址、端口。这些合称『运行环境』。第 7 课上线的本质，就是把『你本机那套环境』尽量一致地搬到服务器上。"]},{"type":"ask","title":"怎么用 AI 帮你改代码：先问清『第几层』","scenario":"你的页面打开了，但点击『登录』没反应，控制台报了个错。怎么把这个信息高效地交给 AI？","template":"[我要描述] 我在做一个登录功能，点击登录按钮后页面没反应。\n[它能观测到的现象] 浏览器控制台报错：Cannot read properties of undefined (reading 'catch')，出错在 main.js 第 42 行。\n[我判断在哪一层] 前端 JS 在做请求时出错（尚未到后端）。\n[请给我] 帮我定位 main.js 第 42 行为什么报错，并给出修复方案与原因。","acceptance":["AI 给的答案里是否指明了『问题所在的那一层』（前端/后端/数据库/网络/环境）？","修复方案是否同时告诉你『为什么之前会错』（因果），而不只是『把这段换成这段』？","改完是否教你该怎么验证（例如：刷新？重启后端？看哪个日志？）？","如果 AI 只给了代码而你仍不确定，是否会继续追问『这个报错出现在哪一层、我怎么验证』？"],"tip":"给 AI 的信息越『分好层』，它越能准确判断。‘分层 + 现象 + 报错 + 我的判断’ 四件套，能大幅减少来回试错。"},{"type":"exercise","prompt":"你在浏览器打开自己刚做的网站，页面显示出来了，但点『提交表单』后页面一点反应都没有，浏览器控制台也没报错。根据这一课的分层，你最应该先怀疑哪一层？","opts":["我的 HTML 结构写错了（前端静态层）","后端程序没启动或没连上（后端层）","我的屏幕/显卡坏了（硬件层）","域名没过期（网络层）"],"a":1,"explain":"页面能正常显示说明前端静态层基本没问题；但『提交表单』要发请求给后端，没反应最可能是后端没启动、路径不对、或请求根本没发出去。先检查后端服务在不在跑、接口地址对不对。","jump":"sec7-step3","jumpLabel":"第 ④ 步：服务器接收并把请求交给后端"},{"type":"check","title":"结课检测：你能给报错『分层』了吗","intro":"共 5 题。全部答对可进入下一课。答错会带你回到对应段落复习。","questions":[{"q":"浏览器里 DNS 解析这一步骤主要解决什么问题？","opts":["把域名翻译成 IP 地址","把 HTML 渲染成画面","把代码编译成机器码","把密码加密"],"a":0,"explain":"网络只认数字 IP，DNS 负责把人类好记的域名翻译成 IP，浏览器才知道该把请求发到哪台机器。","jump":"sec5-step1"},{"q":"『注册新账号后数据能永久保存』，这件事主要由哪几层协作完成？","opts":["只有浏览器（前端）","后端程序 + 数据库，前端只负责收集输入","只有网络（TCP/IP）","只有操作系统"],"a":1,"explain":"注册必须把信息写入数据库才叫『永久保存』；后端程序负责接收并由数据库落盘，前端只是收集输入。","jump":"sec5-step4"},{"q":"『代码在浏览器能跑』是否代表『同样的代码在服务器上也能跑』？","opts":["一定可以","不一定，因为浏览器和 Node/Python 是不同的 Runtime","一定不可以","只和网速有关"],"a":1,"explain":"浏览器里的 JS 由浏览器 JS 引擎跑，服务器上的 JS 由 Node.js 跑，是不同的 Runtime，能力与可用模块不同。","jump":"sec7"},{"q":"一个『Web 产品』由前端、后端、数据库组成。下面哪句最准确？","opts":["前端能直接连接数据库","后端程序通过接口把数据给前端，数据库由后端访问","数据库必须放在浏览器里","后端程序只能写死数据，不能读数据库"],"a":1,"explain":"前端只调用后端提供的接口(API)，后端负责访问数据库并返回结果，这样能隔离权限、便于维护。","jump":"sec7-step5"},{"q":"某功能『本地 localhost 一切正常，部署到线上就报数据库连不上』，最可能是哪两类环境不一致？","opts":["前端字体大小不同","数据库地址/密码/环境变量，以及迁移状态不一致","屏幕分辨率不同","键盘语言不同"],"a":1,"explain":"本地与线上最多的差距是数据库连接信息（地址、账号、密码）、环境变量配置，以及数据库结构是否已迁移。","jump":"sec7"}],"done":"你现在能把『一个 Web 产品』按层拆开了——前端、后端、数据库、服务器、网络各归其位，报错也能分到对应层。下一课我们钻到『后端』这一层：HTTP 到底是什么，API 怎么写、怎么调。","nextLesson":"v03-api"},{"type":"connection","known":["（这是 Vibe Coding 路径的第一课，默认你已经上过《从零看懂 AI》路径或至少了解『模型/产品』概念。）"],"learned":["一个 Web 产品 = 前端 + 后端 + 数据库 + 服务器 + 网络，彼此通过 HTTP 通信","一次请求的 7 步因果链：输入地址 → DNS → 建立连接/HTTP → 服务器 → 后端 → 数据库 → 渲染返回","CPU / 内存 / 磁盘 / 操作系统 / 进程 / 线程 / 编译解释 / Runtime 的定位","前端 / 后端 / 接口 API / 本地 localhost / 线上 的区别","给 AI 提问前先给报错『分层』，能显著提高一次成功率"],"next":"下一步我们进入『后端』层。想了解 AI 生成/理解代码，可回看 AI 路径的《AI Coding》一课；想把这条链路里『数据是怎么被长期记住的』讲透，下一课（API 与后端）与再下一课（数据库、登录与安全）会分别展开。","links":[{"href":"#/lesson/l22-ai-coding","text":"回看 AI 路径《AI Coding：把 AI 变成结对程序员》"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},{"id":"v02-git","title":"Git 与版本控制：改坏了能回退","subtitle":"AI 会帮你写很多代码，也会帮你挖很多坑。Git 就是你的『时光机』：每次改动都能留下脚印，随时能回到任意一个能跑的状态。","course":"vibe","courseNo":"02","level":"base","estTime":"15-25 分钟","difficulty":1,"concepts":["git","version-control","commit","rollback"],"prereqLessons":["v01-web"],"nextLesson":"v03-api","sections":[{"type":"opening","question":"你让 AI 帮你改了三版代码，第三版比第一版还烂，可你已经不记得第一版长什么样了。或者，你一次『大手笔』改动了 20 个文件，结果整个网站跑不起来了，你该从哪开始往回找？","guess":"很多人会一边叹气一边‘硬改回来’，或者干脆重写一遍。","next":"这一课教你用 Git 给项目装一台时光机：学会『提交快照』、『回到过去』、『看谁改了什么』。从此，你再也不用怕 AI 挖坑——任何时候都能一键回退到能用的时候。"},{"type":"why","before":"你在 Vibe Coding 里高频迭代，AI 每天都在‘改这改那’，你分不清哪次改对了、哪次改坏了。","problem":"没有版本意识时，一切改动都是一次性赌注：改坏了只能干瞪眼，重写又怕丢东西，联合 AI 调试也像无头苍蝇。","need":"你需要一个能记录每次改动、允许你随时回到任何历史状态的工具。Git 就是这个工具——它是所有 AI 编程、团队协作、正式上线的地基。"},{"type":"oneline","text":"Git 是一个版本控制工具：它把项目的每一次改动分别保存成一个个『快照（提交/commit）』，你可以在任意两个快照之间来回切换、对比、合并与回退，相当于给整个代码库装了‘存档 + 读档’功能。"},{"type":"intuition","blocks":[{"k":"用游戏存档来想","t":"Git 就像游戏里的存档系统：每过一关（每次你确认‘行，就这样’）就存一次档。后来玩砸了（改坏了），不用从头再来，直接读档回到上一个存档点。存档点就是 commit。"},{"k":"用写作文改稿来想","t":"你写作文时会保留每一稿：初稿、改一稿、改二稿。每一个‘稿’都是一个版本，你随时能翻回去看最初写得多烂，也能一句句对比改了什么。Git 就是自动帮你留稿，还能任意回看。"},{"k":"三棵树记法","t":"Git 有‘三棵树’：工作区（你正在改的文件）、暂存区（你选定了要记录的改动）、版本库（已正式存档的历史）。顺序是：改文件 → 加进暂存区（git add）→ 提交存档（git commit）。‘提交’就是按下存盘键。"}]},{"type":"how","intro":"一套最简 Git 工作流，五步。你不需要记一堆命令，只记这条主干循环。","steps":[{"in":"① 初始化仓库：git init","process":"在项目根目录执行 git init，Git 就会开始悄悄跟踪这里的所有改动。这相当于宣布‘从今天起，这个文件夹纳入版本管理’。","out":"一个 git 仓库（.git 目录），开始记录历史"},{"in":"② 查看改动：git status","process":"随时运行 git status，Git 告诉你哪些文件被改了、哪些是新增的、哪些还没被跟踪。这是每次动手前后的‘体检’。","out":"清楚当前工作区里有哪些变动"},{"in":"③ 选定要记录的内容：git add","process":"把你想纳入这份快照的文件加入暂存区。可以全部加（git add .），也可以挑几个加。你决定‘这一份存档里要包含什么’。","out":"文件进入暂存区，等待被提交"},{"in":"④ 正式存档：git commit","process":"执行 git commit，并写一句说明（如‘修复登录按钮’）。这一步像按下存盘键，一个永久、可回退的版本节点就诞生了。","out":"一个带说明的历史版本（commit）"},{"in":"⑤ 回退与查看历史：git log / git checkout / git reset","process":"用 git log 看所有历史版本；改坏了用 git checkout 或 git reset 回到某个 commit；git diff 对比两个版本差别。这就是你的时光机操作台。","out":"随时能回到任意能跑的历史状态"}]},{"type":"realworld","items":[{"name":"每次‘能用’就提交","note":"Vibe Coding 的黄金习惯：只要当前版本能跑、你觉得 OK，就立刻 commit。这会形成一串‘安全的存档点’，让你随便折腾 AI。"},{"name":"提交信息写清楚","note":"写一句人话（‘加了登录’而不是‘改了点东西’），几周后你才知道每个存档里装了什么。AI 生成的代码更要写清楚，否则回退都不知道回到哪。"},{"name":"分支 branch：开一条平行世界","note":"你想大胆试一个新功能又不想搞乱主版本时，开一个分支去折腾，成了再合并回来，毁了就丢。这是团队协作和探索新玩法的基础。"},{"name":"GitHub 远程仓库","note":"把本地仓库推到 GitHub（git push），你的代码就有了云端备份，也方便和 AI/他人协作。这是后续‘部署上线’的前置步骤。"}]},{"type":"compare","pairs":[{"a":"git add","b":"git commit","diff":"add 是把改动选进‘暂存区’（决定存哪些），commit 是正式存档（生成一个永久历史节点）。add 可反复调整，commit 一按即生效。"},{"a":"git checkout","b":"git reset","diff":"checkout 常用于切到某版本查看/恢复单文件，偏‘只管当前状态’；reset 会把仓库指针移回某提交，可能连带影响历史。新手优先用 checkout 更安全。"},{"a":"本地仓库","b":"远程仓库(GitHub)","diff":"本地仓库在你电脑上，随改随存；远程仓库在云端，用于备份、协作、部署。两者靠 push/pull 同步。"},{"a":"没有 Git","b":"有 Git","diff":"没有 Git，改坏了只能靠记忆或重写；有 Git，随便改、随时回退、随手对比，风险大幅降低。"}]},{"type":"mistakes","items":["只在‘做坏了’才想起 git——其实应该在‘做对了’（能跑）时就提交，形成安全存档点。","提交信息乱写甚至不写——几周后完全看不懂每个存档是干嘛的。","把 node_modules、.env 密码等不该提交的文件也提交了——这些要么巨大要么含敏感信息。","一次提交塞了 20 个文件的无关改动——回退和排查时一团乱。每份提交尽量单一、聚焦。","以为 git 会‘自动保存’——不会！你得手动 add + commit。忘了提交 = 没存档。"]},{"type":"ask","title":"怎么用 AI 帮你处理 Git：把报错和意图一起给","scenario":"你想回退一个改动，但不太确定用哪个命令，或者 git 报了一大串英文错误。","template":"[我的意图] 我想把刚改坏的登录功能回到『能跑』的那个版本。\n[我做了什么] 刚刚 commit 了一个修复登录的版本，现在想回到上一个能跑的版本。\n[我看到的报错] git 提示：error: Your local changes to the following files would be overwritten by checkout...\n[请给我] 告诉我这个报错是什么意思，应该用哪个命令安全回退，并且不要丢我现在还没提交的改动。","acceptance":["AI 是否先解释了报错的含义，而不是直接丢命令？","是否提示了‘会覆盖未提交改动’这类风险，让你确认后再执行？","是否给出安全回退的具体命令序列？","是否提醒你在回退前先 commit 或 stash，避免丢失当前工作？"],"tip":"亲手学会 git 三个核心动作（add/commit/checkout），其余的交给 AI 也行——但你要能看懂它在给你做什么、会不会有风险。"},{"type":"exercise","prompt":"你让 AI 改了代码，然后手动运行发现网站跑不起来了。你希望回到‘之前的能跑版本’。下面哪个动作是你应该先确认的？","opts":["立刻 git commit，把坏掉的也存档一份","先 git log 找到最近一个能跑版本的提交编号，再据此回退","直接删掉整个项目文件夹重新开始","啥也不做继续改"],"a":1,"explain":"正确做法是先 git log 定位到能跑的那次提交，再用 git checkout / reset 回退到该版本。把坏版本也 commit 存档（选项 1）反而制造了更多坏存档，不是首选。","jump":"sec5-step4","jumpLabel":"回退与查看历史这一步步"},{"type":"check","title":"结课检测：你掌握 Git 时光机了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回对应段落复习。","questions":[{"q":"Git 里‘存档点’的正式名称是什么？","opts":["分支","提交 (commit)","暂存区","工作区"],"a":1,"explain":"commit（提交）就是保存一个可回退的历史快照，相当于游戏存档点。","jump":"sec5-step3"},{"q":"正确的‘三棵树’操作顺序是？","opts":["commit → add → 修改","修改文件 → git add → git commit","git add → 修改 → git commit","git commit → git checkout"],"a":1,"explain":"顺序是：先在工作区修改文件，再用 git add 选入暂存区，最后 git commit 正式存档。","jump":"sec5-step2"},{"q":"为什么 Vibe Coding 强调‘能跑就立刻 commit’？","opts":["为了显得专业","形成安全存档点，之后随便让 AI 折腾都能回退","提交越多代码越少","Git 会自动备份"],"a":1,"explain":"每个能跑的 commit 都是一个安全存档点，AI 后续怎么改坏了都能一键回到这个状态。","jump":"sec5-step4"},{"q":"下面哪类文件最不应该被提交到仓库？","opts":["源码 js 文件","含密码/密钥的 .env 等敏感配置","html 页面","readme 说明"],"a":1,"explain":"敏感配置（.env 含密钥）绝不应提交，否则会被泄露；这类通常放进 .gitignore。","jump":"sec6"}],"done":"你现在有了自己的时光机：能存档、能回退、能对比，再也不怕 AI 挖坑了。下一课进入后端：API 到底是什么，前后端怎么在 HTTP 里对话。","nextLesson":"v03-api"},{"type":"connection","known":["你已了解一个 Web 产品的分层（v01）、AI 会挖坑的风险（Vibe 课核心）"],"learned":["Git = 版本控制的存档系统，add/commit/checkout 主干循环","‘能跑就提交’形成安全存档点，是 AI 编程的兜底","分支、远程仓库、.gitignore 等进阶用法","给 AI 处理 Git 报错时的安全提问方式"],"next":"自这一步开始，你的每次改动都有据可查。下一课我们进入后端层：API 与 HTTP——前后端到底是怎么说话的。","links":[{"href":"#/lesson/v03-api","text":"下一课：《API 与后端：前后端怎么对话》"},{"href":"#/lesson/v01-web","text":"回看《一个 Web 产品是怎么跑起来的》"}]}]},{"id":"v03-api","title":"API 与后端：前后端怎么『对话』","subtitle":"前端要数据、后端给数据，靠的是一套约定好的『暗号』——HTTP 方法与状态码。看懂它对 AI 来说轻而易举，对你是判断代码靠不靠谱的分水岭。","course":"vibe","courseNo":"03","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web"],"nextLesson":"v04-db","sections":[{"type":"opening","question":"你的 App 在前端里点了个『收藏』按钮，后端怎么知道你要『新增一条收藏』而不是『删除一条』？同样是敲同一个接口地址，凭什么这次是加分、那次是删东西？","guess":"很多人会说『靠传一个名字不一样的按钮』。","next":"答案藏在 HTTP 的『方法（Method）』里。这一课我们把前后端之间的对话协议——HTTP 方法和状态码——彻底讲透：GET 和 POST 到底差在哪，200/404/500 各代表什么，什么是 API、什么是 JSON。学完你会开始『读』接口而不是『猜』接口。"},{"type":"why","before":"AI 写了个后端接口，前端也调了。你看着代码：有一堆 `app.get('/api/friends')`、`app.post('/api/friends')`、`req.body`、`res.json(...)`。你不懂为什么有的用 get 有的用 post，也不知道返回的 `{status:'ok', data:[...]}` 是什么。","problem":"不懂 HTTP 方法与状态码，你会犯两种错：要么把『该用 POST 写数据的操作』写成了 GET，导致数据带在 URL 里、既不安全又不支持大内容；要么拿到报错号 404/500 完全没概念，不知道该看前端还是后端。AI 生成的代码你再不敢动，一改就崩。","need":"把 HTTP 的『动词』（方法）、『回执』（状态码）、『货单』（请求/响应头与正文 JSON）看明白，你就拥有了『判断一段接口代码对不对』的最小能力：方法对不对、状态码合不合理、参数传没传对。这正是把 AI 代码从『能跑』升级到『可靠』的一步。"},{"type":"oneline","text":"API 是后端对外开的一扇扇门（URL），你用『HTTP 方法』说明你想干嘛（GET 拿数据 / POST 新增 / PUT 整体更新 / PATCH 部分更新 / DELETE 删除），后端用『状态码』告诉你结果（2xx 成功 / 4xx 你这边的问题 / 5xx 服务器的问题），数据通常以 JSON 格式在请求和响应里传递。"},{"type":"visual","kind":"http-viewer","title":"互动实验：HTTP 查看器，亲手发一个请求","hint":"选一个方法、填一个地址（或点预设接口），点『发送』。它会向你展示：这次请求带了哪些方法/头部/参数，服务器会返回什么状态码与 JSON 正文，以及每个状态码对应的含义。体会『同一个 URL，方法不同 = 动作不同』。"},{"type":"intuition","blocks":[{"k":"用餐厅点菜来想","t":"API 地址（URL）＝餐厅的『窗口名』，比如『/api/friends』是『朋友窗口』；HTTP 方法＝你点菜的动作——‘看看今天的菜单’（GET）、‘点一个菜’（POST）、‘把整个菜换掉’（PUT）、‘加个辣’（PATCH）、‘退掉这个菜’（DELETE）。后端（厨师）按你的动作处理，再用状态码告诉你：‘上菜了’（200）、‘这个菜没有’（404）、‘厨房炸了’（500）。"},{"k":"用寄快递来想","t":"GET 就像‘查单号’——只读，不改变任何东西，可以来很多次；POST 就像‘下单寄件’——会产生一个新的快递（新增数据）。所以‘收藏、下单、注册、发帖’这些会新增数据的操作用 POST，而‘翻页、搜索’这种只看不动的用 GET。"},{"k":"一句话记住状态码","t":"2 开头的都成功；3 开头的是‘让你去别处看’（重定向）；4 开头的是‘你（客户端）的问题’（404 找不到、401 没登录、403 没权限、400 请求写错）；5 开头的是‘服务器（后端）的问题’（500 内部出错）。看到 4 或 5，你就能立刻判断该检查哪一边。"}]},{"type":"how","intro":"把一个 HTTP 请求拆成 5 个部分，从头到尾走一遍『前端 → 后端 → 响应回前端』。","steps":[{"in":"① 请求行：方法 + URL","process":"前端发起一行字：`POST /api/friends`。前半是方法（动作），后半是接口地址（去哪扇门）。这决定了后端接下来执行哪段逻辑。","out":"例如 POST = 新增；GET = 查询；DELETE = 删除"},{"in":"② 请求头 Headers","process":"附带的一堆元信息：Content-Type（正文是 JSON 还是表单）、Authorization（登录凭证，如 Bearer token）、Accept（你想要什么格式）、携带的 Cookie 等。后端靠这些判断『你是谁、你给的是什么』。","out":"身份与格式声明"},{"in":"③ 请求正文 Body","process":"POST / PUT 需要把要写入的数据放进正文，通常是 JSON：`{\"name\":\"小明\",\"phone\":\"138...\"}`。GET 一般没有正文，参数放在 URL 查询串里（?name=小明）。","out":"数据内容（多为 JSON）"},{"in":"④ 后端处理并返回状态码","process":"后端读到方法+地址+头+正文，跑对应的逻辑，无论成败都返回一个状态码：成功 200/201，找不到 404，参数错 400，没登录 401，服务器异常 500。","out":"状态码：2xx / 4xx / 5xx"},{"in":"⑤ 响应正文 + 响应头","process":"成功后后端通常返回一个 JSON：`{\"ok\":true,\"data\":{...}}`，前端拿到这个结构再决定如何渲染。响应头里也常有 Set-Cookie、Cache-Control 等控制信息。","out":"前端拿到 JSON，渲染到界面"}]},{"type":"realworld","items":[{"name":"浏览器开发者工具 Network 面板","note":"按 F12 → Network，你能亲眼看到每一笔请求：方法、URL、状态码、耗时、请求/响应头与 JSON。这是『读接口』最重要的工具，AI 给不了你，但它能解释你从里面截到的任何一行。"},{"name":"REST 设计风格","note":"REST 是一套流行的接口组织约定：把『资源』当名词放 URL（/users、/posts），把动作当方法（GET/POST/PUT/DELETE）。例如 GET /users/5 读用户5，DELETE /users/5 删用户5。看懂 REST，你便看懂了大半后端代码的结构。"},{"name":"第三方开放 API（天气/支付/地图）","note":"你在产品里调的天气、支付、地图接口，就是对面公司后端暴露的 API。你会看到它要求固定方法、固定鉴权头（Authorization/ApiKey）、返回固定 JSON 结构。会读 API 文档 = 会接第三方能力。"},{"name":"前后端分离项目","note":"很多现代项目前端与后端是两个独立工程，只通过一组 API 契约对接。只要接口约定不变，前端可以换成任何形态（网页/App/小程序），后端完全不用改。这也解释了为什么『接口规范』如此重要。"}]},{"type":"compare","pairs":[{"a":"GET","b":"POST","diff":"GET 用于『读』数据：参数放 URL，可分享/可缓存，不应产生副作用（不会改服务器的数据）；POST 用于『写』数据：参数放正文，用于新增/提交，会产生副作用。安全与不大数据量的操作用 GET，会改数据的操作用 POST。"},{"a":"状态码 4xx","b":"状态码 5xx","diff":"4xx 是『客户端问题』：请求写错、没登录（401）、没权限（403）、找不到（404）——请检查你前端发出去的请求；5xx 是『服务器问题』：后端代码异常（500）、超时（504）——请检查后端日志。"},{"a":"REST API","b":"GraphQL","diff":"REST 靠『多个端点 URL + 方法』组织接口；GraphQL 靠『一个端点 + 查询语句』按需取字段。REST 更简单通用、生态大；GraphQL 更灵活但要学查询语法。入门从 REST 开始最稳。"},{"a":"JSON","b":"表单 Form-encoded","diff":"JSON 是一种结构化文本（{\"k\":v}），后端好解析、支持嵌套，是现代 API 主流；传统表单格式（a=1&b=2）较简单但在复杂数据前吃力。看到 Content-Type: application/json 就知道后面是 JSON。"}]},{"type":"mistakes","items":["AI 常犯（也常让你中招）的错误案例①：把『该用 POST 的新增操作』写成了 GET，导致密码等敏感数据出现在 URL / 日志里，既不安全又不支持大内容。","错误案例②：删改操作应返回合适状态码，却一律返回 200——前端永远‘成功’，数据却没被真正删掉。看到代码里所有分支都 res.json({ok:true}) 且不看状态码，就要警惕。","错误案例③：前端没把 token/Cookie 带上（没设置 headers.Authorization），导致后端每次回 401；前端却把锅甩给‘后端 bug’。判断法：看 Network 里那次请求的请求头带没带凭证。","把 404 理解成‘页面不见了’就完事——404 也可能是‘接口地址写错’，要不检查前端 URL，要不检查后端路由。/api/users 与 /api/user 差一个字母就是两个世界。","盲目照抄 AI 生成的接口而不看返回结构：前端拿 res.data.data 却和接口对不上，出来全是 undefined。学会看 Network 里真实的 JSON 结构再写渲染。"]},{"type":"deep","title":"深入一点：怎么判读一段 AI 写的接口代码","beginner":["拿到 AI 写的后端接口，按下面三问逐一看，就能快速判断靠不靠谱：","**一问方法**：这个操作该不该用这个 HTTP 方法？读操作用 GET，写操作用 POST/PUT/DELETE。方法不对 = 语义错。","**二问状态码**：成功路径返回 2xx 吗？参数错返回 400 吗？没登录返回 401 吗？没有的数据返回 404 吗？服务器异常会抛 500 吗？一个只返回 200 的接口是不合格的。","**三问数据流**：后端取参数的字段名，和前端传的字段名一致吗（body.name）？返回的 JSON 结构和前端 res.data.xxx 对得上吗？对不上就是坑。"],"advanced":["**express（Node 后端框架最小示例）**：","```js\napp.get('/api/users/:id', async (req, res) => {\n  const user = await db.one('SELECT * FROM users WHERE id=$1', [req.params.id]);\n  res.status(200).json({ ok: true, data: user });\n});\n```","注意三件事：`:id` 是路径参数（req.params.id）；操作是读 → 用 GET；成功返回 200。若查不到应 `return res.status(404).json({ok:false})`，而不是硬返回 200 空对象。","**错误处理缺失是最大隐患**：AI 常写出‘只管成功不管失败’的接口。可靠接口要捕获异常并返回 5xx：","```js\napp.post('/api/users', async (req, res) => {\n  try { await db.insert('users', req.body); res.status(201).json({ok:true}); }\n  catch (e) { console.error(e); res.status(500).json({ok:false, msg:'写入失败'}); }\n});\n```","**‘如何向 AI 验收一个接口’**：让 AI 给出‘该方法、正常/异常状态码、请求/响应 JSON 示例’三件套；你再对照 方法→语义 是否正确。能给出完整三件套的接口定义，才值得写进产品。"]},{"type":"ask","title":"怎么用 AI 帮你写/改一个接口","scenario":"你让 AI 写一个‘新增好友’的后端接口，并希望它可靠、前后端好对接。","template":"[我要做一个] POST /api/friends 的新增好友接口。\n[我希望的入参] JSON：{ nickname, remark }。\n[我希望的结果] 成功后返回 201 + {ok,data};昵称为空返回 400;后端异常返回 500。\n[请给我] 完整的 Node/Express 代码（含错误处理），并附：请求示例 JSON、成功/失败状态码与返回体、以及前端如何 fetch 调用的示例。","acceptance":["接口是否用对了 HTTP 方法（新增→POST）？","是否覆盖了成功(201)、参数错(400)、服务器错(500) 至少三类状态码？","请求与响应 JSON 结构是否给出、且前后端字段名一致？","是否包含 try/catch 错误处理而不是只管成功？用浏览器 Network 面板实测一下接口是否按文档返回。"],"tip":"把‘我要什么入参 + 我要什么结果 + 我要什么状态码’写成模板，AI 生成的接口会立刻规范很多；再用 Network 面板实测验证，别只看它嘴上说‘OK’。"},{"type":"exercise","prompt":"你在前端写了一个请求，点按钮后 Network 面板显示某请求返回 401。你最应该先检查什么？","opts":["后端 SQL 写错了","前端这次请求有没有带上登录凭证（Authorization/Cookie）","服务器机器坏了","网络 DNS 解析失败"],"a":1,"explain":"401 = 未认证/未登录，最常见原因就是请求没带凭证。去看 Network 里这一次请求的请求头，确认是否带了 token 或 Cookie。","jump":"sec5-step1","jumpLabel":"第 ② 步：请求头 Headers"},{"type":"check","title":"结课检测：你会读 API 了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"‘把一条收藏记录保存起来’应该用哪个 HTTP 方法？","opts":["GET","POST","PUT","DELETE"],"a":1,"explain":"产生新数据的写操作应该用 POST；GET 只用于读，不该产生副作用。","jump":"sec5-step0"},{"q":"状态码 401 表示什么？","opts":["找不到页面","未认证/未登录","服务器内部错误","请求太大"],"a":1,"explain":"401 Unauthorized = 未认证，需要登录凭证；403 才是‘已登录但没权限’。","jump":"sec5-step4"},{"q":"看到返回 500，你优先怀疑哪一层？","opts":["前端渲染","浏览器缓存","后端程序异常","CSS 样式"],"a":2,"explain":"500 = Internal Server Error，是服务器（后端）处理出错，去查后端日志与代码。","jump":"sec5-step4"},{"q":"REST 接口中，URL 里的名词代表什么？","opts":["动作（增删改查）","资源（如 /users、/posts）","设计者名字","数据库类型"],"a":1,"explain":"REST 把资源当名词放 URL，动作由 HTTP 方法表达。GET /users/5 是‘读用户5’。","jump":"sec6"},{"q":"前端请求里，登录凭证通常放在哪个位置？","opts":["URL 查询串","请求头 Headers（如 Authorization）","CSS 文件","浏览器书签"],"a":1,"explain":"凭证（token/Cookie）一般放在请求头里，如 Authorization: Bearer xxx；不放会导致 401。","jump":"sec5-step1"}],"done":"你已经能读懂前后端之间的‘暗号’了：方法定动作、状态码定结果、JSON 传数据。下一课我们把线的另一头——数据本身——讲清楚：数据库怎么设计，登录与安全怎么做。","nextLesson":"v04-db"},{"type":"connection","known":["你已经知道一个 Web 产品 = 前端 + 后端 + 数据库，通过 HTTP 通信（上一课）。","你已经会调用模型/看得懂 AI 相关 API 的基础概念（AI 路径）。"],"learned":["HTTP 方法：GET 读 / POST 写 / PUT 整体更新 / PATCH 局部更新 / DELETE 删除","状态码：2xx 成功 / 4xx 客户端问题 / 5xx 服务器问题","请求 = 方法 + URL + 头 + 正文(JSON)；响应 = 状态码 + JSON","REST 设计：名词当资源，方法当动作","给 AI 描述接口需求时，用‘入参+结果+状态码’三件套模板"],"next":"接口是承上启下的：它把‘数据’从后端递给前端。可数据从哪来、怎么存、怎么保证安全？这正是下一课《数据库、登录与安全》要解决的。和 AI 路径的联系：你调用大模型 API 的本质也是‘前端→HTTP→别人家后端的接口’，底层逻辑完全相同。","links":[{"href":"#/lesson/l16-llm-api","text":"回看 AI 路径《用 API 把模型接进你的产品》(规划中)"},{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"}]}]},{"id":"v04-db","title":"数据库、登录与安全","subtitle":"数据是产品的命，登录是产品的门。这一课把‘数据怎么存’、‘你怎么证明是你’、‘怎么防坏人’讲透。","course":"vibe","courseNo":"04","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api"],"nextLesson":"v05-test","sections":[{"type":"opening","question":"用户注册了账号、收藏了文章、下了单——这些数据如果不做任何抽象地乱放在一起，会出什么问题？‘收藏’和‘用户’之间到底是什么关系？而你按下‘登录’，服务器凭什么相信你就是那个人，而不是冒充的？","guess":"很多人觉得‘数据随便存个文件不就行了，登录就是在数据库里对一下密码’。","next":"这一课回答三件事：①数据用‘关系表’组织才不乱（表、列、主键、外键、索引、SQL）；②‘登录’不是查一下密码那么简单——Session、JWT、OAuth 各是怎么证明‘你是谁’的；③坏人会怎么攻击（SQL 注入、XSS），以及怎么守住（参数化、转义、加密/哈希、最小权限）。"},{"type":"why","before":"AI 帮你生成登录/注册/收藏/下单功能，里面全是你不认识的词：SQL、primary key、foreign key、index、session、token、bcrypt、JWT、OAuth、SQL 注入。你照抄能跑，但出问题时完全无法判断是‘表没建对’‘还是登录逻辑错’‘还是被人攻击了’。","problem":"数据库设计与安全是‘你几乎不会让 AI 自己随便发挥’的地方——因为数据是用户资产、登录是安全边界。如果不懂“为什么用户表要 id 做主键”“为什么密码要哈希不能存明文”“为什么 SQL 要参数化防止注入”，你根本没法验收 AI 的代码，等于把产品最关键的部分交出去赌运气，早晚出事。","need":"这一课把最少必备的数据库设计与安全知识补上：会看表结构、会写最基础的 SQL、能对比 Session / JWT / OAuth、知道 SQL 注入和 XSS 是什么并知道对应防御。这样当 AI 给出表结构和登录代码，你能像审稿人一样快速挑出明显错误。"},{"type":"oneline","text":"产品数据大多存在关系型数据库（如 PostgreSQL/MySQL）：数据按‘表’组织，每行一条记录，靠‘主键’唯一标识，表与表用‘外键’建立关系，用 SQL 增删改查；登录靠加密凭证证明身份（Session 服务端记、JWT 它自己证明、OAuth 让第三方背书）；安全的核心三件事——密码要哈希不要明文、SQL 用参数化防注入、输出要转义防 XSS。"},{"type":"visual","kind":"db-designer","title":"互动实验：设计一张数据库表","hint":"这是一个迷你‘表设计器’：你决定表有哪些列、哪列是主键、要不要加索引、要不要存密码明文。点击‘预览 SQL / 检查问题’，它会告诉你这张表会不会踩主键、密码明文、可空、无索引等常见坑。体会‘多花一分钟设计，省无数 bug’。"},{"type":"intuition","blocks":[{"k":"用班级花名册来想","t":"数据库里的‘表’就像一张花名册：‘列’是表头（学号、姓名、班级），‘行’是一条记录（某个同学）。‘主键（primary key）’＝学号——全班唯一，靠它能精准找到某个人；‘外键（foreign key）’＝‘本班编号’——它指向另一张‘班级表’的主键，从而把两张表关联起来。没有主键，你用‘姓名’找人会遇到重名；没有外键，班级和学生就接不上。"},{"k":"用门禁卡来想登录","t":"Session＝你在前台刷了一次脸后，前台给你一把只在这栋楼有效的临时钥匙，钥匙上是你进门时发的一个号码（sessionId），门卫每次核对后台名单；JWT＝一把自带信息的加密卡片，上面写着‘我是小明，3 小时后过期’，门卫验签名就放行，不用每次查后台；OAuth＝你出示‘微信已认证’的凭证，门卫信微信的背书就让你进。三种都是‘证明你是你’，只是证明的方式和存放地点不同。"},{"k":"一句话记住安全","t":"密码只存哈希（加盐），不存明文；SQL 永远用参数化（?/$1 占位符），别拼字符串；输出到页面要转义（防 XSS）；后端始终校验，前端校验只是体验。记住这四条，你能挡住绝大多数入门级攻击。"}]},{"type":"visual","kind":"auth-compare","title":"互动实验：Session / JWT / OAuth 三种登录横评","hint":"点击三种登录方式，看同一个‘登录→鉴权→访问’场景在后台是怎么不同的：状态存在哪、怎么验证、有没有跨端问题、优缺点一目了然。帮你给产品选对登录方案。"},{"type":"how","intro":"把‘数据入库 + 登录鉴权’拆成两条因果链：先看一张表从设计到查询怎么走，再看一次登录如何完成。","steps":[{"in":"① 设计表结构（Schema）","process":"确定这张表存什么：用户表要有 id（主键）、username、password_hash、created_at。列的类型要选对（数字用 integer、文本用 varchar）。先想好‘要回答什么问题’，再定表，否则后面改结构（迁移）很麻烦。","out":"一张结构清晰的表 + 主键"},{"in":"② 建表 + 加索引","process":"用 SQL 建表；对‘经常按它来查’的列（如 username）加上索引（index），否则数据多了每次都全表扫描、慢到卡死。索引=书的目录，能加速查找。","out":"表建好，查询有索引加持"},{"in":"③ 用 SQL 增删改查","process":"INSERT 插入、SELECT 查询、UPDATE 更新、DELETE 删除。查询可加 WHERE 过滤、JOIN 关联别表。这是后端操作数据库的日常。","out":"数据被正确写入/读出"},{"in":"④ 表和表用外键建立关系","process":"比如‘收藏表’里放一个 user_id 外键指向用户表、一个 article_id 指向文章表，就能表达‘这个用户收藏了那篇文章’的关系。","out":"数据之间有明确关联，不重复、不乱"},{"in":"⑤ 登录：验证 + 发凭证","process":"用户输入密码 → 后端把输入的密码加盐哈希，和库里存的那个哈希比对 → 相同则信任，创建会话凭证（Session 存服务端 / JWT 返回一个 token / OAuth 走第三方）。","out":"前端拿到凭证，后续请求都带上它"},{"in":"⑥ 访问控制：每步鉴权","process":"后续每个需要身份的请求，后端都校验凭证 → 合法才放行，非法返回 401。同时用权限逻辑控制在‘只能动自己的数据’（不能改别人的）。","out":"只有合法用户能访问其权限内的数据"}]},{"type":"realworld","items":[{"name":"用户系统崩了=数据库没备份/没迁移","note":"很多线上事故是数据库结构改了没做迁移，或连接串配错。知道‘表结构=产品地基’，你就会让 AI 在改表时同步给迁移脚本（ALTER TABLE…），并先在本地/测试库验证。"},{"name":"密码泄露事件=明文存储的代价","note":"反复出现的‘XX 网站密码库泄露’事故，根源常是明文或弱哈希存密码。正确做法：bcrypt/scrypt 加盐哈希。这是判断 AI 登录代码‘安全与否’的第一眼标准。"},{"name":"登录方案选择=产品形态决定","note":"简单网页用 Session 就够；前后端分离/多端（App+网页+小程序）常用 JWT；要‘微信一键登录’就用 OAuth。你会常看到这三者在真实项目里混用（如 JWT 登录 + 微信 OAuth 授权）。"},{"name":"防火墙/最小权限=运维层防御","note":"生产数据库通常不直接暴露公网，只允许服务器内网访问；应用账号只给它需要的库表权限。这是安全纵深的一部分，和‘代码那次注入’互补。"}]},{"type":"compare","pairs":[{"a":"Session（服务端会话）","b":"JWT（令牌）","diff":"Session 把状态存在服务器（内存/Redis/库），客户端只持一个 sessionId，好处是可随时踢人/注销；JWT 把身份信息加密签进 token 给客户端，服务器无状态，好处是天然适合多端与分布式，缺点是一旦签发难在过期前吊销。选型：传统/单一服务用 Session，前后端分离多端多用 JWT。"},{"a":"JWT","b":"OAuth","diff":"JWT 是一种‘凭证格式’（我信任它的签名）；OAuth 是一种‘授权协议’（用户把权限授予第三方，如‘微信允许这个 App 读我的昵称头像’）。OAuth 常把 JWT 当作其中一种 access_token 的载体。"},{"a":"哈希 Hash（单向）","b":"加密 Encrypt（可逆）","diff":"哈希不可逆：密码只做比对，任何人（包括你自己）都无法还原，适合存密码；加密可逆：能解回原文，适合传输敏感信息（但要妥善保管密钥）。拿加密去存密码是常见误区。"},{"a":"SQL 注入","b":"XSS 跨站脚本","diff":"注入是‘坏人把 SQL 代码塞进输入，骗后端执行’，防御靠参数化查询；XSS 是‘坏人把脚本塞进页面内容，骗浏览器执行’，防御靠输出转义。一个打数据库、一个打浏览器，都要防。"}]},{"type":"mistakes","items":["错误案例①（AI 高频）：密码用明文存进数据库列 `password`。正确是 `password_hash` 且用 bcrypt/scrypt 加盐哈希。看到列名叫 password 就要警觉。","错误案例②（致命）：SQL 用字符串拼接——`SELECT * FROM users WHERE name = '` + input + `'`。坏人输入 `' OR '1'='1` 就能登录一切人。必须改成参数化：`WHERE name = $1`（PG）或 `?`（MySQL）。","错误案例③：用户表没有主键，或把‘用户名’当唯一标识——重名就会数据错乱。主键必须稳定唯一（通常用自增 id 或 UUID）。","错误案例④：前端校验当安全边界——‘我在前端限制了只能填数字’并不能挡住直接调接口的攻击者。真正的校验必须在后端。","错误案例⑤：把 token 存 localStorage 又不设过期、也不校验是不是当前用户——一旦 XSS 就能偷走凭证。安全要‘防御纵深’，别只做一层。"]},{"type":"deep","title":"深入一点：手把手判读一张 AI 建的‘用户表’和登录接口","beginner":["看一张 AI 生成的用户表，先问五件事：","**有没有主键？** 要有 id（或 UUID）作主键，能唯一稳定地定位记录。","**密码是不是哈希列？** 应该叫 password_hash / password_digest，用 bcrypt，绝不存明文。","**必填列有没有 NOT NULL？** 用户名、密码哈希不能为空。","**会不会被注入？** 查询语句是不是参数化的（用占位符而非拼接）？","**有没有做访问控制？** 比如‘只能读自己的数据’，而不是任何人传个 id 就能读到别人的。"],"advanced":["**合法但可以更好的设计**：除了基础列，常加 created_at/updated_at 时间戳（审计用）；经常按 username 查就加唯一索引 `UNIQUE(username)`；邮箱/手机号单独存或用正则后端校验。","**登录接口应返回什么**：成功后（201/200）返回凭证；密码错返回 401；账号不存在也返回 401（而不是 404，避免暴露‘这账号存在’）。失败要记日志，但日志里别打明文密码。","**一个可参考的 SQL 建表**：","```sql\nCREATE TABLE users (\n  id BIGSERIAL PRIMARY KEY,\n  username VARCHAR(50) NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n```","**登录校验（参数化防注入的示范）**：","```js\nconst row = await db.oneOrNone('SELECT * FROM users WHERE username=$1', [username]);\nconst ok = row && await bcrypt.compare(password, row.password_hash);\nif (!ok) return res.status(401).json({ ok:false, msg:'用户名或密码错误' });\n```","注意 `$1` 占位符 + `[username]` 参数数组 = 参数化，SQL 注入无从下手。"]},{"type":"ask","title":"怎么用 AI 帮你设计数据库和登录","scenario":"你做了一个‘用户能注册、能收藏文章’的小产品，想让 AI 一次性给出靠谱的表设计和登录方案。","template":"[产品场景] 用户注册登录后，可以收藏文章（一个用户可收藏多篇文章）。\n[请帮我设计] ①用户表与收藏表的结构（含主键、外键、索引）；②注册/登录后端代码，密码用 bcrypt 加盐哈希、SQL 用参数化防注入；③返回 401/201 等状态码。\n[验收标准] 请说明：主键是谁、外键怎么关联、密码如何存储、如何防 SQL 注入、登录凭证用 Session 还是 JWT 并说明理由。","acceptance":["表结构是否给出了主键、外键和需要加的索引？","密码是否明确用了 bcrypt 之类加盐哈希而非明文？","SQL 是否参数化（占位符）而非字符串拼接？","登录凭证方案是否说明了 Session/JWT 的选择及理由？是否覆盖成功与失败状态码？"],"tip":"涉及数据库和安全，务必让 AI 把‘为什么这么做’讲出来，而不能只给代码。你再用上面的‘五问’走一遍，就能当半个审查。"},{"type":"exercise","prompt":"你的登录接口被人用输入 `' OR '1'='1` 打穿了，任何密码都能登进去。这最可能是下面哪种代码导致的？","opts":["用 bcrypt 哈希密码","SQL 用了字符串拼接用户输入（未参数化）","给 username 加了唯一索引","登录返回了 401"],"a":1,"explain":"把用户输入直接拼进 SQL 会造成 SQL 注入——输入里含有的引号和 OR 让查询恒真，从而绕过密码。改成参数化查询即可堵住。","jump":"sec8","jumpLabel":"深入一点的 SQL 注入示范段"},{"type":"check","title":"结课检测：数据库与安全你真的懂了吗","intro":"共 5 题。全部答对可进入下一课。","questions":[{"q":"用户的‘收藏表’要关联用户和文章，最正规的做法的核心是？","opts":["把所有用户名和文章名塞进同一列","用外键 user_id 和 article_id 分别指向用户表、文章表的主键","每次复制一份用户表","收藏不存数据库"],"a":1,"explain":"用外键指向各自表的主键，才能表达‘哪个用户收藏了哪篇文章’的关系且不重复存储。","jump":"sec5-step3"},{"q":"密码正确的存储方式是？","opts":["明文存进 password 列","加密（可逆）后存","加盐哈希（如 bcrypt）后存，且不存明文","存进 cookie"],"a":2,"explain":"哈希是不可逆的，任何人不包括你自己都无法还原密码，只能用于比对；加盐防止相同密码产生相同哈希。","jump":"sec5-step4"},{"q":"SQL 注入的根本防御是？","opts":["在前端把输入框禁用","用参数化查询（占位符）","把数据库放到公网","把 SQL 写成大写字母"],"a":1,"explain":"参数化查询把用户输入当作数据而不是可执行的 SQL 代码，因此注入失效。","jump":"sec8"},{"q":"Session 与 JWT 的区别，哪句最准确？","opts":["Session 把状态存服务器，JWT 把身份信息加密进令牌交给客户端","两者完全一样","JWT 不能加密","Session 只用于 HTTPS"],"a":0,"explain":"Session 服务端有状态、可随时注销；JWT 无状态、令牌自证身份，适合多端，但签发后较难在过期前撤销。","jump":"sec6"},{"q":"别人的博客里嵌了你的登录页代码，结果是坏人代码执行——这属于用什么方式防御的问题？","opts":["SQL 注入","XSS 跨站脚本","数据库索引","密码哈希"],"a":1,"explain":"把脚本塞进页面内容让浏览器执行的是 XSS，防御靠输出转义 + CSP 等；这不是 SQL 注入（那是打数据库的）。","jump":"sec6"}],"done":"你现在能看懂表结构、能审 AI 的建表与登录代码、知道 Session/JWT/OAuth 怎么选、也知道 SQL 注入/XSS 怎么防。下一课我们把这一切真正‘送上线’：从本地 Demo 变成一台公网可访问、稳定可回滚的真实产品。","nextLesson":"v07-deploy"},{"type":"connection","known":["你知道后端通过 API 和数据库交互（上一课）。","你知道数据要长期保存、要按关系组织（本课）。"],"learned":["数据库用表组织数据：列、行、主键唯一、外键关联、索引加速","SQL 增删改查与参数化防注入","登录三方案：Session 存服务端 / JWT 自证令牌 / OAuth 第三方授权","安全四原则：密码哈希、SQL 参数化、输出转义、后端校验"],"next":"数据和身份都准备好了，下一步是把它们‘送上线’。这与 AI 路径的联系：当你要做的是 AI 产品（如 RAG 问答），RAG 的向量库也是一种‘数据库’，登录/安全同样适用。下一课《从本地 Demo 到正式上线》会把 部署、健康检查、回滚 讲透。","links":[{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——了解向量数据库在 AI 产品里的角色"},{"href":"#/lesson/l20-ai-eng","text":"回看 AI 路径《AI 工程：从原型到生产》(规划中)"}]}]},{"id":"v05-test","title":"测试与调试：让 bug 无处可藏","subtitle":"AI 写的代码‘看起来对’不代表真的对。测试就是给代码挂号看病：把你担心的每一种情况写成‘处方’，让机器自动反复验证。","course":"vibe","courseNo":"05","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":["testing","debugging","test-driven","error-handling"],"prereqLessons":["v04-db"],"nextLesson":"v06-arch","sections":[{"type":"opening","question":"AI 帮你写完功能，你点了一下‘看起来正常’。但这只证明‘这一种情况正常’。如果用户传了空值、超长文本、重复提交，或者网速很慢时呢？它会不会悄悄出错？","guess":"很多人把‘点一下没坏’当成‘没问题’，等上线后才被用户骂出 bug。","next":"这一课让你从‘靠感觉’升级到‘靠验证’：学会写测试，让机器替你一遍遍检查；学会高效调试，遇到 bug 能用工具精准定位而不是瞎猜。"},{"type":"why","before":"你用 AI 快速堆了很多功能，但每次改一处就怕另一处坏，全靠人工点来点去，又慢又容易漏。","problem":"没有测试时，回归风险（改这坏那）全靠人肉；bug 只在线上被用户撞到；调试时踢‘玄学’，分不清是前端、后端还是数据。","need":"你需要一套‘自动验证’体系：把正常/极限/出错的情况固化成测试，任何改动跑一遍就知道坏没坏；再加一套科学的调试流程，快速锁定问题根因。"},{"type":"oneline","text":"测试 = 用代码检查代码：把你关心的输入和期望输出写成断言，让程序自动运行并告诉我们‘通过’还是‘失败’；调试 = 当失败发生时，用日志、断点、报错信息逐层缩小范围，找到并修掉根因，再补一条测试防止它复发。"},{"type":"visual","kind":"http-viewer","title":"互动实验：把一次请求拆开‘调试’","hint":"查看一次请求的完整信息（请求方法/参数/状态码/响应体）。当功能表现不对时，先看请求对不对、状态码对不对、响应对不对——绝大多数 bug 都能在这一层现行。"},{"type":"intuition","blocks":[{"k":"用医生体检来想","t":"测试就像定期体检：你不是‘感觉健康’，而是用仪器（测试用例）一项项量。体检结果红灯/绿灯，告诉你哪里该治。改完代码再‘体检’一次，确认没有新问题（回归）。"},{"k":"用过安检来想","t":"每次上线前，测试就是‘安检门’：正常行李、液体、打火机、可疑物品各走一遍（边界与异常用例）。安检没拦下问题，才会漏到线上。"},{"k":"一句话记住","t":"测试管‘它该不该错’（验证正确性），调试管‘它为什么错’（找根因）。两者配套：写了测试的 bug 更好调，调完的 bug 最好补测试防复发。"}]},{"type":"how","intro":"科学调试 + 自动测试的完整闭环，六步。","steps":[{"in":"① 复现：先让它稳定地出错","process":"调试第一步是把 bug 稳定复现——找出输入、操作、环境的组合。‘偶现’的 bug 最难调，先尽量锁定触发条件。","out":"一个能稳定触发问题的操作路径"},{"in":"② 读报错：从报错和日志定位层","process":"查看报错来自哪一层（前端控制台/后端终端/数据库）。报错信息 + 堆栈 + 日志是缩小范围的雷达。","out":"判断问题最可能在哪一层、哪个文件哪一行"},{"in":"③ 缩小范围：二分法 / 断点","process":"在可疑处打断点或加日志，看变量值是否符合预期。用二分法：先确认一半流程没问题，再把怀疑区切半，快速收敛。","out":"定位到具体的错误代码位置"},{"in":"④ 修复 + 写一条测试","process":"修掉根因（不是表面掩盖），然后写一个能复现此 bug 的测试用例，确保以后不会再犯（回归测试）。","out":"修复完成，且有测试保驾护航"},{"in":"⑤ 跑测试套件","process":"运行整套测试，确认修复没弄坏别的地方。测试套件就是你的‘回归安检门’。","out":"红灯/绿灯：全部通过则放心，有红灯继续修"},{"in":"⑥ 交给 AI 辅助：带着上下文提问","process":"把‘复现步骤 + 报错 + 相关代码 + 我试过的’交给 AI，让它给假设与修复建议；你验证后再落地。","out":"更快地解决复杂疑难 bug"}]},{"type":"realworld","items":[{"name":"单元测试（最小函数）","note":"测一个函数/一个输入输出对：‘输入 3 和 4，应当返回 7’。粒度最小、跑得最快、最稳。"},{"name":"集成测试（多个模块配合）","note":"测‘后端接口读数据库再返回正确结构’这种跨模块流程，确认各部分协作正确。"},{"name":"端到端测试（模拟真实用户）","note":"自动开浏览器，模拟用户点按钮、填表单、走完整流程，确认产品级行为正常。"},{"name":"让 AI 帮你写测试","note":"把函数/接口描述给 AI，让它生成覆盖正常、边界、异常的测试用例。再由你补充‘你的产品里最怕坏的那几条’。"}]},{"type":"compare","pairs":[{"a":"单元测试","b":"端到端测试","diff":"单元测试只测单个小函数，快而稳；端到端测试模拟整个真实流程，覆盖广而慢。两者互补，前者定位快，后者保整体。"},{"a":"调试","b":"测试","diff":"调试是当下找并修现有 bug 的根因；测试是把‘该对的不变错’固化成自动化验证，防止未来回归。调试解决‘现在’，测试守住‘以后’。"},{"a":"人肉点验","b":"自动化测试","diff":"人肉点验靠眼、易漏、难重复；自动化测试靠代码、可重复、可长时间回归。AI 时代的快节奏尤其需要自动化兜底。"},{"a":"掩耳修 bug","b":"修根因","diff":"表面掩盖（如删掉报错）下个输入还会炸；修根因 + 补测试才是一劳永逸。"}]},{"type":"mistakes","items":["只测‘正常情况’，不测空值/超长/重复/超时等边界——线上都是在边界炸的。","改完代码不重跑测试——回归 bug 悄悄溜回去。","看到报错就贴给 AI，不先自己读——先定位‘哪一层、哪个文件’，AI 才能精准。","写测试只求‘通过’不求‘有意义’——骗过自己的测试没有价值。","把 .env 密码打进日志——泄露风险大于 bug 本身。"]},{"type":"ask","title":"怎么用 AI 帮你调试：给足四件套","scenario":"你的接口偶尔返回错误，你想让 AI 帮你定位。","template":"[现象] 点击保存后约 20% 概率报 500 错误，多数时候正常。\n[复现] 连续快速点两次保存，必现。\n[报错] 后端日志：TypeError: Cannot read properties of undefined (reading 'id') at line 88.\n[我试过] 单次保存正常；怀疑是重复提交/竞态导致请求对象未就绪。\n[请给我] 判断根因最可能是什么，并给出修复 + 回归测试方案。","acceptance":["AI 是否先确认了复现条件与报错层级？","是否给出根因判断而非简单贴代码？","是否提供修复 + 一条防复发的测试？","是否提醒测试边界（重复提交/空值）？"],"tip":"调试提问的黄金四件套：现象 + 复现 + 报错 + 我试过的。越具体，AI 越能帮你一击命中。"},{"type":"exercise","prompt":"你的功能‘在本地点一下没问题’，但你最担心上线后被用户遇到奇怪输入就崩。下面哪个做法最能防患于未然？","opts":["相信 AI 写的没问题，不测","补上正常/边界/异常的自动化测试，并在每次改动后重跑","只在发布当天人工多点点","把报错用 try-catch 吞掉不上报"],"a":1,"explain":"把担心的情况固化成自动化测试（正常/边界/异常）并持续回归，才是防患于未然的正道；try-catch 吞错只会掩盖问题。","jump":"sec5-step4","jumpLabel":"补测试防复发这一步步"},{"type":"check","title":"结课检测：你会给代码看病了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回对应段落复习。","questions":[{"q":"‘回归测试’主要为了防止什么？","opts":["新增功能太少","改了这处却弄坏了之前能用的功能","代码写了注释","部署变慢"],"a":1,"explain":"回归测试是在每次改动后重跑，确保‘不该变错’的旧功能没被新改动弄坏。","jump":"sec5-step4"},{"q":"调试一个‘偶发’bug 的第一步是什么？","opts":["直接重写整个模块","先想办法稳定复现它，锁定触发条件","立刻上线再观察","删掉报错"],"a":1,"explain":"先稳定复现并锁定触发条件，才能进一步定位；偶发 bug 最难调，复现是第一步。","jump":"sec5-step0"},{"q":"下面哪一类测试粒度最小、跑得最快？","opts":["端到端测试","单元测试","集成测试","人工测试"],"a":1,"explain":"单元测试只测单个小函数，粒度最小、最快最稳；端到端最慢。","jump":"sec6"},{"q":"把 bug 交个 AI 之前，最有效的准备是？","opts":["只发一句‘它坏了帮我修’","提供现象 + 复现步骤 + 报错 + 我试过的","什么都不说让 AI 猜","先删掉相关代码"],"a":1,"explain":"四件套（现象/复现/报错/已试过）让 AI 快速定位根因，避免无效往返。","jump":"sec7"}],"done":"你现在既能用测试预防 bug，又能用科学流程调试 bug，还能让 AI 高效地帮你。下一课把目光放回代码本身：怎么组织项目结构，让一开头乱成一团的代码变得清晰可维护。","nextLesson":"v06-arch"},{"type":"connection","known":["你已了解后端 API、数据库（v03/v04）与分层思想（v01）"],"learned":["测试 = 自动验证正确性；调试 = 定位并修根因，两者互补","复现→定位→修复→补测试→回归的科学调试闭环","单元/集成/端到端测试的区别与分工","给 AI 调试提问的黄金四件套"],"next":"测试守住质量底线，下一步我们要管好代码本身的结构：让工程量变大时依然清晰、好扩展、好维护。","links":[{"href":"#/lesson/v06-arch","text":"下一课：《项目结构与代码组织》"},{"href":"#/lesson/v04-db","text":"回看《数据库、登录与安全》"}]}]},{"id":"v06-arch","title":"项目结构与代码组织","subtitle":"AI 会把所有代码一股脑塞进一两个文件。功能少时没事，功能一多就变成没人敢动的‘意大利面’。这节课教你给项目‘装修’，让它清晰、好扩展、好维护。","course":"vibe","courseNo":"06","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":["project-structure","code-organization","modularity","refactoring"],"prereqLessons":["v05-test"],"nextLesson":"v07-deploy","sections":[{"type":"opening","question":"你的项目从 2 个文件长到了 20 个文件。现在你想加一个‘分享’功能，却要改 6 个文件，每改一处都怕碰坏别处。AI 也越帮越乱——它不知道你的项目现在长什么样。","guess":"很多人选择‘忍’，或者干脆重写一个更乱的项目。","next":"这一课教你如何规划项目结构：怎么分文件夹、怎么分层、怎么拆分组件，让代码像整理好的衣橱一样‘东西各有其位’。结构清晰，AI 才能准确帮你改，你才不会改一处崩三处。"},{"type":"why","before":"你在 Vibe Coding 里让 AI 快速堆功能，很快发现文件多、职责乱、命名随意，连你都不敢轻易动。","problem":"结构混乱的代价：改一处崩三处、加功能要动一堆文件、AI 因为看不懂全貌而瞎改、你无法确认改动影响面。","need":"你需要一个清晰的项目骨架：明确的分层、职责单一的模块、合理的命名与目录。这样无论是你还是 AI，都能‘小范围定位、大胆改动、放心验证’。"},{"type":"oneline","text":"好的项目结构 = 按‘职责’而不是‘随意’组织的代码摆放：前端/后端/数据分层清晰，每个模块只做一件事，文件命名即职责，改动影响面小、可测试、可替换。它是让‘小项目’能长大成‘可维护产品’的地基。"},{"type":"intuition","blocks":[{"k":"用整理衣柜来想","t":"衣柜分格：上衣一格、裤子一格、袜子一格，找衣服（找代码）快、放回去不乱。如果把所有衣服扔进一个大抽屉（一个 giant 文件），找什么都翻半天，还容易拿错。"},{"k":"用餐厅分工来想","t":"一个好的餐厅有明确分工：前台点单、后厨做菜、仓库备料、财务算账，各司其职。一个烂餐厅‘一个人啥都干’，热闹时必崩。代码分层同理：页面只管展示，逻辑只管处理，数据只管存取。"},{"k":"一句话记住","t":"‘职责单一 + 分层清晰 + 命名即职责’。看到文件名就知道它管什么；改一个功能只动最少文件。这就是可维护性的全部秘密。"}]},{"type":"how","intro":"从混乱到清晰的三步整理法。","steps":[{"in":"① 按层分目录（横向分层）","process":"按‘类型/职责’分开：前端代码、后端代码、数据库相关、配置、测试、静态资源各放各目录。例：src/、api/、db/、tests/、config/、public/。","out":"横向分层清晰，一眼看懂项目由哪几块组成"},{"in":"② 按功能分模块（纵向拆块）","process":"在一个层内部再按功能拆分：比如‘用户’、‘订单’、‘分享’各自成模块，模块内部再包含自己的逻辑/子文件。一个文件只负责一个功能点。","out":"纵向模块化，加功能影响面收窄到单一模块"},{"in":"③ 命名即职责 + 收敛公共部分","process":"文件/函数命名说清职责（userService.js 管用户逻辑、db.js 管连接）。把重复出现的代码抽成公共函数，避免复制粘贴三遍。","out":"可读性提升，改动点集中，易于测试与替换"},{"in":"④ 找 AI 重构（带着结构上下文）","process":"把‘当前目录结构 + 你要的目标结构/问题’给 AI，让它帮你拆分、抽取、重命名。分小步做，每步后跑测试验证。","out":"借助 AI 快速完成结构整理且不破坏功能"}]},{"type":"realworld","items":[{"name":"前后端分离","note":"前端代码和后端服务分开目录（甚至分开仓库/部署），职责完全不同，各自独立演化与测试。"},{"name":"一个文件只做一件事","note":"giant 文件是最大的敌人：几百行的单一文件难读难测难改。拆成职责清晰的小文件/函数。"},{"name":"配置与代码分离","note":"数据库地址、密钥、端口等‘环境相关’配置放 config 或环境变量，别硬编码进代码，便于本地/线上切换。"},{"name":"测试与源码平行","note":"测试文件和被测代码放在对应/平行的目录，改动时容易同步维护。结构清晰才能让‘改这里测那里’成为日常。"}]},{"type":"compare","pairs":[{"a":"扁平大文件","b":"分层分模块","diff":"扁平把所有逻辑塞一起，难读难测；分层次、分模块按职责归位，定位快、影响面小。"},{"a":"复制粘贴复用","b":"抽取公共函数","diff":"复制粘贴三遍，改一处要改三处且易漏；抽成公共函数单点维护，一处改动全局生效。"},{"a":"随意命名","b":"命名即职责","diff":"随意命名（a/b/temp）看不懂；命名即职责（saveUser）看到名字就知道干什么、改哪找哪。"},{"a":"硬编码配置","b":"配置分离","diff":"硬编码密钥/地址难切换且易泄露；配置分离便于本地/线上切换与安全。"}]},{"type":"mistakes","items":["把所有代码塞进一个 main 文件——看一眼就头大，AI 也会改错。","不设目录分层，东放一个西放一个——找不到文件该在哪。","命名随意（a/b/test12）——神仙也看不懂。","一个函数干八件事——难测难调。职责单一才可测。","重构一上来就大动干戈——高风险。小步重构 + 每步测试，才稳。"]},{"type":"ask","title":"怎么用 AI 帮你整理结构：把当前全貌给出去","scenario":"你的项目文件越来越乱，想请 AI 帮你重构组织。","template":"[现状] 我的项目目前文件都在根目录：main.js（约 300 行）、utils.js、data-handler.js… 没有分目录。\n[目标] 我想整理成前端/后端/配置/测试分层的清晰结构，并让每个文件职责单一。\n[约束] 不能破坏现有功能，我有测试可以验证；请分小步提出重构方案，每一步不要动太多。\n[请给我] 先给出目标目录结构与分工建议，再给按小步执行的拆分清单。","acceptance":["AI 是否先了解现有结构再动手？","是否给出分层/模块化的目标结构，而不只是‘把文件挪一挪’？","是否建议小步重构 + 测试验证，避免一次性大动？","是否提醒命名即职责、公共部分收敛？"],"tip":"把‘当前结构 + 目标 + 约束（不能坏、有测试）+ 请小步’交给 AI，它会给你靠谱的重构方案。别让它‘直接重构’，要先给方案。"},{"type":"exercise","prompt":"你的项目所有逻辑都挤在一个 400 行的 main.js 里，想让它便于维护。下面哪个做法是正确第一步？","opts":["一次性把 400 行全部重写成多个文件再跑","先按职责切分，小步把一块块功能抽到独立模块，并保持每次都还能跑 + 测试通过","继续加在一个文件里，方便 AI 找","删掉重写"],"a":1,"explain":"正确做法是小步按职责拆分，每拆一块仍能跑、测试仍过，逐步收敛；一次性大重写风险极高。","jump":"sec5-step3","jumpLabel":"找 AI 重构这一步步"},{"type":"check","title":"结课检测：你会给项目‘装修’了吗","intro":"共 4 题。全部答对可进入下一课。答错会带你回对应段落复习。","questions":[{"q":"项目结构清晰的主要好处是？","opts":["代码变少了","改动影响面小、定位快、易测试易维护","运行更快","AI 不需要了"],"a":1,"explain":"结构清晰的本质是降低‘改动成本与风险’：定位快、影响面小、可测、可维护。","jump":"sec5-step0"},{"q":"下面哪个符合‘职责单一’？","opts":["一个函数既渲染页面又查数据库还保存文件","一个模块只负责一件事：比如用户模块只管用户","把所有逻辑写一个函数里","一个文件放所有样式和逻辑"],"a":1,"explain":"职责单一 = 每块代码只做一件清楚的事，这样才好测、好改、好复用。","jump":"sec5-step2"},{"q":"数据库地址、密钥这类配置应该放在哪里？","opts":["硬编码写死在代码里","放在 config/环境变量，与代码分离","放到前端页面","写进提交日志"],"a":1,"explain":"环境相关配置应与代码分离（config/环境变量）：便于本地/线上切换，也避免密钥泄露到代码与仓库。","jump":"sec6"},{"q":"重复出现三遍的同一段代码，最好怎么处理？","opts":["继续复制粘贴","抽成一个公共函数，单点维护","每次都重写一遍","交给 AI 不管"],"a":1,"explain":"抽成公共函数，一处改动全局生效，避免三处不同步的隐患。","jump":"sec5-step2"}],"done":"你的项目从‘意大利面’变成了‘有格子的衣橱’，自己和 AI 都能快速定位、安心改动。最后一关：怎么把这套东西从你电脑搬到真正的线上服务器，让全世界都能访问。","nextLesson":"v07-deploy"},{"type":"connection","known":["你已了解分层（v01）、后端 API（v03）、数据库（v04）、测试（v05）"],"learned":["结构清晰 = 职责单一 + 分层模块化 + 命名即职责","从混乱到清晰的整理法：分层→分模块→命名/收敛公共→AI 辅助小步重构","前后端分离、配置分离、测试平行摆放","小步重构 + 测试验证的原则"],"next":"结构理清了，最后一步就是把它送上线：怎么从‘本地能跑’变成‘人人能访问’。部署是 Vibe 路径的临门一脚。","links":[{"href":"#/lesson/v07-deploy","text":"下一课：《从本地 Demo 到正式上线》"},{"href":"#/lesson/v05-test","text":"回看《测试与调试》"}]}]},{"id":"v07-deploy","title":"从本地 Demo 到正式上线","subtitle":"代码在你自己电脑上能跑，不算数；让全世界都能访问、且挂了能快速恢复，才是‘上线’。这一课讲清楚那条从 localhost 到公网的最后一公里。","course":"vibe","courseNo":"07","level":"base","estTime":"15-25 分钟","difficulty":2,"concepts":[],"prereqLessons":["v01-web","v03-api","v04-db"],"nextLesson":"v08-workflow","sections":[{"type":"opening","question":"你的产品在自己电脑上跑得欢，你联调、测试都通过了。现在要把它放到公网，让外地、外网、别家浏览器都能访问——为什么这件事永远比想象中麻烦？常见的‘本地正常、线上挂掉’到底差在哪？","guess":"很多人以为‘上线就是把文件传到服务器上，然后就能用了’。","next":"这一课我们拆解上线全流程：环境如何保持一致（环境变量）、如何把项目部署到服务器/云平台、域名与 HTTPS 怎么配、上线后怎么确认它是‘健康的’（健康检查）、出问题怎么快速回滚、以及要不要上 CI/CD。学完后你拥有的能力是：把 AI 做的 Demo 安全地变成可上线产品，并知道每一步万一失败该怎么退回来。"},{"type":"why","before":"你写好了产品，AI 也说‘好了，部署吧’。可你一部署，报‘连接数据库失败’‘端口被占用’‘找不到 .env’‘静态资源 404’……你完全不知道从哪查起，只能一遍遍粘日志给 AI，反复重装环境。","problem":"本地与线上天然不同：路径不同、数据库地址不同、端口不同、依赖版本可能不同、还要面对公网连接、域名、HTTPS 证书、防火墙。如果你没有‘环境一致性’与‘可回滚’的意识，即使这次勉强跑起来，下次改动也会随时把线上搞挂而无法恢复。","need":"掌握上线的最小可靠流程：用环境变量（.env）把差异集中管理；部署常走三大路径（静态托管 / PaaS 平台 / 自管服务器）分别怎么选；配域名 + HTTPS；加‘健康检查’让系统自己喊救命；上线清单与回滚流程让‘挂了也能退回去’。这是把 Demo 变成产品的临门一脚。"},{"type":"oneline","text":"上线 = 把代码 + 环境一致地搬上公网机器 + 配好域名/HTTPS + 挂上健康检查 + 准备好一键回滚。核心三句话：环境用变量隔离差异（不同环境不同值）、部署用脚本/平台保证可重复（别靠手敲）、发布用‘灰度/可回滚’控制风险（挂了能退）。"},{"type":"visual","kind":"deploy-console","title":"互动实验：部署控制台，看一次完整上线","hint":"这是一个模拟部署终端：点‘部署’会经历 构建 → 迁移 → 健康检查 → 流量切换；如果健康检查失败，系统会拒绝放量并自动回滚到上一个版本。你还能故意制造‘健康检查失败’来亲眼看到回滚是怎么保命的。"},{"type":"intuition","blocks":[{"k":"用开餐厅来想","t":"本地 Demo 像在你的厨房试菜——火候是你自己调好的、食材在你冰箱里。上线＝在商业街上开正式的餐厅：要租店面（服务器）、接水电气（网络/HTTPS）、换统一采购的食材（数据库搬到线上）、店员按标准作业（健康检查/监控）、万一某天厨房着火（服务挂）要能立刻换上备用后厨（回滚/容灾）。‘本地试菜’和‘正式营业’根本不是一回事。"},{"k":"用电梯/红绿灯来想健康检查","t":"健康检查＝系统自己定时喊一嗓子‘我还活着’（探测 /health 接口）。就像电梯每隔几秒报一次运行状态。如果它不喊了，编排系统（如负载均衡）就把它踢出队伍并拉起一个新的——而不是让用户对着白屏干等。"},{"k":"一句话记住上线","t":"环境变量隔离差异 → 构建产物可重复 → 部署到线上 → 健康检查确认活着 → 出问题回滚上个版本。五个动作，缺一不可；其中‘能回滚’是你最后的保险绳。"}]},{"type":"visual","kind":"llm-retry","title":"互动实验：给 LLM 调用加上超时 + 重试 + 回退","hint":"你的产品里调了大模型 API（这也是你 AI 产品的‘后厨’）。网络抖动/超时/限流在线上是家常便饭。这个实验模拟‘调用 → 超时 → 重试 → 回退(fallback)’，体会电商级 API 调用为什么要设计超时与降级。这也是 Vibe Coding 路径与 AI 路径的连接点。"},{"type":"how","intro":"把一次‘安全上线’拆成 6 步：每一步都有明确的‘成功标志’和‘失败补救’。","steps":[{"in":"① 环境变量：把差异抽出来","process":"本地/测试/线上需要不同的数据库地址、密钥、端口。把它们写进环境变量（如 .env 文件或平台面板），代码里用 process.env.XXX（Node）/ os.environ（Python）读取，而不是写死。","out":"代码与环境解耦：同一份代码换环境即可"},{"in":"② 构建 + 迁移","process":"前端打包成静态文件（npm run build → dist/）；数据库结构变化用迁移脚本（migration）跑一遍。构建产物要是‘可重复’的——同一份源码应产出同样的产物。","out":"得到一个可直接发布的‘构建物’+ 数据库就绪"},{"in":"③ 部署到线上","process":"三大路径：静态托管（页面纯前端，丢到 GitHub Pages/CF Pages/OSS 即可）；PaaS 平台（Vercel/Netlify/Railway/Render，把代码推送即可自动部署，适合新手与中等项目）；自管服务器（买 ECS/VPS，自己配 Nginx + 进程守护如 PM2/systemd）。新手从 PaaS 起步最稳。","out":"公网可以访问你的服务"},{"in":"④ 域名 + HTTPS","process":"买个域名，把 DNS 解析到你的服务（A 记录指向 IP / CNAME 指向平台）；再签 HTTPS 证书（平台自动，或云厂商+Letʼs Encrypt），让访问走 https:// 加密。浏览器地址栏的小锁 = 加密。","out":"用户通过好记的 https://你的域名 访问"},{"in":"⑤ 健康检查 + 监控","process":"后端提供 /health 接口（返回 200 + 状态）。负载均衡/编排平台每 X 秒探测它：活着→正常放量；不活→摘除并重启该实例，同时报给你（监控告警）。","out":"系统自己‘喊救命’，而不是等用户来报"},{"in":"⑥ 发布即回滚预案","process":"大型发布用‘灰度’：先 10% 流量验证，稳妥再全量；每版都保留上一个版本，发现异常立刻一键回滚（切回旧版本）。回滚能力 = 你改线上时的底气。","out":"即使新版本有问题，也可在几分钟内恢复"}]},{"type":"realworld","items":[{"name":"GitHub Pages（本站就是这么上线的）","note":"纯前端静态站可直接推到 GitHub Pages，免费公网、自带 HTTPS。适合‘文档/演示/静态首页’。注意它只托管静态资源，没有后端/数据库——需要后端的要另选 PaaS 或 VPS。"},{"name":"Vercel / Render / Railway（PaaS）","note":"‘连上 Git 仓库，push 即部署’：自动构建、自动 HTTPS、给环境变量面板、自动健康检查与回滚。是前端+轻后端产品（含 Next.js 全栈）最省心的上线方式。"},{"name":"云服务器 + 进程守护（VPS）","note":"腾讯云/阿里云的 ECS 上装 Node/Python、用 PM2/systemd 守护进程、Nginx 反代 + HTTPS。灵活可控但维护成本高。适合要自己掌控环境、或者后端较重/要连自己数据库的产品。"},{"name":"CI/CD（持续集成/持续部署）","note":"把‘测试 → 构建 → 部署’做成流水线：你 push 代码，系统自动跑测试并部署。好处是上线行为可重复、可审计；新手至少理解它的存在，平滑后再引入 (如 GitHub Actions)。"}]},{"type":"compare","pairs":[{"a":"静态托管（GitHub Pages/OSS）","b":"PaaS 平台（Vercel/Render）","diff":"静态托管只能放纯前端静态文件、无后端、一般免费；PaaS 能托管前端+后端（有的带数据库），源码推送自动构建/部署/HTTPS，更适合‘有后端的完整产品’。纯静态选前者，有后端选后者。"},{"a":"PaaS 平台","b":"自管云服务器（VPS+PM2+Nginx）","diff":"PaaS 帮你管环境、自动部署、内置回滚，省心但灵活度有限；VPS 完全可控（能装任意软件）但要自己维护系统、进程守护、HTTPS、备份，运维成本高。新手/中小产品从 PaaS 起步，要深度控制再上 VPS。"},{"a":"环境变量 .env","b":"写死在代码里","diff":"环境变量让同一份代码在不同环境（本地/测试/线上）用不同配置，且密钥不进代码库；写死会导致‘本地行、线上不行’，且密钥泄露风险大。必须用环境变量管理差异与密钥。"},{"a":"健康检查 /health","b":"用户报错才知道挂了","diff":"健康检查是主动、自动、秒级的探活，挂了立刻摘除重启并告警；等用户报告则被动、慢、伤口碑。生产环境必须有健康检查。"}]},{"type":"mistakes","items":["错误案例①：把数据库连接串、API 密钥写死在代码/前端里并 push 到公开仓库——等于把保险柜密码贴在门口。密钥必须进环境变量并严格保密。","错误案例②：没有环境意识，‘本地跑通了就认为线上能跑’。正确的验证方式：线上部署后跑一遍健康检查 + 真实浏览器访问，而不是‘本地 200 就完事’。","错误案例③：上线直接改线上数据库结构却不做迁移回滚——出事退不回去。数据库结构变更要保留迁移脚本、可逆可回退。","错误案例④：追逐‘最新框架/功能’把线上当实验场，改一次崩一次却没有任何回滚按钮。生产稳定 > 炫技；改版前后都要有一键回滚能力。","错误案例⑤：把‘调大模型 API’当成不会失败——线上网络抖动、超时、限流很常见。不给 API 调用加超时/重试/回退(fallback) 的 AI 功能，用户会频繁看到转圈/报错。"]},{"type":"deep","title":"深入一点：一次失败的线上事故是怎么被救回来的","beginner":["把‘回滚像不像重装系统’想明白：回滚不是把线上机器清空重装，而是‘把流量切回上一个已知良好的版本镜像/构建物’。现代平台（PaaS、容器编排）都保留旧版本，一键切换即可，秒级恢复。","健康检查的 /health 接口长什么样？就是一个后端路由，返回 200 和一个简单的 JSON：`{status:'ok'}`。它常常还会顺带检查数据库能否连上。如果数据库挂了，/health 也会返回失败——这样编排系统才会判断这台机器‘不健康’并把它踢出去。"],"advanced":["**一次事故的完整剧本**：新版本把数据库连接串写错 → 部署平台探测 /health → 数据库连不上 → /health 返回 500 → 平台判定‘不健康’→ 拒绝放量 / 自动回滚到旧版本 → 监控告警发到你手机 → 你看日志定位到环境变量拼错 → 修正后重新部署。全程用户几乎无感知。这就是‘健康检查 + 回滚 + 监控’三件套的价值。","**LLM 调用的可靠性设计（与 AI 路径的接口）**：真实产品调大模型 API 时，用模式是‘超时 + 指数退避重试 + 回退（缓存结果 / 备用模型 / 返回友好提示）’：","```js\nconst response = await fetchLLMWithRetry({\n  prompt, timeoutMs: 8000,            // 超时：8 秒没回应就放弃重试\n  retries: 3, backoffMs: 1000,         // 重试 3 次，指数退避\n  fallback: () => cache.get(key)       // 兜底：用缓存或降级文案\n});\n```","**上线检查清单（Checklist）**：①环境变量配全了吗？②数据库迁移跑了吗？③HTTPS 生效了吗（浏览器锁）？④/health 探针过吗？⑤日志与告警接了吗？⑥旧版本能一键回滚吗？⑦真实浏览器/多设备验证了吗？全部打勾，才算一次‘可上线发布’。"]},{"type":"ask","title":"怎么让 AI 帮你安全上线","scenario":"你的产品要第一次上线，不确定从哪下手、怕把线上搞挂。","template":"[我的产品] 是一个 [前端 + Node 后端 + PostgreSQL] 的小产品，目前只在本地能跑。\n[请给我] 一份最小可靠的上线方案：推荐用哪种托管方式（静态/PaaS/VPS）并说明理由；列出需要的环境变量清单；给出数据库迁移与开启 HTTPS 的步骤；提供 /health 接口示例与回滚预案。\n[验收标准] 每一步是否有明确操作与验证方法？是否包含失败时的回滚步骤？","acceptance":["部署方案是否说明了选型理由（静态/PaaS/VPS）与本产品的适配性？","环境变量清单是否完整且不包含明文密钥？","是否提供了可复现的部署步骤与验证方式（健康检查/浏览器访问）？","是否有明确的回滚/恢复预案，而不是‘挂了重装’？先小范围(灰度)验证再全量了吗？"],"tip":"上线是最不能‘赌一把’的环节。让 AI 给出‘选型 + 环境变量 + 验证 + 回滚’全套，再逐项打勾验收；任何一步读不懂就让 AI 解释‘为什么这样做’，直到你能复述为止。"},{"type":"exercise","prompt":"你上线了新版本，负载均衡探测 /health 连续几次都返回 500。接下来最正确的自动动作是什么？","opts":["继续放大流量，等用户反馈","把该实例摘除并自动回滚到上一个良好版本","重启浏览器","删掉数据库"],"a":1,"explain":"健康检查失败说明新版不健康，应把它踢出流量并回滚到上一版本，让用户在无感知的情况下继续使用。","jump":"sec7-step4","jumpLabel":"第 ⑤ 步：健康检查 + 监控"},{"type":"check","title":"结课检测：你的上线观念成立了吗","intro":"共 5 题。全部答对可进入下一节后续课程（或视为完成本路径第一批）。","questions":[{"q":"‘本地跑通 = 线上一定能跑’这句话？","opts":["完全正确","错误，本地与线上环境(变量/依赖/数据库)常不同，需部署后验证","只对前端成立","只对数据库成立"],"a":1,"explain":"环境差异（连接串、密钥、依赖版本、端口）是‘本地行、线上挂’的常见原因，必须部署后做健康检查与真实访问验证。","jump":"sec4"},{"q":"数据库地址、API 密钥这类差异应当怎么管？","opts":["写死在代码里方便","放进环境变量按环境区分，且密钥不进代码库","藏在注释里","放前端页面里"],"a":1,"explain":"环境变量让同一代码适应不同环境、密钥不进仓库，安全且可维护。","jump":"sec5-step0"},{"q":"完全不会写代码、只想让前端+后端都能自动上线，最省心的选项是？","opts":["自建机房","PaaS 平台（如 Vercel/Render），连 Git push 即部署","用纯记事本手写服务器脚本","不部署"],"a":1,"explain":"PaaS 负责构建、部署、HTTPS、健康检查与回滚，对新手最友好；VPS 更适合要深度控制的高级场景。","jump":"sec7"},{"q":"/health 健康检查的探测失败时，编排系统最合理的动作是？","opts":["什么都不做","摘除不健康实例并重启/拉起新的，必要时候选回滚","把数据库清空","关掉域名"],"a":1,"explain":"自动摘除+重启，必要时回滚旧版本，让用户几乎无感知；同时告警提醒你排查。","jump":"sec7-step4"},{"q":"调用大模型 API 时，‘超时 + 重试 + 回退(fallback)’组合主要防范什么？","opts":["防止代码有语法错误","线上网络抖动、超时、限流导致的偶发失败","防止数据库被删","防止前端样式错乱"],"a":1,"explain":"线上第三方 API 偶发失败是常态，超时避免无限等待、重试提高成功率、回退(缓存/备用/友好提示)兜底，保证用户体验不崩。","jump":"sec7"}],"done":"你已经掌握了从 localhost 到公网‘最后一百米’的全部关键：环境变量隔离、部署三路径选型、域名+HTTPS、健康检查、回滚预案、上线清单。Vibe Coding 第一批四门课到此收官——你已经能看懂代码结构、判断接口与数据库靠不靠谱、把 Demo 安全上线了。","nextLesson":""},{"type":"connection","known":["你知道一个 Web 产品如何分层（课1）、前后端怎么通信（课3）、数据怎么存与登录安全（课4）。","你会调大模型 API / 了解 RAG、Agent（AI 路径）。"],"learned":["环境变量隔离本地/测试/线上差异，密钥不进代码库","部署三路径：静态托管 / PaaS / 自管 VPS，以及各自适用场景","域名 + HTTPS（浏览器小锁）怎么配","健康检查(/health)探活 + 监控告警，挂了自动摘除","灰度 + 一键回滚 = 改线上时的底气；上线检查清单"],"next":"Vibe Coding 第一批四个环节到此闭环：看懂 → 懂接口 → 懂数据/安全 → 懂上线。下一步安排：第二批课程将覆盖 前端与语言基础（课2）、终端与 Git（课5）、存储缓存与测试排错（课6）、系统设计与 AI 产品工程（课8）。与本路径之外的联系：AI 产品的上线同样遵循本课原则，且多了‘LLM 调用可靠性’（超时/重试/回退）这一环——已在课 7 实验里有真机感受。","links":[{"href":"#/lesson/l00-ai-world","text":"回看 AI 路径《一张图看懂整个 AI 世界》"},{"href":"#/lesson/l-rag","text":"回看 AI 路径《RAG：让模型先查资料再回答》——AI 产品上线的数据侧"},{"href":"#/lesson/l-agent","text":"回看 AI 路径《Agent：让 AI 自己动手做事》——Agent 产品化时的可靠性思考"}]}]},{"id":"v08-workflow","title":"用 AI 完整做一个产品：全流程实战","subtitle":"前面七课把每一块都讲透了。这一课把它们串成一场完整实战：从一句话想法开始，走完立项、搭建、版本、联调、测试、部署，最终上线一个能给朋友用的真产品。","course":"vibe","courseNo":"08","level":"pro","estTime":"25-40 分钟","difficulty":3,"concepts":["full-workflow","product-launch","vibe-coding","mdv"],"prereqLessons":["v07-deploy"],"nextLesson":"","sections":[{"type":"opening","question":"你学完了：Web 链路、Git、API、数据库、测试、结构、部署。现在你把七块拼起来，用 AI 从零做一个真产品——比如‘家庭记账本’。你心里有完整的路线图，但你知道第一步该做什么、每一步怎么验收、在哪里最容易翻车吗？","guess":"很多人学完每课都很手痒，但真开始就面临‘从哪入手、怎么保证不烂尾、怎么保证上线安全’三大问题。","next":"这一课是收官实战：给你一套可直接照做的‘从想法到上线’端到端清单，串起前七课的全部能力。做完这课，你就是真正‘用 AI 独立做一个上线产品’的人了。"},{"type":"why","before":"你各环节都会一点，但没试过‘一口气走完全程’，担心翻车、烂尾、不知道每步到什么程度算 OK。","problem":"做一个真产品和做 demo 的区别：要能经受真实用户、真实数据、真实安全与真实故障。缺一个可照做的端到端流程，就容易卡在某一环或上线后翻车。","need":"你需要一条完整的实战流水线：每个阶段有明确目标、明确验收标准、明确翻车点与对策。学完立刻能复制到任意新项目。"},{"type":"oneline","text":"全流程实战 = 立项（一句话 + MVP）→ 骨架搭建 → 版本控制 → 前后端联调 → 数据与安全 → 测试 → 部署上线 → 上线后观察。八个阶段各含‘目标/验收/雷区’，串起来就是一套可复制的‘AI 产品生产线’。"},{"type":"visual","kind":"request-flow","title":"互动实验：走一遍上线后的一次完整请求","hint":"点‘发送请求’，用一个真实上线产品的视角，重走一次 用户→浏览器→DNS→网络→服务器→后端→数据库→回显，把 v01 到 v07 学的每一层验收一遍。这就是你上线产品每天在被执行的事。"},{"type":"intuition","blocks":[{"k":"用盖一栋楼来想","t":"立项=出图纸，骨架=打地基，Git=施工日志，联调=水电管线对接，测试=竣工验收，部署=交付入住，上线观察=回访保修。任何一步省掉，楼都住不安稳。"},{"k":"用做一顿饭来想","t":"备料（数据）、切配（分模块）、下锅（写功能）、尝味（测试）、装盘（部署）、上桌（上线）。每步都能‘尝一口’，别憋到最后才开火。"},{"k":"一句话记住","t":"小步快跑 + 每步验收 + 能回退 + 有测试防回归。把这四个关键词刻在流程里，任何项目都不会翻车。"}]},{"type":"how","intro":"从想法到上线的八阶段实战清单。每阶段都有验收标准。","steps":[{"in":"① 立项：一句话 + 最小 MVP","process":"把想法压缩成一句话：为谁解决什么。锁定最小可用范围（核心 1-2 个功能），暂不做锦上添花。","out":"一句需求 + MVP 边界清单","note":"这一阶段是产品判断，交给 AI 前先自己想清楚。"},{"in":"② 搭骨架：让 AI 生成基础工程","process":"把需求、技术选型、运行环境给 AI，让它一键生成可运行的基础工程（页面+后端+GIT 初始）。","out":"能跑的最小骨架","note":"把 v06 结构思想直接要求 AI 遵守。"},{"in":"③ 版本控制：立刻 git init + 首次提交","process":"骨架一跑通就 commit。自此每个‘能跑’版本都存档（v02），为后续折腾提供安全网。","out":"一个安全起点：首个可回退 commit","note":"‘能跑就提交’从第一步就开始做。"},{"in":"④ 前后端联调：核心功能跑通","process":"实现 MVP 的核心交互：前端调用 API（v03）、后端存取数据库（v04），把‘保存一条记录→回显’走通。","out":"核心功能端到端可用","note":"每接通一个接口就验证一次；别攒到最后一起测。"},{"in":"⑤ 数据与安全：别裸奔上线","process":"检查输入校验、密码加密、权限控制、.env 隐藏（v04）。把密钥放进环境变量并 .gitignore，绝不暴露在代码里。","out":"基础安全加固：校验+加密+权限+密钥隔离","note":"上线前必须过这一关。"},{"in":"⑥ 测试与收尾：补边界 + 回归","process":"写关键路径测试（v05）：正常/边界/异常用例；修 bug 补回归测试；整理结构让小步可维护（v06）。","out":"有自动化验证、可在后续改动中反复确认","note":"上线前至少覆盖核心链路。"},{"in":"⑦ 部署上线：搬到公网","process":"把本地跑通的版本部署到托管平台/服务器，配好环境变量、域名与 HTTPS（v07）。","out":"一个公网可访问的真实 URL","note":"本地没问题≠线上没问题，上线后立刻用真实地址自测。"},{"in":"⑧ 上线后观察：日志 + 收集反馈 + 迭代","process":"观察访问日志/报错，收集第一批真实用户反馈，按‘小步迭代’节奏继续发布新版本。","out":"持续迭代的活产品，而非一次性的 demo","note":"产品是‘上线才开始’，不是‘上线就结束’。"}]},{"type":"realworld","items":[{"name":"第一个版本只需要一个核心功能","note":"MVP 越小越容易成功上线。纪念版、仪表盘、多用户等先放 TODO，上线后再加。"},{"name":"让 AI 分模块生成","note":"不要一句‘帮我做个记账系统’；而是按 v06 结构分功能/分接口给 AI，逐个生成、逐个联调、逐个测试。"},{"name":"上线前过一遍安全清单","note":"输入校验、密钥不入库、权限默认拒绝、HTTPS——四条底线守住，避免上线即翻车。"},{"name":"把流程固化成模板","note":"把这 8 阶段存成自己的 CheckList，以后每个新项目都照跑一遍，效率和质量双保险。"}]},{"type":"compare","pairs":[{"a":"做 Demo","b":"做真产品","diff":"Demo 只要能演示关键功能；真产品要能扛真实用户、真实数据、安全与故障。流程完整、版本可控、测试兜底、安全到位。"},{"a":"一次性大开发","b":"八阶段小步","diff":"一次性憋大版本风险高、难回退；八阶段小步每步有验收与存档，翻车可回退。"},{"a":"先写代码","b":"先立项","diff":"先写代码容易做偏；先一句话立项 + MVP 边界，保证做得对再做得快。"},{"a":"上线即结束","b":"上线才开始","diff":"把上线当终点会烂尾；当做起点则持续观察、收集反馈、迭代，产品才越来越好用。"}]},{"type":"mistakes","items":["一上来就让 AI 写‘整个系统’——八成失控。按阶段、按模块小步走。","跳过大安全清单就上线——密钥泄露、可被随意改数据，上线即事故。","本地 OK 就当上线 OK——不部署真实地址自测，线上环境不同照样翻车。","不 commit / 不写测试——改坏了没法回退、回归全靠人肉，返工翻倍。","上线后不观察日志 ——用户报了 bug 你还不知道，产品口碑崩塌。"]},{"type":"ask","title":"怎么用 AI 全程辅助一个真实项目：阶段化提问","scenario":"你想做‘家庭记账本’，在不同阶段分别怎么向 AI 提问。","template":"[阶段①立项] 帮我把‘记录家庭每笔支出并生成月度统计’压缩成一个最小 MVP，给出核心功能清单和不要做的部分。\n[阶段④联调] 我的记账接口 GET /entries 报 500，报错在 db.js 第 20 行，这是日志：...，请定位根因并给修复+回归测试。\n[阶段⑦部署] 我用 Vercel 部署 Node 后端，连接本地 MongoDB，请给部署清单，指出本地与线上的环境差异点。","acceptance":["AI 是否理解你处于哪个阶段并给相应输出？","是否给出‘目标/验收/雷区’式回答，而不只是贴代码？","是否把上一阶段的产物作为下一阶段的输入？","是否提醒每步都 commit + 测试，安全清单上线前必过？"],"tip":"把项目拆成阶段，每阶段单独、具体地追问 AI：立项就问范围、联调就问具体报错、部署就问环境清单。越分阶段，越精准。"},{"type":"exercise","prompt":"你要做一个‘打卡习惯’小程序，刚从头开始。按本课流程，你第一步最该做什么？","opts":["让 AI 一次性生成完整系统","先把想法压缩成一句话 MVP 与边界，再让 AI 搭可跑骨架并立即 git commit","直接部署一个空文件夹","先写数据库表"],"a":1,"explain":"正确开局：一句话立项锁定 MVP → AI 搭可跑骨架 → 立刻 git 存档建立安全起点。之后再联调、测试、部署。","jump":"sec5-step0","jumpLabel":"立项这一步"},{"type":"check","title":"结课检测：你能独立走完一条产品生产线了吗","intro":"共 4 题。全部答对即可完成整条 Vibe Coding 工程基础路径。答错会带你回对应段落复习。","questions":[{"q":"从想法到上线，八个阶段的第一步是？","opts":["写代码","一句话立项 + 锁定最小 MVP 边界","部署服务器","写测试"],"a":1,"explain":"先想清楚‘为谁解决什么、最小做哪些’，再动手。立项是地基。","jump":"sec5-step0"},{"q":"‘本地 OK 不等于线上 OK’主要指什么风险？","opts":["线上网速更快","环境配置、依赖版本、数据库连接等与本地不一致","线上没有显示器","线上代码自动更好"],"a":1,"explain":"环境不一致是头号翻车点（密钥/数据库/版本/路径），上线后必须用真实地址自测。","jump":"sec5-step6"},{"q":"上线前必须过的基本安全底线包含？","opts":["页面好看","输入校验 + 密钥不入库(.env 隔离) + 权限控制 + HTTPS","代码注释多","视频教程"],"a":1,"explain":"输入校验防注入、密钥隔离防泄露、权限控制防越权、HTTPS 防窃听——四条底线。","jump":"sec5-step4"},{"q":"为什么每个‘能跑’的版本都要 git commit？","opts":["显得专业","形成安全存档点，后续小步迭代随时能回退，防翻车","省磁盘","为了提交给 AI 看"],"a":1,"explain":"能跑就提交，把迭代变成可回退的小步，翻车永远是‘回到上一版’而不是‘重头再来’。","jump":"sec5-step2"}],"done":"恭喜你走完 Vibe Coding 工程基础整条路径！你从‘看懂一个 Web 产品’一路走到了‘能独立用 AI 做出一个上线产品’。记住这条生产线：立项→骨架→版本→联调→安全→测试→部署→观察。现在，去做出你的第一个真产品吧。","nextLesson":""},{"type":"connection","known":["Vibe 路径前七课：Web 链路 / Git / API / 数据库 / 测试 / 结构 / 部署"],"learned":["从想法到上线的八阶段生产线与各自验收标准","每个阶段怎么把对应课程能力用上、怎么防翻车","上线只是开始，观察与迭代才是产品的常态","把流程固化成个人 CheckList 的方法"],"next":"这是 Vibe Coding 工程基础的最后一课，也是你独立做产品的起点。可以回到《从零看懂 AI》路径或继续探索更进阶的工程主题。祝你做出第一个真正上线的产品！","links":[{"href":"#/lesson/v07-deploy","text":"回看《从本地 Demo 到正式上线》"},{"href":"#/lesson/l18-vibe-coding","text":"回到核心路径《Vibe Coding 入门》"}]}]}]},"lessonConceptMap":{"agent-intro":["l-agent"],"agent-loop":["l-agent"],"tool-use":["l-agent","pl-function-calling"],"agent-planning":["l-agent"],"agent-memory":["l-agent"],"agent-reflection":["l-agent"],"attention":["l-attention","l-transformer"],"qkv":["l-attention"],"multihead":["l-attention","l-transformer"],"attention-long":["l-attention"],"embedding":["l-embedding"],"vector":["l-embedding"],"cosine-similarity":["l-embedding"],"emb-vector-store":["l-embedding","l-rag"],"rag-pain":["l-rag"],"rag-pipeline":["l-rag"],"chunking":["l-rag"],"vector-search":["l-rag"],"rerank":["l-rag"],"transformer":["l-transformer"],"position-enc":["l-transformer"],"ai-what":["l00-ai-world","l01-ai-vs-ml-dl"],"ai-ml-dl":["l00-ai-world","l01-ai-vs-ml-dl","pl-train-infer"],"ai-apps":["l00-ai-world"],"ai-limits":["l00-ai-world"],"loss":["l05-gradient-descent"],"gradient":["l05-gradient-descent","l09-backprop"],"gradient-descent":["l05-gradient-descent"],"neural-network":["l08-neural-network"],"neuron":["l08-neural-network"],"layer":["l08-neural-network"],"activation":["l08-neural-network"],"backpropagation":["l09-backprop"],"chain-rule":["l09-backprop"],"tokenization":["l11-tokenization"],"token":["l11-tokenization","l12-context-window"],"bpe":["l11-tokenization"],"context-window":["l12-context-window"],"inference":["l12-context-window","pl-train-infer"],"vibe-coding":["l18-vibe-coding","v08-workflow"],"ai-coding":["l18-vibe-coding","l22-ai-coding"],"product-building":["l18-vibe-coding"],"pair-programming":["l22-ai-coding"],"agentic-coding":["l22-ai-coding"],"codegen":["l22-ai-coding"],"data":["pl-data"],"model":["pl-data"],"parameter":["pl-data"],"function-calling":["pl-function-calling"],"structured-output":["pl-function-calling"],"prompt":["pl-prompt"],"prompt-engineering":["pl-prompt"],"context":["pl-prompt"],"training":["pl-train-infer"],"git":["v02-git"],"version-control":["v02-git"],"commit":["v02-git"],"rollback":["v02-git"],"testing":["v05-test"],"debugging":["v05-test"],"test-driven":["v05-test"],"error-handling":["v05-test"],"project-structure":["v06-arch"],"code-organization":["v06-arch"],"modularity":["v06-arch"],"refactoring":["v06-arch"],"full-workflow":["v08-workflow"],"product-launch":["v08-workflow"],"mdv":["v08-workflow"]}};
  var lessons = DATA.lessons, curriculum = DATA.curriculum;
  var lessonsByCat = DATA.lessonsByCat, lessonConceptMap = DATA.lessonConceptMap;
  var flagship = DATA.flagship || [];

  function getLesson(id) { return lessons[id] || null; }
  function getLessonsByCategory(catId) { return lessonsByCat[catId] || []; }
  function lessonForConcept(cid) { return lessonConceptMap[cid] || []; }
  function getCurriculumLessonMeta(id) {
    for (var ci = 0; ci < (curriculum.categories || []).length; ci++) {
      var cat = curriculum.categories[ci];
      for (var hi = 0; hi < (cat.chapters || []).length; hi++) {
        var ch = cat.chapters[hi];
        for (var li = 0; li < (ch.lessons || []).length; li++) {
          if (ch.lessons[li].id === id) return ch.lessons[li];
        }
      }
    }
    return null;
  }
  function readyLessons() { return Object.keys(lessons).map(function (id) { return lessons[id]; }); }
  function flagshipLessons() {
    var out = [];
    flagship.forEach(function (id) { if (lessons[id]) out.push(lessons[id]); });
    return out;
  }
  function flaggedMeta(id) { return getCurriculumLessonMeta(id); }

  var L = {
    version: DATA.version,
    builtAt: DATA.builtAt,
    curriculum: curriculum,
    lessonCount: DATA.lessonCount,
    flagship: flagship,
    lessons: lessons,
    byId: lessons,
    lessonsByCat: lessonsByCat,
    lessonConceptMap: lessonConceptMap,
    getLesson: getLesson,
    getLessonsByCategory: getLessonsByCategory,
    lessonForConcept: lessonForConcept,
    getCurriculumLessonMeta: getCurriculumLessonMeta,
    readyLessons: readyLessons,
    flagshipLessons: flagshipLessons,
    flaggedMeta: flaggedMeta
  };

  if (typeof window !== "undefined") window.LEARN = L;
  if (typeof module !== "undefined" && module.exports) module.exports = L;
})();